import { useQuery } from "@tanstack/react-query";
import { Search, User } from "lucide-react";
import { useCallback, useEffect, useMemo,useRef, useState } from "react";

import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/Dialog";
import { Input } from "@/components/ui/Input";
import { matchesShortcut, SHORTCUT_GLOBAL_SEARCH } from "@/constants/shortcuts";
import { cn } from "@/lib/utils";

interface SearchDialogProps<T> {
    value: string;
    onSelect: (name: string) => void;
    queryKey: string[];
    fetchFn: (searchTerm: string) => Promise<{ items: T[] }>;
    getName: (item: T) => string;
    getSubtitle?: (item: T) => string;
    title?: string;
    placeholder?: string;
    minLength?: number;
    maxResults?: number;
    hideTrigger?: boolean;
}

export function SearchDialog<T>({
    value: _value,
    onSelect,
    queryKey,
    fetchFn,
    getName,
    getSubtitle,
    title = "بحث بالاسم",
    placeholder = "بحث بالاسم أو الرقم...",
    minLength = 2,
    maxResults = 20,
    hideTrigger = false,
}: SearchDialogProps<T>) {
    const [open, setOpen] = useState(false);
    const [searchText, setSearchText] = useState("");
    const [debouncedSearch, setDebouncedSearch] = useState("");
    const [activeIndex, setActiveIndex] = useState(-1);
    const listRef = useRef<HTMLDivElement>(null);
    const inputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        if (open && inputRef.current) {
            const timer = setTimeout(() => inputRef.current?.focus(), 60);
            return () => clearTimeout(timer);
        }
    }, [open]);

    useEffect(() => {
        const handleShortcut = (e: KeyboardEvent) => {
            if (matchesShortcut(e, SHORTCUT_GLOBAL_SEARCH)) {
                e.preventDefault();
                setOpen((prev) => !prev);
            }
        };
        window.addEventListener("keydown", handleShortcut);
        return () => window.removeEventListener("keydown", handleShortcut);
    }, []);

    useEffect(() => {
        const timer = setTimeout(() => setDebouncedSearch(searchText), 300);
        return () => clearTimeout(timer);
    }, [searchText]);

    const { data: results, isLoading } = useQuery({
        queryKey: [...queryKey, debouncedSearch],
        queryFn: () => fetchFn(debouncedSearch),
        enabled: open && debouncedSearch.length >= minLength,
    });

    const items = results?.items ?? [];

    const uniqueNames = useMemo(() => {
        const seen = new Map<string, { name: string; subtitle: string }>();
        for (const item of items) {
            const name = getName(item);
            if (!name) continue;
            if (!seen.has(name)) {
                seen.set(name, { name, subtitle: getSubtitle?.(item) ?? "" });
            }
        }
        return Array.from(seen.values()).slice(0, maxResults);
    }, [items, getName, getSubtitle, maxResults]);

    const selectName = useCallback((name: string) => {
        onSelect(name);
        setOpen(false);
        setSearchText("");
        setActiveIndex(-1);
    }, [onSelect]);

    const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
        if (!uniqueNames.length) return;
        if (e.key === "ArrowDown") {
            e.preventDefault();
            setActiveIndex((prev) => (prev < uniqueNames.length - 1 ? prev + 1 : 0));
        } else if (e.key === "ArrowUp") {
            e.preventDefault();
            setActiveIndex((prev) => (prev > 0 ? prev - 1 : uniqueNames.length - 1));
        } else if (e.key === "Enter" && activeIndex >= 0) {
            e.preventDefault();
            selectName(uniqueNames[activeIndex].name);
        } else if (e.key === "Escape") {
            setOpen(false);
        }
    }, [uniqueNames, activeIndex, selectName]);

    useEffect(() => {
        if (activeIndex < 0 || !listRef.current) return;
        const el = listRef.current.children[activeIndex] as HTMLElement;
        el?.scrollIntoView({ block: "nearest" });
    }, [activeIndex]);

    return (
        <Dialog open={open} onOpenChange={setOpen}>
            {!hideTrigger && (
                <DialogTrigger className="inline-flex items-center justify-center w-10 h-10 rounded-md border border-input bg-background transition-colors hover:bg-muted shrink-0" title={title}>
                    <Search className="w-4 h-4" />
                </DialogTrigger>
            )}
            <DialogContent className="sm:max-w-2xl p-0 gap-0 overflow-hidden border-border">
                <DialogHeader className="px-5 pt-5 pb-0 border-b-0">
                    <DialogTitle className="text-lg font-bold">{title}</DialogTitle>
                </DialogHeader>
                <div className="px-5 pt-3 pb-5">
                    <div className="relative">
                        <Search className="absolute right-3 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" />
                        <Input
                            ref={inputRef}
                            placeholder={placeholder}
                            value={searchText}
                            onChange={(e) => { setSearchText(e.target.value); setActiveIndex(-1); }}
                            onKeyDown={handleKeyDown}
                            className="pr-10 h-12 text-base border-2 border-primary focus-visible:border-primary focus-visible:ring-1 focus-visible:ring-primary/20 bg-muted/30"
                            autoFocus
                        />
                    </div>

                    {debouncedSearch.length >= minLength && (
                        <div ref={listRef} className="mt-3 max-h-[28rem] overflow-y-auto space-y-1 divide-y divide-border" role="listbox">
                            {isLoading ? (
                                <p className="text-sm text-muted-foreground text-center py-8">جاري البحث...</p>
                            ) : uniqueNames.length > 0 ? (
                                uniqueNames.map((item, index) => (
                                    <button
                                        key={item.name}
                                        role="option"
                                        aria-selected={index === activeIndex}
                                        className={cn(
                                            "w-full text-right p-3.5 transition-colors flex items-center justify-between",
                                            index === activeIndex
                                                ? "bg-primary/5"
                                                : "hover:bg-muted/50"
                                        )}
                                        onClick={() => selectName(item.name)}
                                        onMouseEnter={() => setActiveIndex(index)}
                                    >
                                        <div className="flex items-center gap-3 min-w-0">
                                            <div className="flex items-center justify-center w-9 h-9 rounded-full bg-primary/10 shrink-0">
                                                <User className="w-4 h-4 text-primary" />
                                            </div>
                                            <span className="text-sm font-medium truncate">{item.name}</span>
                                        </div>
                                        {item.subtitle && (
                                            <span className="text-xs text-muted-foreground truncate mr-3 bg-muted/50 px-2 py-1 rounded">{item.subtitle}</span>
                                        )}
                                    </button>
                                ))
                            ) : (
                                <p className="text-sm text-muted-foreground text-center py-8">لا توجد نتائج</p>
                            )}
                        </div>
                    )}
                </div>
            </DialogContent>
        </Dialog>
    );
}

import React, { useMemo } from 'react';
import { 
  Area, 
  AreaChart,
  CartesianGrid, 
  Line, 
  LineChart, 
  ResponsiveContainer, // تمت الإضافة لدعم التجاوب
  XAxis, 
  YAxis} from 'recharts';

import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card';
import type { ChartConfig } from '@/components/ui/chart';
import { ChartContainer, ChartLegend, ChartLegendContent,ChartTooltip, ChartTooltipContent } from '@/components/ui/chart';
import { chartColors } from '@/lib/chartColors';
import { cn, formatNumber } from '@/lib/utils';

interface ReportLineChartProps {
  data: Record<string, any>[];
  xKey: string;
  lines: { key: string; color?: string; label: string }[];
  title?: string;
  height?: number;
  showGrid?: boolean;
  showLegend?: boolean;
  area?: boolean;
  formatValue?: (value: number) => string;
  className?: string;
}

const DEFAULT_COLORS = [
  chartColors.primary,
  chartColors.success,
  chartColors.danger,
  chartColors.warning,
  chartColors.purple,
  chartColors.teal,
];

export const ReportLineChart: React.FC<ReportLineChartProps> = ({
  data,
  xKey,
  lines,
  title,
  height = 350,
  showGrid = true,
  showLegend = true,
  area = false,
  formatValue,
  className,
}) => {
  if (!data || data.length === 0) return null;

  const ChartComponent = area ? AreaChart : LineChart;

  // إعداد إعدادات المخطط باستخدام useMemo لتحسين الأداء
  const chartConfig = useMemo(() => {
    const config: ChartConfig = {};
    lines.forEach((line, index) => {
      config[line.key] = {
        label: line.label,
        color: line.color || DEFAULT_COLORS[index % DEFAULT_COLORS.length],
      };
    });
    return config;
  }, [lines]);

  return (
    <Card className={cn("h-full border border-border shadow-sm transition-shadow hover:shadow-md", className)}>
      {title && (
        <CardHeader className="pb-0 pt-1 px-3 space-y-0">
          <CardTitle className="text-sm font-bold text-foreground">{title}</CardTitle>
        </CardHeader>
      )}
      <CardContent className="p-0">
        <div role="img" aria-label={title || 'Chart'} className="w-full">
          <ChartContainer config={chartConfig} className="w-full !aspect-auto justify-start" style={{ height }}>
            {/* استخدام ResponsiveContainer لضمان تجاوب المخطط مع الشاشات المختلفة */}
            <ResponsiveContainer width="100%" height="100%">
              <ChartComponent data={data} margin={{ top: 5, right: 10, left: 0, bottom: 0 }}>
                {/* إضافة التدرج اللوني (Gradient) لـ Area Chart */}
                {area && (
                  <defs>
                    {lines.map((line, index) => {
                      const color = line.color || DEFAULT_COLORS[index % DEFAULT_COLORS.length];
                      return (
                        <linearGradient key={`fill-${line.key}`} id={`color-${line.key}`} x1="0" y1="0" x2="0" y2="1">
                          <stop offset="5%" stopColor={color} stopOpacity={0.3} />
                          <stop offset="95%" stopColor={color} stopOpacity={0} />
                        </linearGradient>
                      );
                    })}
                  </defs>
                )}

                {showGrid && (
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="hsl(var(--border))" />
                )}
                
                <XAxis
                  dataKey={xKey}
                  tickLine={false}
                  axisLine={false}
                  tick={{ fontSize: 12, fill: 'hsl(var(--muted-foreground))' }}
                  tickMargin={10}
                />
                
                <YAxis
                  tickLine={false}
                  axisLine={false}
                  tick={{ fontSize: 12, fill: 'hsl(var(--muted-foreground))' }}
                  tickMargin={10}
                  tickFormatter={(val) => {
                    if (val >= 1000000) return `${(val / 1000000).toFixed(1)}M`;
                    if (val >= 1000) return `${(val / 1000).toFixed(0)}K`;
                    return val;
                  }}
                />
                
                <ChartTooltip
                  cursor={{ stroke: 'hsl(var(--muted))', strokeWidth: 2, strokeDasharray: '4 4' }}
                  content={
                    <ChartTooltipContent
                      formatter={(value) => (
                        <span className="font-mono font-medium text-foreground tabular-nums">
                          {formatValue ? formatValue(Number(value)) : formatNumber(Number(value))}
                        </span>
                      )}
                    />
                  }
                />
                
                {showLegend && <ChartLegend content={<ChartLegendContent />} className="mt-0 pt-0" />}
                
                {lines.map((line, index) => {
                  const color = line.color || DEFAULT_COLORS[index % DEFAULT_COLORS.length];
                  
                  if (area) {
                    return (
                      <Area
                        key={line.key}
                        type="monotone"
                        dataKey={line.key}
                        name={line.label}
                        stroke={color}
                        fill={`url(#color-${line.key})`}
                        strokeWidth={2}
                        activeDot={{ r: 6, stroke: 'hsl(var(--background))', strokeWidth: 2 }}
                      />
                    );
                  }
                  
                  return (
                    <Line
                      key={line.key}
                      type="monotone"
                      dataKey={line.key}
                      name={line.label}
                      stroke={color}
                      strokeWidth={2}
                      dot={false} // إخفاء النقاط العادية ليكون الخط أنظف
                      activeDot={{ r: 6, fill: color, stroke: 'hsl(var(--background))', strokeWidth: 2 }}
                    />
                  );
                })}
              </ChartComponent>
            </ResponsiveContainer>
          </ChartContainer>
        </div>
      </CardContent>
    </Card>
  );
};

import React, { useMemo } from 'react';
import { Cell, Pie, PieChart, ResponsiveContainer } from 'recharts';

import { Card, CardContent } from '@/components/ui/Card';
import type { ChartConfig } from '@/components/ui/chart';
import { ChartContainer, ChartTooltip, ChartTooltipContent } from '@/components/ui/chart';
import { chartColors } from '@/lib/chartColors';
import { cn, formatNumber } from '@/lib/utils';

interface ReportPieChartProps {
  data: Record<string, unknown>[];
  nameKey: string;
  valueKey: string;
  title?: string;
  subtitle?: string;
  height?: number;
  colors?: string[];
  showLegend?: boolean;
  innerRadius?: number | string;
  formatValue?: (value: number) => string;
  className?: string;
  /** عتبة النسبة المئوية للقطع الصغيرة التي تُجمع في "أخرى" */
  minPercent?: number;
  /** تسمية القسم المجمّع */
  otherLabel?: string;
  /** لون قسم "أخرى" */
  otherColor?: string;
}

interface CustomLabelProps {
  cx: number;
  cy: number;
  midAngle: number;
  innerRadius: number;
  outerRadius: number;
  percent: number;
}

const DEFAULT_COLORS = [
  chartColors.primary,
  chartColors.success,
  chartColors.danger,
  chartColors.warning,
  chartColors.purple,
  chartColors.teal,
  chartColors.pink,
];

const RADIAN = Math.PI / 180;

const renderCustomLabel = ({
  cx,
  cy,
  midAngle,
  innerRadius,
  outerRadius,
  percent,
}: CustomLabelProps) => {
  // إخفاء النصوص للقطع الصغيرة جداً أو الكبيرة جداً لتجنب التداخل
  if (percent < 0.08 || percent > 0.85) return null;

  const radius = innerRadius + (outerRadius - innerRadius) * 0.5;
  const x = cx + radius * Math.cos(-midAngle * RADIAN);
  const y = cy + radius * Math.sin(-midAngle * RADIAN);

  return (
    <text
      x={x}
      y={y}
      fill="white"
      textAnchor="middle"
      dominantBaseline="central"
      fontSize={12}
      fontWeight="bold"
      className="drop-shadow-sm pointer-events-none"
    >
      {`${(percent * 100).toFixed(0)}%`}
    </text>
  );
};

export const ReportPieChart: React.FC<ReportPieChartProps> = ({
  data,
  nameKey,
  valueKey,
  title,
  subtitle,
  height = 280,
  colors,
  showLegend = true,
  innerRadius = "62%",
  formatValue,
  className,
  minPercent = 3,
  otherLabel = "أخرى",
  otherColor = "hsl(220, 9%, 60%)",
}) => {
  if (!data || data.length === 0) return null;

  const palette = colors || DEFAULT_COLORS;

  // ─── ترتيب البيانات تنازلياً حسب القيمة ───
  const sortedData = useMemo(() => {
    return [...data].sort((a, b) => Number(b[valueKey] ?? 0) - Number(a[valueKey] ?? 0));
  }, [data, valueKey]);

  // ─── حساب الإجمالي ───
  const totalVal = useMemo(() => {
    return sortedData.reduce((sum, item) => sum + Number(item[valueKey] ?? 0), 0);
  }, [sortedData, valueKey]);

  // ─── تجميع القطع الصغيرة في "أخرى" ───
  const processedData = useMemo(() => {
    if (totalVal === 0) return sortedData;

    const major: Record<string, unknown>[] = [];
    let otherSum = 0;
    let otherCount = 0;
    const otherNames: string[] = [];

    sortedData.forEach((item) => {
      const value = Number(item[valueKey] ?? 0);
      const percent = (value / totalVal) * 100;
      if (percent < minPercent) {
        otherSum += value;
        otherCount += 1;
        const n = String(item[nameKey] ?? "");
        if (n) otherNames.push(n);
      } else {
        major.push(item);
      }
    });

    if (otherSum > 0) {
      major.push({
        [nameKey]: otherCount > 1 ? `${otherLabel} (${otherCount})` : otherLabel,
        [valueKey]: otherSum,
        _isOther: true,
        _originalNames: otherNames,
      });
    }

    return major;
  }, [sortedData, totalVal, valueKey, nameKey, minPercent, otherLabel]);

  // ─── إعداد إعدادات المخطط بألوان ثابتة حسب الترتيب ───
  const chartConfig = useMemo(() => {
    const config: ChartConfig = {};
    processedData.forEach((entry, i) => {
      const key = String(entry[nameKey]);
      const isOther = (entry as Record<string, unknown>)._isOther === true;
      config[key] = {
        label: key,
        color: isOther ? otherColor : (palette[i % palette.length] ?? otherColor),
      };
    });
    return config;
  }, [processedData, nameKey, palette, otherColor]);

  // ─── تنسيق القيمة للعرض في Legend ───
  const fmt = (v: number) => (formatValue ? formatValue(v) : formatNumber(v));

  // عدد الأعمدة للـ Legend — بحسب عدد العناصر
  void (processedData.length <= 4 ? 2 : processedData.length <= 8 ? 3 : 4);

  return (
    <Card className={cn(
      "border border-border bg-card shadow-sm transition-shadow duration-200 hover:shadow-md flex flex-col overflow-hidden",
      className
    )}>

      {/* Header Section */}
      {(title || subtitle) && (
        <div className="pt-3 pb-1 px-3 shrink-0 text-center">
          {title && <h3 className="text-sm font-bold text-foreground leading-tight">{title}</h3>}
          {subtitle && <p className="text-xs text-muted-foreground leading-tight mt-0.5">{subtitle}</p>}
        </div>
      )}

      <CardContent className="p-2 pt-2 flex-1 flex flex-col md:flex-row items-center justify-start gap-2">

        {/* Donut Chart Canvas */}
        <div
          className="relative w-full md:w-2/3 flex items-center justify-center max-h-[280px] md:max-h-none"
          style={{ minHeight: height }}
        >
          <ChartContainer config={chartConfig} className="w-full h-full absolute inset-0">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={processedData}
                  cx="50%"
                  cy="50%"
                  labelLine={false}
                  label={renderCustomLabel}
                  outerRadius="92%"
                  innerRadius={innerRadius}
                  dataKey={valueKey}
                  nameKey={nameKey}
                  paddingAngle={processedData.length > 1 ? 2 : 0}
                  stroke="none"
                  isAnimationActive
                >
                  {processedData.map((entry, index) => {
                    const key = String(entry[nameKey]);
                    return (
                      <Cell
                        key={`cell-${index}`}
                        fill={chartConfig[key]?.color}
                        className="stroke-background hover:opacity-100 transition-opacity duration-200 outline-none"
                        strokeWidth={2}
                      />
                    );
                  })}
                </Pie>
                <ChartTooltip
                  cursor={false}
                  content={
                    <ChartTooltipContent
                      formatter={(value, name) => (
                        <span className="font-mono font-bold text-foreground tabular-nums">
                          {fmt(Number(value))}
                          <span className="text-muted-foreground font-normal ms-2">({name})</span>
                        </span>
                      )}
                    />
                  }
                />
              </PieChart>
            </ResponsiveContainer>
          </ChartContainer>

          {/* Donut Hole Total Indicator */}
          {totalVal > 0 && (
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none z-10">
              <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest">المجموع</span>
              <span className="text-2xl font-black text-foreground tabular-nums tracking-tight mt-0.5">
                {fmt(totalVal)}
              </span>
            </div>
          )}
        </div>

        {/* Legend Section — أفقي على الهاتف، جانبي على سطح المكتب */}
        {showLegend && processedData.length > 0 && (
          <div className="w-full md:w-1/3 pt-2 md:pt-0 md:pe-2 flex flex-wrap items-center justify-center md:flex-col md:items-start md:justify-center gap-x-3 gap-y-1">
            {processedData.map((entry, i) => {
              const name = String(entry[nameKey]);
              const color = chartConfig[name]?.color;
              const value = Number(entry[valueKey] ?? 0);
              const percent = totalVal > 0 ? ((value / totalVal) * 100).toFixed(1) : "0";

              return (
                <div
                  key={`legend-${name}-${i}`}
                  className="flex items-center gap-1.5 py-0.5 px-1.5 rounded-md hover:bg-muted/40 transition-colors cursor-default min-w-0"
                  title={`${name} — ${fmt(value)} (${percent}%)`}
                >
                  <span
                    className="w-3 h-3 rounded-full shrink-0 shadow-sm ring-1 ring-background"
                    style={{ backgroundColor: color }}
                  />
                  <span className="text-foreground font-medium text-sm truncate">
                    {name}
                  </span>
                </div>
              );
            })}
          </div>
        )}
      </CardContent>
    </Card>
  );
};

import {
AlertOctagon,
AlertTriangle,     BarChart3, Building2,     Calculator, Calendar, CheckCircle, Clock, DollarSign,     FileText,     Folder, Link,
MapPin,
Minus,
Percent, Shield, TrendingDown, TrendingUp,     User, Users, Wrench, XCircle} from 'lucide-react';
import { useMemo } from 'react';

import type { SummaryCardConfig } from '@/api/reports';
import { StatCard } from '@/components/ui/StatCard';

interface ReportSummaryCardsProps {
    cards: SummaryCardConfig[];
    data: Record<string, any>[];
    summaryData?: Record<string, any>;
    loading?: boolean;
    error?: boolean;
}

const ICON_MAP: Record<string, React.ComponentType<{ className?: string }>> = {
    BarChart3, TrendingUp, TrendingDown, Minus,
    FileText, Users, Clock, AlertTriangle, CheckCircle, XCircle,
    Calculator, DollarSign, Percent, Calendar, MapPin,
    Folder, Building2, Shield, Wrench, Link, User, AlertOctagon,
};

const COLOR_TO_VARIANT: Record<string, string> = {
    blue: 'blue', green: 'emerald', red: 'rose', yellow: 'amber',
    purple: 'purple', orange: 'orange', cyan: 'cyan', emerald: 'emerald',
    rose: 'rose', amber: 'amber',
};

function getNestedValue(obj: Record<string, any>, key: string): any {
    return key.split('.').reduce((acc, k) => acc?.[k], obj);
}

export function ReportSummaryCards({ cards, data, summaryData, loading, error }: ReportSummaryCardsProps) {
    const values = useMemo(() => {
        const result: Record<string, number> = {};
        const source = summaryData || {};

        cards.forEach(card => {
            const raw = getNestedValue(source, card.valueKey);
            if (raw !== undefined && raw !== null) {
                result[card.valueKey] = Number(raw) || 0;
                return;
            }
            if (data && data.length > 0) {
                const vals = data.map(d => Number(d[card.valueKey]) || 0);
                const sum = vals.reduce((a, b) => a + b, 0);
                result[card.valueKey] = sum;
            } else {
                result[card.valueKey] = 0;
            }
        });
        return result;
    }, [cards, data, summaryData]);

    if (!cards || cards.length === 0) return null;

    return (
        <div className="grid grid-cols-2 sm:grid-cols-2 lg:grid-cols-4 gap-2 sm:gap-4 mb-6">
            {cards.map((card, index) => {
                const value = values[card.valueKey] ?? 0;
                const formatted = card.format === 'currency'
                    ? `${value.toLocaleString('ar-YE')} ر.ي`
                    : card.format === 'percent'
                        ? `${value.toFixed(1)}%`
                        : card.format === 'date'
                            ? new Date(value).toLocaleDateString('ar-YE')
                            : value.toLocaleString('ar-YE');

                const Icon = card.icon ? (ICON_MAP[card.icon] || BarChart3) : BarChart3;
                const variant = (card.variant || COLOR_TO_VARIANT[card.color || 'blue'] || 'blue') as any;

                return (
                    <StatCard
                        key={index}
                        title={card.title}
                        value={error ? '—' : formatted}
                        loading={loading}
                        icon={<Icon className="h-4 w-4" />}
                        description={card.description}
                        variant={variant}
                    />
                );
            })}
        </div>
    );
}

import { zodResolver } from "@hookform/resolvers/zod";
import { BookOpen } from "lucide-react";
import { useEffect } from "react";
import { type Resolver, useForm } from "react-hook-form";
import { z } from "zod";

import { accountsApi } from "@/api/accounting";
import { BaseFormDialog, FormField, FormSection, Input, NativeSelect } from "@/components/ui";
import { useApiMutation } from "@/hooks";
import type { AccountCategory,ChartOfAccountDto, UpdateChartOfAccountDto } from "@/types/accounting";
import { ACCOUNT_CATEGORY, ACCOUNT_CATEGORY_AR } from "@/types/accounting";

// ─── Schema ───────────────────────────────────────
const schema = z.object({
  accountCode: z.string().min(1, "كود الحساب مطلوب"),
  accountName: z.string().min(1, "اسم الحساب مطلوب"),
  accountNature: z.enum(["Debit", "Credit"]),
  isPostable: z.boolean().default(false),
  accountCategory: z.string().default("Asset"),
  description: z.string().max(500).nullable().optional(),
});

type FormValues = z.infer<typeof schema>;

// ─── Props ────────────────────────────────────────
interface AccountFormDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  account?: ChartOfAccountDto | null;
  parentAccount?: ChartOfAccountDto | null;
}

// ─── Component ────────────────────────────────────
export function AccountFormDialog({ open, onOpenChange, account, parentAccount }: AccountFormDialogProps) {
  const isEditing = !!account;

  const form = useForm<FormValues>({
    resolver: zodResolver(schema) as Resolver<FormValues>,
    defaultValues: {
      accountCode: "",
      accountName: "",
      accountNature: parentAccount?.accountNature === "Credit" ? "Credit" : "Debit",
      isPostable: !!parentAccount,
      accountCategory: "Asset",
      description: "",
    },
  });

  const { register, handleSubmit, formState: { errors, isDirty }, setValue, reset } = form;

  // ─── Reset on open ───────────────────────────────
  useEffect(() => {
    if (open) {
      if (account) {
        reset({
          accountCode: account.accountCode,
          accountName: account.accountName,
          accountNature: account.accountNature as "Debit" | "Credit",
          isPostable: account.isPostable,
          accountCategory: account.accountCategory,
          description: account.description || "",
        });
      } else {
        reset({
          accountCode: "",
          accountName: "",
          accountNature: parentAccount?.accountNature === "Credit" ? "Credit" : "Debit",
          isPostable: !!parentAccount,
          accountCategory: "Asset",
          description: "",
        });
      }
    }
  }, [open, account, parentAccount, reset]);

  // ─── Mutation ────────────────────────────────────
  const mutation = useApiMutation(
    async (data: FormValues) => {
      if (isEditing) {
        const updateData: UpdateChartOfAccountDto = {
          accountCode: data.accountCode,
          accountName: data.accountName,
          accountNature: data.accountNature,
          parentAccountID: parentAccount?.accountID ?? null,
          isPostable: data.isPostable,
          accountCategory: data.accountCategory as AccountCategory,
          description: data.description || null,
          isActive: account?.isActive ?? true,
        };
        return accountsApi.update(account!.accountID, updateData);
      }
      return accountsApi.create({
        ...data,
        parentAccountID: parentAccount?.accountID ?? null,
        accountCategory: data.accountCategory as AccountCategory,
        description: data.description || null,
      });
    },
    {
      successMessage: isEditing ? "تم تحديث الحساب بنجاح" : "تم إنشاء الحساب بنجاح",
      errorTitle: "خطأ في الحفظ",
      invalidateKeys: [["accounts"]],
      onSuccess: () => {
        onOpenChange(false);
        reset();
      },
    }
  );

  return (
    <BaseFormDialog
      open={open}
      onOpenChange={onOpenChange}
      title={isEditing ? "تعديل حساب" : "إضافة حساب جديد"}
      description={parentAccount ? `تحت: ${parentAccount.accountCode} - ${parentAccount.accountName}` : undefined}
      size="md"
      isLoading={mutation.isPending}
      isDirty={isDirty}
      formErrors={errors}
      onSubmit={handleSubmit((v) => mutation.mutate(v))}
      resetOnOpen
      reset={reset}
      submitLabel={isEditing ? "حفظ التعديلات" : "إنشاء الحساب"}
    >
      <FormSection title="بيانات الحساب" icon={BookOpen}>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <FormField label="كود الحساب" required error={errors.accountCode?.message}>
            <Input {...register("accountCode")} placeholder="مثال: 1110" />
          </FormField>

          <FormField label="طبيعة الحساب" required error={errors.accountNature?.message}>
            <NativeSelect
              value={form.watch("accountNature")}
              options={[
                { label: "مدين", value: "Debit" },
                { label: "دائن", value: "Credit" },
              ]}
              onChange={(v) => setValue("accountNature", v as "Debit" | "Credit")}
            />
          </FormField>
        </div>

        <FormField label="اسم الحساب" required error={errors.accountName?.message}>
          <Input {...register("accountName")} placeholder="اسم الحساب بالعربية" />
        </FormField>

        <FormField label="تصنيف الحساب" required error={errors.accountCategory?.message}>
          <NativeSelect
            value={form.watch("accountCategory")}
            options={Object.entries(ACCOUNT_CATEGORY).map(([, value]) => ({
              label: ACCOUNT_CATEGORY_AR[value as keyof typeof ACCOUNT_CATEGORY_AR],
              value: value,
            }))}
            onChange={(v) => setValue("accountCategory", v)}
          />
        </FormField>

        <FormField label="الوصف" error={errors.description?.message}>
          <Input {...register("description")} placeholder="وصف مختصر للحساب (اختياري)" />
        </FormField>

        <label className="flex items-center gap-2 cursor-pointer">
          <input
            type="checkbox"
            checked={form.watch("isPostable")}
            onChange={(e) => setValue("isPostable", e.target.checked)}
            className="rounded border-border"
          />
          <span className="text-sm">حساب قابل للترحيل (مستوى تفصيلي)</span>
        </label>
      </FormSection>
    </BaseFormDialog>
  );
}

﻿import { useQuery } from "@tanstack/react-query";
import { useCallback,useEffect, useState } from "react";

import { accountsApi, reportsApi } from "@/api/accounting";
import { AccountingReportLayout } from "@/components/common/AccountingReportLayout";
import { ReportLineChart } from "@/components/common/charts";
import { ReportFilters } from "@/components/common/ReportFilters";
import { Button } from "@/components/ui";
import { Card } from "@/components/ui/Card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/Select";
import { chartColors } from "@/lib/chartColors";
import { formatCurrency } from "@/lib/utils";
import type { AccountStatementResultDto, ChartOfAccountDto } from "@/types/accounting";

interface AccountStatementReportProps {
  fiscalYearId?: number;
  fromDate?: string;
  toDate?: string;
  externalFilters?: { accountId?: number };
  hideInternalControls?: boolean;
}

export function AccountStatementReport({ fiscalYearId, fromDate: propFromDate, toDate: propToDate, externalFilters, hideInternalControls }: AccountStatementReportProps) {
  const [internalAccountId, setInternalAccountId] = useState<number | null>(null);
  const accountId = externalFilters?.accountId !== undefined ? externalFilters.accountId : internalAccountId;
  const [filters, setFilters] = useState<Record<string, any>>({
    fromDate: propFromDate || new Date(new Date().getFullYear(), 0, 1).toISOString().split("T")[0],
    toDate: propToDate || new Date().toISOString().split("T")[0],
  });

  useEffect(() => {
    if (propFromDate) setFilters(prev => ({ ...prev, fromDate: propFromDate }));
    if (propToDate) setFilters(prev => ({ ...prev, toDate: propToDate }));
  }, [propFromDate, propToDate]);

  const { data: accounts } = useQuery({
    queryKey: ["accounts", "postable"],
    queryFn: () => accountsApi.getPostable(),
  });

  const { data, isLoading, error, refetch } = useQuery({
    queryKey: ["reports", "account-statement", accountId, fiscalYearId, filters.fromDate, filters.toDate],
    queryFn: () => reportsApi.accountStatement({ accountId: accountId!, fiscalYearId, fromDate: filters.fromDate, toDate: filters.toDate }),
    enabled: !!accountId && !!filters.fromDate && !!filters.toDate,
  });

  const handleFilterChange = useCallback((key: string, value: any) => {
    setFilters(prev => ({ ...prev, [key]: value }));
  }, []);

  const handleSearch = () => {
    if (!accountId || !filters.fromDate || !filters.toDate) return;
    refetch();
  };

  const handlePrint = useCallback(() => {
    const params = new URLSearchParams();
    if (accountId) params.set("accountId", String(accountId));
    if (fiscalYearId) params.set("fiscalYearId", String(fiscalYearId));
    if (filters.fromDate) params.set("fromDate", filters.fromDate);
    if (filters.toDate) params.set("toDate", filters.toDate);
    window.open(`/reports/account-statement/print?${params.toString()}`, "_blank");
  }, [accountId, fiscalYearId, filters]);

  const result = data as AccountStatementResultDto | undefined;
  const items = result?.items ?? [];

  const chartContent = items.length > 0 ? (
    <ReportLineChart
      data={items.map(item => ({
        name: new Date(item.entryDate).toLocaleDateString('ar-SA', { month: 'short', day: 'numeric' }),
        balance: item.runningBalance,
      }))}
      xKey="name"
      lines={[{ key: 'balance', color: chartColors.primary, label: 'الرصيد' }]}
      title="تطور الرصيد"
      area
      height={250}
    />
  ) : undefined;

  const customKPIs = items.length > 0 ? [
    { label: 'عدد الحركات', value: items.length, color: 'default' },
    { label: 'إجمالي المدين', value: formatCurrency(items.reduce((s, i) => s + i.debit, 0)), color: 'info' },
    { label: 'إجمالي الدائن', value: formatCurrency(items.reduce((s, i) => s + i.credit, 0)), color: 'success' },
    { label: 'الرصيد النهائي', value: formatCurrency(items[items.length - 1]?.runningBalance ?? 0), color: 'primary' },
  ] : [];

  const filterBar = hideInternalControls ? undefined : (
    <Card className="p-4 flex flex-wrap gap-4 items-end mb-6">
      <div className="w-full sm:w-64">
        <label className="label-filter">الحساب</label>
        <Select value={String(accountId ?? "")} onValueChange={(v) => setInternalAccountId(Number(v))}>
          <SelectTrigger className="h-10">
            <SelectValue placeholder="اختر الحساب" />
          </SelectTrigger>
          <SelectContent className="max-h-[250px]">
            {accounts?.map((a: ChartOfAccountDto) => (
              <SelectItem key={a.accountID} value={String(a.accountID)}>
                {a.accountCode} - {a.accountName}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
      <ReportFilters
        filters={['fromDate', 'toDate']}
        values={filters}
        onChange={handleFilterChange}
        showApplyButton={false}
        compact
      />
      <Button
        onClick={handleSearch}
        disabled={!accountId || !filters.fromDate || !filters.toDate}
      >
        عرض
      </Button>
    </Card>
  );

  return (
    <AccountingReportLayout
      title="كشف حساب"
      description="عرض حركات حساب معين في فترة محددة"
      isLoading={isLoading}
      customKPIs={customKPIs}
      filterBar={filterBar}
      chartContent={chartContent}
      onPrint={hideInternalControls ? undefined : (items.length > 0 ? handlePrint : undefined)}
    >
      {error ? (
        <div className="text-destructive text-sm">فشل في تحميل كشف الحساب</div>
      ) : items.length === 0 ? (
        <div className="text-muted-foreground text-sm p-8 text-center">اختر الحساب والتاريخ لعرض كشف الحساب</div>
      ) : (
        <div className="border rounded-xl overflow-hidden">
          <table className="w-full text-sm" role="table" aria-label="كشف حساب">
            <thead className="bg-muted/50 sticky top-0 z-10">
              <tr>
                <th className="text-end p-2">التاريخ</th>
                <th className="text-end p-2">رقم القيد</th>
                <th className="text-end p-2">البيان</th>
                <th className="text-start p-2 w-28">مدين</th>
                <th className="text-start p-2 w-28">دائن</th>
                <th className="text-start p-2 w-28">الرصيد</th>
              </tr>
            </thead>
            <tbody>
              {items.map((item, i) => (
                <tr key={i} className="border-t border-border hover:bg-muted/20">
                  <td className="p-2 text-xs">{new Date(item.entryDate).toLocaleDateString("ar-SA")}</td>
                  <td className="p-2 font-mono text-xs ltr" dir="ltr">{item.entryNumber}</td>
                  <td className="p-2 text-xs">{item.description}</td>
                  <td className="p-2 text-start font-mono text-xs">{item.debit > 0 ? formatCurrency(item.debit) : "—"}</td>
                  <td className="p-2 text-start font-mono text-xs">{item.credit > 0 ? formatCurrency(item.credit) : "—"}</td>
                  <td className="p-2 text-start font-mono text-xs">{formatCurrency(item.runningBalance)}</td>
                </tr>
              ))}
            </tbody>
            <tfoot className="bg-muted/30 font-medium">
              <tr>
                <td colSpan={5} className="p-2 text-start">الرصيد النهائي</td>
                <td className="p-2 text-start font-mono">{formatCurrency(items[items.length - 1]?.runningBalance ?? 0)}</td>
              </tr>
            </tfoot>
          </table>
        </div>
      )}
    </AccountingReportLayout>
  );
}

import { useQuery } from "@tanstack/react-query";
import { ChevronDown, ChevronLeft } from "lucide-react";
import { useCallback,useState } from "react";

import { reportsApi } from "@/api/accounting";
import { AccountingReportLayout } from "@/components/common/AccountingReportLayout";
import { ReportBarChart } from "@/components/common/charts";
import { ReportFilters } from "@/components/common/ReportFilters";
import { Button } from "@/components/ui";
import { chartColors } from "@/lib/chartColors";
import { formatCurrency } from "@/lib/utils";
import { cn } from "@/lib/utils";
import type { BalanceSheetSectionDto } from "@/types/accounting";

interface BalanceSheetReportProps {
  fiscalYearId?: number;
  asOfDate?: string;
  externalFilters?: { toDate?: string };
  hideInternalControls?: boolean;
}

function SectionRow({ section, depth }: { section: BalanceSheetSectionDto; depth: number }) {
  const [expanded, setExpanded] = useState(depth < 1);
  const hasChildren = section.children && section.children.length > 0;

  return (
    <div>
      <div className={cn(
        "flex items-center justify-between px-3 py-1.5 border-t border-border text-sm hover:bg-muted/20",
        depth === 0 && "font-medium bg-muted/20",
        depth === 1 && "pr-8",
        depth >= 2 && "pr-12 text-xs"
      )}>
        <div className="flex items-center gap-2">
          {hasChildren ? (
            <Button variant="ghost" size="icon" className="h-6 w-6" onClick={() => setExpanded(!expanded)}>
              {expanded ? <ChevronDown className="w-3 h-3" /> : <ChevronLeft className="w-3 h-3" />}
            </Button>
          ) : <span className="w-4" />}
          <span className="font-mono text-xs text-muted-foreground">{section.accountCode}</span>
          <span>{section.accountName}</span>
        </div>
        <span className="font-mono text-sm text-foreground font-bold">{formatCurrency(section.balance)}</span>
      </div>
      {hasChildren && expanded && section.children.map((child) => (
        <SectionRow key={child.accountID} section={child} depth={depth + 1} />
      ))}
    </div>
  );
}

export function BalanceSheetReport({ fiscalYearId, asOfDate, externalFilters, hideInternalControls }: BalanceSheetReportProps) {
  const [internalFilters, setInternalFilters] = useState<Record<string, any>>({
    toDate: asOfDate || new Date().toISOString().split("T")[0],
  });

  const filters = {
    ...internalFilters,
    ...(externalFilters?.toDate !== undefined ? { toDate: externalFilters.toDate } : {}),
  };

  const { data, isLoading, error, refetch } = useQuery({
    queryKey: ["reports", "balance-sheet", filters.toDate, fiscalYearId],
    queryFn: () => reportsApi.balanceSheet(filters.toDate!, fiscalYearId),
    enabled: !!filters.toDate,
  });

  const handleFilterChange = useCallback((key: string, value: any) => {
    setInternalFilters(prev => ({ ...prev, [key]: value }));
  }, []);


  const handlePrint = useCallback(() => {
    const params = new URLSearchParams();
    if (fiscalYearId) params.set("fiscalYearId", String(fiscalYearId));
    if (filters.toDate) params.set("date", filters.toDate);
    window.open(`/reports/balance-sheet/print?${params.toString()}`, "_blank");
  }, [fiscalYearId, filters.toDate]);

  const customKPIs = data ? [
    { label: 'إجمالي الأصول', value: formatCurrency(data.totalAssets), color: 'info' },
    { label: 'إجمالي الخصوم', value: formatCurrency(data.totalLiabilities), color: 'warning' },
    { label: 'حقوق الملكية', value: formatCurrency(data.totalEquity), color: 'success' },
    { label: 'الحالة', value: data.isBalanced ? 'متوازنة' : 'غير متوازنة', color: data.isBalanced ? 'text-success' : 'text-danger' },
  ] : [];

  const chartContent = data ? (
    <ReportBarChart
      data={[
        { name: 'الأصول', value: data.totalAssets, fill: chartColors.primary },
        { name: 'الخصوم', value: data.totalLiabilities, fill: chartColors.warning },
        { name: 'حقوق الملكية', value: data.totalEquity, fill: chartColors.success },
      ]}
      xKey="name"
      yKeys={[{ key: 'value', color: chartColors.primary, label: 'المبلغ' }]}
      title="الميزانية العمومية - ملخص"
      height={280}
    />
  ) : undefined;

  const filterBar = hideInternalControls ? undefined : (
    <ReportFilters
      filters={['toDate']}
      values={filters}
      onChange={handleFilterChange}
      onApply={() => refetch()}
      showApplyButton={false}
    />
  );

  return (
    <AccountingReportLayout
      title="الميزانية العمومية"
      description="عرض الأصول والخصوم وحقوق الملكية"
      isLoading={isLoading}
      customKPIs={customKPIs}
      filterBar={filterBar}
      chartContent={chartContent}      onPrint={hideInternalControls ? undefined : (data ? handlePrint : undefined)}
    >
      {error ? (
        <div className="text-destructive text-sm">فشل في تحميل التقرير</div>
      ) : !data ? (
        <div className="text-muted-foreground text-sm p-8 text-center">اختر تاريخاً لعرض الميزانية</div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          <div className="border rounded-xl overflow-hidden">
            <div className="bg-info/10 p-3 font-medium text-info">الأصول</div>
            {data.assets.map((a: BalanceSheetSectionDto) => <SectionRow key={a.accountID} section={a} depth={0} />)}
            <div className="flex justify-between p-3 bg-info/10 font-medium border-t">
              <span>إجمالي الأصول</span>
              <span className="font-mono text-foreground">{formatCurrency(data.totalAssets)}</span>
            </div>
          </div>

          <div className="space-y-4">
            <div className="border rounded-xl overflow-hidden">
              <div className="bg-warning/10 p-3 font-medium text-warning">الخصوم</div>
              {data.liabilities.map((l: BalanceSheetSectionDto) => <SectionRow key={l.accountID} section={l} depth={0} />)}
              <div className="flex justify-between p-3 bg-warning/10 font-medium border-t">
                <span>إجمالي الخصوم</span>
                <span className="font-mono text-foreground">{formatCurrency(data.totalLiabilities)}</span>
              </div>
            </div>

            <div className="border rounded-xl overflow-hidden">
              <div className="bg-success/10 p-3 font-medium text-success">حقوق الملكية</div>
              {data.equity.map((e: BalanceSheetSectionDto) => <SectionRow key={e.accountID} section={e} depth={0} />)}
              <div className="flex justify-between p-3 bg-success/10 font-medium border-t">
                <span>إجمالي حقوق الملكية</span>
                <span className="font-mono">{formatCurrency(data.totalEquity)}</span>
              </div>
            </div>
          </div>

          <div className="lg:col-span-2">
            <div className={cn(
              "p-3 rounded-xl text-center font-medium",
              data.isBalanced ? "bg-success/10 text-success" : "bg-destructive/10 text-destructive"
            )}>
              {data.isBalanced
                ? "الميزانية متوازنة ✓ — الأصول = الخصوم + حقوق الملكية"
                : "الميزانية غير متوازنة ✗ — يوجد فرق في التسجيل"
              }
            </div>
          </div>
        </div>
      )}
    </AccountingReportLayout>
  );
}

