import { zodResolver } from "@hookform/resolvers/zod";
import { useQuery } from "@tanstack/react-query";
import { BarChart3 } from "lucide-react";
import { useEffect } from "react";
import { type Resolver, useForm } from "react-hook-form";

import { accountsApi, periodsApi,quartersApi } from "@/api/accounting";
import { budgetApi } from "@/api/budget";
import { BaseFormDialog, FormField, FormSection, Input, NativeSelect } from "@/components/ui";
import { useApiMutation } from "@/hooks";
import type { ChartOfAccountDto, FiscalPeriodDto,QuarterDto } from "@/types/accounting";
import {
  type CreateBudgetItemForm,
  createBudgetItemSchema,
} from "@/types/budget";

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  fiscalYearID: number | null;
  editItem?: any;
  onSuccess: () => void;
}

export function BudgetFormDialog({
  open,
  onOpenChange,
  fiscalYearID,
  editItem,
  onSuccess,
}: Props) {
  const isEditing = !!editItem;

  const form = useForm<CreateBudgetItemForm>({
    resolver: zodResolver(createBudgetItemSchema) as Resolver<CreateBudgetItemForm>,
    defaultValues: {
      accountID: 0,
      plannedAmount: 0,
      quarterID: null,
      notes: "",
    },
  });

  const { register, handleSubmit, formState: { errors, isDirty }, setValue, reset, watch } = form;

  // جلب حسابات الاستخدامات (المصروفات) - BookNumber = 3
  const { data: allAccounts } = useQuery({
    queryKey: ["postable-accounts"],
    queryFn: () => accountsApi.getPostable(),
  });

  // تصفية الحسابات لعرض حسابات الاستخدامات فقط (BookNumber = 3)
  const accounts = allAccounts?.filter((acc: ChartOfAccountDto) => {
    // حسابات الاستخدامات تبدأ بـ 3xxx
    return acc.accountCode.startsWith("3");
  });

  // جلب الفصول
  const { data: quarters } = useQuery({
    queryKey: ["quarters", fiscalYearID],
    queryFn: () => quartersApi.getAll(fiscalYearID!),
    enabled: fiscalYearID != null,
  });

  // جلب الفترات الشهرية
  const { data: periods } = useQuery({
    queryKey: ["periods", fiscalYearID],
    queryFn: () => periodsApi.getAll(fiscalYearID!),
    enabled: fiscalYearID != null,
  });

  // تعبئة النموذج عند التعديل
  useEffect(() => {
    if (open) {
      if (editItem) {
        reset({
          accountID: editItem.accountID,
          plannedAmount: editItem.plannedAmount,
          quarterID: editItem.quarterID,
          periodID: editItem.periodID,
          notes: editItem.notes || "",
        });
      } else {
        reset({
          accountID: 0,
          plannedAmount: 0,
          quarterID: null,
          periodID: null,
          notes: "",
        });
      }
    }
  }, [open, editItem, reset]);

  // إنشاء/تعديل البند
  const mutation = useApiMutation(
    async (data: CreateBudgetItemForm) => {
      const payload = {
        ...data,
        fiscalYearID: fiscalYearID!,
      };
      if (isEditing) {
        return budgetApi.update(editItem.budgetItemID, {
          plannedAmount: data.plannedAmount,
          notes: data.notes,
        });
      }
      return budgetApi.create(payload);
    },
    {
      successMessage: isEditing ? "تم التحديث بنجاح" : "تم الإنشاء بنجاح",
      errorTitle: "خطأ في الحفظ",
      invalidateKeys: [["budget-report"]],
      onSuccess: () => {
        onOpenChange(false);
        reset();
        onSuccess();
      },
    }
  );

  // تحويل الحسابات إلى خيارات
  const accountOptions = accounts?.map((acc: ChartOfAccountDto) => ({
    label: `${acc.accountCode} - ${acc.accountName}`,
    value: String(acc.accountID),
  })) ?? [];

  // تحويل الفصول إلى خيارات
  const quarterOptions = [
    { label: "لفصل السنة كاملة", value: "null" },
    ...(quarters?.map((q: QuarterDto) => ({
      label: q.quarterName,
      value: String(q.quarterID),
    })) ?? []),
  ];

  // تحويل الفترات الشهرية إلى خيارات
  const periodOptions = [
    { label: "للسنة كاملة", value: "null" },
    ...(periods?.map((p: FiscalPeriodDto) => ({
      label: p.periodName,
      value: String(p.periodID),
    })) ?? []),
  ];

  return (
    <BaseFormDialog
      open={open}
      onOpenChange={onOpenChange}
      title={isEditing ? "تعديل بند الموازنة" : "إضافة بند موازنة جديد"}
      size="md"
      isLoading={mutation.isPending}
      isDirty={isDirty}
      formErrors={errors}
      onSubmit={handleSubmit((v) => mutation.mutate(v))}
      resetOnOpen
      reset={reset}
      submitLabel={isEditing ? "حفظ التعديلات" : "إضافة البند"}
    >
      <FormSection title="بيانات بند الموازنة" icon={BarChart3}>
        <FormField label="الحساب" required error={errors.accountID?.message}>
          <NativeSelect
            value={watch("accountID") || ""}
            options={accountOptions}
            onChange={(v) => setValue("accountID", Number(v), { shouldDirty: true })}
            placeholder="اختر الحساب"
          />
        </FormField>

        <FormField label="المبلغ المخطط" required error={errors.plannedAmount?.message}>
          <Input
            type="number"
            {...register("plannedAmount", { valueAsNumber: true })}
            placeholder="0"
          />
        </FormField>

        <FormField label="الفصل (اختياري)" error={errors.quarterID?.message}>
          <NativeSelect
            value={watch("quarterID") ?? "null"}
            options={quarterOptions}
            onChange={(v) => {
              setValue("quarterID", v === "null" ? null : Number(v), { shouldDirty: true });
              // عند اختيار فصل، نلغي اختيار الشهر
              if (v !== "null") {
                setValue("periodID", null, { shouldDirty: true });
              }
            }}
          />
        </FormField>

        <FormField label="الشهر (اختياري)" error={errors.periodID?.message}>
          <NativeSelect
            value={watch("periodID") ?? "null"}
            options={periodOptions}
            onChange={(v) => {
              setValue("periodID", v === "null" ? null : Number(v), { shouldDirty: true });
              // عند اختيار شهر، نلغي اختيار الفصل
              if (v !== "null") {
                setValue("quarterID", null, { shouldDirty: true });
              }
            }}
          />
        </FormField>

        <FormField label="ملاحظات" error={errors.notes?.message}>
          <Input {...register("notes")} placeholder="ملاحظات إضافية (اختياري)" />
        </FormField>
      </FormSection>
    </BaseFormDialog>
  );
}

import { Pencil, Trash2 } from "lucide-react";

import { Badge, Button, Card, Heading,Skeleton } from "@/components/ui";
import { formatCurrency } from "@/lib/utils";

interface Props {
  data: any;
  isLoading: boolean;
  onRefresh: () => void;
  onEdit?: (item: any) => void;
  onDelete?: (item: any) => void;
  showQuarters?: boolean;
  showMonthly?: boolean;
  selectedMonth?: number | null;
}

export function BudgetReport({ data, isLoading, showQuarters, showMonthly, selectedMonth, onEdit, onDelete }: Props) {
  if (isLoading) {
    return <Skeleton className="h-96 rounded-3xl" />;
  }

  if (!data) {
    return (
      <Card className="p-12 text-center text-muted-foreground">
        لا توجد بيانات موازنة
      </Card>
    );
  }

  // حالة التقرير الشهري
  if (showMonthly && data?.months) {
    // تصفية الشهور حسب الاختيار
    const filteredMonths = selectedMonth
      ? data.months.filter((m: any) => m.periodID === selectedMonth)
      : data.months;

    return (
      <div className="space-y-4">
        {filteredMonths.length === 0 ? (
          <Card className="p-12 text-center text-muted-foreground">
            لا توجد بيانات موازنة لهذا الشهر
          </Card>
        ) : (
          filteredMonths.map((month: any) => (
          <Card
            key={month.periodID}
            className="border-none rounded-3xl overflow-hidden"
          >
            <div className="p-4 bg-muted/30 flex items-center justify-between">
               <Heading level="h3" className="font-bold text-lg">{month.periodName}</Heading>
              <div className="flex gap-4 text-sm">
                <span>المخطط: {formatCurrency(month.totalPlanned)}</span>
                <span>الفعلي: {formatCurrency(month.totalActual)}</span>
              </div>
            </div>
            <table className="w-full text-sm" role="table" aria-label="تقرير الموازنة">
              <thead className="bg-muted/50 sticky top-0 z-10">
                <tr>
                  <th className="text-end p-3">رقم الحساب</th>
                  <th className="text-end p-3">الحساب</th>
                  <th className="text-end p-3">المخطط</th>
                  <th className="text-end p-3">الفعلي</th>
                  <th className="text-end p-3">الحالة</th>
                  {(onEdit || onDelete) && <th className="text-end p-3">إجراءات</th>}
                </tr>
              </thead>
              <tbody>
                {month.items?.map((item: any) => (
                  <tr
                    key={item.budgetItemID}
                    className="border-t border-border hover:bg-muted/20"
                  >
                    <td className="p-3 font-mono text-xs">{item.accountCode}</td>
                    <td className="p-3 font-medium">{item.accountName}</td>
                    <td className="p-3">{formatCurrency(item.plannedAmount)}</td>
                    <td className="p-3">{formatCurrency(item.actualAmount)}</td>
                    <td className="p-3">
                      <Badge
                        variant={
                          item.status === "مطابق"
                            ? "success"
                            : item.status === "تجاوز"
                              ? "destructive"
                              : "secondary"
                        }
                      >
                        {item.status}
                      </Badge>
                    </td>
                    {(onEdit || onDelete) && (
                      <td className="p-3">
                        <div className="flex gap-1">
                          {onEdit && (
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => onEdit(item)}
                            >
                              <Pencil className="w-4 h-4" />
                            </Button>
                          )}
                          {onDelete && (
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => onDelete(item)}
                              className="text-destructive hover:text-destructive"
                            >
                              <Trash2 className="w-4 h-4" />
                            </Button>
                          )}
                        </div>
                      </td>
                    )}
                  </tr>
                ))}
              </tbody>
            </table>
          </Card>
        ))
        )}
      </div>
    );
  }

  // حالة التقرير السنوي
  if (!showQuarters) {
    return (
      <Card className="border-none rounded-3xl overflow-hidden">
        <div className="p-4 bg-muted/30">
          <Heading level="h3" className="font-bold text-lg">
            تقرير الموازنة السنوي - {data.yearName}
          </Heading>
        </div>
        <table className="w-full text-sm">
          <thead className="bg-muted/50 sticky top-0 z-10">
            <tr>
              <th className="text-end p-3">رقم الحساب</th>
              <th className="text-end p-3">الحساب</th>
              <th className="text-end p-3">المخطط</th>
              <th className="text-end p-3">الفعلي</th>
              <th className="text-end p-3">الفرق</th>
              <th className="text-end p-3">النسبة</th>
              <th className="text-end p-3">الحالة</th>
              {(onEdit || onDelete) && <th className="text-end p-3">إجراءات</th>}
            </tr>
          </thead>
          <tbody>
            {data.items?.map((item: any) => (
              <tr
                key={item.budgetItemID}
                className="border-t border-border hover:bg-muted/20"
              >
                <td className="p-3 font-mono text-xs">{item.accountCode}</td>
                <td className="p-3 font-medium">{item.accountName}</td>
                <td className="p-3">{formatCurrency(item.plannedAmount)}</td>
                <td className="p-3">{formatCurrency(item.actualAmount)}</td>
                <td
                  className={`p-3 font-medium ${
                    item.variance > 0
                      ? "text-destructive"
                      : item.variance < 0
                        ? "text-emerald-600 dark:text-emerald-400"
                        : ""
                  }`}
                >
                  {formatCurrency(Math.abs(item.variance))}
                </td>
                <td className="p-3">{Math.abs(item.variancePercentage)}%</td>
                <td className="p-3">
                  <Badge
                    variant={
                      item.status === "مطابق"
                        ? "success"
                        : item.status === "تجاوز"
                          ? "destructive"
                          : "secondary"
                    }
                  >
                    {item.status}
                  </Badge>
                </td>
                {(onEdit || onDelete) && (
                  <td className="p-3">
                    <div className="flex gap-1">
                      {onEdit && (
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => onEdit(item)}
                        >
                          <Pencil className="w-4 h-4" />
                        </Button>
                      )}
                      {onDelete && (
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => onDelete(item)}
                          className="text-destructive hover:text-destructive"
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      )}
                    </div>
                  </td>
                )}
              </tr>
            ))}
          </tbody>
          <tfoot className="bg-muted/50 font-bold">
            <tr>
              <td className="p-3"></td>
              <td className="p-3">الإجمالي</td>
              <td className="p-3">{formatCurrency(data.totalPlanned)}</td>
              <td className="p-3">{formatCurrency(data.totalActual)}</td>
              <td
                className={`p-3 ${
                  data.totalVariance > 0 ? "text-destructive" : "text-emerald-600 dark:text-emerald-400"
                }`}
              >
                {formatCurrency(Math.abs(data.totalVariance))}
              </td>
              <td className="p-3">{Math.abs(data.totalVariancePercentage)}%</td>
              <td></td>
            </tr>
          </tfoot>
        </table>
      </Card>
    );
  }

  // حالة التقرير حسب الفصول
  return (
    <div className="space-y-4">
      {data.quarters?.map((quarter: any) => (
        <Card
          key={quarter.quarterID}
          className="border-none rounded-3xl overflow-hidden"
        >
          <div className="p-4 bg-muted/30 flex items-center justify-between">
            <Heading level="h3" className="font-bold text-lg">{quarter.quarterName}</Heading>
            <div className="flex gap-4 text-sm">
              <span>المخطط: {formatCurrency(quarter.totalPlanned)}</span>
              <span>الفعلي: {formatCurrency(quarter.totalActual)}</span>
            </div>
          </div>
          <table className="w-full text-sm">
            <thead className="bg-muted/50 sticky top-0 z-10">
              <tr>
                <th className="text-end p-3">رقم الحساب</th>
                <th className="text-end p-3">الحساب</th>
                <th className="text-end p-3">المخطط</th>
                <th className="text-end p-3">الفعلي</th>
                <th className="text-end p-3">الحالة</th>
                {(onEdit || onDelete) && <th className="text-end p-3">إجراءات</th>}
              </tr>
            </thead>
            <tbody>
              {quarter.items?.map((item: any) => (
                <tr
                  key={item.budgetItemID}
                  className="border-t border-border hover:bg-muted/20"
                >
                  <td className="p-3 font-mono text-xs">{item.accountCode}</td>
                  <td className="p-3 font-medium">{item.accountName}</td>
                  <td className="p-3">{formatCurrency(item.plannedAmount)}</td>
                  <td className="p-3">{formatCurrency(item.actualAmount)}</td>
                  <td className="p-3">
                    <Badge
                      variant={
                        item.status === "مطابق"
                          ? "success"
                          : item.status === "تجاوز"
                            ? "destructive"
                            : "secondary"
                      }
                    >
                      {item.status}
                    </Badge>
                  </td>
                  {(onEdit || onDelete) && (
                    <td className="p-3">
                      <div className="flex gap-1">
                        {onEdit && (
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => onEdit(item)}
                          >
                            <Pencil className="w-4 h-4" />
                          </Button>
                        )}
                        {onDelete && (
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => onDelete(item)}
                            className="text-destructive hover:text-destructive"
                          >
                            <Trash2 className="w-4 h-4" />
                          </Button>
                        )}
                      </div>
                    </td>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        </Card>
      ))}
    </div>
  );

  return null;
}

