﻿import { useQuery } from "@tanstack/react-query";
import { useCallback, useEffect, useMemo,useState } from "react";

import { periodsApi,reportsApi } from "@/api/accounting";
import { AccountingReportLayout } from "@/components/common/AccountingReportLayout";
import { ReportBarChart, ReportPieChart } from "@/components/common/charts";
import { Card, Heading, Text } from "@/components/ui";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/Select";
import { chartColors } from "@/lib/chartColors";
import { formatCurrency } from "@/lib/utils";
import type { FiscalPeriodDto, TrialBalanceItemDto } from "@/types/accounting";

interface CurrentOperationsReportProps {
  fiscalYearId?: number;
  externalFilters?: { periodId?: number };
  hideInternalControls?: boolean;
}

export function CurrentOperationsReport({ fiscalYearId, externalFilters, hideInternalControls }: CurrentOperationsReportProps) {
  const [internalSelectedPeriodId, setInternalSelectedPeriodId] = useState<number | undefined>();
  const selectedPeriodId = externalFilters?.periodId !== undefined ? externalFilters.periodId : internalSelectedPeriodId;

  const { data: periods } = useQuery({
    queryKey: ["periods", fiscalYearId],
    queryFn: () => periodsApi.getAll(fiscalYearId!),
    enabled: !!fiscalYearId,
  });

  useEffect(() => {
    if (periods && periods.length > 0 && !selectedPeriodId) {
      const activePeriod = periods.find((p: FiscalPeriodDto) => !p.isClosed);
      setInternalSelectedPeriodId(activePeriod?.periodID ?? periods[periods.length - 1].periodID);
    }
  }, [periods]);

  const { data: trialBalance, isLoading, error } = useQuery({
    queryKey: ["reports", "trial-balance", fiscalYearId, selectedPeriodId],
    queryFn: () => reportsApi.trialBalance({ fiscalYearId, periodId: selectedPeriodId }),
    enabled: !!fiscalYearId && !!selectedPeriodId,
  });

  const handlePrint = useCallback(() => {
    const params = new URLSearchParams();
    if (fiscalYearId) params.set("fiscalYearId", String(fiscalYearId));
    if (selectedPeriodId) params.set("periodId", String(selectedPeriodId));
    window.open(`/reports/current-operations/print?${params.toString()}`, "_blank");
  }, [fiscalYearId, selectedPeriodId]);

  const selectedPeriod = periods?.find((p: FiscalPeriodDto) => p.periodID === selectedPeriodId);

  const classified = useMemo(() => {
    if (!trialBalance) return null;
    const revenueAccounts = trialBalance.filter((a: TrialBalanceItemDto) => a.accountCode.startsWith("4"));
    const expenseAccounts = trialBalance.filter((a: TrialBalanceItemDto) => a.accountCode.startsWith("3"));
    const assetAccounts = trialBalance.filter((a: TrialBalanceItemDto) => a.accountCode.startsWith("1"));
    const liabilityAccounts = trialBalance.filter((a: TrialBalanceItemDto) => a.accountCode.startsWith("2") && !a.accountCode.startsWith("21") && !a.accountCode.startsWith("22"));
    const equityAccounts = trialBalance.filter((a: TrialBalanceItemDto) => a.accountCode.startsWith("21") || a.accountCode.startsWith("22"));

    return {
      revenueAccounts,
      expenseAccounts,
      assetAccounts,
      liabilityAccounts,
      equityAccounts,
      totalRevenue: revenueAccounts.reduce((s: number, a: TrialBalanceItemDto) => s + a.balance, 0),
      totalExpenses: expenseAccounts.reduce((s: number, a: TrialBalanceItemDto) => s + a.balance, 0),
      totalAssets: assetAccounts.reduce((s: number, a: TrialBalanceItemDto) => s + a.balance, 0),
      totalLiabilities: liabilityAccounts.reduce((s: number, a: TrialBalanceItemDto) => s + a.balance, 0),
      totalEquity: equityAccounts.reduce((s: number, a: TrialBalanceItemDto) => s + a.balance, 0),
    };
  }, [trialBalance]);

  const customKPIs = classified ? [
    { label: 'الإيرادات', value: formatCurrency(classified.totalRevenue), color: 'success' },
    { label: 'المصروفات', value: formatCurrency(classified.totalExpenses), color: 'danger' },
    { label: 'صافي الدخل', value: formatCurrency(classified.totalRevenue - classified.totalExpenses), color: (classified.totalRevenue - classified.totalExpenses) >= 0 ? 'text-green-600' : 'text-red-600' },
    { label: 'الفترة', value: selectedPeriod?.periodName || '', color: 'primary' },
  ] : [];

  const chartContent = classified ? (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      <ReportBarChart
        data={[
          { name: 'الأصول', value: classified.totalAssets },
          { name: 'الخصوم', value: classified.totalLiabilities },
          { name: 'حقوق الملكية', value: classified.totalEquity },
          { name: 'صافي الدخل', value: classified.totalRevenue - classified.totalExpenses },
        ]}
        xKey="name"
        yKeys={[{ key: 'value', color: chartColors.primary, label: 'المبلغ' }]}
        title="ملخص العمليات الجارية"
        height={280}
      />
      <ReportPieChart
        data={[
          { name: 'الإيرادات', value: classified.totalRevenue },
          { name: 'المصروفات', value: classified.totalExpenses },
        ]}
        nameKey="name"
        valueKey="value"
        title="نسبة الإيرادات والمصروفات"
        height={280}
      />
    </div>
  ) : undefined;

  const filterBar = hideInternalControls ? undefined : (
    <Card className="p-4 flex flex-wrap gap-4 items-end mb-6">
      <div className="w-full sm:w-64">
        <label className="label-filter">الفترة المحاسبية</label>
        <Select
          value={selectedPeriodId != null ? String(selectedPeriodId) : undefined}
          onValueChange={(v) => setInternalSelectedPeriodId(Number(v))}
        >
          <SelectTrigger className="h-10">
            <SelectValue placeholder="اختر الفترة" />
          </SelectTrigger>
          <SelectContent>
            {periods?.map((p: FiscalPeriodDto) => (
              <SelectItem key={p.periodID} value={String(p.periodID)}>
                {p.periodName} {p.isClosed ? "(مغلقة)" : ""}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
      {selectedPeriod && (
        <div className="text-sm text-muted-foreground">
          من {new Date(selectedPeriod.startDate).toLocaleDateString("ar-SA")} إلى{" "}
          {new Date(selectedPeriod.endDate).toLocaleDateString("ar-SA")}
        </div>
      )}
    </Card>
  );

  return (
    <AccountingReportLayout
      title="العمليات الجارية"
      description="عرض ملخص العمليات المحاسبية للفترة الجارية"
      isLoading={isLoading}
      customKPIs={customKPIs}
      filterBar={filterBar}
      chartContent={chartContent}
      onPrint={hideInternalControls ? undefined : (classified ? handlePrint : undefined)}
    >
      {error ? (
        <div className="text-destructive text-sm">فشل في تحميل التقرير</div>
      ) : !classified ? (
        <div className="text-muted-foreground text-sm p-8 text-center">لا توجد بيانات العمليات الجارية</div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          <Card className="border-none rounded-3xl overflow-hidden">
            <div className="p-4 bg-green-50">
               <Heading level="h3" className="font-bold text-lg text-green-800">الإيرادات</Heading>
            </div>
            <div className="p-4 max-h-64 overflow-y-auto">
              {classified.revenueAccounts.length === 0 ? (
                <Text variant="description" className="text-center">لا توجد إيرادات</Text>
              ) : (
                <div className="space-y-2">
                  {classified.revenueAccounts.map((account: TrialBalanceItemDto) => (
                    <div key={account.accountID} className="flex items-center justify-between py-2 border-b border-border last:border-0">
                      <div>
                        <span className="text-xs font-mono text-muted-foreground">{account.accountCode}</span>
                        <span className="text-sm mr-2">{account.accountName}</span>
                      </div>
                      <span className="text-sm font-medium text-green-600">{formatCurrency(account.balance)}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </Card>

          <Card className="border-none rounded-3xl overflow-hidden">
            <div className="p-4 bg-red-50">
               <Heading level="h3" className="font-bold text-lg text-red-800">المصروفات</Heading>
            </div>
            <div className="p-4 max-h-64 overflow-y-auto">
              {classified.expenseAccounts.length === 0 ? (
                <Text variant="description" className="text-center">لا توجد مصروفات</Text>
              ) : (
                <div className="space-y-2">
                  {classified.expenseAccounts.map((account: TrialBalanceItemDto) => (
                    <div key={account.accountID} className="flex items-center justify-between py-2 border-b border-border last:border-0">
                      <div>
                        <span className="text-xs font-mono text-muted-foreground">{account.accountCode}</span>
                        <span className="text-sm mr-2">{account.accountName}</span>
                      </div>
                      <span className="text-sm font-medium text-red-600">{formatCurrency(account.balance)}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </Card>

          <Card className="border-none rounded-3xl overflow-hidden">
            <div className="p-4 bg-blue-50">
               <Heading level="h3" className="font-bold text-lg text-blue-800">الأصول</Heading>
            </div>
            <div className="p-4 max-h-64 overflow-y-auto">
              {classified.assetAccounts.length === 0 ? (
                <Text variant="description" className="text-center">لا توجد أصول</Text>
              ) : (
                <div className="space-y-2">
                  {classified.assetAccounts.map((account: TrialBalanceItemDto) => (
                    <div key={account.accountID} className="flex items-center justify-between py-2 border-b border-border last:border-0">
                      <div>
                        <span className="text-xs font-mono text-muted-foreground">{account.accountCode}</span>
                        <span className="text-sm mr-2">{account.accountName}</span>
                      </div>
                      <span className="text-sm font-medium text-blue-600">{formatCurrency(account.balance)}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </Card>

          <Card className="border-none rounded-3xl overflow-hidden">
            <div className="p-4 bg-purple-50">
               <Heading level="h3" className="font-bold text-lg text-purple-800">الخصوم وحقوق الملكية</Heading>
            </div>
            <div className="p-4 max-h-64 overflow-y-auto">
              {classified.liabilityAccounts.length === 0 && classified.equityAccounts.length === 0 ? (
                <Text variant="description" className="text-center">لا توجد خصوم أو حقوق ملكية</Text>
              ) : (
                <div className="space-y-2">
                  {classified.equityAccounts.map((account: TrialBalanceItemDto) => (
                    <div key={account.accountID} className="flex items-center justify-between py-2 border-b border-border last:border-0">
                      <div>
                        <span className="text-xs font-mono text-muted-foreground">{account.accountCode}</span>
                        <span className="text-sm mr-2">{account.accountName}</span>
                        <span className="text-xs text-purple-600 mr-1">(حقوق ملكية)</span>
                      </div>
                      <span className="text-sm font-medium text-purple-600">{formatCurrency(account.balance)}</span>
                    </div>
                  ))}
                  {classified.liabilityAccounts.map((account: TrialBalanceItemDto) => (
                    <div key={account.accountID} className="flex items-center justify-between py-2 border-b border-border last:border-0">
                      <div>
                        <span className="text-xs font-mono text-muted-foreground">{account.accountCode}</span>
                        <span className="text-sm mr-2">{account.accountName}</span>
                      </div>
                      <span className="text-sm font-medium text-purple-600">{formatCurrency(account.balance)}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </Card>
        </div>
      )}
    </AccountingReportLayout>
  );
}

﻿import { useQuery } from "@tanstack/react-query";
import { TrendingDown } from "lucide-react";
import { useCallback,useMemo, useState } from "react";

import { fixedAssetApi } from "@/api/fixedAssets";
import { AccountingReportLayout } from "@/components/common/AccountingReportLayout";
import { ReportBarChart, ReportLineChart } from "@/components/common/charts";
import { ReportFilters } from "@/components/common/ReportFilters";
import { Card, Heading } from "@/components/ui";
import { chartColors } from "@/lib/chartColors";
import { formatCurrency } from "@/lib/utils";

interface DepreciationReportProps {
  fiscalYearId?: number;
  externalFilters?: { assetType?: string };
  hideInternalControls?: boolean;
}

export function DepreciationReport(_props: DepreciationReportProps) {
  const externalFilters = _props.externalFilters;
  const hideInternalControls = _props.hideInternalControls;
  const [internalFilters, setInternalFilters] = useState<Record<string, any>>({ assetType: 'all' });

  const filters = {
    ...internalFilters,
    ...(externalFilters?.assetType !== undefined ? { assetType: externalFilters.assetType } : {}),
  };

  const { data: assets = [], isLoading: loadingAssets } = useQuery({
    queryKey: ["fixed-assets"],
    queryFn: () => fixedAssetApi.getAll(),
  });

  const { data: assetTypes = [] } = useQuery({
    queryKey: ["asset-types"],
    queryFn: () => fixedAssetApi.getTypes(),
  });

  const filteredAssets = useMemo(() => {
    if (filters.assetType === 'all' || !filters.assetType) return assets;
    return assets.filter(a => a.assetTypeID === Number(filters.assetType));
  }, [assets, filters.assetType]);

  const stats = useMemo(() => {
    const activeAssets = filteredAssets.filter(a => a.status === 0);
    return {
      totalCost: activeAssets.reduce((s, a) => s + a.acquiredCost, 0),
      totalAccumulated: activeAssets.reduce((s, a) => s + a.accumulatedDepreciation, 0),
      totalNetBook: activeAssets.reduce((s, a) => s + a.netBookValue, 0),
      count: activeAssets.length,
    };
  }, [filteredAssets]);

  const handleFilterChange = useCallback((key: string, value: any) => {
    setInternalFilters(prev => ({ ...prev, [key]: value }));
  }, []);

  const handlePrint = useCallback(() => {
    const params = new URLSearchParams();
    if (filters.assetType !== 'all') params.set("typeId", filters.assetType!);
    window.open(`/reports/depreciation/print?${params.toString()}`, "_blank");
  }, [filters.assetType]);

  const customKPIs = [
    { label: 'عدد الأصول النشطة', value: stats.count, color: 'default' },
    { label: 'إجمالي التكلفة', value: formatCurrency(stats.totalCost), color: 'info' },
    { label: 'الإهلاك المتراكم', value: formatCurrency(stats.totalAccumulated), color: 'danger' },
    { label: 'القيمة الدفترية', value: formatCurrency(stats.totalNetBook), color: 'success' },
  ];

  const chartContent = filteredAssets.filter(a => a.status === 0).length > 0 ? (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      <ReportBarChart
        data={assetTypes.map(t => ({
          name: t.typeName,
          cost: filteredAssets.filter(a => a.assetTypeID === t.assetTypeID && a.status === 0).reduce((s, a) => s + a.acquiredCost, 0),
          depreciation: filteredAssets.filter(a => a.assetTypeID === t.assetTypeID && a.status === 0).reduce((s, a) => s + a.accumulatedDepreciation, 0),
          netBook: filteredAssets.filter(a => a.assetTypeID === t.assetTypeID && a.status === 0).reduce((s, a) => s + a.netBookValue, 0),
        }))}
        xKey="name"
        yKeys={[
          { key: 'cost', color: chartColors.primary, label: 'التكلفة' },
          { key: 'depreciation', color: chartColors.danger, label: 'الإهلاك' },
          { key: 'netBook', color: chartColors.success, label: 'القيمة الدفترية' },
        ]}
        title="الإهلاك حسب نوع الأصل"
        height={300}
      />
      <ReportLineChart
        data={filteredAssets
          .filter(a => a.status === 0)
          .sort((a, b) => new Date(a.inServiceDate).getTime() - new Date(b.inServiceDate).getTime())
          .slice(0, 10)
          .map(a => ({
            name: a.assetName.length > 15 ? a.assetName.substring(0, 15) + '...' : a.assetName,
            cost: a.acquiredCost,
            depreciation: a.accumulatedDepreciation,
            netBook: a.netBookValue,
          }))}
        xKey="name"
        lines={[
          { key: 'cost', color: chartColors.primary, label: 'التكلفة' },
          { key: 'depreciation', color: chartColors.danger, label: 'الإهلاك' },
          { key: 'netBook', color: chartColors.success, label: 'القيمة الدفترية' },
        ]}
        title="أعلى 10 أصول حسب التكلفة"
        height={300}
      />
    </div>
  ) : undefined;

  const filterBar = hideInternalControls ? undefined : (
    <ReportFilters
      filters={['assetType']}
      values={filters}
      onChange={handleFilterChange}
      showApplyButton={false}
    />
  );

  return (
    <AccountingReportLayout
      title="تقرير الإهلاك"
      description="عرض إهلاك الأصول الثابتة والقيمة الدفترية"
      isLoading={loadingAssets}
      customKPIs={customKPIs}
      filterBar={filterBar}
      chartContent={chartContent}
      onPrint={hideInternalControls ? undefined : (stats.count > 0 ? handlePrint : undefined)}
    >
      <Card className="border-none rounded-3xl overflow-hidden">
        <div className="p-4 bg-muted/30 flex items-center gap-2">
          <TrendingDown className="w-5 h-5 text-primary" />
          <Heading level="h3" className="font-bold text-lg">جدول إهلاك الأصول الثابتة</Heading>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-sm" role="table" aria-label="جدول الإهلاك">
            <thead className="bg-muted/50 sticky top-0 z-10">
              <tr>
                <th className="text-end p-3">رقم الأصل</th>
                <th className="text-end p-3">اسم الأصل</th>
                <th className="text-end p-3">التصنيف</th>
                <th className="text-end p-3">التكلفة</th>
                <th className="text-end p-3">نسبة الإهلاك</th>
                <th className="text-end p-3">الإهلاك المتراكم</th>
                <th className="text-end p-3">القيمة الدفترية</th>
                <th className="text-end p-3">آخر إهلاك</th>
              </tr>
            </thead>
            <tbody>
              {filteredAssets.filter(a => a.status === 0).length === 0 ? (
                <tr>
                  <td colSpan={8} className="p-8 text-center text-muted-foreground">
                    لا توجد أصول نشطة
                  </td>
                </tr>
              ) : (
                filteredAssets
                  .filter(a => a.status === 0)
                  .map((asset) => (
                    <tr key={asset.assetID} className="border-t border-border hover:bg-muted/20">
                      <td className="p-3 font-mono text-xs">{asset.assetNumber}</td>
                      <td className="p-3 font-medium">{asset.assetName}</td>
                      <td className="p-3 text-muted-foreground">{asset.categoryName || "—"}</td>
                      <td className="p-3 font-mono">{formatCurrency(asset.acquiredCost)}</td>
                      <td className="p-3">{asset.depreciationRate}%</td>
                      <td className="p-3 font-mono text-destructive">{formatCurrency(asset.accumulatedDepreciation)}</td>
                      <td className="p-3 font-mono text-emerald-600 dark:text-emerald-400 font-bold">{formatCurrency(asset.netBookValue)}</td>
                      <td className="p-3 text-xs text-muted-foreground">
                        {asset.lastDepreciationDate
                          ? new Date(asset.lastDepreciationDate).toLocaleDateString("ar-SA")
                          : "لم يتم بعد"}
                      </td>
                    </tr>
                  ))
              )}
            </tbody>
            <tfoot className="bg-muted/50 font-bold">
              <tr>
                <td className="p-3" colSpan={3}>الإجمالي</td>
                <td className="p-3 font-mono">{formatCurrency(stats.totalCost)}</td>
                <td className="p-3"></td>
                <td className="p-3 font-mono text-destructive">{formatCurrency(stats.totalAccumulated)}</td>
                <td className="p-3 font-mono text-emerald-600 dark:text-emerald-400">{formatCurrency(stats.totalNetBook)}</td>
                <td className="p-3"></td>
              </tr>
            </tfoot>
          </table>
        </div>
      </Card>
    </AccountingReportLayout>
  );
}

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { AlertTriangle, CheckCircle2 } from "lucide-react";
import { useState } from "react";
import { toast } from "sonner";

import { accountsApi, closingApi, fiscalYearsApi,periodsApi } from "@/api/accounting";
import { Button, Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle, Select, SelectContent, SelectItem, SelectTrigger, SelectValue, Text } from "@/components/ui";
import type { ChartOfAccountDto, FiscalPeriodDto,FiscalYearSummaryDto } from "@/types/accounting";

interface FiscalYearCloseDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function FiscalYearCloseDialog({ open, onOpenChange }: FiscalYearCloseDialogProps) {
  const queryClient = useQueryClient();
  const [step, setStep] = useState<"close" | "opening">("close");
  const [targetAccountID, setTargetAccountID] = useState<number | null>(null);
  const [selectedFiscalYearID, setSelectedFiscalYearID] = useState<number | null>(null);
  const [targetFiscalYearID, setTargetFiscalYearID] = useState<number | null>(null);
  const [result, setResult] = useState<{ entryNumber: string; netResult: number; resultType: string } | null>(null);

  const { data: fiscalYears } = useQuery({
    queryKey: ["fiscal-years"],
    queryFn: () => fiscalYearsApi.getAll(),
    enabled: open,
  });

  const selectedYear = fiscalYears?.find((y: FiscalYearSummaryDto) => y.fiscalYearID === selectedFiscalYearID);

  const { data: periods } = useQuery({
    queryKey: ["periods", selectedFiscalYearID],
    queryFn: () => periodsApi.getAll(selectedFiscalYearID!),
    enabled: open && !!selectedFiscalYearID,
  });

  const { data: accounts } = useQuery({
    queryKey: ["accounts", "all"],
    queryFn: () => accountsApi.getAll(),
    enabled: open,
  });

  // Default: surplus/deficit account (3400 or similar)
  const surplusAccount = accounts?.find((a: ChartOfAccountDto) => a.accountCode.startsWith("340"));

  const closeMutation = useMutation({
    mutationFn: () => closingApi.closeYear({
      fiscalYearID: selectedFiscalYearID!,
      targetAccountID: targetAccountID ?? surplusAccount?.accountID ?? 0,
    }),
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["accounting"] });
      setResult({ entryNumber: data.entryNumber, netResult: data.netResult, resultType: data.resultType });
      toast.success("تم إقفال السنة المالية بنجاح");
    },
    onError: (err: any) => {
      const msg = err?.response?.data?.message || err?.message || "فشل في إقفال السنة";
      toast.error(msg);
    },
  });

  const openingMutation = useMutation({
    mutationFn: () => closingApi.createOpeningBalances({
      newFiscalYearID: targetFiscalYearID!,
      sourceFiscalYearID: selectedFiscalYearID!,
    }),
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["accounting"] });
      toast.success(`تم ترحيل الأرصدة الافتتاحية: ${data.accountsCarriedForward} حساب`);
      onOpenChange(false);
      setResult(null);
      setStep("close");
      setSelectedFiscalYearID(null);
      setTargetFiscalYearID(null);
    },
    onError: (err: any) => {
      const msg = err?.response?.data?.message || err?.message || "فشل في إنشاء الأرصدة الافتتاحية";
      toast.error(msg);
    },
  });

  const handleClose = () => {
    if (step === "close") {
      closeMutation.mutate();
    } else {
      openingMutation.mutate();
    }
  };

  const reset = () => {
    setStep("close");
    setResult(null);
    setSelectedFiscalYearID(null);
    setTargetFiscalYearID(null);
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={reset}>
      <DialogContent className="sm:max-w-[500px]" dir="rtl">
        <DialogHeader>
          <DialogTitle>{step === "close" ? "إقفال السنة المالية" : "إنشاء الأرصدة الافتتاحية"}</DialogTitle>
        </DialogHeader>

        {!result ? (
          <div className="space-y-4 py-2">
            {/* Step indicator */}
            <div className="flex items-center gap-2">
              <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium ${step === "close" ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground"}`}>1</div>
              <div className="h-px flex-1 bg-border" />
              <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium ${step === "opening" ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground"}`}>2</div>
            </div>

            {step === "close" ? (
              <>
                {/* Year selector */}
                <div className="space-y-1.5">
                  <label className="label-field">السنة المالية المراد إقفالها</label>
                  <Select value={String(selectedFiscalYearID ?? "")} onValueChange={(v) => setSelectedFiscalYearID(Number(v))}>
                    <SelectTrigger>
                      <SelectValue placeholder="اختر السنة المالية" />
                    </SelectTrigger>
                    <SelectContent>
                      {fiscalYears?.filter((y: FiscalYearSummaryDto) => !y.isClosed).map((fy: FiscalYearSummaryDto) => (
                        <SelectItem key={fy.fiscalYearID} value={String(fy.fiscalYearID)}>
                          {fy.yearName}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                {selectedFiscalYearID && (
                  <>
                    <div className="flex items-start gap-3 p-3 bg-amber-50 rounded-xl">
                      <AlertTriangle className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" />
                      <div className="text-sm text-amber-800">
                        <p className="font-medium">إقفال السنة {selectedYear?.yearName}</p>
                        <p className="mt-1">سيتم إقفال حسابات الإيرادات والمصروفات في حساب الأرباح المحتجزة. هذا الإجراء لا يمكن التراجع عنه.</p>
                      </div>
                    </div>

                    <div className="space-y-1.5">
                      <label className="label-field">حساب الأرباح المحتجزة (الفائض/العجز)</label>
                      <Select value={String(targetAccountID ?? surplusAccount?.accountID ?? "")} onValueChange={(v) => setTargetAccountID(Number(v))}>
                        <SelectTrigger>
                          <SelectValue placeholder="اختر الحساب" />
                        </SelectTrigger>
                        <SelectContent>
                          {accounts?.filter((a: ChartOfAccountDto) => a.isPostable).map((acc: ChartOfAccountDto) => (
                            <SelectItem key={acc.accountID} value={String(acc.accountID)}>
                              {acc.accountCode} - {acc.accountName}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>

                    <div className="text-sm text-muted-foreground bg-muted/30 p-3 rounded-xl">
                      <Text variant="body">عدد الفترات: {periods?.length ?? 0}</Text>
                      <Text variant="body">الفترات المغلقة: {periods?.filter((p: FiscalPeriodDto) => p.isClosed).length ?? 0}</Text>
                      <Text variant="body">الفترات المفتوحة: {periods?.filter((p: FiscalPeriodDto) => !p.isClosed).length ?? 0}</Text>
                    </div>
                  </>
                )}
              </>
            ) : (
              <>
                <div className="flex items-start gap-3 p-3 bg-blue-50 rounded-xl">
                  <CheckCircle2 className="w-5 h-5 text-blue-600 shrink-0 mt-0.5" />
                  <div className="text-sm text-blue-800">
                    <p className="font-medium">إنشاء الأرصدة الافتتاحية</p>
                    <p className="mt-1">سيتم ترحيل أرصدة حسابات الميزانية العمومية إلى السنة الجديدة.</p>
                  </div>
                </div>

                <div className="space-y-1.5">
                  <label className="label-field">السنة المالية المستهدفة</label>
                  <Select value={targetFiscalYearID != null ? String(targetFiscalYearID) : undefined} onValueChange={(v) => setTargetFiscalYearID(Number(v))}>
                    <SelectTrigger>
                      <SelectValue placeholder="اختر السنة المالية" />
                    </SelectTrigger>
                    <SelectContent>
                      {fiscalYears?.map((fy: FiscalYearSummaryDto) => (
                        <SelectItem key={fy.fiscalYearID} value={String(fy.fiscalYearID)}>
                          {fy.yearName} {fy.isClosed ? "(مغلقة)" : ""}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </>
            )}

            {/* Navigation buttons */}
            <div className="flex gap-2 pt-2">
              {step === "opening" && (
                <Button variant="outline" onClick={() => setStep("close")}>الرجوع</Button>
              )}
            </div>

            <DialogFooter className="gap-2">
              <Button variant="outline" onClick={reset}>إلغاء</Button>
              {step === "close" ? (
                <Button onClick={handleClose} disabled={!selectedFiscalYearID || closeMutation.isPending} className="bg-amber-600 hover:bg-amber-700">
                  {closeMutation.isPending ? "جاري الإقفال..." : "إقفال السنة"}
                </Button>
              ) : (
                <Button onClick={handleClose} disabled={!targetFiscalYearID || openingMutation.isPending}>
                  {openingMutation.isPending ? "جاري..." : "إنشاء الأرصدة"}
                </Button>
              )}
            </DialogFooter>
          </div>
        ) : (
          /* Result display */
          <div className="space-y-4 py-4">
            <div className="flex flex-col items-center gap-3">
              <div className="w-16 h-16 rounded-full bg-green-100 flex items-center justify-center">
                <CheckCircle2 className="w-8 h-8 text-green-600" />
              </div>
              <Text variant="body" className="font-medium">تم إقفال السنة المالية</Text>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 bg-muted/30 p-4 rounded-xl">
              <div>
                <span className="text-xs text-muted-foreground">رقم قيد الإقفال</span>
                <p className="font-medium font-mono" dir="ltr">{result.entryNumber}</p>
              </div>
              <div>
                <span className="text-xs text-muted-foreground">صافي النتيجة</span>
                <p className={`font-medium ${result.resultType === "فائض" ? "text-green-600" : "text-red-600"}`}>
                  {result.resultType}: {result.netResult.toLocaleString()} د.ع
                </p>
              </div>
            </div>
            <div className="flex justify-center">
              <Button onClick={() => { setStep("opening"); setResult(null); }}>
                إنشاء الأرصدة الافتتاحية
              </Button>
            </div>
            <DialogFooter>
              <Button variant="outline" onClick={reset}>إغلاق</Button>
            </DialogFooter>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

