import { zodResolver } from "@hookform/resolvers/zod";
import { Calendar } from "lucide-react";
import { useEffect } from "react";
import { Controller,type Resolver, useForm } from "react-hook-form";
import { z } from "zod";

import { fiscalYearsApi } from "@/api/accounting";
import { BaseFormDialog, DateInput, FormField, FormSection, Input } from "@/components/ui";
import { useApiMutation } from "@/hooks";

// ─── Schema ───────────────────────────────────────
const schema = z.object({
  yearName: z.string().min(1, "اسم السنة مطلوب").regex(/^\d{4}$/, "يجب أن يكون سنة (مثل 2027)"),
  startDate: z.string().min(1, "تاريخ البداية مطلوب"),
  endDate: z.string().min(1, "تاريخ النهاية مطلوب"),
  totalBudget: z.coerce.number().min(0, "الميزانية يجب أن تكون صفر أو أكثر"),
});

type FormValues = z.infer<typeof schema>;

// ─── Props ────────────────────────────────────────
interface FiscalYearFormDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

// ─── Component ────────────────────────────────────
export function FiscalYearFormDialog({ open, onOpenChange }: FiscalYearFormDialogProps) {
  const form = useForm<FormValues>({
    resolver: zodResolver(schema) as Resolver<FormValues>,
    defaultValues: {
      yearName: "",
      startDate: "",
      endDate: "",
      totalBudget: 0,
    },
  });

  const { register, handleSubmit, formState: { errors, isDirty }, reset, watch, setValue, control } = form;
  const yearName = watch("yearName");

  // ─── Auto-fill dates when year changes ──────────
  useEffect(() => {
    if (open) {
      reset({ yearName: "", startDate: "", endDate: "", totalBudget: 0 });
    }
  }, [open, reset]);

  useEffect(() => {
    if (yearName && /^\d{4}$/.test(yearName)) {
      setValue("startDate", `${yearName}-01-01`);
      setValue("endDate", `${yearName}-12-31`);
    }
  }, [yearName, setValue]);

  // ─── Mutation ────────────────────────────────────
  const mutation = useApiMutation(
    async (data: FormValues) => {
      return fiscalYearsApi.create(data);
    },
    {
      successMessage: "تم إنشاء السنة المالية والفترات والفصول بنجاح",
      errorTitle: "خطأ في الإنشاء",
      invalidateKeys: [["fiscal-years"], ["periods"], ["quarters"]],
      onSuccess: () => {
        onOpenChange(false);
        reset();
      },
    }
  );

  return (
    <BaseFormDialog
      open={open}
      onOpenChange={onOpenChange}
      title="إضافة سنة مالية جديدة"
      description="ستُنشأ تلقائياً 12 فترة شهرية و4 فصول مالية"
      size="md"
      isLoading={mutation.isPending}
      isDirty={isDirty}
      formErrors={errors}
      onSubmit={handleSubmit((v) => mutation.mutate(v))}
      resetOnOpen
      reset={reset}
      submitLabel="إنشاء السنة المالية"
      submitIcon={<Calendar className="w-4 h-4" />}
    >
      <FormSection title="بيانات السنة المالية" icon={Calendar}>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <FormField label="اسم السنة المالية" required error={errors.yearName?.message}>
            <Input {...register("yearName")} placeholder="مثال: 2027" maxLength={4} />
          </FormField>
          <FormField label="الميزانية الإجمالية" error={errors.totalBudget?.message}>
            <Input {...register("totalBudget")} type="number" min={0} placeholder="0" />
          </FormField>
          <FormField label="تاريخ البداية" required error={errors.startDate?.message}>
            <Controller
              control={control}
              name="startDate"
              render={({ field }) => (
                <DateInput value={field.value} onChange={field.onChange} />
              )}
            />
          </FormField>
          <FormField label="تاريخ النهاية" required error={errors.endDate?.message}>
            <Controller
              control={control}
              name="endDate"
              render={({ field }) => (
                <DateInput value={field.value} onChange={field.onChange} />
              )}
            />
          </FormField>
        </div>
      </FormSection>
    </BaseFormDialog>
  );
}

﻿import { useQuery } from "@tanstack/react-query";
import { Building2 } from "lucide-react";
import { useMemo,useState } from "react";

import { fixedAssetApi } from "@/api/fixedAssets";
import { AccountingReportLayout } from "@/components/common/AccountingReportLayout";
import { ReportBarChart, ReportPieChart } from "@/components/common/charts";
import { ReportFilters } from "@/components/common/ReportFilters";
import { Card, Heading } from "@/components/ui";
import { chartColors } from "@/lib/chartColors";
import { formatCurrency } from "@/lib/utils";

interface FixedAssetsReportProps {
  fiscalYearId?: number;
  asOfDate?: string;
  externalFilters?: { assetType?: string };
  hideInternalControls?: boolean;
}

export function FixedAssetsReport(_props: FixedAssetsReportProps) {
  const externalFilters = _props.externalFilters;
  const hideInternalControls = _props.hideInternalControls;
  const [internalFilters, setInternalFilters] = useState<Record<string, any>>({ assetType: 'all' });

  const filters = {
    ...internalFilters,
    ...(externalFilters?.assetType !== undefined ? { assetType: externalFilters.assetType } : {}),
  };

  const { data: assets = [], isLoading: loadingAssets } = useQuery({
    queryKey: ["fixed-assets"],
    queryFn: () => fixedAssetApi.getAll(),
  });

  const { data: assetTypes = [] } = useQuery({
    queryKey: ["asset-types"],
    queryFn: () => fixedAssetApi.getTypes(),
  });

  const filteredAssets = useMemo(() => {
    if (filters.assetType === 'all' || !filters.assetType) return assets;
    return assets.filter(a => a.assetTypeID === Number(filters.assetType));
  }, [assets, filters.assetType]);

  const stats = useMemo(() => {
    const activeAssets = filteredAssets.filter(a => a.status === 0);
    const disposedAssets = filteredAssets.filter(a => a.status === 1);
    return {
      totalCost: activeAssets.reduce((s, a) => s + a.acquiredCost, 0),
      totalAccumulated: activeAssets.reduce((s, a) => s + a.accumulatedDepreciation, 0),
      totalNetBook: activeAssets.reduce((s, a) => s + a.netBookValue, 0),
      activeCount: activeAssets.length,
      disposedCount: disposedAssets.length,
      totalCount: filteredAssets.length,
    };
  }, [filteredAssets]);

  const handleFilterChange = (key: string, value: any) => {
    setInternalFilters(prev => ({ ...prev, [key]: value }));
  };

  const handlePrint = () => {
    const params = new URLSearchParams();
    if (filters.assetType !== 'all') params.set("typeId", filters.assetType!);
    window.open(`/reports/fixed-assets/print?${params.toString()}`, "_blank");
  };

  const customKPIs = [
    { label: 'عدد الأصول النشطة', value: stats.activeCount, color: 'default' },
    { label: 'إجمالي التكلفة', value: formatCurrency(stats.totalCost), color: 'info' },
    { label: 'الإهلاك المتراكم', value: formatCurrency(stats.totalAccumulated), color: 'danger' },
    { label: 'القيمة الدفترية', value: formatCurrency(stats.totalNetBook), color: 'success' },
  ];

  const chartContent = filteredAssets.length > 0 ? (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      <ReportBarChart
        data={assetTypes.map(t => ({
          name: t.typeName,
          cost: filteredAssets.filter(a => a.assetTypeID === t.assetTypeID).reduce((s, a) => s + a.acquiredCost, 0),
          depreciation: filteredAssets.filter(a => a.assetTypeID === t.assetTypeID).reduce((s, a) => s + a.accumulatedDepreciation, 0),
        }))}
        xKey="name"
        yKeys={[
          { key: 'cost', color: chartColors.primary, label: 'التكلفة' },
          { key: 'depreciation', color: chartColors.danger, label: 'الإهلاك' },
        ]}
        title="التكلفة والإهلاك حسب النوع"
        height={280}
      />
      <ReportPieChart
        data={assetTypes.map(t => ({
          name: t.typeName,
          value: filteredAssets.filter(a => a.assetTypeID === t.assetTypeID && a.status === 0).length,
        })).filter(d => d.value > 0)}
        nameKey="name"
        valueKey="value"
        title="توزيع الأصول حسب النوع"
        height={280}
      />
    </div>
  ) : undefined;

  const filterBar = hideInternalControls ? undefined : (
    <ReportFilters
      filters={['assetType']}
      values={filters}
      onChange={handleFilterChange}
      showApplyButton={false}
    />
  );

  return (
    <AccountingReportLayout
      title="الأصول الثابتة"
      description="عرض سجل الأصول الثابتة والإهلاك"
      isLoading={loadingAssets}
      customKPIs={customKPIs}
      filterBar={filterBar}
      chartContent={chartContent}
      onPrint={hideInternalControls ? undefined : (filteredAssets.length > 0 ? handlePrint : undefined)}
    >
      <Card className="border-none rounded-3xl overflow-hidden">
        <div className="p-4 bg-muted/30 flex items-center gap-2">
          <Building2 className="w-5 h-5 text-primary" />
          <Heading level="h3" className="font-bold text-lg">سجل الأصول الثابتة</Heading>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-sm" role="table" aria-label="سجل الأصول الثابتة">
            <thead className="bg-muted/50 sticky top-0 z-10">
              <tr>
                <th className="text-end p-3">رقم الأصل</th>
                <th className="text-end p-3">اسم الأصل</th>
                <th className="text-end p-3">التصنيف</th>
                <th className="text-end p-3">تاريخ الشراء</th>
                <th className="text-end p-3">التكلفة</th>
                <th className="text-end p-3">نسبة الإهلاك</th>
                <th className="text-end p-3">الإهلاك المتراكم</th>
                <th className="text-end p-3">القيمة الدفترية</th>
                <th className="text-end p-3">الحالة</th>
              </tr>
            </thead>
            <tbody>
              {stats.activeCount === 0 ? (
                <tr>
                  <td colSpan={9} className="p-8 text-center text-muted-foreground">
                    لا توجد أصول ثابتة
                  </td>
                </tr>
              ) : (
                filteredAssets
                  .filter(a => a.status === 0)
                  .map((asset) => (
                    <tr key={asset.assetID} className="border-t border-border hover:bg-muted/20">
                      <td className="p-3 font-mono text-xs">{asset.assetNumber}</td>
                      <td className="p-3 font-medium">{asset.assetName}</td>
                      <td className="p-3 text-muted-foreground">{asset.categoryName || "—"}</td>
                      <td className="p-3 text-xs">
                        {new Date(asset.inServiceDate).toLocaleDateString("ar-SA")}
                      </td>
                      <td className="p-3 font-mono">{formatCurrency(asset.acquiredCost)}</td>
                      <td className="p-3">{asset.depreciationRate}%</td>
                      <td className="p-3 font-mono text-destructive">{formatCurrency(asset.accumulatedDepreciation)}</td>
                      <td className="p-3 font-mono text-emerald-600 dark:text-emerald-400 font-bold">{formatCurrency(asset.netBookValue)}</td>
                      <td className="p-3">
                        <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400">
                          نشط
                        </span>
                      </td>
                    </tr>
                  ))
              )}
            </tbody>
            <tfoot className="bg-muted/50 font-bold">
              <tr>
                <td className="p-3" colSpan={4}>الإجمالي</td>
                <td className="p-3 font-mono">{formatCurrency(stats.totalCost)}</td>
                <td className="p-3"></td>
                <td className="p-3 font-mono text-destructive">{formatCurrency(stats.totalAccumulated)}</td>
                <td className="p-3 font-mono text-emerald-600 dark:text-emerald-400">{formatCurrency(stats.totalNetBook)}</td>
                <td className="p-3"></td>
              </tr>
            </tfoot>
          </table>
        </div>
      </Card>
    </AccountingReportLayout>
  );
}

﻿import { useQuery } from "@tanstack/react-query";
import { useCallback,useEffect, useState } from "react";

import { accountsApi, reportsApi } from "@/api/accounting";
import { AccountingReportLayout } from "@/components/common/AccountingReportLayout";
import { ReportLineChart } from "@/components/common/charts";
import { ReportFilters } from "@/components/common/ReportFilters";
import { Button } from "@/components/ui";
import { Card } from "@/components/ui/Card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/Select";
import { chartColors } from "@/lib/chartColors";
import { formatCurrency } from "@/lib/utils";
import type { ChartOfAccountDto,GeneralLedgerDto, GeneralLedgerLineDto } from "@/types/accounting";

interface GeneralLedgerReportProps {
  fiscalYearId?: number;
  fromDate?: string;
  toDate?: string;
  externalFilters?: { accountId?: number };
  hideInternalControls?: boolean;
}

export function GeneralLedgerReport({ fromDate: propFromDate, toDate: propToDate, externalFilters, hideInternalControls }: GeneralLedgerReportProps) {
  const [internalAccountId, setInternalAccountId] = useState<number | null>(null);
  const accountId = externalFilters?.accountId !== undefined ? externalFilters.accountId : internalAccountId;
  const [filters, setFilters] = useState<Record<string, any>>({
    fromDate: propFromDate || '',
    toDate: propToDate || '',
  });

  useEffect(() => {
    if (propFromDate) setFilters(prev => ({ ...prev, fromDate: propFromDate }));
    if (propToDate) setFilters(prev => ({ ...prev, toDate: propToDate }));
  }, [propFromDate, propToDate]);

  const { data: accounts } = useQuery({
    queryKey: ["accounts", "all"],
    queryFn: () => accountsApi.getAll(),
  });

  const { data, isLoading, error, refetch } = useQuery({
    queryKey: ["reports", "general-ledger", accountId, filters.fromDate, filters.toDate],
    queryFn: () => reportsApi.generalLedger({
      accountId: accountId!,
      fromDate: filters.fromDate || undefined,
      toDate: filters.toDate || undefined,
    }),
    enabled: !!accountId,
  });

  const handleFilterChange = useCallback((key: string, value: any) => {
    setFilters(prev => ({ ...prev, [key]: value }));
  }, []);

  const handleSearch = () => {
    if (!accountId) return;
    refetch();
  };

  const handlePrint = useCallback(() => {
    const params = new URLSearchParams();
    if (accountId) params.set("accountId", String(accountId));
    if (filters.fromDate) params.set("fromDate", filters.fromDate);
    if (filters.toDate) params.set("toDate", filters.toDate);
    window.open(`/reports/general-ledger/print?${params.toString()}`, "_blank");
  }, [accountId, filters]);

  const chartContent = data ? (
    <ReportLineChart
      data={data.entries.map((e: GeneralLedgerLineDto) => ({
        name: new Date(e.entryDate).toLocaleDateString('ar-SA', { month: 'short', day: 'numeric' }),
        balance: e.runningBalance,
        debit: e.debit,
        credit: e.credit,
      }))}
      xKey="name"
      lines={[
        { key: 'balance', color: chartColors.primary, label: 'الرصيد' },
      ]}
      title="تطور الرصيد عبر الزمن"
      area
      height={250}
    />
  ) : undefined;

  const filterBar = hideInternalControls ? undefined : (
    <Card className="p-4 flex flex-wrap gap-4 items-end mb-6">
      <div className="w-full sm:w-64">
        <label className="label-filter">الحساب</label>
        <Select value={String(accountId ?? "")} onValueChange={(v) => setInternalAccountId(Number(v))}>
          <SelectTrigger className="h-10">
            <SelectValue placeholder="اختر الحساب" />
          </SelectTrigger>
          <SelectContent className="max-h-[250px]">
            {accounts?.map((a: ChartOfAccountDto) => (
              <SelectItem key={a.accountID} value={String(a.accountID)}>
                {a.accountCode} - {a.accountName}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
      <ReportFilters
        filters={['fromDate', 'toDate']}
        values={filters}
        onChange={handleFilterChange}
        showApplyButton={false}
        compact
      />
      <Button
        onClick={handleSearch}
        disabled={!accountId}
      >
        عرض
      </Button>
    </Card>
  );

  const customKPIs = data ? [
    { label: 'الرصيد الافتتاحي', value: formatCurrency(data.openingBalance), color: 'default' },
    { label: 'إجمالي المدين', value: formatCurrency(data.totalDebit), color: 'info' },
    { label: 'إجمالي الدائن', value: formatCurrency(data.totalCredit), color: 'success' },
    { label: 'الرصيد الختامي', value: formatCurrency(data.closingBalance), color: 'primary' },
  ] : [];

  return (
    <AccountingReportLayout
      title="دفتر الأستاذ العام"
      description="عرض حركات الحسابات التفصيلية"
      isLoading={isLoading}
      customKPIs={customKPIs}
      filterBar={filterBar}
      chartContent={chartContent}
      onPrint={hideInternalControls ? undefined : (data ? handlePrint : undefined)}
    >
      {error ? (
        <div className="text-destructive text-sm">فشل في تحميل التقرير</div>
      ) : !data ? (
        <div className="text-muted-foreground text-sm p-8 text-center">اختر حساباً وانقر عرض</div>
      ) : (
        <GeneralLedgerTable data={data} />
      )}
    </AccountingReportLayout>
  );
}

function GeneralLedgerTable({ data }: { data: GeneralLedgerDto }) {
  const isParentAccount = data.entries.some(e => e.accountCode && e.accountCode !== data.accountCode);

  return (
    <div className="border rounded-xl overflow-hidden">
      <table className="w-full text-sm" role="table" aria-label="دفتر الأستاذ العام">
        <thead className="bg-muted/50 sticky top-0 z-10">
          <tr>
            <th className="text-end p-2">التاريخ</th>
            <th className="text-end p-2">رقم القيد</th>
            {isParentAccount && <th className="text-end p-2">الحساب</th>}
            <th className="text-end p-2">البيان</th>
            <th className="text-end p-2">مركز التكلفة</th>
            <th className="text-start p-2 w-28">مدين</th>
            <th className="text-start p-2 w-28">دائن</th>
            <th className="text-start p-2 w-28">الرصيد</th>
          </tr>
        </thead>
        <tbody>
          {data.entries.map((entry, i) => (
            <tr key={i} className="border-t border-border hover:bg-muted/20">
              <td className="p-2 text-xs">{new Date(entry.entryDate).toLocaleDateString("ar-SA")}</td>
              <td className="p-2 font-mono text-xs ltr" dir="ltr">{entry.entryNumber}</td>
              {isParentAccount && (
                <td className="p-2 text-xs">
                  <span className="text-muted-foreground">{entry.accountCode}</span>
                  <span className="ms-1">{entry.accountName}</span>
                </td>
              )}
              <td className="p-2 text-xs">{entry.description}</td>
              <td className="p-2 text-xs text-muted-foreground">{entry.costCenterName || "—"}</td>
              <td className="p-2 text-start font-mono text-xs">{entry.debit > 0 ? formatCurrency(entry.debit) : "—"}</td>
              <td className="p-2 text-start font-mono text-xs">{entry.credit > 0 ? formatCurrency(entry.credit) : "—"}</td>
              <td className="p-2 text-start font-mono text-xs">{formatCurrency(entry.runningBalance)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

﻿import { useQuery } from "@tanstack/react-query";
import { useCallback,useEffect, useState } from "react";

import { fiscalYearsApi,reportsApi } from "@/api/accounting";
import { AccountingReportLayout } from "@/components/common/AccountingReportLayout";
import { ReportBarChart, ReportPieChart } from "@/components/common/charts";
import { chartColors } from "@/lib/chartColors";
import { formatCurrency } from "@/lib/utils";
import { cn } from "@/lib/utils";
import type { FiscalYearSummaryDto } from "@/types/accounting";

interface IncomeStatementReportProps {
  fiscalYearId?: number;
  hideInternalControls?: boolean;
}

export function IncomeStatementReport({ fiscalYearId, hideInternalControls }: IncomeStatementReportProps) {
  const { data: fiscalYears } = useQuery({
    queryKey: ["fiscal-years"],
    queryFn: () => fiscalYearsApi.getAll(),
  });

  const [selectedYearId, setSelectedYearId] = useState<number | undefined>(fiscalYearId);

  useEffect(() => {
    if (fiscalYearId) {
      setSelectedYearId(fiscalYearId);
    } else if (fiscalYears && fiscalYears.length > 0 && !selectedYearId) {
      const currentYear = new Date().getFullYear();
      const match = fiscalYears.find((y: FiscalYearSummaryDto) => y.yearName === String(currentYear));
      setSelectedYearId(match?.fiscalYearID ?? fiscalYears[fiscalYears.length - 1].fiscalYearID);
    }
  }, [fiscalYears, fiscalYearId]);

  const { data, isLoading, error } = useQuery({
    queryKey: ["reports", "income-statement", selectedYearId],
    queryFn: () => reportsApi.incomeStatement(selectedYearId!),
    enabled: !!selectedYearId,
  });


  const handlePrint = useCallback(() => {
    const params = new URLSearchParams();
    if (selectedYearId) params.set("fiscalYearId", String(selectedYearId));
    window.open(`/reports/income-statement/print?${params.toString()}`, "_blank");
  }, [selectedYearId]);

  const renderLines = (lines: { accountCode: string; accountName: string; amount: number; accountLevel: number }[]) => {
    return lines.map((line, i) => (
      <div key={i} className={cn(
        "flex justify-between px-3 py-1.5 border-t border-border text-sm",
        line.accountLevel <= 1 && "font-medium bg-muted/20",
        line.accountLevel === 2 && "pr-6",
        line.accountLevel >= 3 && "pr-10 text-xs"
      )}>
        <span>{line.accountName}</span>
        <span className="font-mono">{formatCurrency(line.amount)}</span>
      </div>
    ));
  };

  const customKPIs = data ? [
    { label: 'إجمالي الإيرادات', value: formatCurrency(data.totalRevenue), color: 'success' },
    { label: 'إجمالي المصروفات', value: formatCurrency(data.totalExpenses), color: 'danger' },
    { label: 'صافي الدخل', value: formatCurrency(data.netIncome), color: data.netIncome >= 0 ? 'text-green-600' : 'text-red-600' },
    { label: 'النسبة', value: data.totalRevenue > 0 ? `${((data.netIncome / data.totalRevenue) * 100).toFixed(1)}%` : '0%', color: 'primary' },
  ] : [];

  const chartContent = data ? (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      <ReportBarChart
        data={[
          { name: 'الإيرادات', value: data.totalRevenue },
          { name: 'المصروفات', value: data.totalExpenses },
          { name: 'صافي الدخل', value: data.netIncome },
        ]}
        xKey="name"
        yKeys={[{ key: 'value', color: chartColors.primary, label: 'المبلغ' }]}
        title="ملخص قائمة الدخل"
        height={280}
      />
      <ReportPieChart
        data={[
          { name: 'الإيرادات', value: data.totalRevenue },
          { name: 'المصروفات', value: data.totalExpenses },
        ]}
        nameKey="name"
        valueKey="value"
        title="نسبة الإيرادات والمصروفات"
        height={280}
      />
    </div>
  ) : undefined;

  return (
    <AccountingReportLayout
      title="قائمة الدخل"
      description="عرض الإيرادات والمصروفات وصافي الدخل"
      isLoading={isLoading}
      customKPIs={customKPIs}
      chartContent={chartContent}      onPrint={hideInternalControls ? undefined : (data ? handlePrint : undefined)}
    >
      {error ? (
        <div className="text-destructive text-sm">فشل في تحميل التقرير</div>
      ) : !data ? (
        <div className="text-muted-foreground text-sm p-8 text-center">اختر السنة لعرض قائمة الدخل</div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          <div className="border rounded-xl overflow-hidden">
            <div className="bg-green-50 p-3 font-medium text-green-800">الإيرادات</div>
            {renderLines(data.revenues)}
            <div className="flex justify-between p-3 bg-green-50/50 font-medium border-t">
              <span>إجمالي الإيرادات</span>
              <span className="font-mono">{formatCurrency(data.totalRevenue)}</span>
            </div>
          </div>

          <div className="border rounded-xl overflow-hidden">
            <div className="bg-red-50 p-3 font-medium text-red-800">المصروفات</div>
            {renderLines(data.expenses)}
            <div className="flex justify-between p-3 bg-red-50/50 font-medium border-t">
              <span>إجمالي المصروفات</span>
              <span className="font-mono">{formatCurrency(data.totalExpenses)}</span>
            </div>
          </div>

          <div className="lg:col-span-2">
            <div className={cn(
              "p-4 rounded-xl text-center",
              data.netIncome >= 0 ? "bg-green-50" : "bg-red-50"
            )}>
              <span className="text-sm text-muted-foreground">صافي الدخل</span>
              <p className={cn("text-2xl font-bold mt-1", data.netIncome >= 0 ? "text-green-700" : "text-red-700")}>
                {formatCurrency(data.netIncome)}
              </p>
              <p className="text-xs text-muted-foreground mt-1">
                من {new Date(data.fromDate).toLocaleDateString("ar-SA")} إلى {new Date(data.toDate).toLocaleDateString("ar-SA")}
              </p>
            </div>
          </div>
        </div>
      )}
    </AccountingReportLayout>
  );
}

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { AlertCircle, CheckCircle2, Plus, Trash2, Wrench } from "lucide-react";
import { useMemo, useState } from "react";
import { toast } from "sonner";

import { accountsApi, closingApi,fiscalYearsApi } from "@/api/accounting";
import { FixedAssetFormDialog } from "@/components/domain/assets/FixedAssetFormDialog";
import {
  Button,
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  Input,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Text,
} from "@/components/ui";
import { queryKeys } from "@/constants/queryKeys";
import { normalizeApiError } from "@/lib/errorUtils";
import type { ChartOfAccountDto, FiscalYearSummaryDto,InitialOpeningBalanceLineDto } from "@/types/accounting";

interface InitialOpeningBalanceDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function InitialOpeningBalanceDialog({ open, onOpenChange }: InitialOpeningBalanceDialogProps) {
  const queryClient = useQueryClient();
  const [fiscalYearID, setFiscalYearID] = useState<number | null>(null);
  const [asOfDate, setAsOfDate] = useState(new Date().toISOString().split("T")[0]);
  const [lines, setLines] = useState<InitialOpeningBalanceLineDto[]>([]);
  const [result, setResult] = useState<{ accountsCarriedForward: number } | null>(null);
  const [showAssetForm, setShowAssetForm] = useState(false);

  const { data: fiscalYears } = useQuery({
    queryKey: queryKeys.accounting.fiscalYears,
    queryFn: () => fiscalYearsApi.getAll(),
    enabled: open,
  });

  const { data: allAccounts } = useQuery({
    queryKey: queryKeys.accounting.accounts.postable,
    queryFn: () => accountsApi.getPostable(),
    enabled: open,
  });

  const addLine = () => {
    setLines([...lines, {
      accountID: 0,
      accountCode: "",
      accountName: "",
      accountNature: "Debit",
      balance: 0,
    }]);
  };

  const addLineByCategory = (categoryPrefix: string) => {
    // Find first postable account starting with the category prefix
    const account = allAccounts?.find((a: ChartOfAccountDto) => a.accountCode.startsWith(categoryPrefix) && a.isPostable);
    if (!account) {
      toast.error(`لا توجد حسابات متاحة في هذا التصنيف`);
      return;
    }
    setLines([...lines, {
      accountID: account.accountID,
      accountCode: account.accountCode,
      accountName: account.accountName,
      accountNature: account.accountNature,
      balance: 0,
    }]);
  };

  const removeLine = (index: number) => {
    setLines(lines.filter((_, i) => i !== index));
  };

  const updateLine = (index: number, field: keyof InitialOpeningBalanceLineDto, value: string | number) => {
    const updated = [...lines];
    if (field === "accountID") {
      const account = allAccounts?.find((a: ChartOfAccountDto) => a.accountID === Number(value));
      if (account) {
        updated[index] = {
          ...updated[index],
          accountID: account.accountID,
          accountCode: account.accountCode,
          accountName: account.accountName,
          accountNature: account.accountNature,
        };
      }
    } else if (field === "balance") {
      updated[index] = { ...updated[index], balance: Number(value) };
    }
    setLines(updated);
  };

  const { totalDebit, totalCredit, isBalanced } = useMemo(() => {
    let debit = 0;
    let credit = 0;
    for (const line of lines) {
      if (line.accountID === 0 || line.balance === 0) continue;
      if (line.accountNature === "Debit") {
        if (line.balance > 0) debit += line.balance;
        else credit += Math.abs(line.balance);
      } else {
        if (line.balance > 0) credit += line.balance;
        else debit += Math.abs(line.balance);
      }
    }
    return { totalDebit: debit, totalCredit: credit, isBalanced: Math.abs(debit - credit) < 0.01 };
  }, [lines]);

  const mutation = useMutation({
    mutationFn: () => closingApi.createInitialOpeningBalances({
      fiscalYearID: fiscalYearID!,
      asOfDate,
      description: "إثبات الأرصدة الافتتاحية الأولية",
      lines: lines.filter(l => l.accountID > 0 && l.balance !== 0),
    }),
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: queryKeys.accounting.all });
      setResult({ accountsCarriedForward: data.accountsCarriedForward });
      toast.success(`تم إدخال الأرصدة الافتتاحية: ${data.accountsCarriedForward} حساب`);
    },
    onError: (err: Error) => {
      const { message } = normalizeApiError(err);
      toast.error(message || "فشل في إدخال الأرصدة الافتتاحية");
    },
  });

  const reset = () => {
    setFiscalYearID(null);
    setAsOfDate(new Date().toISOString().split("T")[0]);
    setLines([]);
    setResult(null);
    onOpenChange(false);
  };

  const handleAssetCreated = (assetData: { assetAccountID: number; acquiredCost: number; assetName: string }) => {
    // Find the asset account to add to opening balance
    const account = allAccounts?.find((a: ChartOfAccountDto) => a.accountID === assetData.assetAccountID);
    if (account && assetData.acquiredCost > 0) {
      setLines([...lines, {
        accountID: account.accountID,
        accountCode: account.accountCode,
        accountName: `${account.accountName} - ${assetData.assetName}`,
        accountNature: account.accountNature,
        balance: assetData.acquiredCost,
      }]);
      toast.success(`تمت إضافة الأصل "${assetData.assetName}" بقيمة ${assetData.acquiredCost.toLocaleString()} إلى الأرصدة`);
    }
  };

  const usedAccountIds = new Set(lines.map(l => l.accountID).filter(id => id > 0));

  return (
    <Dialog open={open} onOpenChange={reset}>
      <DialogContent className="sm:max-w-[700px] max-h-[85vh] overflow-y-auto" dir="rtl">
        <DialogHeader>
          <DialogTitle>إدخال الأرصدة الافتتاحية الأولية</DialogTitle>
        </DialogHeader>

        {result ? (
          <div className="space-y-4 py-4">
            <div className="flex flex-col items-center gap-3">
              <div className="w-16 h-16 rounded-full bg-green-100 flex items-center justify-center">
                <CheckCircle2 className="w-8 h-8 text-green-600" />
              </div>
              <Text variant="body" className="font-medium">تم إدخال الأرصدة بنجاح</Text>
            </div>
            <div className="grid grid-cols-1 gap-3 bg-muted/30 p-4 rounded-xl">
              <div>
                <span className="text-xs text-muted-foreground">عدد الحسابات</span>
                <p className="font-medium">{result.accountsCarriedForward}</p>
              </div>
            </div>
            <DialogFooter>
              <Button variant="outline" onClick={reset}>إغلاق</Button>
            </DialogFooter>
          </div>
        ) : (
          <div className="space-y-4">
            {/* Year and Date */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div className="space-y-1.5">
                <label className="label-field">السنة المالية</label>
                <Select value={String(fiscalYearID ?? "")} onValueChange={(v) => setFiscalYearID(Number(v))}>
                  <SelectTrigger>
                    <SelectValue placeholder="اختر السنة" />
                  </SelectTrigger>
                  <SelectContent>
                    {fiscalYears?.filter((y: FiscalYearSummaryDto) => !y.isClosed).map((fy: FiscalYearSummaryDto) => (
                      <SelectItem key={fy.fiscalYearID} value={String(fy.fiscalYearID)}>
                        {fy.yearName}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1.5">
                <label className="label-field">التاريخ</label>
                <Input type="date" value={asOfDate} onChange={(e) => setAsOfDate(e.target.value)} />
              </div>
            </div>

            {/* Warning */}
            <div className="flex items-start gap-3 p-3 bg-amber-50 rounded-xl">
              <AlertCircle className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" />
              <div className="text-sm text-amber-800">
                <p className="font-medium">تنبيه</p>
                <p className="mt-1">يُستخدم هذا الإجراء فقط عند بدء تشغيل النظام لأول مرة. الأرصدة المُدخلة ستنشئ قيداً محاسبياً مرحلاً.</p>
              </div>
            </div>

            {/* Lines */}
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <label className="label-field">الحسابات وأرصدتها</label>
                <div className="flex gap-2">
                  <Button type="button" variant="outline" size="sm" onClick={() => setShowAssetForm(true)}>
                    <Wrench className="w-4 h-4 ml-1" /> إضافة أصل جديد
                  </Button>
                  <Button type="button" variant="outline" size="sm" onClick={() => addLineByCategory("13")}>
                    <Plus className="w-4 h-4 ml-1" /> مخزون
                  </Button>
                  <Button type="button" variant="outline" size="sm" onClick={addLine}>
                    <Plus className="w-4 h-4 ml-1" /> حساب آخر
                  </Button>
                </div>
              </div>

              {lines.length === 0 && (
                <div className="text-center py-8 text-muted-foreground text-sm">
                  لا توجد حسابات. اضغط "إضافة حساب" للبدء.
                </div>
              )}

              {lines.map((line, index) => (
                <div key={index} className="grid grid-cols-[1fr_120px_40px] gap-2 items-end p-2 bg-muted/30 rounded-lg">
                  <div className="space-y-1">
                    {index === 0 && <label className="label-field">الحساب</label>}
                    <Select
                      value={String(line.accountID || "")}
                      onValueChange={(v) => updateLine(index, "accountID", Number(v))}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="اختر الحساب" />
                      </SelectTrigger>
                      <SelectContent>
                        {allAccounts?.filter((a: ChartOfAccountDto) => !usedAccountIds.has(a.accountID) || a.accountID === line.accountID).map((acc: ChartOfAccountDto) => (
                          <SelectItem key={acc.accountID} value={String(acc.accountID)}>
                            {acc.accountCode} - {acc.accountName}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-1">
                    {index === 0 && <label className="label-field">الرصيد</label>}
                    <Input
                      type="number"
                      step="0.01"
                      placeholder="0"
                      value={line.balance || ""}
                      onChange={(e) => updateLine(index, "balance", parseFloat(e.target.value) || 0)}
                      className="font-mono"
                    />
                  </div>
                  <div className="space-y-1">
                    {index === 0 && <label className="label-field">&nbsp;</label>}
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon"
                      className="text-destructive"
                      onClick={() => removeLine(index)}
                    >
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </div>
                </div>
              ))}
            </div>

            {/* Summary */}
            {lines.length > 0 && (
              <div className={`flex items-center justify-between p-3 rounded-xl ${isBalanced ? "bg-green-50" : "bg-red-50"}`}>
                <div className="flex gap-4 text-sm">
                  <span>إجمالي المدين: <strong className="font-mono">{totalDebit.toLocaleString()}</strong></span>
                  <span>إجمالي الدائن: <strong className="font-mono">{totalCredit.toLocaleString()}</strong></span>
                </div>
                <span className={`text-sm font-medium ${isBalanced ? "text-green-600" : "text-red-600"}`}>
                  {isBalanced ? "متوازن" : "غير متوازن"}
                </span>
              </div>
            )}

            <DialogFooter className="gap-2">
              <Button variant="outline" onClick={reset}>إلغاء</Button>
              <Button
                onClick={() => mutation.mutate()}
                disabled={!fiscalYearID || lines.length === 0 || !isBalanced || mutation.isPending}
              >
                {mutation.isPending ? "جاري الترحيل..." : "ترحيل الأرصدة الافتتاحية"}
              </Button>
            </DialogFooter>
          </div>
        )}
      </DialogContent>
      <FixedAssetFormDialog
        open={showAssetForm}
        onOpenChange={setShowAssetForm}
        mode="create"
        skipJournalEntry
        onSuccess={(asset) => {
          if (asset) {
            handleAssetCreated({
              assetAccountID: asset.assetAccountID,
              acquiredCost: asset.acquiredCost,
              assetName: asset.assetName,
            });
          }
        }}
      />
    </Dialog>
  );
}

import { useQuery } from "@tanstack/react-query";
import { Pencil, PlusCircle, Trash2 } from "lucide-react";
import { useEffect, useMemo, useState } from "react";

import { accountsApi, fiscalYearsApi,journalEntriesApi, journalEntryTypesApi, periodsApi } from "@/api/accounting";
import {
  BaseFormDialog,
  Button,
  DateInput,
  FormField,
  FormSection,
  Input,
  NativeSelect,
  Text,
} from "@/components/ui";
import { queryKeys } from "@/constants/queryKeys";
import { useApiMutation } from "@/hooks";
import { formatCurrency } from "@/lib/utils";
import type { ChartOfAccountDto, CreateJournalEntryLineDto, FiscalPeriodDto, FiscalYearSummaryDto, JournalEntryTypeDto } from "@/types/accounting";

// ─── Types ────────────────────────────────────────
interface LineEntry {
  key: string;
  accountID: number;
  accountName: string;
  accountCode: string;
  debit: number;
  credit: number;
  description: string;
}

let lineKeyCounter = 0;
function newLineKey() {
  return `line_${++lineKeyCounter}`;
}

function createEmptyLine(): LineEntry {
  return { key: newLineKey(), accountID: 0, accountName: "", accountCode: "", debit: 0, credit: 0, description: "" };
}

// ─── Component ────────────────────────────────────
interface JournalEntryFormDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function JournalEntryFormDialog({ open, onOpenChange }: JournalEntryFormDialogProps) {
  // ─── State (lines must be state — dynamic rows) ──
  const [entryDate, setEntryDate] = useState(new Date().toISOString().split("T")[0]);
  const [fiscalYearID, setFiscalYearID] = useState<number | null>(null);
  const [periodID, setPeriodID] = useState<number>(0);
  const [journalEntryTypeID, setJournalEntryTypeID] = useState<number>(0);
  const [description, setDescription] = useState("");
  const [lines, setLines] = useState<LineEntry[]>([createEmptyLine(), createEmptyLine()]);

  // ─── Queries ─────────────────────────────────────
  const { data: fiscalYears } = useQuery({
    queryKey: queryKeys.accounting.fiscalYears,
    queryFn: () => fiscalYearsApi.getAll(),
    enabled: open,
  });

  const { data: periods } = useQuery({
    queryKey: queryKeys.accounting.periods.byYear(fiscalYearID!),
    queryFn: () => periodsApi.getAll(fiscalYearID!),
    enabled: open && fiscalYearID != null,
  });

  const { data: activePeriod } = useQuery({
    queryKey: queryKeys.accounting.periods.active(fiscalYearID!),
    queryFn: () => periodsApi.getActive(fiscalYearID!),
    enabled: open && fiscalYearID != null,
  });

  const { data: postableAccounts } = useQuery({
    queryKey: queryKeys.accounting.accounts.postable,
    queryFn: () => accountsApi.getPostable(),
    enabled: open,
  });

  const { data: journalEntryTypes } = useQuery({
    queryKey: queryKeys.accounting.journalEntryTypes,
    queryFn: () => journalEntryTypesApi.getAll(),
    enabled: open,
  });

  // ─── Reset on open ───────────────────────────────
  useEffect(() => {
    if (open) {
      const today = new Date().toISOString().split("T")[0];
      setEntryDate(today);
      setPeriodID(0);
      setFiscalYearID(null);
      setJournalEntryTypeID(0);
      setDescription("");
      setLines([createEmptyLine(), createEmptyLine()]);
    }
  }, [open]);

  // ─── Auto-match fiscal year & period from date ───
  useEffect(() => {
    if (!open || !entryDate || !fiscalYears || fiscalYears.length === 0) return;

    const date = new Date(entryDate);

    // 1) Find the fiscal year that contains this date
    const matchedYear = fiscalYears.find(
      (y: FiscalYearSummaryDto) => date >= new Date(y.startDate) && date <= new Date(y.endDate)
    );

    if (matchedYear && matchedYear.fiscalYearID !== fiscalYearID) {
      setFiscalYearID(matchedYear.fiscalYearID);
      setPeriodID(0); // reset period so the next effect picks it
      return; // wait for periods to load before matching period
    }

    // 2) Find the period that contains this date
    if (matchedYear && periods && periods.length > 0 && periodID === 0) {
      const matchedPeriod = periods.find(
        (p: FiscalPeriodDto) => date >= new Date(p.startDate) && date <= new Date(p.endDate)
      );
      if (matchedPeriod) {
        setPeriodID(matchedPeriod.periodID);
      } else {
        // Date falls inside the year but outside all periods — pick active or first
        setPeriodID(activePeriod?.periodID ?? periods[0].periodID);
      }
    }
  }, [open, entryDate, fiscalYears, periods, activePeriod, fiscalYearID, periodID]);

  // ─── Account options ─────────────────────────────
  const accountOptions = useMemo(
    () => postableAccounts?.map((a: ChartOfAccountDto) => ({ value: String(a.accountID), label: `${a.accountCode} - ${a.accountName}` })) || [],
    [postableAccounts]
  );

  const periodOptions = useMemo(
    () => periods?.map((p: FiscalPeriodDto) => ({ value: String(p.periodID), label: p.periodName })) || [],
    [periods]
  );

  const journalEntryTypeOptions = useMemo(
    () => journalEntryTypes?.map((t: JournalEntryTypeDto) => ({ value: String(t.journalEntryTypeID), label: `${t.code} - ${t.typeName}` })) || [],
    [journalEntryTypes]
  );

  // ─── Computed ────────────────────────────────────
  const totalDebit = lines.reduce((s, l) => s + (l.debit || 0), 0);
  const totalCredit = lines.reduce((s, l) => s + (l.credit || 0), 0);
  const isBalanced = Math.abs(totalDebit - totalCredit) < 0.01;

  // ─── Line operations ─────────────────────────────
  const addLine = () => setLines([...lines, createEmptyLine()]);

  const removeLine = (key: string) => {
    if (lines.length <= 2) return;
    setLines(lines.filter((l) => l.key !== key));
  };

  const updateLine = (key: string, field: keyof LineEntry, value: unknown) => {
    setLines(
      lines.map((l) => {
        if (l.key !== key) return l;
        const updated = { ...l, [field]: value };
        if (field === "debit" && Number(value) > 0) updated.credit = 0;
        if (field === "credit" && Number(value) > 0) updated.debit = 0;
        return updated;
      })
    );
  };

  const selectAccount = (key: string, accountID: string) => {
    const id = Number(accountID);
    const acc = postableAccounts?.find((a: ChartOfAccountDto) => a.accountID === id);
    setLines(
      lines.map((l) =>
        l.key === key ? { ...l, accountID: id, accountName: acc?.accountName ?? "", accountCode: acc?.accountCode ?? "" } : l
      )
    );
  };

  // ─── Mutation ────────────────────────────────────
  const mutation = useApiMutation(
    async () => {
      const linesDto: CreateJournalEntryLineDto[] = lines.map((l) => ({
        accountID: l.accountID,
        debit: l.debit || 0,
        credit: l.credit || 0,
        description: l.description || null,
      }));
      return journalEntriesApi.create({
        entryDate,
        periodID: periodID!,
        journalEntryTypeID,
        description,
        lines: linesDto,
      });
    },
    {
      successMessage: "تم إنشاء القيد اليومي بنجاح",
      errorTitle: "خطأ في إنشاء القيد",
      invalidateKeys: [["journal-entries"]],
      onSuccess: () => {
        onOpenChange(false);
      },
    }
  );

  return (
    <BaseFormDialog
      open={open}
      onOpenChange={onOpenChange}
      title="إضافة قيد يومي يدوي"
      description="إنشاء قيد يومي جديد ببنود متعددة"
      size="2xl"
      isLoading={mutation.isPending}
      isDirty={!!description.trim() || lines.some((l) => l.accountID > 0)}
      onSubmit={() => mutation.mutate(undefined as void)}
      resetOnOpen
      submitLabel="حفظ القيد"
      submitIcon={<Pencil className="w-4 h-4" />}
    >
      <div className="space-y-4">
        {/* ─── Header fields ─── */}
        <FormSection title="بيانات القيد" icon={Pencil}>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <FormField label="تاريخ القيد" required>
              <DateInput value={entryDate} onChange={(val) => setEntryDate(val || "")} />
            </FormField>

            <FormField label="السنة المالية" required>
              <NativeSelect
                value={fiscalYearID || ""}
                onChange={(val) => {
                  setFiscalYearID(val ? Number(val) : null);
                  setPeriodID(0);
                }}
                options={fiscalYears?.map((y: FiscalYearSummaryDto) => ({ value: String(y.fiscalYearID), label: y.yearName })) || []}
                placeholder="اختر السنة"
              />
            </FormField>

            <FormField label="الفترة المحاسبية" required>
              <NativeSelect
                value={periodID || ""}
                onChange={(val) => setPeriodID(val ? Number(val) : 0)}
                options={periodOptions}
                placeholder="اختر الفترة"
              />
            </FormField>

            <FormField label="نوع القيد" required>
              <NativeSelect
                value={journalEntryTypeID || ""}
                onChange={(val) => setJournalEntryTypeID(val ? Number(val) : 0)}
                options={journalEntryTypeOptions}
                placeholder="اختر نوع القيد"
              />
            </FormField>
          </div>

          <FormField label="بيان القيد" required>
            <Input
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="شرح سبب القيد..."
            />
          </FormField>
        </FormSection>

        {/* ─── Lines table ─── */}
        <FormSection
          title="بنود القيد"
          icon={null}
          badge={lines.length}
        >
          <div className="flex justify-end mb-3">
            <Button
              type="button"
              variant="link"
              size="sm"
              className="h-auto p-0 gap-1"
              onClick={addLine}
            >
              <PlusCircle className="w-3.5 h-3.5" />
              إضافة بند
            </Button>
          </div>

          <div className="border rounded-xl overflow-hidden">
            <table className="w-full text-sm" role="table" aria-label="إدخال القيود اليومية">
              <thead className="bg-muted/50 sticky top-0 z-10">
                <tr>
                  <th className="text-end p-2 w-8">#</th>
                  <th className="text-end p-2">الحساب</th>
                  <th className="text-end p-2">البيان</th>
                  <th className="text-start p-2 w-28">مدين</th>
                  <th className="text-start p-2 w-28">دائن</th>
                  <th className="p-2 w-8"></th>
                </tr>
              </thead>
              <tbody>
                {lines.map((line, idx) => (
                  <tr key={line.key} className="border-t border-border">
                    <td className="p-1.5 text-xs text-muted-foreground text-center">{idx + 1}</td>
                    <td className="p-1.5">
                      <NativeSelect
                        value={line.accountID || ""}
                        onChange={(val) => selectAccount(line.key, val)}
                        options={accountOptions}
                        placeholder="اختر حساب"
                        className="h-9 text-xs"
                      />
                    </td>
                    <td className="p-1.5">
                      <Input
                        className="h-9 text-xs"
                        placeholder="بيان (اختياري)"
                        value={line.description}
                        onChange={(e) => updateLine(line.key, "description", e.target.value)}
                      />
                    </td>
                    <td className="p-1.5">
                      <Input
                        type="number"
                        className="h-9 text-xs text-left font-mono ltr"
                        dir="ltr"
                        placeholder="0.00"
                        value={line.debit || ""}
                        onChange={(e) => updateLine(line.key, "debit", Number(e.target.value))}
                      />
                    </td>
                    <td className="p-1.5">
                      <Input
                        type="number"
                        className="h-9 text-xs text-left font-mono ltr"
                        dir="ltr"
                        placeholder="0.00"
                        value={line.credit || ""}
                        onChange={(e) => updateLine(line.key, "credit", Number(e.target.value))}
                      />
                    </td>
                    <td className="p-1.5">
                      {lines.length > 2 && (
                        <Button
                          type="button"
                          variant="ghost"
                          size="icon"
                          className="h-7 w-7 text-destructive hover:bg-destructive/10"
                          onClick={() => removeLine(line.key)}
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </Button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
              <tfoot className="bg-muted/30 font-medium">
                <tr>
                  <td colSpan={3} className="p-2 text-start">الإجمالي</td>
                  <td className="p-2 text-start font-mono">{formatCurrency(totalDebit)}</td>
                  <td className="p-2 text-start font-mono">{formatCurrency(totalCredit)}</td>
                  <td></td>
                </tr>
              </tfoot>
            </table>
          </div>

          {!isBalanced && lines.length >= 2 && (
            <Text variant="body-sm" className="text-destructive mt-2">
              غير متوازن — إجمالي المدين ({formatCurrency(totalDebit)}) لا يساوي إجمالي الدائن ({formatCurrency(totalCredit)})
            </Text>
          )}
        </FormSection>
      </div>
    </BaseFormDialog>
  );
}

﻿import { useQuery } from "@tanstack/react-query";
import { useCallback,useEffect, useState } from "react";

import { reportsApi } from "@/api/accounting";
import { AccountingReportLayout } from "@/components/common/AccountingReportLayout";
import { ReportBarChart } from "@/components/common/charts";
import { ReportFilters } from "@/components/common/ReportFilters";
import { Badge } from "@/components/ui";
import { JOURNAL_STATUS } from "@/constants";
import { chartColors } from "@/lib/chartColors";
import { formatCurrency } from "@/lib/utils";
import type { JournalRegisterItemDto } from "@/types/accounting";

interface JournalRegisterReportProps {
  fiscalYearId?: number;
  fromDate?: string;
  toDate?: string;
  hideInternalControls?: boolean;
}

const statusBadge: Record<string, { label: string; variant: "warning" | "success" | "destructive" | "outline" }> = {
  [JOURNAL_STATUS.DRAFT]: { label: "مسودة", variant: "warning" },
  [JOURNAL_STATUS.POSTED]: { label: "مرحّل", variant: "success" },
  [JOURNAL_STATUS.REVERSED]: { label: "ملغي", variant: "destructive" },
};

export function JournalRegisterReport({ fiscalYearId, fromDate: propFromDate, toDate: propToDate, hideInternalControls }: JournalRegisterReportProps) {
  const today = new Date();
  const firstDay = new Date(today.getFullYear(), today.getMonth(), 1);
  const [filters, setFilters] = useState<Record<string, any>>({
    fromDate: propFromDate || firstDay.toISOString().split("T")[0],
    toDate: propToDate || today.toISOString().split("T")[0],
  });

  useEffect(() => {
    if (propFromDate) setFilters(prev => ({ ...prev, fromDate: propFromDate }));
    if (propToDate) setFilters(prev => ({ ...prev, toDate: propToDate }));
  }, [propFromDate, propToDate]);

  const { data, isLoading, error, refetch } = useQuery({
    queryKey: ["reports", "journal-register", fiscalYearId, filters.fromDate, filters.toDate],
    queryFn: () => reportsApi.journalRegister({ fiscalYearId, fromDate: filters.fromDate, toDate: filters.toDate }),
    enabled: !!filters.fromDate && !!filters.toDate,
  });

  const handleFilterChange = useCallback((key: string, value: any) => {
    setFilters(prev => ({ ...prev, [key]: value }));
  }, []);

  const handlePrint = useCallback(() => {
    const params = new URLSearchParams();
    if (fiscalYearId) params.set("fiscalYearId", String(fiscalYearId));
    if (filters.fromDate) params.set("fromDate", filters.fromDate);
    if (filters.toDate) params.set("toDate", filters.toDate);
    window.open(`/reports/journal-register/print?${params.toString()}`, "_blank");
  }, [fiscalYearId, filters]);


  const chartContent = data ? (
    <ReportBarChart
      data={[
        { name: 'القيود', value: data.totalEntries },
        { name: 'المدين', value: data.grandTotalDebit },
        { name: 'الدائن', value: data.grandTotalCredit },
      ]}
      xKey="name"
      yKeys={[{ key: 'value', color: chartColors.primary, label: 'المبلغ' }]}
      title="ملخص سجل اليومية"
      height={250}
    />
  ) : undefined;

  const customKPIs = data ? [
    { label: 'عدد القيود', value: data.totalEntries, color: 'default' },
    { label: 'إجمالي المدين', value: formatCurrency(data.grandTotalDebit), color: 'info' },
    { label: 'إجمالي الدائن', value: formatCurrency(data.grandTotalCredit), color: 'success' },
  ] : [];

  const filterBar = hideInternalControls ? undefined : (
    <ReportFilters
      filters={['fromDate', 'toDate']}
      values={filters}
      onChange={handleFilterChange}
      onApply={() => refetch()}
      showApplyButton={false}
    />
  );

  return (
    <AccountingReportLayout
      title="سجل اليومية"
      description="عرض القيود اليومية المحاسبية"
      isLoading={isLoading}
      customKPIs={customKPIs}
      filterBar={filterBar}
      chartContent={chartContent}
      onPrint={hideInternalControls ? undefined : (data ? handlePrint : undefined)}    >
      {error ? (
        <div className="text-destructive text-sm">فشل في تحميل سجل اليومية</div>
      ) : !data ? (
        <div className="text-muted-foreground text-sm p-8 text-center">اختر التاريخ لعرض سجل اليومية</div>
      ) : (
        <div className="border rounded-xl overflow-hidden">
          <table className="w-full text-sm" role="table" aria-label="سجل القيود اليومية">
            <thead className="bg-muted/50 sticky top-0 z-10">
              <tr>
                <th className="text-end p-2">التاريخ</th>
                <th className="text-end p-2">رقم القيد</th>
                <th className="text-end p-2">البيان</th>
                <th className="text-end p-2">المصدر</th>
                <th className="text-end p-2">الحالة</th>
                <th className="text-end p-2">بواسطة</th>
                <th className="text-start p-2 w-28">مدين</th>
                <th className="text-start p-2 w-28">دائن</th>
              </tr>
            </thead>
            <tbody>
              {data.entries.map((entry: JournalRegisterItemDto) => (
                <tr key={entry.journalEntryID} className="border-t border-border hover:bg-muted/20">
                  <td className="p-2 text-xs">{new Date(entry.entryDate).toLocaleDateString("ar-SA")}</td>
                  <td className="p-2 font-mono text-xs ltr" dir="ltr">{entry.entryNumber}</td>
                  <td className="p-2 text-xs max-w-[200px] truncate">{entry.description}</td>
                  <td className="p-2 text-xs">{entry.sourceModule === "Manual" ? "يدوي" : entry.sourceModule}</td>
                  <td className="p-2">
                    <Badge variant={statusBadge[entry.status]?.variant ?? "outline"}>
                      {statusBadge[entry.status]?.label ?? entry.status}
                    </Badge>
                  </td>
                  <td className="p-2 text-xs">{entry.createdByUserName}</td>
                  <td className="p-2 text-start font-mono text-xs">{formatCurrency(entry.totalDebit)}</td>
                  <td className="p-2 text-start font-mono text-xs">{formatCurrency(entry.totalCredit)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </AccountingReportLayout>
  );
}

﻿import { useQuery } from "@tanstack/react-query";
import { useCallback, useMemo,useState } from "react";

import { reportsApi } from "@/api/accounting";
import { AccountingReportLayout } from "@/components/common/AccountingReportLayout";
import { ReportBarChart,ReportPieChart } from "@/components/common/charts";
import { ReportFilters } from "@/components/common/ReportFilters";
import { Card, Heading, Text } from "@/components/ui";
import { chartColors } from "@/lib/chartColors";
import { formatCurrency } from "@/lib/utils";
import type { BalanceSheetSectionDto } from "@/types/accounting";

interface LiabilitiesReportProps {
  fiscalYearId?: number;
  asOfDate?: string;
  externalFilters?: { toDate?: string };
  hideInternalControls?: boolean;
}

export function LiabilitiesReport({ fiscalYearId, asOfDate: propAsOfDate, externalFilters, hideInternalControls }: LiabilitiesReportProps) {
  const [internalFilters, setInternalFilters] = useState<Record<string, any>>({
    toDate: propAsOfDate || new Date().toISOString().split("T")[0],
  });

  const filters = {
    ...internalFilters,
    ...(externalFilters?.toDate !== undefined ? { toDate: externalFilters.toDate } : {}),
  };

  const { data, isLoading, error, refetch } = useQuery({
    queryKey: ["reports", "balance-sheet", filters.toDate, fiscalYearId],
    queryFn: () => reportsApi.balanceSheet(filters.toDate!, fiscalYearId),
    enabled: !!filters.toDate,
  });

  const handleFilterChange = useCallback((key: string, value: any) => {
    setInternalFilters(prev => ({ ...prev, [key]: value }));
  }, []);

  const handlePrint = useCallback(() => {
    const params = new URLSearchParams();
    if (fiscalYearId) params.set("fiscalYearId", String(fiscalYearId));
    if (filters.toDate) params.set("date", filters.toDate);
    window.open(`/reports/liabilities/print?${params.toString()}`, "_blank");
  }, [fiscalYearId, filters.toDate]);

  const classified = useMemo(() => {
    if (!data) return null;
    const liabilities = data.liabilities || [];
    const currentLiabilities = liabilities.filter((l: BalanceSheetSectionDto) => {
      const code = l.accountCode || "";
      return code.startsWith("21") || code.startsWith("22");
    });
    const nonCurrentLiabilities = liabilities.filter((l: BalanceSheetSectionDto) => {
      const code = l.accountCode || "";
      return code.startsWith("23") || code.startsWith("24") || code.startsWith("25");
    });
    const otherLiabilities = liabilities.filter((l: BalanceSheetSectionDto) => {
      const code = l.accountCode || "";
      return !code.startsWith("21") && !code.startsWith("22") && !code.startsWith("23") && !code.startsWith("24") && !code.startsWith("25");
    });
    return {
      currentLiabilities,
      nonCurrentLiabilities,
      otherLiabilities,
      totalCurrent: currentLiabilities.reduce((s: number, l: BalanceSheetSectionDto) => s + l.balance, 0),
      totalNonCurrent: nonCurrentLiabilities.reduce((s: number, l: BalanceSheetSectionDto) => s + l.balance, 0),
      totalOther: otherLiabilities.reduce((s: number, l: BalanceSheetSectionDto) => s + l.balance, 0),
      totalLiabilities: data.totalLiabilities,
    };
  }, [data]);

  const customKPIs = classified ? [
    { label: 'الالتزامات قصيرة الأجل', value: formatCurrency(classified.totalCurrent), color: 'warning' },
    { label: 'الالتزامات طويلة الأجل', value: formatCurrency(classified.totalNonCurrent), color: 'warning' },
    { label: 'التزامات أخرى', value: formatCurrency(classified.totalOther), color: 'default' },
    { label: 'إجمالي الديون', value: formatCurrency(classified.totalLiabilities), color: 'danger' },
  ] : [];

  const chartContent = classified ? (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      <ReportPieChart
        data={[
          { name: 'قصيرة الأجل', value: classified.totalCurrent },
          { name: 'طويلة الأجل', value: classified.totalNonCurrent },
          { name: 'أخرى', value: classified.totalOther },
        ].filter(d => d.value > 0)}
        nameKey="name"
        valueKey="value"
        title="توزيع الديون حسب الأجل"
        height={280}
      />
      <ReportBarChart
        data={[
          { name: 'قصيرة الأجل', value: classified.totalCurrent },
          { name: 'طويلة الأجل', value: classified.totalNonCurrent },
          { name: 'أخرى', value: classified.totalOther },
        ]}
        xKey="name"
        yKeys={[{ key: 'value', color: chartColors.warning, label: 'المبلغ' }]}
        title="مقارنة الديون"
        height={280}
      />
    </div>
  ) : undefined;

  const filterBar = hideInternalControls ? undefined : (
    <ReportFilters
      filters={['toDate']}
      values={filters}
      onChange={handleFilterChange}
      onApply={() => refetch()}
      showApplyButton={false}
    />
  );

  return (
    <AccountingReportLayout
      title="الديون والالتزامات"
      description="عرض الديون والالتزامات حسب الأجل"
      isLoading={isLoading}
      customKPIs={customKPIs}
      filterBar={filterBar}
      chartContent={chartContent}
      onPrint={hideInternalControls ? undefined : (classified ? handlePrint : undefined)}
    >
      {error ? (
        <div className="text-destructive text-sm">فشل في تحميل التقرير</div>
      ) : !classified ? (
        <div className="text-muted-foreground text-sm p-8 text-center">اختر تاريخاً لعرض الديون والالتزامات</div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          <Card className="border-none rounded-3xl overflow-hidden">
            <div className="p-4 bg-amber-50">
               <Heading level="h3" className="font-bold text-lg text-amber-800">الالتزامات قصيرة الأجل (أقل من سنة)</Heading>
              <p className="text-sm text-amber-600 mt-1">الإجمالي: {formatCurrency(classified.totalCurrent)}</p>
            </div>
            <div className="p-4 max-h-64 overflow-y-auto">
              {classified.currentLiabilities.length === 0 ? (
                <Text variant="description" className="text-center">لا توجد التزامات قصيرة الأجل</Text>
              ) : (
                <div className="space-y-2">
                  {classified.currentLiabilities.map((item: BalanceSheetSectionDto) => (
                    <div key={item.accountID} className="flex items-center justify-between py-2 border-b border-border last:border-0">
                      <div>
                        <span className="text-xs font-mono text-muted-foreground">{item.accountCode}</span>
                        <span className="text-sm mr-2">{item.accountName}</span>
                      </div>
                      <span className="text-sm font-medium">{formatCurrency(item.balance)}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </Card>

          <Card className="border-none rounded-3xl overflow-hidden">
            <div className="p-4 bg-orange-50">
               <Heading level="h3" className="font-bold text-lg text-orange-800">الالتزامات طويلة الأجل (أكثر من سنة)</Heading>
              <p className="text-sm text-orange-600 mt-1">الإجمالي: {formatCurrency(classified.totalNonCurrent)}</p>
            </div>
            <div className="p-4 max-h-64 overflow-y-auto">
              {classified.nonCurrentLiabilities.length === 0 ? (
                <Text variant="description" className="text-center">لا توجد التزامات طويلة الأجل</Text>
              ) : (
                <div className="space-y-2">
                  {classified.nonCurrentLiabilities.map((item: BalanceSheetSectionDto) => (
                    <div key={item.accountID} className="flex items-center justify-between py-2 border-b border-border last:border-0">
                      <div>
                        <span className="text-xs font-mono text-muted-foreground">{item.accountCode}</span>
                        <span className="text-sm mr-2">{item.accountName}</span>
                      </div>
                      <span className="text-sm font-medium">{formatCurrency(item.balance)}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </Card>

          {classified.otherLiabilities.length > 0 && (
            <Card className="lg:col-span-2 border-none rounded-3xl overflow-hidden">
              <div className="p-4 bg-muted/30">
                <Heading level="h3" className="font-bold text-lg">التزامات أخرى</Heading>
                <p className="text-sm text-muted-foreground mt-1">الإجمالي: {formatCurrency(classified.totalOther)}</p>
              </div>
              <div className="p-4">
                <div className="space-y-2">
                  {classified.otherLiabilities.map((item: BalanceSheetSectionDto) => (
                    <div key={item.accountID} className="flex items-center justify-between py-2 border-b border-border last:border-0">
                      <div>
                        <span className="text-xs font-mono text-muted-foreground">{item.accountCode}</span>
                        <span className="text-sm mr-2">{item.accountName}</span>
                      </div>
                      <span className="text-sm font-medium">{formatCurrency(item.balance)}</span>
                    </div>
                  ))}
                </div>
              </div>
            </Card>
          )}
        </div>
      )}
    </AccountingReportLayout>
  );
}

﻿import { useQuery } from "@tanstack/react-query";
import { useCallback, useMemo,useState } from "react";

import { reportsApi } from "@/api/accounting";
import { AccountingReportLayout } from "@/components/common/AccountingReportLayout";
import { ReportBarChart,ReportPieChart } from "@/components/common/charts";
import { ReportFilters } from "@/components/common/ReportFilters";
