﻿import { useQuery } from "@tanstack/react-query";
import { useCallback,useEffect, useState } from "react";

import { fiscalYearsApi, quartersApi,reportsApi } from "@/api/accounting";
import { AccountingReportLayout } from "@/components/common/AccountingReportLayout";
import { ReportBarChart, ReportPieChart } from "@/components/common/charts";
import { Card } from "@/components/ui/Card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/Select";
import { chartColors } from "@/lib/chartColors";
import { formatCurrency } from "@/lib/utils";
import { cn } from "@/lib/utils";
import type { FiscalYearSummaryDto, QuarterDto } from "@/types/accounting";

interface QuarterlyReportProps {
  fiscalYearId?: number;
  externalFilters?: { quarterId?: number };
  hideInternalControls?: boolean;
}

export function QuarterlyReport({ fiscalYearId, externalFilters, hideInternalControls }: QuarterlyReportProps) {
  const { data: fiscalYears } = useQuery({
    queryKey: ["fiscal-years"],
    queryFn: () => fiscalYearsApi.getAll(),
  });

  const [selectedYearId, setSelectedYearId] = useState<number | undefined>(fiscalYearId);
  const [selectedQuarterId, setSelectedQuarterId] = useState<number | undefined>();

  const { data: quarters } = useQuery({
    queryKey: ["quarters", selectedYearId],
    queryFn: () => quartersApi.getAll(selectedYearId!),
    enabled: !!selectedYearId,
  });

  useEffect(() => {
    if (fiscalYearId) {
      setSelectedYearId(fiscalYearId);
    } else if (fiscalYears && fiscalYears.length > 0 && !selectedYearId) {
      const currentYear = new Date().getFullYear();
      const match = fiscalYears.find((y: FiscalYearSummaryDto) => y.yearName === String(currentYear));
      setSelectedYearId(match?.fiscalYearID ?? fiscalYears[fiscalYears.length - 1].fiscalYearID);
    }
  }, [fiscalYears, fiscalYearId]);

  useEffect(() => {
    if (externalFilters?.quarterId && quarters) {
      const match = quarters.find((q: QuarterDto) => q.quarterID === externalFilters.quarterId);
      if (match) setSelectedQuarterId(match.quarterID);
    } else if (quarters && quarters.length > 0 && !selectedQuarterId) {
      const openQ = quarters.find((q: QuarterDto) => !q.isClosed);
      setSelectedQuarterId(openQ?.quarterID ?? quarters[quarters.length - 1].quarterID);
    }
  }, [externalFilters?.quarterId, quarters, selectedQuarterId]);

  const selectedQuarter = quarters?.find((q: QuarterDto) => q.quarterID === selectedQuarterId);

  const { data, isLoading, error } = useQuery({
    queryKey: ["reports", "income-statement", selectedYearId, selectedQuarterId],
    queryFn: () => reportsApi.incomeStatement(selectedYearId!, selectedQuarterId),
    enabled: !!selectedYearId && !!selectedQuarterId,
  });

  const handlePrint = useCallback(() => {
    const params = new URLSearchParams();
    if (selectedYearId) params.set("fiscalYearId", String(selectedYearId));
    if (selectedQuarterId) params.set("quarterId", String(selectedQuarterId));
    window.open(`/reports/quarterly/print?${params.toString()}`, "_blank");
  }, [selectedYearId, selectedQuarterId]);


  const customKPIs = data ? [
    { label: 'إجمالي الإيرادات', value: formatCurrency(data.totalRevenue), color: 'success' },
    { label: 'إجمالي المصروفات', value: formatCurrency(data.totalExpenses), color: 'danger' },
    { label: 'صافي الدخل الفصلي', value: formatCurrency(data.netIncome), color: data.netIncome >= 0 ? 'text-green-600' : 'text-red-600' },
    { label: 'الفصل', value: selectedQuarter?.quarterName || '', color: 'primary' },
  ] : [];

  const chartContent = data ? (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      <ReportBarChart
        data={[
          { name: 'الإيرادات', value: data.totalRevenue },
          { name: 'المصروفات', value: data.totalExpenses },
          { name: 'صافي الدخل', value: data.netIncome },
        ]}
        xKey="name"
        yKeys={[{ key: 'value', color: chartColors.primary, label: 'المبلغ' }]}
        title="ملخص الفصل المالي"
        height={280}
      />
      <ReportPieChart
        data={[
          { name: 'الإيرادات', value: data.totalRevenue },
          { name: 'المصروفات', value: data.totalExpenses },
        ]}
        nameKey="name"
        valueKey="value"
        title="نسبة الإيرادات والمصروفات"
        height={280}
      />
    </div>
  ) : undefined;

  const filterBar = hideInternalControls ? undefined : (
    <Card className="p-4 flex flex-wrap gap-4 items-end mb-6">
      <div className="w-full sm:w-48">
        <label className="label-filter">السنة المالية</label>
        <Select
          value={selectedYearId != null ? String(selectedYearId) : undefined}
          onValueChange={(v) => {
            setSelectedYearId(Number(v));
            setSelectedQuarterId(undefined);
          }}
        >
          <SelectTrigger className="h-10">
            <SelectValue placeholder="اختر السنة" />
          </SelectTrigger>
          <SelectContent>
            {fiscalYears?.map((y: FiscalYearSummaryDto) => (
              <SelectItem key={y.fiscalYearID} value={String(y.fiscalYearID)}>
                {y.yearName} {y.isClosed ? "(مغلقة)" : ""}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
      <div className="w-full sm:w-48">
        <label className="label-filter">الفصل المالي</label>
        <Select
          value={selectedQuarterId != null ? String(selectedQuarterId) : undefined}
          onValueChange={(v) => setSelectedQuarterId(Number(v))}
        >
          <SelectTrigger className="h-10">
            <SelectValue placeholder="اختر الفصل" />
          </SelectTrigger>
          <SelectContent>
            {quarters?.map((q: QuarterDto) => (
              <SelectItem key={q.quarterID} value={String(q.quarterID)}>
                {q.quarterName} {q.isClosed ? "(مغلق)" : ""}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
    </Card>
  );

  const renderLines = (lines: { accountCode: string; accountName: string; amount: number; accountLevel: number }[]) => {
    return lines.map((line, i) => (
      <div key={i} className={cn(
        "flex justify-between px-3 py-1.5 border-t border-border text-sm",
        line.accountLevel <= 1 && "font-medium bg-muted/20",
        line.accountLevel === 2 && "pr-6",
        line.accountLevel >= 3 && "pr-10 text-xs"
      )}>
        <span>{line.accountName}</span>
        <span className="font-mono">{formatCurrency(line.amount)}</span>
      </div>
    ));
  };

  return (
    <AccountingReportLayout
      title="التقرير الفصلي"
      description="عرض الإيرادات والمصروفات الفصلية"
      isLoading={isLoading}
      customKPIs={customKPIs}
      filterBar={filterBar}
      chartContent={chartContent}
      onPrint={hideInternalControls ? undefined : (data ? handlePrint : undefined)}    >
      {selectedQuarter && (
        <div className="bg-blue-50 border border-blue-200 text-blue-800 px-4 py-2 rounded-xl text-sm flex justify-between mb-4">
          <span>
            <strong>{selectedQuarter.quarterName}</strong> — {selectedQuarter.periods.length} فترات
          </span>
          <span>
            من {new Date(selectedQuarter.startDate).toLocaleDateString("ar-SA")} إلى{" "}
            {new Date(selectedQuarter.endDate).toLocaleDateString("ar-SA")}
          </span>
        </div>
      )}

      {error ? (
        <div className="text-destructive text-sm">فشل في تحميل التقرير</div>
      ) : !data || !selectedQuarter ? (
        <div className="text-muted-foreground text-sm p-8 text-center">اختر الفصل لعرض التقرير الفصلي</div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          <div className="border rounded-xl overflow-hidden">
            <div className="bg-green-50 p-3 font-medium text-green-800">الإيرادات — {selectedQuarter.quarterName}</div>
            {renderLines(data.revenues)}
            <div className="flex justify-between p-3 bg-green-50/50 font-medium border-t">
              <span>إجمالي الإيرادات</span>
              <span className="font-mono">{formatCurrency(data.totalRevenue)}</span>
            </div>
          </div>

          <div className="border rounded-xl overflow-hidden">
            <div className="bg-red-50 p-3 font-medium text-red-800">المصروفات — {selectedQuarter.quarterName}</div>
            {renderLines(data.expenses)}
            <div className="flex justify-between p-3 bg-red-50/50 font-medium border-t">
              <span>إجمالي المصروفات</span>
              <span className="font-mono">{formatCurrency(data.totalExpenses)}</span>
            </div>
          </div>

          <div className="lg:col-span-2">
            <div className={cn("p-4 rounded-xl text-center", data.netIncome >= 0 ? "bg-green-50" : "bg-red-50")}>
              <span className="text-sm text-muted-foreground">صافي الدخل الفصلي</span>
              <p className={cn("text-2xl font-bold mt-1", data.netIncome >= 0 ? "text-green-700" : "text-red-700")}>
                {formatCurrency(data.netIncome)}
              </p>
              <p className="text-xs text-muted-foreground mt-1">
                من {new Date(selectedQuarter.startDate).toLocaleDateString("ar-SA")} إلى{" "}
                {new Date(selectedQuarter.endDate).toLocaleDateString("ar-SA")}
              </p>
            </div>
          </div>
        </div>
      )}
    </AccountingReportLayout>
  );
}

﻿import { useQuery } from "@tanstack/react-query";
import { useCallback,useEffect, useState } from "react";

import { accountsApi, reportsApi } from "@/api/accounting";
import { AccountingReportLayout } from "@/components/common/AccountingReportLayout";
import { ReportLineChart } from "@/components/common/charts";
import { ReportFilters } from "@/components/common/ReportFilters";
import { Button, Card, Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui";
import { chartColors } from "@/lib/chartColors";
import { formatCurrency } from "@/lib/utils";
import type { ChartOfAccountDto,SubledgerReportLineDto } from "@/types/accounting";

interface SubledgerReportProps {
  fiscalYearId?: number;
  fromDate?: string;
  toDate?: string;
  externalFilters?: { accountId?: number };
  hideInternalControls?: boolean;
}

export function SubledgerReport({ fromDate: propFromDate, toDate: propToDate, externalFilters, hideInternalControls }: SubledgerReportProps) {
  const [internalAccountId, setInternalAccountId] = useState<number | null>(null);
  const accountId = externalFilters?.accountId !== undefined ? externalFilters.accountId : internalAccountId;
  const [filters, setFilters] = useState<Record<string, any>>({
    fromDate: propFromDate || '',
    toDate: propToDate || '',
  });

  useEffect(() => {
    if (propFromDate) setFilters(prev => ({ ...prev, fromDate: propFromDate }));
    if (propToDate) setFilters(prev => ({ ...prev, toDate: propToDate }));
  }, [propFromDate, propToDate]);

  const { data: postableAccounts = [] } = useQuery({
    queryKey: ["accounts", "postable"],
    queryFn: () => accountsApi.getPostable(),
  });

  const { data, isLoading, error, refetch } = useQuery({
    queryKey: ["reports", "subledger", accountId, filters.fromDate, filters.toDate],
    queryFn: () => reportsApi.subledger({
      accountId: accountId!,
      fromDate: filters.fromDate || undefined,
      toDate: filters.toDate || undefined,
    }),
    enabled: !!accountId,
  });

  const handleFilterChange = useCallback((key: string, value: any) => {
    setFilters(prev => ({ ...prev, [key]: value }));
  }, []);

  const handleSearch = () => {
    if (!accountId) return;
    refetch();
  };

  const handlePrint = useCallback(() => {
    const params = new URLSearchParams();
    if (accountId) params.set("accountId", String(accountId));
    if (filters.fromDate) params.set("fromDate", filters.fromDate);
    if (filters.toDate) params.set("toDate", filters.toDate);
    window.open(`/reports/subledger/print?${params.toString()}`, "_blank");
  }, [accountId, filters]);

  const chartContent = data ? (
    <ReportLineChart
      data={data.entries.map((e: SubledgerReportLineDto) => ({
        name: new Date(e.entryDate).toLocaleDateString('ar-SA', { month: 'short', day: 'numeric' }),
        balance: e.runningBalance,
      }))}
      xKey="name"
      lines={[{ key: 'balance', color: chartColors.primary, label: 'الرصيد' }]}
      title="تطور الرصيد"
      area
      height={250}
    />
  ) : undefined;

  const customKPIs = data ? [
    { label: 'الحساب', value: `${data.accountCode} - ${data.accountName}`, color: 'default' },
    { label: 'الرصيد الافتتاحي', value: formatCurrency(data.openingBalance), color: 'default' },
    { label: 'إجمالي المدين', value: formatCurrency(data.totalDebit), color: 'info' },
    { label: 'إجمالي الدائن', value: formatCurrency(data.totalCredit), color: 'success' },
  ] : [];

  const filterBar = hideInternalControls ? undefined : (
    <Card className="p-4 flex flex-wrap gap-4 items-end mb-6">
      <div className="w-full sm:w-64">
        <label className="label-filter">الحساب</label>
        <Select
          value={accountId?.toString() ?? ""}
          onValueChange={(val) => setInternalAccountId(val ? Number(val) : null)}
        >
          <SelectTrigger>
            <SelectValue placeholder="اختر الحساب" />
          </SelectTrigger>
          <SelectContent>
            {postableAccounts.map((a: ChartOfAccountDto) => (
              <SelectItem key={a.accountID} value={a.accountID.toString()}>
                {a.accountCode} - {a.accountName}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
      <ReportFilters
        filters={['fromDate', 'toDate']}
        values={filters}
        onChange={handleFilterChange}
        showApplyButton={false}
        compact
      />
      <Button
        onClick={handleSearch}
        disabled={!accountId}
      >
        عرض
      </Button>
    </Card>
  );

  return (
    <AccountingReportLayout
      title="كشف حساب تفصيلي"
      description="عرض حركات حساب معين بتفاصيل القيود"
      isLoading={isLoading}
      customKPIs={customKPIs}
      filterBar={filterBar}
      chartContent={chartContent}
      onPrint={hideInternalControls ? undefined : (data ? handlePrint : undefined)}
    >
      {error ? (
        <div className="text-destructive text-sm">فشل في تحميل التقرير</div>
      ) : !data ? (
        <div className="text-muted-foreground text-sm p-8 text-center">اختر الحساب ثم انقر عرض</div>
      ) : (
        <div className="border rounded-xl overflow-hidden">
          <table className="w-full text-sm" role="table" aria-label="دفتر الأستاذ الفرعي">
            <thead className="bg-muted/50 sticky top-0 z-10">
              <tr>
                <th className="text-end p-2">التاريخ</th>
                <th className="text-end p-2">رقم القيد</th>
                <th className="text-end p-2">الحساب</th>
                <th className="text-end p-2">البيان</th>
                <th className="text-start p-2 w-28">مدين</th>
                <th className="text-start p-2 w-28">دائن</th>
                <th className="text-start p-2 w-28">الرصيد</th>
              </tr>
            </thead>
            <tbody>
              {data.entries.length === 0 ? (
                <tr>
                  <td colSpan={7} className="p-8 text-center text-muted-foreground">
                    لا توجد حركات في الفترة المحددة
                  </td>
                </tr>
              ) : (
                data.entries.map((entry: SubledgerReportLineDto, i) => (
                  <tr key={i} className="border-t border-border hover:bg-muted/20">
                    <td className="p-2 text-xs">{new Date(entry.entryDate).toLocaleDateString("ar-SA")}</td>
                    <td className="p-2 font-mono text-xs ltr" dir="ltr">{entry.entryNumber}</td>
                    <td className="p-2 text-xs">{entry.accountCode} - {entry.accountName}</td>
                    <td className="p-2 text-xs">{entry.description}</td>
                    <td className="p-2 text-start font-mono text-xs">{entry.debit > 0 ? formatCurrency(entry.debit) : "—"}</td>
                    <td className="p-2 text-start font-mono text-xs">{entry.credit > 0 ? formatCurrency(entry.credit) : "—"}</td>
                    <td className="p-2 text-start font-mono text-xs">{formatCurrency(entry.runningBalance)}</td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      )}
    </AccountingReportLayout>
  );
}

import { useQuery } from "@tanstack/react-query";
import { AlertCircle,CheckCircle } from "lucide-react";
import { useCallback,useMemo, useState } from "react";
import { toast } from "sonner";

import { reportsApi } from "@/api/accounting";
import { AccountingReportLayout } from "@/components/common/AccountingReportLayout";
import { ReportBarChart, ReportPieChart } from "@/components/common/charts";
import { ReportFilters } from "@/components/common/ReportFilters";
import { type CustomColumnDef,DataTable } from "@/components/ui/DataTable";
import { chartColors } from "@/lib/chartColors";
import { formatCurrency } from "@/lib/utils";
import type { TrialBalanceItemDto } from "@/types/accounting";

interface TrialBalanceReportProps {
  fiscalYearId?: number;
  periodId?: number;
  fromDate?: string;
  toDate?: string;
  externalFilters?: { accountLevel?: string };
  hideInternalControls?: boolean;
}


export function TrialBalanceReport({
  fiscalYearId,
  periodId,
  fromDate,
  toDate,
  externalFilters,
  hideInternalControls,
}: TrialBalanceReportProps) {
  const [internalFilters, setInternalFilters] = useState<Record<string, any>>({ accountLevel: 'all' });

  const filters = {
    ...internalFilters,
    ...(externalFilters?.accountLevel !== undefined ? { accountLevel: externalFilters.accountLevel } : {}),
  };

  const { data = [], isLoading, error, refetch } = useQuery({
    queryKey: ["reports", "trial-balance", fiscalYearId, periodId, fromDate, toDate],
    queryFn: () => reportsApi.trialBalance({ fiscalYearId, periodId, fromDate, toDate }),
    enabled: true,
  });

  const filteredData = useMemo(() => {
    if (filters.accountLevel === 'all' || !filters.accountLevel) return data;
    const level = parseInt(filters.accountLevel);
    return data.filter((a: TrialBalanceItemDto) => a.accountLevel <= level);
  }, [data, filters.accountLevel]);

  const postableData = filteredData.filter((a: TrialBalanceItemDto) => a.isPostable);
  const grandOpeningDebit = postableData.reduce((s: number, i: TrialBalanceItemDto) => s + i.openingDebit, 0);
  const grandOpeningCredit = postableData.reduce((s: number, i: TrialBalanceItemDto) => s + i.openingCredit, 0);
  const grandMovementDebit = postableData.reduce((s: number, i: TrialBalanceItemDto) => s + i.movementDebit, 0);
  const grandMovementCredit = postableData.reduce((s: number, i: TrialBalanceItemDto) => s + i.movementCredit, 0);
  const grandClosingDebit = postableData.reduce((s: number, i: TrialBalanceItemDto) => s + i.closingDebit, 0);
  const grandClosingCredit = postableData.reduce((s: number, i: TrialBalanceItemDto) => s + i.closingCredit, 0);
  const grandTotalDebit = postableData.reduce((s: number, i: TrialBalanceItemDto) => s + i.totalDebit, 0);
  const grandTotalCredit = postableData.reduce((s: number, i: TrialBalanceItemDto) => s + i.totalCredit, 0);
  const isBalanced = Math.abs(grandTotalDebit - grandTotalCredit) < 0.01;

  const totalAccounts = filteredData.length;
  const postableAccounts = postableData.length;
  const debitAccounts = filteredData.filter((a: TrialBalanceItemDto) => a.balanceType === "Debit" && a.balance > 0).length;
  const creditAccounts = filteredData.filter((a: TrialBalanceItemDto) => a.balanceType === "Credit" && a.balance > 0).length;

  // Chart data: top 10 accounts by balance
  const chartData = useMemo(() => {
    return postableData
      .filter((a: TrialBalanceItemDto) => a.balance > 0)
      .sort((a: TrialBalanceItemDto, b: TrialBalanceItemDto) => b.balance - a.balance)
      .slice(0, 10)
      .map((a: TrialBalanceItemDto) => ({
        name: a.accountName.length > 20 ? a.accountName.substring(0, 20) + '...' : a.accountName,
        fullName: a.accountName,
        debit: a.totalDebit,
        credit: a.totalCredit,
        balance: a.balance,
        type: a.balanceType,
      }));
  }, [postableData]);

  // Pie chart data: debit vs credit totals
  const pieData = useMemo(() => [
    { name: 'المدين', value: grandTotalDebit, fill: chartColors.primary },
    { name: 'الدائن', value: grandTotalCredit, fill: chartColors.success },
  ], [grandTotalDebit, grandTotalCredit]);

  const handleFilterChange = useCallback((key: string, value: any) => {
    setInternalFilters(prev => ({ ...prev, [key]: value }));
  }, []);

  const handleExportExcel = useCallback(async () => {
    try {
      await reportsApi.exportTrialBalance({ periodId, fromDate, toDate,
        accountLevel: filters.accountLevel === "all" ? undefined : Number(filters.accountLevel) });
      toast.success("تم التصدير بنجاح");
    } catch {
      toast.error("فشل تصدير ميزان المراجعة");
    }
  }, [periodId, fromDate, toDate, filters.accountLevel]);

  const handlePrint = useCallback(() => {
    const params = new URLSearchParams();
    if (fiscalYearId) params.set("fiscalYearId", String(fiscalYearId));
    if (periodId) params.set("periodId", String(periodId));
    if (fromDate) params.set("fromDate", fromDate);
    if (toDate) params.set("toDate", toDate);
    window.open(`/reports/trial-balance/print?${params.toString()}`, "_blank");
  }, [fiscalYearId, periodId, fromDate, toDate]);

  const columns: CustomColumnDef<TrialBalanceItemDto>[] = useMemo(() => [
    {
      key: "accountCode",
      header: "الكود",
      className: "text-center",
      render: (row) => (
        <span
          className="font-mono font-bold text-foreground"
          dir="ltr"
          style={{
            paddingRight: `${(row.accountLevel - 1) * 16}px`,
            fontSize: row.isPostable ? '14px' : '16px'
          }}
        >
          {row.accountCode}
        </span>
      ),
    },
    {
      key: "accountName",
      header: "الحساب",
      render: (row) => (
        <span
          className="text-foreground"
          style={{
            fontWeight: row.isPostable ? 'normal' : 'bold',
            paddingRight: `${(row.accountLevel - 1) * 16}px`
          }}
        >
          {!row.isPostable && <span className="text-muted-foreground ml-1">📂</span>}
          {row.accountName}
        </span>
      ),
    },
    {
      key: "openingDebit",
      header: "افتتاحي مدين",
      className: "text-center",
      render: (row) => (
        <span className="font-mono font-bold text-sm text-info">
          {row.openingDebit > 0 ? formatCurrency(row.openingDebit) : "-"}
        </span>
      ),
    },
    {
      key: "openingCredit",
      header: "افتتاحي دائن",
      className: "text-center",
      render: (row) => (
        <span className="font-mono font-bold text-sm text-success">
          {row.openingCredit > 0 ? formatCurrency(row.openingCredit) : "-"}
        </span>
      ),
    },
    {
      key: "movementDebit",
      header: "حركه مدين",
      className: "text-center",
      render: (row) => (
        <span className="font-mono font-bold text-sm text-info">
          {row.movementDebit > 0 ? formatCurrency(row.movementDebit) : "-"}
        </span>
      ),
    },
    {
      key: "movementCredit",
      header: "حركه دائن",
      className: "text-center",
      render: (row) => (
        <span className="font-mono font-bold text-sm text-success">
          {row.movementCredit > 0 ? formatCurrency(row.movementCredit) : "-"}
        </span>
      ),
    },
    {
      key: "closingDebit",
      header: "ختامي مدين",
      className: "text-center",
      render: (row) => (
        <span className="font-mono font-bold text-sm text-info">
          {row.closingDebit > 0 ? formatCurrency(row.closingDebit) : "-"}
        </span>
      ),
    },
    {
      key: "closingCredit",
      header: "ختامي دائن",
      className: "text-center",
      render: (row) => (
        <span className="font-mono font-bold text-sm text-success">
          {row.closingCredit > 0 ? formatCurrency(row.closingCredit) : "-"}
        </span>
      ),
    },
    {
      key: "balance",
      header: "الرصيد",
      className: "text-center",
      render: (row) => (
        <div className="flex items-center justify-center gap-2">
          <span className={`font-mono font-bold text-lg ${
            row.balanceType === "Debit" ? "text-info" : "text-success"
          }`}>
            {row.balance > 0 ? formatCurrency(row.balance) : "-"}
          </span>
          {row.balance > 0 && (
            <span className={`text-xs px-1.5 py-0.5 rounded ${
              row.balanceType === "Debit"
                ? "bg-info/10 text-info"
                : "bg-success/10 text-success"
            }`}>
              {row.balanceType === "Debit" ? "مدين" : "دائن"}
            </span>
          )}
        </div>
      ),
    },
  ], []);

  if (error)
    return (
      <div className="text-destructive text-sm">فشل في تحميل التقرير</div>
    );

  const filterBar = hideInternalControls ? undefined : (
    <ReportFilters
      filters={['accountLevel']}
      values={filters}
      onChange={handleFilterChange}
      onApply={() => refetch()}
      showApplyButton={false}
    />
  );

  const customKPIs = [
    { label: 'إجمالي الحسابات', value: totalAccounts, color: 'default' },
    { label: 'حسابات مدينة', value: debitAccounts, color: 'info' },
    { label: 'حسابات دائنة', value: creditAccounts, color: 'success' },
    { label: 'حسابات فرعية', value: postableAccounts, color: 'default' },
  ];

  const chartContent = (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      <ReportBarChart
        data={chartData}
        xKey="name"
        yKeys={[
          { key: 'debit', color: chartColors.primary, label: 'المدين' },
          { key: 'credit', color: chartColors.success, label: 'الدائن' },
        ]}
        title="أعلى 10 حسابات حسب الرصيد"
        height={300}
      />
      <ReportPieChart
        data={pieData}
        nameKey="name"
        valueKey="value"
        title="توزيع المدين والدائن"
        height={300}
      />
    </div>
  );

  const footer = filteredData.length > 0 ? (
    <div className={`rounded-lg p-4 font-bold ${isBalanced ? 'bg-success/10 border border-success' : 'bg-danger/10 border border-danger'}`}>
      <div className="flex items-center justify-between flex-wrap gap-4">
        <div className="flex items-center gap-3">
          {isBalanced ? (
            <CheckCircle className="w-6 h-6 text-success" />
          ) : (
            <AlertCircle className="w-6 h-6 text-danger" />
          )}
          <div>
            <div className="text-lg">
              {isBalanced ? "الميزان متوازن ✓" : "الميزان غير متوازن ✗"}
            </div>
            {!isBalanced && (
              <div className="text-sm font-normal text-danger">
                الفرق: {formatCurrency(Math.abs(grandTotalDebit - grandTotalCredit))}
              </div>
            )}
          </div>
        </div>
        <div className="flex gap-6 flex-wrap">
          <div className="text-center">
            <div className="text-xs text-muted-foreground">الافتتاحي</div>
            <div className="flex gap-3">
              <div><span className="text-xs text-muted-foreground">م:</span> <span className="font-mono text-info">{formatCurrency(grandOpeningDebit)}</span></div>
              <div><span className="text-xs text-muted-foreground">د:</span> <span className="font-mono text-success">{formatCurrency(grandOpeningCredit)}</span></div>
            </div>
          </div>
          <div className="text-center">
            <div className="text-xs text-muted-foreground">الحركه</div>
            <div className="flex gap-3">
              <div><span className="text-xs text-muted-foreground">م:</span> <span className="font-mono text-info">{formatCurrency(grandMovementDebit)}</span></div>
              <div><span className="text-xs text-muted-foreground">د:</span> <span className="font-mono text-success">{formatCurrency(grandMovementCredit)}</span></div>
            </div>
          </div>
          <div className="text-center">
            <div className="text-xs text-muted-foreground">الختامي</div>
            <div className="flex gap-3">
              <div><span className="text-xs text-muted-foreground">م:</span> <span className="font-mono text-info">{formatCurrency(grandClosingDebit)}</span></div>
              <div><span className="text-xs text-muted-foreground">د:</span> <span className="font-mono text-success">{formatCurrency(grandClosingCredit)}</span></div>
            </div>
          </div>
          <div className="text-center">
            <div className="text-xs text-muted-foreground">الإجمالي</div>
            <div className="flex gap-3">
              <div><span className="text-xs text-muted-foreground">م:</span> <span className="font-mono text-xl text-info">{formatCurrency(grandTotalDebit)}</span></div>
              <div><span className="text-xs text-muted-foreground">د:</span> <span className="font-mono text-xl text-success">{formatCurrency(grandTotalCredit)}</span></div>
            </div>
          </div>
        </div>
      </div>
    </div>
  ) : null;

  return (
    <AccountingReportLayout
      title="ميزان المراجعة"
      description="عرض أرصدة الحسابات وميزان التوازن"
      isLoading={isLoading}
      customKPIs={customKPIs}
      filterBar={filterBar}
      chartContent={chartContent}
      onExport={hideInternalControls ? undefined : (filteredData.length > 0 ? handleExportExcel : undefined)}
      onPrint={hideInternalControls ? undefined : (filteredData.length > 0 ? handlePrint : undefined)}
      footer={footer}
    >
      <DataTable
        columns={columns}
        data={filteredData}
        loading={isLoading}
        emptyMessage="لا توجد بيانات"
        rowKey={(row) => row.accountID}
      />
    </AccountingReportLayout>
  );
}

import { zodResolver } from "@hookform/resolvers/zod";
import { useQuery } from "@tanstack/react-query";
import { Landmark, Receipt } from "lucide-react";
import { useEffect, useMemo } from "react";
import { Controller, type Resolver,useForm, useWatch } from "react-hook-form";
import { z } from "zod";

import { accountsApi } from "@/api/accounting";
import { type CreateVoucherDto,vouchersApi, type VoucherType } from "@/api/vouchers";
import {
  BaseFormDialog,
  Button,
  DateInput,
  FormField,
  FormSection,
  Input,
  NativeSelect,
  NoteBox,
} from "@/components/ui";
import { queryKeys } from "@/constants/queryKeys";
import { useApiMutation } from "@/hooks";
import type { ChartOfAccountDto } from "@/types/accounting";

// ─── Schema ───────────────────────────────────────
const voucherSchema = z.object({
  voucherType: z.number().min(1).max(2),
  voucherDate: z.string().min(1, "التاريخ مطلوب"),
  payeeName: z.string().optional().or(z.literal("")),
  amount: z.coerce.number().min(0.01, "المبلغ يجب أن أكبر من صفر"),
  description: z.string().min(1, "البيان مطلوب"),
  debitAccountID: z.coerce.number().min(1, "اختر حساب المدين"),
  creditAccountID: z.coerce.number().min(1, "اختر حساب الدائن"),
  chequeNumber: z.string().optional().or(z.literal("")),
  referralSource: z.string().optional().or(z.literal("")),
});

type VoucherFormValues = z.infer<typeof voucherSchema>;

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function VoucherFormDialog({ open, onOpenChange }: Props) {
  // ─── Accounts Query ──────────────────────────────
  const { data: accounts, isLoading: accountsLoading } = useQuery({
    queryKey: queryKeys.accounting.accounts.postable,
    queryFn: () => accountsApi.getPostable(),
    enabled: open,
  });

  // ─── Form ────────────────────────────────────────
  const form = useForm<VoucherFormValues>({
    resolver: zodResolver(voucherSchema) as Resolver<VoucherFormValues>,
    defaultValues: {
      voucherType: 1,
      voucherDate: new Date().toISOString().split("T")[0],
      payeeName: "",
      amount: 0,
      description: "",
      debitAccountID: 0,
      creditAccountID: 0,
      chequeNumber: "",
      referralSource: "",
    },
  });

  const { control, register, setValue, handleSubmit, formState: { errors, isDirty }, reset } = form;

  // ─── Watch type to filter accounts ───────────────
  const voucherType = useWatch({ control, name: "voucherType" });

  const expenseAccounts = useMemo(
    () => accounts?.filter((a: ChartOfAccountDto) => a.accountCode.startsWith("3") && a.isPostable) || [],
    [accounts]
  );
  const revenueAccounts = useMemo(
    () => accounts?.filter((a: ChartOfAccountDto) => a.accountCode.startsWith("4") && a.isPostable) || [],
    [accounts]
  );
  const treasuryAccounts = useMemo(
    () => accounts?.filter((a: ChartOfAccountDto) => a.accountCode.startsWith("18") && a.isPostable) || [],
    [accounts]
  );

  const debitAccountOptions = useMemo(() => {
    const list = voucherType === 1 ? expenseAccounts : treasuryAccounts;
    return list.map((a: ChartOfAccountDto) => ({ value: String(a.accountID), label: `${a.accountCode} - ${a.accountName}` }));
  }, [voucherType, expenseAccounts, treasuryAccounts]);

  const creditAccountOptions = useMemo(() => {
    const list = voucherType === 1 ? treasuryAccounts : revenueAccounts;
    return list.map((a: ChartOfAccountDto) => ({ value: String(a.accountID), label: `${a.accountCode} - ${a.accountName}` }));
  }, [voucherType, treasuryAccounts, revenueAccounts]);

  // ─── Auto-set accounts when type changes ─────────
  useEffect(() => {
    if (!open) return;
    setValue("debitAccountID", 0);
    setValue("creditAccountID", 0);
  }, [voucherType, open, setValue]);

  // ─── Mutation ────────────────────────────────────
  const mutation = useApiMutation(
    async (values: VoucherFormValues) => {
      const dto: CreateVoucherDto = {
        voucherType: values.voucherType as VoucherType,
        voucherDate: values.voucherDate,
        payeeName: values.voucherType === 1 ? values.payeeName || undefined : undefined,
        payerName: values.voucherType === 2 ? values.payeeName || undefined : undefined,
        amount: values.amount,
        description: values.description,
        debitAccountID: values.debitAccountID,
        creditAccountID: values.creditAccountID,
        chequeNumber: values.chequeNumber || undefined,
        referralSource: values.referralSource || undefined,
      };
      return vouchersApi.create(dto);
    },
    {
      successMessage: "تم إنشاء السند بنجاح",
      errorTitle: "خطأ في إنشاء السند",
      invalidateKeys: [["vouchers"]],
      onSuccess: () => {
        onOpenChange(false);
        form.reset();
      },
    }
  );

  return (
    <BaseFormDialog
      open={open}
      onOpenChange={onOpenChange}
      title={voucherType === 1 ? "سند صرف" : "سند قبض"}
      description="إنشاء سند مالي جديد"
      size="lg"
      isLoading={mutation.isPending || accountsLoading}
      isDirty={isDirty}
      formErrors={errors}
      onSubmit={handleSubmit((v) => mutation.mutate(v))}
      resetOnOpen
      reset={reset}
      submitLabel="إنشاء السند"
    >
      <div className="space-y-4">
        {/* ─── Type Toggle ─── */}
        <div className="flex gap-2">
          <Controller
            name="voucherType"
            control={control}
            render={({ field }) => (
              <>
                <input type="hidden" {...field} />
                <Button
                  type="button"
                  variant={field.value === 1 ? "default" : "outline"}
                  className="flex-1"
                  onClick={() => field.onChange(1)}
                >
                  سند صرف
                </Button>
                <Button
                  type="button"
                  variant={field.value === 2 ? "default" : "outline"}
                  className="flex-1"
                  onClick={() => field.onChange(2)}
                >
                  سند قبض
                </Button>
              </>
            )}
          />
        </div>

        {/* ─── بيانات السند ─── */}
        <FormSection title="بيانات السند" icon={Receipt}>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <FormField label="التاريخ" required error={errors.voucherDate?.message}>
              <Controller
                name="voucherDate"
                control={control}
                render={({ field }) => (
                  <DateInput
                    id={field.name}
                    value={field.value || undefined}
                    onChange={field.onChange}
                  />
                )}
              />
            </FormField>

            <FormField
              label={voucherType === 1 ? "المستفيد" : "الدافع"}
              required
              error={errors.payeeName?.message}
            >
              <Input
                {...register("payeeName")}
                placeholder={voucherType === 1 ? "اسم المستفيد" : "اسم الدافع"}
              />
            </FormField>

            <FormField label="المبلغ (ريال يمني)" required error={errors.amount?.message}>
              <Input
                type="number"
                {...register("amount")}
                placeholder="0"
                min="0"
              />
            </FormField>

            <FormField label="رقم الشيك / المرجع" error={errors.chequeNumber?.message}>
              <Input {...register("chequeNumber")} placeholder="اختياري" />
            </FormField>

            <FormField label="مصدر التوجيه" error={errors.referralSource?.message}>
              <Input {...register("referralSource")} placeholder="مصدر التوجيه (اختياري)" />
            </FormField>
          </div>

          <FormField label="البيان" required error={errors.description?.message}>
            <Input {...register("description")} placeholder="بيان السند..." />
          </FormField>
        </FormSection>

        {/* ─── الحسابات ─── */}
        <FormSection title="الحسابات المحاسبية" icon={Landmark}>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <FormField
              label={`حساب المدين (${voucherType === 1 ? "مصروف" : "خزينة"})`}
              required
              error={errors.debitAccountID?.message}
            >
              <Controller
                name="debitAccountID"
                control={control}
                render={({ field }) => (
                  <NativeSelect
                    value={field.value || ""}
                    onChange={(val) => field.onChange(val ? Number(val) : 0)}
                    options={debitAccountOptions}
                    placeholder="اختر حساب المدين"
                  />
                )}
              />
            </FormField>

            <FormField
              label={`حساب الدائن (${voucherType === 1 ? "خزينة" : "إيراد"})`}
              required
              error={errors.creditAccountID?.message}
            >
              <Controller
                name="creditAccountID"
                control={control}
                render={({ field }) => (
                  <NativeSelect
                    value={field.value || ""}
                    onChange={(val) => field.onChange(val ? Number(val) : 0)}
                    options={creditAccountOptions}
                    placeholder="اختر حساب الدائن"
                  />
                )}
              />
            </FormField>
          </div>

          <NoteBox type="info" title="القيد المحاسبي المتوقع">
            {voucherType === 1
              ? "مدين: مصروفات (3XXX) ← دائن: الخزينة (18XX)"
              : "مدين: الخزينة (18XX) ← دائن: إيرادات (4XXX)"}
          </NoteBox>
        </FormSection>
      </div>
    </BaseFormDialog>
  );
}

import { AlertTriangle, CheckCircle2, FileSpreadsheet, Upload, X } from "lucide-react";
import { useCallback, useRef, useState } from "react";
import { toast } from "sonner";

import { type ImportVoucherResultDto,vouchersApi } from "@/api/vouchers";
import { Badge, Button, Dialog, DialogContent, DialogHeader, DialogTitle, Text } from "@/components/ui";

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onImported?: () => void;
}

type ImportStep = "select" | "importing" | "result";

export function VoucherImportDialog({ open, onOpenChange, onImported }: Props) {
  const [step, setStep] = useState<ImportStep>("select");
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [result, setResult] = useState<ImportVoucherResultDto | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const reset = useCallback(() => {
    setStep("select");
    setSelectedFile(null);
    setResult(null);
  }, []);

  const handleClose = useCallback(() => {
    onOpenChange(false);
    // delay reset to avoid animation issues
    setTimeout(reset, 200);
  }, [onOpenChange, reset]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setSelectedFile(file);
    }
  };

  const handleImport = async () => {
    if (!selectedFile) return;

    setStep("importing");
    try {
      const response = await vouchersApi.import(selectedFile);
      if (response.isSuccess) {
        setResult(response.data);
        setStep("result");
        toast.success(response.message || "تم الاستيراد بنجاح");
        onImported?.();
      } else {
        toast.error(response.message || "فشل في الاستيراد");
        setStep("select");
      }
    } catch (err: any) {
      toast.error(err?.response?.data?.message || "خطأ في رفع الملف");
      setStep("select");
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <div className="flex items-center justify-between">
            <DialogTitle className="flex items-center gap-2">
              <FileSpreadsheet className="w-5 h-5" />
              استيراد سندات من Excel
            </DialogTitle>
            <Button variant="ghost" size="icon" onClick={handleClose}>
              <X className="w-4 h-4" />
            </Button>
          </div>
        </DialogHeader>

        {/* Step 1: Select file */}
        {step === "select" && (
          <div className="space-y-4">
            <div className="text-sm text-muted-foreground">
              <Text variant="body">يقبل ملف Excel (.xlsx) بالتنسيق التالي:</Text>
              <ul className="mt-2 space-y-1 list-disc list-inside text-xs">
                <li>العمود A: الرقم (سيُحفظ كمرجع)</li>
                <li>العمود B: التاريخ</li>
                <li>العمود C: المبلغ</li>
                <li>العمود D: جهة الاستلام (المستفيد)</li>
                <li>العمود E: جهة الأمر</li>
                <li>العمود F: البيان</li>
              </ul>
            </div>

            <input
              ref={fileInputRef}
              type="file"
              accept=".xlsx,.xls"
              onChange={handleFileChange}
              className="hidden"
            />

            <Button
              type="button"
              variant="outline"
              className="w-full border-2 border-dashed p-8 h-auto"
              onClick={() => fileInputRef.current?.click()}
            >
              <Upload className="w-8 h-8 mx-auto mb-2 text-muted-foreground" />
              {selectedFile ? (
                <div>
                  <Text variant="label">{selectedFile.name}</Text>
                  <Text variant="caption" className="mt-1">
                    {(selectedFile.size / 1024).toFixed(1)} KB
                  </Text>
                </div>
              ) : (
                <div>
                  <Text variant="label">اضغط لاختيار ملف</Text>
                  <Text variant="caption" className="mt-1">أو اسحب وأفلت الملف هنا</Text>
                </div>
              )}
            </Button>

            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={handleClose}>إلغاء</Button>
              <Button onClick={handleImport} disabled={!selectedFile}>
                <Upload className="w-4 h-4 me-1" />
                استيراد
              </Button>
            </div>
          </div>
        )}

        {/* Step 2: Importing */}
        {step === "importing" && (
          <div className="py-8 text-center">
            <div className="animate-spin w-8 h-8 border-4 border-primary border-t-transparent rounded-full mx-auto mb-4" />
            <Text variant="description">جاري استيراد السندات...</Text>
          </div>
        )}

        {/* Step 3: Result */}
        {step === "result" && result && (
          <div className="space-y-4">
            {/* Summary */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 text-center">
              <div className="p-3 bg-blue-50 rounded-lg">
                <Text variant="body" className="font-bold text-blue-700">{result.totalRows}</Text>
                <Text variant="caption">إجمالي الصفوف</Text>
              </div>
              <div className="p-3 bg-green-50 rounded-lg">
                <Text variant="body" className="font-bold text-green-700">{result.successCount}</Text>
                <Text variant="caption">تم الاستيراد</Text>
              </div>
              <div className="p-3 bg-orange-50 rounded-lg">
                <Text variant="body" className="font-bold text-orange-700">{result.skipCount}</Text>
                <Text variant="caption">تم التخطي</Text>
              </div>
            </div>

            {/* Errors list */}
            {result.errors.length > 0 && (
              <div className="max-h-48 overflow-y-auto border rounded-lg">
                <div className="p-2 bg-muted/50 text-xs font-medium flex items-center gap-1">
                  <AlertTriangle className="w-3 h-3" />
                  تفاصيل الأخطاء
                </div>
                {result.errors.map((err, i) => (
                  <div key={i} className="px-3 py-1.5 text-xs border-t flex items-center gap-2">
                    <Badge variant="outline" className="shrink-0">صف {err.rowNumber}</Badge>
                    <span>{err.message}</span>
                  </div>
                ))}
              </div>
            )}

            {/* Success message */}
            {result.skipCount === 0 && (
              <div className="flex items-center gap-2 p-3 bg-green-50 text-green-700 rounded-lg text-sm">
                <CheckCircle2 className="w-4 h-4" />
                تم استيراد جميع السندات بنجاح
              </div>
            )}

            <div className="flex justify-end">
              <Button onClick={handleClose}>إغلاق</Button>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

import { useQuery } from "@tanstack/react-query";
import { useEffect,useRef } from "react";
import { useReactToPrint } from "react-to-print";

import { vouchersApi } from "@/api/vouchers";
import { PrintablePaymentOrder } from "@/pages/print/PrintablePaymentOrder";
import { PrintableVoucher } from "@/pages/print/PrintableVoucher";

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  voucherId: number;
}

export function VoucherPrintDialog({ open, onOpenChange, voucherId }: Props) {
  const printRef = useRef<HTMLDivElement>(null);

  const { data: voucher, isLoading } = useQuery({
    queryKey: ["voucher", voucherId],
    queryFn: () => vouchersApi.getById(voucherId),
    enabled: open && !!voucherId,
  });

  const handlePrint = useReactToPrint({
    contentRef: printRef,
    documentTitle: voucher?.voucherNumber || "سند",
    onAfterPrint: () => onOpenChange(false),
    onPrintError: () => onOpenChange(false),
  });

  // طباعة تلقائية عند تحميل البيانات
  useEffect(() => {
    if (voucher && !isLoading) {
      const timer = setTimeout(() => {
        handlePrint();
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [voucher, isLoading]);

  if (!open) return null;

  const isReceipt = voucher?.voucherType === 2;

  return (
    <div className="fixed inset-0 bg-white z-[9999] flex items-center justify-center flex-col gap-4">
      {isLoading ? (
        <div className="text-lg text-muted-foreground">جاري تحميل السند...</div>
      ) : voucher ? (
        isReceipt ? (
          <PrintableVoucher ref={printRef} voucher={voucher} />
        ) : (
          <PrintablePaymentOrder ref={printRef} voucher={voucher} />
        )
      ) : (
        <div className="text-lg text-muted-foreground">السند غير موجود</div>
      )}
    </div>
  );
}

﻿import { useQuery } from "@tanstack/react-query";
import { useCallback,useEffect, useState } from "react";

import { fiscalYearsApi,reportsApi } from "@/api/accounting";
import { AccountingReportLayout } from "@/components/common/AccountingReportLayout";
import { ReportBarChart } from "@/components/common/charts";
import { Card, Heading, Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui";
import { chartColors } from "@/lib/chartColors";
import { formatCurrency } from "@/lib/utils";
import type { FiscalYearSummaryDto } from "@/types/accounting";

interface YearOverYearReportProps {
  fiscalYearId?: number;
  externalFilters?: { comparisonYear?: number };
  hideInternalControls?: boolean;
}

export function YearOverYearReport({ fiscalYearId, externalFilters, hideInternalControls }: YearOverYearReportProps) {
  const [year1Id, setYear1Id] = useState<number | undefined>(fiscalYearId);
  const [year2Id, setYear2Id] = useState<number | undefined>();

  const { data: fiscalYears } = useQuery({
    queryKey: ["fiscal-years"],
    queryFn: () => fiscalYearsApi.getAll(),
  });

  useEffect(() => {
    if (externalFilters?.comparisonYear && fiscalYears) {
      const match = fiscalYears.find((y: FiscalYearSummaryDto) => y.yearName === String(externalFilters.comparisonYear));
      if (match) setYear2Id(match.fiscalYearID);
    } else if (fiscalYears && fiscalYears.length >= 2 && !year2Id) {
      const currentYear = new Date().getFullYear().toString();
      const current = fiscalYears.find((y: FiscalYearSummaryDto) => y.yearName === currentYear);
      const previous = fiscalYears.find((y: FiscalYearSummaryDto) => y.yearName === String(Number(currentYear) - 1));
      if (current && previous) {
        setYear1Id(current.fiscalYearID);
        setYear2Id(previous.fiscalYearID);
      } else if (fiscalYears.length >= 2) {
        setYear1Id(fiscalYears[0].fiscalYearID);
        setYear2Id(fiscalYears[1].fiscalYearID);
      }
    }
  }, [fiscalYears]);

  const { data: income1, isLoading: loading1 } = useQuery({
    queryKey: ["reports", "income-statement", year1Id],
    queryFn: () => reportsApi.incomeStatement(year1Id!),
    enabled: !!year1Id,
  });

  const { data: income2, isLoading: loading2 } = useQuery({
    queryKey: ["reports", "income-statement", year2Id],
    queryFn: () => reportsApi.incomeStatement(year2Id!),
    enabled: !!year2Id,
  });

  const isLoading = loading1 || loading2;

  const handlePrint = useCallback(() => {
    const params = new URLSearchParams();
    if (year1Id) params.set("year1Id", String(year1Id));
    if (year2Id) params.set("year2Id", String(year2Id));
    window.open(`/reports/year-over-year/print?${params.toString()}`, "_blank");
  }, [year1Id, year2Id]);

  const year1 = fiscalYears?.find((y: FiscalYearSummaryDto) => y.fiscalYearID === year1Id);
  const year2 = fiscalYears?.find((y: FiscalYearSummaryDto) => y.fiscalYearID === year2Id);

  const revenueChange = income2 && income2.totalRevenue !== 0
    ? ((income1!.totalRevenue - income2.totalRevenue) / Math.abs(income2.totalRevenue)) * 100
    : 0;
  const expenseChange = income2 && income2.totalExpenses !== 0
    ? ((income1!.totalExpenses - income2.totalExpenses) / Math.abs(income2.totalExpenses)) * 100
    : 0;
  const netIncomeChange = income2 && income2.netIncome !== 0
    ? ((income1!.netIncome - income2.netIncome) / Math.abs(income2.netIncome)) * 100
    : 0;

  const customKPIs = income1 && income2 ? [
    { label: 'الإيرادات', value: `${formatCurrency(income1.totalRevenue)} (${revenueChange >= 0 ? '+' : ''}${revenueChange.toFixed(1)}%)`, color: revenueChange >= 0 ? 'text-green-600' : 'text-red-600' },
    { label: 'المصروفات', value: `${formatCurrency(income1.totalExpenses)} (${expenseChange >= 0 ? '+' : ''}${expenseChange.toFixed(1)}%)`, color: expenseChange <= 0 ? 'text-green-600' : 'text-red-600' },
    { label: 'صافي الدخل', value: `${formatCurrency(income1.netIncome)} (${netIncomeChange >= 0 ? '+' : ''}${netIncomeChange.toFixed(1)}%)`, color: netIncomeChange >= 0 ? 'text-green-600' : 'text-red-600' },
    { label: 'السنة المقارنة', value: `${year1?.yearName || ''} vs ${year2?.yearName || ''}`, color: 'primary' },
  ] : [];

  const chartContent = income1 && income2 ? (
    <ReportBarChart
      data={[
        { name: 'الإيرادات', [year1?.yearName || 'الحالية']: income1.totalRevenue, [year2?.yearName || 'السابقة']: income2.totalRevenue },
        { name: 'المصروفات', [year1?.yearName || 'الحالية']: income1.totalExpenses, [year2?.yearName || 'السابقة']: income2.totalExpenses },
        { name: 'صافي الدخل', [year1?.yearName || 'الحالية']: income1.netIncome, [year2?.yearName || 'السابقة']: income2.netIncome },
      ]}
      xKey="name"
      yKeys={[
        { key: year1?.yearName || 'الحالية', color: chartColors.primary, label: year1?.yearName || 'الحالية' },
        { key: year2?.yearName || 'السابقة', color: chartColors.success, label: year2?.yearName || 'السابقة' },
      ]}
      title="مقارنة الأداء السنوي"
      height={300}
    />
  ) : undefined;

  const filterBar = hideInternalControls ? undefined : (
    <Card className="p-4 flex flex-wrap gap-4 items-end mb-6">
      <div className="w-full sm:w-48">
        <label className="label-filter">السنة الحالية</label>
        <Select
          value={year1Id ? String(year1Id) : ''}
          onValueChange={(value) => setYear1Id(Number(value))}
        >
          <SelectTrigger className="w-full">
            <SelectValue placeholder="اختر السنة" />
          </SelectTrigger>
          <SelectContent>
            {fiscalYears?.map((y: FiscalYearSummaryDto) => (
              <SelectItem key={y.fiscalYearID} value={String(y.fiscalYearID)}>
                {y.yearName}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
      <div className="w-full sm:w-48">
        <label className="label-filter">السنة السابقة</label>
        <Select
          value={year2Id?.toString() ?? ''}
          onValueChange={(val) => setYear2Id(Number(val))}
        >
          <SelectTrigger>
            <SelectValue placeholder="اختر السنة" />
          </SelectTrigger>
          <SelectContent>
            {fiscalYears?.map((y: FiscalYearSummaryDto) => (
              <SelectItem key={y.fiscalYearID} value={y.fiscalYearID.toString()}>{y.yearName}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
    </Card>
  );

  return (
    <AccountingReportLayout
      title="المقارنة السنوية"
      description="مقارنة الأداء المالي بين سنتين ماليتين"
      isLoading={isLoading}
      customKPIs={customKPIs}
      filterBar={filterBar}
      chartContent={chartContent}
      onPrint={hideInternalControls ? undefined : (income1 && income2 ? handlePrint : undefined)}
    >
      {!income1 || !income2 ? (
        <div className="text-muted-foreground text-sm p-8 text-center">اختر سنتين ماليتين للمقارنة</div>
      ) : (
        <Card className="border-none rounded-3xl overflow-hidden">
          <div className="p-4 bg-muted/30">
            <Heading level="h3" className="font-bold text-lg">مقارنة تفصيلية: {year1?.yearName} vs {year2?.yearName}</Heading>
          </div>
          <table className="w-full text-sm" role="table" aria-label="مقارنة سنوية">
            <thead className="bg-muted/50 sticky top-0 z-10">
              <tr>
                <th className="text-end p-3">البند</th>
                <th className="text-end p-3">{year1?.yearName}</th>
                <th className="text-end p-3">{year2?.yearName}</th>
                <th className="text-end p-3">الفرق</th>
                <th className="text-end p-3">النسبة</th>
              </tr>
            </thead>
            <tbody>
              <tr className="border-t border-border bg-emerald-50/50 dark:bg-emerald-950/20">
                <td className="p-3 font-medium">إجمالي الإيرادات</td>
                <td className="p-3">{formatCurrency(income1.totalRevenue)}</td>
                <td className="p-3">{formatCurrency(income2.totalRevenue)}</td>
                <td className={`p-3 font-medium ${revenueChange >= 0 ? "text-emerald-600 dark:text-emerald-400" : "text-destructive"}`}>
                  {formatCurrency(income1.totalRevenue - income2.totalRevenue)}
                </td>
                <td className={`p-3 ${revenueChange >= 0 ? "text-emerald-600 dark:text-emerald-400" : "text-destructive"}`}>
                  {revenueChange >= 0 ? "+" : ""}{revenueChange.toFixed(1)}%
                </td>
              </tr>
              <tr className="border-t border-border bg-red-50/50 dark:bg-red-950/20">
                <td className="p-3 font-medium">إجمالي المصروفات</td>
                <td className="p-3">{formatCurrency(income1.totalExpenses)}</td>
                <td className="p-3">{formatCurrency(income2.totalExpenses)}</td>
                <td className={`p-3 font-medium ${expenseChange <= 0 ? "text-emerald-600 dark:text-emerald-400" : "text-destructive"}`}>
                  {formatCurrency(income1.totalExpenses - income2.totalExpenses)}
                </td>
                <td className={`p-3 ${expenseChange <= 0 ? "text-emerald-600 dark:text-emerald-400" : "text-destructive"}`}>
                  {expenseChange >= 0 ? "+" : ""}{expenseChange.toFixed(1)}%
                </td>
              </tr>
              <tr className="border-t border-border font-bold">
                <td className="p-3">صافي الدخل</td>
                <td className={`p-3 ${income1.netIncome >= 0 ? "text-emerald-600 dark:text-emerald-400" : "text-destructive"}`}>
                  {formatCurrency(income1.netIncome)}
                </td>
                <td className={`p-3 ${income2.netIncome >= 0 ? "text-emerald-600 dark:text-emerald-400" : "text-destructive"}`}>
                  {formatCurrency(income2.netIncome)}
                </td>
                <td className={`p-3 ${netIncomeChange >= 0 ? "text-emerald-600 dark:text-emerald-400" : "text-destructive"}`}>
                  {formatCurrency(income1.netIncome - income2.netIncome)}
                </td>
                <td className={`p-3 ${netIncomeChange >= 0 ? "text-emerald-600 dark:text-emerald-400" : "text-destructive"}`}>
                  {netIncomeChange >= 0 ? "+" : ""}{netIncomeChange.toFixed(1)}%
                </td>
              </tr>
            </tbody>
          </table>
        </Card>
      )}
    </AccountingReportLayout>
  );
}

import { zodResolver } from "@hookform/resolvers/zod";
import { useQuery } from "@tanstack/react-query";
import { Activity, Hash, Landmark } from "lucide-react";
import { useMemo } from "react";
import { type Resolver, useForm } from "react-hook-form";
import * as z from "zod";

import { accountsApi } from "@/api/accounting";
import { bankApi, type BankDto } from "@/api/banks";
import {
    BaseFormDialog,
    FormField,
    FormSection,
    Input,
    NativeSelect,
    NoteBox} from "@/components/ui";
import { useApiMutation } from "@/hooks";
import type { ChartOfAccountDto } from "@/types/accounting";

// ─── Validation Schema ─────────────────────────────────

const bankSchema = z.object({
    bankName: z.string().trim().min(2, "اسم البنك مطلوب"),
    bankCode: z.string().trim().optional().nullable().or(z.literal("")),
    accountID: z.number().nullable().optional(),
    isActive: z.boolean(),
});

type BankFormValues = z.infer<typeof bankSchema>;

interface Props {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onSaved: () => void;
    bank: BankDto | null;
}

/**
 * Standardized BankFormDialog.
 * Refactored to reach 100% architectural compliance.
 */
export function BankFormDialog({ open, onOpenChange, onSaved, bank }: Props) {
    const isEdit = !!bank;

    const { data: accounts = [] } = useQuery({
        queryKey: ["accounts", "postable"],
        queryFn: () => accountsApi.getPostable(),
        enabled: open,
    });

    // تصفية الحسابات البنكية (تبدأ بـ 18 - الأموال الجاهزة)
    const bankAccounts = useMemo(() => {
        return accounts.filter((a: ChartOfAccountDto) => a.accountCode.startsWith("18"));
    }, [accounts]);

    const mutation = useApiMutation(
        (values: BankFormValues) => isEdit
            ? bankApi.update(bank!.bankID, values)
            : bankApi.create(values),
        {
            successMessage: isEdit ? "تم تحديث بيانات البنك بنجاح" : "تم إضافة البنك الجديد بنجاح",
            onSuccessCallback: () => {
                onSaved();
                onOpenChange(false);
            }
        }
    );

    const form = useForm<BankFormValues>({
        resolver: zodResolver(bankSchema) as Resolver<z.infer<typeof bankSchema>>,
        defaultValues: {
            bankName: "",
            bankCode: "",
            accountID: null,
            isActive: true,
        },
    });

    const { register, handleSubmit, reset, watch, setValue, formState: { errors, isDirty } } = form;

    const onSubmit = (values: BankFormValues) => {
        mutation.mutate(values);
    };

    const initialValues = useMemo(() => {
        if (!bank) return { bankName: "", bankCode: "", accountID: null, isActive: true };
        return {
            bankName: bank.bankName,
            bankCode: bank.bankCode || "",
            accountID: bank.accountID || null,
            isActive: bank.isActive,
        };
    }, [bank]);

    return (
        <BaseFormDialog
            open={open}
            onOpenChange={onOpenChange}
            title={isEdit ? "تعديل بيانات البنك" : "إضافة بنك جديد"}
            description="إدارة الجهات المصرفية المعتمدة لصرف المعاشات"
            size="md"
            isLoading={mutation.isPending}
            isDirty={isDirty}
            onSubmit={handleSubmit(onSubmit)}
            resetOnOpen
            reset={reset}
            initialValues={initialValues}
            showGlobalError
            formErrors={errors}
            submitLabel={isEdit ? "حفظ التعديلات" : "إضافة البنك"}
        >
            <div className="space-y-4">
                <FormSection title="البيانات الأساسية للبنك" icon={Landmark}>
                    <div className="grid grid-cols-1 gap-4">
                        <FormField label="اسم البنك / المصرف" required error={errors.bankName?.message}>
                            <Input
                                {...register("bankName")}
                                placeholder="مثال: البنك المركزي، بنك الكريمي..."
                                icon={Landmark}
                            />
                        </FormField>

                        <FormField label="رمز البنك (Bank Code)" error={errors.bankCode?.message}>
                            <Input
                                {...register("bankCode")}
                                placeholder="مثال: CACB"
                                icon={Hash}
                                dir="ltr"
                                className="font-mono uppercase"
                            />
                        </FormField>

                        <FormField label="الحساب المحاسبي المرتبط" error={errors.accountID?.message}>
                            <NativeSelect
                                value={String(watch("accountID") || "")}
                                options={[
                                    { label: "اختر الحساب...", value: "" },
                                    ...bankAccounts.map((a: ChartOfAccountDto) => ({
                                        label: `${a.accountCode} - ${a.accountName}`,
                                        value: String(a.accountID)
                                    }))
                                ]}
                                onChange={(v) => setValue("accountID", v ? Number(v) : null)}
                            />
                        </FormField>
                    </div>
                </FormSection>

                <FormSection title="الحالة الإدارية" icon={Activity}>
                    <div className="flex items-center gap-3 p-4 bg-muted/30 rounded-2xl border border-border">
                        <input
                            type="checkbox"
                            id="bank-active-check"
                            {...register("isActive")}
                            className="h-5 w-5 rounded border-border text-primary focus:ring-primary accent-primary cursor-pointer"
                        />
                        <label htmlFor="bank-active-check" className="text-sm font-bold text-foreground cursor-pointer">
                            البنك نشط (يسمح بإجراء التحويلات المالية إليه)
                        </label>
                    </div>
                </FormSection>

                <NoteBox type="info">
                    تأكد من اختيار الحساب المحاسبي الصحيح للبنك لضمان تسجيل القيود البنكية بشكل صحيح.
                </NoteBox>
            </div>
        </BaseFormDialog>
    );
}

import { zodResolver } from "@hookform/resolvers/zod";
import { Activity,FileText, HardDrive, Settings2 } from "lucide-react";
import { useMemo } from "react";
import { Controller, type Resolver, useForm } from "react-hook-form";
import * as z from "zod";

import { documentTypesApi } from "@/api/document-types";
import { 
