import { zodResolver } from "@hookform/resolvers/zod";
import { Barcode, Hash, MapPin, Package, StickyNote, Wrench } from "lucide-react";
import { useMemo } from "react";
import { type Resolver, useForm } from "react-hook-form";
import * as z from "zod";

import { itemApi, type ItemDto } from "@/api/inventory/items";
import {
    BaseFormDialog,
    FormField,
    FormSection,
    Input,
    NativeSelect,
    Textarea
} from "@/components/ui";
import { useApiMutation } from "@/hooks";

const itemSchema = z.object({
    itemName: z.string().trim().min(2, "اسم الصنف مطلوب"),
    itemCode: z.string().trim().min(1, "كود الصنف مطلوب"),
    description: z.string().trim().optional().nullable().or(z.literal("")),
    unit: z.string().trim().min(1, "وحدة القياس مطلوبة"),
    quantity: z.coerce.number().int().min(0, "الكمية لا يمكن أن تكون سالبة").default(0),
    minimumQuantity: z.coerce.number().int().min(0).default(0),
    condition: z.coerce.number().int().min(0).default(0),
    location: z.string().trim().optional().nullable().or(z.literal("")),
    serialNumber: z.string().trim().optional().nullable().or(z.literal("")),
    notes: z.string().trim().optional().nullable().or(z.literal("")),
});

type ItemFormValues = z.infer<typeof itemSchema>;

interface Props {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onSaved: () => void;
    item: ItemDto | null;
}

export function InventoryItemFormDialog({ open, onOpenChange, onSaved, item }: Props) {
    const isEdit = !!item;

    const mutation = useApiMutation(
        (values: ItemFormValues) => isEdit
            ? itemApi.update(item!.inventoryItemID, values)
            : itemApi.create(values),
        {
            successMessage: isEdit ? "تم تحديث الصنف بنجاح" : "تم إضافة الصنف الجديد بنجاح",
            onSuccessCallback: () => { onSaved(); onOpenChange(false); }
        }
    );

    const form = useForm<ItemFormValues>({
        resolver: zodResolver(itemSchema) as Resolver<z.infer<typeof itemSchema>>,
        defaultValues: {
            itemName: "", itemCode: "", description: "",
            unit: "قطعة", quantity: 0, minimumQuantity: 0, condition: 0, location: "",
            serialNumber: "", notes: ""
        },
    });

    const { register, handleSubmit, reset, formState: { errors, isDirty }, setValue, watch } = form;

    const onSubmit = (values: ItemFormValues) => mutation.mutate(values);

    const initialValues = useMemo(() => {
        if (!item) return {
            itemName: "", itemCode: "", description: "",
            unit: "قطعة", quantity: 0, minimumQuantity: 0, condition: 0, location: "",
            serialNumber: "", notes: ""
        };
        return {
            itemName: item.itemName,
            itemCode: item.itemCode,
            description: item.description || "",
            unit: item.unit,
            quantity: item.quantity,
            minimumQuantity: item.minimumQuantity,
            condition: item.condition,
            location: item.location || "",
            serialNumber: item.serialNumber || "",
            notes: item.notes || "",
        };
    }, [item]);

    return (
        <BaseFormDialog
            open={open}
            onOpenChange={onOpenChange}
            title={isEdit ? "تعديل الصنف" : "إضافة صنف جديد"}
            description="إدارة الأصول والمخزون"
            size="lg"
            isLoading={mutation.isPending}
            isDirty={isDirty}
            onSubmit={handleSubmit(onSubmit)}
            resetOnOpen={false}
            reset={reset}
            initialValues={initialValues}
            showGlobalError
            formErrors={errors}
            submitLabel={isEdit ? "حفظ التعديلات" : "إضافة الصنف"}
        >
            <div className="space-y-4">
                <FormSection title="البيانات الأساسية" icon={Package}>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <FormField label="اسم الصنف" required error={errors.itemName?.message}>
                            <Input {...register("itemName")} placeholder="اسم الصنف" icon={Package} />
                        </FormField>
                        <FormField label="كود الصنف" required error={errors.itemCode?.message}>
                            <Input {...register("itemCode")} placeholder="رقم فريد" icon={Hash} className="font-mono" />
                        </FormField>
                        <FormField label="وحدة القياس" required error={errors.unit?.message}>
                            <Input {...register("unit")} placeholder="قطعة، علبة، رزمة..." />
                        </FormField>
                        <FormField label="حالة الصنف" error={errors.condition?.message}>
                            <NativeSelect
                                options={[
                                    { value: "0", label: "جديد" },
                                    { value: "1", label: "مستعمل" },
                                ]}
                                value={watch("condition")}
                                onChange={(val) => setValue("condition", Number(val), { shouldValidate: true })}
                                icon={Wrench}
                            />
                        </FormField>
                        <FormField label="الكمية الحالية" error={errors.quantity?.message}>
                            <Input {...register("quantity")} type="number" icon={Package} />
                        </FormField>
                        <FormField label="الحد الأدنى" error={errors.minimumQuantity?.message}>
                            <Input {...register("minimumQuantity")} type="number" />
                        </FormField>
                        <FormField label="الموقع" error={errors.location?.message}>
                            <Input {...register("location")} placeholder="مستودع، مكتب..." icon={MapPin} />
                        </FormField>
                        <FormField label="الرقم التسلسلي" error={errors.serialNumber?.message}>
                            <Input {...register("serialNumber")} placeholder="للأجهزة" icon={Barcode} className="font-mono" />
                        </FormField>
                    </div>
                </FormSection>

                <FormSection title="ملاحظات" icon={StickyNote}>
                    <FormField label="الوصف" error={errors.description?.message}>
                        <Textarea {...register("description")} placeholder="وصف الصنف..." rows={2} />
                    </FormField>
                    <FormField label="ملاحظات" error={errors.notes?.message}>
                        <Textarea {...register("notes")} placeholder="ملاحظات إضافية..." rows={2} />
                    </FormField>
                </FormSection>
            </div>
        </BaseFormDialog>
    );
}

import { zodResolver } from "@hookform/resolvers/zod";
import { Calendar, Coins, FileText, Hash, Network, StickyNote } from "lucide-react";
import { useMemo } from "react";
import { type Resolver, useForm } from "react-hook-form";
import * as z from "zod";

import { transactionApi } from "@/api/inventory/transactions";
import {
    BaseFormDialog,
    FormField,
    FormSection,
    Input,
    NativeSelect,
    Textarea
} from "@/components/ui";
import { useApiMutation } from "@/hooks";

const transactionSchema = z.object({
    transactionType: z.coerce.number().int().min(0, "نوع الحركة مطلوب"),
    quantity: z.coerce.number().int().min(1, "الكمية يجب أن تكون 1 على الأقل"),
    unitCost: z.coerce.number().min(0).optional().nullable(),
    currency: z.string().trim().optional().nullable().or(z.literal("")),
    withdrawalOrderNumber: z.string().trim().optional().nullable().or(z.literal("")),
    invoiceNumber: z.string().trim().optional().nullable().or(z.literal("")),
    referenceNumber: z.string().trim().optional().nullable().or(z.literal("")),
    reason: z.string().trim().optional().nullable().or(z.literal("")),
    transactionDate: z.string().min(1, "تاريخ الحركة مطلوب"),
});

type TransactionFormValues = z.infer<typeof transactionSchema>;

const typeOptions = [
    { value: "0", label: "إدخال (شراء)" },
    { value: "1", label: "إخراج (صرف)" },
    { value: "2", label: "نقل" },
    { value: "3", label: "إتلاف" },
    { value: "4", label: "تسوية جرد" },
];

interface Props {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onSaved: () => void;
    transaction: unknown;
    itemId: number;
}

export function InventoryTransactionFormDialog({ open, onOpenChange, onSaved, itemId }: Props) {
    const mutation = useApiMutation(
        (values: TransactionFormValues) => transactionApi.create({
            ...values,
            inventoryItemID: itemId,
        }),
        {
            successMessage: "تم إضافة الحركة بنجاح",
            onSuccessCallback: () => { onSaved(); onOpenChange(false); }
        }
    );

    const form = useForm<TransactionFormValues>({
        resolver: zodResolver(transactionSchema) as Resolver<z.infer<typeof transactionSchema>>,
        defaultValues: {
            transactionType: 0, quantity: 1, unitCost: null, currency: "SAR",
            withdrawalOrderNumber: "", invoiceNumber: "",
            referenceNumber: "", reason: "",
            transactionDate: new Date().toISOString().split('T')[0]
        },
    });

    const { register, handleSubmit, reset, formState: { errors, isDirty }, setValue, watch } = form;

    const onSubmit = (values: TransactionFormValues) => mutation.mutate(values);

    const initialValues = useMemo(() => ({
        transactionType: 0, quantity: 1, unitCost: null, currency: "SAR",
        withdrawalOrderNumber: "", invoiceNumber: "",
        referenceNumber: "", reason: "",
        transactionDate: new Date().toISOString().split('T')[0]
    }), []);

    const transactionType = watch("transactionType");

    return (
        <BaseFormDialog
            open={open}
            onOpenChange={onOpenChange}
            title="إضافة حركة مخزون"
            description="تسجيل حركة على الصنف المحدد"
            size="md"
            isLoading={mutation.isPending}
            isDirty={isDirty}
            onSubmit={handleSubmit(onSubmit)}
            resetOnOpen={false}
            reset={reset}
            initialValues={initialValues}
            showGlobalError
            formErrors={errors}
            submitLabel="تسجيل الحركة"
        >
            <div className="space-y-4">
                <FormSection title="بيانات الحركة">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <FormField label="نوع الحركة" required error={errors.transactionType?.message}>
                            <NativeSelect
                                options={typeOptions}
                                placeholder="اختر النوع..."
                                value={form.watch("transactionType")}
                                onChange={(val) => setValue("transactionType", Number(val), { shouldValidate: true })}
                            />
                        </FormField>
                        <FormField label="الكمية" required error={errors.quantity?.message}>
                            <Input {...register("quantity")} type="number" min={1} />
                        </FormField>
                        <FormField label="تكلفة الوحدة" error={errors.unitCost?.message}>
                            <Input {...register("unitCost")} type="number" step="0.01" min={0} placeholder="0.00" icon={Coins} />
                        </FormField>
                        <FormField label="العملة" error={errors.currency?.message}>
                            <Input {...register("currency")} placeholder="SAR" maxLength={3} icon={Network} className="font-mono" />
                        </FormField>
                        {transactionType === 1 && (
                            <FormField label="رقم أمر الصرف" error={errors.withdrawalOrderNumber?.message}>
                                <Input {...register("withdrawalOrderNumber")} placeholder="رقم أمر الصرف" icon={FileText} className="font-mono" />
                            </FormField>
                        )}
                        <FormField label="رقم الفاتورة" error={errors.invoiceNumber?.message}>
                            <Input {...register("invoiceNumber")} placeholder="رقم فاتورة الشراء" icon={FileText} className="font-mono" />
                        </FormField>
                        <FormField label="الرقم المرجعي" error={errors.referenceNumber?.message}>
                            <Input {...register("referenceNumber")} placeholder="أمر شراء، محضر..." icon={Hash} className="font-mono" />
                        </FormField>
                        <FormField label="تاريخ الحركة" required error={errors.transactionDate?.message}>
                            <Input {...register("transactionDate")} type="date" icon={Calendar} />
                        </FormField>
                    </div>
                </FormSection>

                <FormSection title="السبب" icon={StickyNote}>
                    <FormField label="السبب" error={errors.reason?.message}>
                        <Textarea {...register("reason")} placeholder="سبب الحركة..." rows={2} />
                    </FormField>
                </FormSection>
            </div>
        </BaseFormDialog>
    );
}

import { zodResolver } from "@hookform/resolvers/zod";
import { Calculator, FileText,User } from "lucide-react";
import { Controller,useForm } from "react-hook-form";
import * as z from "zod";

import { investmentApi } from "@/api/investment";
import { 
    BaseFormDialog, 
    DateInput,
    FormField, 
    FormSection,
    Input,
    NoteBox,
    Textarea} from "@/components/ui";
import { useApiMutation } from "@/hooks";

const schema = z.object({
    description: z.string().min(2, "الوصف مطلوب"),
    amount: z.number().positive("المبلغ يجب أن يكون موجباً"),
    costDate: z.string().min(1, "التاريخ مطلوب"),
    vendor: z.string().optional().or(z.literal("")),
    notes: z.string().optional().or(z.literal("")),
});

type FormValues = z.infer<typeof schema>;

interface Props {
    open?: boolean;
    isOpen?: boolean;
    onOpenChange?: (open: boolean) => void;
    onClose?: () => void;
    ticketId: number;
}

/**
 * Standardized AddCostDialog.
 * Refactored to use BaseFormDialog and FormSection for maintenance cost tracking.
 */
export function AddCostDialog({ 
    open, 
    isOpen,
    onOpenChange,
    onClose, 
    ticketId 
}: Props) {
    const form = useForm<FormValues>({ 
        resolver: zodResolver(schema), 
        defaultValues: { 
            description: "", 
            amount: 0, 
            costDate: new Date().toISOString().split('T')[0], 
            vendor: "", 
            notes: "" 
        } 
    });

    const { register, handleSubmit, reset, formState: { errors, isDirty } } = form;

    const mutation = useApiMutation(
        (v: FormValues) => investmentApi.addMaintenanceCost(ticketId, v),
        {
            successMessage: "تم تسجيل التكلفة بنجاح",
            invalidateKeys: [["maintenance-request", ticketId]],
            onSuccess: () => { 
                if (onOpenChange) onOpenChange(false);
                else if (onClose) onClose(); 
            }
        }
    );

    return (
        <BaseFormDialog 
            open={open}
            isOpen={isOpen} 
            onOpenChange={onOpenChange}
            onClose={onClose} 
            title="إضافة تكلفة صيانة" 
            description="تسجيل المصاريف الفعلية المرتبطة ببلاغ الصيانة"
            size="lg" 
            isLoading={mutation.isPending} 
            isDirty={isDirty}
            onSubmit={handleSubmit((v) => mutation.mutate(v))} 
            submitLabel="اعتماد التكلفة"
            resetOnOpen
            reset={reset}
            showGlobalError
            formErrors={errors}
        >
            <div className="space-y-4">
                <FormSection title="البيانات المالية" icon={Calculator}>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <FormField label="المبلغ المنصرف (ر.ي)" error={errors.amount?.message} required>
                            <Input {...register("amount", { valueAsNumber: true })} type="number" step="0.01" className="font-mono font-bold text-lg text-primary" />
                        </FormField>
                        <FormField label="تاريخ الصرف" error={errors.costDate?.message} required>
                            <Controller
                                name="costDate"
                                control={form.control}
                                render={({ field }) => (
                                    <DateInput
                                        id={field.name}
                                        value={field.value || undefined}
                                        onChange={field.onChange}
                                        className="font-mono"
                                    />
                                )}
                            />
                        </FormField>
                    </div>
                </FormSection>

                <FormSection title="تفاصيل الصرف والمورد" icon={User}>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <FormField label="بيان التكلفة / الخدمة" error={errors.description?.message} required>
                            <Input {...register("description")} placeholder="مثال: قطع غيار، أجور أيدي عاملة..." />
                        </FormField>
                        <FormField label="اسم المورد / الفني" error={errors.vendor?.message}>
                            <Input {...register("vendor")} placeholder="الجهة المنفذة للخدمة" />
                        </FormField>
                    </div>
                </FormSection>

                <FormSection title="الملاحظات" icon={FileText}>
                    <div className="grid grid-cols-1 gap-4">
                        <FormField label="ملاحظات إضافية" error={errors.notes?.message}>
                            <Textarea {...register("notes")} rows={2} placeholder="أي تفاصيل أخرى حول هذه التكلفة..." />
                        </FormField>
                    </div>
                </FormSection>

                <NoteBox type="info">
                    سيتم ترحيل هذه التكلفة لتضاف إلى إجمالي مصاريف الصيانة الخاصة بالعقار المرتبط.
                </NoteBox>
            </div>
        </BaseFormDialog>
    );
}

import { zodResolver } from "@hookform/resolvers/zod";
import { useQuery } from "@tanstack/react-query";
import { Calendar, DollarSign, Users } from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";
import { Controller, useForm } from "react-hook-form";
import * as z from "zod";

import { investmentApi, type LeaseContractDto } from "@/api/investment";
import {
    BaseFormDialog,
    DateInput,
    FileField,
    FormField,
    FormSection,
    Input,
    NativeSelect,
    Textarea
} from "@/components/ui";
import { useApiMutation } from "@/hooks";

// ─── Validation Schema ─────────────────────────────────

const contractSchema = z.object({
    unitID: z.number().min(1, "يجب تحديد الوحدة المؤجرة"),
    tenantID: z.number().min(1, "يجب تحديد المستأجر"),
    startDate: z.string().min(1, "تاريخ بداية العقد مطلوب"),
    endDate: z.string().min(1, "تاريخ نهاية العقد مطلوب"),
    totalContractValue: z.number().positive("قيمة العقد يجب أن تكون رقماً موجباً"),
    paymentFrequency: z.string().min(1, "دورية السداد مطلوبة"),
    notes: z.string().trim().optional(),
    contractFile: z.instanceof(File).optional().nullable(),
    generateSchedules: z.boolean(),
});

export type ContractFormValues = z.infer<typeof contractSchema>;

// ─── Props ─────────────────────────────────────────────

interface ContractFormDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    initialData?: Partial<LeaseContractDto>;
    mode: "create" | "edit";
    onSuccess?: () => void;
    propertyId?: number;
}

// ─── Component ─────────────────────────────────────────

export function ContractDialog({
    open,
    onOpenChange,
    initialData,
    mode,
    onSuccess,
    propertyId
}: ContractFormDialogProps) {
    // ─── Fresh data in edit mode ────────────────────────
    const editId = mode === "edit" ? initialData?.contractID : undefined;
    const { data: freshData } = useQuery({
        queryKey: ["contract", editId],
        queryFn: () => investmentApi.getContract(editId!),
        enabled: !!editId && open,
    });

    const effectiveData = useMemo(() => {
        if (mode === "edit" && freshData) return freshData as LeaseContractDto;
        return initialData;
    }, [mode, freshData, initialData]);

    // ─── Lookups ────────────────────────────────────────
    const { data: allUnits = [], isLoading: unitsLoading } = useQuery({
        queryKey: ["all-units"],
        queryFn: () => investmentApi.getAllUnits(),
        enabled: open,
    });

    const { data: allProperties = [], isLoading: propertiesLoading } = useQuery({
        queryKey: ["properties"],
        queryFn: () => investmentApi.getAllProperties(),
        enabled: open,
    });

    const { data: tenantsRes = [], isLoading: tenantsLoading } = useQuery({
        queryKey: ["tenants"],
        queryFn: () => investmentApi.getTenants(),
        enabled: open,
    });

    // فلتر العقار المحدد محلياً
    const [selectedPropertyId, setSelectedPropertyId] = useState<string>(String(propertyId || ""));

    useEffect(() => {
        if (propertyId) setSelectedPropertyId(String(propertyId));
    }, [propertyId]);

    const propertiesOptions = allProperties.map(p => ({
        label: p.propertyName,
        value: String(p.propertyID)
    }));

    const unitsOptions = (() => {
        if (!allUnits) return [];
        const filtered = selectedPropertyId
            ? allUnits.filter(u => u.propertyID === Number(selectedPropertyId))
            : allUnits;
        return filtered.map(u => ({
            label: u.propertyName ? `${u.propertyName} - ${u.unitNumber}` : u.unitNumber,
            value: String(u.unitID)
        }));
    })();

    const tenantsOptions = tenantsRes.map(t => ({
        label: t.fullName,
        value: String(t.tenantID)
    }));

    // ─── Form ───────────────────────────────────────────
    const form = useForm<ContractFormValues>({
        resolver: zodResolver(contractSchema),
        defaultValues: useMemo(() => ({
            unitID: 0,
            tenantID: 0,
            startDate: new Date().toISOString().split('T')[0],
            endDate: "",
            totalContractValue: 0,
            paymentFrequency: "Monthly",
            notes: "",
            contractFile: null,
            generateSchedules: true,
        }), []),
    });

    const { register, control, reset, formState: { errors, isDirty } } = form;

    // ─── Initial values for BaseFormDialog reset ────────
    const initialValues = useMemo(() => {
        const data = effectiveData;
        if (!data) return undefined;
        return {
            unitID: data.unitID || 0,
            tenantID: data.tenantID || 0,
            startDate: data.startDate?.split('T')[0] || "",
            endDate: data.endDate?.split('T')[0] || "",
            totalContractValue: data.totalContractValue || 0,
            paymentFrequency: data.paymentFrequency || "Monthly",
            notes: "",
            contractFile: null,
            generateSchedules: true,
        };
    }, [effectiveData]);

    // ─── Mutation ───────────────────────────────────────
    const mutation = useApiMutation(
        async (values: ContractFormValues) => {
            const { contractFile, ...dto } = values;
            let res: number;
            if (mode === "create") {
                res = await investmentApi.createContract(dto);
            } else {
                res = await investmentApi.updateContract(effectiveData!.contractID!, dto) as unknown as number;
            }
            if (res && contractFile instanceof File) {
                await investmentApi.uploadSignedContract(res, contractFile);
            }
            return res;
        },
        {
            successMessage: mode === "create" ? "تم إنشاء العقد بنجاح" : "تم تحديث العقد بنجاح",
            invalidateKeys: [
                ["contracts"],
                ["property-contracts", propertyId],
                ["schedules"],
            ],
            onSuccess: () => {
                onOpenChange(false);
                onSuccess?.();
            },
        }
    );

    const handleFormSubmit = useCallback((values: ContractFormValues) => {
        mutation.mutate(values);
    }, [mutation]);

    return (
        <BaseFormDialog
            open={open}
            onOpenChange={onOpenChange}
            title={mode === "create" ? "إنشاء عقد إيجار جديد" : "تعديل عقد إيجار"}
            description="إدارة عقود الإيجار للوحدات العقارية وربطها بالمستأجرين"
            size="2xl"
            isLoading={mutation.isPending || unitsLoading || propertiesLoading || tenantsLoading}
            isDirty={isDirty}
            onSubmit={form.handleSubmit(handleFormSubmit)}
            resetOnOpen={true}
            reset={reset}
            initialValues={initialValues}
            showGlobalError
            formErrors={errors}
            submitLabel={mode === "create" ? "إنشاء العقد" : "حفظ التعديلات"}
        >
            <div className="space-y-4 text-start">
                <FormSection title="أطراف العقد" icon={Users}>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <FormField label="العقار">
                            <NativeSelect
                                options={propertiesOptions}
                                value={selectedPropertyId}
                                onChange={(v) => {
                                    setSelectedPropertyId(v);
                                }}
                                placeholder="كل العقارات..."
                            />
                        </FormField>
                        <FormField label="الوحدة المؤجرة" required error={errors.unitID?.message}>
                            <Controller
                                name="unitID"
                                control={control}
                                render={({ field }) => (
                                    <NativeSelect
                                        options={unitsOptions}
                                        value={String(field.value)}
                                        onChange={(v) => field.onChange(Number(v))}
                                        placeholder="اختر الوحدة..."
                                    />
                                )}
                            />
                        </FormField>
                        <FormField label="المستأجر" required error={errors.tenantID?.message}>
                            <Controller
                                name="tenantID"
                                control={control}
                                render={({ field }) => (
                                    <NativeSelect
                                        options={tenantsOptions}
                                        value={String(field.value)}
                                        onChange={(v) => field.onChange(Number(v))}
                                        placeholder="اختر المستأجر..."
                                    />
                                )}
                            />
                        </FormField>
                    </div>
                </FormSection>

                <FormSection title="الشروط المالية والجدولة" icon={DollarSign}>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <FormField label="قيمة العقد الإجمالية" required error={errors.totalContractValue?.message}>
                            <Input type="number" {...register("totalContractValue", { valueAsNumber: true })} placeholder="0.00" className="font-mono" />
                        </FormField>
                        <FormField label="دورية السداد" required error={errors.paymentFrequency?.message}>
                            <Controller
                                name="paymentFrequency"
                                control={control}
                                render={({ field }) => (
                                    <NativeSelect
                                        options={[
                                            { label: "شهري", value: "Monthly" },
                                            { label: "ربع سنوي", value: "Quarterly" },
                                            { label: "نصف سنوي", value: "SemiAnnually" },
                                            { label: "سنوي", value: "Annually" },
                                        ]}
                                        value={field.value}
                                        onChange={field.onChange}
                                    />
                                )}
                            />
                        </FormField>
                    </div>

                    {mode === "create" && (
                        <div className="mt-4 p-3 bg-muted/30 rounded-lg flex items-center gap-3">
                            <Controller
                                name="generateSchedules"
                                control={control}
                                render={({ field }) => (
                                    <input
                                        type="checkbox"
                                        id="generateSchedules"
                                        checked={field.value}
                                        onChange={field.onChange}
                                        className="w-4 h-4 rounded border-input text-primary focus:ring-primary"
                                    />
                                )}
                            />
                            <label htmlFor="generateSchedules" className="text-sm font-medium cursor-pointer select-none">
                                توليد جدول الدفعات تلقائياً بناءً على دورية السداد وقيمة العقد
                            </label>
                        </div>
                    )}
                </FormSection>

                <FormSection title="المدة الزمنية ومرفق العقد" icon={Calendar}>
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                        <FormField label="تاريخ بداية العقد" required error={errors.startDate?.message}>
                            <Controller
                                name="startDate"
                                control={control}
                                render={({ field }) => (
                                    <DateInput
                                        id={field.name}
                                        value={field.value || undefined}
                                        onChange={field.onChange}
                                        className="font-mono"
                                    />
                                )}
                            />
                        </FormField>
                        <FormField label="تاريخ نهاية العقد" required error={errors.endDate?.message}>
                            <Controller
                                name="endDate"
                                control={control}
                                render={({ field }) => (
                                    <DateInput
                                        id={field.name}
                                        value={field.value || undefined}
                                        onChange={field.onChange}
                                        className="font-mono"
                                    />
                                )}
                            />
                        </FormField>
                        <div className="lg:col-span-2">
                            <FormField label="ملاحظات العقد (اختياري)" error={errors.notes?.message}>
                                <Textarea {...register("notes")} placeholder="بنود خاصة أو ملاحظات..." rows={1} />
                            </FormField>
                        </div>
                    </div>
                    <div className="grid grid-cols-1 gap-4 mt-4 text-start">
                        <FileField name="contractFile" control={control} label="نسخة العقد الممسوحة ضوئياً" size="sm" />
                    </div>
                </FormSection>
            </div>
        </BaseFormDialog>
    );
}

