import { zodResolver } from "@hookform/resolvers/zod";
import { useQuery } from "@tanstack/react-query";
import { AlertOctagon, Building2, FileText, Wrench } from "lucide-react";
import { useCallback, useMemo } from "react";
import { Controller, type Resolver, useForm } from "react-hook-form";
import * as z from "zod";

import { investmentApi, type MaintenanceRequestDto } from "@/api/investment";
import {
    BaseFormDialog,
    FormField,
    FormSection,
    NativeSelect,
    NoteBox,
    Textarea
} from "@/components/ui";
import { useApiMutation } from "@/hooks";

// ─── Validation Schema ─────────────────────────────────

const schema = z.object({
    propertyID: z.number().min(1, "العقار مطلوب"),
    unitID: z.number().optional().nullable(),
    description: z.string().min(5, "وصف المشكلة مطلوب (5 أحرف على الأقل)"),
    priority: z.string().min(1, "الأولوية مطلوبة"),
});

export type MaintenanceFormValues = z.infer<typeof schema>;

// ─── Props ─────────────────────────────────────────────

interface MaintenanceRequestFormDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    initialData?: Partial<MaintenanceRequestDto>;
    mode: "create" | "edit";
    onSuccess?: () => void;
    propertyId?: number;
}

// ─── Component ─────────────────────────────────────────

export function MaintenanceRequestDialog({
    open,
    onOpenChange,
    initialData,
    mode,
    onSuccess,
    propertyId
}: MaintenanceRequestFormDialogProps) {
    // ─── Fresh data in edit mode ────────────────────────
    const editId = mode === "edit" ? initialData?.requestID : undefined;
    const { data: freshData } = useQuery({
        queryKey: ["maintenance-request", editId],
        queryFn: () => investmentApi.getRequest(editId!),
        enabled: !!editId && open,
    });

    const effectiveData = useMemo(() => {
        if (mode === "edit" && freshData) return freshData as MaintenanceRequestDto;
        return initialData;
    }, [mode, freshData, initialData]);

    // ─── Lookups ────────────────────────────────────────
    const effectivePropertyId = effectiveData?.propertyID || propertyId || 0;

    const { data: properties = [] } = useQuery({
        queryKey: ["investment", "properties-simple"],
        queryFn: () => investmentApi.getProperties(),
        enabled: open,
    });

    const { data: units = [] } = useQuery({
        queryKey: ["investment", "units", effectivePropertyId],
        queryFn: () => investmentApi.getUnits(effectivePropertyId),
        enabled: open && !!effectivePropertyId,
    });

    // ─── Form ───────────────────────────────────────────
    const form = useForm<MaintenanceFormValues>({
        resolver: zodResolver(schema) as Resolver<z.infer<typeof schema>>,
        defaultValues: useMemo(() => ({
            propertyID: propertyId || 0,
            unitID: null,
            description: "",
            priority: "Medium",
        }), [propertyId]),
    });

    const { register, control, watch, reset, formState: { errors, isDirty } } = form;
    const selectedPropertyID = watch("propertyID");

    const initialValues = useMemo(() => {
        const data = effectiveData;
        if (!data) return undefined;
        return {
            propertyID: data.propertyID || propertyId || 0,
            unitID: data.unitID || null,
            description: data.description || "",
            priority: data.priority || "Medium",
        };
    }, [effectiveData, propertyId]);

    // ─── Mutation ───────────────────────────────────────
    const mutation = useApiMutation(
        async (values: MaintenanceFormValues) => {
            if (mode === "create") {
                return investmentApi.createRequest({ ...values, propertyID: values.propertyID || propertyId });
            }
            return investmentApi.updateRequest(effectiveData!.requestID!, values);
        },
        {
            successMessage: mode === "create" ? "تم تسجيل بلاغ الصيانة بنجاح" : "تم تحديث بلاغ الصيانة",
            invalidateKeys: [
                ["property-maintenance", (propertyId as number) ?? 0],
                ["maintenance-requests-all"],
                ["maintenance-request", editId],
            ],
            onSuccess: () => {
                onOpenChange(false);
                onSuccess?.();
            },
        }
    );

    const handleFormSubmit = useCallback((values: MaintenanceFormValues) => {
        mutation.mutate(values);
    }, [mutation]);

    return (
        <BaseFormDialog
            open={open}
            onOpenChange={onOpenChange}
            title={mode === "create" ? "تسجيل بلاغ صيانة جديد" : "تعديل بلاغ صيانة"}
            description="إرسال طلب صيانة أو إصلاح لمرافق العقارات التابعة للصندوق"
            size="xl"
            isLoading={mutation.isPending}
            isDirty={isDirty}
            onSubmit={form.handleSubmit(handleFormSubmit)}
            resetOnOpen={true}
            reset={reset}
            initialValues={initialValues}
            showGlobalError
            formErrors={errors}
            submitLabel={mode === "create" ? "تسجيل البلاغ" : "حفظ التعديلات"}
        >
            <div className="space-y-4 text-start">
                <FormSection title="تحديد الموقع" icon={Building2}>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <FormField label="العقار المرتبط" error={errors.propertyID?.message} required>
                            <Controller
                                name="propertyID"
                                control={control}
                                render={({ field }) => (
                                    <NativeSelect
                                        value={String(field.value)}
                                        onChange={(v) => field.onChange(Number(v))}
                                        options={properties.map((p) => ({
                                            value: String(p.propertyID),
                                            label: p.propertyName
                                        }))}
                                        placeholder="اختر العقار..."
                                    />
                                )}
                            />
                        </FormField>
                        <FormField label="الوحدة (اختياري)" error={errors.unitID?.message}>
                            <Controller
                                name="unitID"
                                control={control}
                                render={({ field }) => (
                                    <NativeSelect
                                        value={field.value ? String(field.value) : ""}
                                        onChange={(v) => field.onChange(v ? Number(v) : null)}
                                        options={
                                            units.map((u) => ({
                                                value: String(u.unitID),
                                                label: u.unitNumber || `Unit ${u.unitID}`,
                                            }))
                                        }
                                        placeholder="اختر الوحدة..."
                                        disabled={!selectedPropertyID}
                                    />
                                )}
                            />
                        </FormField>
                    </div>
                </FormSection>

                <FormSection title="تفاصيل المشكلة والأولوية" icon={Wrench}>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <FormField label="درجة الأهمية" error={errors.priority?.message} required>
                            <Controller
                                name="priority"
                                control={control}
                                render={({ field }) => (
                                    <NativeSelect
                                        {...field}
                                        options={[
                                            { value: "Low", label: "منخفض" },
                                            { value: "Medium", label: "متوسط" },
                                            { value: "High", label: "مرتفع" },
                                            { value: "Urgent", label: "عاجل جداً" }
                                        ]}
                                        icon={AlertOctagon}
                                    />
                                )}
                            />
                        </FormField>

                        <div className="md:col-span-2">
                            <FormField label="وصف العطل / الطلب" error={errors.description?.message} required icon={FileText}>
                                <Textarea
                                    {...register("description")}
                                    rows={2}
                                    placeholder="يرجى وصف المشكلة بالتفصيل وموقعها الدقيق في العقار..."
                                    className="leading-relaxed"
                                />
                            </FormField>
                        </div>
                    </div>
                </FormSection>

                <NoteBox type="info">
                    سيتم إرسال هذا البلاغ مباشرة إلى قسم الصيانة والخدمات الفنية للمراجعة والتكليف.
                </NoteBox>
            </div>
        </BaseFormDialog>
    );
}

import { zodResolver } from "@hookform/resolvers/zod";
import { useQuery } from "@tanstack/react-query";
import { Activity, Briefcase, DollarSign, User } from "lucide-react";
import { useCallback, useMemo } from "react";
import { Controller, useForm } from "react-hook-form";
import * as z from "zod";

import api from "@/api/axios";
import { investmentApi, type PortfolioDto } from "@/api/investment";
import {
    BaseFormDialog,
    FormField,
    FormSection,
    Input,
    NativeSelect,
    NoteBox,
    Textarea
} from "@/components/ui";
import { useApiMutation } from "@/hooks";

// ─── Validation Schema ─────────────────────────────────

const portfolioSchema = z.object({
    name: z.string().trim().min(3, "اسم المحفظة يجب أن يكون 3 أحرف على الأقل"),
    description: z.string().trim().optional(),
    managerUserID: z.number().min(1, "يجب تحديد المدير المسؤول"),
    totalTargetCapital: z.number().positive("رأس المال المستهدف يجب أن يكون مبلغاً موجباً"),
    status: z.enum(["Active", "Inactive", "Closed"]),
});

type PortfolioFormValues = z.infer<typeof portfolioSchema>;

// ─── Types ─────────────────────────────────────────────



// ─── Props ─────────────────────────────────────────────

interface PortfolioFormDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    initialData?: Partial<PortfolioDto>;
    mode: "create" | "edit";
    onSuccess?: () => void;
}

// ─── Component ─────────────────────────────────────────

export function PortfolioDialog({
    open,
    onOpenChange,
    initialData,
    mode,
    onSuccess
}: PortfolioFormDialogProps) {
    // ─── Fresh data in edit mode ────────────────────────
    const editId = mode === "edit" ? initialData?.portfolioID : undefined;
    const { data: freshData } = useQuery({
        queryKey: ["portfolio", editId],
        queryFn: () => investmentApi.getPortfolio(editId!),
        enabled: !!editId && open,
    });

    const effectiveData = useMemo(() => {
        if (mode === "edit" && freshData) return freshData as PortfolioDto;
        return initialData;
    }, [mode, freshData, initialData]);

    // ─── Lookups ────────────────────────────────────────
    const { data: users = [] } = useQuery({
        queryKey: ["users-lookup"],
        queryFn: () => api.get<{ id: number; fullName: string }[]>("/users").then(r => r.data.map(u => ({ id: u.id, name: u.fullName }))),
        staleTime: 5 * 60 * 1000,
        enabled: open,
    });

    // ─── Form ───────────────────────────────────────────
    const form = useForm<PortfolioFormValues>({
        resolver: zodResolver(portfolioSchema),
        defaultValues: useMemo(() => ({
            name: "",
            description: "",
            managerUserID: 0,
            totalTargetCapital: 0,
            status: "Active" as const,
        }), []),
    });

    const { register, control, reset, formState: { errors, isDirty } } = form;

    const initialValues = useMemo(() => {
        const data = effectiveData;
        if (!data) return undefined;
        return {
            name: data.name || "",
            description: data.description || "",
            managerUserID: data.managerUserID || 0,
            totalTargetCapital: data.totalTargetCapital || 0,
            status: (data as any).status || "Active",
        };
    }, [effectiveData]);

    // ─── Mutation ───────────────────────────────────────
    const mutation = useApiMutation(
        async (values: PortfolioFormValues) => {
            if (mode === "create") {
                return investmentApi.createPortfolio(values);
            }
            return investmentApi.updatePortfolio(effectiveData!.portfolioID!, {
                ...values,
                status: (effectiveData as any)?.status || "Active",
            });
        },
        {
            successMessage: mode === "create" ? "تم إنشاء المحفظة بنجاح" : "تم تحديث المحفظة بنجاح",
            invalidateKeys: [
                ["portfolios"],
                ["portfolio", editId],
                ["portfolio-summary"],
            ],
            onSuccess: () => {
                onOpenChange(false);
                onSuccess?.();
            },
        }
    );

    const handleFormSubmit = useCallback((values: PortfolioFormValues) => {
        mutation.mutate(values);
    }, [mutation]);

    return (
        <BaseFormDialog
            open={open}
            onOpenChange={onOpenChange}
            title={mode === "create" ? "إنشاء محفظة جديدة" : "تعديل محفظة استثمارية"}
            description="إدارة المحافظ الاستثمارية الكبرى وتحديد رؤوس الأموال المستهدفة"
            size="xl"
            isLoading={mutation.isPending}
            isDirty={isDirty}
            onSubmit={form.handleSubmit(handleFormSubmit)}
            resetOnOpen={true}
            reset={reset}
            initialValues={initialValues}
            showGlobalError
            formErrors={errors}
            submitLabel={mode === "create" ? "إنشاء المحفظة" : "حفظ التغييرات"}
        >
            <div className="space-y-4 text-start">
                <FormSection title="البيانات الأساسية للمحفظة" icon={Briefcase}>
                    <div className="grid grid-cols-1 gap-4">
                        <FormField label="اسم المحفظة الاستثمارية" required error={errors.name?.message}>
                            <Input
                                {...register("name")}
                                placeholder="مثال: محفظة التطوير العقاري السكني"
                            />
                        </FormField>
                        <FormField label="وصف أهداف المحفظة" error={errors.description?.message}>
                            <Textarea
                                {...register("description")}
                                placeholder="أدخل تفاصيل حول الأهداف الاستثمارية لهذه المحفظة..."
                                className="min-h-[80px]"
                                rows={2}
                            />
                        </FormField>
                    </div>
                </FormSection>

                <FormSection title="البيانات المالية والإدارية" icon={DollarSign}>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <FormField label="رأس المال المستهدف (ر.ي)" required error={errors.totalTargetCapital?.message}>
                            <Input
                                type="number"
                                step="1000"
                                {...register("totalTargetCapital", { valueAsNumber: true })}
                                placeholder="0.00"
                                className="font-mono text-lg"
                            />
                        </FormField>
                        <FormField label="المدير المسؤول" required error={errors.managerUserID?.message}>
                            <Controller
                                name="managerUserID"
                                control={control}
                                render={({ field }) => (
                                    <NativeSelect
                                        options={users.map(u => ({ label: u.name, value: String(u.id) }))}
                                        value={String(field.value)}
                                        onChange={(v) => field.onChange(Number(v))}
                                        placeholder="اختر المدير..."
                                        icon={User}
                                    />
                                )}
                            />
                        </FormField>
                    </div>
                </FormSection>

                <FormSection title="الحالة التشغيلية" icon={Activity}>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <FormField label="حالة المحفظة" required error={errors.status?.message}>
                            <Controller
                                name="status"
                                control={control}
                                render={({ field }) => (
                                    <NativeSelect
                                        options={[
                                            { label: "نشطة", value: "Active" },
                                            { label: "غير نشطة", value: "Inactive" },
                                            { label: "مغلقة", value: "Closed" }
                                        ]}
                                        value={field.value}
                                        onChange={field.onChange}
                                    />
                                )}
                            />
                        </FormField>
                    </div>
                </FormSection>

                <NoteBox type="warning">
                    تنبيه: سيؤدي إغلاق المحفظة (Closed) إلى إيقاف إمكانية إضافة مشاريع جديدة إليها مستقبلاً.
                </NoteBox>
            </div>
        </BaseFormDialog>
    );
}

import { zodResolver } from "@hookform/resolvers/zod";
import { useQuery } from "@tanstack/react-query";
import { Building, Calendar, DollarSign, FileText } from "lucide-react";
import { useCallback, useMemo } from "react";
import { Controller, useForm } from "react-hook-form";
import * as z from "zod";

import { investmentApi, type ProjectDto } from "@/api/investment";
import {
    BaseFormDialog,
    DateInput,
    FormField,
    FormSection,
    Input,
    NativeSelect,
    Textarea
} from "@/components/ui";
import { useApiMutation } from "@/hooks";

// ─── Validation Schema ─────────────────────────────────

const projectSchema = z.object({
    portfolioID: z.number().min(1, "يجب تحديد المحفظة"),
    typeID: z.number().min(1, "يجب تحديد نوع المشروع"),
    name: z.string().trim().min(3, "اسم المشروع مطلوب"),
    description: z.string().trim().optional(),
    plannedBudget: z.number().positive("الميزانية يجب أن تكون رقماً موجباً"),
    expectedROI: z.number().min(0, "العائد المتوقع يجب أن يكون موجباً"),
    startDate: z.string().min(1, "تاريخ البدء مطلوب"),
    endDate: z.string().optional(),
});

type ProjectFormValues = z.infer<typeof projectSchema>;

// ─── Props ─────────────────────────────────────────────

interface ProjectFormDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    initialData?: Partial<ProjectDto>;
    mode: "create" | "edit";
    onSuccess?: () => void;
}

// ─── Component ─────────────────────────────────────────

export function ProjectDialog({
    open,
    onOpenChange,
    initialData,
    mode,
    onSuccess
}: ProjectFormDialogProps) {
    // ─── Fresh data in edit mode ────────────────────────
    const editId = mode === "edit" ? initialData?.projectID : undefined;
    const { data: freshData } = useQuery({
        queryKey: ["project", editId],
        queryFn: () => investmentApi.getProject(editId!),
        enabled: !!editId && open,
    });

    const effectiveData = useMemo(() => {
        if (mode === "edit" && freshData) return freshData as ProjectDto;
        return initialData;
    }, [mode, freshData, initialData]);

    // ─── Lookups ────────────────────────────────────────
    const { data: portfolios = [] } = useQuery({
        queryKey: ["portfolios-lookup"],
        queryFn: () => investmentApi.getPortfolios(),
        staleTime: 5 * 60 * 1000,
        enabled: open,
    });

    // ─── Form ───────────────────────────────────────────
    const form = useForm<ProjectFormValues>({
        resolver: zodResolver(projectSchema),
        defaultValues: useMemo(() => ({
            portfolioID: 0,
            typeID: 1,
            name: "",
            description: "",
            plannedBudget: 0,
            expectedROI: 0,
            startDate: new Date().toISOString().split("T")[0],
            endDate: "",
        }), []),
    });

    const { register, control, reset, formState: { errors, isDirty } } = form;

    const initialValues = useMemo(() => {
        const data = effectiveData;
        if (!data) return undefined;
        return {
            portfolioID: data.portfolioID || 0,
            typeID: data.typeID || 1,
            name: data.name || "",
            plannedBudget: data.plannedBudget || 0,
            expectedROI: data.expectedROI || 0,
            startDate: data.startDate?.split("T")[0] || "",
            endDate: data.endDate?.split("T")[0] || "",
        };
    }, [effectiveData]);

    // ─── Mutation ───────────────────────────────────────
    const mutation = useApiMutation(
        async (values: ProjectFormValues) => {
            if (mode === "create") {
                return investmentApi.createProject(values);
            }
            return investmentApi.updateProject(effectiveData!.projectID!, {
                ...values,
                status: effectiveData?.status || "Active",
            });
        },
        {
            successMessage: mode === "create" ? "تم إنشاء المشروع بنجاح" : "تم تحديث المشروع بنجاح",
            invalidateKeys: [
                ["projects"],
                ["project", editId],
                ["project-summary"],
                ["portfolios"],
            ],
            onSuccess: () => {
                onOpenChange(false);
                onSuccess?.();
            },
        }
    );

    const handleFormSubmit = useCallback((values: ProjectFormValues) => {
        mutation.mutate(values);
    }, [mutation]);

    return (
        <BaseFormDialog
            open={open}
            onOpenChange={onOpenChange}
            title={mode === "create" ? "إنشاء مشروع جديد" : "تعديل مشروع استثماري"}
            description="إدارة المشاريع الاستثمارية ضمن المحافظ المعتمدة"
            size="3xl"
            isLoading={mutation.isPending}
            isDirty={isDirty}
            onSubmit={form.handleSubmit(handleFormSubmit)}
            resetOnOpen={true}
            reset={reset}
            initialValues={initialValues}
            showGlobalError
            formErrors={errors}
            submitLabel={mode === "create" ? "إنشاء المشروع" : "حفظ التغييرات"}
        >
            <div className="space-y-4 text-start">
                <FormSection title="البيانات الأساسية للمشروع" icon={Building}>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <FormField label="المحفظة الاستثمارية" required error={errors.portfolioID?.message}>
                            <Controller
                                name="portfolioID"
                                control={control}
                                render={({ field }) => (
                                    <NativeSelect
                                        options={portfolios.map(p => ({ label: p.name, value: String(p.portfolioID) }))}
                                        value={String(field.value)}
                                        onChange={(v) => field.onChange(Number(v))}
                                        placeholder="اختر المحفظة..."
                                    />
                                )}
                            />
                        </FormField>
                        <FormField label="نوع المشروع" required error={errors.typeID?.message}>
                            <Controller
                                name="typeID"
                                control={control}
                                render={({ field }) => (
                                    <NativeSelect
                                        options={[
                                            { label: "سكني", value: "1" },
                                            { label: "تجاري", value: "2" },
                                            { label: "صناعي", value: "3" },
                                        ]}
                                        value={String(field.value)}
                                        onChange={(v) => field.onChange(Number(v))}
                                        placeholder="اختر النوع..."
                                    />
                                )}
                            />
                        </FormField>
                        <FormField label="اسم المشروع" required error={errors.name?.message}>
                            <Input {...register("name")} placeholder="مثال: بناء برج النخيل السكني" />
                        </FormField>
                    </div>
                </FormSection>

                <FormSection title="البيانات المالية" icon={DollarSign}>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <FormField label="الميزانية المخططة (ر.ي)" required error={errors.plannedBudget?.message}>
                            <Input type="number" {...register("plannedBudget", { valueAsNumber: true })} placeholder="0.00" className="font-mono" />
                        </FormField>
                        <FormField label="العائد المتوقع (%)" required error={errors.expectedROI?.message}>
                            <Input type="number" step="0.1" {...register("expectedROI", { valueAsNumber: true })} placeholder="0.0" className="font-mono" />
                        </FormField>
                    </div>
                </FormSection>

                <FormSection title="الجدول الزمني" icon={Calendar}>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <FormField label="تاريخ البدء" required error={errors.startDate?.message}>
                            <Controller
                                name="startDate"
                                control={control}
                                render={({ field }) => (
                                    <DateInput
                                        id={field.name}
                                        value={field.value || undefined}
                                        onChange={field.onChange}
                                        className="font-mono"
