import { zodResolver } from "@hookform/resolvers/zod";
import { useQuery } from "@tanstack/react-query";
import { Calculator, User } from "lucide-react";
import { useCallback, useMemo } from "react";
import { Controller,useForm } from "react-hook-form";
import * as z from "zod";

import { investmentApi, type ValuationDto } from "@/api/investment";
import {
    BaseFormDialog,
    DateInput,
    FormField,
    FormSection,
    Input,
    NoteBox,
    Textarea
} from "@/components/ui";
import { useApiMutation } from "@/hooks";

// ─── Validation Schema ─────────────────────────────────

const schema = z.object({
    valuationDate: z.string().min(1, "تاريخ التقييم مطلوب"),
    marketValue: z.number().positive("القيمة السوقية مطلوبة"),
    valuedBy: z.string().min(3, "اسم المُقيّم مطلوب"),
    notes: z.string().optional().or(z.literal("")),
});

export type ValuationFormValues = z.infer<typeof schema>;

// ─── Props ─────────────────────────────────────────────

interface ValuationFormDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    initialData?: Partial<ValuationDto>;
    mode: "create" | "edit";
    onSuccess?: () => void;
    propertyId: number;
}

// ─── Component ─────────────────────────────────────────

export function ValuationDialog({
    open,
    onOpenChange,
    initialData,
    mode,
    onSuccess,
    propertyId
}: ValuationFormDialogProps) {
    // ─── Fresh data in edit mode ────────────────────────
    const editId = mode === "edit" ? initialData?.valuationID : undefined;
    const { data: freshData } = useQuery({
        queryKey: ["valuation", editId],
        queryFn: () => investmentApi.getValuations(propertyId).then(v => v.find(x => x.valuationID === editId)),
        enabled: !!editId && open,
    });

    const effectiveData = useMemo(() => {
        if (mode === "edit" && freshData) return freshData as ValuationDto;
        return initialData;
    }, [mode, freshData, initialData]);

    // ─── Form ───────────────────────────────────────────
    const form = useForm<ValuationFormValues>({
        resolver: zodResolver(schema),
        defaultValues: useMemo(() => ({
            valuationDate: new Date().toISOString().split("T")[0],
            marketValue: 0,
            valuedBy: "",
            notes: "",
        }), []),
    });

    const { register, reset, control, formState: { errors, isDirty } } = form;

    const initialValues = useMemo(() => {
        const data = effectiveData;
        if (!data) return undefined;
        return {
            valuationDate: data.valuationDate?.split("T")[0] || "",
            marketValue: data.marketValue || 0,
            valuedBy: data.valuedBy || "",
            notes: "",
        };
    }, [effectiveData]);

    // ─── Mutation ───────────────────────────────────────
    const mutation = useApiMutation(
        async (values: ValuationFormValues) => {
            if (mode === "create") {
                return investmentApi.createValuation({ ...values, propertyID: propertyId });
            }
            // No update API for valuations — create only
            return investmentApi.createValuation({ ...values, propertyID: propertyId });
        },
        {
            successMessage: mode === "create" ? "تم إضافة التقييم بنجاح" : "تم تحديث التقييم بنجاح",
            invalidateKeys: [
                ["property-valuations", propertyId],
                ["property", propertyId],
                ["properties"],
                ["portfolio-summary"],
                ["project-summary"],
            ],
            onSuccess: () => {
                onOpenChange(false);
                onSuccess?.();
            },
        }
    );

    const handleFormSubmit = useCallback((values: ValuationFormValues) => {
        mutation.mutate(values);
    }, [mutation]);

    return (
        <BaseFormDialog
            open={open}
            onOpenChange={onOpenChange}
            title={mode === "create" ? "إضافة تقييم عقاري جديد" : "تعديل تقييم العقار"}
            description="توثيق القيمة السوقية الحالية للأصل العقاري بناءً على تقييم فني"
            size="lg"
            isLoading={mutation.isPending}
            isDirty={isDirty}
            onSubmit={form.handleSubmit(handleFormSubmit)}
            resetOnOpen={true}
            reset={reset}
            initialValues={initialValues}
            showGlobalError
            formErrors={errors}
            submitLabel={mode === "create" ? "إضافة التقييم" : "حفظ التعديلات"}
        >
            <div className="space-y-4 text-start">
                <FormSection title="القيمة المالية والجدولة" icon={Calculator}>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <FormField label="القيمة السوقية المعتمدة" error={errors.marketValue?.message} required>
                            <Input {...register("marketValue", { valueAsNumber: true })} type="number" className="font-mono font-bold text-lg text-primary" />
                        </FormField>
                        <FormField label="تاريخ التقييم" error={errors.valuationDate?.message} required>
                            <Controller
                                name="valuationDate"
                                control={control}
                                render={({ field }) => (
                                    <DateInput
                                        id={field.name}
                                        value={field.value || undefined}
                                        onChange={field.onChange}
                                        className="font-mono"
                                    />
                                )}
                            />
                        </FormField>
                    </div>
                </FormSection>

                <FormSection title="بيانات المُقيّم والملاحظات" icon={User}>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <FormField label="المُقيّم / جهة التقييم" error={errors.valuedBy?.message} required>
                            <Input {...register("valuedBy")} placeholder="اسم الخبير أو الشركة المثمنة" />
                        </FormField>
                        <FormField label="ملاحظات إضافية" error={errors.notes?.message}>
                            <Textarea {...register("notes")} rows={2} placeholder="تفاصيل حول حالة العقار أو معايير التقييم..." />
                        </FormField>
                    </div>
                </FormSection>

                <NoteBox type="info">
                    يتم استخدام هذا التقييم لتحديث إجمالي قيمة المحفظة الاستثمارية واحتساب نسب النمو.
                </NoteBox>
            </div>
        </BaseFormDialog>
    );
}

import { retirementApi } from "@/api/retirement";
import { salaryRecipientApi } from "@/api/salary-recipients";

import type { FileDetailsForPrint,NormalizableItem } from "./print.types";

/**
 * دالة موحدة لتوحيد مسميات الحقول القادمة من API مختلف (Casing normalization)
 * تستخدم خصيصاً في مباينات الطباعة لضمان الوصول الصحيح للصور والمعرفات
 */
export const normalizePrintItem = (item: NormalizableItem) => {
    if (!item) return null;
    
    // استخراج مسار الصورة من عدة احتمالات مسميات (PascalCase vs camelCase)
    const photoPath = (item.personalPhotoPath ??
        item.PersonalPhotoPath ??
        item.personalPhoto ??
        item.PersonalPhoto ??
        item.PhotoPath ??
        item.photoPath ??
        item.path ??
        item.filePath ??
        item.FilePath) as string | undefined;

    return {
        ...item,
        // توحيد المعرفات
        agentId: (item.agentId ?? item.agentID ?? item.AgentID) as number | undefined,
        guardianId: (item.guardianId ?? item.guardianID ?? item.GuardianID) as number | undefined,
        entitledId: (item.entitledId ?? item.entitledID ?? item.EntitledID) as number | undefined,
        recipientId: (item.recipientId ?? item.recipientID ?? item.RecipientID) as number | undefined,
        
        // توحيد النوع
        recipientType: (item.recipientType ?? item.RecipientType) as string | undefined,

        // توحيد الحالة النشطة
        isActive: item.isActive === true || item.IsActive === true || item.isActive === 1 || item.IsActive === 1,
        
        // توحيد النصوص
        fullName: (item.fullName ?? item.FullName) as string,
        recipientName: (item.recipientName ?? item.RecipientName) as string,
        
        // الحقل الموحد للصورة
        personalPhotoPath: photoPath,
    };
};

/**
 * دالة موحدة لتنسيق العملة في صفحات الطباعة
 */
export const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('ar-YE', {
        style: 'currency',
        currency: 'YER',
        maximumFractionDigits: 0
    }).format(amount).replace('ر.ي.‏', '').trim() + ' ر.ي';
};

/**
 * ثوابت التصميم المشتركة لجداول الطباعة
 */
export const PRINT_STYLES = {
    TB: "border border-black",
    CELL: "px-3 py-2 text-[12px] leading-snug",
    LBL: "px-3 py-2 text-[12px] leading-snug bg-slate-100 font-bold text-black whitespace-nowrap",
    VAL: "px-3 py-2 text-[12px] leading-snug font-semibold text-black",
    SECTION_HEADER: "border border-black bg-slate-200 font-extrabold text-[13px] py-2 px-3 flex items-center gap-2",
};

/**
 * دالة موحدة لجلب تفاصيل ملف التقاعد وملحقاته للطباعة
 */
export const fetchFileDetails = async (fileId: number): Promise<FileDetailsForPrint | null> => {
    if (!fileId) return null;

    const [fileRes, entitledRes, agentsRes, guardiansRes, recipientsRes] = await Promise.all([
        retirementApi.getFile(fileId),
        retirementApi.getEntitledPersons(fileId).catch(() => []),
        retirementApi.getAgents(fileId).catch(() => []),
        retirementApi.getGuardians(fileId).catch(() => []),
        salaryRecipientApi.getByFile(fileId).catch(() => ({ data: [] })),
    ]);

    const fileData = (fileRes as unknown as Record<string, unknown> || {}) as Record<string, unknown>;
    
    return {
        file: {
            activePaymentBookNumber: (fileData.activePaymentBookNumber ?? fileData.ActivePaymentBookNumber ?? null) as string | null,
            personalPhotoPath: (fileData.personalPhotoPath ?? fileData.PersonalPhotoPath ?? fileData.PersonalPhoto ?? null) as string | null,
        },
        entitled: (entitledRes || []).map(normalizePrintItem as any).filter((e: any) => e && (e.isActive === true || e.IsActive === true)),
        agents: (agentsRes || []).map(normalizePrintItem as any),
        guardians: (guardiansRes || []).map(normalizePrintItem as any),
        recipients: (recipientsRes.data || []).map(normalizePrintItem as any),
    } as FileDetailsForPrint;
};

/**
 * الحصول على رابط الصور الموحد
 */
export const getPrintBaseUrl = () => import.meta.env.VITE_API_URL?.replace("/api", "").replace(/\/?$/, "/") || "";

import { zodResolver } from "@hookform/resolvers/zod";
import { Controller,useForm } from "react-hook-form";
import { z } from "zod";

import api from "@/api/axios";
import { 
    BaseFormDialog, 
    DateInput,
    FormField, 
    NativeSelect 
} from "@/components/ui";
import { useApiMutation } from "@/hooks";

// ─── Validation Schema ─────────────────────────────────

const schema = z.object({
    entitledID: z.string().min(1, "يجب اختيار المستحق القاصر"),
    startDate: z.string().min(1, "تاريخ بدء الوصاية مطلوب"),
});

type FormValues = z.infer<typeof schema>;

interface EntitledOption {
    entitledID: number;
    fullName: string;
}

interface AddGuardianMinorDialogProps {
    open: boolean;
    onClose: () => void;
    onSaved: () => void;
    guardianId: number;
    availableEntitleds: EntitledOption[];
}

/**
 * حوار إضافة مستحق إضافي تحت وصاية قائمة - Named Export (Constraint 8)
 */
export function AddGuardianMinorDialog({ 
    open, 
    onClose, 
    onSaved, 
    guardianId, 
    availableEntitleds 
}: AddGuardianMinorDialogProps) {
    
    const form = useForm<FormValues>({
        resolver: zodResolver(schema),
        defaultValues: {
            entitledID: "",
            startDate: new Date().toISOString().split('T')[0],
        }
    });

    const { handleSubmit, control, reset, formState: { errors, isDirty } } = form;

    const mutation = useApiMutation(
        (data: { entitledID: number; startDate: string }) => 
            api.put(`/guardians/${guardianId}/add-minor`, data),
        {
            successMessage: "تم إضافة القاصر للوصي بنجاح",
            onSuccess: () => {
                onSaved();
                onClose();
                reset();
            }
        }
    );

    const onSubmit = (values: FormValues) => {
        mutation.mutate({
            entitledID: Number(values.entitledID),
            startDate: values.startDate + "T00:00:00"
        });
    };

    return (
        <BaseFormDialog
            open={open}
            onOpenChange={(o) => !o && onClose()}
            title="إضافة مستحق للوصي"
            description="ربط مستحق (قاصر) إضافي تحت وصاية هذا الشخص"
            size="full"
            isLoading={mutation.isPending}
            isDirty={isDirty}
            onSubmit={handleSubmit(onSubmit)}
            resetOnOpen
            reset={reset}
            showGlobalError
            formErrors={errors}
            submitLabel="إضافة"
        >
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-2 text-start" dir="rtl">
                <FormField label="اختر المستحق القاصر" required error={errors.entitledID?.message}>
                    <Controller
                        name="entitledID"
                        control={control}
                        render={({ field }) => (
                            <NativeSelect 
                                value={field.value}
                                onChange={field.onChange}
                                options={availableEntitleds.map(e => ({ value: e.entitledID.toString(), label: e.fullName }))}
                                placeholder="اختر من القائمة..."
                            />
                        )}
                    />
                </FormField>
                <FormField label="تاريخ بدء الوصاية" required error={errors.startDate?.message}>
                    <Controller
                        name="startDate"
                        control={control}
                        render={({ field }) => (
                            <DateInput
                                id={field.name}
                                value={field.value || undefined}
                                onChange={field.onChange}
                                className="font-mono text-start"
                            />
                        )}
                    />
                </FormField>
            </div>
        </BaseFormDialog>
    );
}

