/**

 * CreateFileWizard — 4-step wizard for creating or editing a retirement file.

 */

import { useQuery } from "@tanstack/react-query";

import { AlertTriangle, ArrowLeft, ArrowRight, Briefcase, FileUp, IdCard, MapPin, Save, Search, UserCheck } from "lucide-react";

import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";

import { createPortal } from "react-dom";

import { useNavigate } from "react-router-dom";

import api from "@/api/axios";

import { ranksApi } from "@/api/ranks";

import { lookupApi } from "@/api/pension";

import {

    Button,

    FileUploader,

    FormField,

    FormSection,

    Input,

    NativeSelect,

    RadioGroup,

    RadioGroupItem,

    Stepper,

    Text,

    Textarea,

    useConfirm
} from "@/components/ui";

import { DateInput } from "@/components/ui/Input";

import { CLOSED_STATUS_ID, YEMEN_GOVERNORATES } from "@/constants/retirement";

import { useApiMutation } from "@/hooks";

import { normalizeApiError } from "@/lib/errorUtils";

import {

    DRAFT_SESSION_KEY,

    buildFormData,

    findActiveFile,

    isRetireeStepBlocked,

    isStepValid,

    mapRetireeToForm,

    resolveInitialForm,

    shouldConfirmExplicitCancel,

    shouldOpenExistingFileOnEnter,

    toDraft,

    validateStep,

    type ExistingFile,

    type FormState,

    type RetireeFullData,

} from "@/lib/retirementFileForm";

import { focusEnterField, getEnterFocusables } from "@/lib/enterFocus";
import { normalizeArabicDigits } from "@/lib/utils";

// ─── Types ─────────────────────────────────────────────

interface RetireeSearch {

    retireeID: number;

    fullName: string;

    nationalID: string;

    militaryNumber: string | null;

}

interface LookupItem {

    id: number;

    name: string;

}

interface Props {

    onSuccess: () => void;

    onCancel: () => void;

    onCreated?: (fileId: number) => void;

    initialRetireeId?: number;

    initialRetireeName?: string;

    mode?: "create" | "edit";

    fileId?: number;

    /** يُبلَّغ صعودًا ليتحكم الغلاف في مطالبة التأكيد عند X / Escape / النقر خارجًا. */

    onDirtyChange?: (isDirty: boolean) => void;

}

const steps = [

    { label: "المتقاعد", icon: <UserCheck className="w-4 h-4" />, description: "البحث والاختيار" },

    { label: "البيانات", icon: <IdCard className="w-4 h-4" />, description: "المعلومات الشخصية" },

    { label: "العنوان", icon: <MapPin className="w-4 h-4" />, description: "الاتصال والعنوان" },

    { label: "الوثائق", icon: <FileUp className="w-4 h-4" />, description: "الملفات والحفظ" },

];

const PREFILL_FAILED = "فشل في تحميل بيانات المتقاعد. لا يمكن الحفظ قبل نجاح التحميل — يرجى المحاولة مرة أخرى.";

export function CreateFileWizard({ onSuccess, onCancel, onCreated, initialRetireeId, initialRetireeName, mode = "create", fileId, onDirtyChange }: Props) {

    const { confirm, ConfirmDialogElement } = useConfirm();

    const navigate = useNavigate();

    const firstStep = mode === "edit" ? 1 : 0;

    const [step, setStep] = useState(firstStep);

    const computeInitialForm = useCallback(() => {

        return resolveInitialForm({

            mode,

            initialRetireeId,

            rawDraft: typeof sessionStorage === "undefined" ? null : sessionStorage.getItem(DRAFT_SESSION_KEY),

        });

    }, [mode, initialRetireeId]);

    const [initialFormResult] = useState(computeInitialForm);

    const [form, setForm] = useState<FormState>(initialFormResult.form);

    const [isDirty, setIsDirty] = useState(false);

    const [draftRestored] = useState(initialFormResult.draftRestored);

    const [prefillError, setPrefillError] = useState<string | null>(null);

    /** كل تعديل من المستخدم يمر من هنا: يوسم النموذج كقابل للتلافي ويبلّغ الغلاف. */

    const patchForm = useCallback(

        (updater: (previous: FormState) => FormState) => {

            setForm((prev) => {

                const nextState = updater(prev);

                setIsDirty((wasDirty) => {

                    if (!wasDirty) onDirtyChange?.(true);

                    return true;

                });

                return nextState;

            });

        },

        [onDirtyChange],

    );

    const selectRequestIdRef = useRef(0);

    const isInitialized = useRef(false);

    // حفظ المسودة بعد أول تعديل فقط (لا تُنشأ مسودة بمجرد فتح النافذة)

    useEffect(() => {

        if (mode === "edit" || !isDirty) return;

        sessionStorage.setItem(DRAFT_SESSION_KEY, JSON.stringify(toDraft(form)));

    }, [form, mode, isDirty]);

    // إعادة الضبط الدقيقة عند تغير ملف/متقاعد/وضع

    useEffect(() => {

        const init = computeInitialForm();

        setForm(init.form);

        setIsDirty(false);

        onDirtyChange?.(false);

        setPrefillError(null);

        setStep(firstStep);

        setExistingFile(null);

        setExistingCheckFailed(false);

        isInitialized.current = false;

    }, [fileId, initialRetireeId, mode, firstStep, computeInitialForm, onDirtyChange]);

    const [retireeSearch, setRetireeSearch] = useState("");

    const [retireeResults, setRetireeResults] = useState<RetireeSearch[]>([]);

    const [searchingRetirees, setSearchingRetirees] = useState(false);

    const [errors, setErrors] = useState<Record<string, string>>({});

    const searchContainerRef = useRef<HTMLDivElement>(null);

    const [dropdownPos, setDropdownPos] = useState<{ top: number; left: number; width: number } | null>(null);

    const [highlightedIndex, setHighlightedIndex] = useState(-1);

    const dropdownRef = useRef<HTMLDivElement>(null);

    const [existingFile, setExistingFile] = useState<ExistingFile | null>(null);

    const [existingCheckFailed, setExistingCheckFailed] = useState(false);

    const [checkingExistingFile, setCheckingExistingFile] = useState(false);

    // ─── Queries ───────────────────────────────────────

    const { data: socialStatuses = [] } = useQuery({

        queryKey: ["lookups", "social-statuses"],

        queryFn: async () => {

            const res = await api.get<{ data: LookupItem[] }>("/lookups/social-statuses");

            return res.data.data || [];

        },

        staleTime: 5 * 60 * 1000,

    });

    const { data: healthStatuses = [] } = useQuery({

        queryKey: ["lookups", "health-statuses"],

        queryFn: async () => {

            const res = await api.get<{ data: LookupItem[] }>("/lookups/health-statuses");

            return res.data.data || [];

        },

        staleTime: 5 * 60 * 1000,

    });

    const { data: ranks = [] } = useQuery({

        queryKey: ["lookups", "ranks"],

        queryFn: () => ranksApi.getAll(),

        enabled: mode === "edit",

        staleTime: 5 * 60 * 1000,

    });

    const { data: branches = [] } = useQuery({

        queryKey: ["lookups", "branches"],

        queryFn: () => lookupApi.getBranches(),

        enabled: mode === "edit",

        staleTime: 5 * 60 * 1000,

    });

    const { data: prefillData, isPending: prefillPending, isError: prefillFailed, refetch: refetchPrefill } = useQuery({

        queryKey: ["retiree-full-data", initialRetireeId, fileId],

        queryFn: async ({ signal }) => {

            const fullDataRes = await api.get<{ data: RetireeFullData }>(`/retirees/${initialRetireeId}/full-data`, { signal });

            return fullDataRes.data.data;

        },

        enabled: !!initialRetireeId,

        retry: false,

        staleTime: 0,

    });

    // استعلام مدمج وموحد لبيانات الملف وملاحظاته في وضع التعديل

    const { data: editFileData, isPending: editFilePending, isError: editFileFailed, refetch: refetchEditFile } = useQuery({

        queryKey: ["retirement-file-edit-data", fileId],

        queryFn: async ({ signal }) => {

            const res = await api.get<{ data: { notes?: string | null; rankID?: number | null; branchID?: number | null } }>(`/retirement-files/${fileId}`, { signal });

            return res.data.data;

        },

        enabled: mode === "edit" && !!fileId,

        retry: false,

        staleTime: 0,

    });

    // مزامنة تهيئة البيانات بدون جعل النموذج Dirty

    useEffect(() => {

        if (isInitialized.current) return;

        if (isDirty) return;

        if (mode === "edit") {

            if (!prefillData || !editFileData) return;

            setForm((f) => ({

                ...f,

                ...mapRetireeToForm(prefillData, editFileData.notes ?? f.notes, initialRetireeName),

                rankID: editFileData.rankID != null ? String(editFileData.rankID) : f.rankID,

                branchID: editFileData.branchID != null ? String(editFileData.branchID) : f.branchID,

            }));

            setPrefillError(null);

            isInitialized.current = true;

        } else if (mode === "create" && initialRetireeId) {

            if (!prefillData) return;

            setForm((f) => ({

                ...f,

                ...mapRetireeToForm(prefillData, f.notes, initialRetireeName),

            }));

            setPrefillError(null);

            isInitialized.current = true;

        }

    }, [prefillData, editFileData, initialRetireeName, initialRetireeId, mode, isDirty]);

    useEffect(() => {

        if (mode === "create" && initialRetireeId && prefillFailed) {

            setPrefillError(PREFILL_FAILED);

        } else if (mode === "edit" && (prefillFailed || editFileFailed)) {

            setPrefillError(PREFILL_FAILED);

        }

    }, [prefillFailed, editFileFailed, initialRetireeId, mode]);

    const retryPrefill = useCallback(() => {

        void refetchPrefill();

        if (mode === "edit") {

            void refetchEditFile();

        }

    }, [refetchPrefill, refetchEditFile, mode]);

    /** حارس التحقق من وجود ملف نشط للمتقاعد. */

    const checkExistingFile = useCallback(async (retireeId: number): Promise<{ active: ExistingFile | null; failed: boolean }> => {

        try {

            const res = await api.get<{ data: ExistingFile[] }>(`/retirement-files/by-retiree/${retireeId}`);

            return { active: findActiveFile(res.data.data ?? [], CLOSED_STATUS_ID) ?? null, failed: false };

        } catch {

            return { active: null, failed: true };

        }

    }, []);

    // فحص وجود ملف سابق للمتقاعد في وضع الإنشاء عند تمرير initialRetireeId

    useEffect(() => {

        if (mode !== "create" || !initialRetireeId) return;

        let isSubscribed = true;

        setCheckingExistingFile(true);

        checkExistingFile(initialRetireeId).then((fileCheck) => {

            if (!isSubscribed) return;

            setExistingFile(fileCheck.failed ? null : fileCheck.active);

            setExistingCheckFailed(fileCheck.failed);

            setCheckingExistingFile(false);

        });

        return () => {

            isSubscribed = false;

        };

    }, [mode, initialRetireeId, checkExistingFile]);

    const createMutation = useApiMutation(

        (data: FormData) => {

            if (mode === "edit") {

                if (!fileId) throw new Error("رقم الملف مطلوب لتعديل البيانات");

                return api.put(`/retirement-files/${fileId}`, data, { headers: { "Content-Type": "multipart/form-data" } });

            }

            return api.post("/retirement-files", data, { headers: { "Content-Type": "multipart/form-data" } });

        },

        {

            successMessage: mode === "edit" ? "تم تحديث الملف بنجاح" : "تم إنشاء الملف بنجاح",

            onSuccess: (response: { data?: { data?: { fileID?: number; FileID?: number; id?: number }; fileID?: number; FileID?: number; id?: number }; fileID?: number; FileID?: number; id?: number }) => {

                sessionStorage.removeItem(DRAFT_SESSION_KEY);

                onDirtyChange?.(false);

                const payload = response?.data ?? response;

                const newFileId = payload?.data?.fileID ?? payload?.data?.FileID ?? payload?.data?.id;

                if (mode === "create" && newFileId != null) onCreated?.(newFileId);

                onSuccess();

            },

        }

    );

    useEffect(() => {

        if (retireeSearch.length < 2) {

            setRetireeResults([]);

            setSearchingRetirees(false);

            return;

        }

        const controller = new AbortController();

        const timer = setTimeout(async () => {

            setSearchingRetirees(true);

            try {
                const normalizedSearch = normalizeArabicDigits(retireeSearch.trim());
                const res = await api.get<{ data: { items: RetireeSearch[] } }>("/retirees", {
                    params: { search: normalizedSearch, page: 1, pageSize: 10 },
                    signal: controller.signal,
                });

                if (controller.signal.aborted) return;

                setRetireeResults(res.data.data.items || []);

            } catch (err) {

                if (controller.signal.aborted) return;

                setRetireeResults([]);

                setErrors((prev) => ({

                    ...prev,

                    retireeSearch: normalizeApiError(err).message || "تعذّر البحث، حاول مرة أخرى",

                }));

            } finally {

                if (!controller.signal.aborted) setSearchingRetirees(false);

            }

        }, 400);

        return () => {

            clearTimeout(timer);

            controller.abort();

        };

    }, [retireeSearch]);

    const showDropdown = (retireeResults.length > 0 || searchingRetirees);

    useEffect(() => {

        setHighlightedIndex(-1);

    }, [retireeResults]);

    /** إغلاق القائمة عند النقر خارج حقل البحث أو القائمة نفسها. */

    useEffect(() => {

        if (!showDropdown) return;

        const onPointerDown = (event: MouseEvent) => {

            const target = event.target as Node;

            if (searchContainerRef.current?.contains(target)) return;

            if (dropdownRef.current?.contains(target)) return;

            setRetireeResults([]);

            setHighlightedIndex(-1);

        };

        document.addEventListener("mousedown", onPointerDown);

        return () => document.removeEventListener("mousedown", onPointerDown);

    }, [showDropdown]);

    useLayoutEffect(() => {

        if (!showDropdown || !searchContainerRef.current) {

            setDropdownPos(null);

            return;

        }

        const updatePos = () => {

            if (!searchContainerRef.current) return;

            const rect = searchContainerRef.current.getBoundingClientRect();

            setDropdownPos({ top: rect.bottom + 4, left: rect.left, width: rect.width });

        };

        updatePos();

        window.addEventListener("resize", updatePos);

        window.addEventListener("scroll", updatePos, true);

        return () => {

            window.removeEventListener("resize", updatePos);

            window.removeEventListener("scroll", updatePos, true);

        };

    }, [showDropdown]);

    const selectRetiree = useCallback(

        async (r: RetireeSearch) => {

            const currentReqId = ++selectRequestIdRef.current;

            patchForm((f) => ({

                ...f,

                retireeID: r.retireeID,

                retireeDisplayName: `${r.fullName} — ${r.nationalID}`,

            }));

            setRetireeSearch("");

            setRetireeResults([]);

            setErrors({});

            setExistingFile(null);

            setExistingCheckFailed(false);

            setCheckingExistingFile(true);

            try {

                const [fullDataRes, fileCheck] = await Promise.all([

                    api.get<{ data: RetireeFullData }>(`/retirees/${r.retireeID}/full-data`),

                    checkExistingFile(r.retireeID),

                ]);

                if (selectRequestIdRef.current !== currentReqId) return;

                setExistingFile(fileCheck.failed ? null : fileCheck.active);

                setExistingCheckFailed(fileCheck.failed);

                patchForm((f) => ({ ...f, ...mapRetireeToForm(fullDataRes.data.data, f.notes) }));

            } catch (err) {

                if (selectRequestIdRef.current !== currentReqId) return;

                setErrors((prev) => ({

                    ...prev,

                    retireeSearch: normalizeApiError(err).message || "فشل في تحميل بيانات المتقاعد. يرجى المحاولة مرة أخرى.",

                }));

                patchForm((f) => ({ ...f, retireeID: 0, retireeDisplayName: "" }));

            } finally {

                if (selectRequestIdRef.current === currentReqId) {

                    setCheckingExistingFile(false);

                }

            }

        },

        [checkExistingFile, patchForm],

    );

    const handleSearchKeyDown = useCallback(
        (e: React.KeyboardEvent) => {
            // Enter أثناء تركيب النص (IME) يؤكد الحرف — لا نعترضه ولا نمنعه.
            if (e.nativeEvent.isComposing) return;

            // Enter داخل البحث مخصص لاختيار المتقاعد فقط ولا يجب أن يصل لمعالج النموذج العام.
            if (e.key === "Enter") {
                if (retireeResults.length === 0) {
                    // لا نتائج: نمرّر الحدث للمعالج العام ليتقدّم بالخطوة أو يفسّر الخطوة.
                    return;
                }

                e.preventDefault();
                e.stopPropagation();

                const index = highlightedIndex >= 0 ? highlightedIndex : 0;
                const selected = retireeResults[index];

                if (selected) {
                    void selectRetiree(selected);
                }
                return;
            }

            if (e.key === "Escape") {
                if (!showDropdown) return;

                e.preventDefault();
                e.stopPropagation();
                setRetireeResults([]);
                setHighlightedIndex(-1);
                return;
            }

            if (!showDropdown) return;

            if (e.key === "ArrowDown") {
                e.preventDefault();
                e.stopPropagation();
                setHighlightedIndex((prev) => (prev < retireeResults.length - 1 ? prev + 1 : 0));
                return;
            }

            if (e.key === "ArrowUp") {
                e.preventDefault();
                e.stopPropagation();
                setHighlightedIndex((prev) => (prev > 0 ? prev - 1 : retireeResults.length - 1));
            }
        },
        [showDropdown, retireeResults, highlightedIndex, selectRetiree],
    );


    useEffect(() => {

        if (highlightedIndex < 0 || !dropdownRef.current) return;

        const items = dropdownRef.current.querySelectorAll('[data-dropdown-item]');

        items[highlightedIndex]?.scrollIntoView({ block: "nearest" });

    }, [highlightedIndex]);

    const prefillLoading =

        (!!initialRetireeId && prefillPending) ||

        (mode === "edit" && !!fileId && (editFilePending || prefillPending));

    const prefillBlocked = prefillError !== null || prefillLoading || (mode === "edit" && editFileFailed);

    const effectivePrefillError =

        prefillError ??

        (prefillLoading ? "جاري تحميل بيانات المتقاعد…" : null) ??

        (editFileFailed ? "تعذّر تحميل ملاحظات وبيانات الملف. أعد المحاولة قبل الحفظ." : null);

    const runValidation = useCallback(

        (s: number): boolean => {

            const stepErrors = validateStep(form, s, {

                existingFile,

                existingCheckFailed,

                prefillError: effectivePrefillError,

                lifeStatusReadOnly: mode === "edit",

            });

            setErrors((prev) => ({ ...prev, ...stepErrors, prefill: stepErrors.prefill ?? "" }));

            return isStepValid(stepErrors);

        },

        [form, existingFile, existingCheckFailed, effectivePrefillError, mode],

    );

    const containerRef = useRef<HTMLDivElement>(null);

    const rootRef = useRef<HTMLDivElement>(null);

    /**
     * ينقل التركيز للحقل رقم index بعد تهدئة التحديث.
     * يُعاد الاستعلام من DOM عند التنفيذ لا من العقدة المخزّنة،
     * لأن re-render بين المفتاح والتنفيذ يفصل العقدة.
     */
    const focusFieldAt = useCallback((index: number) => {
        const container = containerRef.current;
        if (!container) return;

        focusEnterField(container, index);
    }, []);

    const next = useCallback(() => {

        if (runValidation(step)) setStep((s) => Math.min(s + 1, steps.length - 1));

    }, [step, runValidation]);

    const prev = useCallback(() => setStep((s) => Math.max(s - 1, firstStep)), [firstStep]);

    const handleCancelRequest = async () => {

        if (shouldConfirmExplicitCancel(mode, form, step, firstStep)) {

            const confirmed = await confirm({

                title: mode === "edit" ? "التراجع عن التعديلات" : "التراجع عن إنشاء الملف",

                description: "هل أنت متأكد؟ سيتم حذف البيانات المدخلة والمسودة المحفوظة.",

                confirmLabel: "نعم، إلغاء",

                cancelLabel: "تراجع",

                variant: "danger",

            });

            if (!confirmed) return;

        }

        // المسودة تُحذف مع الإلغاء الصريح — للإغلاق العرضي تبقى للاستئناف

        sessionStorage.removeItem(DRAFT_SESSION_KEY);

        onDirtyChange?.(false);

        onCancel();

    };

    const handleSubmit = useCallback(() => {

        if (!runValidation(step)) return;

        if (prefillBlocked) return;

        createMutation.mutate(buildFormData(form, mode === "create"));

    }, [step, runValidation, prefillBlocked, createMutation, form, mode]);

    /** Enter على متقاعد لديه ملف نشط: افتح تفاصيل الملف بدل إظهار خطأ منع المتابعة. */
    const openExistingFile = useCallback(() => {

        if (!existingFile) return;

        // تدفق الإنشاء متروك: تُحذف المسودة لئلا تُستأنف مع تنبيه «ملف نشط» في المرة القادمة.
        sessionStorage.removeItem(DRAFT_SESSION_KEY);

        onDirtyChange?.(false);

        navigate(`/files/${existingFile.fileID}`);

    }, [existingFile, navigate, onDirtyChange]);

    /**
     * Enter = الانتقال للحقل التالي داخل المعالج.
     *
     * المستمع على document (bubble) وليس على div الجذر: بعد اختيار المتقاعد
     * لا يتبقّى في الخطوة أي حقل، فيقع التركيز على body ولا يصل الحدث إلى
     * div الجذر إطلاقًا.
     */
    const handleEnterChain = useCallback(
        (e: KeyboardEvent) => {
            // Enter أثناء تركيب النص (IME) يؤكد الحرف العربي؛ لا نشغّل السلسلة وقتها.
            if (e.isComposing) return;

            if (
                e.key !== "Enter" ||
                e.ctrlKey ||
                e.altKey ||
                e.metaKey ||
                e.shiftKey
            ) {
                return;
            }

            const root = rootRef.current;
            if (!root) return;

            const target = e.target as HTMLElement | null;

            // الهدف إما داخل المعالج أو body (لا يوجد تركيز)، وكلاهما معنا.
            // أي هدف آخر — نافذة تأكيد، رافع ملفات، حقل خارج المعالج — يُترك.
            if (target && target !== document.body && !root.contains(target)) return;

            // الحقول التي تدير Enter بنفسها تُعلن ذلك بسمة صريحة.
            // لا نستخدم `e.defaultPrevented` كمؤشر: Radix RadioGroupItem
            // يستدعي preventDefault على Enter (لمنع إرسال النموذج) قبل وصول
            // الحدث إلينا، فكان الحارس يوقف انتقال التركيز داخل RadioGroup.
            if (target?.closest("[data-enter-handled]")) return;

            // Enter داخل الملاحظات يبقى سطرًا جديدًا طبيعيًا.
            if (target?.tagName === "TEXTAREA") return;

            // عناصر نتائج البحث تدير Enter بنفسها.
            if (target?.closest("[data-dropdown-item]")) return;

            const radioGroup = target?.closest<HTMLElement>('[role="radiogroup"]') ?? null;

            // الأزرار والروابط تحتفظ بسلوك Enter الافتراضي.
            // SELECT مستثنى: نتولى انتقاله هنا عبر المنطق الموحد، إلا إذا كانت فارغة
            // (يستدعي NativeSelect.onKeyDown الفتح natively حتى بعد إضافة preventDefault هنا).
            // RadioGroup مستثنى حتى نعامل المجموعة كحقل منطقي واحد.
            const keepsNativeEnter =
                !radioGroup &&
                !!target &&
                (
                    target.tagName === "BUTTON" ||
                    target.tagName === "A" ||
                    target.getAttribute("role") === "button"
                );

            // SELECT بقيمة محددة: نديره عبر السلسلة (الأولوية للمنطق أدناه).
            // SELECT بلا قيمة: نتركه يفتح منتقي الاختيار natively عبر NativeSelect.onKeyDown.
            const isEmptySelect =
                target?.tagName === "SELECT" &&
                !(target as HTMLSelectElement).value;

            if (keepsNativeEnter || isEmptySelect) return;

            e.preventDefault();

            // متقاعد لديه ملف نشط بالفعل: Enter ينقل إلى تفاصيل الملف، لا إلى الخطوة التالية.
            if (shouldOpenExistingFileOnEnter({ mode, step, existingFile })) {
                openExistingFile();
                return;
            }

            // حقول يُقصد بها Enter = الانتقال للخطوة التالية لا الحقل التالي
            // (مثل تاريخ الوفاة: بقية بيانات المتوفى اختيارية، فالتالي هو التبويب التالي).
            if (target?.closest("[data-enter-advance]")) {
                next();
                return;
            }

            if (!containerRef.current) return;

            const focusables = getEnterFocusables(containerRef.current);

            let nextIndex = -1;

            // مجموعة حي/متوفى تعامل كحقل واحد؛ Enter يخرج منها إلى الحقل التالي.
            if (radioGroup) {
                const radioIndexes = focusables
                    .map((element, index) => (radioGroup.contains(element) ? index : -1))
                    .filter((index) => index >= 0);

                if (radioIndexes.length > 0) {
                    nextIndex = Math.max(...radioIndexes) + 1;
                }
            } else if (target) {
                // بعض المكونات قد ترسل الحدث من عنصر داخلي، لذلك نتحقق من contains أيضًا.
                const currentIndex = focusables.findIndex(
                    (element) => element === target || element.contains(target)
                );

                if (currentIndex >= 0) {
                    nextIndex = currentIndex + 1;
                }
            }

            // يوجد حقل تالٍ في نفس الخطوة.
            if (nextIndex >= 0 && nextIndex < focusables.length) {
                // نعيد الاستعلام بالـ index داخل المؤقت بدل الاحتفاظ بعقدة DOM:
                // بين المفتاح والمؤقت قد يتغيّر النموذج (حقل شرطي أو رسائل خطأ)،
                // فتُفصل العقدة المخزّنة عن DOM ويضيع التركيز.
                focusFieldAt(nextIndex);
                return;
            }

            // لا حقل تالٍ داخل الخطوة.
            // في الخطوة الأخيرة: نُركّز زر الحفظ ليعلم المستخدم أن Enter التالي سيحفظ.
            // في أي خطوة أخرى: ننتقل مباشرةً بدون ضغطة Enter إضافية.
            if (step === steps.length - 1) {
                const finalAction = rootRef.current?.querySelector<HTMLElement>(
                    "[data-enter-chain-target]"
                );
                if (finalAction) {
                    finalAction.focus();
                    return;
                }
                handleSubmit();
                return;
            }

            next();
        },
        [step, next, handleSubmit, focusFieldAt, mode, existingFile, openExistingFile],
    );

    // تسجيل سلسلة Enter على document ليعمل Enter حتى بلا حقل مركّز داخل المعالج
    useEffect(() => {
        document.addEventListener("keydown", handleEnterChain);
        return () => document.removeEventListener("keydown", handleEnterChain);
    }, [handleEnterChain]);


    /**
     * عند دخول خطوة جديدة: التركيز على أول عنصر فيها.
     *
     * الإلغاء الوحيد: أن يكون المستخدم هو من ركّز عنصرًا داخل جسم الخطوة خلال
     * نافذة الانتظار (فلا نقفز ونقطع كتابته). الاعتماد على `focusin` لا على
     * `document.activeElement`، لأن زر «التالي» يبقى داخل المعالج بعد النقر
     * ووجوده كتركيز حالي كان يمنع التركيز التلقائي تمامًا.
     */
    useEffect(() => {
        let userPickedField = false;

        const onFocusIn = (e: FocusEvent) => {
            if (containerRef.current?.contains(e.target as Node)) userPickedField = true;
        };

        document.addEventListener("focusin", onFocusIn, true);

        const timer = window.setTimeout(() => {
            const container = containerRef.current;
            const root = rootRef.current;
            if (!container || !root) return;
            if (userPickedField) return;

            // في خطوة البيانات نبدأ من الخيار المحدد في RadioGroup إن وجد.
            const checkedRadio = container.querySelector<HTMLElement>(
                '[role="radio"][aria-checked="true"]:not([disabled])'
            );

            const target = checkedRadio ?? getEnterFocusables(container)[0] ?? root;

            target.focus();
            target.scrollIntoView({ block: "nearest" });
        }, 150);

        return () => {
            window.clearTimeout(timer);
            document.removeEventListener("focusin", onFocusIn, true);
        };
    }, [step]);

    return (

        <div ref={rootRef} className="flex flex-col h-full overflow-x-auto bg-background" tabIndex={-1} data-wizard-root>

            <div className="shrink-0 px-3 py-3 sm:px-6 sm:py-4 bg-card rounded-t-2xl">

                <Stepper steps={steps} activeStep={step} onStepClick={(i) => i < step && i >= firstStep && setStep(i)} />

            </div>

            <div

                ref={containerRef}

                className="flex-1 overflow-y-auto flex flex-col"

                style={{ padding: 'var(--dlg-body-py) var(--dlg-body-px)', gap: 'var(--dlg-body-gap)' }}

            >

                {prefillError && (

                    <div className="rounded-lg border border-destructive bg-destructive/5 px-4 py-3 flex items-start justify-between gap-3">

                        <div className="flex items-start gap-2 text-sm text-destructive">

                            <AlertTriangle className="w-5 h-5 shrink-0 mt-0.5" />

                            <span>{prefillError}</span>

                        </div>

                        <Button type="button" variant="outline" size="sm" onClick={retryPrefill}>إعادة المحاولة</Button>

                    </div>

                )}

                {draftRestored && !prefillError && (

                    <div className="rounded-lg border border-amber-300 bg-amber-50 px-4 py-2 text-sm text-amber-800">

                        تم استرجاع مسودة غير مكتملة. راجع البيانات قبل الحفظ، أو اضغط «إلغاء» لحذفها.

                    </div>

                )}

                {step === 0 && mode === "create" && (

                    <FormSection>

                        <div className="space-y-4">

                            {!form.retireeID ? (

                                <div className="max-w-2xl mx-auto w-full">

                                        <FormField label="ابحث عن المتقاعد بالاسم أو الرقم الوطني" error={errors.retireeID}>

                                            <div ref={searchContainerRef} className="relative">

                                                <Search className="absolute end-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground z-10" />

                                                <Input

                                                    value={retireeSearch}

                                                    onChange={(e) => setRetireeSearch(e.target.value)}

                                                    onKeyDown={handleSearchKeyDown}

                                                    className="pe-10"

                                                    placeholder="أدخل اسم المتقاعد أو الرقم الوطني..."

                                                    autoFocus

                                                />

                                            </div>

                                        </FormField>

                                        {showDropdown && dropdownPos && createPortal(

                                            <div

                                                ref={dropdownRef}

                                                className="fixed z-dialog rounded-lg border bg-card max-h-64 overflow-y-auto shadow-lg"

                                                style={{ top: dropdownPos.top, left: dropdownPos.left, width: dropdownPos.width }}

                                            >

                                                {searchingRetirees && <div className="px-4 py-3 text-sm text-muted-foreground">جاري البحث...</div>}

                                                {retireeResults.map((r, i) => (

                                                    <Button

                                                        key={r.retireeID}

                                                        type="button"

                                                        variant="ghost"

                                                        data-dropdown-item

                                                        className={`w-full justify-start px-4 py-3 h-auto border-b border-border last:border-0 gap-3 ${i === highlightedIndex ? "bg-primary/10" : ""}`}

                                                        onClick={() => selectRetiree(r)}

                                                        onMouseEnter={() => setHighlightedIndex(i)}

                                                    >

                                                        <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center text-primary font-bold text-xs shrink-0">{r.fullName.charAt(0)}</div>

                                                        <div className="min-w-0 flex-1 text-start">

                                                            <div className="font-bold text-sm truncate">{r.fullName}</div>

                                                            <div className="text-[10px] sm:text-xs text-muted-foreground flex gap-3">

                                                                <span>الرقم الوطني: {r.nationalID}</span>

                                                                {r.militaryNumber && <span>الرقم العسكري: {r.militaryNumber}</span>}

                                                            </div>

                                                        </div>

                                                    </Button>

                                                ))}

                                            </div>,

                                            document.body

                                        )}

                                        {errors.retireeSearch && (

                                            <div className="text-sm text-destructive font-medium bg-destructive/5 border border-destructive rounded-lg px-4 py-2.5 flex items-center gap-2 animate-in fade-in slide-in-from-top-1">

                                                <span className="text-destructive">⚠️</span> {errors.retireeSearch}

                                            </div>

                                        )}

                                </div>

                            ) : (

                                <>

                                    <div className="flex items-center justify-between rounded-lg border border-emerald-200 px-4 py-3 bg-emerald-50/50 flex-wrap gap-2">

                                        <div className="flex items-center gap-3">

                                            <div className="w-8 h-8 rounded bg-emerald-100 flex items-center justify-center text-emerald-600"><UserCheck className="w-4 h-4" /></div>

                                            <Text variant="body" className="font-bold text-emerald-700">{form.retireeDisplayName}</Text>

                                        </div>

                                        <Button type="button" variant="ghost" size="sm" className="h-11 text-xs" onClick={() => { patchForm((f) => ({ ...f, retireeID: 0, retireeDisplayName: "" })); setExistingFile(null); setExistingCheckFailed(false); }}>تغيير</Button>

                                    </div>

                                    {checkingExistingFile && (

                                        <Text variant="caption">جاري التحقق من الملفات السابقة...</Text>

                                    )}

                                    {existingFile && (

                                        <div className="rounded-lg border border-amber-300 bg-amber-50 px-4 py-3 flex items-start gap-3 animate-in fade-in slide-in-from-top-1">

                                            <AlertTriangle className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" />

                                            <div className="text-sm text-amber-800">

                                                <Text variant="body" className="font-bold">هذا المتقاعد لديه ملف نشط بالفعل</Text>

                                                <Text variant="body" className="mt-0.5">

                                                    رقم الملف: <span className="font-mono font-semibold">{existingFile.fileNumber}</span>

                                                    {existingFile.fileStatusName && <> — الحالة: {existingFile.fileStatusName}</>}

                                                </Text>

                                                <Text variant="caption" className="mt-1 text-amber-700">لا يمكن فتح ملف جديد لمتقاعد لديه ملف غير مغلق.</Text>

                                            </div>

                                        </div>

                                    )}

                                    {existingCheckFailed && (

                                        <div className="rounded-lg border border-destructive bg-destructive/5 px-4 py-3 flex items-start gap-3 animate-in fade-in slide-in-from-top-1">

                                            <AlertTriangle className="w-5 h-5 text-destructive shrink-0 mt-0.5" />

                                            <div className="text-sm text-destructive">

                                                <Text variant="body" className="font-bold">تعذّر التحقق من ملفات المتقاعد</Text>

                                                <Text variant="caption" className="mt-1 block">أعد اختيار المتقاعد للمحاولة مرة أخرى قبل المتابعة.</Text>

                                            </div>

                                        </div>

                                    )}

                                </>

                            )}

                        </div>

                    </FormSection>

                )}

                {step === 1 && (

                    <div className="animate-in fade-in duration-200">

                        <FormSection title="المعلومات الشخصية" icon={IdCard}>

                            {/* Is Alive Radio Group */}

                            <div className="flex flex-col gap-2 mb-4">

                                <label className="label-field">حالة المتقاعد</label>

                                <RadioGroup
                                    disabled={mode === "edit"}

                                    value={form.isAlive ? "alive" : "dead"}

                                    onValueChange={(val) => {

                                        if (mode === "edit") return;

                                        if (val === "alive") {

                                            patchForm((f) => ({ ...f, isAlive: true, deathDate: "", healthStatusID: f.healthStatusID === "4" ? "1" : f.healthStatusID }));

                                        } else {

                                            patchForm((f) => ({ ...f, isAlive: false, healthStatusID: "4" }));

                                        }

                                    }}

                                    onKeyDown={(e) => {

                                        if (mode === "edit") return;

                                        if (e.key === "ArrowLeft" || e.key === "ArrowRight" || e.key === "ArrowUp" || e.key === "ArrowDown") {

                                            e.preventDefault();

                                            patchForm((f) => {

                                                const nextAlive = !f.isAlive;

                                                return {

                                                    ...f,

                                                    isAlive: nextAlive,

                                                    deathDate: nextAlive ? "" : f.deathDate,

                                                    healthStatusID: nextAlive ? (f.healthStatusID === "4" ? "1" : f.healthStatusID) : "4",

                                                };

                                            });

                                        }

                                    }}

                                    className="flex items-center h-11 border rounded-md bg-muted/5 max-w-sm overflow-hidden focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-2"

                                >

                                    <label className={`flex items-center justify-center gap-2 cursor-pointer flex-1 h-full px-4 transition-colors ${form.isAlive ? "bg-primary/10 font-bold text-primary" : "hover:bg-muted/50"}`}>

                                        <RadioGroupItem value="alive" className="accent-primary" id="status-alive" />

                                        <span className="text-sm font-medium">على قيد الحياة</span>

                                    </label>

                                    <div className="w-px h-full bg-border"></div>

                                    <label className={`flex items-center justify-center gap-2 cursor-pointer flex-1 h-full px-4 transition-colors ${!form.isAlive ? "bg-destructive/10 font-bold text-destructive" : "hover:bg-muted/50"}`}>

                                        <RadioGroupItem value="dead" className="accent-destructive" id="status-dead" />

                                        <span className="text-sm font-medium text-destructive">متوفي</span>

                                    </label>

                                </RadioGroup>

                                {mode === "edit" && <p className="text-sm text-muted-foreground">لتغيير حالة الحياة استخدم إجراء تسجيل الوفاة أو تصحيح الحالة من صفحة الملف.</p>}

                            </div>

                            {!form.isAlive && mode === "create" && (

                                <div className="pb-4 border-b border-border mb-4 animate-in fade-in slide-in-from-top-1">

                                    <div className="max-w-sm">

                                        <FormField label="تاريخ الوفاة" required error={errors.deathDate}>

                                            <DateInput data-enter-advance value={form.deathDate} onChange={(val) => patchForm((f) => ({ ...f, deathDate: val || "" }))} />

                                        </FormField>


                                    </div>

                                </div>

                            )}

                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 items-start">

                                <FormField label="الرقم الوطني" required={form.isAlive} error={errors.nationalID}>

                                    <Input value={form.nationalID} onChange={(e) => patchForm((f) => ({ ...f, nationalID: normalizeArabicDigits(e.target.value).replace(/\D/g, "") }))} placeholder={!form.isAlive ? "اختياري للمتوفين" : "000000000000"} maxLength={12} />

                                </FormField>

                                <FormField label="الجنس">

                                    <NativeSelect

                                        options={[

                                            { value: "1", label: "ذكر" },

                                            { value: "2", label: "أنثى" },

                                        ]}

                                        value={form.gender}

                                        onChange={(val) => patchForm((f) => ({ ...f, gender: val }))}

                                        placeholder="اختر الجنس..."

                                    />

                                </FormField>

                                <FormField label="تاريخ الميلاد" required={form.isAlive} error={errors.birthDate}>

                                    <DateInput value={form.birthDate} onChange={(val) => patchForm((f) => ({ ...f, birthDate: val || "" }))} />

                                </FormField>

                                <FormField label="الحالة الاجتماعية">

                                    <NativeSelect

                                        options={socialStatuses.map((s) => ({ value: s.id.toString(), label: s.name }))}

                                        value={form.socialStatusID}

                                        onChange={(val) => patchForm((f) => ({ ...f, socialStatusID: val }))}

                                        placeholder="اختر..."

                                    />

                                </FormField>

                                <FormField label="الحالة الصحية">

                                    <NativeSelect

                                        options={healthStatuses
                                            .filter((s) => mode !== "edit" || !form.isAlive || s.id <= 3)
                                            .map((s) => ({ value: s.id.toString(), label: s.name }))}

                                        value={form.healthStatusID}

                                        disabled={mode === "edit" && !form.isAlive}

                                        onChange={(val) => patchForm((f) => ({ ...f, healthStatusID: val }))}

                                        placeholder="اختر..."

                                    />

                                </FormField>

                            </div>

                        </FormSection>

                        {mode === "edit" && (

                            <FormSection title="بيانات الرتبة والفرع" icon={Briefcase} className="mt-5">

                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 items-start">

                                    <FormField label="الرتبة">

                                        <NativeSelect

                                            options={ranks.map((r) => ({ value: r.rankID.toString(), label: r.rankName }))}

                                            value={form.rankID}

                                            onChange={(val) => patchForm((f) => ({ ...f, rankID: val }))}

                                            placeholder="اختر الرتبة..."

                                        />

                                    </FormField>

                                    <FormField label="الفرع">

                                        <NativeSelect

                                            options={branches.map((b) => ({ value: b.id.toString(), label: b.name }))}

                                            value={form.branchID}

                                            onChange={(val) => patchForm((f) => ({ ...f, branchID: val }))}

                                            placeholder="اختر الفرع..."

                                        />

                                    </FormField>

                                </div>

                            </FormSection>

                        )}

                    </div>

                )}

                {step === 2 && (

                    <div className="animate-in fade-in duration-200">

                        <FormSection title="معلومات السكن والاتصال" icon={MapPin}>

                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 items-start">

                                <FormField label="المحافظة">

                                    <NativeSelect

                                        options={YEMEN_GOVERNORATES.map(g => ({ value: g, label: g }))}

                                        value={form.governorate}

                                        onChange={(val) => patchForm((f) => ({ ...f, governorate: val }))}

                                        placeholder="اختر المحافظة..."

                                    />

                                </FormField>

                                <FormField label="المدينة"><Input value={form.city} onChange={(e) => patchForm((f) => ({ ...f, city: e.target.value }))} placeholder="المدينة" /></FormField>

                                <FormField label="رقم الهاتف" error={errors.phone}><Input value={form.phone} onChange={(e) => patchForm((f) => ({ ...f, phone: e.target.value }))} placeholder="7xxxxxxx" /></FormField>

                                <div className="md:col-span-2 lg:col-span-3"><FormField label="العنوان التفصيلي"><Input value={form.address} onChange={(e) => patchForm((f) => ({ ...f, address: e.target.value }))} placeholder="العنوان بالكامل..." /></FormField></div>

                            </div>

                        </FormSection>

                    </div>

                )}

                {step === 3 && (

                    <div className="animate-in fade-in duration-200 dlg-body-gap flex flex-col">

                        <FormSection title="الوثائق والمستندات" icon={FileUp}>

                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 dlg-gap">

                                <FormField label="الصورة الشخصية"><FileUploader accept="image/*" value={form.personalPhoto} onChange={(file) => patchForm((f) => ({ ...f, personalPhoto: file }))} enableScanner={true} size="sm" /></FormField>

                                <FormField label="أوليات الملف"><FileUploader accept="image/*,application/pdf" value={form.primaryDocument} onChange={(file) => patchForm((f) => ({ ...f, primaryDocument: file }))} enableScanner={true} size="sm" /></FormField>

                                {form.isAlive ? (

                                    <div className="md:col-span-2 grid grid-cols-1 md:grid-cols-2 gap-4">

                                        <FormField label="الهوية الوطنية"><FileUploader accept="image/*,application/pdf" value={form.idDocument} onChange={(file) => patchForm((f) => ({ ...f, idDocument: file }))} enableScanner={true} size="sm" /></FormField>

                                    </div>

                                ) : <FormField label="شهادة الوفاة"><FileUploader accept="image/*,application/pdf" value={form.deathCertificate} onChange={(file) => patchForm((f) => ({ ...f, deathCertificate: file }))} enableScanner={true} size="sm" /></FormField>}

                            </div>

                        </FormSection>

                        <FormField label="ملاحظات"><Textarea rows={2} data-enter-skip value={form.notes} onChange={(e) => patchForm((f) => ({ ...f, notes: e.target.value }))} placeholder="أضف ملاحظاتك هنا..." /></FormField>

                    </div>

                )}

            </div>

            <div className="shrink-0 bg-background z-30" style={{ padding: 'var(--dlg-footer-py) var(--dlg-body-px)' }}>

                <div className="flex items-center justify-between gap-3 w-full">

                    <Button type="button" variant="outline" onClick={handleCancelRequest} disabled={createMutation.isPending}>إلغاء</Button>

                    <div className="flex items-center gap-2">

                        {step > (mode === "edit" ? 1 : 0) && <Button type="button" variant="outline" onClick={prev} disabled={createMutation.isPending}><ArrowRight className="w-4 h-4 ms-2" />السابق</Button>}

                        {step < steps.length - 1 ? (

                            <Button type="button" onClick={next} disabled={(step === 0 && (!form.retireeID || isRetireeStepBlocked({ prefillError: effectivePrefillError, existingFile, existingCheckFailed }) || checkingExistingFile)) || createMutation.isPending}>التالي<ArrowLeft className="w-4 h-4 me-2" /></Button>

                        ) : <Button type="button" data-enter-chain-target onClick={handleSubmit} loading={createMutation.isPending}><Save className="w-4 h-4 ms-2" />{mode === "edit" ? "حفظ التعديلات" : "حفظ الملف"}</Button>}

                    </div>

                </div>

            </div>

            {ConfirmDialogElement}

        </div>

    );

}

import { useQueryClient } from "@tanstack/react-query";
import {
    Check,
    Contrast,
    Crop,
    Download,
    Loader2,
    RotateCcw,
    RotateCw,
    Save,
    Sun,
    Undo,
    ZoomIn,
    ZoomOut,
} from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";

import { documentsApi } from "@/api/documents";
import { Button } from "@/components/ui/Button";
import { Card } from "@/components/ui/Card";
import { CornerEditor } from "@/components/ui/CornerEditor";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/Dialog";
import { Slider } from "@/components/ui/Slider";
import { useDocumentBlob } from "@/hooks/useDocumentBlob";
import { DEFAULT_CROP_TIMEOUT_MS, runCropPipeline } from "@/lib/crop-pipeline";
import { getCropBudget } from "@/lib/crop-region";
import { getDeviceCapabilities } from "@/lib/device-capabilities";
import { getDocumentUrl } from "@/lib/utils";


interface DocumentData {
    documentID: number;
    documentTypeID: number;
    documentTypeName: string;
    fileName: string;
    filePath?: string | null;
    notes?: string | null;
    uploadedByUser?: string | null;
    createdAt: string;
}

interface ImageSettings {
    brightness: number;
    contrast: number;
    sharpness: number;
    rotation: 0 | 90 | 180 | 270;
}

const DEFAULT_SETTINGS: ImageSettings = {
    brightness: 100,
    contrast: 100,
    sharpness: 0,
    rotation: 0,
};

const IMAGE_EXTENSIONS = [".jpg", ".jpeg", ".png", ".gif", ".bmp", ".webp", ".tiff", ".tif"];
/** مهلة رفع الملف — مستقلة عن مهلة المعالجة */
const UPLOAD_TIMEOUT_MS = 60000;

// ─── Canvas Pool ─────────────────────────────────────────
const globalCanvasPool: HTMLCanvasElement[] = [];

function acquireCanvas(w?: number, h?: number): HTMLCanvasElement {
    const c = globalCanvasPool.pop() || window.document.createElement("canvas");
    if (w !== undefined) c.width = w;
    if (h !== undefined) c.height = h;
    return c;
}

function releaseCanvas(c: HTMLCanvasElement) {
    c.width = 0;
    c.height = 0;
    globalCanvasPool.push(c);
}

function isImageDocument(doc: DocumentData | null): boolean {
    if (!doc?.fileName) return false;
    const lower = doc.fileName.toLowerCase();
    return IMAGE_EXTENSIONS.some((ext) => lower.endsWith(ext));
}

// ─── Helpers ─────────────────────────────────────────────

/**
 * تحميل عنصر صورة من blob URL.
 *
 * لا crossOrigin: رابط blob: نفس الأصل، فلا يتلوث الـ canvas عند toBlob —
 * وهو شرط ضروري هنا لأن المعالجة ترسم على canvas ثم تصدّر.
 * الجلب نفسه يمرّ عبر useDocumentBlob (النمط الموحد للمشروع).
 */
function loadImageElement(src: string): Promise<HTMLImageElement> {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => resolve(img);
        img.onerror = () => reject(new Error("فشل تحميل الصورة"));
        img.src = src;
    });
}

function rotateImage(
    img: HTMLImageElement,
    rotation: 0 | 90 | 180 | 270,
): HTMLCanvasElement {
    const isVertical = rotation === 90 || rotation === 270;
    const w = isVertical ? img.height : img.width;
    const h = isVertical ? img.width : img.height;
    const canvas = acquireCanvas(w, h);
    const ctx = canvas.getContext("2d");
    if (!ctx) throw new Error("فشل إنشاء سياق الرسم للدوران");

    ctx.translate(w / 2, h / 2);
    ctx.rotate((rotation * Math.PI) / 180);
    ctx.drawImage(img, -img.width / 2, -img.height / 2);

    return canvas;
}

function rotateCorners(
    corners: { x: number; y: number }[],
    rotation: 0 | 90 | 180 | 270,
    naturalW: number,
    naturalH: number,
): { x: number; y: number }[] {
    switch (rotation) {
        case 90:  return corners.map(c => ({ x: naturalH - c.y, y: c.x }));
        case 180: return corners.map(c => ({ x: naturalW - c.x, y: naturalH - c.y }));
        case 270: return corners.map(c => ({ x: c.y, y: naturalW - c.x }));
        default:  return corners;
    }
}

function canvasToFile(canvas: HTMLCanvasElement, originalName: string): Promise<File> {
    return new Promise((resolve, reject) => {
        canvas.toBlob((blob) => {
            if (!blob) {
                reject(new Error("فشل تحويل Canvas"));
                return;
            }
            // Strip GUID prefix added by LocalFileStorageService (e.g. "guid_original.jpg")
            const cleaned = originalName.replace(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}_/i, "");
            const baseName = cleaned.replace(/\.[^.]+$/, "");
            const name = baseName.endsWith("_scanned") ? `${baseName}.jpg` : `${baseName}_scanned.jpg`;
            resolve(new File([blob], name, { type: "image/jpeg" }));
        }, "image/jpeg", 0.85);
    });
}

// ─── Component ───────────────────────────────────────────

const deviceCapabilities = getDeviceCapabilities();

function applySharpen(
    ctx: CanvasRenderingContext2D,
    width: number,
    height: number,
    amount: number,
) {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const original = new Uint8ClampedArray(data);

    const kernel = [
        0, -1, 0,
        -1, 5, -1,
        0, -1, 0,
    ];

    for (let y = 1; y < height - 1; y++) {
        for (let x = 1; x < width - 1; x++) {
            for (let c = 0; c < 3; c++) {
                let sum = 0;
                for (let ky = -1; ky <= 1; ky++) {
                    for (let kx = -1; kx <= 1; kx++) {
                        const idx = ((y + ky) * width + (x + kx)) * 4 + c;
                        sum += original[idx] * kernel[(ky + 1) * 3 + (kx + 1)];
                    }
                }
                const idx = (y * width + x) * 4 + c;
                data[idx] = Math.min(255, Math.max(0, original[idx] + (sum - original[idx]) * amount));
            }
        }
    }

    ctx.putImageData(imageData, 0, 0);
}

function renderSettingsImage(
    ctx: CanvasRenderingContext2D,
    img: HTMLImageElement,
    settings: ImageSettings,
    scale: number,
): void {
    const canvas = ctx.canvas;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    ctx.translate(canvas.width / 2, canvas.height / 2);
    ctx.rotate((settings.rotation * Math.PI) / 180);
    ctx.scale(scale, scale);
    ctx.drawImage(img, -img.width / 2, -img.height / 2);
    ctx.restore();

    const brightness = settings.brightness / 100;
    const contrast = settings.contrast / 100;
    ctx.filter = `brightness(${brightness}) contrast(${contrast})`;
    ctx.drawImage(canvas, 0, 0);
    ctx.filter = "none";

    if (settings.sharpness > 0) {
        applySharpen(ctx, canvas.width, canvas.height, settings.sharpness / 100);
    }
}

function renderExportCanvas(img: HTMLImageElement, settings: ImageSettings): HTMLCanvasElement {
    const isVertical = settings.rotation === 90 || settings.rotation === 270;
    const canvas = acquireCanvas(
        isVertical ? img.height : img.width,
        isVertical ? img.width : img.height,
    );
    const ctx = canvas.getContext("2d");
    if (!ctx) {
        releaseCanvas(canvas);
        throw new Error("فشل إنشاء سياق الرسم");
    }
    // التصدير من الأصل بالدقة الكاملة — دقة المعاينة لا تدخل هنا
    renderSettingsImage(ctx, img, settings, 1);
    return canvas;
}

interface DocumentProcessDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    document: DocumentData | null;
    fileId: number;
    onSaved?: () => void;
}

export function DocumentProcessDialog({
    open,
    onOpenChange,
    document: docData,
    fileId,
    onSaved,
}: DocumentProcessDialogProps) {
    const queryClient = useQueryClient();

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const originalImageRef = useRef<HTMLImageElement | null>(null);
    const settingsRef = useRef<ImageSettings>(DEFAULT_SETTINGS);
    // رقم العملية الجارية: انتهاء المهلة يجعل الفحص اللاحق يرفض نتائج العملية القديمة
    const operationRef = useRef(0);
    const abortRef = useRef<AbortController | null>(null);

    const [settings, setSettings] = useState<ImageSettings>(DEFAULT_SETTINGS);
    const [history, setHistory] = useState<ImageSettings[]>([DEFAULT_SETTINGS]);
    const [historyIndex, setHistoryIndex] = useState(0);
    const [zoom, setZoom] = useState(1);
    const [isProcessing, setIsProcessing] = useState(false);

    const [isCropMode, setIsCropMode] = useState(false);
    const [manualCorners, setManualCorners] = useState<{ x: number; y: number }[] | null>(null);

    useEffect(() => {
        settingsRef.current = settings;
    }, [settings]);

    // إعادة تهيئة جلسة التحرير عند تغيير الوثيقة أو فتح النافذة لوثيقة أخرى
    useEffect(() => {
        setSettings(DEFAULT_SETTINGS);
        setHistory([DEFAULT_SETTINGS]);
        setHistoryIndex(0);
        setZoom(1);
        setIsProcessing(false);
        setIsCropMode(false);
        setManualCorners(null);
        settingsRef.current = DEFAULT_SETTINGS;
        originalImageRef.current = null;
    }, [docData?.documentID, open]);

    // الجلب يمرّ عبر useDocumentBlob — النمط الموحد للمشروع لملفات محمية (JWT).
    // blob: نفس الأصل، فلا حاجة لـ crossOrigin ولا تتلوث الـ canvas.
    const { blobUrl: imageBlobUrl, loading: blobLoading } = useDocumentBlob(docData?.filePath, {
        enabled: open,
    });

    const imageUrl = useMemo(() => {
        if (!docData?.filePath) return null;
        return getDocumentUrl(docData.filePath);
    }, [docData?.filePath]);

    useEffect(() => {
        if (!imageBlobUrl || !open) return;

        let cancelled = false;

        void (async () => {
            try {
                const img = await loadImageElement(imageBlobUrl);
                if (cancelled) return;
                originalImageRef.current = img;
                applySettings(settingsRef.current);
            } catch {
                if (cancelled) return;
                toast.error("تعذّر تحميل الصورة، تحقّق من الاتصال أو من صلاحية الجلسة");
            }
        })();

        return () => {
            cancelled = true;
        };
    }, [imageBlobUrl, open]);

    // فشل الجلب: useDocumentBlob يُبقي blobUrl=null و loading=false
    useEffect(() => {
        if (!open || !docData?.filePath || blobLoading) return;
        if (imageBlobUrl) return;
        if (originalImageRef.current) return;
        toast.error("تعذّر تحميل الصورة، تحقّق من الاتصال أو من صلاحية الجلسة");
    }, [open, docData?.filePath, blobLoading, imageBlobUrl]);

    const applySettings = useCallback(
        (newSettings: ImageSettings) => {
            const canvas = canvasRef.current;
            const img = originalImageRef.current;
            if (!canvas || !img) return;

            setIsProcessing(true);

            const ctx = canvas.getContext("2d");
            if (!ctx) {
                setIsProcessing(false);
                return;
            }

            const { previewDim } = getCropBudget(deviceCapabilities);
            const isVertical = newSettings.rotation === 90 || newSettings.rotation === 270;
            const baseW = isVertical ? img.height : img.width;
            const baseH = isVertical ? img.width : img.height;
            // معاينة بدقة منفصلة عن التصدير: حجم شاشة المعاينة لا يمس دقة الحفظ
            const scale = Math.min(1, previewDim / baseW, previewDim / baseH);
            canvas.width = Math.max(1, Math.round(baseW * scale));
            canvas.height = Math.max(1, Math.round(baseH * scale));

            renderSettingsImage(ctx, img, newSettings, scale);

            setIsProcessing(false);
        },
        []
    );

    useEffect(() => {
        if (!isCropMode) {
            applySettings(settings);
        }
    }, [settings, applySettings, isCropMode]);

    const undo = useCallback(() => {
        if (historyIndex > 0) {
            const newIndex = historyIndex - 1;
            setHistoryIndex(newIndex);
            setSettings(history[newIndex]);
        }
    }, [historyIndex, history]);

    const redo = useCallback(() => {
        if (historyIndex < history.length - 1) {
            const newIndex = historyIndex + 1;
            setHistoryIndex(newIndex);
            setSettings(history[newIndex]);
        }
    }, [historyIndex, history]);

    const saveToHistory = useCallback(
        (newSettings: ImageSettings) => {
            const newHistory = history.slice(0, historyIndex + 1);
            newHistory.push(newSettings);
            setHistory(newHistory);
            setHistoryIndex(newHistory.length - 1);
        },
        [history, historyIndex]
    );

    const updateSetting = useCallback(
        <K extends keyof ImageSettings>(key: K, value: ImageSettings[K]) => {
            const newSettings = { ...settings, [key]: value };
            setSettings(newSettings);
            saveToHistory(newSettings);
        },
        [settings, saveToHistory]
    );

    const rotate = useCallback(
        (delta: 90 | -90) => {
            const newRotation = ((settings.rotation + delta + 360) % 360) as 0 | 90 | 180 | 270;
            updateSetting("rotation", newRotation);
        },
        [settings.rotation, updateSetting]
    );

    const enableCropMode = useCallback(() => {
        setIsCropMode(true);
        setManualCorners(null);
    }, []);

    const cancelCrop = useCallback(() => {
        setIsCropMode(false);
        setManualCorners(null);
        applySettings(settings);
    }, [applySettings, settings]);

    const applyCrop = useCallback(async () => {
        if (!manualCorners || manualCorners.length !== 4 || !imageUrl || !docData) return;

        setIsProcessing(true);

        const opId = ++operationRef.current;
        const controller = new AbortController();
        abortRef.current = controller;

        let workCanvas: HTMLCanvasElement | null = null;
        let outCanvas: HTMLCanvasElement | null = null;

        // مهلة المعالجة فقط (WebGL/Worker/CPU) — الرفع خارجها
        const timeoutId = setTimeout(() => {
            // إنهاء فعلي: توقف رقم العملية وإلغاء المعالجة الجارية
            operationRef.current++;
            controller.abort();
            toast.error("انتهت مهلة القص، يرجى المحاولة مرة أخرى");
            setIsProcessing(false);
        }, DEFAULT_CROP_TIMEOUT_MS);

        try {
            // الصورة محمّلة مسبقاً في originalImageRef من blob: — لا جلب ثانٍ
            const img = originalImageRef.current;
            if (!img) throw new Error("الصورة غير محمّلة");
            if (opId !== operationRef.current) return;

            const hasRotation = settings.rotation !== 0;
            const rotatedCorners = hasRotation
                ? rotateCorners(manualCorners, settings.rotation, img.naturalWidth, img.naturalHeight)
                : manualCorners;

            let regionSource: CanvasImageSource;
            let regionSourceW: number;
            let regionSourceH: number;

            if (hasRotation) {
                workCanvas = rotateImage(img, settings.rotation);
                regionSource = workCanvas;
                regionSourceW = workCanvas.width;
                regionSourceH = workCanvas.height;
            } else {
                // بدون دوران: لا تُنشأ نسخة بالحجم الطبيعي — تُستخرج منطقة القص مباشرة من الأصل
                regionSource = img;
                regionSourceW = img.naturalWidth;
                regionSourceH = img.naturalHeight;
            }

            let finalData: Uint8ClampedArray<ArrayBuffer>;
            let finalW: number;
            let finalH: number;

            try {
                const result = await runCropPipeline({
                    source: regionSource,
                    sourceWidth: regionSourceW,
                    sourceHeight: regionSourceH,
                    corners: rotatedCorners,
                    capabilities: deviceCapabilities,
                    signal: controller.signal,
                });
                finalData = result.data;
                finalW = result.width;
                finalH = result.height;
            } catch (error) {
                console.error("Processor failed:", error);
                const message = error instanceof Error ? error.message : "";
                throw new Error(/[\u0600-\u06FF]/.test(message) ? message : "فشل معالجة الصورة");
            }

            if (opId !== operationRef.current) return;

            // انتهت المعالجة: تُلغى المهلة قبل الحفظ والرفع
            clearTimeout(timeoutId);

            outCanvas = acquireCanvas(finalW, finalH);
            const outCtx = outCanvas.getContext("2d");
            if (!outCtx) throw new Error("فشل إنشاء سياق الإخراج");
            outCtx.putImageData(new ImageData(finalData, finalW, finalH), 0, 0);

            const brightness = settings.brightness / 100;
            const contrast = settings.contrast / 100;
            if (brightness !== 1 || contrast !== 1) {
                outCtx.filter = `brightness(${brightness}) contrast(${contrast})`;
                outCtx.drawImage(outCanvas, 0, 0);
                outCtx.filter = "none";
            }

            if (settings.sharpness > 0) {
                applySharpen(outCtx, finalW, finalH, settings.sharpness / 100);
            }

            const file = await canvasToFile(outCanvas, docData.fileName);
            releaseCanvas(outCanvas);
            outCanvas = null;

            if (opId !== operationRef.current) return;

            // استبدال الأصل: تحديث الوثيقة الحالية — المالك والبيانات تبقى كما هي
            const formData = new FormData();
            formData.append("File", file);
            formData.append("DocumentTypeID", String(docData.documentTypeID));
            formData.append("Notes", `صورة مقصوصة من: ${docData.fileName}`);

            // مهلة الرفع منفصلة: الطلب يُلغى فعلياً عبر signal
            const uploadController = new AbortController();
            abortRef.current = uploadController;
            const uploadTimeoutId = setTimeout(() => uploadController.abort(), UPLOAD_TIMEOUT_MS);
            try {
                await documentsApi.update(docData.documentID, formData, uploadController.signal);
            } catch (error) {
                if (uploadController.signal.aborted) {
                    throw new Error("انتهت مهلة رفع الصورة، يرجى المحاولة مرة أخرى");
                }
                throw error;
            } finally {
                clearTimeout(uploadTimeoutId);
            }
            if (opId !== operationRef.current) return;

            toast.success("تم القص والحفظ بنجاح");
            setIsCropMode(false);
            setManualCorners(null);
            await queryClient.invalidateQueries({ queryKey: ["documents", fileId] });
            await queryClient.invalidateQueries({ queryKey: ["document", docData.documentID] });
            onSaved?.();
            onOpenChange(false);
        } catch (error) {
            if (opId !== operationRef.current) return; // نتيجة ملغاة — لا رسالة ولا واجهة
            console.error("Crop error:", error);
            toast.error(error instanceof Error ? error.message : "فشل قص الصورة");
        } finally {
            clearTimeout(timeoutId);
            if (workCanvas) releaseCanvas(workCanvas);
            if (outCanvas) releaseCanvas(outCanvas);
            setIsProcessing(false);
        }
    }, [manualCorners, imageUrl, docData, settings, fileId, queryClient, onSaved, onOpenChange]);

    const handleSave = useCallback(async () => {
        const img = originalImageRef.current;
        if (!img || !docData) return;

        setIsProcessing(true);

        const opId = ++operationRef.current;
        const controller = new AbortController();
        abortRef.current = controller;

        try {
            // إعادة الرسم من الأصل بالدقة الكاملة — دقة المعاينة المصغرة لا تُحفظ
            const exportCanvas = renderExportCanvas(img, settings);
            let file: File;
            try {
                file = await canvasToFile(exportCanvas, docData.fileName);
            } finally {
                releaseCanvas(exportCanvas);
            }
            if (opId !== operationRef.current) return;

            // استبدال الأصل بدل رفع نسخة جديدة — يمنع فقدان المالك والبيانات الوصفية
            const formData = new FormData();
            formData.append("File", file);
            formData.append("DocumentTypeID", String(docData.documentTypeID));
            formData.append("Notes", `صورة معالجة من: ${docData.fileName}`);

            await documentsApi.update(docData.documentID, formData, controller.signal);
            if (opId !== operationRef.current) return;

            toast.success("تم حفظ الصورة المعالجة بنجاح");
            await queryClient.invalidateQueries({ queryKey: ["documents", fileId] });
            await queryClient.invalidateQueries({ queryKey: ["document", docData.documentID] });
            onSaved?.();
            onOpenChange(false);
        } catch (error) {
            if (opId !== operationRef.current) return;
            console.error("Save error:", error);
            toast.error("فشل حفظ الصورة");
        } finally {
            setIsProcessing(false);
        }
    }, [docData, settings, fileId, queryClient, onSaved, onOpenChange]);

    const handleDownload = useCallback(() => {
        const img = originalImageRef.current;
        if (!img) return;

        const link = window.document.createElement("a");
        // الامتداد من صيغة التصدير الفعلية (JPEG) لا من اسم الأصل
        const baseName = (docData?.fileName || "image").replace(/\.[^.]+$/, "");
        link.download = `processed_${baseName}.jpg`;
        const exportCanvas = renderExportCanvas(img, settings);
        try {
            link.href = exportCanvas.toDataURL("image/jpeg", 0.92);
        } finally {
            releaseCanvas(exportCanvas);
        }
        link.click();
    }, [docData?.fileName, settings]);

    const resetSettings = useCallback(() => {
        setSettings(DEFAULT_SETTINGS);
        saveToHistory(DEFAULT_SETTINGS);
    }, [saveToHistory]);

    if (!docData || !isImageDocument(docData)) {
        return (
            <Dialog open={open} onOpenChange={onOpenChange}>
                <DialogContent size="sm">
                    <DialogHeader>
                        <DialogTitle>معالجة الصورة</DialogTitle>
                    </DialogHeader>
                    <div className="py-12 text-center text-muted-foreground">
                        الوثيقة غير موجودة أو ليست صورة
                    </div>
                </DialogContent>
            </Dialog>
        );
    }

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent size="full" className="p-0 overflow-hidden" clipContent={false}>
                <DialogHeader className="shrink-0 px-4 py-3 border-b">
                    <DialogTitle className="flex items-center gap-2 text-base">
                        <span className="font-bold">{docData.documentTypeName}</span>
                        <span className="text-xs text-muted-foreground font-normal">— {docData.fileName}</span>
                    </DialogTitle>
                </DialogHeader>

                <div className="flex-1 flex overflow-hidden" style={{ height: "calc(100dvh - 200px)" }}>
                    {/* Image Area */}
                    <div className="flex-1 overflow-auto bg-muted/20 flex items-center justify-center p-4">
                        {isCropMode ? (
                            <div className="w-full h-full max-w-5xl">
                                <CornerEditor
                                    imageUrl={imageBlobUrl || imageUrl || ""}
                                    rotation={settings.rotation}
                                    corners={manualCorners ?? undefined}
                                    onCornersChange={setManualCorners}
                                />
                            </div>
                        ) : (
                            <div
                                className="relative bg-white rounded-lg overflow-hidden"
                                style={{ transform: `scale(${zoom})`, transformOrigin: "center" }}
                            >
                                <canvas
                                    ref={canvasRef}
                                    className="max-w-full max-h-[70vh]"
                                />
                                {isProcessing && (
                                    <div className="absolute inset-0 bg-background/50 flex items-center justify-center">
                                        <Loader2 className="w-8 h-8 animate-spin text-primary" />
                                    </div>
                                )}
                            </div>
                        )}
                    </div>

                    {/* Sidebar Controls */}
                    <aside className="w-72 border-r bg-card overflow-y-auto shrink-0">
                        <div className="p-3 space-y-3">
                            {/* Action Buttons */}
                            {isCropMode ? (
                                <div className="flex gap-2">
                                    <Button
                                        variant="outline"
                                        size="sm"
                                        onClick={cancelCrop}
                                        disabled={isProcessing}
                                        className="flex-1"
                                    >
                                        إلغاء
                                    </Button>
                                    <Button
                                        size="sm"
                                        onClick={applyCrop}
                                        disabled={!manualCorners || manualCorners.length !== 4 || isProcessing}
                                        className="flex-1"
                                    >
                                        {isProcessing ? (
                                            <Loader2 className="w-4 h-4 animate-spin ml-1" />
                                        ) : (
                                            <Check className="w-4 h-4 ml-1" />
                                        )}
                                        تطبيق القص
                                    </Button>
                                </div>
                            ) : (
                                <div className="flex gap-2">
                                    <Button
                                        variant="outline"
                                        size="sm"
                                        onClick={handleDownload}
                                        className="flex-1 gap-1"
                                    >
                                        <Download className="w-4 h-4" />
                                        تحميل
                                    </Button>
                                    <Button
                                        size="sm"
                                        onClick={handleSave}
                                        disabled={isProcessing}
                                        className="flex-1 gap-1"
                                    >
                                        {isProcessing ? (
                                            <Loader2 className="w-4 h-4 animate-spin" />
                                        ) : (
                                            <Save className="w-4 h-4" />
                                        )}
                                        حفظ
                                    </Button>
                                </div>
                            )}

                            {/* Zoom */}
                            <Card className="p-3">
                                <h3 className="font-bold text-xs mb-2 flex items-center gap-1.5">
                                    <ZoomIn className="w-3.5 h-3.5" />
                                    التكبير
                                </h3>
                                <div className="flex items-center gap-2">
                                    <Button
                                        variant="outline"
                                        size="icon"
                                        className="h-7 w-7"
                                        onClick={() => setZoom(Math.max(0.25, zoom - 0.25))}
                                        disabled={zoom <= 0.25 || isCropMode}
                                    >
                                        <ZoomOut className="w-3.5 h-3.5" />
                                    </Button>
                                    <span className="flex-1 text-center text-xs font-mono">
                                        {Math.round(zoom * 100)}%
                                    </span>
                                    <Button
                                        variant="outline"
                                        size="icon"
                                        className="h-7 w-7"
                                        onClick={() => setZoom(Math.min(3, zoom + 0.25))}
                                        disabled={zoom >= 3 || isCropMode}
                                    >
                                        <ZoomIn className="w-3.5 h-3.5" />
                                    </Button>
                                </div>
                            </Card>

                            {/* Rotation */}
                            <Card className="p-3">
                                <h3 className="font-bold text-xs mb-2 flex items-center gap-1.5">
                                    <RotateCw className="w-3.5 h-3.5" />
                                    التدوير
                                </h3>
                                <div className="flex items-center gap-2">
                                    <Button
                                        variant="outline"
                                        className="flex-1 gap-1 text-xs h-8"
                                        onClick={() => rotate(-90)}
                                        disabled={isCropMode}
                                    >
                                        <RotateCcw className="w-3.5 h-3.5" />
                                        يسار
                                    </Button>
                                    <Button
                                        variant="outline"
                                        className="flex-1 gap-1 text-xs h-8"
                                        onClick={() => rotate(90)}
                                        disabled={isCropMode}
                                    >
                                        <RotateCw className="w-3.5 h-3.5" />
                                        يمين
                                    </Button>
                                </div>
                                {settings.rotation !== 0 && (
                                    <p className="text-[10px] text-muted-foreground text-center mt-1">
                                        {settings.rotation}°
                                    </p>
                                )}
                            </Card>

                            {/* Crop */}
                            <Card className={`p-3 ${isCropMode ? "border-primary" : ""}`}>
                                <h3 className="font-bold text-xs mb-2 flex items-center gap-1.5">
                                    <Crop className="w-3.5 h-3.5" />
                                    القص
                                </h3>
                                {isCropMode ? (
                                    <p className="text-[10px] text-muted-foreground">
                                        اسحب النقاط لتعديل حواف المستند
                                    </p>
                                ) : (
                                    <Button
                                        variant="outline"
                                        className="w-full gap-1 text-xs h-8"
                                        onClick={enableCropMode}
                                    >
                                        <Crop className="w-3.5 h-3.5" />
                                        بدء القص
                                    </Button>
                                )}
                            </Card>

                            {/* Image Adjustments */}
                            <Card className="p-3">
                                <h3 className="font-bold text-xs mb-2 flex items-center gap-1.5">
                                    <Sun className="w-3.5 h-3.5" />
                                    تحسين
                                </h3>
                                <div className="space-y-3">
                                    <div>
                                        <div className="flex items-center justify-between mb-1">
                                            <label className="text-[10px] font-medium flex items-center gap-1">
                                                <Sun className="w-3 h-3" />
                                                السطوع
                                            </label>
                                            <span className="text-[10px] font-mono text-muted-foreground">
                                                {settings.brightness}%
                                            </span>
                                        </div>
                                        <Slider
                                            value={[settings.brightness]}
                                            onValueChange={([v]) => updateSetting("brightness", v)}
                                            min={50}
                                            max={150}
                                            step={1}
                                            disabled={isCropMode}
                                        />
                                    </div>

                                    <div>
                                        <div className="flex items-center justify-between mb-1">
                                            <label className="text-[10px] font-medium flex items-center gap-1">
                                                <Contrast className="w-3 h-3" />
                                                التباين
                                            </label>
                                            <span className="text-[10px] font-mono text-muted-foreground">
                                                {settings.contrast}%
                                            </span>
                                        </div>
                                        <Slider
                                            value={[settings.contrast]}
                                            onValueChange={([v]) => updateSetting("contrast", v)}
                                            min={50}
                                            max={150}
                                            step={1}
                                            disabled={isCropMode}
                                        />
                                    </div>

                                    <div>
                                        <div className="flex items-center justify-between mb-1">
                                            <label className="text-[10px] font-medium">الحدة</label>
                                            <span className="text-[10px] font-mono text-muted-foreground">
                                                {settings.sharpness}%
                                            </span>
                                        </div>
                                        <Slider
                                            value={[settings.sharpness]}
                                            onValueChange={([v]) => updateSetting("sharpness", v)}
                                            min={0}
                                            max={100}
                                            step={1}
                                            disabled={isCropMode}
                                        />
                                    </div>
                                </div>
                            </Card>

                            {/* History */}
                            <Card className="p-3">
                                <h3 className="font-bold text-xs mb-2">سجل التعديلات</h3>
                                <div className="flex items-center gap-2">
                                    <Button
                                        variant="outline"
                                        size="sm"
                                        onClick={undo}
                                        disabled={historyIndex === 0 || isCropMode}
                                        className="flex-1 gap-1 text-xs h-7"
                                    >
                                        <Undo className="w-3.5 h-3.5" />
                                        تراجع
                                    </Button>
                                    <Button
                                        variant="outline"
                                        size="sm"
                                        onClick={redo}
                                        disabled={historyIndex === history.length - 1 || isCropMode}
                                        className="flex-1 gap-1 text-xs h-7"
                                    >
                                        <RotateCcw className="w-3.5 h-3.5" />
                                        إعادة
                                    </Button>
                                </div>
                                <Button
                                    variant="ghost"
                                    size="sm"
                                    onClick={resetSettings}
                                    disabled={isCropMode}
                                    className="w-full mt-2 text-destructive hover:text-destructive text-xs h-7"
                                >
                                    إعادة ضبط
                                </Button>
                            </Card>
                        </div>
                    </aside>
                </div>
            </DialogContent>
        </Dialog>
    );
}

import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { Eye, FileSearch, FileText } from "lucide-react";
import { useForm } from "react-hook-form";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { z } from "zod";

import { archiveApi } from "@/api/archive";
import {
    Badge,
    Button,
    Card,
    FormField,
    NativeSelect,
    Text,
    Textarea,
} from "@/components/ui";
import { formatDate, getDocumentUrl } from "@/lib/utils";
import type { DocumentReviewItem } from "@/types/archive";
import { REVIEW_STATUS } from "@/types/archive";

import { DocumentActions } from "./DocumentActions";

const reviewSchema = z.object({
    reviewStatus: z.number().min(0, "حالة الفحص مطلوبة"),
    reviewNotes: z.string().min(10, "ملاحظات الفحص مطلوبة (10 أحرف على الأقل)"),
    rejectionReason: z.string().optional(),
}).refine(
    (data) => {
        if (data.reviewStatus === REVIEW_STATUS.REJECTED) {
            return data.rejectionReason && data.rejectionReason.length > 0;
        }
        return true;
    },
    {
        message: "سبب الرفض مطلوب عند رفض الوثيقة",
        path: ["rejectionReason"],
    }
);

type ReviewForm = z.infer<typeof reviewSchema>;

function getFileType(fileName: string): "pdf" | "image" | "unknown" {
    const ext = fileName.toLowerCase().split(".").pop();
    if (ext === "pdf") return "pdf";
    if (["jpg", "jpeg", "png", "gif", "webp", "bmp", "svg"].includes(ext || "")) return "image";
    return "unknown";
}

interface DocumentReviewPanelProps {
    document: DocumentReviewItem | null;
    onRefresh?: () => void;
    onViewDocument?: (doc: DocumentReviewItem) => void;
}

export function DocumentReviewPanel({
    document: doc,
    onRefresh,
    onViewDocument,
}: DocumentReviewPanelProps) {
    const navigate = useNavigate();
    const queryClient = useQueryClient();

    const reviewForm = useForm<ReviewForm>({
        resolver: zodResolver(reviewSchema),
        defaultValues: {
            reviewStatus: REVIEW_STATUS.PENDING,
            reviewNotes: "",
            rejectionReason: "",
        },
    });

    const reviewMutation = useMutation({
        mutationFn: (data: { documentId: number; reviewStatus: number; reviewNotes: string; rejectionReason?: string }) =>
            archiveApi.reviewDocument(data.documentId, {
                reviewStatus: data.reviewStatus,
                reviewNotes: data.reviewNotes,
                rejectionReason: data.rejectionReason,
            }),
        onSuccess: () => {
            toast.success("تم حفظ نتيجة الفحص بنجاح");
            queryClient.invalidateQueries({ queryKey: ["archive", "review-documents"] });
            queryClient.invalidateQueries({ queryKey: ["archive", "review-stats"] });
            onRefresh?.();
            reviewForm.reset();
        },
        onError: () => {
            toast.error("خطأ في حفظ نتيجة الفحص");
        },
    });

    const handleSubmitReview = (data: ReviewForm) => {
        if (!doc) return;
        reviewMutation.mutate({
            documentId: doc.documentId,
            reviewStatus: data.reviewStatus,
            reviewNotes: data.reviewNotes,
            rejectionReason: data.rejectionReason,
        });
    };

    const getReviewBadge = (status: number) => {
        switch (status) {
            case REVIEW_STATUS.APPROVED:
                return <Badge variant="success">معتمدة</Badge>;
            case REVIEW_STATUS.REJECTED:
                return <Badge variant="destructive">مرفوضة</Badge>;
            case REVIEW_STATUS.PENDING:
            default:
                return <Badge variant="warning">بانتظار الفحص</Badge>;
        }
    };

    if (!doc) {
        return (
            <Card className="flex-1 flex flex-col overflow-hidden">
                <div className="flex-1 flex items-center justify-center text-muted-foreground">
                    <div className="text-center">
                        <FileText className="w-12 h-12 mx-auto mb-3 opacity-100" />
                        <Text variant="body">اختر وثيقة من القائمة لعرض تفاصيلها</Text>
                    </div>
                </div>
            </Card>
        );
    }

    return (
        <Card className="flex-1 flex flex-col overflow-hidden">
            {/* Header */}
            <div className="p-4 border-b bg-muted/30 shrink-0">
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3 min-w-0">
                        <FileText className="w-5 h-5 text-muted-foreground shrink-0" />
                        <div className="min-w-0">
                            <p className="font-medium truncate">{doc.fileName}</p>
                            <Text variant="caption">
                                {doc.documentTypeName} — {doc.uploadedBy} — {formatDate(doc.createdAt)}
                            </Text>
                        </div>
                    </div>
                    <div className="flex items-center gap-2 shrink-0">
                        {getReviewBadge(doc.reviewStatus)}
                        {onViewDocument && (
                            <Button variant="ghost" size="sm" onClick={() => onViewDocument(doc)}>
                                <Eye className="w-4 h-4 ml-1" />
                                عرض كامل
                            </Button>
                        )}
                        {doc.retirementFileId && (
                            <DocumentActions
                                document={{
                                    documentID: doc.documentId,
                                    documentTypeID: doc.documentTypeId,
                                    documentTypeName: doc.documentTypeName,
                                    fileName: doc.fileName,
                                    filePath: doc.filePath,
                                    notes: doc.notes,
                                    uploadedByUser: doc.uploadedBy,
                                    createdAt: doc.createdAt,
                                    pendingReviewStatus: doc.reviewStatus,
                                }}
                                fileId={doc.retirementFileId}
                                actions={["download", "edit", "note", "process", "delete"]}
                                size="sm"
                                onRefresh={() => {
                                    queryClient.invalidateQueries({ queryKey: ["archive", "review-documents"] });
                                    queryClient.invalidateQueries({ queryKey: ["archive", "review-stats"] });
                                    onRefresh?.();
                                }}
                            />
                        )}
                    </div>
                </div>
            </div>

            {/* Content */}
            <div className="flex-1 flex overflow-hidden min-h-0">
                {/* Preview */}
                <div className="flex-1 p-4 flex items-center justify-center bg-muted/10 min-h-0 overflow-auto">
                    {doc.filePath ? (
                        (() => {
                            const fileType = getFileType(doc.fileName);
                            const url = getDocumentUrl(doc.filePath);
                            if (fileType === "pdf") {
                                return (
                                    <iframe
                                        src={url ?? undefined}
                                        className="w-full h-full rounded-lg border bg-white shadow-sm"
                                        title={doc.fileName}
                                    />
                                );
                            }
                            if (fileType === "image") {
                                return (
                                    <img
                                        src={url ?? undefined}
                                        alt={doc.fileName}
                                        className="max-w-full max-h-full object-contain rounded-lg border bg-white shadow-sm"
                                    />
                                );
                            }
                            return (
                                <div className="text-center text-muted-foreground">
                                    <FileText className="w-10 h-10 mx-auto mb-2 opacity-100" />
                                    <Text variant="body">نوع الملف غير مدعوم للعرض</Text>
                                    <p className="text-xs mt-1">{doc.fileName}</p>
                                </div>
                            );
                        })()
                    ) : (
                        <div className="text-center text-muted-foreground">
                            <FileText className="w-10 h-10 mx-auto mb-2 opacity-100" />
                            <Text variant="body">لا يوجد ملف مرفق</Text>
                        </div>
                    )}
                </div>

                {/* Review Form Sidebar */}
                <div className="w-[320px] shrink-0 border-r p-4 flex flex-col gap-4 overflow-auto">
                    <h4 className="text-sm font-bold flex items-center gap-2">
                        <FileSearch className="w-4 h-4" />
                        فحص الوثيقة
                    </h4>

                    {/* Info */}
                    <div className="space-y-3 text-sm">
                        <div className="flex justify-between">
                            <span className="text-muted-foreground">رقم الوثيقة:</span>
                            <span className="font-mono font-bold">{doc.documentId}</span>
                        </div>
                        {doc.documentNumber && (
                            <div className="flex justify-between">
                                <span className="text-muted-foreground">رقم المستند:</span>
                                <span className="font-mono">{doc.documentNumber}</span>
                            </div>
                        )}
                        <div className="flex justify-between">
                            <span className="text-muted-foreground">نوع الوثيقة:</span>
                            <span>{doc.documentTypeName}</span>
                        </div>
                        <div className="flex justify-between">
                            <span className="text-muted-foreground">القسم:</span>
                            <Badge variant="outline" className="text-xs">{doc.ownerTypeName}</Badge>
                        </div>
                        {doc.entityName && (
                            <div className="flex justify-between">
                                <span className="text-muted-foreground">صاحب الوثيقة:</span>
                                <span className="font-medium">{doc.entityName}</span>
                            </div>
                        )}
                        {doc.retireeName && !doc.entityName && (
                            <div className="flex justify-between">
                                <span className="text-muted-foreground">رقم الملف:</span>
                                <span>{doc.retireeName}</span>
                            </div>
                        )}
                        {doc.fileNumber && (
                            <div className="flex justify-between">
                                <span className="text-muted-foreground">رقم الملف:</span>
                                <Button
                                    variant="link"
                                    size="sm"
                                    className="p-0 h-auto text-xs"
                                    onClick={() => navigate(`/files/${doc.retirementFileId}`)}
                                >
                                    {doc.fileNumber}
                                </Button>
                            </div>
                        )}
                        <div className="flex justify-between">
                            <span className="text-muted-foreground">رفع بواسطة:</span>
                            <span>{doc.uploadedBy}</span>
                        </div>
                        {doc.expiryDate && (
                            <div className="flex justify-between">
                                <span className="text-muted-foreground">انتهاء الصلاحية:</span>
                                <span>{formatDate(doc.expiryDate)}</span>
                            </div>
                        )}
                    </div>

                    {doc.notes && (
                        <>
                            <div className="h-px bg-border" />
                            <div>
                                <h5 className="text-xs font-bold text-muted-foreground mb-1">ملاحظات الوثيقة</h5>
                                <Text variant="body" className="bg-muted/50 p-2 rounded-lg whitespace-pre-wrap">{doc.notes}</Text>
                            </div>
                        </>
                    )}

                    {doc.reviewNotes && (
                        <>
                            <div className="h-px bg-border" />
                            <div>
                                <h5 className="text-xs font-bold text-muted-foreground mb-1">ملاحظات الفحص</h5>
                                <Text variant="body" className="bg-muted/50 p-2 rounded-lg whitespace-pre-wrap">{doc.reviewNotes}</Text>
                                {doc.reviewedBy && (
                                    <Text variant="caption" className="mt-1">
                                        بواسطة: {doc.reviewedBy}
                                        {doc.reviewedAt && ` — ${formatDate(doc.reviewedAt)}`}
                                    </Text>
                                )}
                            </div>
                        </>
                    )}

                    {doc.rejectionReason && (
                        <>
                            <div className="h-px bg-border" />
                            <div>
                                <h5 className="text-xs font-bold text-destructive mb-1">سبب الرفض</h5>
                                <Text variant="body" className="bg-destructive/5 p-2 rounded-lg text-destructive whitespace-pre-wrap">{doc.rejectionReason}</Text>
                            </div>
                        </>
                    )}

                    <div className="h-px bg-border" />

                    {/* Review Form */}
                    <FormField label="حالة الفحص *" error={reviewForm.formState.errors.reviewStatus?.message}>
                        <NativeSelect
                            value={reviewForm.watch("reviewStatus").toString()}
                            onChange={(val) => reviewForm.setValue("reviewStatus", Number(val))}
                            options={[
                                { value: "1", label: "بانتظار الفحص" },
                                { value: "2", label: "معتمدة" },
                                { value: "3", label: "مرفوضة" },
                            ]}
                        />
                    </FormField>

                    <FormField label="ملاحظات الفحص *" error={reviewForm.formState.errors.reviewNotes?.message}>
                        <Textarea
                            {...reviewForm.register("reviewNotes")}
                            placeholder="أدخل ملاحظات الفحص..."
                            rows={3}
                        />
                    </FormField>

                    {reviewForm.watch("reviewStatus") === REVIEW_STATUS.REJECTED && (
                        <FormField label="سبب الرفض *" error={reviewForm.formState.errors.rejectionReason?.message}>
                            <Textarea
                                {...reviewForm.register("rejectionReason")}
                                placeholder="أدخل سبب رفض الوثيقة..."
                                rows={2}
                            />
                        </FormField>
                    )}

                    <div className="mt-auto pt-2">
                        <Button
                            className="w-full"
                            onClick={reviewForm.handleSubmit(handleSubmitReview)}
                            disabled={reviewMutation.isPending}
                        >
                            {reviewMutation.isPending ? "جاري الحفظ..." : "حفظ نتيجة الفحص"}
                        </Button>
                    </div>
                </div>
            </div>
        </Card>
    );
}

import { zodResolver } from "@hookform/resolvers/zod";
import { Calendar } from "lucide-react";
import { Controller,useForm } from "react-hook-form";
import { z } from "zod";

import {
    BaseFormDialog,
    DateInput,
    FormField,
    FormSection,
    NoteBox,
    Textarea} from "@/components/ui";

// ─── Validation Schema ─────────────────────────────────

const endRecipientSchema = z.object({
    endDate: z.string().min(1, "تاريخ انتهاء الصرف مطلوب"),
    notes: z.string().trim().min(3, "يجب إدخال سبب الإنهاء (3 أحرف على الأقل)"),
});

export type EndRecipientFormValues = z.infer<typeof endRecipientSchema>;

interface EndRecipientDialogProps {
    open?: boolean;
    isOpen?: boolean;
    onOpenChange?: (open: boolean) => void;
    onClose?: () => void;
    onSubmit: (values: EndRecipientFormValues) => void;
    isLoading?: boolean;
    recipientName: string;
}

/**
 * حوار إنهاء حالة مستلم المعاش - Named Export (Constraint 8)
 */
export function EndRecipientDialog({
    open,
    isOpen,
    onOpenChange,
    onClose,
    onSubmit,
    isLoading,
    recipientName
}: EndRecipientDialogProps) {
    const form = useForm<EndRecipientFormValues>({
        resolver: zodResolver(endRecipientSchema),
        defaultValues: {
            endDate: new Date().toISOString().split('T')[0],
            notes: "",
        }
    });

    const { register, formState: { errors, isDirty } } = form;

    return (
        <BaseFormDialog
            open={open}
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            onClose={onClose}
            title="إنهاء حالة مستلم المعاش"
            description={`أنت بصدد إيقاف صرف المستحقات المالية لـ: ${recipientName}`}
            size="md"
            isLoading={isLoading}
            isDirty={isDirty}
            onSubmit={form.handleSubmit(onSubmit)}
            resetOnOpen={true}
            reset={form.reset}
            showGlobalError
            formErrors={errors}
            submitLabel="تأكيد الإنهاء"
            className="border-t-4 border-t-destructive"
        >
            <div className="space-y-4 text-start">
                <FormSection title="تفاصيل الإنهاء" icon={Calendar}>
                    <div className="grid grid-cols-1 gap-4">
                        <FormField label="تاريخ انتهاء الاستحقاق" required error={errors.endDate?.message}>
                            <Controller
                                name="endDate"
                                control={form.control}
                                render={({ field }) => (
                                    <DateInput
                                        id={field.name}
                                        value={field.value || undefined}
                                        onChange={field.onChange}
                                        className="font-mono font-bold"
                                    />
                                )}
                            />
                        </FormField>

                        <FormField label="سبب الإنهاء / ملاحظات إدارية" required error={errors.notes?.message}>
                            <Textarea
                                {...register("notes")}
                                placeholder="يرجى توضيح سبب إيقاف الصرف لهذا المستلم..."
                                rows={2}
                                className="leading-relaxed"
                            />
                        </FormField>
                    </div>
                </FormSection>

                <NoteBox type="warning" title="تنبيه الإيقاف">
                    سيتم إيقاف تحويل المبالغ المالية لهذا المستلم بدءاً من التاريخ المحدد. هذا الإجراء سيؤثر على كشوفات الصرف القادمة للملف.
                </NoteBox>
            </div>
        </BaseFormDialog>
    );
}

