import { useQuery } from "@tanstack/react-query";
import { Percent } from "lucide-react";
import { useId } from "react";
import type { Ref } from "react";

import { retirementApi } from "@/api/retirement";
import { FormField, Input } from "@/components/ui";

interface EntitlementAmountFieldProps {
    retireeId?: number;
    value?: string;
    onChange: (value: string) => void;
    onBlur: () => void;
    inputRef?: Ref<HTMLInputElement>;
    savedSharePercent?: number | null;
    error?: string;
}

const numberFormat = new Intl.NumberFormat("ar-YE", { maximumFractionDigits: 2 });

export function EntitlementAmountField({ retireeId, value, onChange, onBlur, inputRef, savedSharePercent, error }: EntitlementAmountFieldProps) {
    const id = useId();
    const { data, isLoading, isError, refetch } = useQuery({
        queryKey: ["financial-entitlements", retireeId],
        queryFn: () => retirementApi.getFinancialEntitlements(retireeId!),
        enabled: !!retireeId,
    });
    // The API returns the latest entitlement first, matching amount conversion on save.
    const pensionAmount = data?.find(item => item.entitlementID > 0)?.amount;
    const hasPension = pensionAmount != null && pensionAmount > 0;
    const savedAmount = hasPension && savedSharePercent != null
        ? (pensionAmount * savedSharePercent / 100).toFixed(2) : "";
    const displayedValue = value ?? savedAmount;
    const amount = Number(displayedValue);
    const percent = hasPension && displayedValue !== "" && Number.isFinite(amount) && amount > 0
        ? amount / pensionAmount * 100 : null;
    const exceedsPension = hasPension && amount > pensionAmount;

    return (
        <div className="rounded-xl border border-border bg-muted/20 p-4 space-y-3">
            <div className="grid grid-cols-[minmax(0,1fr)_minmax(96px,0.55fr)] gap-3 items-start">
                <FormField label="مبلغ الاستحقاق الشهري (ريال)" htmlFor={id} error={error || (exceedsPension ? "المبلغ يتجاوز إجمالي المعاش" : undefined)}>
                    <Input id={id} ref={inputRef} type="number" inputMode="decimal" min="0.01" max={hasPension ? pensionAmount : undefined} step="0.01"
                        value={displayedValue} onChange={event => onChange(event.target.value)} onBlur={onBlur}
                        disabled={!hasPension || isError} placeholder="0.00" dir="ltr" className="h-11 sm:h-10 text-base font-semibold tabular-nums text-start" />
                </FormField>
                <div className="space-y-1">
                    <span id={`${id}-percentage-label`} className="label-field flex items-center gap-1.5"><Percent className="h-4 w-4" aria-hidden="true" />النسبة المحسوبة</span>
                    <output aria-labelledby={`${id}-percentage-label`} aria-live="polite" className={`flex h-11 sm:h-10 items-center justify-center rounded-md border text-base font-bold tabular-nums ${exceedsPension ? "border-destructive bg-destructive/10 text-destructive" : "border-primary bg-primary/5 text-primary"}`}>
                        {percent == null ? "—" : `${numberFormat.format(percent)}٪`}
                    </output>
                </div>
            </div>
            <p className="text-xs text-muted-foreground">
                {isLoading ? "جارٍ تحميل إجمالي المعاش…" : isError ? "تعذر تحميل إجمالي المعاش." : hasPension
                    ? `من إجمالي معاش ${numberFormat.format(pensionAmount)} ريال. تُحسب النسبة تلقائياً عند الحفظ.`
                    : "يجب تسجيل الاستحقاق المالي للمتقاعد أولاً لحساب حصة المستحق."}
            </p>
            {savedSharePercent != null && <p className="text-xs text-muted-foreground">الحصة المحفوظة: {numberFormat.format(savedSharePercent)}٪. ترك المبلغ فارغاً يحافظ عليها.</p>}
            {isError && <button type="button" onClick={() => void refetch()} className="min-h-11 text-sm text-primary underline">إعادة المحاولة</button>}
        </div>
    );
}

"use no memo";

import { zodResolver } from "@hookform/resolvers/zod";
import { FileText,Gavel, ShieldCheck } from "lucide-react";
import { Controller,useForm, useWatch } from "react-hook-form";
import { z } from "zod";

import { DocumentChecklistField } from "@/components/domain/retirement/DocumentChecklistField";
import {
  BaseFormDialog,
  DateInput,
  FileField,
  FormField,
  FormSection,
  Input,
  NoteBox,
  Textarea,
} from "@/components/ui";
import type { MissingDocOption } from "@/utils/missing-documents";

// ─── Validation Schema ─────────────────────────────────

const exemptionSchema = z.object({
  missingDocumentIDs: z.array(z.union([z.number(), z.string()])).min(1, "يجب اختيار وثيقة واحدة على الأقل"),
  directiveSource: z.string().trim().min(3, "مصدر التوجيه مطلوب"),
  exemptionDate: z.string().min(1, "تاريخ الإعفاء مطلوب"),
  notes: z.string().trim().optional().or(z.literal("")),
  exemptionFile: z.instanceof(File).optional().nullable(),
});

export type ExemptionFormValues = z.infer<typeof exemptionSchema>;

interface ExemptionDialogProps {
    open?: boolean;
    isOpen?: boolean;
    onOpenChange?: (open: boolean) => void;
    onClose?: () => void;
    onSubmit: (values: ExemptionFormValues) => void;
    isLoading?: boolean;
    mode: "create" | "edit";
    missingDocs: MissingDocOption[];
    initialData?: Partial<ExemptionFormValues>;
}

/**
 * حوار تسجيل إعفاء جديد - Named Export (Constraint 8)
 */
export function ExemptionDialog({
    open,
    isOpen,
    onOpenChange,
    onClose,
    onSubmit,
    isLoading,
    mode,
    missingDocs,
    initialData
}: ExemptionDialogProps) {
    const form = useForm<ExemptionFormValues>({
        resolver: zodResolver(exemptionSchema),
        defaultValues: {
            missingDocumentIDs: initialData?.missingDocumentIDs || [],
            directiveSource: initialData?.directiveSource || "",
            exemptionDate: initialData?.exemptionDate || new Date().toISOString().split('T')[0],
            notes: initialData?.notes || "",
            exemptionFile: null,
        }
    });

    const { control, register, setValue, formState: { errors, isDirty } } = form;
    const selectedDocIDs = useWatch({ control, name: "missingDocumentIDs" }) || [];

    return (
        <BaseFormDialog
            open={open}
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            onClose={onClose}
            title={mode === "create" ? "تسجيل إعفاء جديد" : "تعديل بيانات الإعفاء"}
            description="إسقاط المطالبة بوثيقة ناقصة بناءً على توجيه رسمي"
            size="full"
            isLoading={isLoading}
            isDirty={isDirty}
            onSubmit={form.handleSubmit(onSubmit)}
            resetOnOpen={true}
            reset={form.reset}
            showGlobalError
            formErrors={errors}
            submitLabel={mode === "create" ? "إضافة الإعفاء" : "حفظ التعديلات"}
        >
            <div className="space-y-4 text-start" dir="rtl">
                <FormSection title="الوثائق المعفاة" icon={ShieldCheck}>
                    <DocumentChecklistField
                        selectedIds={selectedDocIDs}
                        documents={missingDocs}
                        onChange={(ids) => setValue("missingDocumentIDs", ids, { shouldDirty: true })}
                        error={errors.missingDocumentIDs?.message}
                        label="اختر الوثائق من قائمة النواقص"
                    />
                </FormSection>

                <FormSection title="تفاصيل توجيه الإعفاء" icon={Gavel}>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <FormField label="مصدر التوجيه الرسمي" required error={errors.directiveSource?.message}>
                            <Input {...register("directiveSource")} placeholder="مثال: مدير الصندوق، الوزير..." />
                        </FormField>
                        <FormField label="تاريخ صدور التوجيه" required error={errors.exemptionDate?.message}>
                            <Controller
                                name="exemptionDate"
                                control={control}
                                render={({ field }) => (
                                    <DateInput
                                        id={field.name}
                                        value={field.value || undefined}
                                        onChange={field.onChange}
                                        className="font-mono font-bold"
                                    />
                                )}
                            />
                        </FormField>
                    </div>
                </FormSection>
                
                <FormSection title="ملاحظات ومرفقات الإعفاء" icon={FileText}>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <FormField label="ملاحظات (اختياري)" error={errors.notes?.message}>
                            <Textarea {...register("notes")} placeholder="تفاصيل إضافية حول سبب الإعفاء..." rows={1} />
                        </FormField>
                        <FileField name="exemptionFile" control={control} label="مرفق التوجيه (اختياري)" size="sm" />
                    </div>
                </FormSection>

                 <NoteBox type="warning" title="الأثر القانوني">
                    بموجب هذا الإجراء، سيتم إسقاط المطالبة بهذه الوثائق بشكل نهائي من الملف التقاعدي.
                </NoteBox>
            </div>
        </BaseFormDialog>
    );
}

import { ArrowRight, CheckCircle2, Eye,Printer, XCircle } from "lucide-react";
import { useNavigate } from "react-router-dom";

import { PermissionGate } from "@/components/auth/PermissionGate";
import { Button, Text } from "@/components/ui";
import { Badge } from "@/components/ui";
import { RecordStateBadge } from "@/components/ui";

interface FileReviewHeaderProps {
    fileId: number;
    fileNumber: string;
    retireeName: string;
    statusID: number | null;
    statusName: string | null;
    pendingReviewCount: number;
    missingDocsCount: number;
    onToggleReviewPanel: () => void;
    onApprove: () => void;
    isApproving: boolean;
    onReject: () => void;
    isRejecting: boolean;
}

export function FileReviewHeader({
    fileId,
    fileNumber,
    retireeName,
    statusID,
    pendingReviewCount,
    onToggleReviewPanel,
    onApprove,
    isApproving,
    onReject,
    isRejecting,
}: FileReviewHeaderProps) {
    const navigate = useNavigate();

    return (
        <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
                <Button
                    variant="ghost"
                    size="icon"
                    onClick={() => navigate("/files")}
                    aria-label="العودة لقائمة الملفات"
                >
                    <ArrowRight className="w-4 h-4" />
                </Button>
                <div className="w-px h-8 bg-border" />
                <div>
                    <div className="flex items-center gap-2">
                        <span className="text-lg font-bold">ملف رقم {fileNumber}</span>
                        {statusID && <RecordStateBadge state={statusID as any} />}
                    </div>
                    <Text variant="description">{retireeName}</Text>
                </div>
            </div>

            <div className="flex items-center gap-2">
                <Button variant="outline" size="sm" onClick={onToggleReviewPanel}>
                    <Eye className="w-4 h-4 ms-1" />
                    مراجعة التعديلات
                    {pendingReviewCount > 0 && (
                        <Badge variant="danger" className="me-2 text-[10px] px-1.5 py-0.5">
                            {pendingReviewCount}
                        </Badge>
                    )}
                </Button>

                <PermissionGate permission="File.Review.Approve">
                    <Button
                        variant="success"
                        size="sm"
                        onClick={onApprove}
                        loading={isApproving}
                    >
                        <CheckCircle2 className="w-4 h-4 ms-1" />
                        اعتماد
                    </Button>
                </PermissionGate>

                <PermissionGate permission="File.Review.Reject">
                    <Button
                        variant="destructive"
                        size="sm"
                        onClick={onReject}
                        loading={isRejecting}
                    >
                        <XCircle className="w-4 h-4 ms-1" />
                        رفض
                    </Button>
                </PermissionGate>

                <Button
                    variant="outline"
                    size="sm"
                    onClick={() => navigate(`/files/${fileId}/print`)}
                >
                    <Printer className="w-4 h-4 ms-1" />
                    طباعة
                </Button>
            </div>
        </div>
    );
}

import { DollarSign, FileText, FileWarning, History, MapPin, Shield, User,UserCheck, UserCircle2, Users } from "lucide-react";

import { Badge, Button } from "@/components/ui";
import { Heading } from "@/components/ui";
import { Text } from "@/components/ui";
import { RecordStateBadge } from "@/components/ui";
import { REVIEW_SECTIONS, REVIEW_SECTIONS_AR } from "@/constants";
import { cn, getDefaultDeceasedAvatar, getPhotoUrl, getStatusColorClass, resolvePersonalPhotoPath } from "@/lib/utils";
import type { RetireeDetail, RetirementFileDetail, ReviewSection } from "@/types/retirement";

interface FileReviewSidebarProps {
    file: RetirementFileDetail;
    retiree: RetireeDetail;
    activeSection: ReviewSection;
    onSectionChange: (section: ReviewSection) => void;
    missingDocsCount: number;
    missingDataCount: number;
    pendingReviewCount: number;
}

const navItems: { key: ReviewSection; icon: typeof Users; permission?: string }[] = [
    { key: REVIEW_SECTIONS.BASIC, icon: Users },
    { key: REVIEW_SECTIONS.PEOPLE, icon: UserCheck },
    { key: REVIEW_SECTIONS.DOCUMENTS, icon: FileText },
    { key: REVIEW_SECTIONS.FINANCIAL, icon: DollarSign },
    { key: REVIEW_SECTIONS.HISTORY, icon: History },
];

export function FileReviewSidebar({
    file,
    retiree,
    activeSection,
    onSectionChange,
    missingDocsCount,
    pendingReviewCount: _pendingReviewCount,
}: FileReviewSidebarProps) {
    const photoUrl = getPhotoUrl(resolvePersonalPhotoPath(retiree)) ?? (getPhotoUrl(resolvePersonalPhotoPath(file)) ?? (!file.isAlive ? getDefaultDeceasedAvatar(file.gender) : null));

    return (
        <div className="flex flex-col h-full min-w-0">
            {/* ─── بطاقة الهوية الرئيسية ─── */}
            <div className="relative overflow-hidden border-b border-border">
                {/* خلفية علوية متدرجة */}
                <div className="h-16 bg-gradient-to-br from-primary/15 via-primary/5 to-background relative">
                    <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_top_right,var(--primary)_0%,transparent_60%)] opacity-100" />
                    <div className="absolute bottom-0 inset-x-0 h-px bg-gradient-to-r from-transparent via-primary/20 to-transparent" />
                </div>

                {/* محتوى البطاقة */}
                <div className="px-3 pb-4 -mt-10 relative">
                    <div className="flex flex-col items-center">
                        {/* الصورة الشخصية */}
                        <div className="relative group">
                            <div className="absolute -inset-0.5 bg-gradient-to-br from-primary/30 to-primary/10 rounded-2xl blur opacity-100 group-hover:opacity-100 transition duration-500" />
                            {photoUrl ? (
                                <img
                                    src={photoUrl}
                                    alt={file.retireeFullName}
                                    className="relative w-20 h-28 rounded-2xl border-[4px] border-card object-cover bg-muted transition-all duration-300 group-hover:scale-[1.02]"
                                />
                            ) : (
                                <div className="relative w-20 h-28 rounded-2xl border-[4px] border-card bg-muted flex items-center justify-center">
                                    <User className="w-8 h-8 text-muted-foreground" />
                                </div>
                            )}
                            {/* شارة الحالة على الصورة */}
                            <div className={cn(
                                "absolute -bottom-1 -right-1 w-4 h-4 rounded-full border-[2px] border-card",
                                file.isAlive ? "bg-emerald-500" : "bg-red-500"
                            )}>
                                {file.isAlive && (
                                    <div className="absolute inset-0 rounded-full bg-emerald-500 animate-ping opacity-100" />
                                )}
                            </div>
                        </div>

                        {/* الاسم والرتبة */}
                        <div className="text-center mt-2.5 space-y-1 min-w-0 w-full">
                            <Heading level="h4" className={cn(
                                "text-sm leading-tight truncate",
                                getStatusColorClass(file.statusID)
                            )}>
                                {file.retireeFullName}
                            </Heading>
                            <div className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-primary/8 text-primary text-[10px] font-semibold">
                                <Shield className="w-2.5 h-2.5" />
                                <span className="truncate">{file.rankName || "رتبة غير محددة"}</span>
                            </div>
                        </div>
                    </div>

                    {/* معلومات سريعة */}
                    <div className="mt-3 space-y-1.5">
                        <InfoPill
                            icon={<UserCircle2 className="w-3 h-3" />}
                            label="الرقم الوطني"
                            value={file.nationalID || "—"}
                            dir="ltr"
                        />
                        <InfoPill
                            icon={<MapPin className="w-3 h-3" />}
                            label="العنوان"
                            value={retiree.governorate && retiree.city ? `${retiree.governorate}، ${retiree.city}` : retiree.governorate || retiree.city || "—"}
                        />
                    </div>

                    {/* شارة الحالة */}
                    <div className="flex justify-center mt-3">
                        <RecordStateBadge state={(file.statusID as any) || "active"} />
                    </div>
                </div>
            </div>

            {/* ─── التنقل بين الأقسام ─── */}
            <nav className="flex-1 py-2 px-2 space-y-1">
                {navItems.map((item) => {
                    const Icon = item.icon;
                    const isActive = activeSection === item.key;
                    return (
                        <Button
                            key={item.key}
                            variant={isActive ? "default" : "ghost"}
                            className="w-full justify-start gap-2 px-3 py-2.5 h-auto truncate"
                            onClick={() => onSectionChange(item.key)}
                        >
                            <Icon className="w-4 h-4 shrink-0" />
                            <span className="truncate">{REVIEW_SECTIONS_AR[item.key]}</span>
                            {item.key === REVIEW_SECTIONS.DOCUMENTS && missingDocsCount > 0 && (
                                <Badge variant="danger" className="me-auto text-[10px] px-1.5 py-0.5 shrink-0">
                                    {missingDocsCount}
                                </Badge>
                            )}
                        </Button>
                    );
                })}
            </nav>

            {missingDocsCount > 0 && (
                <div className="px-3 pb-3">
                    <div className="bg-red-50 dark:bg-red-950/20 border border-red-200 dark:border-red-800 rounded-lg px-2 py-2 flex items-center gap-2">
                        <FileWarning className="w-4 h-4 text-red-500 shrink-0" />
                        <Text variant="small" className="text-red-700 dark:text-red-400 truncate">
                            {missingDocsCount} وثائق ناقصة
                        </Text>
                    </div>
                </div>
            )}
        </div>
    );
}

/* ─── مكون مساعد ─── */
function InfoPill({ icon, label, value, dir }: { icon: React.ReactNode; label: string; value: string; dir?: string }) {
    return (
        <div className="flex items-center justify-between gap-2 p-2 rounded-xl bg-muted/40 border border-border hover:bg-muted/60 transition-colors group min-w-0">
            <div className="flex items-center gap-1.5 text-muted-foreground shrink-0">
                {icon}
                <span className="text-xs font-bold">{label}</span>
            </div>
            <p className="text-xs font-semibold text-foreground truncate min-w-0 text-end" title={value} dir={dir}>
                {value}
            </p>
        </div>
    );
}

