import { useQuery,useQueryClient } from "@tanstack/react-query";
import { Link as LinkIcon, Loader2,Search } from "lucide-react";
import { useEffect,useState } from "react";

import { retireeApi } from "@/api/retirees";
import type { RetireeListItem } from "@/api/retirees";
import type { SettlementItemDto } from "@/api/settlements";
import { settlementApi } from "@/api/settlements";
import { Badge,BaseFormDialog, Button, Input, Text } from "@/components/ui";
import { useApiMutation } from "@/hooks";
import { cn } from "@/lib/utils";

interface LinkRetireeDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    item: SettlementItemDto | null;
    onLinked: () => void;
}

export function LinkRetireeDialog({ open, onOpenChange, item, onLinked }: LinkRetireeDialogProps) {
    const queryClient = useQueryClient();
    const [searchTerm, setSearchTerm] = useState("");
    const [debouncedSearch, setDebouncedSearch] = useState("");
    const [selectedRetireeId, setSelectedRetireeId] = useState<number | null>(null);

    useEffect(() => {
        const timer = setTimeout(() => {
            setDebouncedSearch(searchTerm);
        }, 500);
        return () => clearTimeout(timer);
    }, [searchTerm]);

    // Reset state when opening a new item
    useEffect(() => {
        if (open) {
            const timer = setTimeout(() => {
                setSearchTerm("");
                setDebouncedSearch("");
                setSelectedRetireeId(item?.retireeID ?? null);
            }, 0);
            return () => clearTimeout(timer);
        }
    }, [open, item]);

    const { data: searchResults, isLoading: isSearching } = useQuery({
        queryKey: ["retirees-search", debouncedSearch],
        queryFn: () => retireeApi.getAll({ page: 1, pageSize: 15, search: debouncedSearch, isProcessed: true }),
        enabled: open && debouncedSearch.length > 1,
    });

    const linkMutation = useApiMutation(
        async () => {
            if (!item || !selectedRetireeId) return;
            
            await settlementApi.linkItem({
                settlementItemID: item.settlementItemID,
                retireeID: selectedRetireeId
            });
        },
        {
            successMessage: "تم ربط المتقاعد بنجاح",
            onSuccessCallback: () => {
                if (selectedRetireeId) {
                    queryClient.invalidateQueries({ queryKey: ["financial-entitlements", selectedRetireeId] });
                    queryClient.invalidateQueries({ queryKey: ["active-entitlement", selectedRetireeId] });
                    queryClient.invalidateQueries({ queryKey: ["retiree-statement", String(selectedRetireeId)] });
                    queryClient.invalidateQueries({ queryKey: ["settlements", selectedRetireeId] });
                    queryClient.invalidateQueries({ queryKey: ["retiree", selectedRetireeId] });
                    queryClient.invalidateQueries({ queryKey: ["retirement-file"] });
                    queryClient.invalidateQueries({ queryKey: ["financial-entitlements-search"] });
                }
                onLinked();
                onOpenChange(false);
            }
        }
    );

    const handleLink = () => {
        if (!selectedRetireeId) return;
        linkMutation.mutate({}); // Passing empty object to satisfy type requirement
    };

    return (
        <BaseFormDialog
            open={open}
            onOpenChange={onOpenChange}
            title="ربط قيد بملف متقاعد"
            size="md"
            footer={
                <div className="flex justify-end gap-2 w-full">
                    <Button variant="outline" onClick={() => onOpenChange(false)}>إلغاء</Button>
                    <Button
                        className="gap-2"
                        onClick={handleLink}
                        loading={linkMutation.isPending}
                        disabled={!selectedRetireeId}
                    >
                        <LinkIcon className="w-4 h-4" />
                        اعتماد الربط
                    </Button>
                </div>
            }
        >
            <div className="space-y-6" dir="rtl">
                {/* Item Info */}
                {item && (
                    <div className="bg-muted/30 p-4 rounded-xl border border-primary">
                        <h4 className="text-sm font-bold text-muted-foreground mb-3 border-b pb-2">بيانات القيد في القرار</h4>
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 text-sm">
                            <div>
                                <Text variant="caption" className="mb-1">الاسم كما ورد في القرار</Text>
                                <p className="font-bold">{item.retireeFullName}</p>
                            </div>
                            <div>
                                <Text variant="caption" className="mb-1">الرقم العسكري</Text>
                                <p className="font-mono">{item.militaryNumber || "غير متوفر"}</p>
                            </div>
                        </div>
                        {item.retireeID && <p className="mt-3 text-xs text-muted-foreground">المتقاعد المرتبط حاليًا: {item.retireeID}. الاستحقاق المالي مُنشأ بالفعل؛ إعادة الربط بمتقاعد آخر غير مسموح.</p>}
                    </div>
                )}

                {/* Search */}
                <div className="space-y-3">
                    <h4 className="text-sm font-bold">البحث عن المتقاعد في النظام</h4>
                    <div className="relative">
                        <Search className="absolute end-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                        <Input
                            placeholder="ابحث بالاسم أو الرقم العسكري أو الوطني..."
                            className="pe-9"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            autoComplete="off"
                        />
                    </div>
                </div>

                {/* Results Area */}
                <div className="max-h-64 h-auto overflow-y-auto border rounded-xl divide-y bg-card flex flex-col items-center">
                    {!debouncedSearch || debouncedSearch.length < 2 ? (
                        <div className="text-sm text-muted-foreground m-auto p-4 text-center">
                            الرجاء إدخال حرفين على الأقل للبحث عن المتقاعدين.
                        </div>
                    ) : isSearching ? (
                        <div className="flex items-center gap-2 m-auto p-4 text-muted-foreground">
                            <Loader2 className="w-4 h-4 animate-spin" /> جاري البحث...
                        </div>
                    ) : searchResults?.items?.length === 0 ? (
                        <div className="text-sm text-muted-foreground m-auto p-4 text-center">
                            لا يوجد نتائج متطابقة للبحث.
                        </div>
                    ) : (
                        <div className="w-full flex flex-col">
                            {searchResults?.items.map((retiree: RetireeListItem) => (
                                <div
                                    key={retiree.retireeID}
                                    onClick={() => setSelectedRetireeId(retiree.retireeID)}
                                    onKeyDown={(e: React.KeyboardEvent) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setSelectedRetireeId(retiree.retireeID); } }}
                                    role="button"
                                    tabIndex={0}
                                    className={cn(
                                        "p-3 flex items-start gap-3 cursor-pointer transition-colors focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-inset hover:bg-muted/40",
                                        selectedRetireeId === retiree.retireeID ? "bg-primary/5 border-e-[3px] border-e-primary" : ""
                                    )}
                                >
                                    <div className="w-10 h-10 rounded-full bg-secondary text-secondary-foreground flex items-center justify-center font-bold shrink-0">
                                        {retiree.fullName.charAt(0)}
                                    </div>
                                    <div className="flex-1 space-y-1 text-sm text-start">
                                        <p className="font-bold">{retiree.fullName}</p>
                                        <div className="flex flex-wrap gap-2">
                                            {retiree.militaryNumber && (
                                                <span className="text-muted-foreground text-xs">الرقم العسكري: <span className="font-mono" dir="ltr">{retiree.militaryNumber}</span></span>
                                            )}
                                        </div>
                                    </div>
                                    <div className="shrink-0 text-start">
                                        <Badge variant="outline">{retiree.rankName || "بدون رتبة"}</Badge>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>
        </BaseFormDialog>
    );
}

import { zodResolver } from "@hookform/resolvers/zod";
import { useQuery } from "@tanstack/react-query";
import { Ban, FileText, Landmark, Search } from "lucide-react";
import { useState } from "react";
import { useForm } from "react-hook-form";
import { z } from "zod";

import { retirementApi } from "@/api/retirement";
import {
    BaseFormDialog,
    Button,
    FormField,
    FormSection,
    Input,
    Text,
    Textarea} from "@/components/ui";

// ─── Validation Schema ─────────────────────────────────

const suspensionSchema = z.object({
    fileID: z.number({ message: "يجب اختيار ملف التقاعد" }).min(1, "يجب اختيار ملف التقاعد"),
    suspensionReason: z.string().trim().min(5, "يجب إدخال سبب الإيقاف (5 أحرف على الأقل)"),
    suspensionSource: z.string().trim().min(3, "يجب إدخال مصدر الإيقاف (الجهة أو الأمر الإداري)"),
});

export type CreateSuspensionFormValues = z.infer<typeof suspensionSchema>;

interface CreateSuspensionDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onCreated?: () => void;
}

// ─── File Search Result Type ────────────────────────────

interface FileSearchResult {
    fileID: number;
    fileNumber: string;
    retireeFullName: string;
    rankName?: string;
    statusName: string;
}

/**
 * حوار إنشاء إيقاف معاش جديد — مع بحث عن الملف
 */
export function CreateSuspensionDialog({ open, onOpenChange, onCreated }: CreateSuspensionDialogProps) {
    const [searchTerm, setSearchTerm] = useState("");
    const [selectedFile, setSelectedFile] = useState<FileSearchResult | null>(null);

    const form = useForm<CreateSuspensionFormValues>({
        resolver: zodResolver(suspensionSchema),
        defaultValues: {
            fileID: 0,
            suspensionReason: "",
            suspensionSource: "",
        }
    });

    const { register, setValue, handleSubmit, formState: { errors, isDirty }, reset } = form;

    // ── Search for files ────────────────────────────────
    const { data: searchResults = [], isLoading: isSearching } = useQuery({
        queryKey: ["file-search-suspension", searchTerm],
        queryFn: async () => {
            if (searchTerm.length < 2) return [];
            const res = await retirementApi.getFiles({ page: 1, pageSize: 10, search: searchTerm });
            return (res?.items || []).map((item: any) => ({
                fileID: item.fileID,
                fileNumber: item.fileNumber,
                retireeFullName: item.retireeFullName,
                rankName: item.rankName,
                statusName: item.fileStatusName || item.statusName || "",
            })) as FileSearchResult[];
        },
        enabled: searchTerm.length >= 2,
        staleTime: 3000,
    });

    const handleFileSelect = (file: FileSearchResult) => {
        setSelectedFile(file);
        setValue("fileID", file.fileID, { shouldDirty: true, shouldValidate: true });
        setSearchTerm("");
    };

    const handleFormSubmit = async (values: CreateSuspensionFormValues) => {
        try {
            await retirementApi.createSuspension({
                fileID: values.fileID,
                suspensionReason: values.suspensionReason,
                suspensionSource: values.suspensionSource,
            } as any);
            reset();
            setSelectedFile(null);
            onOpenChange(false);
            onCreated?.();
        } catch (error: any) {
            const msg = error?.response?.data?.message || error?.message || "فشل إنشاء الإيقاف";
            alert(msg);
        }
    };

    const handleOpenChange = (isOpen: boolean) => {
        if (!isOpen) {
            reset();
            setSelectedFile(null);
            setSearchTerm("");
        }
        onOpenChange(isOpen);
    };

    return (
        <BaseFormDialog
            open={open}
            onOpenChange={handleOpenChange}
            title="إيقاف معاش جديد"
            description="إنشاء قرار إيقاف صرف معاش لملف تقاعد محدد"
            size="full"
            isLoading={form.formState.isSubmitting}
            isDirty={isDirty}
            onSubmit={handleSubmit(handleFormSubmit)}
            resetOnOpen={true}
            reset={reset}
            showGlobalError
            formErrors={errors}
            submitLabel="تأكيد الإيقاف"
            className="border-t-4 border-t-destructive"
        >
            <div className="space-y-4 text-start">
                {/* ── اختيار الملف ── */}
                <FormSection title="اختيار ملف التقاعد" icon={FileText}>
                    {selectedFile ? (
                        <div className="flex items-center justify-between p-3 bg-destructive/5 border border-destructive rounded-xl">
                            <div className="flex items-center gap-3">
                                <div className="bg-destructive/10 p-2 rounded-lg">
                                    <FileText className="w-4 h-4 text-destructive" />
                                </div>
                                <div>
                                <Text variant="body" className="font-bold">{selectedFile.fileNumber}</Text>
                                <Text variant="caption">{selectedFile.retireeFullName} — {selectedFile.rankName}</Text>
                                </div>
                            </div>
                            <Button
                                type="button"
                                variant="link"
                                size="sm"
                                className="h-auto p-0 text-destructive"
                                onClick={() => { setSelectedFile(null); setValue("fileID", 0); }}
                            >
                                تغيير
                            </Button>
                        </div>
                    ) : (
                        <div className="space-y-2">
                            <div className="relative">
                                <Search className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                                <Input
                                    placeholder="ابحث برقم الملف أو اسم المتقاعد..."
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                    className="pr-10"
                                />
                            </div>
                            {searchResults.length > 0 && (
                                <div className="border border-border rounded-xl max-h-48 overflow-y-auto">
                                    {searchResults.map((file) => (
                                        <Button
                                            key={file.fileID}
                                            type="button"
                                            variant="ghost"
                                            className="w-full justify-start gap-3 p-3 h-auto border-b border-border last:border-0 text-start"
                                            onClick={() => handleFileSelect(file)}
                                        >
                                            <FileText className="w-4 h-4 text-muted-foreground shrink-0" />
                                            <div className="min-w-0 text-start">
                                                <Text variant="body" className="font-bold truncate">{file.fileNumber}</Text>
                                                <Text variant="caption" className="truncate">{file.retireeFullName} — {file.rankName}</Text>
                                            </div>
                                            <span className="mr-auto text-xs text-muted-foreground">{file.statusName}</span>
                                        </Button>
                                    ))}
                                </div>
                            )}
                            {searchTerm.length >= 2 && searchResults.length === 0 && !isSearching && (
                                <Text variant="description" className="text-center py-4">لا توجد نتائج مطابقة</Text>
                            )}
                        </div>
                    )}
                    {errors.fileID && <Text variant="body-sm" className="text-destructive mt-1">{errors.fileID.message}</Text>}
                </FormSection>

                {/* ── تفاصيل الإيقاف ── */}
                <FormSection title="تفاصيل قرار الإيقاف" icon={Ban}>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <FormField label="سبب الإيقاف القانوني" required error={errors.suspensionReason?.message}>
                            <Textarea
                                {...register("suspensionReason")}
                                placeholder="يرجى توضيح السبب التفصيلي لإيقاف صرف المعاش..."
                                rows={3}
                                className="leading-relaxed"
                            />
                        </FormField>

                        <FormField label="مصدر الإيقاف (الجهة / الأمر)" required error={errors.suspensionSource?.message}>
                            <Input
                                {...register("suspensionSource")}
                                placeholder="مثال: مدير المعاشات.."
                                icon={Landmark}
                            />
                        </FormField>
                    </div>
                </FormSection>

          
            </div>
        </BaseFormDialog>
    );
}

import { ChevronDown } from "lucide-react";
import { memo, useCallback, useMemo, useState } from "react";
import { NavLink, useLocation } from "react-router-dom";

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from "@/components/ui";
import { cn } from "@/lib/utils";
import { useAuthStore } from "@/stores/authStore";

import {
  filterByPermissions,
  groupIcons,
  groupLabels,
  type NavGroup,
  type NavItem,
  subGroupLabels,
} from "./navigationData";

// ─── Helpers ──────────────────────────────────────────────

function isActiveGroup(items: NavItem[], pathname: string): boolean {
  return items.some(
    (item) => pathname === item.path || pathname.startsWith(item.path + "/")
  );
}

// ─── DropdownNavLink (styled item inside dropdown) ──────

const DropdownNavLink = memo(function DropdownNavLink({
  item,
  onSelect,
}: {
  item: NavItem;
  onSelect: () => void;
}) {
  return (
    <DropdownMenuItem asChild>
      <NavLink
        to={item.path}
        onClick={onSelect}
        className={({ isActive }) =>
          cn(
            "flex items-center gap-2.5 px-3 py-2.5 text-base rounded-lg cursor-pointer",
            "transition-colors duration-150",
            isActive
              ? "bg-primary/10 text-primary font-semibold"
              : "text-foreground hover:bg-muted hover:text-foreground"
          )
        }
      >
        <span className="shrink-0 text-muted-foreground">{item.icon}</span>
        <span className="truncate">{item.label}</span>
      </NavLink>
    </DropdownMenuItem>
  );
});

// ─── NavDropdown Component ──────────────────────────────

interface NavDropdownProps {
  group: NavGroup;
  items: NavItem[];
}

export const NavDropdown = memo(function NavDropdown({
  group,
  items,
}: NavDropdownProps) {
  const [open, setOpen] = useState(false);
  const location = useLocation();
  const permissions = useAuthStore((s) => s.permissions);

  const visibleItems = useMemo(
    () => filterByPermissions(items, permissions),
    [items, permissions]
  );

  if (visibleItems.length === 0) return null;

  const mainItems = visibleItems.filter((i) => !i.subGroup);
  const subGroups = Array.from(
    new Set(visibleItems.filter((i) => i.subGroup && !i.nestedIn).map((i) => i.subGroup!))
  );
  const isGroupActive = isActiveGroup(visibleItems, location.pathname);

  const handleSelect = useCallback(() => setOpen(false), []);

  return (
    <DropdownMenu open={open} onOpenChange={setOpen} dir="rtl">
      <DropdownMenuTrigger
        className={cn(
          "flex items-center gap-1.5 px-3 py-2 rounded-lg text-base font-semibold transition-colors duration-150 outline-none",
          "hover:bg-muted hover:text-foreground",
          "data-[state=open]:bg-muted data-[state=open]:text-foreground",
          "data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
          isGroupActive
            ? "text-primary bg-primary/5"
            : "text-muted-foreground"
        )}
      >
        <span className={cn("shrink-0", isGroupActive ? "text-primary" : "text-muted-foreground")}>
          {groupIcons[group]}
        </span>
        <span className="hidden lg:inline">{groupLabels[group]}</span>
        <ChevronDown
          className={cn(
            "h-3.5 w-3.5 shrink-0 transition-transform duration-200",
            open && "rotate-180"
          )}
        />
      </DropdownMenuTrigger>

      <DropdownMenuContent
        align="start"
        sideOffset={8}
        className={cn(
          "max-h-[70vh] overflow-y-auto",
          subGroups.length > 0 ? "w-[min(400px,90vw)]" : "w-[280px]"
        )}
      >
        {/* Main items (no subGroup) */}
        {mainItems.length > 0 && (
          <div className="p-2 pb-1">
            {mainItems.map((item) => (
              <DropdownNavLink key={item.path} item={item} onSelect={handleSelect} />
            ))}
          </div>
        )}

        {mainItems.length > 0 && subGroups.length > 0 && (
          <div className="mx-2 border-t border-border" />
        )}

        {/* All sub-groups — flat list with labels */}
        {subGroups.length > 0 && (
          <div className="p-2">
            {subGroups.map((sg) => {
              const sgDirectItems = visibleItems.filter(
                (i) => i.subGroup === sg && !i.nestedIn
              );
              const sgNestedGroups = Array.from(
                new Set(
                  visibleItems
                    .filter((i) => i.nestedIn === sg)
                    .map((i) => i.subGroup!)
                )
              );

              return (
                <div key={sg} className="mb-1">
                  {sgDirectItems.length > 0 && (
                    <DropdownMenuLabel className="px-2 py-1.5 text-[11px] font-bold text-muted-foreground uppercase tracking-wider">
                      {subGroupLabels[sg] || sg}
                    </DropdownMenuLabel>
                  )}
                  <div className="space-y-0.5">
                    {sgDirectItems.map((item) => (
                      <DropdownNavLink
                        key={item.path}
                        item={item}
                        onSelect={handleSelect}
                      />
                    ))}
                  </div>

                  {sgNestedGroups.map((nestedGroup) => (
                    <div key={nestedGroup} className="mt-2">
                      <div className="flex items-center gap-1.5 px-3 py-1 text-[10px] font-bold text-primary tracking-wider">
                        <div className="h-px w-2 bg-primary/30" />
                        {subGroupLabels[nestedGroup] || nestedGroup}
                      </div>
                      <div className="space-y-0.5 border-e-2 border-primary ms-1">
                        {visibleItems
                          .filter(
                            (i) => i.nestedIn === sg && i.subGroup === nestedGroup
                          )
                          .map((item) => (
                            <DropdownNavLink
                              key={item.path}
                              item={item}
                              onSelect={handleSelect}
                            />
                          ))}
                      </div>
                    </div>
                  ))}
                </div>
              );
            })}
          </div>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
});

import * as React from "react";
import type { DefaultValues, FieldErrors, FieldValues, UseFormReset } from "react-hook-form";

import { useConfirm } from "@/components/ui";
import type { ButtonVariant } from "@/components/ui/Dialog"; // استيراد النوع الموحد
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/Dialog";
import { useDialogKeyboard } from "@/constants/shortcuts";
import { useDialogReset } from "@/hooks/useDialogReset";
import { cn } from "@/lib/utils";

import { ErrorAlert } from "./ErrorAlert";
import { FormDialogFooter } from "./FormDialogFooter";

export interface BaseOverlayProps {
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  isOpen?: boolean;
  onClose?: () => void;
}

export interface BaseFormDialogProps<T extends FieldValues = FieldValues> extends BaseOverlayProps {
  title: string;
  description?: string;
  size?: "sm" | "md" | "lg" | "xl" | "2xl" | "3xl" | "4xl" | "5xl" | "6xl" | "full";
  isLoading?: boolean;
  isDirty?: boolean;
  onSubmit?: (e?: React.BaseSyntheticEvent) => Promise<void> | void;
  onSaveAndNew?: () => void | Promise<void>;
  children: React.ReactNode;
  submitLabel?: string;
  cancelLabel?: string;
  className?: string;
  formId?: string;
  resetOnOpen?: boolean;
  reset?: UseFormReset<T>;
  initialValues?: DefaultValues<T> | T;
  showGlobalError?: boolean;
  formErrors?: FieldErrors<T>;
  dirtyWarningMessage?: string;
  enableKeyboardShortcuts?: boolean;
  footer?: React.ReactNode;
  submitIcon?: React.ReactNode;
  submitVariant?: ButtonVariant; // تم توحيد النوع
  portal?: boolean;
}

export function BaseFormDialog<T extends FieldValues = FieldValues>({
  open: controlledOpen,
  onOpenChange: controlledOnOpenChange,
  isOpen: legacyOpen,
  onClose: legacyClose,
  title,
  description,
  size = "md",
  isLoading: providedIsLoading = false,
  isDirty = false,
  onSubmit,
  onSaveAndNew,
  children,
  footer,
  submitLabel = "حفظ",
  cancelLabel = "إلغاء",
  className,
  formId,
  resetOnOpen = true,
  reset,
  initialValues,
  showGlobalError = false,
  formErrors,
  dirtyWarningMessage = "لديك تغييرات غير محفوظة، هل أنت متأكد من الإغلاق؟",
  enableKeyboardShortcuts = true,
  submitIcon,
  submitVariant = "primary",
  portal = true,
}: BaseFormDialogProps<T>) {
  const [submitting, setSubmitting] = React.useState(false);
  const submitInFlight = React.useRef(false);
  const dialogRef = React.useRef<HTMLDivElement>(null);
  const isLoading = providedIsLoading || submitting;

  const open = controlledOpen !== undefined ? controlledOpen : !!legacyOpen;
  const onOpenChange = controlledOnOpenChange || ((v: boolean) => { if (!v) legacyClose?.(); });
  const { confirm, ConfirmDialogElement } = useConfirm();

  // 1. إصلاح الحلقة المفرغة: فصل طلب الإغلاق عن الإغلاق الفعلي
  const requestClose = React.useCallback(async () => {
    if (isDirty && !isLoading) {
      if (import.meta.env.DEV) {
        console.warn("[BaseFormDialog] unsaved-changes confirm", new Error("trace").stack);
      }
      const ok = await confirm({
        title: dirtyWarningMessage,
        variant: "warning",
      });
      if (ok) {
        onOpenChange?.(false);
      }
    } else if (!isLoading) {
      onOpenChange?.(false);
    }
  }, [isDirty, isLoading, onOpenChange, confirm, dirtyWarningMessage]);

  const dummyReset = React.useCallback(() => {}, []);
  useDialogReset(
    open,
    (reset as UseFormReset<T>) || (dummyReset as unknown as UseFormReset<T>),
    initialValues,
    resetOnOpen
  );

  const autoId = React.useId();
  const internalFormId = formId || `form-${autoId.replace(/:/g, "")}`;

  const triggerSubmit = React.useCallback(async (event?: React.BaseSyntheticEvent) => {
    if (!onSubmit || isLoading || submitInFlight.current) return;
    submitInFlight.current = true;
    setSubmitting(true);
    try {
      await onSubmit(event);
    } catch {
      // The mutation/form owns its error UI. Keep the form open and allow retry.
    } finally {
      submitInFlight.current = false;
      setSubmitting(false);
    }
  }, [onSubmit, isLoading]);

  const triggerSaveAndNew = React.useCallback(async () => {
    if (!onSaveAndNew || isLoading || submitInFlight.current) return;
    submitInFlight.current = true;
    setSubmitting(true);
    try {
      await onSaveAndNew();
    } catch {
      // The mutation/form owns its error UI. Keep the form open and allow retry.
    } finally {
      submitInFlight.current = false;
      setSubmitting(false);
    }
  }, [onSaveAndNew, isLoading]);

  useDialogKeyboard({
    isOpen: enableKeyboardShortcuts ? open : false,
    isDirty,
    isLoading,
    onClose: requestClose,
    onSubmit: triggerSubmit,
    onSaveAndNew: triggerSaveAndNew,
    dialogRef,
  });

  const handleOpenChange = React.useCallback((openState: boolean) => {
    if (!openState) {
      requestClose();
    } else {
      onOpenChange?.(true);
    }
  }, [requestClose, onOpenChange]);

  const handleCancel = React.useCallback(() => {
    requestClose();
  }, [requestClose]);

  // ─── حظر زر الرجوع في المتصفح عند وجود تغييرات غير محفوظة ───
  const dirtyRef = React.useRef(isDirty);
  const requestCloseRef = React.useRef(requestClose);
  const loadingRef = React.useRef(isLoading);
  React.useEffect(() => {
    dirtyRef.current = isDirty;
    loadingRef.current = isLoading;
    requestCloseRef.current = requestClose;
  }, [isDirty, isLoading, requestClose]);

  React.useEffect(() => {
    if (!open || !isDirty) return;

    const token = {};
    window.history.pushState({ __dlgBlock: token }, "");

    const handlePopState = () => {
      // pop ناتج عن تنظيف نافذة أخرى (لا ازاحة إلى صفحة سابقة) — لا نطلب إغلاق.
      if (window.history.state?.__dlgBlock) return;
      if (dirtyRef.current && !loadingRef.current) {
        window.history.pushState({ __dlgBlock: token }, "");
        requestCloseRef.current();
      }
    };

    window.addEventListener("popstate", handlePopState);

    const handleBeforeUnload = (e: BeforeUnloadEvent) => {
      if (dirtyRef.current) {
        e.preventDefault();
        e.returnValue = "";
      }
    };
    window.addEventListener("beforeunload", handleBeforeUnload);

    return () => {
      window.removeEventListener("popstate", handlePopState);
      window.removeEventListener("beforeunload", handleBeforeUnload);
      if (window.history.state?.__dlgBlock) {
        window.history.back();
      }
    };
  }, [open, isDirty]);

  // 2. إصلاح مشكلة النماذج: الحاوية دائماً form
  const hasErrors = formErrors && Object.keys(formErrors).length > 0;

  return (
    <>
      <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent
        ref={dialogRef}
        aria-labelledby={`${internalFormId}-title`}
        size={size}
        className={cn("flex flex-col p-0 overflow-visible outline-none", className)}
        removePadding // تمرير البروب بدلاً من البحث في النصوص
        portal={portal}
        onOpenAutoFocus={(e) => {
          const dialogEl = e.target as HTMLElement;
          const autoFocusEl = dialogEl.querySelector<HTMLElement>("[autofocus], [data-autofocus]");
          if (autoFocusEl) {
            e.preventDefault();
            setTimeout(() => autoFocusEl.focus(), 0);
          }
        }}
        onEscapeKeyDown={(e) => {
          // السماح بالإغلاق دائماً لتجنب حجز المستخدم
          if (isLoading) e.preventDefault(); 
        }}
        onInteractOutside={(e) => {
          // منع الإغلاق بالضغط خارج النافذة إذا كان هناك تغييرات أو تحميل
          if (isDirty || isLoading) e.preventDefault();
        }}
      >
        <form
          id={internalFormId}
          onSubmit={(e: React.FormEvent<HTMLFormElement>) => {
            e.preventDefault();
            void triggerSubmit(e);
          }}
          className="flex flex-col h-full min-h-0"
          noValidate
        >
          <DialogHeader className="shrink-0">
            <DialogTitle id={`${internalFormId}-title`} className="flex items-center gap-2 text-sm sm:text-base">
              {title}
            </DialogTitle>
            {description && (
              <DialogDescription className="max-w-full sm:max-w-[85%] text-xs sm:text-sm leading-relaxed">
                {description}
              </DialogDescription>
            )}
          </DialogHeader>

          <div className="flex-1 overflow-y-auto min-h-0 bg-muted/10 relative custom-scrollbar -webkit-overflow-scrolling-touch">
            <div className="p-[var(--dlg-section-p)] space-y-[var(--dlg-body-gap)] pb-4 sm:pb-0">
              {showGlobalError && hasErrors && (
                <ErrorAlert
