        <TabsContent value="quarterly">
          <BudgetReport
            data={report}
            isLoading={isLoading}
            onRefresh={refetch}
            showQuarters
            onEdit={(item) => {
              setEditItem(item);
              setShowForm(true);
            }}
            onDelete={async (item) => {
              const ok = await confirm({
                title: `هل أنت متأكد من حذف بند "${item.accountName}"؟`,
                variant: "danger",
              });
              if (ok) {
                deleteMutation.mutate(item.budgetItemID);
              }
            }}
          />
        </TabsContent>

        <TabsContent value="monthly">
          {/* فلتر الشهر */}
          <div className="mb-4">
            <Select
              value={selectedMonth != null ? String(selectedMonth) : "all"}
              onValueChange={(v) => setSelectedMonth(v === "all" ? null : Number(v))}
            >
              <SelectTrigger className="w-60">
                <SelectValue placeholder="اختر الشهر" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">جميع الشهور</SelectItem>
                {periods?.map((p) => (
                  <SelectItem key={p.periodID} value={String(p.periodID)}>
                    {p.periodName}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <BudgetReport
            data={report}
            isLoading={isLoading}
            onRefresh={refetch}
            showMonthly
            selectedMonth={selectedMonth}
            onEdit={(item) => {
              setEditItem(item);
              setShowForm(true);
            }}
            onDelete={async (item) => {
              const ok = await confirm({
                title: `هل أنت متأكد من حذف بند "${item.accountName}"؟`,
                variant: "danger",
              });
              if (ok) {
                deleteMutation.mutate(item.budgetItemID);
              }
            }}
          />
        </TabsContent>
      </Tabs>

      {/* Form Dialog */}
      <BudgetFormDialog
        open={showForm}
        onOpenChange={(open) => {
          setShowForm(open);
          if (!open) setEditItem(null);
        }}
        fiscalYearID={fiscalYearID}
        editItem={editItem}
        onSuccess={() => {
          setShowForm(false);
          setEditItem(null);
          refetch();
        }}
      />

      {/* Seed Budget Confirm */}
      <ConfirmDialog
        open={showSeedConfirm}
        onOpenChange={setShowSeedConfirm}
        title="إدخال موازنة مسبقة"
        description="سيتم إدخال بنود الموازنة (سنوية + ربعية + شهرية) للسنة المالية المحددة. الحسابات الموجودة مسبقاً لن تتكرر."
        confirmLabel="إدخال"
        variant="warning"
        isLoading={seedMutation.isPending}
        onConfirm={() => {
          if (fiscalYearID) seedMutation.mutate(fiscalYearID);
        }}
      />
      {ConfirmDialogElement}
    </PageLayout>
  );
}

