                    </div>
                  </Card>
                </TabsContent>
              </Tabs>
            </div>
          )}
        </div>

        {/* ═══════════════════════════════════════════
            الطباعة: تصميم رسمي باستخدام PrintLayout
           ═══════════════════════════════════════════ */}
