// ═══════════════════════════════════════
// Component
// ═══════════════════════════════════════
export function ReportsPage() {
  const [activeReport, setActiveReport] = useState<ReportType>("trial-balance");
  const [selectedYearId, setSelectedYearId] = useState<number | undefined>();

  // الفلاتر الفرعية
  const [accountLevel, setAccountLevel] = useState("all");
  const [toDate, setToDate] = useState("");
  const [fromDate, setFromDate] = useState("");
  const [quarter, setQuarter] = useState("");
  const [assetType, setAssetType] = useState("all");
  const [comparisonYear, setComparisonYear] = useState("");
  const [accountId, setAccountId] = useState<number | null>(null);
  const [periodId, setPeriodId] = useState<number | undefined>();

  // جلب البيانات
  const { data: fiscalYears } = useQuery<FiscalYearSummaryDto[]>({ queryKey: ["fiscal-years"], queryFn: () => fiscalYearsApi.getAll() });
  const { data: _accounts } = useQuery<ChartOfAccountDto[]>({ queryKey: ["accounts", "all"], queryFn: () => accountsApi.getAll() });
  const { data: postableAccounts } = useQuery<ChartOfAccountDto[]>({ queryKey: ["accounts", "postable"], queryFn: () => accountsApi.getPostable() });
  const { data: periods } = useQuery<FiscalPeriodDto[]>({ queryKey: ["periods", selectedYearId], queryFn: () => periodsApi.getAll(selectedYearId!), enabled: !!selectedYearId });
  const { data: quarters } = useQuery<QuarterDto[]>({ queryKey: ["quarters", selectedYearId], queryFn: () => quartersApi.getAll(selectedYearId!), enabled: !!selectedYearId });

  // تصفير الفلاتر عند تغيير نوع التقرير
  useEffect(() => {
    setAccountLevel("all");
    setToDate("");
    setFromDate("");
    setQuarter("");
    setAssetType("all");
    setComparisonYear("");
    setAccountId(null);
    setPeriodId(undefined);
  }, [activeReport]);

  // اختيار السنة المالية تلقائياً
  useEffect(() => {
    if (fiscalYears && fiscalYears.length > 0 && !selectedYearId) {
      const currentYear = new Date().getFullYear();
      const match = fiscalYears.find((y) => y.yearName === String(currentYear));
      setSelectedYearId(match?.fiscalYearID ?? fiscalYears[fiscalYears.length - 1].fiscalYearID);
    }
  }, [fiscalYears]);

  // اختيار الفترة تلقائياً
  useEffect(() => {
    if (periods && periods.length > 0 && !periodId) {
      const active = periods.find(p => !p.isClosed);
      setPeriodId(active?.periodID ?? periods[periods.length - 1].periodID);
    }
  }, [periods]);

  // اختيار الفصل تلقائياً
  useEffect(() => {
    if (quarters && quarters.length > 0 && !quarters.some(q => String(q.quarterID) === quarter)) {
      const openQ = quarters.find(q => !q.isClosed);
      setQuarter(String(openQ?.quarterID ?? quarters[quarters.length - 1].quarterID));
    }
  }, [quarters, quarter]);

  const selectedYear = fiscalYears?.find((y) => y.fiscalYearID === selectedYearId);
  const activeReportConfig = REPORT_CONFIGS.find(r => r.type === activeReport);

  // تصدير
  const [isExporting, setIsExporting] = useState(false);
  const [exportFormat, setExportFormat] = useState<"excel" | "pdf">("excel");

  const handleExport = useCallback(async (format: "excel" | "pdf") => {
    if (!activeReportConfig) return;
    setIsExporting(true);
    setExportFormat(format);
    try {
      if (!selectedYearId) { toast.error("اختر السنة المالية أولاً"); return; }
      if (activeReportConfig.filters.includes("accountId") && !accountId) { toast.error("اختر الحساب أولاً"); return; }
      const params = {
        fiscalYearId: selectedYearId,
        fromDate: fromDate || selectedYear?.startDate || "",
        toDate: toDate || selectedYear?.endDate || "",
        accountId: accountId ?? 0,
        periodId: activeReportConfig.filters.includes("periodId") ? periodId : undefined,
        quarterId: activeReportConfig.filters.includes("quarter") && quarter ? Number(quarter) : undefined,
        accountLevel: accountLevel === "all" ? undefined : Number(accountLevel), format,
      };
      switch (activeReport) {
        case "trial-balance": await reportsApi.exportTrialBalance(params); break;
        case "balance-sheet": await reportsApi.exportBalanceSheet({ asOfDate: params.toDate, format }); break;
        case "income-statement": await reportsApi.exportIncomeStatement(params); break;
        case "general-ledger": await reportsApi.exportGeneralLedger(params); break;
        case "account-statement": await reportsApi.exportAccountStatement(params); break;
        case "subledger": await reportsApi.exportSubledger(params); break;
        case "journal-register": await reportsApi.exportJournalRegister(params); break;
        case "cash-flow": await reportsApi.exportCashFlow(params); break;
        case "quarterly":
          if (!params.quarterId) { toast.error("اختر الفصل المالي أولاً"); return; }
          await reportsApi.exportQuarterly({ ...params, quarterId: params.quarterId }); break;
        case "budget": await reportsApi.exportBudget(params); break;
        default: toast.error("هذا التقرير لا يدعم التصدير حالياً"); return;
      }
      toast.success("تم التصدير بنجاح");
    } catch {
      toast.error("حدث خطأ أثناء التصدير");
    } finally {
      setIsExporting(false);
    }
  }, [activeReportConfig, activeReport, selectedYearId, selectedYear, fromDate, toDate, accountId, periodId, quarter, accountLevel]);

  // طباعة
  const handlePrint = useCallback(() => {
    if (!activeReportConfig) return;
    const params = new URLSearchParams();
    if (selectedYearId) params.set("fiscalYearId", String(selectedYearId));
    if (selectedYear?.endDate) params.set("date", selectedYear.endDate);
    if (selectedYear?.startDate) params.set("fromDate", fromDate || selectedYear.startDate);
    if (toDate || selectedYear?.endDate) params.set("toDate", (toDate || selectedYear?.endDate)!);
    if (accountId) params.set("accountId", String(accountId));
    if (periodId) params.set("periodId", String(periodId));
    if (quarter) params.set("quarterId", quarter);
    window.open(`${activeReportConfig.printPath}?${params.toString()}`, "_blank");
  }, [activeReportConfig, selectedYearId, selectedYear, fromDate, toDate, accountId, periodId, quarter]);

  const filters = activeReportConfig?.filters || [];

  return (
    <PageLayout>
      {/* ═══ العنوان ═══ */}
      <StickyHeader>
        <div className="flex items-center gap-4">
          <div className="p-3 bg-primary/10 rounded-2xl">
            <FileText className="w-7 h-7 md:w-9 md:h-9 text-primary" />
          </div>
          <div>
            <Heading level="h1" className="text-xl md:text-3xl font-bold tracking-tight">التقارير المالية</Heading>
            <Text variant="caption" className="md:text-sm mt-1">التقارير المحاسبية الموحدة للصندوق</Text>
          </div>
        </div>
      </StickyHeader>

      {/* ═══ شريط الفلاتر الموحد ═══ */}
      <Card className="p-4 mb-6">
        <div className="flex flex-col xl:flex-row items-end gap-3">
          {/* نوع التقرير */}
          <div className="w-full xl:w-64 space-y-1">
            <Text variant="caption" className="font-bold uppercase tracking-wider">نوع التقرير</Text>
            <Select value={activeReport} onValueChange={(v) => setActiveReport(v as ReportType)}>
              <SelectTrigger className="h-10 text-sm">
                <SelectValue />
              </SelectTrigger>
              <SelectContent className="max-h-[400px]">
                {Object.entries(REPORT_GROUPS).map(([group, reports]) => (
                  <div key={group}>
                    <div className="px-2 py-1.5 text-xs font-bold text-muted-foreground bg-muted/50 sticky top-0">{group}</div>
                    {reports.map((r) => (
                      <SelectItem key={r.type} value={r.type}>
                        <span>{r.label}</span>
                      </SelectItem>
                    ))}
                  </div>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* السنة المالية */}
          <div className="w-full xl:w-40 space-y-1">
            <Text variant="caption" className="font-bold uppercase tracking-wider">السنة المالية</Text>
            <Select value={selectedYearId != null ? String(selectedYearId) : undefined} onValueChange={(v) => setSelectedYearId(Number(v))}>
              <SelectTrigger className="h-10 text-sm"><SelectValue placeholder="السنة" /></SelectTrigger>
              <SelectContent>
                {fiscalYears?.map((y) => (
                  <SelectItem key={y.fiscalYearID} value={String(y.fiscalYearID)}>{y.yearName} {y.isClosed ? "(مغلقة)" : ""}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* ═══ الفلاتر الفرعية حسب نوع التقرير ═══ */}

          {/* مستوى الحساب - ميزان المراجعة */}
          {filters.includes("accountLevel") && (
            <div className="w-full xl:w-48 space-y-1">
              <Text variant="caption" className="font-bold uppercase tracking-wider">المستوى</Text>
              <Select value={accountLevel} onValueChange={setAccountLevel}>
                <SelectTrigger className="h-10 text-sm"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {ACCOUNT_LEVEL_OPTIONS.map(o => <SelectItem key={o.value} value={o.value}>{o.label}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
          )}

          {/* حتى تاريخ - الميزانية/الديون/المخصصات */}
          {filters.includes("toDate") && !filters.includes("fromDate") && (
            <div className="w-full xl:w-40 space-y-1">
              <Text variant="caption" className="font-bold uppercase tracking-wider">حتى تاريخ</Text>
              <DateInput className="h-10" value={toDate || selectedYear?.endDate || ""} onChange={(v) => setToDate(v || "")} />
            </div>
          )}

          {/* من تاريخ / إلى تاريخ - الأستاذ/الكشف/اليومية */}
          {filters.includes("fromDate") && (
            <>
              <div className="w-full xl:w-36 space-y-1">
                <Text variant="caption" className="font-bold uppercase tracking-wider">من تاريخ</Text>
                <DateInput className="h-10" value={fromDate || selectedYear?.startDate || ""} onChange={(v) => setFromDate(v || "")} />
              </div>
              <div className="w-full xl:w-36 space-y-1">
                <Text variant="caption" className="font-bold uppercase tracking-wider">إلى تاريخ</Text>
                <DateInput className="h-10" value={toDate || selectedYear?.endDate || ""} onChange={(v) => setToDate(v || "")} />
              </div>
            </>
          )}

          {/* الفصل - التقرير الفصلي */}
          {filters.includes("quarter") && (
            <div className="w-full xl:w-40 space-y-1">
              <Text variant="caption" className="font-bold uppercase tracking-wider">الفصل</Text>
              <Select value={quarter} onValueChange={setQuarter}>
                <SelectTrigger className="h-10 text-sm"><SelectValue placeholder="اختر الفصل" /></SelectTrigger>
                <SelectContent>
                  {quarters?.map(q => <SelectItem key={q.quarterID} value={String(q.quarterID)}>{q.quarterName} {q.isClosed ? "(مغلق)" : ""}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
          )}

          {/* الحساب - دفتر الأستاذ/كشف حساب */}
          {filters.includes("accountId") && (
            <div className="w-full xl:w-64 space-y-1">
              <Text variant="caption" className="font-bold uppercase tracking-wider">الحساب</Text>
              <Select value={accountId != null ? String(accountId) : ""} onValueChange={(v) => setAccountId(Number(v))}>
                <SelectTrigger className="h-10 text-sm"><SelectValue placeholder="اختر الحساب" /></SelectTrigger>
                <SelectContent className="max-h-[250px]">
                  {postableAccounts?.map((a: any) => (
                    <SelectItem key={a.accountID} value={String(a.accountID)}>{a.accountCode} - {a.accountName}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          {/* نوع الأصل - الأصول الثابتة/الإهلاك */}
          {filters.includes("assetType") && (
            <div className="w-full xl:w-44 space-y-1">
              <Text variant="caption" className="font-bold uppercase tracking-wider">نوع الأصل</Text>
              <Select value={assetType} onValueChange={setAssetType}>
                <SelectTrigger className="h-10 text-sm"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {ASSET_TYPE_OPTIONS.map(o => <SelectItem key={o.value} value={o.value}>{o.label}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
          )}

          {/* السنة للمقارنة */}
          {filters.includes("comparisonYear") && (
            <div className="w-full xl:w-40 space-y-1">
              <Text variant="caption" className="font-bold uppercase tracking-wider">السنة السابقة</Text>
              <Select value={comparisonYear} onValueChange={setComparisonYear}>
                <SelectTrigger className="h-10 text-sm"><SelectValue placeholder="اختر السنة" /></SelectTrigger>
                <SelectContent>
                  {fiscalYears?.map(y => <SelectItem key={y.fiscalYearID} value={String(y.fiscalYearID)}>{y.yearName}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
          )}

          {/* الفترة المحاسبية */}
          {filters.includes("periodId") && (
            <div className="w-full xl:w-52 space-y-1">
              <Text variant="caption" className="font-bold uppercase tracking-wider">الفترة المحاسبية</Text>
              <Select value={periodId != null ? String(periodId) : ""} onValueChange={(v) => setPeriodId(Number(v))}>
                <SelectTrigger className="h-10 text-sm"><SelectValue placeholder="اختر الفترة" /></SelectTrigger>
                <SelectContent>
                  {periods?.map(p => <SelectItem key={p.periodID} value={String(p.periodID)}>{p.periodName} {p.isClosed ? "(مغلقة)" : ""}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
          )}

          {/* أزرار */}
          <div className="flex items-center gap-2 w-full xl:w-auto">
            <Button variant="outline" size="sm" onClick={handlePrint} className="gap-2 h-10">
              <Printer className="w-4 h-4" /> طباعة
            </Button>
            <Button variant={exportFormat === "excel" ? "success" : "outline"} size="sm" onClick={() => handleExport("excel")} disabled={isExporting} className="gap-2 h-10">
              {isExporting && exportFormat === "excel" ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Download className="w-4 h-4" />}
              Excel
            </Button>
            <Button variant={exportFormat === "pdf" ? "success" : "outline"} size="sm" onClick={() => handleExport("pdf")} disabled={isExporting} className="gap-2 h-10">
              {isExporting && exportFormat === "pdf" ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Download className="w-4 h-4" />}
              PDF
            </Button>
          </div>
        </div>
      </Card>

      {/* ═══ محتوى التقرير ═══ */}
      <Card className="border-none rounded-3xl p-6 shadow-sm">
        {activeReport === "trial-balance" && (
          <TrialBalanceReport fiscalYearId={selectedYearId} fromDate={selectedYear?.startDate} toDate={selectedYear?.endDate} externalFilters={{ accountLevel }} hideInternalControls />
        )}
        {activeReport === "balance-sheet" && (
          <BalanceSheetReport fiscalYearId={selectedYearId} asOfDate={toDate || selectedYear?.endDate} externalFilters={{ toDate }} hideInternalControls />
        )}
        {activeReport === "income-statement" && (
          <IncomeStatementReport fiscalYearId={selectedYearId} hideInternalControls />
        )}
        {activeReport === "quarterly" && (
          <QuarterlyReport fiscalYearId={selectedYearId} externalFilters={{ quarterId: Number(quarter) }} hideInternalControls />
        )}
        {activeReport === "general-ledger" && (
          <GeneralLedgerReport fiscalYearId={selectedYearId} fromDate={fromDate || selectedYear?.startDate} toDate={toDate || selectedYear?.endDate} externalFilters={{ accountId: accountId ?? undefined }} hideInternalControls />
        )}
        {activeReport === "account-statement" && (
          <AccountStatementReport fiscalYearId={selectedYearId} fromDate={fromDate || selectedYear?.startDate} toDate={toDate || selectedYear?.endDate} externalFilters={{ accountId: accountId ?? undefined }} hideInternalControls />
        )}
        {activeReport === "subledger" && (
          <SubledgerReport fiscalYearId={selectedYearId} fromDate={fromDate || selectedYear?.startDate} toDate={toDate || selectedYear?.endDate} externalFilters={{ accountId: accountId ?? undefined }} hideInternalControls />
        )}
        {activeReport === "journal-register" && (
          <JournalRegisterReport fiscalYearId={selectedYearId} fromDate={fromDate || selectedYear?.startDate} toDate={toDate || selectedYear?.endDate} hideInternalControls />
        )}
        {activeReport === "cash-flow" && (
          <CashFlowReport fiscalYearId={selectedYearId} hideInternalControls />
        )}
        {activeReport === "budget" && (
          <BudgetReportView fiscalYearId={selectedYearId} hideInternalControls />
        )}
        {activeReport === "current-operations" && (
          <CurrentOperationsReport fiscalYearId={selectedYearId} externalFilters={{ periodId }} hideInternalControls />
        )}
        {activeReport === "liabilities" && (
          <LiabilitiesReport fiscalYearId={selectedYearId} asOfDate={toDate || selectedYear?.endDate} externalFilters={{ toDate }} hideInternalControls />
        )}
        {activeReport === "year-over-year" && (
          <YearOverYearReport fiscalYearId={selectedYearId} externalFilters={{ comparisonYear: Number(comparisonYear) }} hideInternalControls />
        )}
        {activeReport === "fixed-assets" && (
          <FixedAssetsReport fiscalYearId={selectedYearId} asOfDate={selectedYear?.endDate} externalFilters={{ assetType }} hideInternalControls />
        )}
        {activeReport === "cumulative-pnl" && (
          <CumulativePnLReport fiscalYearId={selectedYearId} hideInternalControls />
        )}
        {activeReport === "cost-centers" && (
          <CostCenterReport fiscalYearId={selectedYearId} hideInternalControls />
        )}
        {activeReport === "provisions" && (
          <ProvisionsReport fiscalYearId={selectedYearId} asOfDate={toDate || selectedYear?.endDate} externalFilters={{ toDate }} hideInternalControls />
        )}
        {activeReport === "depreciation" && (
          <DepreciationReport fiscalYearId={selectedYearId} externalFilters={{ assetType }} hideInternalControls />
        )}
      </Card>
    </PageLayout>
  );
}

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Ban, Calendar,CreditCard, Eye, Pencil, PlusCircle, Printer, Receipt, Send, Trash2, Upload } from "lucide-react";
import { useState } from "react";
import { toast } from "sonner";

import { type VoucherDto, type VoucherFilter,vouchersApi } from "@/api/vouchers";
import { VoucherFormDialog } from "@/components/domain/accounting/VoucherFormDialog";
import { VoucherImportDialog } from "@/components/domain/accounting/VoucherImportDialog";
import { VoucherPrintDialog } from "@/components/domain/accounting/VoucherPrintDialog";
import { VoucherSetAccountDialog } from "@/components/domain/accounting/VoucherSetAccountDialog";
import { VoucherViewDialog } from "@/components/domain/accounting/VoucherViewDialog";
import { Badge, Button, Card, type CustomColumnDef, DataTable, DateInput, Heading, Input, PageLayout, Select, SelectContent, SelectItem, SelectTrigger, SelectValue, Skeleton, StatusBadge,StickyHeader } from "@/components/ui";
import { VOUCHER_STATUS } from "@/constants/statusConfigs";
import { formatCurrency, formatDate } from "@/lib/utils";
import { useHasPermission } from "@/stores/authStore";

const ALL = "__all__";



export function VoucherListPage() {
  const canManage = useHasPermission("Accounting.Manage", "System.Admin");
  const queryClient = useQueryClient();

  const [showCreate, setShowCreate] = useState(false);
  const [showImport, setShowImport] = useState(false);
  const [viewId, setViewId] = useState<number | null>(null);
  const [printId, setPrintId] = useState<number | null>(null);
  const [setAccountId, setSetAccountId] = useState<number | null>(null);
  const [filters, setFilters] = useState<VoucherFilter>({
    pageNumber: 1,
    pageSize: 50,
  });

  const { data, isLoading } = useQuery({
    queryKey: ["vouchers", filters],
    queryFn: () => vouchersApi.list(filters),
  });

  const deleteMutation = useMutation({
    mutationFn: (id: number) => vouchersApi.delete(id),
    onSuccess: (res) => {
      toast.success(res.message || "تم الحذف");
      queryClient.invalidateQueries({ queryKey: ["vouchers"] });
    },
    onError: (err: any) => toast.error(err?.response?.data?.message || "خطأ"),
  });

  const postMutation = useMutation({
    mutationFn: (id: number) => vouchersApi.post(id),
    onSuccess: (res) => {
      toast.success(res.message || "تم الترحيل");
      queryClient.invalidateQueries({ queryKey: ["vouchers"] });
    },
    onError: (err: any) => toast.error(err?.response?.data?.message || "خطأ"),
  });

  const cancelMutation = useMutation({
    mutationFn: (id: number) => vouchersApi.cancel(id),
    onSuccess: (res) => {
      toast.success(res.message || "تم الإلغاء");
      queryClient.invalidateQueries({ queryKey: ["vouchers"] });
    },
    onError: (err: any) => toast.error(err?.response?.data?.message || "خطأ"),
  });

  const vouchers = data?.items || [];

  return (
    <PageLayout>
      <StickyHeader>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-3 bg-primary/10 rounded-2xl">
              <Receipt className="w-8 h-8 text-primary" />
            </div>
            <div>
              <Heading level="h1" className="text-xl md:text-3xl font-bold tracking-tight">سندات الصرف والقبض</Heading>
              <p className="text-muted-foreground mt-1">إدارة سندات الصرف والقبض المحاسبية</p>
            </div>
          </div>
          {canManage && (
            <div className="flex gap-2">
              <Button onClick={() => setShowCreate(true)}>
                <PlusCircle className="w-4 h-4 me-2" /> سند جديد
              </Button>
              <Button variant="outline" onClick={() => setShowImport(true)}>
                <Upload className="w-4 h-4 me-2" /> استيراد
              </Button>
            </div>
          )}
        </div>
      </StickyHeader>

      {/* Filters */}
      <div className="flex flex-wrap items-center gap-3 mb-4">
        <Select value={filters.voucherType != null ? String(filters.voucherType) : ALL} onValueChange={(v) => setFilters((f) => ({ ...f, voucherType: v === ALL ? undefined : Number(v) as any, pageNumber: 1 }))}>
          <SelectTrigger className="w-40"><SelectValue placeholder="النوع" /></SelectTrigger>
          <SelectContent>
            <SelectItem value={ALL}>الكل</SelectItem>
            <SelectItem value="1">سند صرف</SelectItem>
            <SelectItem value="2">سند قبض</SelectItem>
          </SelectContent>
        </Select>
        <Select value={filters.status != null ? String(filters.status) : ALL} onValueChange={(v) => setFilters((f) => ({ ...f, status: v === ALL ? undefined : Number(v) as any, pageNumber: 1 }))}>
          <SelectTrigger className="w-36"><SelectValue placeholder="الحالة" /></SelectTrigger>
          <SelectContent>
            <SelectItem value={ALL}>الكل</SelectItem>
            <SelectItem value="1">مسودة</SelectItem>
            <SelectItem value="2">مرحّل</SelectItem>
            <SelectItem value="3">ملغي</SelectItem>
          </SelectContent>
        </Select>

        {/* فلتر التاريخ */}
        <div className="flex items-center gap-2">
          <Calendar className="w-4 h-4 text-muted-foreground" />
          <DateInput
            value={filters.fromDate || ""}
            onChange={(v) => setFilters((f) => ({ ...f, fromDate: v || undefined, pageNumber: 1 }))}
            placeholder="من"
            className="w-40"
          />
          <span className="text-xs text-muted-foreground">إلى</span>
          <DateInput
            value={filters.toDate || ""}
            onChange={(v) => setFilters((f) => ({ ...f, toDate: v || undefined, pageNumber: 1 }))}
            placeholder="إلى"
            className="w-40"
          />
        </div>

        <Input
          className="w-56"
          placeholder="بحث بالرقم أو البيان..."
          value={filters.search || ""}
          onChange={(e) => setFilters((f) => ({ ...f, search: e.target.value || undefined, pageNumber: 1 }))}
        />
      </div>

      {/* Table */}
      <Card className="overflow-hidden">
        {isLoading ? (
          <div className="p-6 space-y-3">{Array.from({ length: 5 }).map((_, i) => <Skeleton key={i} className="h-12" />)}</div>
        ) : vouchers.length === 0 ? (
          <div className="p-8 text-center text-muted-foreground">لا توجد سندات</div>
        ) : (
          <DataTable
            columns={[
              { key: "voucherNumber", header: "رقم السند", render: (row) => <span className="font-mono text-xs font-bold" dir="ltr">{row.voucherNumber}</span> },
              { key: "voucherDate", header: "التاريخ", render: (row) => <span className="text-xs">{formatDate(row.voucherDate)}</span> },
              { key: "voucherType", header: "النوع", render: (row) => <Badge variant={row.voucherType === 1 ? "destructive" : "success"} className="gap-1">{row.voucherType === 1 ? <CreditCard className="w-3 h-3" /> : <Receipt className="w-3 h-3" />}{row.voucherTypeName}</Badge> },
              { key: "payee", header: "المستفيد / الدافع", render: (row) => <span className="text-xs">{row.voucherType === 1 ? row.payeeName : row.payerName}</span> },
              { key: "amount", header: "المبلغ", render: (row) => <span className="font-mono text-xs font-bold">{formatCurrency(row.amount)}</span> },
              { key: "description", header: "البيان", render: (row) => <span className="text-xs max-w-[200px] truncate block">{row.description}</span> },
              { key: "journalEntryNumber", header: "القيد", render: (row) => <span className="font-mono text-xs" dir="ltr">{row.journalEntryNumber || "—"}</span> },
              { key: "status", header: "الحالة", render: (row) => <StatusBadge status={row.statusName} config={VOUCHER_STATUS} /> },
              { key: "actions", header: "الإجراءات", render: (row) => (
                <div className="flex items-center gap-1">
                  <Button variant="ghost" size="icon" onClick={() => setViewId(row.voucherID)}><Eye className="w-4 h-4" /></Button>
                  <Button variant="ghost" size="icon" className="text-blue-600" onClick={() => setPrintId(row.voucherID)} title="طباعة"><Printer className="w-4 h-4" /></Button>
                  {canManage && row.status === 1 && (
                    <>
                      {(!row.debitAccountID || row.debitAccountID === 0) && (
                        <Button variant="ghost" size="icon" className="text-orange-600" onClick={() => setSetAccountId(row.voucherID)} title="تحديد حساب المصروف"><Pencil className="w-4 h-4" /></Button>
                      )}
                      <Button variant="ghost" size="icon" className="text-green-600" onClick={() => postMutation.mutate(row.voucherID)}><Send className="w-4 h-4" /></Button>
                      <Button variant="ghost" size="icon" className="text-destructive" onClick={() => deleteMutation.mutate(row.voucherID)}><Trash2 className="w-4 h-4" /></Button>
                    </>
                  )}
                  {canManage && row.status === 2 && (
                    <Button variant="ghost" size="icon" className="text-orange-600" onClick={() => cancelMutation.mutate(row.voucherID)}><Ban className="w-4 h-4" /></Button>
                  )}
                </div>
              )},
            ] as CustomColumnDef<VoucherDto>[]}
            data={vouchers}
            rowKey={(row) => row.voucherID}
          />
        )}
      </Card>

      <VoucherFormDialog open={showCreate} onOpenChange={setShowCreate} />
      <VoucherImportDialog open={showImport} onOpenChange={setShowImport} onImported={() => queryClient.invalidateQueries({ queryKey: ["vouchers"] })} />
      {setAccountId && (
        <VoucherSetAccountDialog
          open={!!setAccountId}
          onOpenChange={(o) => { if (!o) setSetAccountId(null); }}
          voucherId={setAccountId}
          currentAccountId={vouchers.find((v) => v.voucherID === setAccountId)?.debitAccountID}
        />
      )}
      {viewId && <VoucherViewDialog open={!!viewId} onOpenChange={(o) => { if (!o) setViewId(null); }} voucherId={viewId} />}
      {printId && <VoucherPrintDialog open={!!printId} onOpenChange={(o) => { if (!o) setPrintId(null); }} voucherId={printId} />}
    </PageLayout>
  );
}

import { zodResolver } from "@hookform/resolvers/zod";
import { useQuery } from "@tanstack/react-query";
import { Target } from "lucide-react";
import { useForm } from "react-hook-form";
import { z } from "zod";

import { hrApi } from "@/api/hr";
import {
    BaseFormDialog,
    FormField,
    FormSection,
    Input,
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
    Textarea,
} from "@/components/ui";
import type { AchievementObstacleDto, AchievementObstacleType, TrackingStatus } from "@/types/achievementObstacle";

// ─── Validation Schema ─────────────────────────────────

const schema = z.object({
    type: z.enum(["Achievement", "Obstacle"]),
    title: z.string().trim().min(3, "العنوان يجب أن يكون 3 أحرف على الأقل"),
    description: z.string().optional(),
    status: z.enum(["New", "InProgress", "Completed", "Closed"]),
    departmentID: z.number().optional(),
    employeeID: z.number().optional(),
});

export type AchievementObstacleFormValues = z.infer<typeof schema>;

// ─── Props ─────────────────────────────────────────────

interface AchievementObstacleDialogProps {
    isOpen?: boolean;
    onOpenChange?: (open: boolean) => void;
    onSubmit: (values: AchievementObstacleFormValues) => void;
    isLoading?: boolean;
    initialData?: Partial<AchievementObstacleDto>;
}

// ─── Lookup Data ───────────────────────────────────────

const typeOptions: { value: AchievementObstacleType; label: string }[] = [
    { value: "Achievement", label: "إنجاز" },
    { value: "Obstacle", label: "معوق" },
];

const statusOptions: { value: TrackingStatus; label: string }[] = [
    { value: "New", label: "جديد" },
    { value: "InProgress", label: "قيد التنفيذ" },
    { value: "Completed", label: "مكتمل" },
    { value: "Closed", label: "مغلق" },
];

export function AchievementObstacleDialog({
    isOpen,
    onOpenChange,
    onSubmit,
    isLoading,
    initialData,
}: AchievementObstacleDialogProps) {
    const isEdit = !!initialData?.id;

    // ─── Data Loading ─────────────────────────────────

    const { data: departments } = useQuery({
        queryKey: ["departments-select"],
        queryFn: () => hrApi.getDepartments(),
        staleTime: 5 * 60_000,
    });

    const { data: employeesData } = useQuery({
        queryKey: ["employees-select"],
        queryFn: () => hrApi.getEmployees({ pageSize: 100 }),
        staleTime: 5 * 60_000,
    });

    const employees = employeesData?.items || [];

    // ─── Form ─────────────────────────────────────────

    const form = useForm<AchievementObstacleFormValues>({
        resolver: zodResolver(schema),
        defaultValues: {
            type: initialData?.type || "Achievement",
            title: initialData?.title || "",
            description: initialData?.description || "",
            status: initialData?.status || "New",
            departmentID: initialData?.departmentID,
            employeeID: initialData?.employeeID,
        },
    });

    const { register, formState: { errors, isDirty }, watch, setValue } = form;

    return (
        <BaseFormDialog<AchievementObstacleFormValues>
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            title={isEdit ? "تعديل سجل الإنجاز/المعوق" : "إنشاء سجل إنجاز/معوق"}
            description={isEdit ? "تعديل بيانات السجل" : "أدخل بيانات السجل الجديد"}
            size="lg"
            isLoading={isLoading}
            isDirty={isDirty}
            onSubmit={form.handleSubmit(onSubmit)}
            resetOnOpen={true}
            reset={form.reset}
            initialValues={initialData || undefined}
            showGlobalError
            formErrors={errors}
            submitLabel={isEdit ? "حفظ التعديلات" : "إنشاء السجل"}
        >
            <div className="space-y-4">
                <FormSection title="بيانات السجل" icon={Target}>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <FormField label="النوع" required error={errors.type?.message}>
                            <Select value={watch("type")} onValueChange={(v) => setValue("type", v as AchievementObstacleType)}>
                                <SelectTrigger><SelectValue /></SelectTrigger>
                                <SelectContent>
                                    {typeOptions.map(o => <SelectItem key={o.value} value={o.value}>{o.label}</SelectItem>)}
                                </SelectContent>
                            </Select>
                        </FormField>

                        <FormField label="العنوان" required error={errors.title?.message}>
                            <Input {...register("title")} placeholder="عنوان السجل" />
                        </FormField>

                        <FormField label="الحالة" required error={errors.status?.message}>
                            <Select value={watch("status")} onValueChange={(v) => setValue("status", v as TrackingStatus)}>
                                <SelectTrigger><SelectValue /></SelectTrigger>
                                <SelectContent>
                                    {statusOptions.map(o => <SelectItem key={o.value} value={o.value}>{o.label}</SelectItem>)}
                                </SelectContent>
                            </Select>
                        </FormField>

                        <FormField label="القسم" error={errors.departmentID?.message}>
                            <Select
                                value={watch("departmentID")?.toString() || ""}
                                onValueChange={(v) => setValue("departmentID", v ? Number(v) : undefined)}
                            >
                                <SelectTrigger><SelectValue placeholder="اختر القسم" /></SelectTrigger>
                                <SelectContent>
                                    {departments?.map(d => <SelectItem key={d.departmentID} value={d.departmentID.toString()}>{d.name}</SelectItem>)}
                                </SelectContent>
                            </Select>
                        </FormField>

                        <FormField label="الموظف المسؤول" error={errors.employeeID?.message}>
                            <Select
                                value={watch("employeeID")?.toString() || ""}
                                onValueChange={(v) => setValue("employeeID", v ? Number(v) : undefined)}
                            >
                                <SelectTrigger><SelectValue placeholder="اختر الموظف" /></SelectTrigger>
                                <SelectContent>
                                    {employees.map(e => <SelectItem key={e.employeeID} value={e.employeeID.toString()}>{e.fullName}</SelectItem>)}
                                </SelectContent>
                            </Select>
                        </FormField>
                    </div>

                    <FormField label="الوصف" error={errors.description?.message}>
                        <Textarea {...register("description")} placeholder="وصف تفصيلي..." rows={3} />
                    </FormField>
                </FormSection>
            </div>
        </BaseFormDialog>
    );
}

import { useQuery, useQueryClient } from "@tanstack/react-query";
import { CheckCircle, LogIn, MapPin, Monitor,RefreshCw, Search, ShieldAlert, XCircle } from "lucide-react";
import { useState } from "react";

import api from "@/api/axios";
import { Badge, Button, Card, type CustomColumnDef, DataTable, DateInput, Heading, Input, Loader, PageLayout, Select, SelectContent, SelectItem, SelectTrigger, SelectValue, StatCard, StickyHeader, Text } from "@/components/ui";

interface LoginEntry {
    loginID: number;
    userID: number | null;
    userName: string | null;
    attemptedUsername: string;
    loginTime: string;
    ipAddress: string | null;
    userAgent: string | null;
    isSuccessful: boolean;
    failureReason: string | null;
    deviceID: string | null;
}

interface LoginStats {
    totalAttempts: number;
    failedToday: number;
    uniqueIpsToday: number;
    lockedAccounts: number;
}

export function LoginHistoryPage() {
    const queryClient = useQueryClient();
    const [page, setPage] = useState(1);

    const [filterSearch, setFilterSearch] = useState("");
    const [filterSuccess, setFilterSuccess] = useState<string>("");
    const [filterFrom, setFilterFrom] = useState("");
    const [filterTo, setFilterTo] = useState("");

    const { data, isLoading: loading, isError } = useQuery({
        queryKey: ["login-history", page, filterSearch, filterSuccess, filterFrom, filterTo],
        queryFn: async () => {
            const params = new URLSearchParams();
            params.set("page", String(page));
            params.set("pageSize", "30");
            if (filterSearch) params.set("search", filterSearch);
            if (filterSuccess === "true") params.set("isSuccessful", "true");
            if (filterSuccess === "false") params.set("isSuccessful", "false");
            if (filterFrom) params.set("from", filterFrom);
            if (filterTo) params.set("to", filterTo);

            const res = await api.get<{ data: { items: LoginEntry[]; totalCount: number; totalPages: number; stats: LoginStats } }>(`/admin/login-history?${params}`);
            return res.data.data;
        }
    });

    const entries = data?.items || [];
    const stats = data?.stats || null;
    const totalPages = data?.totalPages || 1;
    void totalPages;

    const handleRefresh = () => {
        queryClient.invalidateQueries({ queryKey: ["login-history"] });
    };

    return (
        <PageLayout>
            {/* Header */}
            <StickyHeader>
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <div className="p-2.5 rounded-xl bg-gradient-to-br from-blue-500/20 to-cyan-500/20">
                            <LogIn className="w-6 h-6 text-blue-600 dark:text-blue-400" />
                        </div>
                        <div>
                            <Heading level="h1" className="text-lg md:text-xl lg:text-2xl font-bold">سجلات تسجيل الدخول</Heading>
                            <Text variant="description">مراقبة محاولات الدخول والأنشطة الأمنية</Text>
                        </div>
                    </div>
                    <Button variant="outline" size="sm" onClick={handleRefresh} loading={loading}>
                        <RefreshCw className="w-4 h-4 ms-1" /> تحديث
                    </Button>
                </div>
            </StickyHeader>

            {/* Stats Cards */}
            {stats && (
                <div className="grid grid-cols-2 sm:grid-cols-2 md:grid-cols-4 gap-2 sm:gap-4">
                    <StatCard title="إجمالي المحاولات" value={stats.totalAttempts} icon={<LogIn className="w-5 h-5" />} variant="blue" />
                    <StatCard title="محاولات فاشلة اليوم" value={stats.failedToday} icon={<XCircle className="w-5 h-5" />} variant="destructive" />
                    <StatCard title="عناوين IP اليوم" value={stats.uniqueIpsToday} icon={<MapPin className="w-5 h-5" />} variant="amber" />
                    <StatCard title="حسابات مقفلة" value={stats.lockedAccounts} icon={<ShieldAlert className="w-5 h-5" />} variant="rose" />
                </div>
            )}

            {/* Filters */}
            <Card className="p-4">
                <div className="grid grid-cols-1 md:grid-cols-4 gap-3">
                    <div className="relative">
                        <Search className="absolute end-3 top-2.5 w-4 h-4 text-muted-foreground" />
                        <Input
                            placeholder="بحث في اسم المستخدم..."
                            className="pe-9 h-9"
                            value={filterSearch}
                            onChange={(e) => { setFilterSearch(e.target.value); setPage(1); }}
                        />
                    </div>
                    <Select
                        value={filterSuccess}
                        onValueChange={(v) => { setFilterSuccess(v === "__all__" ? "" : v); setPage(1); }}
                    >
                        <SelectTrigger className="min-h-[44px]">
                            <SelectValue placeholder="جميع النتائج" />
                        </SelectTrigger>
                        <SelectContent>
                            <SelectItem value="__all__">جميع النتائج</SelectItem>
                            <SelectItem value="true">عمليات ناجحة</SelectItem>
                            <SelectItem value="false">عمليات فاشلة</SelectItem>
                        </SelectContent>
                    </Select>
                    <DateInput
                        className="h-9"
                        value={filterFrom}
                        onChange={(val) => { val !== undefined && setFilterFrom(val); setPage(1); }}
                    />
                    <DateInput
                        className="h-9"
                        value={filterTo}
                        onChange={(val) => { val !== undefined && setFilterTo(val); setPage(1); }}
                    />
                </div>
            </Card>

            {/* Content */}
            {loading ? (
                <div className="py-20 flex justify-center"><Loader variant="page" /></div>
            ) : isError ? (
                <Card className="py-20 text-center text-destructive"><p>تعذر تحميل سجل الدخول</p></Card>
            ) : entries.length === 0 ? (
                <Card className="py-20 text-center text-muted-foreground">
                    <Search className="w-12 h-12 mx-auto mb-3 opacity-100" />
                    <p>لا توجد سجلات مطابقة للبحث</p>
                </Card>
            ) : (
                <Card className="overflow-hidden ">
                    <DataTable
                        columns={[
                            { key: "userName", header: "اسم المستخدم", render: (row) => <div><div className="font-medium">{row.userName || row.attemptedUsername}</div>{row.userName && row.userName !== row.attemptedUsername && <div className="text-[10px] sm:text-xs text-muted-foreground">حاول بـ: {row.attemptedUsername}</div>}</div> },
                            { key: "loginTime", header: "وقت المحاولة", render: (row) => <span className="text-xs font-mono">{new Date(row.loginTime).toLocaleString("ar-YE")}</span> },
                            { key: "isSuccessful", header: "الحالة", render: (row) => row.isSuccessful ? <Badge variant="success" className="gap-1"><CheckCircle className="w-3 h-3" /> ناجح</Badge> : <Badge variant="destructive" className="gap-1"><XCircle className="w-3 h-3" /> فشل</Badge> },
                            { key: "ipAddress", header: "عنوان IP", render: (row) => <span className="text-xs font-mono text-muted-foreground">{row.ipAddress}</span> },
                            { key: "userAgent", header: "معلومات الجهاز", render: (row) => <div className="flex items-center gap-2 text-xs text-muted-foreground max-w-[300px] truncate" title={row.userAgent || ""}><Monitor className="w-3 h-3 flex-shrink-0" /><span className="truncate">{row.userAgent || "—"}</span></div> },
                            { key: "failureReason", header: "السبب (عند الفشل)", render: (row) => <span className="text-xs text-rose-600 font-medium">{row.failureReason || "—"}</span> },
                        ] as CustomColumnDef<LoginEntry>[]}
                        data={entries}
                        rowKey={(row) => row.loginID}
                        pagination={{ page, pageSize: 30, total: data?.totalCount || 0, onPageChange: setPage }}
                    />
                </Card>
            )}
        </PageLayout>
    );
}

import { zodResolver } from "@hookform/resolvers/zod";
import { useInfiniteQuery, useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import {
    CheckCircle,
    Clock,
    Columns,
    Download,
    Eye,
    FileSearch,
    FileText,
    RotateCcw,
    Table,
    XCircle,
} from "lucide-react";
import { useEffect, useState } from "react";
import { useForm } from "react-hook-form";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { z } from "zod";

import { archiveApi } from "@/api/archive";
import { lookupApi } from "@/api/pension";
import { SearchDialog } from "@/components/common/SearchDialog";
import { DocumentReviewPanel } from "@/components/domain/retirement/DocumentReviewPanel";
import { type DocumentItem,DocumentViewerDialog } from "@/components/domain/retirement/DocumentViewerDialog";
import {
    Badge,
    Button,
    Card,
    type CustomColumnDef,
    DataTable,
    DateInput,
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    FormField,
    Heading,
    NativeSelect,
    PageLayout,
    StatCard,
    Text,
    Textarea,
} from "@/components/ui";
import { getDocumentUrl } from "@/lib/utils";
import { cn, formatDate } from "@/lib/utils";
import type {
    DocumentReviewFilters,
    DocumentReviewItem,
    DocumentReviewStats,
} from "@/types/archive";
import {
    REVIEW_STATUS,
} from "@/types/archive";

const reviewSchema = z.object({
    reviewStatus: z.number().min(0, "حالة الفحص مطلوبة"),
    reviewNotes: z.string().min(10, "ملاحظات الفحص مطلوبة (10 أحرف على الأقل)"),
    rejectionReason: z.string().optional(),
}).refine(
    (data) => {
        if (data.reviewStatus === REVIEW_STATUS.REJECTED) {
            return data.rejectionReason && data.rejectionReason.length > 0;
        }
        return true;
    },
    {
        message: "سبب الرفض مطلوب عند رفض الوثيقة",
        path: ["rejectionReason"],
    }
);

type ReviewForm = z.infer<typeof reviewSchema>;
type ViewMode = "table" | "split";

export function DocumentReviewArchivePage() {
    const navigate = useNavigate();
    const queryClient = useQueryClient();

    // ─── State ────────────────────────────────────────────
    const [page, setPage] = useState(1);
    const pageSize = 20;
    const [search, setSearch] = useState("");
    const [debouncedSearch, setDebouncedSearch] = useState("");
    const [ownerType, setOwnerType] = useState<number | undefined>(undefined);
    const [documentTypeId, setDocumentTypeId] = useState<number | undefined>(undefined);
    const [reviewStatus, setReviewStatus] = useState<number | undefined>(undefined);
    const [dateFrom, setDateFrom] = useState<string | undefined>(undefined);
    const [dateTo, setDateTo] = useState<string | undefined>(undefined);
    const [branchId, setBranchId] = useState<number | undefined>(undefined);

    const [showReviewDialog, setShowReviewDialog] = useState(false);
    const [selectedDocument, setSelectedDocument] = useState<DocumentReviewItem | null>(null);
    const [showViewerDialog, setShowViewerDialog] = useState(false);
    const [viewingDocument, setViewingDocument] = useState<DocumentItem | null>(null);
    const [viewingFileId, setViewingFileId] = useState<number | undefined>(undefined);

    const [viewMode, setViewMode] = useState<ViewMode>("table");
    const [splitSelected, setSplitSelected] = useState<DocumentReviewItem | null>(null);

    // ─── Debounce Search ──────────────────────────────────
    useEffect(() => {
        const timer = setTimeout(() => {
            setDebouncedSearch(search);
        }, 500);
        return () => clearTimeout(timer);
    }, [search]);

    // ─── Form ─────────────────────────────────────────────
    const reviewForm = useForm<ReviewForm>({
        resolver: zodResolver(reviewSchema),
        defaultValues: {
            reviewStatus: REVIEW_STATUS.PENDING,
            reviewNotes: "",
            rejectionReason: "",
        },
    });

    // ─── Queries ──────────────────────────────────────────
    const filters: Omit<DocumentReviewFilters, "page"> = {
        ownerType,
        documentTypeId,
        reviewStatus,
        branchId,
        dateFrom,
        dateTo,
        searchTerm: debouncedSearch || undefined,
        pageSize,
    };

    const {
        data: infiniteData,
        isLoading: isLoadingInfinite,
        fetchNextPage,
        hasNextPage,
        isFetchingNextPage,
    } = useInfiniteQuery({
        queryKey: ["archive", "review-documents-infinite", filters],
        queryFn: ({ pageParam = 1 }) =>
            archiveApi.getReviewDocuments({ ...filters, page: pageParam }),
        getNextPageParam: (lastPage) =>
            lastPage.page * lastPage.pageSize < lastPage.totalCount
                ? lastPage.page + 1
                : undefined,
        initialPageParam: 1,
    });

    const allDocuments = infiniteData?.pages.flatMap((p) => p.items) ?? [];
    const totalCount = infiniteData?.pages[0]?.totalCount ?? 0;

    const { data: tableData, isLoading: isLoadingTable } = useQuery({
        queryKey: ["archive", "review-documents", { ...filters, page }],
        queryFn: () => archiveApi.getReviewDocuments({ ...filters, page }),
    });

    const tableDocuments = tableData?.items ?? [];

    const { data: stats, isLoading: statsLoading } = useQuery<DocumentReviewStats>({
        queryKey: ["archive", "review-stats"],
        queryFn: async () => {
            const result = await archiveApi.getReviewStats();
            return result as unknown as DocumentReviewStats;
        },
    });

    const { data: documentTypes = [] } = useQuery({
        queryKey: ["document-types"],
        queryFn: () => archiveApi.getDocumentTypes(),
    });

    const { data: branches = [] } = useQuery({
        queryKey: ["branches"],
        queryFn: () => lookupApi.getBranches(),
    });

    // ─── Mutations ────────────────────────────────────────
    const reviewMutation = useMutation({
        mutationFn: (data: { documentId: number; reviewStatus: number; reviewNotes: string; rejectionReason?: string }) =>
            archiveApi.reviewDocument(data.documentId, {
                reviewStatus: data.reviewStatus,
                reviewNotes: data.reviewNotes,
                rejectionReason: data.rejectionReason,
            }),
        onSuccess: () => {
            toast.success("تم حفظ نتيجة الفحص بنجاح");
            queryClient.invalidateQueries({ queryKey: ["archive", "review-documents"] });
            queryClient.invalidateQueries({ queryKey: ["archive", "review-stats"] });
            setShowReviewDialog(false);
            setSelectedDocument(null);
            reviewForm.reset();
        },
        onError: () => {
            toast.error("خطأ في حفظ نتيجة الفحص");
        },
    });

    // ─── Handlers ─────────────────────────────────────────
    const handleReview = (doc: DocumentReviewItem) => {
        setSelectedDocument(doc);
        reviewForm.setValue("reviewStatus", doc.reviewStatus || REVIEW_STATUS.PENDING);
        reviewForm.setValue("reviewNotes", doc.reviewNotes || "");
        reviewForm.setValue("rejectionReason", doc.rejectionReason || "");
        setShowReviewDialog(true);
    };

    const handleViewDocument = (doc: DocumentReviewItem) => {
        setViewingDocument({
            documentID: doc.documentId,
            documentTypeID: doc.documentTypeId,
            documentTypeName: doc.documentTypeName,
            fileName: doc.fileName,
            filePath: doc.filePath,
            notes: doc.notes,
            uploadedByUser: doc.uploadedBy,
            createdAt: doc.createdAt,
        });
        setViewingFileId(doc.retirementFileId);
        setShowViewerDialog(true);
    };

    const handleSubmitReview = (data: ReviewForm) => {
        if (!selectedDocument) return;
        reviewMutation.mutate({
            documentId: selectedDocument.documentId,
            reviewStatus: data.reviewStatus,
            reviewNotes: data.reviewNotes,
            rejectionReason: data.rejectionReason,
        });
    };

    const clearFilters = () => {
        setSearch("");
        setDebouncedSearch("");
        setOwnerType(undefined);
        setDocumentTypeId(undefined);
        setReviewStatus(undefined);
        setBranchId(undefined);
        setDateFrom(undefined);
        setDateTo(undefined);
    };

    const getReviewBadge = (status: number) => {
        switch (status) {
            case REVIEW_STATUS.APPROVED:
                return <Badge variant="success">معتمدة</Badge>;
            case REVIEW_STATUS.REJECTED:
                return <Badge variant="destructive">مرفوضة</Badge>;
            case REVIEW_STATUS.PENDING:
            default:
                return <Badge variant="warning">بانتظار الفحص</Badge>;
        }
    };

    const getFileUrl = (filePath: string) => {
        return getDocumentUrl(filePath) ?? filePath;
    };

    // ─── Columns ──────────────────────────────────────────
    const columns: CustomColumnDef<DocumentReviewItem>[] = [
        {
            key: "documentId",
            header: "الرقم",
            render: (row) => (
                <span className="font-mono font-bold text-primary">{row.documentId}</span>
            ),
        },
        {
            key: "fileName",
            header: "اسم الملف",
            render: (row) => (
                <div className="flex items-center gap-2">
                    <FileText className="w-4 h-4 text-muted-foreground" />
                    <span className="text-sm font-medium truncate max-w-[200px]">{row.fileName}</span>
                </div>
            ),
        },
        {
            key: "documentTypeName",
            header: "نوع الوثيقة",
            render: (row) => (
                <span className="text-sm">{row.documentTypeName}</span>
            ),
        },
        {
            key: "ownerType",
            header: "القسم",
            render: (row) => (
                <Badge variant="outline">{row.ownerTypeName}</Badge>
            ),
        },
        {
            key: "retireeName",
            header: "رقم الملف",
            render: (row) => (
                <span className="text-sm font-medium">
                    {row.retireeName || row.fileNumber || "—"}
                </span>
            ),
        },
        {
            key: "uploadedBy",
            header: "رفع بواسطة",
            render: (row) => (
                <span className="text-sm text-muted-foreground">{row.uploadedBy}</span>
            ),
        },
        {
            key: "createdAt",
            header: "تاريخ الرفع",
            render: (row) => (
                <span className="text-sm">{formatDate(row.createdAt)}</span>
            ),
        },
        {
            key: "notes",
            header: "ملاحظات",
            render: (row) => (
                <span className="text-sm text-muted-foreground truncate max-w-[150px] block" title={row.notes || ""}>
                    {row.notes || "—"}
                </span>
            ),
        },
        {
            key: "reviewStatus",
            header: "حالة الفحص",
            render: (row) => getReviewBadge(row.reviewStatus),
        },
        {
            key: "actions",
            header: "",
            render: (row) => (
                <div className="flex items-center gap-1">
                    <Button
                        variant="ghost"
                        size="sm"
                        title="عرض الوثيقة"
                        onClick={(e) => {
                            e.stopPropagation();
                            handleViewDocument(row);
                        }}
                    >
                        <Eye className="w-4 h-4" />
                    </Button>
                    <Button
                        variant="ghost"
                        size="sm"
                        title="تحميل"
                        onClick={(e) => {
                            e.stopPropagation();
                            const link = document.createElement("a");
                            link.href = getFileUrl(row.filePath);
                            link.download = row.fileName;
                            link.click();
                        }}
                    >
                        <Download className="w-4 h-4" />
                    </Button>
                    <Button
                        variant="ghost-action"
                        size="sm"
                        title="فحص الوثيقة"
                        onClick={(e) => {
                            e.stopPropagation();
                            handleReview(row);
                        }}
                    >
                        <FileSearch className="w-4 h-4" />
                    </Button>
                </div>
            ),
        },
    ];

    return (
        <PageLayout>
            <Heading title="فحص الوثائق" />

            {/* Stats Cards */}
            <div className="grid grid-cols-2 sm:grid-cols-2 lg:grid-cols-4 gap-2 sm:gap-4 mb-6">
                <StatCard
                    title="إجمالي الوثائق"
                    value={stats?.totalDocuments ?? 0}
                    icon={<FileText className="w-6 h-6" />}
                    variant="blue"
                    isLoading={statsLoading}
                />
                <StatCard
                    title="بانتظار الفحص"
                    value={stats?.pendingReview ?? 0}
                    icon={<Clock className="w-6 h-6" />}
                    variant="warning"
                    isLoading={statsLoading}
                />
                <StatCard
                    title="معتمدة"
                    value={stats?.approvedDocuments ?? 0}
                    icon={<CheckCircle className="w-6 h-6" />}
                    variant="success"
                    isLoading={statsLoading}
                />
                <StatCard
                    title="مرفوضة"
                    value={stats?.rejectedDocuments ?? 0}
                    icon={<XCircle className="w-6 h-6" />}
                    variant="destructive"
                    isLoading={statsLoading}
                />
            </div>

            {/* Filters */}
            <Card className="p-4 mb-6">
                <div className="flex flex-nowrap gap-3 items-end">
                    <SearchDialog
                        value={search}
                        onSelect={setSearch}
                        queryKey={["archive", "dialog-search"]}
                        fetchFn={(term) => archiveApi.getReviewDocuments({ searchTerm: term || undefined, page: 1, pageSize: 50 })}
                        getName={(doc) => doc.retireeName || doc.entityName || doc.fileName}
                        getSubtitle={(doc) => doc.fileNumber || doc.documentTypeName}
                        title="بحث في الوثائق"
                        placeholder="بحث بالاسم أو الرقم..."
                    />

                    <NativeSelect
                        className="w-36 shrink-0"
                        value={branchId ?? ""}
                        placeholder=""
                        onChange={(val) => {
                            setBranchId(val ? Number(val) : undefined);
                            
                        }}
                        options={[
                            { value: "", label: "جميع الفروع" },
                            ...branches.map((b) => ({
                                value: b.id.toString(),
                                label: b.name,
                            })),
                        ]}
                    />

                    <NativeSelect
                        className="w-36 shrink-0"
                        value={ownerType ?? ""}
                        placeholder=""
                        onChange={(val) => {
                            setOwnerType(val ? Number(val) : undefined);
                            
                        }}
                        options={[
                            { value: "", label: "جميع الأقسام" },
                            { value: "1", label: "ملفات التقاعد" },
                            { value: "2", label: "المتقاعدون" },
                            { value: "3", label: "المستحقون" },
                            { value: "4", label: "الوكلاء" },
                            { value: "5", label: "الأوصياء" },
                            { value: "15", label: "مشاريع الاستثمار" },
                            { value: "40", label: "الموظفون" },
                            { value: "41", label: "المراسلات" },
                        ]}
                    />

                    <NativeSelect
                        className="w-36 shrink-0"
                        value={documentTypeId ?? ""}
                        placeholder=""
                        onChange={(val) => {
                            setDocumentTypeId(val ? Number(val) : undefined);
                            
                        }}
                        options={[
                            { value: "", label: "جميع أنواع الوثائق" },
                            ...documentTypes.map((t) => ({
                                value: t.documentTypeId.toString(),
                                label: t.typeName,
                            })),
                        ]}
                    />

                    <NativeSelect
                        className="w-40 shrink-0"
                        value={reviewStatus ?? ""}
                        placeholder=""
                        onChange={(val) => {
                            setReviewStatus(val !== "" ? Number(val) : undefined);
                            
                        }}
                        options={[
                            { value: "", label: "جميع حالات الفحص" },
                            { value: "1", label: "بانتظار الفحص" },
                            { value: "2", label: "معتمدة" },
                            { value: "3", label: "مرفوضة" },
                        ]}
                    />

                    <DateInput
                        label="من تاريخ"
                        className="w-36 shrink-0"
                        value={dateFrom || ""}
                        onChange={(val) => {
                            setDateFrom(val || undefined);
                            
                        }}
                        placeholder="من تاريخ"
                    />

                    <DateInput
                        label="إلى تاريخ"
                        className="w-36 shrink-0"
                        value={dateTo || ""}
                        onChange={(val) => {
                            setDateTo(val || undefined);
                            
                        }}
                        placeholder="إلى تاريخ"
                    />

                    <Button variant="ghost" size="icon" className="shrink-0" onClick={clearFilters} title="إعادة تعيين">
                        <RotateCcw className="w-4 h-4" />
                    </Button>

                    {/* View Mode Toggle */}
                    <div className="flex items-center border rounded-lg overflow-hidden">
                        <Button
                            variant={viewMode === "table" ? "default" : "ghost"}
                            size="sm"
                            className="rounded-none border-0"
                            onClick={() => setViewMode("table")}
                        >
                            <Table className="w-4 h-4 ml-1" />
                            جدول
                        </Button>
                        <Button
                            variant={viewMode === "split" ? "default" : "ghost"}
                            size="sm"
                            className="rounded-none border-0"
                            onClick={() => setViewMode("split")}
                        >
                            <Columns className="w-4 h-4 ml-1" />
                            مقسم
                        </Button>
                    </div>
                </div>
            </Card>

            {/* ═══ Table View ═══ */}
            {viewMode === "table" && (
                <Card>
                    <DataTable
                        columns={columns}
                        data={tableDocuments}
                        loading={isLoadingTable}
                        emptyMessage="لا توجد وثائق"
                        rowKey={(row, index) => row.documentId ?? index}
                        pagination={{
                            page,
                            pageSize,
                            total: totalCount,
                            onPageChange: setPage,
                        }}
                    />
                </Card>
            )}

            {/* ═══ Split View ═══ */}
            {viewMode === "split" && (
                <div className="flex gap-4 h-[calc(100vh-280px)] min-h-[500px]">
                    {/* Left Panel — Document List */}
                    <Card className="w-[380px] shrink-0 flex flex-col overflow-hidden">
                        <div className="p-3 border-b bg-muted/30">
                            <Text variant="label" className="text-muted-foreground">
                                {totalCount} وثيقة
                            </Text>
                        </div>
                        <div
                            className="flex-1 min-h-0 overflow-y-auto"
                            onScroll={(e) => {
                                const { scrollHeight, scrollTop, clientHeight } = e.currentTarget;
                                if (scrollHeight - scrollTop - clientHeight < 100 && hasNextPage && !isFetchingNextPage) {
                                    fetchNextPage();
                                }
                            }}
                        >
                            {isLoadingInfinite && (
                                <div className="p-8 text-center text-sm text-muted-foreground">
                                    جاري التحميل...
                                </div>
                            )}
                            {!isLoadingInfinite && allDocuments.length === 0 && (
                                <div className="p-8 text-center text-sm text-muted-foreground">
                                    لا توجد وثائق
                                </div>
                            )}
                            {allDocuments.map((doc) => (
                                <div
                                    key={doc.documentId}
                                    className={cn(
                                        "p-3 cursor-pointer transition-colors hover:bg-muted/50 border-b",
                                        splitSelected?.documentId === doc.documentId && "bg-primary/5 border-r-2 border-primary"
                                    )}
                                    onClick={() => {
                                        setSplitSelected(doc);
                                        reviewForm.setValue("reviewStatus", doc.reviewStatus || REVIEW_STATUS.PENDING);
                                        reviewForm.setValue("reviewNotes", doc.reviewNotes || "");
                                        reviewForm.setValue("rejectionReason", doc.rejectionReason || "");
                                    }}
                                >
                                        <div className="flex items-start gap-3">
                                            <div className="shrink-0 mt-0.5">
                                                <FileText className="w-5 h-5 text-muted-foreground" />
                                            </div>
                                            <div className="flex-1 min-w-0">
                                                <Text variant="label">{doc.documentTypeName} — {doc.entityName || doc.retireeName || "—"}</Text>
                                                <Text variant="caption" className="mt-1">{doc.uploadedBy}</Text>
                                                <div className="flex items-center gap-2 mt-1.5">
                                                    {getReviewBadge(doc.reviewStatus)}
                                                    <span className="text-[10px] text-muted-foreground">
                                                        {formatDate(doc.createdAt)}
                                                    </span>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            {isFetchingNextPage && (
                                <div className="p-4 text-center text-sm text-muted-foreground">
                                    جاري تحميل المزيد...
                                </div>
                            )}
                            {hasNextPage === false && allDocuments.length > 0 && (
                                <div className="p-4 text-center text-xs text-muted-foreground">
                                    تم تحميل جميع الوثائق
                                </div>
                            )}
                        </div>
                    </Card>

                    {/* Right Panel — Document Details */}
                    <DocumentReviewPanel
                        document={splitSelected}
                        onViewDocument={handleViewDocument}
                        onRefresh={() => {
                            queryClient.invalidateQueries({ queryKey: ["archive", "review-documents"] });
                            queryClient.invalidateQueries({ queryKey: ["archive", "review-stats"] });
                        }}
                    />
                </div>
            )}

            {/* Review Dialog (for table mode) */}
            <Dialog open={showReviewDialog} onOpenChange={setShowReviewDialog}>
                <DialogContent className="max-w-lg">
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-2">
                            <FileSearch className="w-5 h-5" />
                            فحص الوثيقة
                        </DialogTitle>
                    </DialogHeader>

                    <div className="flex flex-col gap-4">
                        {/* Document Info */}
                        <div className="p-3 bg-muted/50 rounded-lg">
                            <div className="flex items-center gap-2 mb-2">
                                <FileText className="w-4 h-4 text-muted-foreground" />
                                <span className="text-sm font-medium">{selectedDocument?.fileName}</span>
                            </div>
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-sm">
                                <div>
                                    <span className="text-muted-foreground">النوع:</span>
                                    <span className="mr-2">{selectedDocument?.documentTypeName}</span>
                                </div>
                                <div>
                                    <span className="text-muted-foreground">رفع بواسطة:</span>
                                    <span className="mr-2">{selectedDocument?.uploadedBy}</span>
                                </div>
                            </div>
                        </div>

                        {/* View Document Button */}
                        {selectedDocument?.filePath && (
                            <Button
                                variant="outline"
                                className="w-full"
                                onClick={() => {
                                    setShowReviewDialog(false);
                                    handleViewDocument(selectedDocument);
                                }}
                            >
                                <Eye className="w-4 h-4 ml-2" />
                                عرض الوثيقة
                            </Button>
                        )}

                        {/* Review Form */}
                        <FormField label="حالة الفحص *" error={reviewForm.formState.errors.reviewStatus?.message}>
                            <NativeSelect
                                value={reviewForm.watch("reviewStatus").toString()}
                                onChange={(val) => reviewForm.setValue("reviewStatus", Number(val))}
                                options={[
                                    { value: "1", label: "بانتظار الفحص" },
                                    { value: "2", label: "معتمدة" },
                                    { value: "3", label: "مرفوضة" },
                                ]}
                            />
                        </FormField>

                        <FormField label="ملاحظات الفحص *" error={reviewForm.formState.errors.reviewNotes?.message}>
                            <Textarea
                                {...reviewForm.register("reviewNotes")}
                                placeholder="أدخل ملاحظات الفحص..."
                                rows={4}
                            />
                        </FormField>

                        {reviewForm.watch("reviewStatus") === REVIEW_STATUS.REJECTED && (
                            <FormField label="سبب الرفض *" error={reviewForm.formState.errors.rejectionReason?.message}>
                                <Textarea
                                    {...reviewForm.register("rejectionReason")}
                                    placeholder="أدخل سبب رفض الوثيقة..."
                                    rows={3}
                                />
                            </FormField>
                        )}

                        {/* File Link */}
                        {selectedDocument?.retirementFileId && (
                            <div className="p-3 bg-muted/50 rounded-lg">
                                <span className="text-sm text-muted-foreground">مرفق لملف: </span>
                                <Button
                                    variant="link"
                                    size="sm"
                                    className="p-0 h-auto"
                                    onClick={() => {
                                        navigate(`/files/${selectedDocument.retirementFileId}`);
                                    }}
                                >
                                    {selectedDocument.fileNumber || `ملف #${selectedDocument.retirementFileId}`}
                                </Button>
                            </div>
                        )}

                        {/* Action Buttons */}
                        <div className="flex gap-2">
                            <Button
                                variant="outline"
                                className="flex-1"
                                onClick={() => {
                                    setShowReviewDialog(false);
                                    setSelectedDocument(null);
                                    reviewForm.reset();
                                }}
                            >
                                إلغاء
                            </Button>
                            <Button
                                className="flex-1"
                                onClick={reviewForm.handleSubmit(handleSubmitReview)}
                                disabled={reviewMutation.isPending}
                            >
                                {reviewMutation.isPending ? "جاري الحفظ..." : "حفظ نتيجة الفحص"}
                            </Button>
                        </div>
                    </div>
                </DialogContent>
            </Dialog>

            {/* Document Viewer Dialog */}
            <DocumentViewerDialog
                open={showViewerDialog}
                onOpenChange={setShowViewerDialog}
                document={viewingDocument}
                fileId={viewingFileId}
                onUploaded={() => {
                    queryClient.invalidateQueries({ queryKey: ["archive", "review-documents"] });
                    queryClient.invalidateQueries({ queryKey: ["archive", "review-stats"] });
                    setShowViewerDialog(false);
                }}
                onRefresh={() => {
                    queryClient.invalidateQueries({ queryKey: ["archive", "review-documents"] });
                    queryClient.invalidateQueries({ queryKey: ["archive", "review-stats"] });
                }}
            />
        </PageLayout>
    );
}

import { useQuery } from "@tanstack/react-query";
import { Play, Printer, Search, Users } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";

import { discrepancyApi, type DiscrepancyFilter,type RetireeDiscrepancy } from "@/api/discrepancy";
import { ministryApi } from "@/api/ministry";
import {
  Badge,
  Button,
  Card,
  CrudPageLayout,
  Input,
  NativeSelect,
  Text,
  useConfirm
} from "@/components/ui";
import type { CustomColumnDef } from "@/components/ui/DataTable";
import { useApiMutation, useRoleBasedUI } from "@/hooks";

export function DiscrepancyReportPage() {
  const navigate = useNavigate();
  const { hasPermission } = useRoleBasedUI();
  const { confirm, ConfirmDialogElement } = useConfirm();
  const [filter, setFilter] = useState<DiscrepancyFilter>({
    pageNumber: 1,
    pageSize: 10,
    searchTerm: undefined,
    stage: undefined
  });
  const [focusedIndex, setFocusedIndex] = useState(-1);
  const focusedIndexRef = useRef(-1);
  const searchInputRef = useRef<HTMLInputElement>(null);

  // ── Debounce Search ────────────────────────────────
  useEffect(() => {
    const timer = setTimeout(() => {
      setFilter(prev => ({ ...prev, pageNumber: 1 }));
      setFocusedIndex(-1);
      focusedIndexRef.current = -1;
    }, 500);
    return () => clearTimeout(timer);
  }, [filter.searchTerm]);

  // Scroll to focused row
  useEffect(() => {
    if (focusedIndex >= 0) {
      const row = document.querySelector(`[data-row-index="${focusedIndex}"]`)
                || document.querySelector(`[data-index="${focusedIndex}"]`);
      if (row) {
        row.scrollIntoView({ behavior: "smooth", block: "nearest" });
      }
    }
  }, [focusedIndex]);

  const formatDate = useCallback((dateString?: string) => {
    if (!dateString) return "---";
    try {
      const d = new Date(dateString);
      if (isNaN(d.getTime())) return "---";
      const day = String(d.getDate()).padStart(2, '0');
      const month = String(d.getMonth() + 1).padStart(2, '0');
      const year = d.getFullYear();
      return `${day}/${month}/${year}`;
    } catch {
      return "---";
    }
  }, []);

  const { data, isLoading, refetch } = useQuery({
    queryKey: ["discrepancy-report", filter],
    queryFn: () => discrepancyApi.getReport(filter),
  });

  const processMutation = useApiMutation(
    (id: number) => ministryApi.processItem(id),
    {
      successMessage: "تمت معالجة القيد بنجاح",
      onSuccess: () => refetch()
    }
  );

  const handleProcess = useCallback(async (row: RetireeDiscrepancy) => {
    if (!row.approvalItemID) return;

    const ok = await confirm({
      title: "تأكيد معالجة القيد",
      description: `هل أنت متأكد من معالجة المتقاعد ${row.approvalFullName || row.militaryNumber}؟ سيتم إنشاء سجل متقاعد معتمد في النظام.`
    });

    if (ok) {
      processMutation.mutate(row.approvalItemID);
    }
  }, [confirm, processMutation]);

  const items = useMemo(() => (data?.items || []) as unknown as RetireeDiscrepancy[], [data]);

  // ── Keyboard Navigation ────────────────────────────
  const handleSearchKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setFocusedIndex(prev => {
        const next = prev + 1;
        const clamped = next < items.length ? next : prev;
        focusedIndexRef.current = clamped;
        return clamped;
      });
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setFocusedIndex(prev => {
        const clamped = prev > 0 ? prev - 1 : prev;
        focusedIndexRef.current = clamped;
        return clamped;
      });
    } else if (e.key === "Enter") {
      e.preventDefault();
      const idx = focusedIndexRef.current;
      if (idx >= 0 && idx < items.length) {
        const row = items[idx];
        if (!row.isProcessed && row.approvalItemID && hasPermission("Ministry.Manage")) {
          handleProcess(row);
        }
      }
    } else if (e.key === "Escape") {
      setFocusedIndex(-1);
      focusedIndexRef.current = -1;
    }
  }, [items, hasPermission, handleProcess]);

  const columns = useMemo<CustomColumnDef<RetireeDiscrepancy>[]>(() => [
    {
      key: "militaryNumber",
      header: "الرقم العسكري",
      accessor: (row) => row.militaryNumber,
      className: "text-center font-bold",
    },
    {
      key: "fullName",
      header: "الاسم الرباعي",
      render: (row) => row.retireeFullName || row.approvalFullName || "---",
    },
    {
      key: "rank",
      header: "الرتبة",
      render: (row) => row.fileRankName || row.approvalRankName || "---",
    },
    {
      key: "unitName",
      header: "الوحدة",
      accessor: (row) => row.approvalUnitName || "---",
      className: "text-sm",
    },
    {
      key: "retirementDate",
      header: "تاريخ التقاعد",
      render: (row) => formatDate(row.fileRetirementDate || row.approvalRetirementDate),
      className: "text-center",
    },
    {
      key: "currentStage",
      header: "المرحلة الحالية",
      className: "text-center",
      render: (row) => {
        let variant: "default" | "success" | "warning" | "secondary" = "secondary";
        if (row.fileID) variant = "success";
        else if (row.retireeID) variant = "warning";

        return (
          <Badge variant={variant}>
            {row.currentStage === "Stage 3: File Created" ? "ملف مكتمل" :
              row.currentStage === "Stage 2: Processed" ? "تمت المعالجة" : "كشف إحالة فقط"}
          </Badge>
        );
      },
    },
    {
      key: "actions",
      header: "إجراءات",
      className: "text-center",
      render: (row) => (
        <div className="flex items-center justify-center gap-2">
          {!row.isProcessed && row.approvalItemID && hasPermission("Ministry.Manage") && (
            <Button
              variant="ghost"
              size="sm"
              className="gap-1 text-emerald-700 hover:text-emerald-800 hover:bg-emerald-50"
              onClick={() => handleProcess(row)}
              loading={processMutation.isPending && processMutation.variables === row.approvalItemID}
            >
              <Play className="w-3.5 h-3.5" />
              معالجة
            </Button>
          )}
          {row.retireeID && (
            <Button
              variant="ghost"
              size="sm"
              className="gap-1 text-slate-700 hover:text-slate-800 hover:bg-slate-50"
              onClick={() => navigate(`/retirees/${row.retireeID}`)}
            >
              <Users className="w-3.5 h-3.5" />
              الملف
            </Button>
          )}
          {row.approvalItemID ? (
            <Button
              variant="ghost"
              size="sm"
              className="gap-1 text-blue-700 hover:text-blue-800 hover:bg-blue-50"
              onClick={() => window.open(`/force/items/${row.approvalItemID}/print`, '_blank')}
            >
              <Printer className="w-3.5 h-3.5" />
              طباعة
            </Button>
          ) : row.retireeID ? (
            <Button
              variant="ghost"
              size="sm"
              className="gap-1 text-blue-700 hover:text-blue-800 hover:bg-blue-50"
              onClick={() => window.open(`/retirees/${row.retireeID}/statement`, '_blank')}
            >
              <Printer className="w-3.5 h-3.5" />
              طباعة
            </Button>
          ) : null}
        </div>
      ),
    },
  ], [hasPermission, processMutation, confirm, handleProcess, formatDate]);

  return (
    <>
      <CrudPageLayout
        title="مباينة بيانات المتقاعدين"
        description="عرض بيانات المتقاعدين المستخرجة من كشوفات الإحالة"
        columns={columns}
        data={items}
        loading={isLoading}
        focusedRowIndex={focusedIndex}
        pagination={{
          page: filter.pageNumber,
          pageSize: filter.pageSize,
          total: data?.totalCount || 0,
          onPageChange: (page) => setFilter(prev => ({ ...prev, pageNumber: page })),
        }}
        headerActions={
          <Button
            variant="outline"
            onClick={() => {
              const params = new URLSearchParams();
              if (filter.searchTerm) params.set("searchTerm", filter.searchTerm);
              if (filter.stage) params.set("stage", filter.stage);
              navigate(`/admin/discrepancy-report/print?${params.toString()}`);
            }}
            className="gap-2"
          >
            <Printer className="h-4 w-4" />
            طباعة التقرير
          </Button>
        }
      >
        <Card className="p-4 mb-6">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
            <div className="space-y-2">
              <Text variant="label">البحث</Text>
              <div className="relative">
                <Search className="absolute start-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                <Input
                  ref={searchInputRef}
                  placeholder="اسم، رقم عسكري، رقم ملف..."
                  className="ps-10"
                  value={filter.searchTerm}
                  onChange={(e) => setFilter(prev => ({ ...prev, searchTerm: e.target.value }))}
                  onKeyDown={handleSearchKeyDown}
                />
              </div>

            </div>

            <div className="space-y-2">
              <Text variant="label">المرحلة</Text>
              <NativeSelect
                placeholder="كل المراحل"
                options={[
                  { label: "كشف إحالة فقط", value: "Stage 1" },
                  { label: "تمت المعالجة", value: "Stage 2" },
                  { label: "ملف مكتمل", value: "Stage 3" },
                ]}
                value={filter.stage || ""}
                onChange={(val) => setFilter(prev => ({ ...prev, stage: val || undefined, pageNumber: 1 }))}
              />
            </div>

            <Badge variant="outline" className="h-10 justify-center text-xs">
              إجمالي السجلات: {data?.totalCount || 0}
            </Badge>
          </div>
        </Card>
      </CrudPageLayout>
      {ConfirmDialogElement}
    </>
  );
}

/**
 * استكمال النواقص — صفحة مخصصة لتوثيق ورفع الوثائق الناقصة لملفات التقاعد.
 * تعرض قائمة ملفات التقاعد مع عدد النواقص ونسبة اكتمال الوثائق
 * مع إمكانية الانتقال لتفاصيل الملف لرفع وتوثيق الوثائق
 * مع إحصائيات المدخلين وحالة التوثيق
 */

import { useQuery } from "@tanstack/react-query";
import { AlertTriangle, CheckCircle2, ChevronDown, FileText, Printer, Search, Upload, User } from "lucide-react";
import { useCallback, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";

import api from "@/api/axios";
import { documentsApi } from "@/api/documents";
import { SearchDialog } from "@/components/common/SearchDialog";
import { FileStatusBadge } from "@/components/domain/retirement/FileStatusBadge";
import { RetirementFileCard } from "@/components/domain/retirement/RetirementFileCard";
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/Accordion";
import { Badge } from "@/components/ui/Badge";
import { Button } from "@/components/ui/Button";
import type { CustomColumnDef, PaginationConfig } from "@/components/ui/DataTable";
import { DataTable } from "@/components/ui/DataTable";
import { Input } from "@/components/ui/Input";
import { NativeSelect } from "@/components/ui/NativeSelect";
import { useDebouncedSearch } from "@/hooks/useDebouncedSearch";
import { retirementFileCardClassName } from "@/lib/retirementFileCard";
import { cn, getDocumentUrl } from "@/lib/utils";

function sanitizeHtml(str: string): string {
    return str
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
}

interface FileStatus {
    statusID: number;
    statusName: string;
}

interface RetirementFileItem {
    fileID: number;
    fileNumber: string;
    retireeFullName: string;
    nationalID: string | null;
    rankName: string | null;
    fileStatusName: string | null;
    missingDocumentsCount: number;
    hasDocuments: boolean;
    lastUploadedByUserID: number | null;
    lastUploadedByUserName: string | null;
    statusID: number | null;
}

interface PagedResult {
    items: RetirementFileItem[];
    totalPages: number;
}

const DOCUMENT_FILTERS = [
    { value: "all", label: "الكل" },
    { value: "noDocuments", label: "لم تُرفع" },
    { value: "missing", label: "ناقصة" },
    { value: "uploaded", label: "مرفوعة" },
] as const;

export function MissingDocsCompletionPage() {
    const navigate = useNavigate();
    const { searchTerm: search, setSearchTerm: setSearch, debouncedValue: debouncedSearch } = useDebouncedSearch("");
    const [filterMode, setFilterMode] = useState<"all" | "missing" | "uploaded" | "noDocuments">("all");
    const [statusId, setStatusId] = useState<string>("");
    const [uploadedBy, setUploadedBy] = useState<string>("");
    const [page, setPage] = useState(1);
    const [statsOpen, setStatsOpen] = useState(() => typeof window !== "undefined" ? window.innerWidth >= 768 : true);

    // ─── Fetch Statuses (React Query) ───────────────────────
    const { data: statuses = [] } = useQuery({
        queryKey: ["file-statuses"],
        queryFn: async () => {
            const res = await api.get<{ data: FileStatus[] }>("/file-statuses");
            return res.data.data || [];
        },
        staleTime: 5 * 60 * 1000,
    });

    // ─── Fetch Global Stats (React Query) ──────────────────
    const { data: stats } = useQuery({
        queryKey: ["document-upload-stats"],
        queryFn: async () => {
            const res = await api.get<{ data: { totalFiles: number; filesWithDocuments: number; filesWithoutDocuments: number; filesWithMissing: number; totalMissingDocuments: number } }>("/retirement-files/document-upload-stats");
            return res.data.data;
        },
        staleTime: 2 * 60 * 1000,
    });

    // ─── Fetch Files (React Query) ───────────────────────

    const { data: filesData, isLoading: loading } = useQuery({
        queryKey: ["retirement-files", "document-upload", page, debouncedSearch, statusId, uploadedBy],
        queryFn: async () => {
            const res = await api.get<{ data: PagedResult }>("/retirement-files", {
                params: {
                    page,
                    pageSize: 20,
                    search: debouncedSearch || undefined,
                    statusId: statusId || undefined,
                    uploadedBy: uploadedBy || undefined,
                },
            });
            return res.data.data;
        },
    });

    const files = filesData?.items || [];
    const totalPages = filesData?.totalPages || 1;

    // ─── Fetch All Uploaders (React Query) ──────────────────
    const { data: uploadersData = [] } = useQuery({
        queryKey: ["uploader-stats"],
        queryFn: async () => {
            const res = await api.get<{ data: { userID: number; fullName: string; userName: string }[] }>("/retirement-files/uploader-stats");
            return res.data.data || [];
        },
        staleTime: 5 * 60 * 1000,
    });

    const uploaders = useMemo(
        () => uploadersData.map((u) => ({ id: u.userID, name: u.fullName || u.userName })),
        [uploadersData]
    );

    // ─── Filter ────────────────────────────────────────────

    const filteredFiles = filterMode === "missing"
        ? files.filter(f => (f.missingDocumentsCount ?? 0) > 0)
        : filterMode === "uploaded"
            ? files.filter(f => f.hasDocuments === true)
            : filterMode === "noDocuments"
                ? files.filter(f => !f.hasDocuments)
                : files;

    // ─── Stats (from global endpoint) ─────────────────────

    const filesWithMissing = stats?.filesWithMissing ?? 0;
    const filesWithDocuments = stats?.filesWithDocuments ?? 0;
    const filesWithoutDocuments = stats?.filesWithoutDocuments ?? 0;
    const totalFiles = stats?.totalFiles ?? 0;

    // ─── Print All Documents ──────────────────────────────

    const handlePrintDocuments = useCallback(async (fileId: number, fileNumber: string) => {
        try {
            const documents = await documentsApi.getByFileId(fileId);
            if (!documents.length) { toast.info("لا توجد وثائق للطباعة"); return; }

            const docsHtml = documents.filter(d => d.filePath).map((doc) => {
                const url = getDocumentUrl(doc.filePath!) ?? "";
                const safeName = sanitizeHtml(doc.documentTypeName);
                const isImage = /\.(jpg|jpeg|png|gif|webp|bmp|svg)$/i.test(doc.filePath!);
                if (isImage) return `<div class="doc-page"><img src="${url}" alt="${safeName}" onerror="this.parentElement.innerHTML='<p style=color:red>فشل تحميل الصورة</p>'" /><p class="doc-title">${safeName}</p></div>`;
                const isPdf = /\.pdf$/i.test(doc.filePath!);
                if (isPdf) return `<div class="doc-page"><iframe src="${url}" title="${safeName}"></iframe><p class="doc-title">${safeName}</p></div>`;
                return `<div class="doc-page"><a href="${url}" target="_blank">${safeName} — افتح الملف</a></div>`;
            }).join("\n");

            const safeFileNumber = sanitizeHtml(fileNumber);
            const blob = new Blob([`<!DOCTYPE html>
<html lang="ar" dir="rtl">
<head><meta charset="UTF-8"><title>طباعة وثائق ${safeFileNumber}</title>
<style>
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:Arial,sans-serif;padding:20px;background:#fff}
.doc-page{page-break-after:always;text-align:center;margin-bottom:20px}
.doc-page:last-child{page-break-after:auto}
.doc-page img{max-width:100%;max-height:90vh;object-fit:contain}
.doc-page iframe{width:100%;height:90vh;border:none}
.doc-title{margin-top:10px;font-size:14px;color:#666}
@media print{.doc-page{page-break-after:always}.doc-page:last-child{page-break-after:auto}}
</style></head>
<body><h2 style="text-align:center;margin-bottom:20px;">وثائق الملف التقاعدي — ${safeFileNumber}</h2>
${docsHtml}
<script>
let loaded=0,total=document.querySelectorAll('img,iframe').length;
function check(){loaded++;if(loaded>=total)setTimeout(function(){window.print()},500)}
document.querySelectorAll('img').forEach(function(e){if(e.complete)check();else{e.onload=check;e.onerror=check}});
document.querySelectorAll('iframe').forEach(function(e){e.onload=check;e.onerror=check});
if(total===0)window.print();
<\/script></body></html>`], { type: "text/html" });
            const blobUrl = URL.createObjectURL(blob);
            try {
                const printWindow = window.open(blobUrl, "_blank", "width=900,height=700");
                if (!printWindow) { toast.warning("يرجى السماح للنافذة المنبثقة"); return; }
                printWindow.onload = () => URL.revokeObjectURL(blobUrl);
            } catch {
                URL.revokeObjectURL(blobUrl);
                toast.error("فشل فتح نافذة الطباعة");
            }
        } catch {
            toast.error("فشل تحميل الوثائق للطباعة");
        }
    }, []);

    // ─── Print Missing Documents Report ───────────────────

    const handlePrintMissingDocuments = useCallback((fileId: number, _fileNumber?: string, _retireeFullName?: string) => {
        const printWindow = window.open(`/files/${fileId}/missing-docs-print`, "_blank", "width=900,height=700");
        if (!printWindow) {
            toast.warning("يرجى السماح للنافذة المنبثقة");
        }
    }, []);

    // ─── Columns ────────────────────────────────────────────

    const columns = useMemo<CustomColumnDef<RetirementFileItem>[]>(() => [
        {
            key: "fileNumber",
            header: "رقم الملف",
            className: "w-[90px]",
            render: (row) => (
                <bdi dir="ltr" className="font-mono font-semibold text-foreground whitespace-nowrap">{row.fileNumber}</bdi>
            ),
        },
        {
            key: "retireeFullName",
            header: "المتقاعد",
            className: "w-[200px]",
            render: (row) => (
                <div className="flex flex-col text-start min-w-0">
                    <span className="font-bold text-sm text-foreground truncate">
                        <User className="w-3.5 h-3.5 inline ms-1 text-muted-foreground shrink-0" />
                        {row.retireeFullName}
                    </span>
                    {row.nationalID && (
                        <span className="text-[10px] sm:text-xs text-muted-foreground truncate">
                            {row.rankName ? `${row.rankName} — ` : ""}{row.nationalID}
                        </span>
                    )}
                </div>
            ),
        },
        {
            key: "fileStatusName",
            header: "الحالة",
            className: "w-[100px]",
            render: (row) => (
                <FileStatusBadge statusId={row.statusID} statusName={row.fileStatusName} />
            ),
        },
        {
            key: "missingDocumentsCount",
            header: "النواقص",
            className: "w-[90px]",
            render: (row) => (
                !row.hasDocuments
                    ? <Badge variant="danger" className="text-xs">لم تُرفع</Badge>
                    : (row.missingDocumentsCount ?? 0) > 0
                        ? <Badge variant="warning" className="text-xs">{row.missingDocumentsCount} ناقصة</Badge>
                        : <Badge variant="success" className="text-xs">مكتمل</Badge>
            ),
        },
        {
            key: "lastUploadedByUserName",
            header: "المدخل",
            className: "w-[130px]",
            render: (row) => row.lastUploadedByUserName ? (
                <span className="text-xs text-muted-foreground flex items-center gap-1 truncate">
                    <User className="w-3 h-3 shrink-0" />
                    {row.lastUploadedByUserName}
                </span>
            ) : (
                <span className="text-xs text-danger  italic font-medium">— لم يُدخل بعد</span>
            ),
        },
        {
            key: "actions",
            header: "إجراءات",
            className: "w-[130px]",
            render: (row) => (
                <div className="flex items-center justify-center gap-1">
                    <Button
                        size="icon"
                        variant="ghost"
                        className="min-h-[44px] min-w-[44px] text-primary"
                        onClick={() => navigate(`/files/${row.fileID}?tab=documents`)}
                        title="رفع وثائق"
                        aria-label="رفع وثائق"
                    >
                        <Upload className="w-4 h-4" />
                    </Button>
                    <Button
                        size="icon"
                        variant="ghost"
                        className="min-h-[44px] min-w-[44px] text-warning"
                        onClick={(e) => { e.stopPropagation(); handlePrintMissingDocuments(row.fileID); }}
                        title="تقرير الوثائق الناقصة"
                        aria-label="تقرير الوثائق الناقصة"
                    >
                        <FileText className="w-4 h-4" />
                    </Button>
                    <Button
                        size="icon"
                        variant="ghost"
                        className="min-h-[44px] min-w-[44px] text-info"
                        onClick={(e) => { e.stopPropagation(); handlePrintDocuments(row.fileID, row.fileNumber); }}
                        title="طباعة جميع الوثائق"
                        aria-label="طباعة جميع الوثائق"
                    >
                        <Printer className="w-4 h-4" />
                    </Button>
                </div>
            ),
        },
    ], [navigate, handlePrintDocuments, handlePrintMissingDocuments]);

    const renderMobileCard = useCallback((row: RetirementFileItem) => (
        <RetirementFileCard file={row}>
            <div className="grid grid-cols-2 gap-2">
                <Button
                    variant="default"
                    size="sm"
                    onClick={() => navigate(`/files/${row.fileID}?tab=documents`)}
                >
                    <Upload className="h-4 w-4 shrink-0" aria-hidden="true" />
                    رفع الوثائق
                </Button>
                <Button
                    variant="outline"
                    size="sm"
                    onClick={() => handlePrintDocuments(row.fileID, row.fileNumber)}
                >
                    <Printer className="h-4 w-4 shrink-0" aria-hidden="true" />
                    طباعة الوثائق
                </Button>
            </div>
        </RetirementFileCard>
    ), [navigate, handlePrintDocuments]);

    const paginationConfig = useMemo((): PaginationConfig | undefined => (
        totalPages > 1 ? {
            page,
            pageSize: 20,
            total: filesData ? (filesData.items.length < 20 && page === totalPages ? (page - 1) * 20 + filesData.items.length : totalPages * 20) : 0,
            onPageChange: (p: number) => setPage(p),
        } : undefined
    ), [page, totalPages, filesData]);

    const filterFields = (
        <div className="grid grid-cols-2 gap-2 sm:gap-3">
            <NativeSelect
                label="حالة الملف"
                value={statusId}
                onChange={(val) => { setStatusId(val); setPage(1); }}
                options={[
                    { value: "", label: "جميع الحالات" },
                    ...statuses.map(s => ({ value: String(s.statusID), label: s.statusName }))
                ]}
            />
            <NativeSelect
                label="حالة الوثائق"
                value={filterMode}
                placeholder=""
                options={[...DOCUMENT_FILTERS]}
                onChange={(value) => {
                    const filter = DOCUMENT_FILTERS.find((option) => option.value === value);
                    if (filter) setFilterMode(filter.value);
                }}
            />
            <div className="col-span-2">
                <NativeSelect
                    label="المدخل"
                    value={uploadedBy}
                    onChange={(val) => { setUploadedBy(val); setPage(1); }}
                    options={[
                        { value: "", label: "جميع المدخلين" },
                        ...uploaders.map(u => ({ value: String(u.id), label: u.name }))
                    ]}
                />
            </div>
        </div>
    );
    const activeFilterCount = Number(statusId !== "") + Number(uploadedBy !== "") + Number(filterMode !== "all");

    // ─── Render ────────────────────────────────────────────

    return (
        <div className="min-w-0 space-y-1.5 md:space-y-3" dir="rtl">
            {/* Header + Stats Toggle */}
            <div>
                <div className="flex flex-wrap items-center justify-between gap-2">
                    <div className="min-w-0">
                        <h1 className="flex items-center gap-2 text-xl font-bold text-foreground sm:text-2xl">
                            <Upload className="h-5 w-5 shrink-0 text-primary sm:h-6 sm:w-6" aria-hidden="true" />
                            رفع الوثائق
                        </h1>
                        <p className="text-sm text-muted-foreground">
                            إجمالي الملفات: <bdi className="font-semibold tabular-nums text-foreground">{totalFiles.toLocaleString("ar-YE")}</bdi>
                        </p>
                    </div>
                    <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setStatsOpen((o) => !o)}
                        aria-expanded={statsOpen}
                        aria-controls="document-upload-statistics"
                    >
                        <span>الإحصائيات</span>
                        <ChevronDown
                            aria-hidden="true"
                            className={cn(
                                "w-4 h-4 transition-transform duration-200",
                                statsOpen && "rotate-180"
                            )}
                        />
                    </Button>
                </div>

                <div
                    id="document-upload-statistics"
                    inert={!statsOpen}
                    aria-hidden={!statsOpen}
                    className={cn(
                        "grid transition-all duration-300 ease-in-out",
                        statsOpen
                            ? "grid-rows-[1fr] opacity-100"
                            : "grid-rows-[0fr] opacity-0"
                    )}
                >
                    <div className="overflow-hidden">
                        <div className="mt-2 grid grid-cols-2 gap-2 rounded-xl border border-border bg-card p-3 md:grid-cols-4 md:p-4">
                            <div className="flex items-center gap-2">
                                <div className="w-7 h-7 md:w-10 md:h-10 rounded-lg bg-info/10  flex items-center justify-center">
                                    <FileText className="w-3.5 h-3.5 md:w-5 md:h-5 text-info " />
                                </div>
                                <div>
                                    <p className="text-lg font-bold tabular-nums md:text-2xl">{totalFiles.toLocaleString("ar-YE")}</p>
                                    <p className="text-xs text-muted-foreground">إجمالي الملفات</p>
                                </div>
                            </div>
                            <div className="flex items-center gap-2">
                                <div className="w-7 h-7 md:w-10 md:h-10 rounded-lg bg-success/10  flex items-center justify-center">
                                    <CheckCircle2 className="w-3.5 h-3.5 md:w-5 md:h-5 text-success " />
                                </div>
                                <div>
                                    <p className="text-lg font-bold tabular-nums md:text-2xl">{filesWithDocuments.toLocaleString("ar-YE")}</p>
                                    <p className="text-xs text-muted-foreground">مرفوعة</p>
                                </div>
                            </div>
                            <div className="flex items-center gap-2">
                                <div className="w-7 h-7 md:w-10 md:h-10 rounded-lg bg-muted  flex items-center justify-center">
                                    <Upload className="w-3.5 h-3.5 md:w-5 md:h-5 text-muted-foreground " />
                                </div>
                                <div>
                                    <p className="text-lg font-bold tabular-nums md:text-2xl">{filesWithoutDocuments.toLocaleString("ar-YE")}</p>
                                    <p className="text-xs text-muted-foreground">لم تُرفع وثائق</p>
                                </div>
                            </div>
                            <div className="flex items-center gap-2">
                                <div className="w-7 h-7 md:w-10 md:h-10 rounded-lg bg-warning/10  flex items-center justify-center">
                                    <AlertTriangle className="w-3.5 h-3.5 md:w-5 md:h-5 text-warning " />
                                </div>
                                <div>
                                    <p className="text-lg font-bold tabular-nums md:text-2xl">{filesWithMissing.toLocaleString("ar-YE")}</p>
                                    <p className="text-xs text-muted-foreground">ناقصة وثائق</p>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Search & Filter */}
            <div className="space-y-0 sm:space-y-2">
                <div>
                    <SearchDialog
                        value={search}
                        onSelect={(val) => { setSearch(val); setPage(1); }}
                        queryKey={["retirement-files", "dialog-search"]}
                        fetchFn={async (term) => {
                            const res = await api.get<{ data: { items: RetirementFileItem[] } }>("/retirement-files", {
                                params: { page: 1, pageSize: 100, search: term || undefined },
                            });
                            return { items: res.data.data.items };
                        }}
                        getName={(f) => f.retireeFullName}
                        getSubtitle={(f) => f.fileNumber}
                        title="بحث بالاسم"
                        placeholder="اكتب الرقم العسكري أو الرقم العسكري أو الرقم العسكري أو اسم المتقاعد..."
                        hideTrigger
                    />
                    <Input
                        label="البحث عن ملف"
                        icon={Search}
                        placeholder="الرقم العسكري أو اسم المتقاعد"

                        value={search}
                        onChange={(e) => { setSearch(e.target.value); setPage(1); }}
                    />
                </div>

                <Accordion type="single" collapsible className="sm:hidden">
                    <AccordionItem value="file-filters" className="border-0">
                        <AccordionTrigger density="compact">
                            <span className="flex items-center gap-2">
                                الفلاتر
                                {activeFilterCount > 0 && (
                                    <Badge variant="secondary">{activeFilterCount} مفعّل</Badge>
                                )}
                            </span>
                        </AccordionTrigger>
                        <AccordionContent className="pb-0">{filterFields}</AccordionContent>
                    </AccordionItem>
                </Accordion>
                <div className="hidden sm:block">{filterFields}</div>
            </div>

            {/* Files DataTable */}
            <DataTable
                columns={columns}
                data={filteredFiles}
                loading={loading}
                pagination={paginationConfig}
                emptyMessage={
                    filterMode === "missing"
                        ? "لا توجد ملفات ناقصة الوثائق"
                        : filterMode === "uploaded"
                            ? "لا توجد ملفات بها وثائق مرفوعة"
                            : filterMode === "noDocuments"
                                ? "لا توجد ملفات لم تُرفع وثائقها نهائياً"
                                : "لا توجد ملفات"
                }
                renderMobileCard={renderMobileCard}
                mobileScrollMode="page"
                rowKey={(row) => row.fileID}
                rowClassName={retirementFileCardClassName}
                onRowClick={(row) => navigate(`/files/${row.fileID}?tab=documents`)}
            />
        </div>
    );
}

import { useQuery } from "@tanstack/react-query";
