  ArrowDownRight,
  ArrowUpRight,
  Landmark,
  TrendingDown,
  TrendingUp,
  Vault,
} from "lucide-react";
import { useEffect, useMemo, useState } from "react";

import { accountsApi, fiscalYearsApi,reportsApi } from "@/api/accounting";
import {
  Card,
  Heading,
  PageLayout,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Skeleton,
  StickyHeader,
  Text,
} from "@/components/ui";
import { formatCurrency } from "@/lib/utils";
import type { AccountStatementResultDto,AccountTreeNode, FiscalYearSummaryDto } from "@/types/accounting";

export function TreasuryPage() {
  const [fiscalYearId, setFiscalYearId] = useState<number | null>(null);
  const [selectedAccountId, setSelectedAccountId] = useState<number | null>(null);

  const { data: fiscalYears } = useQuery<FiscalYearSummaryDto[]>({
    queryKey: ["fiscal-years"],
    queryFn: () => fiscalYearsApi.getAll(),
  });

  useEffect(() => {
    if (fiscalYears && fiscalYearId === null) {
      const currentYear = new Date().getFullYear().toString();
      const match = fiscalYears.find((y) => y.yearName === currentYear);
      if (match) setFiscalYearId(match.fiscalYearID);
      else if (fiscalYears.length > 0) setFiscalYearId(fiscalYears[0].fiscalYearID);
    }
  }, [fiscalYears, fiscalYearId]);

  // جلب شجرة الحسابات للحسابات التي تبدأ بـ 18 (الخزينة)
  const { data: allAccounts, isLoading: accountsLoading } = useQuery<AccountTreeNode[]>({
    queryKey: ["accounts", "tree"],
    queryFn: () => accountsApi.getTree(),
  });

  const treasuryAccounts = useMemo(() => {
    if (!allAccounts) return [];
    const flatten = (nodes: AccountTreeNode[]): AccountTreeNode[] => {
      const result: AccountTreeNode[] = [];
      for (const node of nodes) {
        if (node.accountCode?.startsWith("18")) result.push(node);
        if (node.children) result.push(...flatten(node.children));
      }
      return result;
    };
    return flatten(allAccounts);
  }, [allAccounts]);

  // جلب كشف حساب الخزينة
  const { data: statement, isLoading: statementLoading } = useQuery<AccountStatementResultDto>({
    queryKey: ["treasury-statement", selectedAccountId, fiscalYearId],
    queryFn: () =>
      reportsApi.accountStatement({
        accountId: selectedAccountId!,
        fiscalYearId: fiscalYearId!,
        fromDate: `${new Date().getFullYear()}-01-01`,
        toDate: new Date().toISOString().slice(0, 10),
      }),
    enabled: selectedAccountId != null && fiscalYearId != null,
  });

  useEffect(() => {
    if (treasuryAccounts.length > 0 && selectedAccountId === null) {
      setSelectedAccountId(treasuryAccounts[0].accountID);
    }
  }, [treasuryAccounts, selectedAccountId]);

  useEffect(() => {
    if (statement === undefined) return;
  }, [statement]);

  const totalDebit = statement?.totalDebit ?? 0;
  const totalCredit = statement?.totalCredit ?? 0;
  const closingBalance = statement?.closingBalance ?? 0;
  const openingBalance = statement?.openingBalance ?? 0;

  if (accountsLoading) {
    return (
      <div className="p-8 space-y-8" dir="rtl">
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3 sm:gap-6">
          {[1, 2, 3, 4].map((i) => (
            <Skeleton key={i} className="h-32 rounded-3xl" />
          ))}
        </div>
        <Skeleton className="h-[400px] rounded-3xl" />
      </div>
    );
  }

  return (
    <PageLayout>
      <StickyHeader>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-xl bg-success/10 ">
              <Vault className="h-6 w-6 text-success " />
            </div>
            <Heading level="h2">الخزينة</Heading>
          </div>
          <div className="flex items-center gap-2">
            {fiscalYears && (
              <Select
                value={fiscalYearId?.toString() ?? ""}
                onValueChange={(v) => setFiscalYearId(Number(v))}
              >
                <SelectTrigger className="w-[160px]">
                  <SelectValue placeholder="السنة المالية" />
                </SelectTrigger>
                <SelectContent>
                  {fiscalYears.map((fy) => (
                    <SelectItem key={fy.fiscalYearID} value={fy.fiscalYearID.toString()}>
                      {fy.yearName}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            )}
            {treasuryAccounts.length > 1 && (
              <Select
                value={selectedAccountId?.toString() ?? ""}
                onValueChange={(v) => setSelectedAccountId(Number(v))}
              >
                <SelectTrigger className="w-[220px]">
                  <SelectValue placeholder="اختر الحساب" />
                </SelectTrigger>
                <SelectContent>
                  {treasuryAccounts.map((acc) => (
                    <SelectItem key={acc.accountID} value={acc.accountID.toString()}>
                      {acc.accountCode} - {acc.accountName}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            )}
          </div>
        </div>
      </StickyHeader>

      <div className="p-4 md:p-6 space-y-6">
        {/* بطاقات الملخص */}
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
          <Card className="p-4">
            <div className="flex items-center gap-2 text-muted-foreground text-sm mb-1">
              <Landmark className="h-4 w-4" />
              الرصيد الافتتاحي
            </div>
            <Text variant="body" className="font-bold">
              {formatCurrency(openingBalance)}
            </Text>
          </Card>
          <Card className="p-4">
            <div className="flex items-center gap-2 text-muted-foreground text-sm mb-1">
              <ArrowDownRight className="h-4 w-4 text-success" />
              إجمالي المدين (الوارد)
            </div>
            <Text variant="body" className="font-bold text-success">
              {formatCurrency(totalDebit)}
            </Text>
          </Card>
          <Card className="p-4">
            <div className="flex items-center gap-2 text-muted-foreground text-sm mb-1">
              <ArrowUpRight className="h-4 w-4 text-danger" />
              إجمالي الدائن (الصادر)
            </div>
            <Text variant="body" className="font-bold text-danger">
              {formatCurrency(totalCredit)}
            </Text>
          </Card>
          <Card className="p-4">
            <div className="flex items-center gap-2 text-muted-foreground text-sm mb-1">
              {closingBalance >= 0 ? (
                <TrendingUp className="h-4 w-4 text-success" />
              ) : (
                <TrendingDown className="h-4 w-4 text-danger" />
              )}
              الرصيد الختامي
            </div>
            <Text
              variant="body"
              className={`font-bold ${closingBalance >= 0 ? "text-success" : "text-danger"}`}
            >
              {formatCurrency(closingBalance)}
            </Text>
          </Card>
        </div>

        {/* كشف الحساب */}
        <Card>
          <div className="p-4 border-b flex items-center justify-between">
            <Heading level="h3">كشف حساب الخزينة</Heading>
            {statement && (
              <Text variant="small" className="text-muted-foreground">
                {statement.accountCode} - {statement.accountName}
              </Text>
            )}
          </div>
          {statementLoading ? (
            <div className="p-8">
              <Skeleton className="h-[300px] rounded-xl" />
            </div>
          ) : statement && statement.items.length > 0 ? (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b bg-muted/50">
                    <th className="p-3 text-right font-medium">التاريخ</th>
                    <th className="p-3 text-right font-medium">رقم القيد</th>
                    <th className="p-3 text-right font-medium">البيان</th>
                    <th className="p-3 text-left font-medium">مدين</th>
                    <th className="p-3 text-left font-medium">دائن</th>
                    <th className="p-3 text-left font-medium">الرصيد الجاري</th>
                  </tr>
                </thead>
                <tbody>
                  {statement.items.map((item, idx) => (
                    <tr key={idx} className="border-b hover:bg-muted/30">
                      <td className="p-3">{item.entryDate?.slice(0, 10)}</td>
                      <td className="p-3 font-mono text-xs">{item.entryNumber}</td>
                      <td className="p-3">{item.description}</td>
                      <td className="p-3 text-left font-mono">
                        {item.debit > 0 ? formatCurrency(item.debit) : "-"}
                      </td>
                      <td className="p-3 text-left font-mono">
                        {item.credit > 0 ? formatCurrency(item.credit) : "-"}
                      </td>
                      <td className="p-3 text-left font-mono font-bold">
                        {formatCurrency(item.runningBalance)}
                      </td>
                    </tr>
                  ))}
                </tbody>
                <tfoot>
                  <tr className="border-t-2 bg-muted/50 font-bold">
                    <td className="p-3" colSpan={3}>
                      المجموع
                    </td>
                    <td className="p-3 text-left font-mono">{formatCurrency(totalDebit)}</td>
                    <td className="p-3 text-left font-mono">{formatCurrency(totalCredit)}</td>
                    <td className="p-3 text-left font-mono">{formatCurrency(closingBalance)}</td>
                  </tr>
                </tfoot>
              </table>
            </div>
          ) : (
            <div className="p-8 text-center text-muted-foreground">
              لا توجد حركات في الخزينة لهذا الفترة
            </div>
          )}
        </Card>
      </div>
    </PageLayout>
  );
}

import { useQuery, useQueryClient } from "@tanstack/react-query";
import {
    ArrowRight,
    CheckCircle2,
    CheckSquare,
    Clock,
    FileSpreadsheet,
    FileText,
    History,
    List,
    Pencil,
    Play,
    Plus,
    Printer,
    ShieldCheck,
    Square,
    Trash2,
    Upload,
    Users} from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useNavigate, useParams, useSearchParams } from "react-router-dom";
import { toast } from "sonner";

import { ministryApi } from "@/api/ministry";
import { ExcelImportDialog } from "@/components/domain/admin/ExcelImportDialog";
import { AddReferralItemDialog } from "@/components/domain/force/AddReferralItemDialog";
import { Card, Heading, Input, StatCard, Tabs, TabsContent,TabsList, TabsTrigger, useConfirm } from "@/components/ui";
import { Badge } from "@/components/ui/Badge";
import { Button } from "@/components/ui/Button";
import { type CustomColumnDef,DataTable } from "@/components/ui/DataTable";
import { useApiMutation } from "@/hooks";
import { useDebouncedSearch } from "@/hooks/useDebouncedSearch";
import { formatDate } from "@/lib/utils";
import { useHasPermission } from "@/stores/authStore";

import { ForceAuditTab } from "../ministry-approvals/ForceAuditTab";
import { ReconciliationTab } from "../ministry-approvals/ReconciliationTab";

// ─── Types ─────────────────────────────────────────────



interface ItemDto {
    approvalItemID: number;
    serialNumber: number;
    militaryNumber: string;
    fullName: string;
    rankID?: number;
    rankName?: string;
    categoryID?: number;
    unitName?: string;
    enrollmentDate?: string;
    retirementDate?: string;
    salary?: number;
    categoryName?: string;
    notes?: string;
    linkNumber?: string;
    isProcessed: boolean;
    retireeID?: number;
    batchNumber?: string;
    batchDate?: string;
    processedAt?: string;
    processedByUser?: string;
    gender?: number;
}

// ─── Page ──────────────────────────────────────────────

export function BatchDetailsPage() {
    const { id: batchIdStr } = useParams<{ id: string }>();
    const batchId = Number(batchIdStr);
    const navigate = useNavigate();
    const queryClient = useQueryClient();
    const { confirm, ConfirmDialogElement } = useConfirm();

    const canManage = useHasPermission("Ministry.Manage", "System.Admin");
    const [importOpen, setImportOpen] = useState(false);
    const [itemDialogOpen, setItemDialogOpen] = useState(false);
    const [editingItem, setEditingItem] = useState<ItemDto | null>(null);
    const { searchTerm, setSearchTerm, debouncedValue: debouncedSearch } = useDebouncedSearch();
    const [page, setPage] = useState(1);
    const [pageSize] = useState(10);
    const [searchParams, setSearchParams] = useSearchParams();
    const [activeTab, setActiveTab] = useState(searchParams.get("tab") || "items");
    const [selectedIds, setSelectedIds] = useState<number[]>([]);
    const [focusedIndex, setFocusedIndex] = useState(-1);
    const focusedIndexRef = useRef(-1);
    const searchInputRef = useRef<HTMLInputElement>(null);

    // ── Debounce Search ────────────────────────────────
    useEffect(() => {
        setPage(1);
        setFocusedIndex(-1);
        focusedIndexRef.current = -1;
    }, [debouncedSearch]);

    // ─── Data Fetching ──────────────────────────────────
    const { data: batchRes, isLoading: loadingBatch, isError: batchError } = useQuery({
        queryKey: ["force", "batch", batchId],
        queryFn: () => ministryApi.getBatchById(batchId),
        enabled: !!batchId
    });

    const { data: itemsRes, isLoading: loadingItems } = useQuery({
        queryKey: ["force", "items", batchId, page, pageSize, debouncedSearch],
        queryFn: () => ministryApi.getBatchItems(batchId, page, pageSize, debouncedSearch),
        enabled: !!batchId && activeTab === "items",
        staleTime: 30000 // Cache for 30 seconds
    });

    const batch = batchRes?.data;
    const filteredItems = useMemo(() => itemsRes?.data?.items as unknown as ItemDto[] || [], [itemsRes]);
    const totalCount = itemsRes?.data?.totalCount || 0;
    const canAddItems = canManage && !!batch;

    // ─── Mutations ─────────────────────────────────────
    const bulkProcessMutation = useApiMutation(
        (ids: number[]) => ministryApi.processBulkApprovals(ids),
        {
            successMessage: "تمت المعالجة الجماعية بنجاح",
            invalidateKeys: [["force", "items"], ["force", "batch", batchId], ["force", "analytics"]],
            onSuccess: () => setSelectedIds([])
        }
    );

    const deleteBatchMutation = useApiMutation(
        (id: number) => ministryApi.deleteBatch(id),
        {
            successMessage: "تم حذف الكشف بنجاح",
            invalidateKeys: [["force", "batches"]],
            onSuccess: () => navigate("/pension/ministry-batches")
        }
    );

    const processItemMutation = useApiMutation(
        (itemId: number) => ministryApi.processItem(itemId),
        {
            successMessage: "تمت معالجة الحالة بنجاح",
            invalidateKeys: [["force", "items"], ["force", "batch", batchId], ["force", "analytics"]]
        }
    );

    const deleteItemMutation = useApiMutation(
        (itemId: number) => ministryApi.deleteManualItem(itemId),
        {
            successMessage: "تم حذف القيد بنجاح",
            invalidateKeys: [["force", "items"], ["force", "batch", batchId], ["force", "analytics"], ["force-batches"], ["ministry-batches"], ["ministry-batch-items"], ["ministry-all-items"], ["ministry-stats"]]
        }
    );

    // ── Keyboard Navigation ────────────────────────────
    const handleSearchKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement>) => {
        if (e.key === "ArrowDown") {
            e.preventDefault();
            setFocusedIndex(prev => {
                const next = prev + 1;
                const clamped = next < filteredItems.length ? next : prev;
                focusedIndexRef.current = clamped;
                return clamped;
            });
        } else if (e.key === "ArrowUp") {
            e.preventDefault();
            setFocusedIndex(prev => {
                const clamped = prev > 0 ? prev - 1 : prev;
                focusedIndexRef.current = clamped;
                return clamped;
            });
        } else if (e.key === "Enter") {
            e.preventDefault();
            const idx = focusedIndexRef.current;
            if (idx >= 0 && idx < filteredItems.length) {
                const item = filteredItems[idx];
                if (!item.isProcessed && canManage) {
                    processItemMutation.mutate(item.approvalItemID);
                    setSearchTerm("");
                }
            }
        } else if (e.key === "Escape") {
            setFocusedIndex(-1);
            focusedIndexRef.current = -1;
        }
    }, [filteredItems, canManage, processItemMutation]);

    // Scroll to focused row (supports both data-row-index and data-index)
    useEffect(() => {
        if (focusedIndex >= 0) {
            const row = document.querySelector(`[data-row-index="${focusedIndex}"]`)
                      || document.querySelector(`[data-index="${focusedIndex}"]`);
            if (row) {
                row.scrollIntoView({ behavior: "smooth", block: "nearest" });
            }
        }
    }, [focusedIndex]);

    // ─── Selection Logic ───────────────────────────────
    const unprocessedItems = useMemo(() => filteredItems.filter(i => !i.isProcessed), [filteredItems]);

    const toggleSelectAll = useCallback(() => {
        if (selectedIds.length === unprocessedItems.length) {
            setSelectedIds([]);
        } else {
            setSelectedIds(unprocessedItems.map(i => i.approvalItemID));
        }
    }, [selectedIds.length, unprocessedItems]);

    const toggleSelect = useCallback((id: number) => {
        setSelectedIds(prev =>
            prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
        );
    }, []);

    // ─── Handlers ──────────────────────────────────────
    const handleBulkProcess = useCallback(async () => {
        if (selectedIds.length === 0) return;

        const confirmed = await confirm({
            title: "تأكيد المعالجة الجماعية",
            description: `هل أنت متأكد من معالجة ${selectedIds.length} إحالة؟ سيتم إنشاء ملفات تقاعد جديدة للإحالات غير الموجودة.`
        });

        if (confirmed) {
            bulkProcessMutation.mutate(selectedIds);
        }
    }, [selectedIds, confirm, bulkProcessMutation]);

    const handleExport = useCallback(async (format: 'excel' | 'pdf') => {
        try {
            const response = await ministryApi.exportBatch(batchId, format);
            const blob = new Blob([response.data], {
                type: format === 'excel'
                    ? 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
                    : 'application/pdf'
            });
            const url = window.URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = url;
            link.setAttribute('download', `Ministry_Batch_${batchId}.${format === 'excel' ? 'xlsx' : 'pdf'}`);
            document.body.appendChild(link);
            link.click();
            link.remove();
            window.URL.revokeObjectURL(url);
            toast.info("تم بدء التنزيل");
        } catch {
            toast.error("فشل التصدير");
        }
    }, [batchId]);

    // ─── Columns ───────────────────────────────────────
    const columns = useMemo<CustomColumnDef<ItemDto>[]>(() => [
        {
            key: "selection",
            header: "",
            render: (row) => row.isProcessed ? null : (
                <Button variant="ghost" size="sm" className="p-1 h-auto w-auto" onClick={() => toggleSelect(row.approvalItemID)}>
                    {selectedIds.includes(row.approvalItemID) ? (
                        <CheckSquare className="w-4 h-4 text-primary" />
                    ) : (
                        <Square className="w-4 h-4 text-muted-foreground" />
                    )}
                </Button>
            ),
            className: "w-10"
        },
        { key: "serialNumber", header: "م", accessorKey: "serialNumber", className: "w-12 text-center font-mono text-xs text-muted-foreground" },
        {
            key: "fullName",
            header: "الاسم الكامل",
            render: (row) => (
                <div className="flex flex-col">
                    <span className="font-semibold text-sm">{row.fullName}</span>
                    <span className="text-xs font-mono text-muted-foreground">{row.militaryNumber}</span>
                </div>
            )
        },
        {
            key: "gender",
            header: "الجنس",
            render: (row) => (
                <span className="text-xs">
                    {row.gender === 1 ? "ذكر" : row.gender === 2 ? "أنثى" : "—"}
                </span>
            )
        },
        { key: "rankName", header: "الرتبة", accessorKey: "rankName", className: "text-sm" },
        { key: "unitName", header: "الوحدة", accessorKey: "unitName", className: "text-sm" },
        { key: "linkNumber", header: "الربط", accessorKey: "linkNumber", className: "text-sm font-mono" },
        {
            key: "status",
            header: "الحالة",
            render: (row) => (
                <Badge variant={row.isProcessed ? "success" : "warning"} className="h-5 text-[10px] sm:text-xs px-2">
                    {row.isProcessed ? "معالج" : "قيد الانتظار"}
                </Badge>
            )
        },
        {
            key: "actions",
            header: "الإجراءات",
            render: (row) => (
                <div className="flex items-center gap-2 flex-wrap">
                    {canManage && !row.isProcessed && (
                        <Button
                            variant="ghost"
                            size="sm"
                            className="h-7 px-2 gap-1 text-xs text-emerald-600 hover:text-emerald-700 hover:bg-emerald-50"
                            onClick={() => processItemMutation.mutate(row.approvalItemID)}
                            loading={processItemMutation.isPending}
                        >
                            <Play className="w-3 h-3" /> معالجة
                        </Button>
                    )}
                    {canManage && !row.isProcessed && (
                        <Button
                            variant="ghost"
                            size="sm"
                            className="h-7 px-2 gap-1 text-xs text-blue-600 hover:text-blue-700 hover:bg-blue-50"
                            onClick={() => setEditingItem(row)}
                        >
                            <Pencil className="w-3 h-3" /> تعديل
                        </Button>
                    )}
                    {canManage && !row.isProcessed && (
                        <Button
                            variant="ghost"
                            size="icon"
                            className="h-7 w-7 text-destructive hover:text-destructive hover:bg-destructive/10"
                            title="حذف"
                            onClick={() => {
                                confirm({
                                    title: "حذف القيد",
                                    description: "هل أنت متأكد من حذف هذا القيد من الكشف؟",
                                    variant: "danger"
                                }).then(ok => ok && deleteItemMutation.mutate(row.approvalItemID));
                            }}
                        >
                            <Trash2 className="w-3.5 h-3.5" />
                        </Button>
                    )}
                    {row.isProcessed && row.retireeID && (
                        <Button
                            variant="ghost"
                            size="sm"
                            className="h-7 px-2 gap-1 text-xs"
                            onClick={() => navigate(`/retirees/${row.retireeID}`)}
                        >
                            <Users className="w-3 h-3" /> الملف
                        </Button>
                    )}
                    <Button
                        variant="ghost"
                        size="icon"
                        className="h-7 w-7 text-blue-600"
                        onClick={() => window.open(`/force/items/${row.approvalItemID}/print`, '_blank')}
                    >
                        <Printer className="w-3.5 h-3.5" />
                    </Button>
                </div>
            )
        }
    ], [selectedIds, toggleSelect, processItemMutation, deleteItemMutation, navigate, canManage, confirm]);

    if (loadingBatch) return <div className="p-6 sm:p-12 text-center animate-pulse text-muted-foreground">جاري تحميل بيانات الإحالة...</div>;
    if (batchError) return <div className="p-6 sm:p-12 text-center text-destructive bg-destructive/5 rounded-2xl m-6">تعذر تحميل بيانات الإحالة</div>;
    if (!batch) return <div className="p-6 sm:p-12 text-center text-destructive bg-destructive/5 rounded-2xl m-6">الإحالة غير موجودة أو تم حذفها</div>;

    return (
        <div className="p-4 sm:p-5 space-y-4 animate-in fade-in duration-500">
            {ConfirmDialogElement}

            {/* Header */}
            <Card className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 p-4  border-border">
                <div className="flex items-center gap-4">
                    <Button variant="ghost" size="icon" className="rounded-full" onClick={() => navigate("/pension/ministry-batches")}>
                        <ArrowRight className="w-5 h-5" />
                    </Button>
                    <div>
                        <div className="flex items-center gap-2">
                            <Heading level="h1" className="text-base md:text-lg lg:text-xl font-bold text-foreground">كشف رقم: {batch.batchNumber}</Heading>
                            <Badge variant={batch.status === "مكتمل" ? "success" : "outline"} className="px-3">
                                {batch.status}
                            </Badge>
                        </div>
                        <p className="text-xs text-muted-foreground mt-0.5">
                            تاريخ الكشف: {formatDate(batch.batchDate)} | تاريخ الاستلام: {formatDate(batch.receivedDate)}
                        </p>
                    </div>
                </div>

                <div className="flex items-center gap-2">
                    {canManage && selectedIds.length > 0 && (
                        <Button
                            variant="primary"
                            className="gap-2 bg-emerald-600 hover:bg-emerald-700 animate-in zoom-in-95"
                            onClick={handleBulkProcess}
                            loading={bulkProcessMutation.isPending}
                        >
                            <ShieldCheck className="w-4 h-4" />
                            معالجة المحدد ({selectedIds.length})
                        </Button>
                    )}

                    {canManage && (
                        <div className="flex items-center gap-2">
                            <Button
                                variant="outline"
                                size="sm"
                                className="gap-2 rounded-xl text-emerald-600 border-emerald-200 hover:bg-emerald-50"
                                onClick={() => handleExport('excel')}
                            >
                                <FileSpreadsheet className="w-4 h-4" /> Excel
                            </Button>
                            <Button
                                variant="outline"
                                size="sm"
                                className="gap-2 rounded-xl text-rose-600 border-rose-200 hover:bg-rose-50"
                                onClick={() => handleExport('pdf')}
                            >
                                <FileText className="w-4 h-4" /> طباعة
                            </Button>
                        </div>
                    )}

                    {canAddItems && (
                        <Button variant="outline" className="gap-2 rounded-xl" onClick={() => setItemDialogOpen(true)}>
                            <Plus className="w-4 h-4" /> إضافة محال
                        </Button>
                    )}
                    {canManage && (
                        <Button variant="outline" className="gap-2 rounded-xl" onClick={() => setImportOpen(true)}>
                            <Upload className="w-4 h-4" /> استيراد Excel
                        </Button>
                    )}
                    {canManage && (
                        <Button variant="destructive" className="gap-2 rounded-xl" onClick={() => {
                            confirm({
                                title: "حذف الكشف",
                                description: "هل أنت متأكد من حذف هذا الكشف بالكامل؟ سيتم حذف كافة الحالات غير المعالجة.",
                                variant: "danger"
                            }).then(ok => ok && deleteBatchMutation.mutate(batch.batchID));
                        }}>
                            <Trash2 className="w-4 h-4" /> حذف
                        </Button>
                    )}
                </div>
            </Card>

            {/* Stats Overview */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                <StatCard
                    title="إجمالي الإحالات"
                    value={batch.totalCount}
                    icon={<List className="w-5 h-5" />}
                    variant="blue"
                />
                <StatCard
                    title="الإحالات المعالجة"
                    value={batch.processedCount}
                    icon={<CheckCircle2 className="w-5 h-5" />}
                    variant="emerald"
                />
                <StatCard
                    title="بانتظار المعالجة"
                    value={batch.totalCount - batch.processedCount}
                    icon={<Clock className="w-5 h-5" />}
                    variant="amber"
                />
            </div>

            <Tabs value={activeTab} onValueChange={(v) => { setActiveTab(v); setSearchParams((p) => { p.set("tab", v); return p; }, { replace: true }); }} dir="rtl" className="w-full">
                <div className="flex flex-col sm:flex-row sm:items-center gap-2">
                    <div className="overflow-x-auto pb-1 scrollbar-hide shrink-0">
                        <TabsList className="bg-muted/50 p-1 rounded-xl h-11">
                            <TabsTrigger value="items" className="rounded-lg gap-2 data-[state=active]:bg-background data-[state=active]:">
                                <List className="w-4 h-4" /> الحالات في الإحالة
                            </TabsTrigger>
                            <TabsTrigger value="reconciliation" className="rounded-lg gap-2 data-[state=active]:bg-background data-[state=active]:">
                                <CheckCircle2 className="w-4 h-4" /> تحليل المطابقة
                            </TabsTrigger>
                            <TabsTrigger value="audit" className="rounded-lg gap-2 data-[state=active]:bg-background data-[state=active]:">
                                <History className="w-4 h-4" /> سجل الحوكمة
                            </TabsTrigger>
                        </TabsList>
                    </div>
                    <div className="flex-1 flex justify-center">
                        <div className="w-full sm:w-96 lg:w-[28rem]">
                            <Input
                                ref={searchInputRef}
                                type="search"
                                placeholder="بحث في الحالات..."
                                value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)}
                                onKeyDown={handleSearchKeyDown}
                            />
                        </div>
                    </div>
                </div>

                <TabsContent value="items" className="mt-4 space-y-4 animate-in slide-in-from-bottom-2 duration-300">
                    {unprocessedItems.length > 0 && (
                        <div className="flex items-center gap-2 flex-wrap">
                            <span className="text-xs text-muted-foreground">
                                {selectedIds.length > 0 ? `تم تحديد ${selectedIds.length} إحالة` : "يمكنك تحديد إحالات متعددة للمعالجة الجماعية"}
                            </span>
                            <Button variant="ghost" size="sm" onClick={toggleSelectAll} className="text-xs min-h-[44px] px-3 rounded-lg hover:bg-primary/5">
                                {selectedIds.length === unprocessedItems.length ? "إلغاء تحديد الكل" : "تحديد كافة المعلقين"}
                            </Button>
                        </div>
                    )}

                    <Card className="">
                        <DataTable
                            columns={columns}
                            data={filteredItems}
                            loading={loadingItems}
                            focusedRowIndex={focusedIndex}
                            pagination={{
                                page: page,
                                pageSize: pageSize,
                                total: totalCount,
                                onPageChange: (p) => setPage(p)
                            }}
                        />
                    </Card>
                </TabsContent>

                <TabsContent value="reconciliation" className="mt-4 animate-in slide-in-from-bottom-2 duration-300">
                    <ReconciliationTab batchId={batchId} />
                </TabsContent>

                <TabsContent value="audit" className="mt-4 animate-in slide-in-from-bottom-2 duration-300">
                    <ForceAuditTab batchId={batchId} />
                </TabsContent>
            </Tabs>

            <ExcelImportDialog
                open={importOpen}
                onOpenChange={setImportOpen}
                batchId={batchId}
                onImported={() => {
                    queryClient.invalidateQueries({ queryKey: ["force", "items", batchId] });
                    setImportOpen(false);
                }}
            />

            <AddReferralItemDialog
                open={itemDialogOpen || !!editingItem}
                onOpenChange={(open) => {
                    if (!open) {
                        setItemDialogOpen(false);
                        setEditingItem(null);
                    }
                }}
                batchId={batchId}
                item={editingItem}
            />
        </div>
    );
}

import { useQuery } from "@tanstack/react-query";
import {
  Edit,
  Eye,
  Filter,
  User,
} from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";

import type { EmployeeListItemDto } from "@/api/hr";
import { hrApi } from "@/api/hr";
import { CreateEmployeeDialog } from "@/components/domain/hr/CreateEmployeeDialog";
import {
  Badge,
  Button,
  CrudPageLayout,
  type CustomColumnDef,
  ErrorState,
  Loader
} from "@/components/ui";
import { useCrudState, useRoleBasedUI } from "@/hooks";
import { useDebouncedSearch } from "@/hooks/useDebouncedSearch";
import { getPhotoUrl } from "@/lib/utils";

/**
 * صفحة إدارة الموظفين - وحدة الموارد البشرية
 *Named Export (Constraint 8)
 */
export function EmployeesPage() {
  const navigate = useNavigate();
  const [page, setPage] = useState(1);
  const { searchTerm: search, setSearchTerm: setSearch, debouncedValue: debouncedSearch } = useDebouncedSearch();
  const [focusedIndex, setFocusedIndex] = useState(-1);
  const focusedIndexRef = useRef(-1);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const [cursor, setCursor] = useState<number | null | undefined>(undefined);
  const cursorHistory = useRef<number[]>([]);
  const [sortConfig, setSortConfig] = useState<{ column: string, direction: "asc" | "desc" | null }>({ column: "jobTitleName", direction: "asc" });
  const pageSize = 10;

  // ── Debounce Search ────────────────────────────────
  useEffect(() => {
      setPage(1);
      setCursor(undefined);
      cursorHistory.current = [];
      setFocusedIndex(-1);
      focusedIndexRef.current = -1;
  }, [debouncedSearch]);

  const { hasPermission } = useRoleBasedUI();
  const canCreate = hasPermission("HR.Employee.Create");
  const canEdit = hasPermission("HR.Employee.Edit");

  const {
    isFormOpen,
    selectedItem,
    openCreate,
    openEdit,
    closeForm
  } = useCrudState<EmployeeListItemDto>();

  const { data, isLoading, error } = useQuery({
    queryKey: ["hr", "employees", { page, search: debouncedSearch, cursor }],
    queryFn: () => hrApi.getEmployees({ page, pageSize, search: debouncedSearch, cursor })
  });

  useEffect(() => {
    if (error) toast.error("تعذر تحميل بيانات الموظفين", { id: "employees" });
  }, [error]);

  const onCursorNext = useCallback(() => {
    if (data?.nextCursor) {
      cursorHistory.current.push(data.nextCursor);
      setCursor(data.nextCursor);
      setPage((p) => p + 1);
    }
  }, [data?.nextCursor]);

  const onCursorPrev = useCallback(() => {
    const prev = cursorHistory.current.pop();
    setCursor(prev ?? undefined);
    setPage((p) => Math.max(1, p - 1));
  }, []);

  const onSearchChange = useCallback((val: string) => {
    setSearch(val);
  }, []);

  const sortedData = useMemo(() => {
    if (!data?.items) return [];
    if (!sortConfig.direction || !sortConfig.column) return data.items;

    return [...data.items].sort((a, b) => {
      // Sort by jobTitleID when sorting the jobTitleName column (hierarchy order)
      const sortKey = sortConfig.column === "jobTitleName" ? "jobTitleID" : sortConfig.column;
      const valA = a[sortKey as keyof EmployeeListItemDto] ?? "";
      const valB = b[sortKey as keyof EmployeeListItemDto] ?? "";

      if (typeof valA === "string" && typeof valB === "string") {
        return sortConfig.direction === "asc" ? valA.localeCompare(valB) : valB.localeCompare(valA);
      }

      if (valA < valB) return sortConfig.direction === "asc" ? -1 : 1;
      if (valA > valB) return sortConfig.direction === "asc" ? 1 : -1;
      return 0;
    });
  }, [data, sortConfig]);

  const columns: CustomColumnDef<EmployeeListItemDto>[] = [
    {
      key: "fullName",
      header: "الموظف",
      sortable: true,
      render: (row) => (
        <div className="flex items-center gap-3 text-start">
          {row.profilePhotoPath ? (
            <img 
              src={getPhotoUrl(row.profilePhotoPath)!}  
              alt={row.fullName}
              className="w-10 h-10 rounded-xl object-cover border border-border"
              loading="lazy"
            />
          ) : (
            <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center text-primary font-bold text-sm">
              <User className="w-5 h-5 opacity-100" />
            </div>
          )}
          <div className="flex flex-col">
            <span className="font-bold text-foreground">{row.fullName}</span>
            <span className="text-[10px] sm:text-xs text-muted-foreground font-mono">{row.nationalID}</span>
          </div>
        </div>
      )
    },
    {
      key: "employeeNumber",
      header: "الرقم الوظيفي",
      sortable: true,
      render: (row) => <span className="font-mono text-xs bg-muted/50 px-2 py-1 rounded font-bold">{row.employeeNumber}</span>
    },
    {
      key: "departmentName",
      header: "الإدارة / القسم",
      render: (row) => (
        <div className="flex flex-col text-start">
          <span className="text-sm font-medium">{row.departmentName}</span>
          <span className="text-[10px] sm:text-xs text-muted-foreground">{row.sectionName || '-'}</span>
        </div>
      )
    },
    {
      key: "jobTitleName",
      header: "المسمى الوظيفي",
      sortable: true,
      accessor: (row) => row.jobTitleName
    },
    {
      key: "isActive",
      header: "الحالة",
      render: (row) => (
        <Badge variant={row.isActive ? "success" : "outline"}>
          {row.employmentStatusName}
        </Badge>
      )
    },
    {
      key: "actions",
      header: "الإجراءات",
      className: "w-20",
      render: (row) => (
        <div className="flex items-center gap-1" onClick={(e) => e.stopPropagation()}>
          <Button
            variant="ghost"
            size="icon"
            className="min-h-[44px] min-w-[44px] text-primary hover:bg-primary/10 transition-colors"
            onClick={() => navigate(`/hr/employees/${row.employeeID}`)}
            title="عرض التفاصيل"
          >
            <Eye className="h-4 w-4" />
          </Button>
          {canEdit && (
            <Button
              variant="ghost"
              size="icon"
              className="min-h-[44px] min-w-[44px] text-muted-foreground hover:bg-muted transition-colors"
              title="تعديل"
              onClick={() => openEdit(row)}
            >
              <Edit className="h-4 w-4" />
            </Button>
          )}
        </div>
      )
    }
  ];

  // ── Keyboard Navigation ────────────────────────────
  const handleSearchKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement>) => {
    const items = sortedData;
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setFocusedIndex(prev => {
        const next = prev + 1;
        const clamped = next < items.length ? next : prev;
        focusedIndexRef.current = clamped;
        return clamped;
      });
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setFocusedIndex(prev => {
        const clamped = prev > 0 ? prev - 1 : prev;
        focusedIndexRef.current = clamped;
        return clamped;
      });
    } else if (e.key === "Enter") {
      e.preventDefault();
      const idx = focusedIndexRef.current;
      if (idx >= 0 && idx < items.length) {
        navigate(`/hr/employees/${items[idx].employeeID}`);
      }
    } else if (e.key === "Escape") {
      setFocusedIndex(-1);
      focusedIndexRef.current = -1;
    }
  }, [sortedData, navigate]);

  // Scroll to focused row
  useEffect(() => {
    if (focusedIndex >= 0) {
      const row = document.querySelector(`[data-row-index="${focusedIndex}"]`)
                || document.querySelector(`[data-index="${focusedIndex}"]`);
      if (row) {
        row.scrollIntoView({ behavior: "smooth", block: "nearest" });
      }
    }
  }, [focusedIndex]);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-[60dvh]">
        <Loader text="جاري تحميل قائمة الموظفين..." />
      </div>
    );
  }

  if (error) {
    return <ErrorState message="تعذر تحميل بيانات الموظفين" />;
  }

  return (
    <CrudPageLayout
      title="إدارة الموظفين"
      description="عرض وإدارة السجلات الوظيفية والبيانات الأساسية للمنتسبين"
      createLabel="إضافة موظف جديد"
      onCreateClick={canCreate ? openCreate : undefined}
      canCreate={canCreate}
      columns={columns}
      data={sortedData}
      loading={isLoading}
      sortColumn={sortConfig.column}
      sortDirection={sortConfig.direction}
      onSort={(column, direction) => setSortConfig({ column, direction })}
      searchable
      searchInHeader
      searchPlaceholder="البحث بالاسم، الرقم الوظيفي، أو الرقم الوطني..."
      onSearchChange={onSearchChange}
      searchValue={search}
      onSearchKeyDown={handleSearchKeyDown}
      searchInputRef={searchInputRef}
      focusedRowIndex={focusedIndex}
      pagination={{
        page: page,
        pageSize,
        total: data?.totalCount || 0,
        onPageChange: (p) => { setPage(p); setCursor(undefined); cursorHistory.current = []; },
        cursor,
        hasMore: data?.hasMore,
        onCursorNext: cursor !== undefined ? onCursorNext : undefined,
        onCursorPrev: cursor !== undefined ? onCursorPrev : undefined,
      }}
      onRowClick={(row) => navigate(`/hr/employees/${row.employeeID}`)}
      emptyMessage="لم يتم العثور على موظفين يطابقون معايير البحث"
      headerActions={
        <Button variant="outline" className="gap-2 border-primary bg-primary/5 hover:bg-primary/10">
          <Filter className="h-4 w-4" />
          تصفية متقدمة
        </Button>
      }
    >
      <CreateEmployeeDialog
        open={isFormOpen}
        employeeId={selectedItem?.employeeID}
        onOpenChange={(open) => !open && closeForm()}
        onSaved={() => {
          setPage(1);
        }}
      />
    </CrudPageLayout>
  );
}

import { useQuery } from "@tanstack/react-query";
import {
  CalendarDays,
  Clock,
  Filter,
  LogIn,
  LogOut,
  MapPin} from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";

import type { AttendanceEventDto } from "@/api/hr";
import { hrApi } from "@/api/hr";
import { AttendanceDialog } from "@/components/domain/hr/AttendanceDialog";
import {
  Badge,
  Button,
  CrudPageLayout,
  type CustomColumnDef,
  DateInput,
  ErrorState,
  StatCard} from "@/components/ui";
import { ATTENDANCE_TYPE } from "@/constants";
import { formatDate } from "@/lib/utils";

/**
 * صفحة متابعة سجلات الحضور والانصراف - وحدة الموارد البشرية
 */
export function HrAttendancePage() {
  const [page, setPage] = useState(1);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [focusedIndex, setFocusedIndex] = useState(-1);
  const focusedIndexRef = useRef(-1);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const pageSize = 20;

  // جلب السجلات
  const { data, isLoading, error } = useQuery({
    queryKey: ["hr", "attendance", page, selectedDate],
    queryFn: () => hrApi.getAttendance({
      page,
      pageSize,
      fromDate: selectedDate,
      toDate: selectedDate
    })
  });

  useEffect(() => {
    if (error) toast.error("تعذر تحميل بيانات الحضور", { id: "hr-attendance" });
  }, [error]);

  if (error) {
    return <ErrorState message="تعذر تحميل بيانات الحضور" />;
  }

  // جلب الإحصائيات اليومية
  const { data: stats } = useQuery({
    queryKey: ["hr", "attendance-stats", selectedDate],
    queryFn: () => hrApi.getDailyStats(selectedDate)
  });

  const columns = useMemo<CustomColumnDef<AttendanceEventDto>[]>(() => [
    {
      key: "employeeFullName",
      header: "الموظف",
      render: (r) => (
        <div className="flex items-center gap-2 text-start">
          <div className="h-8 w-8 rounded-full bg-primary/10 flex items-center justify-center text-[10px] sm:text-xs font-bold text-primary shrink-0">
            {r.employeeFullName.split(' ').map(n => n[0]).join('').substring(0, 2)}
          </div>
          <div className="flex flex-col">
            <span className="text-sm font-bold">{r.employeeFullName}</span>
            <span className="text-[10px] sm:text-xs text-muted-foreground font-mono">{r.employeeNumber}</span>
          </div>
        </div>
      )
    },
    {
      key: "eventDate",
      header: "التاريخ",
      render: (r) => <span className="font-mono text-xs">{formatDate(r.eventDate)}</span>
    },
    {
      key: "eventTime",
      header: "الوقت",
      render: (r) => <span className="font-mono font-bold text-primary">{r.eventTime ? r.eventTime.substring(0, 5) : "--:--"}</span>
    },
    {
      key: "eventType",
      header: "نوع الحركة",
      render: (r) => {
        const isCheckIn = r.eventType === ATTENDANCE_TYPE.CHECK_IN;
        return (
          <Badge variant={isCheckIn ? "success" : "warning"} className="gap-1.5 px-2 h-6 font-black">
            {isCheckIn ? <LogIn className="h-3.5 w-3.5" /> : <LogOut className="h-3.5 w-3.5" />}
            {isCheckIn ? "حضور" : "انصراف"}
          </Badge>
        );
      }
    },
    {
      key: "location",
      header: "الموقع",
      render: (r) => (
        <div className="flex items-center gap-1 text-xs text-muted-foreground justify-center">
          <MapPin className="h-3 w-3" />
          {r.location || "غير محدد"}
        </div>
      )
    },
    {
      key: "isManualEntry",
      header: "المصدر",
      render: (r) => (
        <Badge variant="outline" className="text-[10px] sm:text-xs font-medium h-5">
          {r.isManualEntry ? "إدخال يدوي" : "جهاز البصمة"}
        </Badge>
      )
    }
  ], []);

  // ── Keyboard Navigation ────────────────────────────
  const handleSearchKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement>) => {
    const items = data?.items || [];
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setFocusedIndex(prev => {
        const next = prev + 1;
        const clamped = next < items.length ? next : prev;
        focusedIndexRef.current = clamped;
        return clamped;
      });
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setFocusedIndex(prev => {
        const clamped = prev > 0 ? prev - 1 : prev;
        focusedIndexRef.current = clamped;
        return clamped;
      });
    } else if (e.key === "Escape") {
      setFocusedIndex(-1);
      focusedIndexRef.current = -1;
    }
  }, [data?.items]);

  // Scroll to focused row
  useEffect(() => {
    if (focusedIndex >= 0) {
      const row = document.querySelector(`[data-row-index="${focusedIndex}"]`)
                || document.querySelector(`[data-index="${focusedIndex}"]`);
      if (row) {
        row.scrollIntoView({ behavior: "smooth", block: "nearest" });
      }
    }
  }, [focusedIndex]);

  return (
    <CrudPageLayout
      title="سجلات الحضور والانصراف"
      description="متابعة سجلات حضور وانصراف الموظفين وإحصائيات الالتزام بالدوام اليومي"
      createLabel="تسجيل يدوي"
      onCreateClick={() => setIsDialogOpen(true)}
      columns={columns}
      data={data?.items || []}
      loading={isLoading}
      searchable
      searchInHeader
      searchInputRef={searchInputRef}
      onSearchKeyDown={handleSearchKeyDown}
      focusedRowIndex={focusedIndex}
      pagination={{
        page: page,
        pageSize,
        total: data?.totalCount || 0,
        onPageChange: (p) => setPage(p)
      }}
      headerActions={
        <div className="flex items-center gap-2 me-2 flex-wrap">
          <DateInput
            className="h-9 text-xs w-full sm:w-40 font-mono bg-background"
            value={selectedDate}
            onChange={(val) => val && setSelectedDate(val)}
          />
          <Button variant="outline" size="sm" className="gap-2 text-xs h-11 ">
            <Filter className="h-3.5 w-3.5" /> تصفية
          </Button>
        </div>
      }
    >
      {/* Daily Stats */}
      <div className="grid grid-cols-2 sm:grid-cols-2 lg:grid-cols-4 gap-2 sm:gap-4 mb-6">
        <StatCard
          title="الحضور اليوم"
          value={stats?.presentCount || 0}
          description={`${stats?.presencePercentage.toFixed(1) || 0}% من إجمالي القوة`}
          icon={<LogIn className="h-4 w-4" />}
          variant="emerald"
        />
        <StatCard
          title="حالات التأخير"
          value={stats?.lateCount || 0}
          description="بعد الساعة 08:15 ص"
          icon={<Clock className="h-4 w-4" />}
          variant="rose"
        />
        <StatCard
          title="الغياب اليوم"
          value={stats?.absentCount || 0}
          description={`من أصل ${stats?.totalEmployees || 0} موظف`}
          icon={<CalendarDays className="h-4 w-4" />}
          variant="blue"
        />
        <StatCard
          title="مهام خارجية"
          value={stats?.externalTaskCount || 0}
          description="خارج المقر الرسمي"
          icon={<MapPin className="h-4 w-4" />}
          variant="orange"
        />
      </div>

      <AttendanceDialog
        open={isDialogOpen}
        onOpenChange={setIsDialogOpen}
        onSaved={() => setPage(1)}
      />
    </CrudPageLayout>
  );
}

import { useQuery } from "@tanstack/react-query";
import { Download, FileText, User } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";

import { hrApi, type HrGlobalDocumentDto } from "@/api/hr";
import { 
  Badge,
  Button,
  type CustomColumnDef,
  ErrorState,
  Text} from "@/components/ui";
import { CrudPageLayout } from "@/components/ui/CrudPageLayout";
import { getDocumentUrl } from "@/lib/utils";


/**
 * صفحة استعراض وثائق الموظفين الشاملة
 */
export function HrDocumentsPage() {
  const [page, setPage] = useState(1);
  const [pageSize] = useState(10);
  const [search, setSearch] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  const [focusedIndex, setFocusedIndex] = useState(-1);
  const focusedIndexRef = useRef(-1);
  const searchInputRef = useRef<HTMLInputElement>(null);

  const { data, isLoading, error } = useQuery({
    queryKey: ["global-employee-documents", page, pageSize, debouncedSearch],
    queryFn: () => hrApi.getGlobalDocuments({ page, pageSize, search: debouncedSearch }),
  });

  const handleDownload = (doc: HrGlobalDocumentDto) => {
    if (doc.filePath) {
      window.open(getDocumentUrl(doc.filePath) ?? "", "_blank");
    }
  };

  const columns = useMemo<CustomColumnDef<HrGlobalDocumentDto>[]>(() => [
    {
      key: "employeeInfo",
      header: "الموظف",
      render: (row) => (
        <div className="flex items-center gap-3">
          <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-primary/10 text-primary">
            <User className="h-5 w-5" />
          </div>
          <div>
            <p className="text-sm font-semibold text-foreground">{row.employeeFullName}</p>
            <Text variant="caption">{row.employeeNumber}</Text>
          </div>
        </div>
      ),
    },
    {
      key: "fileName",
      header: "اسم الملف",
      render: (row) => (
        <div className="flex items-center gap-2">
            <FileText className="h-4 w-4 text-muted-primary" />
            <span className="font-medium text-sm text-foreground">{row.fileName}</span>
        </div>
      ),
    },
    {
      key: "documentType",
      header: "التصنيف",
      render: (row) => (
        <Badge variant="outline" className="bg-primary/5 text-primary border-primary">
          {row.documentTypeName}
        </Badge>
      ),
    },
    {
       key: "fileSize",
       header: "الحجم",
       render: (row) => (
          <span className="text-sm text-muted-foreground" dir="ltr">
            {(row.fileSize / 1024 / 1024).toFixed(2)} MB
          </span>
       )
    },
    {
      key: "createdAt",
      header: "تاريخ الرفع",
      render: (row) => (
        <span className="text-sm text-muted-foreground whitespace-normal sm:whitespace-nowrap">
          {new Date(row.createdAt).toLocaleDateString('ar-EG', { year: 'numeric', month: 'long', day: 'numeric' })}
        </span>
      ),
    },
    {
      key: "uploadedBy",
      header: "بواسطة",
      render: (row) => (
        <span className="text-sm text-muted-foreground">
          {row.uploadedByUser || "غير محدد"}
        </span>
      ),
    },
    {
      key: "actions",
      header: "",
      render: (row) => (
        <Button 
            variant="ghost" 
            size="sm" 
            onClick={() => handleDownload(row)}
            className="text-primary hover:text-primary hover:bg-primary/10"
            disabled={!row.filePath}
        >
            <Download className="h-4 w-4 ms-1" />
            تحميل
        </Button>
      ),
    },
  ], []);

  useEffect(() => {
    if (error) toast.error("تعذر تحميل المستندات", { id: "hr-documents" });
  }, [error]);

  if (error) {
    return <ErrorState message="تعذر تحميل المستندات" />;
  }

  const searchTimeoutRef = useRef<ReturnType<typeof setTimeout>>(undefined);

  // Clean up search timeout on unmount
  useEffect(() => {
    return () => {
      if (searchTimeoutRef.current) {
        clearTimeout(searchTimeoutRef.current);
      }
    };
  }, []);

  const handleSearch = (term: string) => {
    setSearch(term);
    if (searchTimeoutRef.current) clearTimeout(searchTimeoutRef.current);
    searchTimeoutRef.current = setTimeout(() => {
        setDebouncedSearch(term);
        setPage(1);
        setFocusedIndex(-1);
        focusedIndexRef.current = -1;
    }, 500);
  };

  // ── Keyboard Navigation ────────────────────────────
  const handleSearchKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement>) => {
    const items = data?.items || [];
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setFocusedIndex(prev => {
        const next = prev + 1;
        const clamped = next < items.length ? next : prev;
        focusedIndexRef.current = clamped;
        return clamped;
      });
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setFocusedIndex(prev => {
        const clamped = prev > 0 ? prev - 1 : prev;
        focusedIndexRef.current = clamped;
        return clamped;
      });
    } else if (e.key === "Enter") {
      e.preventDefault();
      const idx = focusedIndexRef.current;
      if (idx >= 0 && idx < items.length) {
        handleDownload(items[idx]);
      }
    } else if (e.key === "Escape") {
      setFocusedIndex(-1);
      focusedIndexRef.current = -1;
    }
  }, [data?.items]);

  // Scroll to focused row
  useEffect(() => {
    if (focusedIndex >= 0) {
      const row = document.querySelector(`[data-row-index="${focusedIndex}"]`)
                || document.querySelector(`[data-index="${focusedIndex}"]`);
      if (row) {
        row.scrollIntoView({ behavior: "smooth", block: "nearest" });
      }
    }
  }, [focusedIndex]);

  return (
    <CrudPageLayout
      title="مستندات الموظفين"
      description="استعراض وإدارة الأرشيف الإلكتروني الشامل لجميع الموظفين"
      icon={<FileText className="h-6 w-6" />}
      columns={columns}
      data={Array.isArray(data?.items) ? data.items : []}
      loading={isLoading}
      searchable
      searchInHeader
      searchPlaceholder="ابحث باسم الموظف، الرقم الوظيفي، أو اسم الملف..."
      onSearchChange={handleSearch}
      searchValue={search}
      onSearchKeyDown={handleSearchKeyDown}
      searchInputRef={searchInputRef}
      focusedRowIndex={focusedIndex}
      pagination={{
          page,
          pageSize,
          total: data?.totalCount || 0,
          onPageChange: setPage,
      }}
      canCreate={false}
    />
  );
}

import { useQuery } from "@tanstack/react-query";
import {
  Calendar,
  CalendarDays,
  CheckCircle2,
  Clock,
  Filter,
  type LucideIcon,
  XCircle} from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";

import type { LeaveRequestListItemDto } from "@/api/hr";
import { hrApi } from "@/api/hr";
import { LeaveRequestDialog } from "@/components/domain/hr/LeaveRequestDialog";
import {
  Badge,
  Button,
  CrudPageLayout,
  type CustomColumnDef,
  ErrorState,
  NativeSelect,
  StatCard} from "@/components/ui";
import { LEAVE_STATUS } from "@/constants";
import { useApiMutation } from "@/hooks";
import { useDebouncedSearch } from "@/hooks/useDebouncedSearch";
import { formatDate } from "@/lib/utils";

/**
 * صفحة إدارة طلبات الإجازات - وحدة الموارد البشرية
 */
export function HrLeavesPage() {
  const { searchTerm: search, setSearchTerm: setSearch, debouncedValue: debouncedSearch } = useDebouncedSearch();
  const [focusedIndex, setFocusedIndex] = useState(-1);
  const focusedIndexRef = useRef(-1);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const [status, setStatus] = useState<string>("");
  const [page, setPage] = useState(1);
  const pageSize = 15;
  const [isModalOpen, setIsModalOpen] = useState(false);

  // ── Debounce Search ────────────────────────────────
  useEffect(() => {
      setPage(1);
      setFocusedIndex(-1);
      focusedIndexRef.current = -1;
  }, [debouncedSearch]);

  // جلب الطلبات مع البحث والفلترة
  const { data, isLoading, error } = useQuery({
    queryKey: ["hr", "leaves", page, debouncedSearch, status],
    queryFn: () => hrApi.getLeaveRequests({
      page,
      pageSize,
      search: debouncedSearch || undefined,
      status: status || undefined
    })
  });

  // جلب الإحصائيات
  const { data: stats } = useQuery({
    queryKey: ["hr", "leaves-stats"],
    queryFn: () => hrApi.getLeaveStats()
  });

  useEffect(() => {
    if (error) toast.error("تعذر تحميل بيانات الإجازات", { id: "hr-leaves" });
  }, [error]);

  if (error) {
    return <ErrorState message="تعذر تحميل بيانات الإجازات" />;
  }

  // معالجة الطلب (قبول/رفض)
  const processMutation = useApiMutation(({ id, status }: { id: number, status: "Approved" | "Rejected" }) =>
    hrApi.processLeave(id, { status, notes: "تمت المعالجة عبر صفحة الإدارة" }), {
    successMessage: "تم تحديث حالة الطلب بنجاح",
    invalidateKeys: [["hr", "leaves"], ["hr", "leaves-stats"]]
  });

  const columns = useMemo<CustomColumnDef<LeaveRequestListItemDto>[]>(() => [
    {
      key: "employeeFullName",
      header: "الموظف",
      render: (r) => (
        <div className="flex items-center gap-2 text-start">
          <div className="h-8 w-8 rounded-full bg-primary/10 flex items-center justify-center text-[10px] sm:text-xs font-bold text-primary">
            {r.employeeFullName.split(' ').map((n: string) => n[0]).join('').substring(0, 2)}
          </div>
          <div className="flex flex-col">
            <span className="text-sm font-medium">{r.employeeFullName}</span>
            <span className="text-[10px] sm:text-xs text-muted-foreground font-mono">{r.employeeNumber}</span>
          </div>
        </div>
      )
    },
    {
      key: "leaveTypeName",
      header: "نوع الإجازة",
      render: (r) => <Badge variant="outline" className="font-bold">{r.leaveTypeName}</Badge>
    },
    {
      key: "startDate",
      header: "الفترة الزمنية",
      render: (r) => (
        <div className="text-[10px] sm:text-xs space-y-0.5 text-start font-mono">
          <div className="flex items-center gap-1 text-muted-foreground">
            <Calendar className="h-3 w-3" />
            <span>من: {formatDate(r.startDate)}</span>
          </div>
          <div className="flex items-center gap-1 text-muted-foreground">
            <Calendar className="h-3 w-3" />
            <span>إلى: {formatDate(r.endDate)}</span>
          </div>
        </div>
      )
    },
    { key: "requestedDays", header: "الأيام", render: (r) => <span className="font-bold font-mono">{r.requestedDays}</span> },
    {
      key: "status",
      header: "الحالة",
      render: (r) => {
        const statusMap: Record<string, { label: string, variant: "warning" | "success" | "danger" | "outline", icon: LucideIcon }> = {
          "Pending": { label: "قيد الانتظار", variant: "warning", icon: Clock },
          "Approved": { label: "معتمدة", variant: "success", icon: CheckCircle2 },
          "Rejected": { label: "مرفوضة", variant: "danger", icon: XCircle },
        };
        const config = statusMap[r.status] || { label: r.status, variant: "outline", icon: Clock };
        const Icon = config.icon;
        return (
          <div className="flex flex-col items-center gap-1">
            <Badge variant={config.variant} className="gap-1 px-2 h-6 font-black">
              <Icon className="h-3 w-3" />
              {config.label}
            </Badge>
          </div>
        );
      }
    },
    {
      key: "actions",
      header: "إجراءات الإدارة",
      render: (r) => (
        <div className="flex gap-1 justify-center">
          {r.status === LEAVE_STATUS.PENDING && (
            <>
              <Button
                variant="ghost"
                size="icon"
                className="min-h-[44px] min-w-[44px] text-emerald-600 hover:bg-emerald-50"
                onClick={() => processMutation.mutate({ id: r.leaveRequestID, status: "Approved" })}
                loading={processMutation.isPending && processMutation.variables?.id === r.leaveRequestID}
                title="اعتماد الإجازة"
              >
                <CheckCircle2 className="h-4 w-4" />
              </Button>
              <Button
                variant="ghost"
                size="icon"
                className="min-h-[44px] min-w-[44px] text-red-600 hover:bg-red-50"
                onClick={() => processMutation.mutate({ id: r.leaveRequestID, status: "Rejected" })}
                loading={processMutation.isPending && processMutation.variables?.id === r.leaveRequestID}
                title="رفض الإجازة"
              >
                <XCircle className="h-4 w-4" />
              </Button>
            </>
          )}
          <Button variant="ghost" size="icon" className="min-h-[44px] min-w-[44px] text-muted-foreground hover:bg-muted" title="تصفية الموظف">
            <Filter className="h-4 w-4" />
          </Button>
        </div>
      )
    }
  ], [processMutation]);

  // ── Keyboard Navigation ────────────────────────────
  const handleSearchKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement>) => {
    const items = data?.items || [];
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setFocusedIndex(prev => {
        const next = prev + 1;
        const clamped = next < items.length ? next : prev;
        focusedIndexRef.current = clamped;
        return clamped;
      });
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setFocusedIndex(prev => {
        const clamped = prev > 0 ? prev - 1 : prev;
        focusedIndexRef.current = clamped;
        return clamped;
      });
    } else if (e.key === "Enter") {
      e.preventDefault();
      const idx = focusedIndexRef.current;
      if (idx >= 0 && idx < items.length) {
        const row = items[idx];
        if (row.status === LEAVE_STATUS.PENDING) {
          processMutation.mutate({ id: row.leaveRequestID, status: "Approved" });
        }
      }
    } else if (e.key === "Escape") {
      setFocusedIndex(-1);
      focusedIndexRef.current = -1;
    }
  }, [data?.items, processMutation]);

  // Scroll to focused row
  useEffect(() => {
    if (focusedIndex >= 0) {
      const row = document.querySelector(`[data-row-index="${focusedIndex}"]`)
                || document.querySelector(`[data-index="${focusedIndex}"]`);
      if (row) {
        row.scrollIntoView({ behavior: "smooth", block: "nearest" });
      }
    }
  }, [focusedIndex]);

  return (
    <CrudPageLayout
      title="طلبات الإجازات"
      description="إدارة ومتابعة طلبات الإجازات السنوية والمرضية والاضطرارية للمنتسبين"
      createLabel="تقديم طلب إجازة"
      onCreateClick={() => setIsModalOpen(true)}
      columns={columns}
      data={data?.items || []}
      loading={isLoading}
      searchable
      searchInHeader
      onSearchChange={(val) => setSearch(val)}
      searchValue={search}
      onSearchKeyDown={handleSearchKeyDown}
      searchInputRef={searchInputRef}
      focusedRowIndex={focusedIndex}
      pagination={{
        page: page,
        pageSize,
        total: data?.totalCount || 0,
        onPageChange: (p) => setPage(p)
      }} headerActions={
        <div className="flex items-center gap-2 me-2 flex-wrap">
          <NativeSelect
            value={status}
            onChange={(val) => { setStatus(val); setPage(1); }}
            options={[
              { label: "كل الحالات", value: "" },
              { label: "قيد الانتظار", value: LEAVE_STATUS.PENDING },
              { label: "معتمدة", value: LEAVE_STATUS.APPROVED },
              { label: "مرفوضة", value: LEAVE_STATUS.REJECTED },
            ]}
            placeholder="فلترة بالحالة"
            className="w-full sm:w-40"
          />
        </div>
      }
    >
      {/* Quick Stats */}
      <div className="grid grid-cols-2 md:grid-cols-3 gap-2 sm:gap-4 mb-6">
        <StatCard title="بانتظار الموافقة" value={stats?.pendingCount || 0} icon={<Clock className="h-4 w-4" />} variant="orange" />
        <StatCard title="المعتمدة هذا الشهر" value={stats?.approvedThisMonthCount || 0} icon={<CheckCircle2 className="h-4 w-4" />} variant="emerald" />
        <StatCard title="إجمالي الطلبات (العام)" value={stats?.totalThisYearCount || 0} icon={<CalendarDays className="h-4 w-4" />} variant="blue" />
      </div>

      <LeaveRequestDialog
        open={isModalOpen}
        onOpenChange={(open) => !open && setIsModalOpen(false)}
      />
    </CrudPageLayout>
  );
}

import { useQuery } from "@tanstack/react-query";
import {
  Activity,
  Briefcase,
  Building2,
  Edit,
  Layers} from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { toast } from "sonner";

import type { DepartmentDto, EmploymentStatusDto,JobTitleDto, SectionDto } from "@/api/hr";
import { hrApi } from "@/api/hr";
import { DepartmentDialog } from "@/components/domain/hr/DepartmentDialog";
import { JobTitleDialog } from "@/components/domain/hr/JobTitleDialog";
import { SectionDialog } from "@/components/domain/hr/SectionDialog";
import {
  Badge,
  Button,
  CrudPageLayout,
  type CustomColumnDef,
  ErrorState,
  PageLayout,
  RecordStateBadge,
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger} from "@/components/ui";

/**
 * صفحة البيانات المرجعية والهيكل التنظيمي - وحدة الموارد البشرية
 */
export function HrReferenceDataPage() {
  const [searchParams, setSearchParams] = useSearchParams();
  const [activeTab, setActiveTab] = useState(searchParams.get("tab") || "departments");

  // حوارات الإدارة
  const [isDeptModalOpen, setIsDeptModalOpen] = useState(false);
  const [selectedDept, setSelectedDept] = useState<DepartmentDto | null>(null);

  // حوارات الأقسام
  const [isSecModalOpen, setIsSecModalOpen] = useState(false);
  const [selectedSec, setSelectedSec] = useState<SectionDto | null>(null);

  // حوارات المسميات الوظيفية
  const [isJobModalOpen, setIsJobModalOpen] = useState(false);
  const [selectedJob, setSelectedJob] = useState<JobTitleDto | null>(null);

  return (
    <PageLayout>
      {/* Header */}


      <Tabs value={activeTab} onValueChange={(v) => { setActiveTab(v); setSearchParams((p) => { p.set("tab", v); return p; }, { replace: true }); }} className="space-y-6">
        <div className="flex items-center w-full overflow-x-auto pb-1 mb-4 scrollbar-hide">
          <TabsList className="bg-muted/50 p-1 h-auto flex gap-1">
            <TabsTrigger value="departments" className="gap-2 px-6 py-2.5">
              <Building2 className="h-4 w-4" /> الإدارات
            </TabsTrigger>
            <TabsTrigger value="sections" className="gap-2 px-6 py-2.5">
              <Layers className="h-4 w-4" /> الأقسام
            </TabsTrigger>
            <TabsTrigger value="job-titles" className="gap-2 px-6 py-2.5">
              <Briefcase className="h-4 w-4" /> المسميات الوظيفية
            </TabsTrigger>
            <TabsTrigger value="status" className="gap-2 px-6 py-2.5">
              <Activity className="h-4 w-4" /> حالات الخدمة
            </TabsTrigger>
          </TabsList>
        </div>

        <TabsContent value="departments" className="animate-in fade-in duration-300 outline-none">
          <DepartmentsTab
            onEdit={(dept) => {
              setSelectedDept(dept);
              setIsDeptModalOpen(true);
            }}
            onAdd={() => {
              setSelectedDept(null);
              setIsDeptModalOpen(true);
            }}
          />
        </TabsContent>

        <TabsContent value="sections" className="animate-in fade-in duration-300 outline-none">
          <SectionsTab
            onEdit={(sec) => {
              setSelectedSec(sec);
              setIsSecModalOpen(true);
            }}
            onAdd={() => {
              setSelectedSec(null);
              setIsSecModalOpen(true);
            }}
          />
        </TabsContent>

        <TabsContent value="job-titles" className="animate-in fade-in duration-300 outline-none">
          <JobTitlesTab
            onEdit={(job) => {
              setSelectedJob(job);
              setIsJobModalOpen(true);
            }}
            onAdd={() => {
              setSelectedJob(null);
              setIsJobModalOpen(true);
            }}
          />
        </TabsContent>

        <TabsContent value="status" className="animate-in fade-in duration-300 outline-none">
          <EmploymentStatusesTab />
        </TabsContent>
      </Tabs>

      <DepartmentDialog
        open={isDeptModalOpen}
        onClose={() => setIsDeptModalOpen(false)}
        initialData={selectedDept}
      />

      <SectionDialog
        open={isSecModalOpen}
        onClose={() => setIsSecModalOpen(false)}
        initialData={selectedSec}
      />

      <JobTitleDialog
        open={isJobModalOpen}
        onClose={() => setIsJobModalOpen(false)}
        initialData={selectedJob}
    />
  </PageLayout>
  );
}

// ─── Sub-Tabs (Internal Components) ────────────────────

function DepartmentsTab({ onEdit, onAdd }: { onEdit: (d: DepartmentDto) => void, onAdd: () => void }) {
  const { data, isLoading, error } = useQuery({
    queryKey: ["hr", "departments"],
    queryFn: () => hrApi.getDepartments()
  });

  useEffect(() => {
    if (error) toast.error("تعذر تحميل البيانات المرجعية", { id: "hr-reference-data" });
  }, [error]);

  if (error) {
    return <ErrorState message="تعذر تحميل البيانات المرجعية" />;
  }

  const columns = useMemo<CustomColumnDef<DepartmentDto>[]>(() => [
    {
      key: "code",
      header: "الكود",
      render: (r) => <span className="font-mono text-xs font-black text-primary bg-primary/5 px-2 py-1 rounded-md border border-primary">{r.code}</span>
    },
    { key: "name", header: "اسم الإدارة", render: (r) => <span className="font-bold text-foreground">{r.name}</span> },
    { key: "employeesCount", header: "عدد الموظفين", render: (r) => <span className="font-mono font-bold">{r.employeesCount}</span> },
