            <SelectTrigger className="w-40">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="asset">جرد الأصول</SelectItem>
              <SelectItem value="simple">جرد المخزون</SelectItem>
            </SelectContent>
          </Select>

          <Select value={selectedFiscalYearId} onValueChange={setSelectedFiscalYearId}>
            <SelectTrigger className="w-56">
              <SelectValue placeholder="السنة المالية" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="current">السنة المالية الحالية</SelectItem>
              {fiscalYears?.map((year) => (
                <SelectItem key={year.fiscalYearID} value={String(year.fiscalYearID)}>
                  {year.yearName} {year.isClosed ? "(مغلقة)" : ""}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {stocktake && (
          <Badge variant={stocktake.status === "Completed" ? "success" : stocktake.status === "Adjusted" ? "outline" : "secondary"}>
            {stocktake.status === "InProgress" ? "قيد التنفيذ" : stocktake.status === "Completed" ? "مكتمل" : "تمت التسوية"}
          </Badge>
        )}
      </div>

      {/* ملخص */}
      {stocktake && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {stocktakeType === "asset" ? (
            <>
              <Card>
                <CardContent className="pt-4">
                  <p className="text-sm text-muted-foreground">إجمالي الأصول</p>
                  <p className="text-base md:text-lg lg:text-xl font-bold">{(stocktake as any).summary?.totalAssets || 0}</p>
                </CardContent>
              </Card>
              <Card>
                <CardContent className="pt-4">
                  <p className="text-sm text-muted-foreground">موجودة</p>
                  <p className="text-base md:text-lg lg:text-xl font-bold text-green-600">{(stocktake as any).summary?.presentAssets || 0}</p>
                </CardContent>
              </Card>
              <Card>
                <CardContent className="pt-4">
                  <p className="text-sm text-muted-foreground">مفقودة</p>
                  <p className="text-base md:text-lg lg:text-xl font-bold text-red-600">{(stocktake as any).summary?.missingAssets || 0}</p>
                </CardContent>
              </Card>
              <Card>
                <CardContent className="pt-4">
                  <p className="text-sm text-muted-foreground">قيمة الدفتر</p>
                  <p className="text-base md:text-lg lg:text-xl font-bold">{(stocktake as any).summary?.totalBookValue?.toLocaleString() || 0}</p>
                </CardContent>
              </Card>
            </>
          ) : (
            <>
              <Card>
                <CardContent className="pt-4">
                  <p className="text-sm text-muted-foreground">إجمالي الأصناف</p>
                  <p className="text-base md:text-lg lg:text-xl font-bold">{(stocktake as any).totalItems || 0}</p>
                </CardContent>
              </Card>
              <Card>
                <CardContent className="pt-4">
                  <p className="text-sm text-muted-foreground">أصناف بها فروق</p>
                  <p className="text-base md:text-lg lg:text-xl font-bold text-amber-600">{(stocktake as any).itemsWithVariance || 0}</p>
                </CardContent>
              </Card>
              <Card>
                <CardContent className="pt-4">
                  <p className="text-sm text-muted-foreground">قيمة الفروق</p>
                  <p className="text-base md:text-lg lg:text-xl font-bold text-red-600">{(stocktake as any).totalVarianceValue?.toLocaleString() || 0}</p>
                </CardContent>
              </Card>
              <Card>
                <CardContent className="pt-4">
                  <p className="text-sm text-muted-foreground">القيد المحاسبي</p>
                  <p className="text-base md:text-lg lg:text-xl font-bold">{(stocktake as any).journalEntryNumber || "-"}</p>
                </CardContent>
              </Card>
            </>
          )}
        </div>
      )}

      {/* جدول */}
      {stocktake && stocktake.lines?.length > 0 && (
        <DataTable
          columns={stocktakeType === "asset" ? assetColumns : simpleColumns}
          data={stocktake.lines}
          loading={isLoading}
          emptyMessage="لا يوجد جرد لهذه السنة المالية"
          rowKey={(row) => row.stocktakeLineID || row.lineID}
        />
      )}

      {!isLoading && (!stocktake || !stocktake.lines || stocktake.lines.length === 0) && (
        <Card>
          <CardContent className="py-12 text-center">
            <Package className="w-12 h-12 text-muted-foreground mx-auto mb-3" />
            <p className="text-muted-foreground">لا يوجد جرد لهذه السنة المالية</p>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

// ═══════════════════════════════════════
// الصفحة الرئيسية
// ═══════════════════════════════════════

export function InventoryDashboardPage() {
  const [activeTab, setActiveTab] = useState("items");

  const { data: items = [] } = useQuery({
    queryKey: ["inventory-items"],
    queryFn: () => itemApi.getAll(),
  });

  const { data: assets = [] } = useQuery({
    queryKey: ["fixed-assets"],
    queryFn: () => fixedAssetApi.getAll(),
  });

  const lowStockCount = items.filter(i => i.quantity <= i.minimumQuantity && i.minimumQuantity > 0).length;

  return (
    <div className="space-y-6" dir="rtl">
      {/* العنوان */}
      <div>
        <Heading level="h1" className="text-lg md:text-xl lg:text-2xl font-bold">إدارة المخزون والأصول</Heading>
        <p className="text-muted-foreground">إدارة أصول ومنقولات المؤسسة والجرد</p>
      </div>

      {/* البطاقات الإحصائية */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <StatCard title="إجمالي الأصناف" value={items.length} icon={<Package className="w-5 h-5" />} variant="blue" />
        <StatCard title="تحت الحد الأدنى" value={lowStockCount} icon={<AlertTriangle className="w-5 h-5" />} variant={lowStockCount > 0 ? "warning" : "default"} />
        <StatCard title="الأصول الثابتة" value={assets.length} icon={<Building2 className="w-5 h-5" />} variant="emerald" />
        <StatCard title="العهدة النشطة" value="-" icon={<ClipboardList className="w-5 h-5" />} variant="blue" />
      </div>

      {/* روابط سريعة */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        <Link to="/inventory/items" className="flex items-center gap-3 rounded-xl border bg-background hover:bg-muted/50 px-4 py-3 transition-colors">
          <Package className="w-5 h-5 text-primary shrink-0" />
          <div>
            <div className="font-medium text-sm">إدارة الأصناف</div>
            <div className="text-xs text-muted-foreground">إضافة/تعديل/حذف</div>
          </div>
        </Link>
        <Link to="/assets/fixed" className="flex items-center gap-3 rounded-xl border bg-background hover:bg-muted/50 px-4 py-3 transition-colors">
          <Building2 className="w-5 h-5 text-primary shrink-0" />
          <div>
            <div className="font-medium text-sm">إدارة الأصول الثابتة</div>
            <div className="text-xs text-muted-foreground">قائمة الأصول</div>
          </div>
        </Link>
        <Link to="/assets/categories" className="flex items-center gap-3 rounded-xl border bg-background hover:bg-muted/50 px-4 py-3 transition-colors">
          <ListTree className="w-5 h-5 text-primary shrink-0" />
          <div>
            <div className="font-medium text-sm">تصنيفات الأصول</div>
            <div className="text-xs text-muted-foreground">إدارة التصنيفات</div>
          </div>
        </Link>
        <Link to="/assets/depreciation-run" className="flex items-center gap-3 rounded-xl border bg-background hover:bg-muted/50 px-4 py-3 transition-colors">
          <Calculator className="w-5 h-5 text-primary shrink-0" />
          <div>
            <div className="font-medium text-sm">الإهلاك</div>
            <div className="text-xs text-muted-foreground">حساب وترحيل الإهلاك</div>
          </div>
        </Link>
      </div>

      {/* التبويبات */}
      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList className="w-full justify-start">
          <TabsTrigger value="items">الأصناف</TabsTrigger>
          <TabsTrigger value="assets">الأصول الثابتة</TabsTrigger>
          <TabsTrigger value="stocktake">الجرد</TabsTrigger>
          <TabsTrigger value="custody">العهدة</TabsTrigger>
          <TabsTrigger value="transactions">الحركات</TabsTrigger>
        </TabsList>

        <TabsContent value="items">
          <ItemsTab />
        </TabsContent>

        <TabsContent value="assets">
          <FixedAssetsTab />
        </TabsContent>

        <TabsContent value="stocktake">
          <StocktakeTab />
        </TabsContent>

        <TabsContent value="custody">
          <Card>
            <CardContent className="pt-6">
              <div className="flex items-center gap-4 mb-4">
                <div className="w-12 h-12 rounded-xl bg-primary/10 flex items-center justify-center">
                  <ClipboardList className="w-6 h-6 text-primary" />
                </div>
                <div>
                  <Heading level="h3" className="font-medium">إدارة العهد الشخصية</Heading>
                  <p className="text-sm text-muted-foreground">تتبع العهد الممنوحة للموظفين</p>
                </div>
              </div>
              <div className="grid grid-cols-2 sm:grid-cols-2 gap-2 sm:gap-3">
                <Link to="/inventory/custody" className="inline-flex items-center gap-2 rounded-xl border bg-background hover:bg-muted/50 px-4 py-2.5 transition-colors text-sm font-medium">
                  <ClipboardList className="w-4 h-4" />
                  عرض العهد النشطة
                </Link>
                <Link to="/inventory/custody?action=new" className="inline-flex items-center gap-2 rounded-xl border bg-background hover:bg-muted/50 px-4 py-2.5 transition-colors text-sm font-medium">
                  <Plus className="w-4 h-4" />
                  إضافة عهد جديدة
                </Link>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="transactions">
          <Card>
            <CardContent className="pt-6">
              <div className="flex items-center gap-4 mb-4">
                <div className="w-12 h-12 rounded-xl bg-primary/10 flex items-center justify-center">
                  <ArrowUpDown className="w-6 h-6 text-primary" />
                </div>
                <div>
                  <Heading level="h3" className="font-medium">سجل الحركات</Heading>
                  <p className="text-sm text-muted-foreground">حركات إدخال وإخراج المخزون</p>
                </div>
              </div>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2 sm:gap-3">
                <Link to="/inventory/transactions" className="inline-flex items-center gap-2 rounded-xl border bg-background hover:bg-muted/50 px-4 py-2.5 transition-colors text-sm font-medium">
                  <ArrowUpDown className="w-4 h-4" />
                  كل الحركات
                </Link>
                <Link to="/inventory/transactions?type=in" className="inline-flex items-center gap-2 rounded-xl border bg-background hover:bg-muted/50 px-4 py-2.5 transition-colors text-sm font-medium">
                  <Plus className="w-4 h-4" />
                  إدخال مخزون
                </Link>
                <Link to="/inventory/transactions?type=out" className="inline-flex items-center gap-2 rounded-xl border bg-background hover:bg-muted/50 px-4 py-2.5 transition-colors text-sm font-medium">
                  <Trash2 className="w-4 h-4" />
                  إخراج مخزون
                </Link>
              </div>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

import { useQuery } from "@tanstack/react-query";
import { ChevronDown, FileText, Inbox, Layers, Package, Plus } from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";

import { itemApi, type ItemDto } from "@/api/inventory/items";
import { transactionApi, type TransactionDto } from "@/api/inventory/transactions";
import { InventoryBulkTransactionFormDialog } from "@/components/domain/inventory/InventoryBulkTransactionFormDialog";
import { InventoryItemFormDialog } from "@/components/domain/inventory/InventoryItemFormDialog";
import { InventoryTransactionFormDialog } from "@/components/domain/inventory/InventoryTransactionFormDialog";
import { Badge, Button, Card, Heading, Loader, PageLayout, Select, SelectContent, SelectItem, SelectTrigger, SelectValue,Text } from "@/components/ui";
import { INVENTORY_TRANSACTION_TYPE } from "@/constants/inventory";
import { useCrudState } from "@/hooks";
import { normalizeApiError } from "@/lib/errorUtils";
import { formatDate } from "@/lib/utils";
import { useHasPermission } from "@/stores/authStore";

export function InventoryTransactionsPage() {
    const crud = useCrudState<TransactionDto>();
    const navigate = useNavigate();
    const canCreate = useHasPermission("Inventory.Transaction.Create");
    const [selectedItemId, setSelectedItemId] = useState<number | null>(null);
    const [items, setItems] = useState<ItemDto[]>([]);
    const [showItemForm, setShowItemForm] = useState(false);
    const [showBulkForm, setShowBulkForm] = useState(false);
    const [showWithdrawalForm, setShowWithdrawalForm] = useState(false);

    const { data: itemsData, refetch: refetchItems } = useQuery({
        queryKey: ["inventory-items"],
        queryFn: () => itemApi.getAll()
    });

    useEffect(() => {
        if (itemsData) setItems(itemsData);
    }, [itemsData]);

    const handleItemSaved = useCallback(() => {
        setShowItemForm(false);
        refetchItems();
    }, [refetchItems]);

    const queryFilter = selectedItemId ? `item-${selectedItemId}` : "all";
    const { data: transactions = [], isLoading: loading, error, refetch } = useQuery({
        queryKey: ["inventory-transactions", queryFilter],
        queryFn: () => selectedItemId ? transactionApi.getByItem(selectedItemId) : transactionApi.getAll(),
    });

    useEffect(() => {
        if (error) {
            toast.error("فشل تحميل الحركات", {
                description: normalizeApiError(error).message
            });
        }
    }, [error]);

    const handleSaved = () => {
        crud.closeForm();
        refetch();
    };

    const handleWithdrawalOrderIssued = (result: TransactionDto[]) => {
        const orderNumber = result[0]?.withdrawalOrderNumber;
        if (orderNumber) {
            navigate(`/inventory/withdrawal-orders/${encodeURIComponent(orderNumber)}/print`);
        }
    };

    const [expandedBatches, setExpandedBatches] = useState<Set<string>>(new Set());

    const groupedTransactions = useMemo(() => {
        const groups: { batchID: string; transactions: TransactionDto[] }[] = [];
        const singles: TransactionDto[] = [];
        const batchMap = new Map<string, TransactionDto[]>();

        for (const t of transactions) {
            if (t.batchID) {
                const arr = batchMap.get(t.batchID) ?? [];
                arr.push(t);
                batchMap.set(t.batchID, arr);
            } else {
                singles.push(t);
            }
        }

        for (const [batchID, txns] of batchMap) {
            groups.push({ batchID, transactions: txns });
        }

        return { groups, singles };
    }, [transactions]);

    const toggleBatch = (batchID: string) => {
        setExpandedBatches(prev => {
            const next = new Set(prev);
            if (next.has(batchID)) next.delete(batchID);
            else next.add(batchID);
            return next;
        });
    };

    const renderRow = (row: TransactionDto) => (
        <div key={row.inventoryTransactionID}
            role="button"
            tabIndex={0}
            className="flex items-center gap-4 p-3 border-b border-border last:border-b-0 hover:bg-muted/30 cursor-pointer transition-colors focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-inset"
            onClick={() => navigate(`/inventory/transactions/${row.inventoryTransactionID}`)}
            onKeyDown={(e: React.KeyboardEvent) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); navigate(`/inventory/transactions/${row.inventoryTransactionID}`); } }}>
            <div className="flex-1 grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-11 gap-2 items-center text-sm">
                <div className="col-span-2">
                    <Badge variant={(INVENTORY_TRANSACTION_TYPE[row.transactionType] ?? INVENTORY_TRANSACTION_TYPE[4]).variant as any}>
                        {(INVENTORY_TRANSACTION_TYPE[row.transactionType] ?? INVENTORY_TRANSACTION_TYPE[4]).label}
                    </Badge>
                </div>
                <div className="col-span-2 flex items-center gap-2">
                    <Package className="w-4 h-4 text-muted-foreground shrink-0" />
                    <div>
                        <div className="font-medium truncate">{row.itemName}</div>
                        <div className="text-xs text-muted-foreground font-mono">{row.itemCode}</div>
                    </div>
                </div>
                <div className="col-span-1 font-mono font-medium">{row.quantity}</div>
                <div className="col-span-1 font-mono text-muted-foreground">{row.previousQuantity}</div>
                <div className="col-span-1 font-mono font-medium">{row.newQuantity}</div>
                <div className="col-span-1 font-mono text-xs">{row.unitCost != null ? `${row.unitCost.toFixed(2)}` : "-"}</div>
                <div className="col-span-1 font-mono text-xs">{row.currency || "-"}</div>
                <div className="col-span-1 font-mono text-xs">{row.withdrawalOrderNumber || "-"}</div>
                <div className="col-span-1 text-xs text-muted-foreground">{formatDate(row.transactionDate)}</div>
            </div>
        </div>
    );

    const renderBatchGroup = (group: { batchID: string; transactions: TransactionDto[] }) => {
        const isExpanded = expandedBatches.has(group.batchID);
        const first = group.transactions[0];
        const t = INVENTORY_TRANSACTION_TYPE[first.transactionType] ?? INVENTORY_TRANSACTION_TYPE[4];
        return (
            <div key={group.batchID} className="border-b border-border last:border-b-0">
                <div
                    role="button"
                    tabIndex={0}
                    className="flex items-center gap-3 p-3 bg-muted/10 cursor-pointer hover:bg-muted/30 transition-colors focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-inset"
                    onClick={() => toggleBatch(group.batchID)}
                    onKeyDown={(e: React.KeyboardEvent) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggleBatch(group.batchID); } }}>
                    <ChevronDown className={`w-4 h-4 text-muted-foreground transition-transform ${isExpanded ? "" : "-rotate-90"}`} />
                    <Layers className="w-4 h-4 text-primary" />
                    <Badge variant={t.variant as any}>{t.label}</Badge>
                    <span className="font-medium text-sm">حركة متعددة ({group.transactions.length} أصناف)</span>
                    <span className="text-xs text-muted-foreground">{first.invoiceNumber || ""}</span>
                    <span className="text-xs text-muted-foreground ms-auto">{formatDate(first.transactionDate)}</span>
                </div>
                {isExpanded && (
                    <div className="border-t border-border bg-muted/5">
                        {group.transactions.map(renderRow)}
                    </div>
                )}
            </div>
        );
    };

    return (
        <PageLayout>
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div className="text-start">
                    <Heading level="h3">حركات المخزون</Heading>
                    <Text variant="description" className="mt-1">
                        سجل حركات الأصناف (إدخال، إخراج، نقل، إتلاف، تسوية جرد)
                    </Text>
                </div>
                <div className="flex items-center gap-2 flex-wrap">
                    <Button variant="outline" onClick={() => setShowItemForm(true)} className="gap-1.5">
                        <Plus className="w-4 h-4" /> إضافة صنف
                    </Button>
                    {canCreate && (
                        <Button variant="secondary" onClick={() => setShowBulkForm(true)} className="gap-1.5">
                            <Plus className="w-4 h-4" /> إضافة حركة متعددة
                        </Button>
                    )}
                    {canCreate && (
                        <Button onClick={() => setShowWithdrawalForm(true)} className="gap-1.5 ">
                            <FileText className="w-4 h-4" /> إصدار أمر صرف
                        </Button>
                    )}
                    {canCreate && selectedItemId && (
                        <Button onClick={() => crud.openCreate()} className="gap-1.5 ">
                            <Plus className="w-4 h-4" /> إضافة حركة
                        </Button>
                    )}
                </div>
            </div>

            <Card className="p-4 flex flex-col sm:flex-row sm:items-center gap-4 bg-muted/20 border-border">
                <div className="flex items-center gap-3">
                    <Text variant="label" className="whitespace-nowrap">تصفية حسب الصنف:</Text>
                    <Select
                        value={selectedItemId?.toString() ?? ""}
                        onValueChange={(val) => setSelectedItemId(val ? Number(val) : null)}
                    >
                        <SelectTrigger className="min-w-[250px]">
                            <SelectValue placeholder="جميع الحركات" />
                        </SelectTrigger>
                        <SelectContent>
                            {items.map((item) => (
                                <SelectItem key={item.inventoryItemID} value={item.inventoryItemID.toString()}>
                                    {item.itemName} ({item.itemCode})
                                </SelectItem>
                            ))}
                        </SelectContent>
                    </Select>
                </div>
            </Card>

            <div className="space-y-4">
                {loading ? (
                    <div className="py-8"><Loader text="جاري تحميل الحركات..." size={40} /></div>
                ) : error ? (
                    <div className="text-center py-12 text-destructive bg-destructive/10 rounded-lg border border-destructive">تعذر تحميل الحركات</div>
                ) : groupedTransactions.groups.length === 0 && groupedTransactions.singles.length === 0 ? (
                    <div className="text-center py-12 text-muted-foreground bg-muted/10 rounded-lg border border-dashed">
                        <Inbox className="w-10 h-10 mx-auto mb-2 opacity-100" />
                        <p className="font-bold">لا توجد حركات مخزون</p>
                        <p className="text-xs mt-1">لم يتم تسجيل أي حركات مخزون بعد</p>
                    </div>
                ) : (
                    <div className="bg-card border rounded-xl overflow-hidden  flex flex-col">
                        <div className="flex items-center gap-4 p-3 border-b bg-muted/40 text-muted-foreground text-xs font-medium">
                            <div className="flex-1 grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-11 gap-2 items-center">
                                <div className="col-span-2">نوع الحركة</div>
                                <div className="col-span-2">الصنف</div>
                                <div className="col-span-1">الكمية</div>
                                <div className="col-span-1">الرصيد السابق</div>
                                <div className="col-span-1">الرصيد الجديد</div>
                                <div className="col-span-1">تكلفة الوحدة</div>
                                <div className="col-span-1">العملة</div>
                                <div className="col-span-1">أمر الصرف</div>
                                <div className="col-span-1">التاريخ</div>
                            </div>
                        </div>
                        {groupedTransactions.groups.map(renderBatchGroup)}
                        {groupedTransactions.singles.map(renderRow)}
                    </div>
                )}
            </div>

            <InventoryItemFormDialog
                open={showItemForm}
                onOpenChange={setShowItemForm}
                onSaved={handleItemSaved}
                item={null}
            />

            <InventoryBulkTransactionFormDialog
                open={showBulkForm}
                onOpenChange={setShowBulkForm}
                onSaved={() => { refetch(); }}
                items={items}
            />

            <InventoryBulkTransactionFormDialog
                open={showWithdrawalForm}
                onOpenChange={setShowWithdrawalForm}
                onSaved={() => { setShowWithdrawalForm(false); refetch(); }}
                items={items}
                presetType={1}
                onSuccessWithResult={handleWithdrawalOrderIssued}
            />

            {selectedItemId != null && (
                <InventoryTransactionFormDialog
                    open={crud.isFormOpen}
                    onOpenChange={crud.onOpenChange}
                    onSaved={handleSaved}
                    transaction={null}
                    itemId={selectedItemId}
                />
            )}
        </PageLayout>
    );
}

import { useMutation,useQuery } from "@tanstack/react-query";
import {
AlertTriangle,   ArrowRight,   Building2, Calculator,
CheckCircle2, ClipboardCheck,
Package, Save, } from "lucide-react";
import { useEffect,useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";

import { type AssetStocktakeLineDto,stocktakeApi } from "@/api/inventory/stocktake";
import { Heading, StatusBadge, Text } from "@/components/ui";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from "@/components/ui/AlertDialog";
import { Badge } from "@/components/ui/Badge";
import { Button } from "@/components/ui/Button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/Card";
import { Checkbox } from "@/components/ui/Checkbox";
import { Input } from "@/components/ui/Input";
import { Loader } from "@/components/ui/Loader";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/Select";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/Table";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/Tabs";
import { STOCKTAKE_STATUS } from "@/constants/statusConfigs";
import { cn } from "@/lib/utils";

// ─── Shared Constants ───────────────────────────────────



const CONDITION_OPTIONS = [
  { value: "Good", label: "جيدة" },
  { value: "Fair", label: "مقبولة" },
  { value: "Poor", label: "ضعيفة" },
  { value: "Missing", label: "مفقودة" },
];

const CONDITION_MAP: Record<string, string> = Object.fromEntries(
  CONDITION_OPTIONS.map((o) => [o.value, o.label])
);

const formatCurrency = (amount: number) =>
  new Intl.NumberFormat("ar-YE", { style: "decimal", minimumFractionDigits: 0 }).format(amount) + " ريال";

// ─── Shared Hook: Fiscal Years ──────────────────────────

function useFiscalYears() {
  return useQuery({
    queryKey: ["fiscal-years"],
    queryFn: async () => {
      const res = await stocktakeApi.getFiscalYears();
      return res.data;
    },
  });
}

// ─── Loading ────────────────────────────────────────────

function LoadingSpinner() {
  return (
    <div className="flex items-center justify-center h-64">
      <Loader variant="page" text="جاري تحميل بيانات الجرد..." />
    </div>
  );
}

// ─── Empty State ────────────────────────────────────────

function EmptyStocktake({ onCreate, isPending }: { onCreate: () => void; isPending: boolean }) {
  return (
    <Card>
      <CardContent className="pt-6 text-center">
        <Package className="w-12 h-12 text-muted-foreground mx-auto mb-3" />
        <p className="text-muted-foreground">لم يتم إنشاء جرد لهذه السنة المالية بعد</p>
        <Button onClick={onCreate} className="mt-4" disabled={isPending}>
          إنشاء جرد جديد
        </Button>
      </CardContent>
    </Card>
  );
}

// ─── Inventory Stocktake Tab ────────────────────────────

function InventoryStocktakeTab({ fiscalYearId }: { fiscalYearId: string }) {
  const [physicalCounts, setPhysicalCounts] = useState<Record<number, number>>({});
  const [showAdjustDialog, setShowAdjustDialog] = useState(false);

  const { data: stocktake, isLoading, refetch } = useQuery({
    queryKey: ["simple-stocktake", fiscalYearId],
    queryFn: async () => {
      if (!fiscalYearId || fiscalYearId === "current") {
        const res = await stocktakeApi.getSimpleStocktake();
        return res.data;
      }
      const res = await stocktakeApi.getSimpleStocktakeByFiscalYear(Number(fiscalYearId));
      return res.data;
    },
    enabled: true,
  });

  const createMutation = useMutation({
    mutationFn: () => stocktakeApi.createSimpleStocktake(),
    onSuccess: () => { toast.success("تم إنشاء جرد المخزون بنجاح"); refetch(); },
    onError: (error: any) => { toast.error(error.response?.data?.message || "فشل إنشاء الجرد"); },
  });

  const adjustMutation = useMutation({
    mutationFn: (stocktakeId: number) => stocktakeApi.adjustSimpleStocktake(stocktakeId),
    onSuccess: () => { toast.success("تم تسوية الجرد وترحيل القيد بنجاح"); setShowAdjustDialog(false); refetch(); },
    onError: (error: any) => { toast.error(error.response?.data?.message || "فشل تسوية الجرد"); },
  });

  const handleAdjust = () => {
    if (!stocktake) return;
    adjustMutation.mutate(stocktake.simpleStocktakeID);
  };

  if (isLoading) return <LoadingSpinner />;
  if (!stocktake) return <EmptyStocktake onCreate={() => createMutation.mutate()} isPending={createMutation.isPending} />;

  const isInProgress = stocktake.status === "InProgress";

  return (
    <div className="space-y-4">
      {/* Header Actions */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <StatusBadge status={stocktake.status} config={STOCKTAKE_STATUS} />
          {stocktake.status === "Adjusted" && (
            <Badge variant="success" className="bg-success text-white">
              <CheckCircle2 className="w-3 h-3 ml-1" /> تمت التسوية
            </Badge>
          )}
        </div>
        {!stocktake && (
          <Button onClick={() => createMutation.mutate()} disabled={createMutation.isPending}>
            <Package className="w-4 h-4 ml-2" /> إنشاء جرد جديد
          </Button>
        )}
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-muted-foreground">إجمالي الأصناف</p>
                <p className="text-lg md:text-xl lg:text-2xl font-bold">{stocktake.totalItems}</p>
              </div>
              <Package className="w-8 h-8 text-muted-foreground" />
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-muted-foreground">أصناف بها فروق</p>
                <p className="text-lg md:text-xl lg:text-2xl font-bold text-warning">{stocktake.itemsWithVariance}</p>
              </div>
              <AlertTriangle className="w-8 h-8 text-warning" />
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-muted-foreground">قيمة الفروق</p>
                <p className="text-lg md:text-xl lg:text-2xl font-bold text-danger">{formatCurrency(stocktake.totalVarianceValue)}</p>
              </div>
              <Calculator className="w-8 h-8 text-danger" />
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-muted-foreground">الحالة</p>
          <StatusBadge status={stocktake.status} config={STOCKTAKE_STATUS} />
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Table */}
      {stocktake.lines.length > 0 ? (
        <Card>
          <CardHeader>
            <CardTitle>قائمة الأصناف ({stocktake.lines.length} صنف)</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead className="w-20 text-center">كود الصنف</TableHead>
                    <TableHead className="min-w-[150px]">اسم الصنف</TableHead>
                    <TableHead className="w-20 text-center">بالسجلات</TableHead>
                    <TableHead className="w-24 text-center">الكمية الفعلية</TableHead>
                    <TableHead className="w-16 text-center">الفرق</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {stocktake.lines.map((line) => {
                    const physicalQty = physicalCounts[line.inventoryItemID] ?? line.physicalQuantity;
                    const variance = physicalQty - line.systemQuantity;
                    return (
                      <TableRow key={line.lineID}>
                        <TableCell className="font-mono text-sm text-center">{line.itemCode}</TableCell>
                        <TableCell className="font-medium">{line.itemName}</TableCell>
                        <TableCell className="text-center">{line.systemQuantity}</TableCell>
                        <TableCell className="text-center">
                          {isInProgress ? (
                            <Input
                              type="number"
                              value={physicalCounts[line.inventoryItemID] ?? line.physicalQuantity}
                              onChange={(e) => {
                                const val = parseInt(e.target.value) || 0;
                                setPhysicalCounts((prev) => ({ ...prev, [line.inventoryItemID]: val }));
                              }}
                              className="w-20 text-center h-9"
                              min={0}
                            />
                          ) : (
                            <span>{physicalQty}</span>
                          )}
                        </TableCell>
                        <TableCell className="text-center">
                          <span className={variance > 0 ? "text-success font-bold" : variance < 0 ? "text-danger font-bold" : ""}>
                            {variance > 0 ? `+${variance}` : variance}
                          </span>
                        </TableCell>
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            </div>
          </CardContent>
        </Card>
      ) : (
        <Card>
          <CardContent className="pt-6 text-center">
            <Package className="w-12 h-12 text-muted-foreground mx-auto mb-3" />
            <p className="text-muted-foreground">لا توجد أصناف في المخزون للجرد</p>
          </CardContent>
        </Card>
      )}

      {/* Adjust Dialog */}
      <AlertDialog open={showAdjustDialog} onOpenChange={setShowAdjustDialog}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>تأكيد تسوية الجرد</AlertDialogTitle>
            <AlertDialogDescription>
              سيتم إنشاء قيد محاسبي للتسوية وترحيله تلقائياً. هل أنت متأكد من المتابعة؟
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>إلغاء</AlertDialogCancel>
            <AlertDialogAction onClick={handleAdjust} disabled={adjustMutation.isPending}>
              {adjustMutation.isPending ? "جاري التسوية..." : "تأكيد التسوية"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

// ─── Asset Stocktake Tab ────────────────────────────────

function AssetStocktakeTab({ fiscalYearId }: { fiscalYearId: string }) {
  const [edits, setEdits] = useState<Record<number, { isPresent: boolean; actualCondition: string; recordedQuantity: number; notes: string }>>({});
  const [showCompleteDialog, setShowCompleteDialog] = useState(false);

  const { data: stocktake, isLoading, refetch } = useQuery({
    queryKey: ["asset-stocktake", fiscalYearId],
    queryFn: async () => {
      if (!fiscalYearId || fiscalYearId === "current") {
        const res = await stocktakeApi.getAssetStocktake();
        return res.data;
      }
      const res = await stocktakeApi.getAssetStocktakeByFiscalYear(Number(fiscalYearId));
      return res.data;
    },
    enabled: true,
  });

  useEffect(() => { setEdits({}); }, [stocktake?.assetStocktakeID]);

  const createMutation = useMutation({
    mutationFn: (fiscalYearID: number) => stocktakeApi.createAssetStocktake(fiscalYearID),
    onSuccess: () => { toast.success("تم إنشاء جرد الأصول بنجاح"); refetch(); },
    onError: (error: any) => { toast.error(error.response?.data?.message || "فشل إنشاء الجرد"); },
  });

  const recordMutation = useMutation({
    mutationFn: ({ stocktakeId, lines }: { stocktakeId: number; lines: AssetStocktakeLineDto[] }) =>
      stocktakeApi.recordAssetStocktake(stocktakeId, lines),
    onSuccess: () => { toast.success("تم حفظ نتائج الجرد بنجاح"); setEdits({}); refetch(); },
    onError: (error: any) => { toast.error(error.response?.data?.message || "فشل حفظ النتائج"); },
  });

  const completeMutation = useMutation({
    mutationFn: (stocktakeId: number) => stocktakeApi.completeAssetStocktake(stocktakeId),
    onSuccess: () => { toast.success("تم إتمام الجرد بنجاح"); setShowCompleteDialog(false); setEdits({}); refetch(); },
    onError: (error: any) => { toast.error(error.response?.data?.message || "فشل إتمام الجرد"); },
  });

  const handleCreateStocktake = () => {
    const yearId = fiscalYearId ? Number(fiscalYearId) : undefined;
    if (!yearId) { toast.error("الرجاء اختيار سنة مالية"); return; }
    createMutation.mutate(yearId);
  };

  const updateEdit = (lineId: number, field: string, value: any) => {
    setEdits((prev) => {
      const existing = stocktake?.lines.find((l) => l.stocktakeLineID === lineId);
      const current = prev[lineId] || {
        isPresent: existing?.isPresent ?? false,
        actualCondition: existing?.actualCondition || "Good",
        recordedQuantity: existing?.recordedQuantity ?? 0,
        notes: existing?.notes || "",
      };
      return { ...prev, [lineId]: { ...current, [field]: value } };
    });
  };

  const getEffectiveLine = (line: AssetStocktakeLineDto) => {
    const edit = edits[line.stocktakeLineID];
    return {
      ...line,
      isPresent: edit?.isPresent ?? line.isPresent,
      actualCondition: edit?.actualCondition ?? (line.actualCondition || ""),
      recordedQuantity: edit?.recordedQuantity ?? line.recordedQuantity ?? 0,
      notes: edit?.notes ?? line.notes ?? "",
    };
  };

  const handleSaveResults = () => {
    if (!stocktake) return;
    const lines: AssetStocktakeLineDto[] = stocktake.lines.map((line) => {
      const edit = edits[line.stocktakeLineID];
      return {
        ...line,
        isPresent: edit?.isPresent ?? line.isPresent,
        actualCondition: edit?.actualCondition ?? (line.actualCondition || "Good"),
        recordedQuantity: edit?.recordedQuantity ?? line.recordedQuantity ?? 0,
        notes: edit?.notes ?? line.notes,
      };
    });
    recordMutation.mutate({ stocktakeId: stocktake.assetStocktakeID, lines });
  };

  const handleComplete = () => {
    if (!stocktake) return;
    if (Object.keys(edits).length > 0) handleSaveResults();
    completeMutation.mutate(stocktake.assetStocktakeID);
  };

  if (isLoading) return <LoadingSpinner />;
  if (!stocktake) return <EmptyStocktake onCreate={handleCreateStocktake} isPending={createMutation.isPending} />;

  const isInProgress = stocktake.status === "InProgress";
  const hasEdits = Object.keys(edits).length > 0;

  return (
    <div className="space-y-4">
      {/* Header Actions */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <StatusBadge status={stocktake.status} config={STOCKTAKE_STATUS} />
          {stocktake.status === "Completed" && (
            <Badge variant="success" className="bg-success text-white">
              <CheckCircle2 className="w-3 h-3 ml-1" /> تم إتمام الجرد
            </Badge>
          )}
          {hasEdits && isInProgress && (
            <Badge variant="outline" className="border-warning text-warning">
              توجد تعديلات غير محفوظة
            </Badge>
          )}
        </div>
        {isInProgress && (
          <div className="flex gap-2">
            <Button variant="outline" onClick={handleSaveResults} disabled={!hasEdits || recordMutation.isPending}>
              <Save className="w-4 h-4 ml-2" /> حفظ النتائج
            </Button>
            <Button onClick={() => setShowCompleteDialog(true)}>
              <ClipboardCheck className="w-4 h-4 ml-2" /> إتمام الجرد
            </Button>
          </div>
        )}
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-muted-foreground">إجمالي الأصول</p>
                <p className="text-lg md:text-xl lg:text-2xl font-bold">{stocktake.summary.totalAssets}</p>
              </div>
              <Building2 className="w-8 h-8 text-muted-foreground" />
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-muted-foreground">موجودة</p>
                <p className="text-lg md:text-xl lg:text-2xl font-bold text-success">{stocktake.summary.presentAssets}</p>
              </div>
              <CheckCircle2 className="w-8 h-8 text-success" />
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-muted-foreground">مفقودة</p>
                <p className="text-lg md:text-xl lg:text-2xl font-bold text-danger">{stocktake.summary.missingAssets}</p>
              </div>
              <AlertTriangle className="w-8 h-8 text-danger" />
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-muted-foreground">قيمة الدفتر</p>
                <p className="text-lg md:text-xl lg:text-2xl font-bold">{formatCurrency(stocktake.summary.totalBookValue)}</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Table */}
      {stocktake.lines.length > 0 ? (
        <Card>
          <CardHeader>
            <CardTitle>قائمة الأصول ({stocktake.lines.length} أصل)</CardTitle>
          </CardHeader>
          <CardContent className="p-0">
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow className="bg-muted/50 hover:bg-muted/50">
                    <TableHead className="w-[100px] text-center font-bold text-xs">رقم الأصل</TableHead>
                    <TableHead className="min-w-[160px] font-bold text-xs">اسم الأصل</TableHead>
                    <TableHead className="w-[120px] text-center font-bold text-xs">الموقع</TableHead>
                    <TableHead className="w-[130px] text-center font-bold text-xs">القيمة الدفترية</TableHead>
                    <TableHead className="w-[100px] text-center font-bold text-xs">الكمية الفعلية</TableHead>
                    <TableHead className="w-[80px] text-center font-bold text-xs">موجود</TableHead>
                    <TableHead className="w-[120px] text-center font-bold text-xs">الحالة</TableHead>
                    <TableHead className="w-[180px] text-center font-bold text-xs">ملاحظات</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {stocktake.lines.map((line) => {
                    const effective = getEffectiveLine(line);
                    const isMissing = effective.isPresent === false;
                    return (
                      <TableRow
                        key={line.stocktakeLineID}
                        className={cn(
                          "transition-colors",
                          edits[line.stocktakeLineID] ? "bg-warning/10 " : "hover:bg-muted/30",
                          isMissing && "bg-danger/10 "
                        )}
                      >
                        <TableCell className="text-center">
                          <span className="font-mono text-xs bg-muted/60 px-2 py-1 rounded">{line.assetNumber}</span>
                        </TableCell>
                        <TableCell>
                          <span className="font-medium text-sm">{line.assetName}</span>
                        </TableCell>
                        <TableCell className="text-center text-sm text-muted-foreground">{line.location || "-"}</TableCell>
                        <TableCell className="text-center">
                          <span className="font-mono text-sm font-semibold" dir="ltr">{formatCurrency(line.netBookValue)}</span>
                        </TableCell>
                        <TableCell className="text-center">
                          {isInProgress ? (
                            <Input
                              type="number"
                              min={0}
                              value={effective.recordedQuantity}
                              onChange={(e) => updateEdit(line.stocktakeLineID, "recordedQuantity", parseInt(e.target.value) || 0)}
                              className="w-16 text-center h-8 text-sm"
                            />
                          ) : (
                            <span className="font-semibold text-sm">{effective.recordedQuantity}</span>
                          )}
                        </TableCell>
                        <TableCell className="text-center">
                          {isInProgress ? (
                            <div className="flex justify-center">
                              <Checkbox
                                checked={effective.isPresent}
                                onCheckedChange={(checked) => updateEdit(line.stocktakeLineID, "isPresent", !!checked)}
                              />
                            </div>
                          ) : (
                            <Badge variant={effective.isPresent ? "success" : "destructive"} className="text-xs">
                              {effective.isPresent ? "موجود" : "مفقود"}
                            </Badge>
                          )}
                        </TableCell>
                        <TableCell className="text-center">
                          {isInProgress ? (
                            <Select
                              value={effective.actualCondition || "Good"}
                              onValueChange={(val) => updateEdit(line.stocktakeLineID, "actualCondition", val)}
                            >
                              <SelectTrigger className="h-8 w-full text-xs"><SelectValue /></SelectTrigger>
                              <SelectContent>
                                {CONDITION_OPTIONS.map((opt) => (
                                  <SelectItem key={opt.value} value={opt.value}>{opt.label}</SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                          ) : (
                            <Badge
                              variant={effective.actualCondition === "Good" ? "success" : effective.actualCondition === "Missing" ? "destructive" : "secondary"}
                              className="text-xs"
                            >
                              {CONDITION_MAP[effective.actualCondition] || effective.actualCondition || "-"}
                            </Badge>
                          )}
                        </TableCell>
                        <TableCell className="text-center">
                          {isInProgress ? (
                            <Input
                              value={effective.notes}
                              onChange={(e) => updateEdit(line.stocktakeLineID, "notes", e.target.value)}
                              placeholder="ملاحظات..."
                              className="h-8 w-full text-xs text-center"
                            />
                          ) : (
                            <span className="text-xs text-muted-foreground">{effective.notes || "-"}</span>
                          )}
                        </TableCell>
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            </div>
          </CardContent>
        </Card>
      ) : (
        <Card>
          <CardContent className="pt-6 text-center">
            <Package className="w-12 h-12 text-muted-foreground mx-auto mb-3" />
            <p className="text-muted-foreground">لا توجد أصول ثابتة للجرد</p>
          </CardContent>
        </Card>
      )}

      {/* Complete Dialog */}
      <AlertDialog open={showCompleteDialog} onOpenChange={setShowCompleteDialog}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>تأكيد إتمام الجرد</AlertDialogTitle>
            <AlertDialogDescription>
              سيتم حفظ جميع التعديلات وإتمام الجرد. لا يمكن تعديل الجرد بعد الإتمام. هل أنت متأكد؟
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>إلغاء</AlertDialogCancel>
            <AlertDialogAction onClick={handleComplete} disabled={completeMutation.isPending}>
              {completeMutation.isPending ? "جاري الإتمام..." : "تأكيد الإتمام"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

// ─── Main Page ──────────────────────────────────────────

export function StocktakePage() {
  const navigate = useNavigate();
  const [selectedFiscalYearId, setSelectedFiscalYearId] = useState<string>("");
  const { data: fiscalYears } = useFiscalYears();

  return (
    <div className="space-y-6">
      {/* Title + Fiscal Year Selector */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <Button variant="ghost" size="icon" onClick={() => navigate("/inventory")}>
            <ArrowRight className="w-4 h-4" />
          </Button>
          <div>
