import { useQuery } from "@tanstack/react-query";
import {
    AlertTriangle,
    Ban,
    BookOpen,
    CalendarDays,
    CheckCircle,
    Clock,
    Download,
    ExternalLink,
    Eye,
    FileText,
    Hash,
    MapPin,
    User,
    XCircle,
    ZoomIn,
} from "lucide-react";
import { useRef, useState } from "react";

import { paymentBookReviewApi } from "@/api/pension";
import {
    Badge,
    BaseFormDialog,
    Button,
    CrudPageLayout,
    FormSection,
    InfoPair,
    NativeSelect,
    StatCard,
} from "@/components/ui";
import { useDebouncedSearch } from "@/hooks/useDebouncedSearch";
import { getDocumentUrl } from "@/lib/utils";
import type { PaymentBookReview } from "@/types/pension";

const statusColors: Record<string, "success" | "warning" | "destructive" | "info" | "outline"> = {
    "فعال": "success",
    "منتهي": "destructive",
    "مفقود": "warning",
    "تالف": "info",
};

const statusLabels: Record<string, string> = {
    "فعال": "نشط",
    "منتهي": "منتهي",
    "مفقود": "مفقود",
    "تالف": "تالف",
};

export function AnnualBookReviewPage() {
    const { searchTerm, setSearchTerm } = useDebouncedSearch();
    const searchInputRef = useRef<HTMLInputElement>(null);
    const [statusFilter, setStatusFilter] = useState("all");
    const [typeFilter, setTypeFilter] = useState("all");
    const [expiringFilter, setExpiringFilter] = useState(false);
    const [selected, setSelected] = useState<PaymentBookReview | null>(null);
    const [previewImage, setPreviewImage] = useState<string | null>(null);

    const { data: stats, isLoading: statsLoading } = useQuery({
        queryKey: ["payment-book-stats"],
        queryFn: () => paymentBookReviewApi.getStats(),
    });

    const { data, isLoading } = useQuery({
        queryKey: ["payment-book-review", { statusFilter, typeFilter, expiringFilter }],
        queryFn: () =>
            paymentBookReviewApi.getReview({
                page: 1,
                pageSize: 100,
                status: statusFilter === "all" ? undefined : statusFilter,
                bookType: typeFilter === "all" ? undefined : typeFilter,
                expiringWithinDays: expiringFilter ? 30 : undefined,
            }),
    });

    const items: PaymentBookReview[] = data?.items || [];

    const filteredItems = items.filter((item) => {
        if (!searchTerm) return true;
        const q = searchTerm.trim().toLowerCase();
        return (
            item.retireeName?.toLowerCase().includes(q) ||
            item.bookNumber?.toLowerCase().includes(q) ||
            item.fileNumber?.toLowerCase().includes(q) ||
            item.recipientName?.toLowerCase().includes(q) ||
            item.militaryNumber?.toLowerCase().includes(q) ||
            item.nationalID?.toLowerCase().includes(q)
        );
    });

    const handleExport = () => {
        const headers = ["رقم الدفتر", "المتقاعد", "رقم الملف", "المستلم", "الرقم العسكري", "الحالة", "تاريخ الانتهاء"];
        const rows = filteredItems.map((item) => [
            item.bookNumber || "",
            item.retireeName || "",
            item.fileNumber || "",
            item.recipientName || "",
            item.militaryNumber || "",
            item.status || "",
            item.expiryDate ? new Date(item.expiryDate).toLocaleDateString("ar-SA") : "",
        ]);
        const csvContent = [headers, ...rows].map((row) => row.join(",")).join("\n");
        const blob = new Blob(["\uFEFF" + csvContent], { type: "text/csv;charset=utf-8;" });
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = `payment-books-${new Date().toISOString().split("T")[0]}.csv`;
        link.click();
        URL.revokeObjectURL(url);
    };

    const columns = [
        {
            key: "bookNumber",
            header: "رقم الدفتر",
            render: (row: PaymentBookReview) => (
                <span className="font-mono font-bold text-xs text-primary">
                    {row.bookNumber}
                </span>
            ),
        },
        {
            key: "retireeName",
            header: "المتقاعد",
            render: (row: PaymentBookReview) => (
                <div>
                    <p className="font-medium text-sm">{row.retireeName || "—"}</p>
                    <div className="flex items-center gap-2 text-xs text-muted-foreground flex-wrap">
                        {row.fileNumber && <span>ملف: {row.fileNumber}</span>}
                        {row.militaryNumber && <span>عسكري: {row.militaryNumber}</span>}
                    </div>
                </div>
            ),
        },
        {
            key: "recipientName",
            header: "المستفيد",
            render: (row: PaymentBookReview) => (
                <span className="text-sm">{row.recipientName || "—"}</span>
            ),
        },
        {
            key: "bookType",
            header: "النوع",
            render: (row: PaymentBookReview) => (
                <Badge variant="outline">{row.bookType || "—"}</Badge>
            ),
        },
        {
            key: "issuingBranchName",
            header: "الفرع المُصدر",
            render: (row: PaymentBookReview) => (
                <span className="text-sm">{row.issuingBranchName || "—"}</span>
            ),
        },
        {
            key: "issueDate",
            header: "تاريخ الإصدار",
            render: (row: PaymentBookReview) => (
                <span className="text-sm">
                    {row.issueDate ? new Date(row.issueDate).toLocaleDateString("ar-SA") : "—"}
                </span>
            ),
        },
        {
            key: "expiryDate",
            header: "تاريخ الانتهاء",
            render: (row: PaymentBookReview) => {
                const isExpiring = row.isExpiringSoon;
                return (
                    <div className="flex items-center gap-1">
                        <span className="text-sm">
                            {row.expiryDate ? new Date(row.expiryDate).toLocaleDateString("ar-SA") : "—"}
                        </span>
                        {isExpiring && (
                            <span title={`باقي ${row.daysUntilExpiry} يوم`}><AlertTriangle className="w-3 h-3 text-amber-500" /></span>
                        )}
                    </div>
                );
            },
        },
        {
            key: "status",
            header: "الحالة",
            render: (row: PaymentBookReview) => (
                <Badge variant={statusColors[row.status] || "outline"}>
                    {statusLabels[row.status] || row.status}
                </Badge>
            ),
        },
        {
            key: "actions",
            header: "",
            render: (row: PaymentBookReview) => (
                <Button
                    variant="ghost-action"
                    size="sm"
                    onClick={(e) => {
                        e.stopPropagation();
                        setSelected(row);
                    }}
                >
                    <Eye className="w-4 h-4" />
                </Button>
            ),
        },
    ];

    return (
        <CrudPageLayout
            title="مراجعة دفاتر الصرف"
            description="مراجعة حالة دفاتر الصرف وتجديدها"
            icon={<CalendarDays className="w-6 h-6" />}
            columns={columns}
            data={filteredItems}
            loading={isLoading}
            searchable
            searchInHeader
            searchPlaceholder="بحث بالاسم أو رقم الدفتر..."
            searchValue={searchTerm}
            onSearchChange={setSearchTerm}
            searchInputRef={searchInputRef}
            rowKey={(row) => row.paymentBookID}
            headerActions={
                <div className="flex gap-2">
                    <NativeSelect
                        value={statusFilter}
                        onChange={setStatusFilter}
                        options={[
                            { value: "all", label: "الكل" },
                            { value: "فعال", label: "نشط" },
                            { value: "منتهي", label: "منتهي" },
                            { value: "مفقود", label: "مفقود" },
                            { value: "تالف", label: "تالف" },
                        ]}
                        placeholder="الحالة"
                    />
                    <NativeSelect
                        value={typeFilter}
                        onChange={setTypeFilter}
                        options={[
                            { value: "all", label: "الكل" },
                            { value: "pension", label: "معاش" },
                            { value: "compensation", label: "تعويض" },
                        ]}
                        placeholder="النوع"
                    />
                    <Button
                        variant={expiringFilter ? "warning" : "outline"}
                        size="sm"
                        onClick={() => setExpiringFilter(!expiringFilter)}
                    >
                        <AlertTriangle className="w-4 h-4 ml-1" />
                        تنتهي قريباً
                    </Button>
                    <Button variant="outline" size="sm" onClick={handleExport}>
                        <Download className="w-4 h-4 ml-1" />
                        تصدير
                    </Button>
                </div>
            }
        >
            {/* Stats */}
            <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-2 sm:gap-4 mb-6">
                <StatCard
                    title="نشطة"
                    value={stats?.totalActive ?? 0}
                    icon={<CheckCircle className="w-5 h-5" />}
                    variant="success"
                    loading={statsLoading}
                />
                <StatCard
                    title="منتهية"
                    value={stats?.totalExpired ?? 0}
                    icon={<XCircle className="w-5 h-5" />}
                    variant="destructive"
                    loading={statsLoading}
                />
                <StatCard
                    title="مفقودة"
                    value={stats?.totalLost ?? 0}
                    icon={<Ban className="w-5 h-5" />}
                    variant="warning"
                    loading={statsLoading}
                />
                <StatCard
                    title="تالفة"
                    value={stats?.totalDamaged ?? 0}
                    icon={<AlertTriangle className="w-5 h-5" />}
                    variant="orange"
                    loading={statsLoading}
                />
                <StatCard
                    title="تنتهي خلال 30 يوم"
                    value={stats?.expiringWithin30Days ?? 0}
                    icon={<Clock className="w-5 h-5" />}
                    variant="amber"
                    loading={statsLoading}
                />
            </div>

            {/* View Dialog */}
            <BaseFormDialog
                title="تفاصيل دفتر الصرف"
                isOpen={!!selected}
                onClose={() => setSelected(null)}
                size="lg"
                submitLabel="إغلاق"
                onSubmit={() => setSelected(null)}
            >
                {selected && (
                    <div className="space-y-6">
                        {/* Header Card */}
                        <div className="flex items-center justify-between p-4 bg-muted/40 rounded-xl border border-border shadow-xs">
                            <div className="flex items-center gap-3.5">
                                <div className="p-2.5 bg-primary/10 rounded-xl border border-primary text-primary">
                                    <BookOpen className="w-5 h-5" />
                                </div>
                                <div>
                                    <div className="flex items-center gap-2">
                                        <span className="text-xs text-muted-foreground font-medium">رقم الدفتر:</span>
                                        <span className="font-mono font-bold text-lg text-primary">{selected.bookNumber}</span>
                                    </div>
                                    <p className="text-xs text-muted-foreground font-medium mt-0.5">{selected.bookType || "دفتر صرف معاش"}</p>
                                </div>
                            </div>
                            <Badge variant={statusColors[selected.status] || "outline"} className="text-sm px-3.5 py-1 font-medium shadow-xs">
                                {statusLabels[selected.status] || selected.status}
                            </Badge>
                        </div>

                        {/* Retiree Info */}
                        <FormSection title="بيانات المتقاعد والمستفيد" icon={User} separator>
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                <InfoPair label="اسم المتقاعد" value={selected.retireeName} icon={<User className="w-4 h-4 text-primary" />} />
                                <InfoPair label="رقم الملف التقاعدي" value={selected.fileNumber} icon={<Hash className="w-4 h-4 text-primary" />} mono />
                                <InfoPair label="اسم المستفيد" value={selected.recipientName} icon={<User className="w-4 h-4 text-primary" />} />
                                <InfoPair label="نوع المستفيد" value={selected.recipientType} icon={<FileText className="w-4 h-4 text-primary" />} />
                            </div>
                        </FormSection>

                        {/* Book Details */}
                        <FormSection title="بيانات الدفتر والتخصيص" icon={FileText} separator>
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                <InfoPair label="نوع الدفتر" value={selected.bookType} icon={<BookOpen className="w-4 h-4 text-primary" />} />
                                <InfoPair label="لون الدفتر" value={selected.legacyColor} icon={<FileText className="w-4 h-4 text-primary" />} />
                                <InfoPair label="الفرع المُصدر" value={selected.issuingBranchName} icon={<MapPin className="w-4 h-4 text-primary" />} />
                                <InfoPair label="سبب التغيير / التعديل" value={selected.changeReason} icon={<AlertTriangle className="w-4 h-4 text-primary" />} />
                            </div>
                        </FormSection>

                        {/* Dates */}
                        <FormSection title="صلاحية الدفتر والتواريخ" icon={CalendarDays} separator={Boolean(selected.bookImagePaths && selected.bookImagePaths.length > 0)}>
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                <InfoPair
                                    label="تاريخ الإصدار"
                                    value={selected.issueDate ? new Date(selected.issueDate).toLocaleDateString("ar-SA") : null}
                                    icon={<CalendarDays className="w-4 h-4 text-primary" />}
                                />
                                <div className="space-y-2">
                                    <InfoPair
                                        label="تاريخ الانتهاء"
                                        value={selected.expiryDate ? new Date(selected.expiryDate).toLocaleDateString("ar-SA") : null}
                                        icon={<CalendarDays className="w-4 h-4 text-primary" />}
                                    />
                                    {selected.isExpiringSoon && selected.daysUntilExpiry !== null && (
                                        <div className="flex items-center gap-2 p-2.5 bg-amber-500/10 border border-amber-500 text-amber-700 dark:text-amber-400 rounded-lg text-xs font-medium">
                                            <AlertTriangle className="w-4 h-4 shrink-0 text-amber-500" />
                                            <span>متبقي <strong>{selected.daysUntilExpiry}</strong> يوم على انتهاء صلاحية هذا الدفتر</span>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </FormSection>

                        {/* Book Images */}
                        {selected.bookImagePaths && selected.bookImagePaths.length > 0 && (
                            <FormSection title={`صور ومستندات الدفتر (${selected.bookImagePaths.length})`} icon={BookOpen}>
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                    {selected.bookImagePaths.map((imagePath, idx) => (
                                        <div
                                            key={idx}
                                            className="relative group overflow-hidden rounded-xl border border-border bg-muted/20 hover:border-primary hover:shadow-md transition-all cursor-pointer"
                                            onClick={() => setPreviewImage(getDocumentUrl(imagePath) ?? `/${imagePath}`)}
                                        >
                                            <img
                                                src={getDocumentUrl(imagePath) ?? `/${imagePath}`}
                                                alt={`صورة الدفتر ${idx + 1}`}
                                                className="w-full h-48 sm:h-56 object-contain bg-background p-2 transition-transform duration-300 group-hover:scale-105"
                                                onError={(e) => {
                                                    (e.target as HTMLImageElement).style.display = "none";
                                                }}
                                            />
                                            {/* Hover overlay with zoom icon */}
                                            <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-2 text-white font-medium text-xs backdrop-blur-[1px]">
                                                <ZoomIn className="w-5 h-5" />
                                                <span>انقر لتكبير الصورة</span>
                                            </div>
                                            <span className="absolute top-2.5 end-2.5 bg-background/90 backdrop-blur-xs text-xs font-semibold px-2.5 py-1 rounded-md border border-border shadow-xs group-hover:opacity-0 transition-opacity">
                                                صورة {idx + 1}
                                            </span>
                                        </div>
                                    ))}
                                </div>
                            </FormSection>
                        )}
                    </div>
                )}
            </BaseFormDialog>

            {/* Image Preview Lightbox Dialog */}
            <BaseFormDialog
                title="معاينة صورة الدفتر المكبرة"
                isOpen={!!previewImage}
                onClose={() => setPreviewImage(null)}
                size="xl"
                submitLabel="إغلاق"
                onSubmit={() => setPreviewImage(null)}
            >
                {previewImage && (
                    <div className="space-y-4">
                        <div className="flex justify-end gap-2">
                            <Button
                                variant="outline"
                                size="sm"
                                onClick={() => window.open(previewImage, "_blank")}
                            >
                                <ExternalLink className="w-4 h-4 ms-1" />
                                فتح في تبويب جديد
                            </Button>
                        </div>
                        <div className="relative flex items-center justify-center p-4 bg-muted/20 rounded-xl min-h-[350px] max-h-[70vh] overflow-auto border border-border">
                            <img
                                src={previewImage}
                                alt="معاينة الدفتر المكبرة"
                                className="max-w-full max-h-[65vh] object-contain rounded-lg shadow-sm"
                            />
                        </div>
                    </div>
                )}
            </BaseFormDialog>
        </CrudPageLayout>
    );
}

import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import {
    CheckCircle,
    Edit,
    Eye,
    Plus,
    StopCircle,
    Trash2,
    Users,
} from "lucide-react";
import { useRef, useState } from "react";
import { useForm } from "react-hook-form";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { z } from "zod";

import { retirementApi } from "@/api/retirement";
import {
    Badge,
    BaseFormDialog,
    Button,
    CrudPageLayout,
    FormField,
    Input,
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
    StatCard,
    yemenPhoneSchema,
} from "@/components/ui";
import { queryKeys } from "@/constants/queryKeys";
import { useDebouncedSearch } from "@/hooks/useDebouncedSearch";
import type { EntitledPersonSummary } from "@/types/retirement";

const addSchema = z.object({
    fullName: z.string().min(1, "الاسم مطلوب"),
    nationalID: z.string().min(1, "الرقم الوطني مطلوب"),
    relationshipID: z.string().min(1, "صلة القرابة مطلوبة"),
    birthDate: z.string().optional(),
    phone: yemenPhoneSchema.optional().or(z.literal("")),
});

const editSchema = z.object({
    fullName: z.string().min(1, "الاسم مطلوب"),
    nationalID: z.string().min(1, "الرقم الوطني مطلوب"),
    relationshipID: z.string().min(1, "صلة القرابة مطلوبة"),
    birthDate: z.string().optional(),
    phone: yemenPhoneSchema.optional().or(z.literal("")),
});

const stopSchema = z.object({
    stopCode: z.string().min(1, "سبب الإيقاف مطلوب"),
    stopDate: z.string().min(1, "تاريخ الإيقاف مطلوب"),
});

type AddForm = z.infer<typeof addSchema>;
type EditForm = z.infer<typeof editSchema>;
type StopForm = z.infer<typeof stopSchema>;

const STOP_CODES = [
    { value: "AGE_LIMIT", label: "ابن >= 24 سنة" },
    { value: "DAUGHTER_MARRIED", label: "بنت متزوجة" },
    { value: "WIDOW_REMARRIED", label: "زوجة تزوجت مرة أخرى" },
    { value: "DECEASED", label: "متوفى" },
    { value: "ADMIN_DECISION", label: "قرار إداري" },
    { value: "EMPLOYED", label: "توظيف" },
];

export function EntitledPersonsPage() {
    const queryClient = useQueryClient();
    const navigate = useNavigate();
    const { searchTerm, setSearchTerm, debouncedValue } = useDebouncedSearch();
    const searchInputRef = useRef<HTMLInputElement>(null);

    const [fileId] = useState<number | null>(null);
    const [showAdd, setShowAdd] = useState(false);
    const [editTarget, setEditTarget] = useState<EntitledPersonSummary | null>(
        null
    );
    const [stopTarget, setStopTarget] = useState<EntitledPersonSummary | null>(
        null
    );
    const [reactivateTarget, setReactivateTarget] =
        useState<EntitledPersonSummary | null>(null);

    // Search mode: global search across all entitled persons
    const { data: searchData = [], isLoading: isSearchLoading } = useQuery({
        queryKey: ["entitled-persons-search", debouncedValue],
        queryFn: () => retirementApi.searchEntitledPersons(debouncedValue, 50),
        enabled: debouncedValue.length > 1,
    });

    // File mode: show entitled persons for a specific file
    const { data: fileData } = useQuery({
        queryKey: ["retirement-file", fileId],
        queryFn: () => retirementApi.getFile(fileId!),
        enabled: !!fileId,
    });

    const { data: entitledData = [], isLoading: isFileLoading } = useQuery({
        queryKey: queryKeys.retirement.entitledPersons.byFile(fileId!),
        queryFn: () => retirementApi.getEntitledPersons(fileId!),
        enabled: !!fileId,
    });

    const isSearchMode = debouncedValue.length > 1;
    const displayData = isSearchMode ? searchData : (fileId ? entitledData : []);
    const isLoading = isSearchMode ? isSearchLoading : isFileLoading;

    const addForm = useForm<AddForm>({
        resolver: zodResolver(addSchema),
        defaultValues: {
            fullName: "",
            nationalID: "",
            relationshipID: "",
            birthDate: "",
            phone: "",
        },
    });

    const editForm = useForm<EditForm>({
        resolver: zodResolver(editSchema),
        defaultValues: {
            fullName: "",
            nationalID: "",
            relationshipID: "",
            birthDate: "",
            phone: "",
        },
    });

    const stopForm = useForm<StopForm>({
        resolver: zodResolver(stopSchema),
        defaultValues: { stopCode: "", stopDate: "" },
    });

    const addMutation = useMutation({
        mutationFn: (data: AddForm) => {
            const formData = new FormData();
            formData.append("fullName", data.fullName);
            formData.append("nationalID", data.nationalID);
            formData.append("relationshipID", data.relationshipID);
            if (data.birthDate) formData.append("birthDate", data.birthDate);
            if (data.phone) formData.append("phone", data.phone);
            return retirementApi.createEntitledPerson(fileId!, formData);
        },
        onSuccess: () => {
            toast.success("تمت الإضافة بنجاح");
            queryClient.invalidateQueries({
                queryKey: queryKeys.retirement.entitledPersons.all,
            });
            setShowAdd(false);
            addForm.reset();
        },
        onError: () => {
            toast.error("خطأ في الإضافة");
        },
    });

    const updateMutation = useMutation({
        mutationFn: (data: { id: number; formData: FormData }) =>
            retirementApi.updateEntitledPerson(data.id, data.formData),
        onSuccess: () => {
            toast.success("تم التحديث بنجاح");
            queryClient.invalidateQueries({
                queryKey: queryKeys.retirement.entitledPersons.all,
            });
            setEditTarget(null);
            editForm.reset();
        },
        onError: () => {
            toast.error("خطأ في التحديث");
        },
    });

    const stopMutation = useMutation({
        mutationFn: (data: { id: number; stopCode: string; stopDate: string }) =>
            retirementApi.stopEntitledPerson(data.id, {
                stopCode: data.stopCode,
                stopDate: data.stopDate,
            }),
        onSuccess: () => {
            toast.success("تم إيقاف الاستحقاق بنجاح");
            queryClient.invalidateQueries({
                queryKey: queryKeys.retirement.entitledPersons.all,
            });
            setStopTarget(null);
            stopForm.reset();
        },
        onError: () => {
            toast.error("خطأ في إيقاف الاستحقاق");
        },
    });

    const reactivateMutation = useMutation({
        mutationFn: (data: { id: number; reactivationCode: string }) =>
            retirementApi.reactivateEntitledPerson(data.id, {
                reactivationCode: data.reactivationCode,
            }),
        onSuccess: () => {
            toast.success("تم إعادة تفعيل الاستحقاق بنجاح");
            queryClient.invalidateQueries({
                queryKey: queryKeys.retirement.entitledPersons.all,
            });
            setReactivateTarget(null);
        },
        onError: () => {
            toast.error("خطأ في إعادة التفعيل");
        },
    });

    const deleteMutation = useMutation({
        mutationFn: (id: number) =>
            retirementApi.deleteEntitledPerson(id),
        onSuccess: () => {
            toast.success("تم الحذف بنجاح");
            queryClient.invalidateQueries({
                queryKey: queryKeys.retirement.entitledPersons.all,
            });
        },
        onError: () => {
            toast.error("خطأ في الحذف");
        },
    });

    const columns = [
        {
            key: "fullName",
            header: "الاسم",
            render: (row: any) => (
                <div className="flex items-center gap-3">
                    <div className="w-9 h-9 rounded-full bg-primary/10 flex items-center justify-center text-primary">
                        <Users className="w-4 h-4" />
                    </div>
                    <span className="font-bold text-foreground">
                        {row.fullName}
                    </span>
                </div>
            ),
        },
        {
            key: "relationshipName",
            header: "صلة القرابة",
            render: (row: any) => (
                <Badge variant="outline">{row.relationshipName || "—"}</Badge>
            ),
        },
        {
            key: "nationalID",
            header: "الرقم الوطني",
            render: (row: any) => (
                <span className="text-sm font-mono">
                    {row.nationalID || "—"}
                </span>
            ),
        },
        {
            key: "phone",
            header: "الهاتف",
            render: (row: any) => (
                <span className="text-sm">{row.phone || "—"}</span>
            ),
        },
        ...(isSearchMode ? [
            {
                key: "fileNumber",
                header: "رقم الملف",
                render: (row: any) => (
                    <Button
                        variant="link"
                        size="sm"
                        className="h-auto p-0 text-sm font-bold"
                        onClick={(e) => {
                            e.stopPropagation();
                            navigate(`/files/${row.fileID}`);
                        }}
                    >
                        {row.fileNumber || "—"}
                    </Button>
                ),
            },
            {
                key: "retireeMilitaryNumber",
                header: "الرقم العسكري",
                render: (row: any) => <span className="text-sm font-mono">{row.retireeMilitaryNumber || "—"}</span>,
            },
        ] : []),
        {
            key: "isActive",
            header: "الحالة",
            render: (row: any) => (
                <Badge
                    variant={
                        row.isDeceased
                            ? "danger"
                            : row.isActive
                                ? "success"
                                : "warning"
                    }
                >
                    {row.isDeceased
                        ? "متوفى"
                        : row.isActive
                            ? "نشط"
                            : "موقوف"}
                </Badge>
            ),
        },
        {
            key: "actions",
            header: "",
            render: (row: any) => (
                <div className="flex gap-1">
                    {isSearchMode ? (
                        <Button
                            variant="ghost-action"
                            size="sm"
                            title="عرض الملف"
                            onClick={(e) => {
                                e.stopPropagation();
                                navigate(`/files/${row.fileID}`);
                            }}
                        >
                            <Eye className="w-4 h-4" />
                        </Button>
                    ) : (
                        <>
                            <Button
                                variant="ghost-action"
                                size="sm"
                                title="تعديل"
                                onClick={(e) => {
                                    e.stopPropagation();
                                    setEditTarget(row);
                                    editForm.reset({
                                        fullName: row.fullName,
                                        nationalID: row.nationalID || "",
                                        relationshipID: row.relationshipName || "",
                                        birthDate: row.dateOfBirth || "",
                                        phone: row.phone || "",
                                    });
                                }}
                            >
                                <Edit className="w-4 h-4" />
                            </Button>
                            {row.isActive && !row.isDeceased && (
                                <Button
                                    variant="ghost-action"
                                    size="sm"
                                    title="إيقاف الاستحقاق"
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        setStopTarget(row);
                                    }}
                                >
                                    <StopCircle className="w-4 h-4" />
                                </Button>
                            )}
                            {!row.isActive && !row.isDeceased && (
                                <Button
                                    variant="ghost-action"
                                    size="sm"
                                    title="إعادة التفعيل"
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        setReactivateTarget(row);
                                    }}
                                >
                                    <CheckCircle className="w-4 h-4" />
                                </Button>
                            )}
                            <Button
                                variant="ghost-action"
                                size="sm"
                                title="حذف"
                                onClick={(e) => {
                                    e.stopPropagation();
                                    if (
                                        confirm(
                                            `هل أنت متأكد من حذف ${row.fullName}؟`
                                        )
                                    ) {
                                        deleteMutation.mutate(row.entitledID);
                                    }
                                }}
                            >
                                <Trash2 className="w-4 h-4 text-destructive" />
                            </Button>
                        </>
                    )}
                </div>
            ),
        },
    ];

    return (
        <CrudPageLayout
            title="إدارة المستحقين"
            description="عرض وإدارة جميع المستحقين (الورثة) عبر ملفات التقاعد"
            icon={<Users className="w-6 h-6" />}
            columns={columns}
            data={displayData}
            loading={isLoading}
            searchable
            searchInHeader
            searchPlaceholder="ابحث بالاسم أو الرقم الوطني أو رقم الملف أو الرقم العسكري..."
            searchValue={searchTerm}
            onSearchChange={setSearchTerm}
            searchInputRef={searchInputRef}
            rowKey={(row: any) => row.entitledID}
            pagination={{
                page: 1,
                pageSize: 50,
                total: displayData.length,
                onPageChange: () => { },
            }}
            emptyMessage="ابحث عن مستحق بالاسم أو الرقم الوطني أو رقم الملف"
            headerActions={
                fileId && !isSearchMode ? (
                    <Button
                        variant="primary"
                        size="sm"
                        onClick={() => setShowAdd(true)}
                    >
                        <Plus className="w-4 h-4 mr-1" />
                        إضافة مستحق
                    </Button>
                ) : undefined
            }
        >
            {/* Stats */}
            {isSearchMode && (
                <div className="grid grid-cols-2 sm:grid-cols-3 gap-2 sm:gap-4 mb-6">
                    <StatCard
                        title="إجمالي النتائج"
                        value={searchData.length}
                        icon={<Users className="w-5 h-5" />}
                        variant="blue"
                        loading={isSearchLoading}
                    />
                    <StatCard
                        title="النشطون"
                        value={searchData.filter((s) => s.isActive && !s.isDeceased).length}
                        icon={<CheckCircle className="w-5 h-5" />}
                        variant="success"
                        loading={isSearchLoading}
                    />
                    <StatCard
                        title="الموقوفون/المتوفون"
                        value={searchData.filter((s) => !s.isActive || s.isDeceased).length}
                        icon={<Trash2 className="w-5 h-5" />}
                        variant="destructive"
                        loading={isSearchLoading}
                    />
                </div>
            )}

            {!isSearchMode && fileId && fileData && (
                <div className="bg-muted/30 rounded-lg p-4 mb-6 border border-border">
                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 text-sm">
                        <div>
                            <span className="text-muted-foreground">
                                المتقاعد:
                            </span>{" "}
                            <strong>{fileData.retireeFullName || "—"}</strong>
                        </div>
                        <div>
                            <span className="text-muted-foreground">
                                رقم الملف:
                            </span>{" "}
                            <strong>{fileData.fileNumber}</strong>
                        </div>
                        <div>
                            <span className="text-muted-foreground">
                                الرقم العسكري:
                            </span>{" "}
                            <strong>
                                {fileData.militaryNumber || "—"}
                            </strong>
                        </div>
                        <div>
                            <span className="text-muted-foreground">
                                عدد المستحقين:
                            </span>{" "}
                            <strong>{entitledData.length}</strong>
                        </div>
                    </div>
                </div>
            )}

            <BaseFormDialog
                title="إضافة مستحق جديد"
                isOpen={showAdd}
                onClose={() => {
                    setShowAdd(false);
                    addForm.reset();
                }}
                onSubmit={addForm.handleSubmit((data) =>
                    addMutation.mutate(data)
                )}
                isLoading={addMutation.isPending}
                size="md"
            >
                <div className="grid grid-cols-1 sm:grid-cols-4 gap-4">
                    <FormField
                        label="الاسم الكامل *"
                        error={addForm.formState.errors.fullName?.message}
                        className="sm:col-span-2"
                    >
                        <Input
                            {...addForm.register("fullName")}
                            placeholder="الاسم"
                        />
                    </FormField>
                    <FormField label="تاريخ الميلاد" className="sm:col-span-2">
                        <Input
                            {...addForm.register("birthDate")}
                            type="date"
                        />
                    </FormField>
                    <FormField
                        label="الرقم الوطني *"
                        error={addForm.formState.errors.nationalID?.message}
                    >
                        <Input
                            {...addForm.register("nationalID")}
                            placeholder="الرقم الوطني"
                        />
                    </FormField>
                    <FormField label="الهاتف">
                        <Input
                            {...addForm.register("phone")}
                            placeholder="7xxxxxxx"
                        />
                    </FormField>
                    <FormField
                        label="صلة القرابة *"
                        error={
                            addForm.formState.errors.relationshipID?.message
                        }
                    >
                        <Input
                            {...addForm.register("relationshipID")}
                            placeholder="رقم العلاقة"
                        />
                    </FormField>
                </div>
            </BaseFormDialog>

            <BaseFormDialog
                title="تعديل بيانات المستحق"
                description={editTarget?.fullName || ""}
                isOpen={!!editTarget}
                onClose={() => {
                    setEditTarget(null);
                    editForm.reset();
                }}
                onSubmit={editForm.handleSubmit((data) => {
                    if (editTarget) {
                        const formData = new FormData();
                        formData.append("fullName", data.fullName);
                        formData.append("nationalID", data.nationalID);
                        formData.append("relationshipID", data.relationshipID);
                        if (data.birthDate) formData.append("birthDate", data.birthDate);
                        if (data.phone) formData.append("phone", data.phone);
                        updateMutation.mutate({ id: editTarget.entitledID, formData });
                    }
                })}
                isLoading={updateMutation.isPending}
                size="md"
            >
                <div className="grid grid-cols-1 sm:grid-cols-4 gap-4">
                    <FormField
                        label="الاسم الكامل *"
                        error={editForm.formState.errors.fullName?.message}
                        className="sm:col-span-2"
                    >
                        <Input
                            {...editForm.register("fullName")}
                            placeholder="الاسم"
                        />
                    </FormField>
                    <FormField label="تاريخ الميلاد" className="sm:col-span-2">
                        <Input
                            {...editForm.register("birthDate")}
                            type="date"
                        />
                    </FormField>
                    <FormField
                        label="الرقم الوطني *"
                        error={editForm.formState.errors.nationalID?.message}
                    >
                        <Input
                            {...editForm.register("nationalID")}
                            placeholder="الرقم الوطني"
                        />
                    </FormField>
                    <FormField label="الهاتف">
                        <Input
                            {...editForm.register("phone")}
                            placeholder="7xxxxxxx"
                        />
                    </FormField>
                    <FormField
                        label="صلة القرابة *"
                        error={editForm.formState.errors.relationshipID?.message}
                    >
                        <Input
                            {...editForm.register("relationshipID")}
                            placeholder="رقم العلاقة"
                        />
                    </FormField>
                </div>
            </BaseFormDialog>

            <BaseFormDialog
                title="إيقاف الاستحقاق"
                description={stopTarget?.fullName || ""}
                isOpen={!!stopTarget}
                onClose={() => {
                    setStopTarget(null);
                    stopForm.reset();
                }}
                onSubmit={stopForm.handleSubmit((data) => {
                    if (stopTarget) {
                        stopMutation.mutate({
                            id: stopTarget.entitledID,
                            stopCode: data.stopCode,
                            stopDate: data.stopDate,
                        });
                    }
                })}
                size="md"
            >
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <FormField
                        label="سبب الإيقاف *"
                        error={stopForm.formState.errors.stopCode?.message}
                    >
                        <Select
                            value={stopForm.watch("stopCode") ?? ""}
                            onValueChange={(value) => stopForm.setValue("stopCode", value)}
                        >
                            <SelectTrigger className="w-full">
                                <SelectValue placeholder="اختر السبب" />
                            </SelectTrigger>
                            <SelectContent>
                                {STOP_CODES.map((c) => (
                                    <SelectItem key={c.value} value={c.value}>
                                        {c.label}
                                    </SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </FormField>
                    <FormField
                        label="تاريخ الإيقاف *"
                        error={stopForm.formState.errors.stopDate?.message}
                    >
                        <Input
                            {...stopForm.register("stopDate")}
                            type="date"
                        />
                    </FormField>
                </div>
            </BaseFormDialog>

            <BaseFormDialog
                title="إعادة التفعيل"
                description={reactivateTarget?.fullName || ""}
                isOpen={!!reactivateTarget}
                onClose={() => setReactivateTarget(null)}
                onSubmit={() => {
                    if (reactivateTarget) {
                        reactivateMutation.mutate({
                            id: reactivateTarget.entitledID,
                            reactivationCode: "ADMIN_DECISION",
                        });
                    }
                }}
                size="md"
            >
                <p className="text-sm text-muted-foreground">
                    هل أنت متأكد من إعادة تفعيل استحقاق{" "}
                    <strong>{reactivateTarget?.fullName}</strong>؟
                </p>
            </BaseFormDialog>
        </CrudPageLayout>
    );
}

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Eye, ShieldCheck, Trash2, Users } from "lucide-react";
import { useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";

import { retirementApi } from "@/api/retirement";
import {
    Badge,
    BaseFormDialog,
    Button,
    CrudPageLayout,
    Heading,
    InfoPair,
    StatCard,
    useConfirm,
} from "@/components/ui";
import { useDebouncedSearch } from "@/hooks/useDebouncedSearch";
import { getPhotoUrl, resolvePersonalPhotoPath } from "@/lib/utils";
import type { GuardianSummary } from "@/types/retirement";

export function GuardiansPage() {
    const navigate = useNavigate();
    const queryClient = useQueryClient();
    const searchInputRef = useRef<HTMLInputElement>(null);
    const { searchTerm, setSearchTerm, debouncedValue } = useDebouncedSearch();
    const [fileId] = useState<number | null>(null);
    const [selected, setSelected] = useState<GuardianSummary | null>(null);
    const { confirm, ConfirmDialogElement } = useConfirm();

    // Search mode: global search across all guardians
    const { data: searchData = [], isLoading: isSearchLoading } = useQuery({
        queryKey: ["guardians-search", debouncedValue],
        queryFn: () => retirementApi.searchGuardians(debouncedValue, 50),
        enabled: debouncedValue.length > 1,
    });

    // File mode: show guardians for a specific file
    const { data: guardians = [], isLoading: isFileLoading } = useQuery({
        queryKey: ["guardians-by-file", fileId],
        queryFn: () => retirementApi.getGuardians(fileId!),
        enabled: !!fileId,
    });

    const isSearchMode = debouncedValue.length > 1;
    const displayData = isSearchMode ? searchData : (fileId ? guardians : []);
    const isLoading = isSearchMode ? isSearchLoading : isFileLoading;

    const endMutation = useMutation({
        mutationFn: (id: number) =>
            retirementApi.endGuardianship(id, { reason: "إنهاء وصاية" }),
        onSuccess: () => {
            toast.success("تم إنهاء الوصاية بنجاح");
            queryClient.invalidateQueries({ queryKey: ["guardians-by-file"] });
        },
        onError: () => {
            toast.error("خطأ في إنهاء الوصاية");
        },
    });


    const activeCount = displayData.filter((g: any) => g.isActive).length;

    const columns = [
        {
            key: "fullName",
            header: "الاسم",
            render: (row: any) => (
                <div className="flex items-center gap-3">
                    <div className="w-9 h-9 rounded-full bg-primary/10 flex items-center justify-center text-primary overflow-hidden">
                        {getPhotoUrl(resolvePersonalPhotoPath(row)) ? (
                            <img src={getPhotoUrl(resolvePersonalPhotoPath(row))!} alt="" className="w-full h-full object-cover" loading="lazy" />
                        ) : (
                            <ShieldCheck className="w-4 h-4" />
                        )}
                    </div>
                    <span className="font-bold text-foreground">{row.fullName}</span>
                </div>
            ),
        },
        {
            key: "nationalID",
            header: "الرقم الوطني",
            render: (row: any) => <span className="text-sm font-mono">{row.nationalID || "—"}</span>,
        },
        {
            key: "guardianshipDocNumber",
            header: "رقم وثيقة الوصاية",
            render: (row: any) => <span className="text-sm">{row.guardianshipDocNumber || "—"}</span>,
        },
        {
            key: "phone",
            header: "الهاتف",
            render: (row: any) => <span className="text-sm">{row.phone || "—"}</span>,
        },
        ...(isSearchMode ? [
            {
                key: "fileNumber",
                header: "رقم الملف",
                render: (row: any) => (
                    <Button
                        variant="link"
                        size="sm"
                        className="h-auto p-0 text-sm font-bold"
                        onClick={(e) => {
                            e.stopPropagation();
                            navigate(`/files/${row.fileID}`);
                        }}
                    >
                        {row.fileNumber || "—"}
                    </Button>
                ),
            },
            {
                key: "retireeMilitaryNumber",
                header: "الرقم العسكري",
                render: (row: any) => <span className="text-sm font-mono">{row.retireeMilitaryNumber || "—"}</span>,
            },
        ] : []),
        {
            key: "isActive",
            header: "الحالة",
            render: (row: any) => (
                <Badge variant={row.isActive ? "success" : "destructive"}>
                    {row.isActive ? "نشط" : "غير نشط"}
                </Badge>
            ),
        },
        {
            key: "actions",
            header: "",
            render: (row: any) => (
                <div className="flex gap-1">
                    {isSearchMode ? (
                        <Button
                            variant="ghost-action"
                            size="sm"
                            title="عرض الملف"
                            onClick={(e) => {
                                e.stopPropagation();
                                navigate(`/files/${row.fileID}`);
                            }}
                        >
                            <Eye className="w-4 h-4" />
                        </Button>
                    ) : (
                        <Button
                            variant="ghost-action"
                            size="sm"
                            title="عرض التفاصيل"
                            onClick={(e) => {
                                e.stopPropagation();
                                setSelected(row);
                            }}
                        >
                            <Eye className="w-4 h-4" />
                        </Button>
                    )}
                </div>
            ),
        },
    ];

    return (
        <CrudPageLayout
            title="إدارة الأوصياء"
            description="عرض وإدارة جميع الأوصياء عبر ملفات التقاعد"
            icon={<ShieldCheck className="w-6 h-6" />}
            columns={columns}
            data={displayData}
            loading={isLoading}
            searchable
            searchInHeader
            searchPlaceholder="ابحث بالاسم أو الرقم الوطني أو رقم الملف أو الرقم العسكري..."
            searchValue={searchTerm}
            onSearchChange={setSearchTerm}
            searchInputRef={searchInputRef}
            rowKey={(row: any) => row.guardianID}
            pagination={{
                page: 1,
                pageSize: 50,
                total: displayData.length,
                onPageChange: () => {},
            }}
            emptyMessage="ابحث عن وصي بالاسم أو الرقم الوطني أو رقم الملف"

        >
            {/* Stats */}
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-2 sm:gap-4 mb-6">
                <StatCard
                    title={isSearchMode ? "إجمالي النتائج" : "إجمالي الأوصياء"}
                    value={displayData.length}
                    icon={<ShieldCheck className="w-5 h-5" />}
                    variant="blue"
                    loading={isLoading}
                />
                <StatCard
                    title="النشطون"
                    value={activeCount}
                    icon={<Users className="w-5 h-5" />}
                    variant="success"
                    loading={isLoading}
                />
                <StatCard
                    title="غير النشطين"
                    value={displayData.length - activeCount}
                    icon={<Trash2 className="w-5 h-5" />}
                    variant="destructive"
                    loading={isLoading}
                />
            </div>

            {/* View Dialog */}
            <BaseFormDialog
                title="تفاصيل الوصي"
                isOpen={!!selected}
                onClose={() => setSelected(null)}
                size="md"
                submitLabel="إغلاق"
                onSubmit={() => setSelected(null)}
            >
                {selected && (
                    <div className="space-y-4">
                        <div className="flex items-center gap-4">
                            <div className="w-16 h-16 rounded-full bg-primary/10 flex items-center justify-center text-primary overflow-hidden">
                                {getPhotoUrl(resolvePersonalPhotoPath(selected)) ? (
                                    <img src={getPhotoUrl(resolvePersonalPhotoPath(selected))!} alt="" className="w-full h-full object-cover" loading="lazy" />
                                ) : (
                                    <ShieldCheck className="w-8 h-8" />
                                )}
                            </div>
                            <div>
                                <Heading level="h3" className="text-lg font-bold">{selected.fullName}</Heading>
                                <p className="text-sm text-muted-foreground">{selected.nationalID}</p>
                            </div>
                        </div>
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <InfoPair label="رقم وثيقة الوصاية" value={selected.guardianshipDocNumber || "—"} />
                            <InfoPair label="رقم الهاتف" value={selected.phone || "—"} />
                            <InfoPair
                                label="الحالة"
                                value={
                                    <Badge variant={selected.isActive ? "success" : "destructive"}>
                                        {selected.isActive ? "نشط" : "غير نشط"}
                                    </Badge>
                                }
                            />
                        </div>
                        <div className="flex gap-2 pt-4">
                            <Button
                                variant="outline"
                                size="sm"
                                onClick={() => navigate(`/files/${fileId}`)}
                            >
                                عرض الملف
                            </Button>
                            {selected.isActive && (
                                <Button
                                    variant="destructive"
                                    size="sm"
                                    onClick={async () => {
                                        const ok = await confirm({
                                            title: "هل أنت متأكد من إنهاء الوصاية؟",
                                            variant: "danger",
                                        });
                                        if (ok) {
                                            endMutation.mutate(selected.guardianID);
                                            setSelected(null);
                                        }
                                    }}
                                >
                                    إنهاء الوصاية
                                </Button>
                            )}
                        </div>
                    </div>
                )}
            </BaseFormDialog>
            {ConfirmDialogElement}
        </CrudPageLayout>
    );
}

import { useQuery } from "@tanstack/react-query";
import {
    BarChart3,
    FileSpreadsheet,
    FileText,
    Users
} from "lucide-react";
import { useCallback, useMemo, useState } from "react";

import {
    discrepancyApi,
    type DiscrepancyFilter,
    type RetireeDiscrepancy
} from "@/api/discrepancy";
import { ReportBarChart } from "@/components/common/charts/ReportBarChart";
import { ReportPieChart } from "@/components/common/charts/ReportPieChart";
import {
    Badge,
    Button,
    Card,
    CardContent,
    CardHeader,
    CardTitle,
    DataTable,
    Heading,
    NativeSelect,
    PageLayout,
    Skeleton,
    Text
} from "@/components/ui";
import type { CustomColumnDef } from "@/components/ui/DataTable";

export function KashfReportsPage() {
    const [filter, setFilter] = useState<DiscrepancyFilter>({
        pageNumber: 1,
        pageSize: 10
    });

    const { data: summary, isLoading: summaryLoading } = useQuery({
        queryKey: ["kashf-report-summary", filter],
        queryFn: () => discrepancyApi.getKashfReportSummary(filter)
    });

    const { data: reportData, isLoading: reportLoading } = useQuery({
        queryKey: ["kashf-report", filter],
        queryFn: () => discrepancyApi.getKashfReport(filter)
    });

    const handleFilterChange = useCallback((key: keyof DiscrepancyFilter, value: string | number | undefined) => {
        setFilter(prev => ({
            ...prev,
            [key]: value || undefined,
            pageNumber: 1
        }));
    }, []);



    const handleExport = useCallback(async (format: "excel" | "pdf") => {
        try {
            const response = await discrepancyApi.exportKashfReport(filter, format);
            const blob = new Blob([response.data], {
                type: format === "excel"
                    ? "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
                    : "application/pdf"
            });
            const url = window.URL.createObjectURL(blob);
            const link = document.createElement("a");
            link.href = url;
            link.download = `kashf_report_${new Date().toISOString().split("T")[0]}.${format === "excel" ? "xlsx" : "pdf"}`;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            window.URL.revokeObjectURL(url);
        } catch (error) {
            console.error("Export failed:", error);
        }
    }, [filter]);

    const formatDate = useCallback((dateString?: string) => {
        if (!dateString) return "---";
        try {
            const d = new Date(dateString);
            if (isNaN(d.getTime())) return "---";
            const day = String(d.getDate()).padStart(2, "0");
            const month = String(d.getMonth() + 1).padStart(2, "0");
            const year = d.getFullYear();
            return `${day}/${month}/${year}`;
        } catch {
            return "---";
        }
    }, []);

    const items = useMemo(() => (reportData?.items || []) as RetireeDiscrepancy[], [reportData]);

    const columns = useMemo<CustomColumnDef<RetireeDiscrepancy>[]>(() => [
        {
            key: "militaryNumber",
            header: "الرقم العسكري",
            accessor: (row) => row.militaryNumber || "---",
            className: "text-center font-bold",
        },
        {
            key: "fullName",
            header: "الاسم الرباعي",
            accessor: (row) => row.approvalFullName || "---",
        },
        {
            key: "rank",
            header: "الرتبة",
            accessor: (row) => row.approvalRankName || "---",
            className: "text-center",
        },
        {
            key: "unitName",
            header: "الوحدة",
            accessor: (row) => row.approvalUnitName || "---",
            className: "text-sm",
        },
        {
            key: "categoryName",
            header: "الفئة",
            accessor: (row) => row.categoryName || "---",
            className: "text-center",
        },
        {
            key: "gender",
            header: "الجنس",
            accessor: (row) => row.gender === 2 ? "أنثى" : "ذكر",
            className: "text-center",
        },
        {
            key: "retirementDate",
            header: "تاريخ الإحالة",
            accessor: (row) => formatDate(row.approvalRetirementDate),
            className: "text-center",
        },
        {
            key: "status",
            header: "الحالة",
            className: "text-center",
            render: (row) => (
                <Badge
                    variant={
                        row.fileID ? "success" :
                        row.isProcessed ? "warning" : "secondary"
                    }
                >
                    {row.fileID ? "ملف مكتمل" :
                     row.isProcessed ? "تمت المعالجة" : "كشف إحالة فقط"}
                </Badge>
            ),
        },
    ], [formatDate]);

    const genderData = useMemo(() => {
        const male = summary?.byGender?.find(g => g.name === "ذكر")?.count ?? 0;
        const female = summary?.byGender?.find(g => g.name === "أنثى")?.count ?? 0;
        return [
            ...(male > 0 ? [{ name: "ذكور", count: male }] : []),
            ...(female > 0 ? [{ name: "إناث", count: female }] : [])
        ];
    }, [summary]);

    const unitData = useMemo(
        () => (summary?.byUnit || []).filter(u => u.count > 0),
        [summary]
    );

    const rankData = useMemo(
        () => (summary?.byRank || []).filter(r => r.count > 0),
        [summary]
    );

    const categoryData = useMemo(
        () => (summary?.byCategory || []).filter(c => c.count > 0),
        [summary]
    );

    if (summaryLoading) {
        return (
            <div className="space-y-4">
                <Skeleton className="h-8 w-48" />
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                    {[...Array(4)].map((_, i) => (
                        <Skeleton key={i} className="h-24 w-full" />
                    ))}
                </div>
            </div>
        );
    }

    return (
        <PageLayout>
            <div className="flex items-center justify-between mb-6">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-lg bg-primary/10 flex items-center justify-center">
                        <BarChart3 className="w-5 h-5 text-primary" />
                    </div>
                    <div>
                        <Heading level="h1">تحليل كشوفات الإحالة إلى التقاعد</Heading>
                        <p className="text-sm text-muted-foreground">التقارير التفصيلية لتحليل كشوفات الإحالة إلى التقاعد</p>
                    </div>
                </div>
                <div className="flex items-center gap-2">
                    <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleExport("excel")}
                        className="gap-2"
                    >
                        <FileSpreadsheet className="w-4 h-4" />
                        تصدير Excel
                    </Button>
                    <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleExport("pdf")}
                        className="gap-2"
                    >
                        <FileText className="w-4 h-4" />
                        تصدير PDF
                    </Button>
                </div>
            </div>

            {/* Filters */}
            <Card className="mb-6">

                <CardContent>
                    <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-6 gap-4">
                        <div className="space-y-2">
                            <Text variant="caption">الوحدة</Text>
                            <NativeSelect
                                placeholder="كل الوحدات"
                                options={
                                    summary?.byUnit?.map(u => ({ label: u.name, value: u.name })) || []
                                }
                                value={filter.unitName || ""}
                                onChange={(val) => handleFilterChange("unitName", val)}
                            />
                        </div>
                        <div className="space-y-2">
                            <Text variant="caption">الرتبة</Text>
                            <NativeSelect
                                placeholder="كل الرتب"
                                options={
                                    summary?.byRank?.map(r => ({ label: r.name, value: r.name })) || []
                                }
                                value={filter.rankName || ""}
                                onChange={(val) => handleFilterChange("rankName", val)}
                            />
                        </div>
                        <div className="space-y-2">
                            <Text variant="caption">الفئة</Text>
                            <NativeSelect
                                placeholder="كل الفئات"
                                options={
                                    summary?.byCategory?.map(c => ({ label: c.name, value: c.name })) || []
                                }
                                value={filter.categoryName || ""}
                                onChange={(val) => handleFilterChange("categoryName", val)}
                            />
                        </div>
                        <div className="space-y-2">
                            <Text variant="caption">الجنس</Text>
                            <NativeSelect
                                placeholder="الكل"
                                options={[
                                    { label: "ذكر", value: "1" },
                                    { label: "أنثى", value: "2" }
                                ]}
                                value={filter.gender?.toString() || ""}
                                onChange={(val) => handleFilterChange("gender", val ? Number(val) : undefined)}
                            />
                        </div>
                        <div className="space-y-2">
                            <Text variant="caption">حالة المعالجة</Text>
                            <NativeSelect
                                placeholder="الكل"
                                options={[
                                    { label: "معالج", value: "processed" },
                                    { label: "معلق", value: "pending" }
                                ]}
                                value={filter.processingStatus || ""}
                                onChange={(val) => handleFilterChange("processingStatus", val)}
                            />
                        </div>
                        <div className="space-y-2">
                            <Text variant="caption">حالة الملفات</Text>
                            <NativeSelect
                                placeholder="الكل"
                                options={[
                                    { label: "ملف مكتمل", value: "file_created" },
                                    { label: "تمت المعالجة فقط", value: "processed_only" },
                                    { label: "كشف إحالة فقط", value: "referral_only" }
                                ]}
                                value={filter.fileStatus || ""}
                                onChange={(val) => handleFilterChange("fileStatus", val)}
                            />
                        </div>
                    </div>
                </CardContent>
            </Card>
      {/* Summary Cards */}
            <div className="grid grid-cols-2 md:grid-cols-2 lg:grid-cols-4 gap-2 sm:gap-4 mb-6">
                <SummaryCard
                    title="إجمالي السجلات"
                    value={summary?.totalCount || 0}
                    icon={<Users className="w-4 h-4 text-blue-500" />}
                />
                <SummaryCard
                    title="المعالجات"
                    value={summary?.processedCount || 0}
                    icon={<BarChart3 className="w-4 h-4 text-emerald-500" />}
                    variant="success"
                />
                <SummaryCard
                    title="المعلقة"
                    value={summary?.pendingCount || 0}
                    icon={<BarChart3 className="w-4 h-4 text-amber-500" />}
                    variant="warning"
                />
                <SummaryCard
                    title="ملفات مكتملة"
                    value={summary?.fileCreatedCount || 0}
                    icon={<FileText className="w-4 h-4 text-blue-500" />}
                    variant="info"
                />
            </div>

            {/* Charts Section */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
                {genderData.length > 0 ? (
                    <ReportPieChart
                        title="التوزيع حسب الجنس"
                        data={genderData}
                        nameKey="name"
                        valueKey="count"
                        innerRadius={60}
                        height={320}
                    />
                ) : (
                    <ChartEmptyCard title="التوزيع حسب الجنس" />
                )}
                <ReportBarChart
                    title="التوزيع حسب الوحدة"
                    data={unitData.map(u => ({ name: u.name, count: u.count }))}
                    xKey="name"
                    yKeys={[{ key: "count", color: "hsl(var(--primary))", label: "عدد السجلات" }]}
                    horizontal={unitData.length > 6}
                    height={320}
                />
                {rankData.length > 0 ? (
                    <ReportPieChart
                        title="التوزيع حسب الرتبة"
                        data={rankData as unknown as Record<string, unknown>[]}
                        nameKey="name"
                        valueKey="count"
                        height={320}
                    />
                ) : (
                    <ChartEmptyCard title="التوزيع حسب الرتبة" />
                )}
                <ReportBarChart
                    title="التوزيع حسب الفئة"
                    data={categoryData.map(c => ({ name: c.name, count: c.count }))}
                    xKey="name"
                    yKeys={[{ key: "count", color: "hsl(var(--primary))", label: "عدد السجلات" }]}
                    horizontal={categoryData.length > 6}
                    height={320}
                />
            </div>

            {/* Detailed Table */}
            <Card>
                <CardHeader>
                    <CardTitle className="text-sm font-medium">
                        بيانات كشوف الإحالة
                        {reportData?.totalCount ? ` (${reportData.totalCount.toLocaleString()})` : ""}
                    </CardTitle>
                </CardHeader>
                <CardContent>
                    <DataTable
                        columns={columns}
                        data={items}
                        loading={reportLoading}
                        pagination={{
                            page: filter.pageNumber,
                            pageSize: filter.pageSize,
                            total: reportData?.totalCount || 0,
                            pageSizeOptions: [10, 25, 50, 100],
                            onPageSizeChange: (pageSize) => setFilter(prev => ({ ...prev, pageSize, pageNumber: 1 })),
                            onPageChange: (page) => setFilter(prev => ({ ...prev, pageNumber: page })),
                        }}
                        emptyMessage="لا توجد بيانات"
                    />
                </CardContent>
            </Card>
        </PageLayout>
    );
}

// Summary Card Component
function SummaryCard({
    title,
    value,
    icon,
    variant = "default"
}: {
    title: string;
    value: number;
    icon: React.ReactNode;
    variant?: "default" | "success" | "warning" | "info" | "destructive";
}) {
    const variantStyles = {
        default: "bg-primary/5",
        success: "bg-emerald-500/5",
        warning: "bg-amber-500/5",
        info: "bg-blue-500/5",
        destructive: "bg-rose-500/5"
    };

    return (
        <Card className={variantStyles[variant]}>
            <CardContent className="p-4">
                <div className="flex items-center justify-between">
                    <div>
                        <p className="text-sm font-medium text-muted-foreground">{title}</p>
                        <p className="text-lg md:text-xl lg:text-2xl font-bold mt-1">{value.toLocaleString()}</p>
                    </div>
                    <div className="w-10 h-10 rounded-lg bg-background flex items-center justify-center">
                        {icon}
                    </div>
                </div>
            </CardContent>
        </Card>
    );
}

// Empty state for charts with no data
function ChartEmptyCard({ title }: { title: string }) {
    return (
        <Card className="mb-6">
            <CardHeader className="pb-2">
                <CardTitle className="text-sm font-bold">{title}</CardTitle>
            </CardHeader>
            <CardContent>
                <div className="flex items-center justify-center h-[220px] text-muted-foreground text-sm">
                    لا توجد بيانات لعرضها
                </div>
            </CardContent>
        </Card>
    );
}

