/* ------------------------------------------------------------------ */

const STATUS_OPTIONS = [
    { value: "all", label: "الكل" },
    { value: "فعال", label: "فعال" },
    { value: "منتهي", label: "منتهي" },
    { value: "ملغي", label: "ملغي" },
    { value: "مفقود", label: "مفقود" },
    { value: "تالف", label: "تالف" },
];

const TYPE_OPTIONS = [
    { value: "all", label: "الكل" },
    { value: "إلكتروني", label: "إلكتروني" },
    { value: "يدوي", label: "يدوي" },
];



const CHANGE_REASONS = [
    "انتهاء الصلاحية",
    "تلف",
    "فقدان",
    "تغيير بيانات",
    "أخرى",
];

const RECIPIENT_TYPES = [
    RECIPIENT_TYPE_AR.RETIREE,
    RECIPIENT_TYPE_AR.AGENT,
    RECIPIENT_TYPE_AR.GUARDIAN,
    RECIPIENT_TYPE_AR.ENTITLED,
];

/* ------------------------------------------------------------------ */
/*  Page Component                                                     */
/* ------------------------------------------------------------------ */

export function PaymentCardsPage() {
    const navigate = useNavigate();
    const [search, setSearch] = useState("");
    const [statusFilter, setStatusFilter] = useState("all");
    const [typeFilter, setTypeFilter] = useState("all");
    const [expiringFilter, setExpiringFilter] = useState(false);

    const [detailItem, setDetailItem] = useState<PaymentBookReview | null>(null);

    const [showIssueDialog, setShowIssueDialog] = useState(false);
    const [issueFileId, setIssueFileId] = useState<number | null>(null);

    const [editItem, setEditItem] = useState<PaymentBookReview | null>(null);

    const [retireeSearchOpen, setRetireeSearchOpen] = useState(false);
    const [retireeSearch, setRetireeSearch] = useState("");
    const [selectedRetiree, setSelectedRetiree] = useState<{
        retireeId: number;
        fileId: number;
        name: string;
        nationalId: string;
    } | null>(null);
    const { confirm, ConfirmDialogElement } = useConfirm();

    /* ---- Lookups ---- */
    const getRecipientOptions = useMemo(
        () => async (_type: string) => [] as { id: number; name: string }[],
        []
    );

    const lookups = useMemo(
        () => ({
            changeReasons: CHANGE_REASONS,
            recipientTypes: RECIPIENT_TYPES,
            getRecipientOptions,
        }),
        [getRecipientOptions]
    );

    /* ---- Stats ---- */
    const { data: stats } = useQuery({
        queryKey: ["payment-book-stats"],
        queryFn: () => paymentBookReviewApi.getStats(),
    });

    /* ---- Main data ---- */
    const { data, isLoading } = useQuery({
        queryKey: ["payment-cards", { search, statusFilter, typeFilter, expiringFilter }],
        queryFn: () =>
            paymentBookReviewApi.getReview({
                page: 1,
                pageSize: 100,
                search: search || undefined,
                status: statusFilter === "all" ? undefined : statusFilter,
                bookType: typeFilter === "all" ? undefined : typeFilter,
                expiringWithinDays: expiringFilter ? 30 : undefined,
            }),
    });

    /* ---- Retiree search ---- */
    const { data: retireeResults, isLoading: isSearching } = useQuery({
        queryKey: ["retiree-search", retireeSearch],
        queryFn: () =>
            retireeApi.getAll({
                search: retireeSearch,
                page: 1,
                pageSize: 10,
            }),
        enabled: retireeSearch.length >= 2,
    });

    const rows = useMemo(() => data?.items ?? [], [data]);

    /* ---- Delete mutation ---- */
    const deleteMutation = useApiMutation(
        async (item: PaymentBookReview) => {
            await retirementApi.deletePaymentBook(item.paymentBookID);
        },
        {
            successMessage: "تم حذف الدفتر بنجاح",
            invalidateKeys: [["payment-cards"], ["payment-book-stats"]],
        }
    );

    /* ---- Save (issue) mutation ---- */
    const issueMutation = useApiMutation(
        async (values: BookFormValues) => {
            const formData = new FormData();
            formData.append("FileID", issueFileId!.toString());
            formData.append(
                "IssueDate",
                values.issueDate
                    ? new Date(values.issueDate).toISOString()
                    : new Date().toISOString()
            );
            formData.append("BookType", values.bookType ?? "");
            if (values.bookType === "يدوي") {
                if (values.bookNumber) formData.append("BookNumber", values.bookNumber);
                if (values.legacyColor) formData.append("LegacyColor", values.legacyColor);
            } else {
                if (values.expiryDate)
                    formData.append("ExpiryDate", new Date(values.expiryDate).toISOString());
                if (values.changeReason) formData.append("ChangeReason", values.changeReason);
            }
            if (values.recipientName) formData.append("RecipientName", values.recipientName);
            if (values.recipientType) formData.append("RecipientType", values.recipientType);
            if (values.notes) formData.append("Notes", values.notes);
            if (values.issuingBranchID)
                formData.append("IssuingBranchID", values.issuingBranchID.toString());
            if (values.bookImage instanceof File) {
                formData.append("BookImage", values.bookImage);
            }
            return retirementApi.createPaymentBook(formData);
        },
        {
            successMessage: "تم إصدار البطاقة بنجاح",
            invalidateKeys: [["payment-cards"], ["payment-book-stats"]],
            onSuccess: () => {
                setShowIssueDialog(false);
                setIssueFileId(null);
                setSelectedRetiree(null);
            },
        }
    );

    /* ---- Edit mutation ---- */
    const editMutation = useApiMutation(
        async (values: BookFormValues) => {
            const updateDto = {
                bookNumber: values.bookNumber,
                issueDate: values.issueDate
                    ? new Date(values.issueDate).toISOString()
                    : undefined,
                expiryDate: values.expiryDate
                    ? new Date(values.expiryDate).toISOString()
                    : undefined,
                status: values.status,
                legacyColor: values.legacyColor,
                changeReason: values.changeReason,
                recipientName: values.recipientName,
                recipientType: values.recipientType,
                notes: values.notes,
                issuingBranchID: values.issuingBranchID || null,
            };
            return retirementApi.updatePaymentBook(editItem!.paymentBookID, updateDto);
        },
        {
            successMessage: "تم تعديل البطاقة بنجاح",
            invalidateKeys: [["payment-cards"], ["payment-book-stats"]],
            onSuccess: () => setEditItem(null),
        }
    );

    /* ---- Columns ---- */
    const columns = useMemo(
        () => [
            {
                key: "bookNumber",
                header: "رقم الدفتر",
                render: (row: PaymentBookReview) => (
                    <span className="font-mono font-bold text-xs text-primary">
                        {row.bookNumber}
                    </span>
                ),
            },
            {
                key: "retireeName",
                header: "المتقاعد",
                render: (row: PaymentBookReview) => (
                    <div>
                        <p className="font-medium text-sm">{row.retireeName || "—"}</p>
                        <div className="flex items-center gap-2 text-xs text-muted-foreground flex-wrap">
                            {row.fileNumber && <span>ملف: {row.fileNumber}</span>}
                            {row.militaryNumber && <span>عسكري: {row.militaryNumber}</span>}
                        </div>
                    </div>
                ),
            },
            {
                key: "bookType",
                header: "النوع",
                render: (row: PaymentBookReview) => (
                    <Badge variant="outline">{row.bookType || "—"}</Badge>
                ),
            },
            {
                key: "issuingBranchName",
                header: "الفرع",
                render: (row: PaymentBookReview) => (
                    <span className="text-sm">{row.issuingBranchName || "—"}</span>
                ),
            },
            {
                key: "issueDate",
                header: "تاريخ الإصدار",
                render: (row: PaymentBookReview) => (
                    <span className="text-sm">
                        {row.issueDate ? new Date(row.issueDate).toLocaleDateString("ar-SA") : "—"}
                    </span>
                ),
            },
            {
                key: "expiryDate",
                header: "تاريخ الانتهاء",
                render: (row: PaymentBookReview) => {
                    if (!row.expiryDate) return <span className="text-sm">—</span>;
                    const date = new Date(row.expiryDate);
                    const now = new Date();
                    const daysLeft = Math.ceil(
                        (date.getTime() - now.getTime()) / (1000 * 60 * 60 * 24)
                    );
                    const isExpiringSoon = daysLeft >= 0 && daysLeft <= 30;
                    const isExpired = daysLeft < 0;
                    return (
                        <div className="flex items-center gap-1">
                            {isExpiringSoon && (
                                <AlertTriangle className="h-4 w-4 text-amber-500" />
                            )}
                            {isExpired && <XCircle className="h-4 w-4 text-red-500" />}
                            <span
                                className={`text-sm ${
                                    isExpiringSoon
                                        ? "text-amber-600 font-medium"
                                        : isExpired
                                          ? "text-red-600"
                                          : ""
                                }`}
                            >
                                {new Date(row.expiryDate).toLocaleDateString("ar-SA")}
                            </span>
                        </div>
                    );
                },
            },
            {
                key: "status",
                header: "الحالة",
                render: (row: PaymentBookReview) => (
                    <StatusBadge status={row.status ?? ""} config={PAYMENT_BOOK_STATUS} />
                ),
            },
            {
                key: "actions",
                header: "",
                render: (row: PaymentBookReview) => (
                    <div className="flex items-center gap-1">
                        <Button
                            size="sm"
                            variant="ghost-action"
                            onClick={(e) => {
                                e.stopPropagation();
                                setDetailItem(row);
                            }}
                        >
                            <Eye className="h-4 w-4" />
                        </Button>
                        <Button
                            size="sm"
                            variant="ghost-action"
                            onClick={(e) => {
                                e.stopPropagation();
                                setEditItem(row);
                            }}
                        >
                            <Pencil className="h-4 w-4" />
                        </Button>
                        <Button
                            size="sm"
                            variant="ghost-action"
                            onClick={(e) => {
                                e.stopPropagation();
                                navigate(`/payment-books/${row.paymentBookID}/print`);
                            }}
                        >
                            <Printer className="h-4 w-4" />
                        </Button>
                        <Button
                            size="sm"
                            variant="destructive"
                            onClick={async (e) => {
                                e.stopPropagation();
                                const ok = await confirm({
                                    title: "هل أنت متأكد من حذف هذا الدفتر؟",
                                    variant: "danger",
                                });
                                if (ok) {
                                    deleteMutation.mutate(row);
                                }
                            }}
                        >
                            <XCircle className="h-4 w-4" />
                        </Button>
                    </div>
                ),
            },
        ],
        []
    );

    /* ---- Render ---- */
    return (
        <CrudPageLayout
            title="بطاقات الصرف"
            description="إدارة دفاتر الصرف وبطاقات الصرف للمتقاعدين"
            columns={columns}
            data={rows}
            loading={isLoading}
            rowKey={(row) => row.paymentBookID}
            onRowClick={setDetailItem}
            searchable
            searchInHeader
            searchPlaceholder="بحث بالاسم / الرقم العسكري / رقم الملف / رقم الدفتر..."
            searchValue={search}
            onSearchChange={setSearch}
            createLabel="إصدار بطاقة جديدة"
            onCreateClick={() => setRetireeSearchOpen(true)}
            headerActions={
                <div className="flex gap-2">
                    <NativeSelect
                        value={statusFilter}
                        onChange={setStatusFilter}
                        options={STATUS_OPTIONS}
                        placeholder="الحالة"
                    />
                    <NativeSelect
                        value={typeFilter}
                        onChange={setTypeFilter}
                        options={TYPE_OPTIONS}
                        placeholder="النوع"
                    />
                    <Button
                        variant={expiringFilter ? "warning" : "outline"}
                        size="sm"
                        onClick={() => setExpiringFilter(!expiringFilter)}
                    >
                        <AlertTriangle className="h-4 w-4 ml-1" />
                        تنتهي خلال 30 يوم
                    </Button>
                </div>
            }
        >
            {stats && (
                <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-2 sm:gap-4 mb-6">
                    <StatCard
                        title="الدفاتر الفعّالة"
                        value={stats.activeCount}
                        icon={<CheckCircle2 />}
                        variant="success"
                    />
                    <StatCard
                        title="المنتهية"
                        value={stats.expiredCount}
                        icon={<Clock />}
                        variant="warning"
                    />
                    <StatCard
                        title="المفقودة"
                        value={stats.lostCount}
                        icon={<XCircle />}
                        variant="destructive"
                    />
                    <StatCard
                        title="التالفة"
                        value={stats.damagedCount}
                        icon={<AlertTriangle />}
                        variant="destructive"
                    />
                    <StatCard
                        title="المجموع"
                        value={stats.totalCount}
                        icon={<CreditCard />}
                        variant="info"
                    />
                </div>
            )}

            {/* Retiree Search Dialog */}
            <BaseFormDialog
                open={retireeSearchOpen}
                onOpenChange={setRetireeSearchOpen}
                title="بحث عن المتتقاعد"
                description="أدخل الرقم الوطني أو اسم المتتقاعد للبحث"
                onSubmit={async () => {
                    if (!selectedRetiree) {
                        toast.error("يرجى اختيار متتقاعد");
                        return;
                    }
                    setIssueFileId(selectedRetiree.fileId);
                    setRetireeSearchOpen(false);
                    setShowIssueDialog(true);
                }}
                submitLabel="إصدار بطاقة"
                size="lg"
            >
                <FormField label="البحث">
                    <Input
                        value={retireeSearch}
                        onChange={(e) => setRetireeSearch(e.target.value)}
                        placeholder="أدخل الرقم الوطني أو الاسم..."
                    />
                </FormField>
                {isSearching && (
                    <p className="text-sm text-muted-foreground mt-2">جاري البحث...</p>
                )}
                {retireeResults && retireeResults.items.length > 0 && (
                    <div className="mt-3 space-y-2 max-h-60 overflow-auto">
                        {retireeResults.items.map((r) => (
                            <div
                                key={r.retireeID}
                                className={`p-3 border rounded-lg cursor-pointer transition-colors ${
                                    selectedRetiree?.retireeId === r.retireeID
                                        ? "border-blue-500 bg-blue-50"
                                        : "border-border hover:border-blue-300"
                                }`}
                                onClick={() => {
                                    setSelectedRetiree({
                                        retireeId: r.retireeID,
                                        fileId: r.fileID ?? 0,
                                        name: r.fullName,
                                        nationalId: r.nationalID,
                                    });
                                }}
                            >
                                <div className="font-medium">{r.fullName}</div>
                                <div className="text-sm text-muted-foreground">رقم وطني: {r.nationalID}</div>
                                <div className="text-sm text-muted-foreground">رقم عسكري: {r.militaryNumber || "—"}</div>
                            </div>
                        ))}
                    </div>
                )}
                {retireeResults &&
                    retireeResults.items.length === 0 &&
                    retireeSearch.length >= 2 && (
                        <EmptyState icon={Inbox} title="لا توجد نتائج" />
                    )}
            </BaseFormDialog>

            {/* Issue New Card Dialog */}
            {showIssueDialog && issueFileId && (
                <PaymentBookDialog
                    open={showIssueDialog}
                    onOpenChange={setShowIssueDialog}
                    mode="create"
                    lookups={lookups}
                    onSubmit={async (values: BookFormValues) => {
                        await issueMutation.mutateAsync(values);
                    }}
                />
            )}

            {/* Edit Dialog */}
            {editItem && (
                <PaymentBookDialog
                    open={!!editItem}
                    onOpenChange={(open) => {
                        if (!open) setEditItem(null);
                    }}
                    mode="edit"
                    initialData={{
                        bookNumber: editItem.bookNumber ?? "",
                        bookType: editItem.bookType ?? "إلكتروني",
                        issueDate: editItem.issueDate ?? "",
                        expiryDate: editItem.expiryDate ?? "",
                        status: editItem.status ?? "فعال",
                        legacyColor: editItem.legacyColor ?? "",
                        changeReason: editItem.changeReason ?? "",
                        recipientName: editItem.recipientName ?? "",
                        recipientType: editItem.recipientType ?? "",
                        notes: editItem.notes ?? "",
                        issuingBranchID: Number(editItem.issuingBranchID) || 0,
                    }}
                    lookups={lookups}
                    onSubmit={async (values: BookFormValues) => {
                        await editMutation.mutateAsync(values);
                    }}
                />
            )}

            {/* Detail Dialog */}
            <BaseFormDialog
                open={!!detailItem}
                onOpenChange={(open) => {
                    if (!open) setDetailItem(null);
                }}
                title="تفاصيل دفتر الصرف"
                submitLabel="إغلاق"
                onSubmit={async () => {
                    setDetailItem(null);
                }}
                size="lg"
            >
                {detailItem && (
                    <>
                        <FormSection title="بيانات المتتقاعد">
                            <InfoPair label="اسم المتتقاعد" value={detailItem.retireeName} />
                            <InfoPair label="رقم الملف" value={detailItem.fileNumber} />
                        </FormSection>
                        <Separator className="my-4" />
                        <FormSection title="بيانات الدفتر">
                            <InfoPair label="رقم الدفتر" value={detailItem.bookNumber} />
                            <InfoPair label="النوع" value={detailItem.bookType} />
                            <InfoPair
                                label="الفرع"
                                value={detailItem.issuingBranchName}
                            />
                            <InfoPair
                                label="الحالة"
                                value={
                                    <StatusBadge status={detailItem.status ?? ""} config={PAYMENT_BOOK_STATUS} />
                                }
                            />
                        </FormSection>
                        <Separator className="my-4" />
                        <FormSection title="التواريخ">
                            <InfoPair
                                label="تاريخ الإصدار"
                                value={detailItem.issueDate ? new Date(detailItem.issueDate).toLocaleDateString("ar-SA") : "—"}
                            />
                            <InfoPair
                                label="تاريخ الانتهاء"
                                value={detailItem.expiryDate ? new Date(detailItem.expiryDate).toLocaleDateString("ar-SA") : "—"}
                            />
                        </FormSection>
                        {detailItem.recipientName && (
                            <>
                                <Separator className="my-4" />
                                <FormSection title="المستفيد">
                                    <InfoPair
                                        label="اسم المستفيد"
                                        value={detailItem.recipientName}
                                    />
                                    <InfoPair
                                        label="نوع المستفيد"
                                        value={detailItem.recipientType}
                                    />
                                </FormSection>
                            </>
                        )}
                        {detailItem.bookImagePaths && detailItem.bookImagePaths.length > 0 && (
                            <>
                                <Separator className="my-4" />
                                <FormSection title="صورة الدفتر">
                                    <div className="flex flex-wrap gap-2">
                                        {detailItem.bookImagePaths.map((img, i) => (
                                            <img
                                                key={i}
                                                src={img}
                                                alt={`صورة الدفتر ${i + 1}`}
                                                className="max-w-full max-h-64 rounded border"
                                            />
                                        ))}
                                    </div>
                                </FormSection>
                            </>
                        )}
                    </>
                )}
            </BaseFormDialog>
            {ConfirmDialogElement}
        </CrudPageLayout>
    );
}

import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import {
    Activity,
    ChevronDown,
    ChevronUp,
    Eye,
    FolderOpen,
    Heart,
    MapPin,
    Phone,
    Printer,
    Search,
    Users,
} from "lucide-react";
import { useMemo, useRef, useState } from "react";
import { useForm } from "react-hook-form";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { z } from "zod";

import { lookupApi,socialResearchApi } from "@/api/pension";
import { SearchDialog } from "@/components/common/SearchDialog";
import {
    Badge,
    BaseFormDialog,
    Button,
    CrudPageLayout,
    DateInput,
    FormField,
    Input,
    NativeSelect,
    StatCard,
    yemenPhoneSchema,
} from "@/components/ui";
import { useDebouncedSearch } from "@/hooks/useDebouncedSearch";
import type {
    SocialResearchFilters,
    SocialResearchResult,
} from "@/types/pension";

const updateSchema = z.object({
    phone: yemenPhoneSchema.optional().or(z.literal("")),
    governorate: z.string().optional(),
    city: z.string().optional(),
});

type UpdateForm = z.infer<typeof updateSchema>;

export function SocialResearchPage() {
    const navigate = useNavigate();
    const queryClient = useQueryClient();
    const { searchTerm, setSearchTerm, debouncedValue } =
        useDebouncedSearch();
    const searchInputRef = useRef<HTMLInputElement>(null);
    const [page, setPage] = useState(1);

    const [showFilters, setShowFilters] = useState(false);
    const [filters, setFilters] = useState<SocialResearchFilters>({});
    const [updateTarget, setUpdateTarget] =
        useState<SocialResearchResult | null>(null);

    const queryFilters = useMemo(
        () => ({
            ...filters,
            hasFiles: true,
            search: debouncedValue || undefined,
            page,
            pageSize: 20,
        }),
        [filters, debouncedValue, page]
    );

    const { data, isLoading } = useQuery({
        queryKey: ["social-research", queryFilters],
        queryFn: () => socialResearchApi.search(queryFilters),
    });

    const { data: socialStatuses = [] } = useQuery({
        queryKey: ["lookup", "socialStatuses"],
        queryFn: () => lookupApi.getSocialStatuses(),
    });

    const { data: healthStatuses = [] } = useQuery({
        queryKey: ["lookup", "healthStatuses"],
        queryFn: () => lookupApi.getHealthStatuses(),
    });

    const { data: governorates = [] } = useQuery({
        queryKey: ["lookup", "governorates"],
        queryFn: () => lookupApi.getGovernorates(),
    });

    const { data: categories = [] } = useQuery({
        queryKey: ["lookup", "categories"],
        queryFn: () => lookupApi.getCategories(),
    });

    const items = data?.items || [];
    const totalCount = data?.totalCount || 0;

    const stats = useMemo(() => {
        const total = totalCount;
        const alive = items.filter((r) => r.isAlive).length;
        const deceased = items.filter((r) => !r.isAlive).length;
        return { total, alive, deceased };
    }, [items, totalCount]);

    const updateForm = useForm<UpdateForm>({
        resolver: zodResolver(updateSchema),
        values: updateTarget
            ? {
                phone: updateTarget.phone || "",
                governorate: updateTarget.governorate || "",
                city: updateTarget.city || "",
            }
            : undefined,
    });

    const updateMutation = useMutation({
        mutationFn: async (data: UpdateForm) => {
            const { default: api } = await import("@/api/axios");
            return api.put(`/social-research/${updateTarget!.retireeID}`, data);
        },
        onSuccess: () => {
            toast.success("تم التحديث بنجاح");
            queryClient.invalidateQueries({ queryKey: ["social-research"] });
            setUpdateTarget(null);
        },
        onError: () => {
            toast.error("خطأ في التحديث");
        },
    });

    const columns = [
        {
            key: "fullName",
            header: "الاسم",
            render: (row: SocialResearchResult) => (
                <span className="font-bold">{row.fullName}</span>
            ),
        },
        {
            key: "nationalID",
            header: "الرقم الوطني",
            render: (row: SocialResearchResult) => (
                <span className="text-sm font-mono">{row.nationalID || "—"}</span>
            ),
        },
        {
            key: "militaryNumber",
            header: "الرقم العسكري",
            render: (row: SocialResearchResult) => (
                <span className="text-sm font-mono text-primary font-bold">
                    {row.militaryNumber || "—"}
                </span>
            ),
        },
        {
            key: "linkNumber",
            header: "رقم الربط",
            render: (row: SocialResearchResult) => (
                <span className="text-sm font-mono">{row.linkNumber || "—"}</span>
            ),
        },
        {
            key: "rankName",
            header: "الرتبة",
            render: (row: SocialResearchResult) => (
                <span className="text-sm">{row.rankName || "—"}</span>
            ),
        },
        {
            key: "unitName",
            header: "الوحدة",
            render: (row: SocialResearchResult) => (
                <span className="text-sm">{row.unitName || "—"}</span>
            ),
        },
        {
            key: "socialStatusName",
            header: "الحالة الاجتماعية",
            render: (row: SocialResearchResult) => (
                <Badge variant="outline">{row.socialStatusName || "—"}</Badge>
            ),
        },
        {
            key: "phone",
            header: "الهاتف",
            render: (row: SocialResearchResult) => (
                <span className="text-sm font-mono flex items-center gap-1">
                    <Phone className="w-3 h-3 text-muted-foreground" />
                    {row.phone || "—"}
                </span>
            ),
        },
        {
            key: "governorate",
            header: "المحافظة",
            render: (row: SocialResearchResult) => (
                <span className="text-sm flex items-center gap-1">
                    <MapPin className="w-3 h-3 text-muted-foreground" />
                    {row.governorate || "—"}
                </span>
            ),
        },
        {
            key: "isAlive",
            header: "الحالة",
            render: (row: SocialResearchResult) => (
                <Badge variant={row.isAlive ? "success" : "danger"}>
                    {row.isAlive ? "على قيد الحياة" : "متوفى"}
                </Badge>
            ),
        },
        {
            key: "fileCount",
            header: "عدد الملفات",
            render: (row: SocialResearchResult) => (
                <span className="text-sm font-bold">{row.fileCount}</span>
            ),
        },
        {
            key: "actions",
            header: "إجراءات",
            render: (row: SocialResearchResult) => (
                <div className="flex gap-1 items-center">
                    <Button
                        variant="ghost"
                        size="sm"
                        className="text-blue-600 dark:text-blue-400 hover:bg-blue-500/15 hover:text-blue-700 dark:hover:text-blue-300"
                        title="عرض التفاصيل"
                        onClick={() => navigate(`/retirees/${row.retireeID}`)}
                    >
                        <Eye className="w-4 h-4 text-blue-600 dark:text-blue-400 shrink-0" />
                    </Button>
                    {row.fileID && (
                        <Button
                            variant="ghost"
                            size="sm"
                            className="text-emerald-600 dark:text-emerald-400 hover:bg-emerald-500/15 hover:text-emerald-700 dark:hover:text-emerald-300"
                            title="عرض الملف التقاعدي"
                            onClick={() => navigate(`/files/${row.fileID}`)}
                        >
                            <FolderOpen className="w-4 h-4 text-emerald-600 dark:text-emerald-400 shrink-0" />
                        </Button>
                    )}
                    <Button
                        variant="ghost"
                        size="sm"
                        className="text-amber-600 dark:text-amber-400 hover:bg-amber-500/15 hover:text-amber-700 dark:hover:text-amber-300"
                        title="طباعة المباينة"
                        onClick={() =>
                            navigate(`/retirees/${row.retireeID}/statement`)
                        }
                    >
                        <Printer className="w-4 h-4 text-amber-600 dark:text-amber-400 shrink-0" />
                    </Button>
                    <Button
                        variant="ghost"
                        size="sm"
                        className="text-indigo-600 dark:text-indigo-400 hover:bg-indigo-500/15 hover:text-indigo-700 dark:hover:text-indigo-300"
                        title="تحديث البيانات"
                        onClick={() => setUpdateTarget(row)}
                    >
                        <Activity className="w-4 h-4 text-indigo-600 dark:text-indigo-400 shrink-0" />
                    </Button>
                </div>
            ),
        },
    ];

    return (
        <CrudPageLayout
            title="البحث الاجتماعي"
            description="بحث شامل عن المتقاعدين وبياناتهم الاجتماعية والصحية والعائلية"
            icon={<Search className="w-6 h-6" />}
            columns={columns}
            data={items}
            loading={isLoading}
            searchable
            searchInHeader
            searchPlaceholder="بحث بالاسم / الرقم الوطني / الرقم العسكري..."
            searchValue={searchTerm}
            onSearchChange={setSearchTerm}
            onSearchKeyDown={(e) => {
                if (e.key === "ArrowDown" || e.key === "ArrowUp")
                    e.preventDefault();
            }}
            searchInputRef={searchInputRef}
            rowKey={(row) => row.retireeID}
            onRowClick={(row) => { if (row.fileID) navigate(`/files/${row.fileID}`); }}
            pagination={{
                page,
                pageSize: 20,
                total: totalCount,
                onPageChange: setPage,
            }}
            headerActions={
                <div className="flex gap-2">
                    <SearchDialog
                        value={searchTerm}
                        onSelect={(val) => { setSearchTerm(val); setPage(1); }}
                        queryKey={["social-research", "dialog-search"]}
                        fetchFn={(term) => socialResearchApi.search({ search: term || undefined, page: 1, pageSize: 100, hasFiles: true } as SocialResearchFilters)}
                        getName={(r) => r.fullName}
                        getSubtitle={(r) => r.nationalID || r.militaryNumber || ""}
                        title="بحث بالاسم"
                        placeholder="اكتب اسم المتقاعد..."
                        hideTrigger
                    />
                    <Button
                        variant={showFilters ? "primary" : "outline"}
                        size="sm"
                        onClick={() => setShowFilters(!showFilters)}
                    >
                        فلاتر متقدمة
                        {showFilters ? (
                            <ChevronUp className="w-5 h-5 mr-1" />
                        ) : (
                            <ChevronDown className="w-5 h-5 mr-1" />
                        )}
                    </Button>
                </div>
            }
        >
            {/* Stats Cards */}
            <div className="grid grid-cols-2 sm:grid-cols-2 lg:grid-cols-4 gap-2 sm:gap-4 mb-6">
                <StatCard
                    title="إجمالي المتقاعدين"
                    value={stats.total}
                    icon={<Users className="w-5 h-5" />}
                    variant="blue"
                    loading={isLoading}
                />
                <StatCard
                    title="على قيد الحياة"
                    value={stats.alive}
                    icon={<Heart className="w-5 h-5" />}
                    variant="emerald"
                    loading={isLoading}
                />
                <StatCard
                    title="المتوفين"
                    value={stats.deceased}
                    icon={<Activity className="w-5 h-5" />}
                    variant="rose"
                    loading={isLoading}
                />
                <StatCard
                    title="عدد الملفات"
                    value={items.reduce((sum, r) => sum + r.fileCount, 0)}
                    icon={<FolderOpen className="w-5 h-5" />}
                    variant="amber"
                    loading={isLoading}
                />
            </div>

            {/* Advanced Filters */}
            {showFilters && (
                <div className="bg-muted/30 rounded-lg p-4 mb-6 border border-border">
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                        <NativeSelect
                            label="الحالة الاجتماعية"
                            value={filters.socialStatusId?.toString() || ""}
                            onChange={(val) =>
                                setFilters((f) => ({
                                    ...f,
                                    socialStatusId: val
                                        ? Number(val)
                                        : undefined,
                                }))
                            }
                            options={socialStatuses.map((s) => ({
                                value: String(s.id),
                                label: s.name,
                            }))}
                            placeholder="الكل"
                        />
                        <NativeSelect
                            label="الحالة الصحية"
                            value={filters.healthStatusId?.toString() || ""}
                            onChange={(val) =>
                                setFilters((f) => ({
                                    ...f,
                                    healthStatusId: val
                                        ? Number(val)
                                        : undefined,
                                }))
                            }
                            options={healthStatuses.map((s) => ({
                                value: String(s.id),
                                label: s.name,
                            }))}
                            placeholder="الكل"
                        />
                        <NativeSelect
                            label="الحالة"
                            value={
                                filters.isAlive === undefined
                                    ? ""
                                    : filters.isAlive
                                        ? "true"
                                        : "false"
                            }
                            onChange={(val) =>
                                setFilters((f) => ({
                                    ...f,
                                    isAlive:
                                        val === ""
                                            ? undefined
                                            : val === "true",
                                }))
                            }
                            options={[
                                { value: "true", label: "على قيد الحياة" },
                                { value: "false", label: "متوفى" },
                            ]}
                            placeholder="الكل"
                        />
                        <NativeSelect
                            label="المحافظة"
                            value={filters.governorate || ""}
                            onChange={(val) =>
                                setFilters((f) => ({
                                    ...f,
                                    governorate: val || undefined,
                                }))
                            }
                            options={governorates.map((g) => ({
                                value: g.name,
                                label: g.name,
                            }))}
                            placeholder="الكل"
                        />
                        <NativeSelect
                            label="الفئة"
                            value={filters.categoryId?.toString() || ""}
                            onChange={(val) =>
                                setFilters((f) => ({
                                    ...f,
                                    categoryId: val
                                        ? Number(val)
                                        : undefined,
                                }))
                            }
                            options={categories.map((c) => ({
                                value: String(c.id),
                                label: c.name,
                            }))}
                            placeholder="الكل"
                        />
                        <DateInput
                            label="من تاريخ التقاعد"
                            value={filters.retirementDateFrom || ""}
                            onChange={(val) =>
                                setFilters((f) => ({
                                    ...f,
                                    retirementDateFrom: val || undefined,
                                }))
                            }
                            placeholder="DD/MM/YYYY"
                        />
                        <DateInput
                            label="إلى تاريخ التقاعد"
                            value={filters.retirementDateTo || ""}
                            onChange={(val) =>
                                setFilters((f) => ({
                                    ...f,
                                    retirementDateTo: val || undefined,
                                }))
                            }
                            placeholder="DD/MM/YYYY"
                        />
                        <div className="flex items-end">
                            <Button
                                variant="outline"
                                size="sm"
                                onClick={() =>
                                    setFilters({
                                        socialStatusId: undefined,
                                        healthStatusId: undefined,
                                        isAlive: undefined,
                                        governorate: undefined,
                                        categoryId: undefined,
                                        hasFiles: true,
                                        retirementDateFrom: undefined,
                                        retirementDateTo: undefined,
                                    })
                                }
                            >
                                مسح الفلاتر
                            </Button>
                        </div>
                    </div>
                </div>
            )}

            {/* Update Dialog */}
            <BaseFormDialog
                title="تحديث بيانات المتقاعد"
                description={`تحديث بيانات: ${updateTarget?.fullName || ""}`}
                isOpen={!!updateTarget}
                onClose={() => setUpdateTarget(null)}
                onSubmit={updateForm.handleSubmit((data) =>
                    updateMutation.mutate(data)
                )}
                isLoading={updateMutation.isPending}
                size="md"
            >
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <FormField
                        label="الهاتف"
                        error={updateForm.formState.errors.phone?.message}
                    >
                        <Input
                            {...updateForm.register("phone")}
                            placeholder="7xxxxxxx"
                        />
                    </FormField>
                    <FormField
                        label="المحافظة"
                        error={
                            updateForm.formState.errors.governorate?.message
                        }
                    >
                        <Input
                            {...updateForm.register("governorate")}
                            placeholder="المحافظة"
                        />
                    </FormField>
                    <FormField
                        label="المدينة"
                        error={updateForm.formState.errors.city?.message}
                    >
                        <Input
                            {...updateForm.register("city")}
                            placeholder="المدينة"
                        />
                    </FormField>
                </div>
            </BaseFormDialog>
        </CrudPageLayout>
    );
}

import { useQuery } from "@tanstack/react-query";
import { AlertTriangle,ArrowRight, FileText, Printer } from "lucide-react";
import { useCallback,useMemo } from "react";
import { useNavigate, useParams,useSearchParams } from "react-router-dom";

import {
  accountsApi,
  fiscalYearsApi,
  periodsApi,
  reportsApi,
} from "@/api/accounting";
import { fixedAssetApi, type FixedAssetDto } from "@/api/fixedAssets";
import { Button } from "@/components/ui/Button";
import { PrintableReport } from "@/components/ui/print/PrintableReport";
import type { TableCell } from "@/components/ui/print/PrintableReportTable";
import { chartColors } from "@/lib/chartColors";
import { formatCurrency } from "@/lib/utils";
import type {
  AccountStatementResultDto,
  BalanceCheckResult,
  BalanceSheetDto,
  BudgetReportResultDto,
  CashFlowStatementDto,
  CostCenterReportDto,
  CumulativePnLReportDto,
  CurrentOperationsReportDto,
  DepreciationReportDto,
  GeneralLedgerDto,
  IncomeStatementDto,
  JournalRegisterDto,
  JournalRegisterItemDto,
  LiabilitiesReportDto,
  ProvisionsReportDto,
  QuarterlyReportDto,
  SubledgerReportResultDto,
  TrialBalanceItemDto,
  YearOverYearReportDto,
} from "@/types/accounting";

/* ═══════════════════════════════════════════════════════════
   Helpers
   ═══════════════════════════════════════════════════════════ */

const fc = (n: number) => formatCurrency(n);
const isNum = (n: number) => n !== 0;

/* ═══════════════════════════════════════════════════════════
   Report Registry — كل التقارير في مكان واحد
   ═══════════════════════════════════════════════════════════ */

interface ReportConfig<TData = unknown> {
  title: string;
  headers: string[];
  pageSize?: "A4" | "A3" | "A5" | "letter";
  orientation?: "portrait" | "landscape";
  buildRows: (data: TData) => TableCell[][];
  buildTotals?: (data: TData) => TableCell[] | undefined;
  buildMetadata?: (data: TData, deps: ReportDeps) => { label: string; value: string }[];
  buildBalanceCheck?: (data: TData) => BalanceCheckResult;
}

interface ReportDeps {
  yearName: string;
  periodName: string;
  accountName?: { accountCode: string; accountName: string };
  fromDate?: string;
  toDate?: string;
  date?: string;
}

const REPORT_REGISTRY: Record<string, ReportConfig<any>> = {
  "trial-balance": {
    title: "ميزان المراجعة",
    headers: ["#", "الكود", "الحساب", "افتتاحي مدين", "افتتاحي دائن", "حركة مدين", "حركة دائن", "ختامي مدين", "ختامي دائن", "الرصيد"],
    pageSize: "A3",
    orientation: "landscape",
    buildRows: (data: TrialBalanceItemDto[]) => data.map((item: TrialBalanceItemDto, i: number) => [
      { value: i + 1 },
      { value: item.accountCode, bold: true, className: "font-mono" },
      { value: item.accountName, bold: !item.isPostable, align: "start" },
      { value: isNum(item.openingDebit) ? fc(item.openingDebit) : "—" },
      { value: isNum(item.openingCredit) ? fc(item.openingCredit) : "—" },
      { value: isNum(item.movementDebit) ? fc(item.movementDebit) : "—" },
      { value: isNum(item.movementCredit) ? fc(item.movementCredit) : "—" },
      { value: isNum(item.closingDebit) ? fc(item.closingDebit) : "—" },
      { value: isNum(item.closingCredit) ? fc(item.closingCredit) : "—" },
      { value: item.balance > 0 ? fc(item.balance) : "—", bold: true, color: item.balanceType === "Debit" ? chartColors.primary : chartColors.success },
    ]),
    buildTotals: (data: TrialBalanceItemDto[]) => {
      const postable = data.filter((d) => d.isPostable);
      const sum = (key: keyof TrialBalanceItemDto) => postable.reduce((s, i) => s + ((i[key] as number) || 0), 0);
      const totalDebit = sum("totalDebit");
      const totalCredit = sum("totalCredit");
      return [
        { value: "الإجمالي", bold: true, colSpan: 2 },
        { value: fc(sum("openingDebit")), bold: true },
        { value: fc(sum("openingCredit")), bold: true },
        { value: fc(sum("movementDebit")), bold: true },
        { value: fc(sum("movementCredit")), bold: true },
        { value: fc(sum("closingDebit")), bold: true },
        { value: fc(sum("closingCredit")), bold: true },
        { value: `${fc(totalDebit)} / ${fc(totalCredit)}`, bold: true },
      ];
    },
    buildBalanceCheck: (data: TrialBalanceItemDto[]) => {
      const postable = data.filter((d) => d.isPostable);
      const sum = (key: keyof TrialBalanceItemDto) => postable.reduce((s, i) => s + ((i[key] as number) || 0), 0);
      const totalDebit = sum("totalDebit");
      const totalCredit = sum("totalCredit");
      return {
        isBalanced: Math.abs(totalDebit - totalCredit) < 0.01,
        difference: Math.abs(totalDebit - totalCredit),
        debitTotal: totalDebit,
        creditTotal: totalCredit,
      };
    },
  },

  "journal-register": {
    title: "سجل القيود اليومية",
    headers: ["التاريخ", "رقم القيد", "البيان", "المصدر", "الحالة", "بواسطة", "مدين", "دائن"],
    pageSize: "A4",
    orientation: "landscape",
    buildRows: (data: JournalRegisterDto) => data.entries.map((entry: JournalRegisterItemDto) => [
      { value: new Date(entry.entryDate).toLocaleDateString("ar-YE") },
      { value: entry.entryNumber, className: "font-mono" },
      { value: entry.description, align: "start" },
      { value: entry.sourceModule === "Manual" ? "يدوي" : entry.sourceModule },
      { value: entry.status === 1 ? "مسودة" : entry.status === 2 ? "مرحّل" : "ملغي", color: entry.status === 2 ? chartColors.success : entry.status === 3 ? chartColors.danger : chartColors.warning, bold: true },
      { value: entry.createdByUserName },
      { value: entry.totalDebit > 0 ? fc(entry.totalDebit) : "—" },
      { value: entry.totalCredit > 0 ? fc(entry.totalCredit) : "—" },
    ]),
    buildTotals: (data) => [
      { value: "الإجمالي", bold: true, colSpan: 6 },
      { value: fc(data.grandTotalDebit), bold: true },
      { value: fc(data.grandTotalCredit), bold: true },
    ],
    buildBalanceCheck: (data) => ({
      isBalanced: Math.abs(data.grandTotalDebit - data.grandTotalCredit) < 0.01,
      difference: Math.abs(data.grandTotalDebit - data.grandTotalCredit),
      debitTotal: data.grandTotalDebit,
      creditTotal: data.grandTotalCredit,
    }),
  },

  "account-statement": {
    title: "كشف حساب",
    headers: ["التاريخ", "رقم القيد", "البيان", "مدين", "دائن", "الرصيد"],
    pageSize: "A4",
    orientation: "portrait",
    buildRows: (data: AccountStatementResultDto) => (data.items || []).map((item) => [
      { value: new Date(item.entryDate).toLocaleDateString("ar-YE") },
      { value: item.entryNumber, className: "font-mono" },
      { value: item.description, align: "start" as const },
      { value: item.debit > 0 ? fc(item.debit) : "—" },
      { value: item.credit > 0 ? fc(item.credit) : "—" },
      { value: fc(item.runningBalance), bold: true },
    ]),
    buildTotals: (data: AccountStatementResultDto) => {
      const lastBalance = data.items?.[data.items.length - 1]?.runningBalance ?? 0;
      return [{ value: "الرصيد النهائي", bold: true, colSpan: 4 }, { value: fc(lastBalance), bold: true }];
    },
  },

  "general-ledger": {
    title: "دفتر الأستاذ العام",
    headers: ["التاريخ", "رقم القيد", "البيان", "مركز التكلفة", "مدين", "دائن", "الرصيد"],
    pageSize: "A4",
    orientation: "landscape",
    buildRows: (data: GeneralLedgerDto) => data.entries.map((entry) => [
      { value: new Date(entry.entryDate).toLocaleDateString("ar-YE") },
      { value: entry.entryNumber, className: "font-mono" },
      { value: entry.description, align: "start" as const },
      { value: entry.costCenterName || "—" },
      { value: entry.debit > 0 ? fc(entry.debit) : "—" },
      { value: entry.credit > 0 ? fc(entry.credit) : "—" },
      { value: fc(entry.runningBalance), bold: true },
    ]),
    buildTotals: (data: GeneralLedgerDto) => [
      { value: "الإجمالي", bold: true, colSpan: 3 },
      { value: fc(data.totalDebit), bold: true },
      { value: fc(data.totalCredit), bold: true },
      { value: fc(data.closingBalance), bold: true },
    ],
    buildMetadata: (data: GeneralLedgerDto, deps: ReportDeps) => [
      ...deps.yearName ? [{ label: "السنة المالية", value: deps.yearName }] : [],
      ...deps.accountName ? [{ label: "الحساب", value: `${deps.accountName.accountCode} - ${deps.accountName.accountName}` }] : [],
      ...deps.fromDate && deps.toDate ? [{ label: "من", value: deps.fromDate }, { label: "إلى", value: deps.toDate }] : [],
      { label: "الرصيد الافتتاحي", value: fc(data.openingBalance) },
    ],
  },

  "fixed-assets": {
    title: "الأصول الثابتة",
    headers: ["رقم الأصل", "اسم الأصل", "التصنيف", "تاريخ الشراء", "التكلفة", "نسبة الإهلاك", "الإهلاك المتراكم", "القيمة الدفترية", "الحالة"],
    pageSize: "A4",
    orientation: "landscape",
    buildRows: (data: FixedAssetDto[]) => data.filter((a) => a.status === 0).map((item) => [
      { value: item.assetNumber, className: "font-mono" },
      { value: item.assetName, align: "start" as const },
      { value: item.categoryName || "—" },
      { value: item.inServiceDate ? new Date(item.inServiceDate).toLocaleDateString("ar-YE") : "—" },
      { value: fc(item.acquiredCost) },
      { value: `${item.depreciationRate}%` },
      { value: fc(item.accumulatedDepreciation), color: chartColors.danger },
      { value: fc(item.netBookValue), bold: true, color: chartColors.success },
      { value: "نشط", color: chartColors.success, bold: true },
    ]),
    buildTotals: (data: FixedAssetDto[]) => {
      const active = data.filter((a) => a.status === 0);
      const totalCost = active.reduce((s, a) => s + a.acquiredCost, 0);
      const totalAccum = active.reduce((s, a) => s + a.accumulatedDepreciation, 0);
      const totalNet = active.reduce((s, a) => s + a.netBookValue, 0);
      return [
        { value: "الإجمالي", bold: true, colSpan: 3 },
        { value: "" },
        { value: fc(totalCost), bold: true },
        { value: "" },
        { value: fc(totalAccum), bold: true, color: chartColors.danger },
        { value: fc(totalNet), bold: true, color: chartColors.success },
        { value: "" },
      ];
    },
  },

  "balance-sheet": {
    title: "الميزانية العمومية",
    headers: ["#", "كود الحساب", "اسم الحساب", "المبلغ"],
    pageSize: "A4",
    orientation: "portrait",
    buildRows: (data: BalanceSheetDto) => {
      type TreeNode = { accountCode: string; accountName: string; balance: number; children?: TreeNode[] };
      const flattenTree = (items: TreeNode[], list: TreeNode[] = []): TreeNode[] => {
        items.forEach(item => { list.push(item); if (item.children) flattenTree(item.children, list); });
        return list;
      };
      const all = [
        ...flattenTree(data.assets || []).map((a) => ({ ...a, section: "الأصول" })),
        ...flattenTree(data.liabilities || []).map((l) => ({ ...l, section: "الخصوم" })),
