const DEFAULT_SIGNATURES = [
  { title: "رئيس قسم الحسابات", sub: "رائد / خالد صالح بن صالح" },
  { title: "رئيس قسم المصروفات والإيرادات", sub: "عقيد / منصور عبد الله اليماني" },
  { title: "المدير المالي", sub: "عقيدركن / شامخ عبد الرحمن فتاح" },
  { title: "المدير العام التنفيذي", sub: "عميد ركن/ جمال فضل القطيبي" },
];

export default function AccountingReportPrintPage() {
  const navigate = useNavigate();
  const { reportType } = useParams<{ reportType: string }>();
  const [searchParams] = useSearchParams();

  const params = useMemo(() => ({
    fiscalYearId: searchParams.get("fiscalYearId") ? Number(searchParams.get("fiscalYearId")) : undefined,
    periodId: searchParams.get("periodId") ? Number(searchParams.get("periodId")) : undefined,
    fromDate: searchParams.get("fromDate") ?? undefined,
    toDate: searchParams.get("toDate") ?? undefined,
    accountId: searchParams.get("accountId") ? Number(searchParams.get("accountId")) : undefined,
    date: searchParams.get("date") ?? undefined,
    year1Id: searchParams.get("year1Id") ? Number(searchParams.get("year1Id")) : undefined,
    year2Id: searchParams.get("year2Id") ? Number(searchParams.get("year2Id")) : undefined,
    quarterId: searchParams.get("quarterId") ? Number(searchParams.get("quarterId")) : undefined,
  }), [searchParams]);

  const { data, fiscalYears, periods, accounts, isLoading, isError, error } = useReportData(reportType ?? "", params);

  const config = REPORT_REGISTRY[reportType ?? ""];
  const yearName = fiscalYears?.find((y: { fiscalYearID: number; yearName: string }) => y.fiscalYearID === params.fiscalYearId)?.yearName ?? "";
  const periodName = periods?.find((p: { periodID: number; periodName: string }) => p.periodID === params.periodId)?.periodName ?? "";
  const accountName = accounts?.find((a: { accountID: number; accountCode: string; accountName: string }) => a.accountID === params.accountId);

  const handlePrint = useCallback(() => window.print(), []);

  /* ── Memoized report data ── */
  const reportData = useMemo(() => {
    if (!config || !data) return null;

    const deps: ReportDeps = {
      yearName,
      periodName,
      accountName: accountName ? { accountCode: accountName.accountCode, accountName: accountName.accountName } : undefined,
      fromDate: params.fromDate,
      toDate: params.toDate,
      date: params.date,
    };

    const rows = config.buildRows(data);
    const totals = config.buildTotals?.(data);
    const balanceCheck = config.buildBalanceCheck?.(data);
    const extraMetadata = config.buildMetadata?.(data, deps) ?? [];

    const metadata: { label: string; value: string }[] = [
      ...(yearName ? [{ label: "السنة المالية", value: yearName }] : []),
      ...(periodName ? [{ label: "الفترة", value: periodName }] : []),
      ...(accountName ? [{ label: "الحساب", value: `${accountName.accountCode} - ${accountName.accountName}` }] : []),
      ...(params.fromDate && params.toDate ? [{ label: "من", value: params.fromDate }, { label: "إلى", value: params.toDate }] : []),
      ...(params.date ? [{ label: "حتى تاريخ", value: params.date }] : []),
      ...extraMetadata,
    ];

    return { rows, totals, metadata, balanceCheck };
  }, [config, data, yearName, periodName, accountName, params]);

  /* ── Loading ── */
  if (isLoading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen gap-4 text-muted-foreground">
        <div className="w-10 h-10 border-4 border-primary border-t-transparent rounded-full animate-spin" />
        <p className="text-lg font-medium">جاري تحميل البيانات...</p>
      </div>
    );
  }

  /* ── Error ── */
  if (isError) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen gap-4 p-6">
        <AlertTriangle className="w-16 h-16 text-destructive" />
        <h2 className="text-xl font-bold text-destructive">حدث خطأ أثناء تحميل البيانات</h2>
        <p className="text-muted-foreground text-center max-w-md">
          {error instanceof Error ? error.message : "يرجى التحقق من الاتصال والمحاولة مرة أخرى"}
        </p>
        <Button variant="outline" onClick={() => navigate(-1)}>
          <ArrowRight className="w-4 h-4 ms-2" />
          رجوع
        </Button>
      </div>
    );
  }

  /* ── No config ── */
  if (!config) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen gap-4 p-6">
        <FileText className="w-16 h-16 text-muted-foreground" />
        <h2 className="text-xl font-bold">تقرير غير معروف</h2>
        <p className="text-muted-foreground">نوع التقرير "{reportType}" غير مدعوم</p>
        <Button variant="outline" onClick={() => navigate(-1)}>
          <ArrowRight className="w-4 h-4 ms-2" />
          رجوع
        </Button>
      </div>
    );
  }

  /* ── Empty data ── */
  if (!reportData || reportData.rows.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen gap-4 p-6">
        <FileText className="w-16 h-16 text-muted-foreground" />
        <h2 className="text-xl font-bold">لا توجد بيانات</h2>
        <p className="text-muted-foreground">لا توجد بيانات متاحة لهذا التقرير في الفترة المحددة</p>
        <Button variant="outline" onClick={() => navigate(-1)}>
          <ArrowRight className="w-4 h-4 ms-2" />
          رجوع
        </Button>
      </div>
    );
  }

  return (
    <>
      {/* ─── Toolbar (شاشة فقط) ─── */}
      <div className="print:hidden sticky top-0 z-50 bg-white/95 backdrop-blur border-b shadow-sm">
        <div className="max-w-7xl mx-auto flex items-center justify-between px-6 py-3">
          <Button variant="ghost" size="sm" onClick={() => navigate(-1)}>
            <ArrowRight className="w-4 h-4 ms-2" />
            رجوع
          </Button>

          <div className="flex items-center gap-2">
            <FileText className="w-5 h-5 text-primary" />
            <span className="font-bold text-sm">{config.title}</span>
            {reportData.metadata.length > 0 && (
              <span className="text-muted-foreground text-xs hidden sm:inline">
                — {reportData.metadata.map(m => m.value).join(" | ")}
              </span>
            )}
          </div>

          <Button size="sm" onClick={handlePrint} className="gap-2">
            <Printer className="w-4 h-4" />
            <span className="hidden sm:inline">طباعة</span>
          </Button>
        </div>
      </div>

      {/* ─── منطقة الطباعة ─── */}
      <div className="w-full flex justify-center p-4 print:p-0">
        <PrintableReport
          title={config.title}
          metadata={reportData.metadata}
          tableHeaders={config.headers}
          rows={reportData.rows}
          totals={reportData.totals}
          balanceCheck={reportData.balanceCheck}
          signatures={DEFAULT_SIGNATURES}
          sectionTitle="الالإدارة المالية"
          pageSize={config.pageSize ?? "A4"}
          orientation={config.orientation ?? "portrait"}
        />
      </div>
    </>
  );
}

import { useQuery } from "@tanstack/react-query";
import { Printer } from "lucide-react";
import { useParams } from "react-router-dom";

import { documentsApi } from "@/api/documents";
import { retirementApi } from "@/api/retirement";
import { Button } from "@/components/ui/Button";
import { PrintableReportTable, type TableCell } from "@/components/ui/print/PrintableReportTable";
import { PrintLayout } from "@/components/ui/print/PrintLayout";
import { chartColors } from "@/lib/chartColors";

export function MissingDocumentsPrintPage() {
    const { id } = useParams<{ id: string }>();
    const fileId = parseInt(id || "");

    const { data: fileData, isLoading: loadingFile } = useQuery({
        queryKey: ["retirement-files", fileId],
        queryFn: () => retirementApi.getFile(fileId),
        enabled: !!fileId,
    });

    const { data: uploaded = [], isLoading: loadingUploaded } = useQuery({
        queryKey: ["documents-by-file", fileId],
        queryFn: () => documentsApi.getByFileId(fileId).then(docs => docs.map(d => ({ documentID: d.documentID, documentTypeName: d.documentTypeName }))),
        enabled: !!fileId,
    });

    const { data: missing = [], isLoading: loadingMissing } = useQuery({
        queryKey: ["missing-documents-auto", fileId],
        queryFn: () => documentsApi.getAutoDetectedMissing(fileId) as Promise<any>,
        enabled: !!fileId,
    });

    const isLoading = loadingFile || loadingUploaded || loadingMissing;

    const uploadedNames = new Set(uploaded.map((d) => d.documentTypeName));

    const missingByName = new Map<string, { entityType: string | null; entityName: string | null }>();
    missing.forEach((d: { documentTypeName: string; entityType?: string | null; entityName?: string | null }) => {
        if (!missingByName.has(d.documentTypeName)) {
            missingByName.set(d.documentTypeName, { entityType: d.entityType ?? null, entityName: d.entityName ?? null });
        }
    });

    const allDocNames = [...new Set([...uploadedNames, ...missingByName.keys()])].sort();

    const uploadedCount = uploadedNames.size;
    const missingCount = missingByName.size;
    const total = allDocNames.length;

    const tableHeaders = ["#", "نوع الوثيقة", "صاحب الوثيقة", "الحالة"];

    const tableRows: TableCell[][] = allDocNames.map((name, i) => {
        const isUploaded = uploadedNames.has(name);
        const owner = missingByName.get(name);
        const ownerLabel = owner?.entityName
            ? `${owner.entityName}${owner.entityType ? ` (${owner.entityType})` : ""}`
            : "—";
        return [
            { value: i + 1, align: "center" },
            { value: name, bold: true, align: "start" },
            { value: ownerLabel, align: "start" },
            {
                value: isUploaded ? "✓ مرفوعة" : "✗ ناقصة",
                bold: true,
                color: isUploaded ? chartColors.success : chartColors.danger,
                align: "center",
            },
        ];
    });

    const tableTotals: TableCell[] = [
        { value: "الإجمالي", bold: true, colSpan: 2 },
        { value: `${total} نوع`, bold: true, align: "center" },
        {
            value: `${uploadedCount} مرفوعة / ${missingCount} ناقصة`,
            bold: true,
            align: "center",
            color: missingCount === 0 ? chartColors.success : chartColors.warning,
        },
    ];

    if (isLoading) {
        return <div className="flex items-center justify-center min-h-screen italic text-muted-foreground text-sm">جاري تجهيز التقرير للطباعة...</div>;
    }

    return (
        <>
            <div className="print:hidden flex items-center justify-between mb-6 p-6 max-w-7xl mx-auto">
                <Button variant="ghost" onClick={() => window.history.back()}>
                    رجوع
                </Button>
                <Button onClick={() => window.print()} className="flex items-center">
                    <Printer className="w-4 h-4 ms-2" />
                    طباعة التقرير
                </Button>
            </div>

            <PrintLayout
                reportName="تقرير حالة الوثائق"
                reportNumber={fileData?.fileNumber || ""}
                attachments={fileData?.retireeFullName || ""}
                config={{
                    pageSize: "A4",
                    orientation: "portrait",
                    sectionTitle: "إدارة المعاشات",
                }}
            >
                <PrintableReportTable
                    headers={tableHeaders}
                    rows={tableRows}
                    totals={tableTotals}
                    caption="قائمة الوثائق"
                    captionNumber={1}
                    hoverable
                />

                {missingCount > 0 && (
                    <section className="mt-6 print:page-break-inside-avoid">
                        <h3 className="text-xs font-black mb-2">ملاحظات:</h3>
                        <ul className="text-[11px] space-y-1 list-disc list-inside">
                            <li>الوثائق الناقصة: {[...missingByName.keys()].join("، ")}</li>
                        </ul>
                    </section>
                )}
            </PrintLayout>
        </>
    );
}

import type {
    AgentForPrint,
    EntitledForPrint,
    GuardianForPrint,
    RetireeDto,
    RetirementFileSummary,
    SalaryRecipientForPrint} from "@/components/domain/print/print.types";
import { PRINT_STYLES } from "@/components/domain/print/print.utils";
import { formatDate, getDocumentUrl } from "@/lib/utils";
import { useAuthStore } from "@/stores/authStore";

const { TB, CELL, LBL, VAL, SECTION_HEADER } = PRINT_STYLES;

const getUrl = (p: string | null | undefined) => {
    if (!p) return "";
    return getDocumentUrl(p) ?? "";
};

interface RetirementFilePrintData extends RetirementFileSummary {
    personalPhotoPath?: string | null;
    ActivePaymentBookNumber?: string | null;
    statusID?: number | null;
    fileStatusName?: string | null;
}

interface RetireePrintData extends RetireeDto {
    personalPhotoPath?: string | null;
}

interface PrintableRetirementFileReportProps {
    file: RetirementFilePrintData;
    retiree: RetireePrintData;
    entitled: EntitledForPrint[];
    agents: AgentForPrint[];
    guardians: GuardianForPrint[];
    financial: { totalAmount?: number; amount?: number; effectiveDate?: string } | null | undefined;
    recipients: SalaryRecipientForPrint[];
    paymentBooks?: { bookNumber?: string; status?: string; bookType?: string; recipientName?: string | null; issueDate?: string; expiryDate?: string }[];
}

export function PrintableRetirementFileReport({
    file,
    retiree,
    entitled,
    agents,
    guardians,
    financial,
    recipients,
    paymentBooks = []
}: PrintableRetirementFileReportProps) {
    const user = useAuthStore(s => s.user);

    const retireePhoto = retiree.personalPhotoPath || file.personalPhotoPath;
    const activePaymentBookNumber = file.activePaymentBookNumber || file.ActivePaymentBookNumber || paymentBooks.find((b: any) => b.status === "فعال")?.bookNumber || paymentBooks[0]?.bookNumber;

    const activeRecipientRecord = recipients?.find(r => r.isActive);
    let activeRecipientName = "—";
    let recipientPhoto: string | null | undefined = null;

    if (activeRecipientRecord) {
        if (activeRecipientRecord.agentId) {
            const agent = agents?.find(a => a.agentId === activeRecipientRecord.agentId);
            activeRecipientName = agent?.fullName || activeRecipientRecord.recipientName || "وكيل غير محدد";
            recipientPhoto = agent?.personalPhotoPath;
        } else if (activeRecipientRecord.guardianId) {
            const guardian = guardians?.find(g => g.guardianId === activeRecipientRecord.guardianId);
            activeRecipientName = guardian?.fullName || activeRecipientRecord.recipientName || "وصي غير محدد";
            recipientPhoto = guardian?.personalPhotoPath;
        } else if (activeRecipientRecord.entitledId) {
            const ep = entitled?.find(e => e.entitledId === activeRecipientRecord.entitledId);
            activeRecipientName = ep?.fullName || activeRecipientRecord.recipientName || "مستحق غير محدد";
            recipientPhoto = ep?.personalPhotoPath;
        } else {
            activeRecipientName = "المتقاعد نفسه";
            recipientPhoto = retireePhoto;
        }
    } else if (activePaymentBookNumber) {
        activeRecipientName = "المتقاعد نفسه";
        recipientPhoto = retireePhoto;
    }

    return (
        <div className="text-black w-full flex flex-col min-h-full">
            {/* ═══ Photos + Title Row ═══ */}
            <div className="flex items-start mb-2 mt-2">
                <div className="flex-1" />
                <div className="flex-none flex justify-center pt-2">
                    <h1 className="text-[24px] font-[900] text-center tracking-[0.5px]">
                        تقرير ملف التقاعد
                    </h1>
                </div>
                <div className="flex-1 flex gap-4 justify-end">
                    <div className="flex flex-col items-center w-16">
                        <p className="text-[9px] font-bold mb-1 border-b border-black w-full text-center pb-0.5">صورة المتقاعد</p>
                        {retireePhoto ? (
                            <img src={getUrl(retireePhoto)} alt="صورة المتقاعد" className="w-16 h-20 object-cover border-2 border-black rounded" />
                        ) : (
                            <div className="w-16 h-20 border-2 border-black rounded bg-muted/50 flex items-center justify-center text-[9px] text-muted-foreground">لا توجد</div>
                        )}
                    </div>
                    <div className="flex flex-col items-center w-16">
                        <p className="text-[9px] font-bold mb-1 border-b border-black w-full text-center pb-0.5">مستلم المعاش</p>
                        {recipientPhoto ? (
                            <img src={getUrl(recipientPhoto)} alt="صورة المستلم" className="w-16 h-20 object-cover border-2 border-black rounded" />
                        ) : (
                            <div className="w-16 h-20 border-2 border-black rounded bg-muted/50 text-muted-foreground">لا توجد</div>
                        )}
                    </div>
                </div>
            </div>

            <div className="space-y-6">
                {/* 1. البيانات الأساسية */}
                <section className={`${TB} w-full`}>
                    <div className={SECTION_HEADER}>
                        <span>البيانات الأساسية للمتقاعد</span>
                    </div>
                    <table className="w-full border-collapse">
                        <tbody>
                            <tr className={TB}>
                                <td className={`${LBL} w-[20%] ${TB}`}>الاسم الكامل</td>
                                <td className={`${VAL} font-extrabold text-[14px]`} colSpan={3}>
                                    {retiree.fullName}
                                </td>
                            </tr>
                            <tr className={TB}>
                                <td className={`${LBL} w-[20%] ${TB}`}>الرتبة</td>
                                <td className={`${VAL} w-[30%] ${TB}`}>
                                    {file.rankName || retiree.rankName || "غير محدد"}
                                </td>
                                <td className={`${LBL} w-[20%] ${TB}`}>الرقم العسكري</td>
                                <td className={`${VAL} w-[30%]`}>
                                    {retiree.militaryNumber || "---"}
                                </td>
                            </tr>
                            <tr className={TB}>
                                <td className={`${LBL} w-[20%] ${TB}`}>رقم الملف</td>
                                <td className={`${VAL} w-[30%] ${TB}`}>
                                    {file.fileNumber || file.fileID}
                                </td>
                                <td className={`${LBL} w-[20%] ${TB}`}>تاريخ فتح الملف</td>
                                <td className={`${VAL} w-[30%]`}>
                                    {file.fileOpenDate ? formatDate(file.fileOpenDate) : "---"}
                                </td>
                            </tr>
                            <tr className={TB}>
                                <td className={`${LBL} w-[20%] ${TB}`}>الحالة الاجتماعية</td>
                                <td className={`${VAL}`} colSpan={3}>
                                    {retiree.socialStatusName || "---"}
                                </td>
                            </tr>
                        </tbody>
                    </table>
                </section>

                {/* 2. المستحقون */}
                {entitled && entitled.length > 0 && (
                    <section className={`${TB} w-full`}>
                        <div className={SECTION_HEADER}>
                            <span>المستحقون عن المتقاعد</span>
                            <span className="text-[11px] font-bold text-slate-500 me-auto">({entitled.length})</span>
                        </div>
                        <table className="w-full border-collapse text-[9px] table-fixed">
                            <thead className="bg-muted/50 text-[10px]">
                                <tr>
                                    <th className={`${CELL} ${TB} text-center w-[4%]`}>م</th>
                                    <th className={`${CELL} ${TB} text-center w-[32%]`}>الاسم الكامل</th>
                                    <th className={`${CELL} ${TB} text-center w-[12%]`}>صلة القرابة</th>
                                    <th className={`${CELL} ${TB} text-center w-[18%]`}>الحالة الاجتماعية</th>
                                    <th className={`${CELL} ${TB} text-center w-[22%]`}>الرقم الوطني</th>
                                    <th className={`${CELL} ${TB} text-center w-[12%]`}>الحالة</th>
                                </tr>
                            </thead>
                            <tbody>
                                {entitled.map((person, index) => (
                                    <tr key={person.entitledId || index} className={TB}>
                                        <td className={`${CELL} ${TB} text-center font-mono text-slate-500`}>{index + 1}</td>
                                        <td className={`${CELL} ${TB} text-start font-bold break-words whitespace-normal overflow-hidden`}>{person.fullName}</td>
                                        <td className={`${CELL} ${TB} text-center break-words whitespace-normal overflow-hidden`}>{person.relationshipName || "---"}</td>
                                        <td className={`${CELL} ${TB} text-center break-words whitespace-normal overflow-hidden`}>{person.socialStatusName || "---"}</td>
                                        <td className={`${CELL} ${TB} text-center font-mono`}>{person.nationalID || "---"}</td>
                                        <td className={`${CELL} ${TB} text-center font-bold`}>
                                            {person.isActive ? "مستحق" : "غير مستحق"}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </section>
                )}

                {/* 3. الوكلاء */}
                {agents && agents.length > 0 && (
                    <section className={`${TB} w-full`}>
                        <div className={SECTION_HEADER}>
                            <span>الوكلاء المعتمدون</span>
                        </div>
                        <table className="w-full border-collapse text-[11px] table-fixed">
                            <thead className="bg-muted/50">
                                <tr>
                                    <th className={`${CELL} ${TB} text-center w-[5%]`}>م</th>
                                    <th className={`${CELL} ${TB} text-center w-[45%]`}>الاسم الكامل</th>
                                    <th className={`${CELL} ${TB} text-center w-[25%]`}>رقم الوكالة</th>
                                    <th className={`${CELL} ${TB} text-center w-[25%]`}>تاريخ الانتهاء</th>
                                </tr>
                            </thead>
                            <tbody>
                                {agents.map((agent, index) => (
                                    <tr key={agent.agentId || index} className={TB}>
                                        <td className={`${CELL} ${TB} text-center font-mono text-slate-500`}>{index + 1}</td>
                                        <td className={`${CELL} ${TB} text-start font-bold`}>{agent.fullName}</td>
                                        <td className={`${CELL} ${TB} text-center font-mono`}>{agent.agencyNumber || "---"}</td>
                                        <td className={`${CELL} ${TB} text-center`}>
                                            {agent.agencyEndDate ? formatDate(agent.agencyEndDate) : "---"}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </section>
                )}

                {/* 4. الأوصياء */}
                {guardians && guardians.length > 0 && (
                    <section className={`${TB} w-full`}>
                        <div className={SECTION_HEADER}>
                            <span>الأوصياء المعتمدون</span>
                        </div>
                        <table className="w-full border-collapse text-[11px] table-fixed">
                            <thead className="bg-muted/50">
                                <tr>
                                    <th className={`${CELL} ${TB} text-center w-[5%]`}>م</th>
                                    <th className={`${CELL} ${TB} text-center w-[45%]`}>الاسم الكامل</th>
                                    <th className={`${CELL} ${TB} text-center w-[50%]`}>رقم قرار الوصاية</th>
                                </tr>
                            </thead>
                            <tbody>
                                {guardians.map((guardian, index) => (
                                    <tr key={guardian.guardianId || index} className={TB}>
                                        <td className={`${CELL} ${TB} text-center font-mono text-slate-500`}>{index + 1}</td>
                                        <td className={`${CELL} ${TB} text-start font-bold`}>{guardian.fullName}</td>
                                        <td className={`${CELL} ${TB} text-center font-mono`}>{guardian.guardianshipDocNumber || "---"}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </section>
                )}

                {/* تفاصيل الصرف */}
                <section className={`${TB} w-full`}>
                    <div className={SECTION_HEADER}>
                        <span>تفاصيل الصرف والتحويل المالي</span>
                    </div>
                    <table className="w-full border-collapse">
                        <tbody>
                            <tr className={TB}>
                                <td className={`${LBL} w-[20%] ${TB}`}>رقم دفتر الصرف</td>
                                <td className={`${VAL} w-[30%] ${TB} font-bold`}>
                                    {activePaymentBookNumber || "—"}
                                </td>
                                <td className={`${LBL} w-[20%] ${TB}`}>المستلم الفعلي</td>
                                <td className={`${VAL} w-[30%] font-extrabold`}>
                                    {activeRecipientName}
                                </td>
                            </tr>
                            {paymentBooks.length > 0 && paymentBooks.map((book: any, idx: number) => (
                                <tr key={idx} className={TB}>
                                    <td className={`${LBL} ${TB} w-[20%]`}>دفتر {idx + 1}</td>
                                    <td className={`${VAL} ${TB} w-[30%]`}>
                                        <span className="font-mono font-bold">{book.bookNumber || "—"}</span>
                                        <span className="mx-2">—</span>
                                        <span>{book.bookType || "—"}</span>
                                    </td>
                                    <td className={`${LBL} ${TB} w-[20%]`}>الحالة / المستلم</td>
                                    <td className={`${VAL} ${TB} w-[30%]`}>
                                        <span className={`font-bold ${book.status === "فعال" ? "text-green-700" : "text-red-700"}`}>{book.status || "—"}</span>
                                        <span className="mx-2">—</span>
                                        <span>{book.recipientName || "—"}</span>
                                    </td>
                                </tr>
                            ))}
                            {financial && (
                                <tr className={TB}>
                                    <td className={`${LBL} ${TB}`}>إجمالي المعاش التقاعدي</td>

                                    <td className={`${VAL} text-[16px] font-black text-primary ${TB}`}>
                                        {financial.totalAmount?.toLocaleString("ar-YE") || financial.amount?.toLocaleString("ar-YE") || 0} ر.ي
                                    </td>
                                    <td className={`${LBL} ${TB}`}>تاريخ السريان</td>
                                    <td className={`${VAL}`}>
                                        {financial.effectiveDate ? formatDate(financial.effectiveDate) : "---"}
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </section>

                {/* 6. جميع المستلمون */}
                {recipients && recipients.length > 0 && (
                    <section className={`${TB} w-full`}>
                        <div className={SECTION_HEADER}>
                            <span>سادساً: المستلمون المعتمدون في الملف</span>
                        </div>
                        <table className="w-full border-collapse text-[11px] table-fixed">
                            <thead className="bg-muted/50">
                                <tr>
                                    <th className={`${CELL} ${TB} text-center w-[5%]`}>م</th>
                                    <th className={`${CELL} ${TB} text-center w-[45%]`}>اسم المستلم</th>
                                    <th className={`${CELL} ${TB} text-center w-[30%]`}>نوع الاستلام</th>
                                    <th className={`${CELL} ${TB} text-center w-[20%]`}>الحالة</th>
                                </tr>
                            </thead>
                            <tbody>
                                {recipients.map((recipient, index) => (
                                    <tr key={recipient.recipientId || index} className={TB}>
                                        <td className={`${CELL} ${TB} text-center font-mono text-slate-500`}>{index + 1}</td>
                                        <td className={`${CELL} ${TB} text-start font-bold`}>{recipient.recipientName}</td>
                                        <td className={`${CELL} ${TB} text-center`}>{recipient.recipientType || "مستحق مباشر"}</td>
                                        <td className={`${CELL} ${TB} text-center font-bold`}>
                                            {recipient.isActive ? "فعال" : "متوقف"}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </section>
                )}
            </div>

            {/* Spacer: pushes signature to bottom */}
            <div className="flex-1" />

            {/* ═══ التوقيعات ═══ */}
            <div className="grid grid-cols-3 gap-8 text-center mt-8 px-2 print:page-break-inside-avoid">
                <div className="col-start-3 flex flex-col items-center">
                    <p className="text-[15px] font-black mb-8">
                        المختص
                    </p>
                    <p className="text-[15px] font-extrabold text-black whitespace-nowrap">
                        {user?.fullName || 'الاســــم والتوقيـــع'}
                    </p>
                </div>
            </div>
        </div>
    );
}

import { useQuery } from "@tanstack/react-query";
import { ArrowRight, Printer } from "lucide-react";
import { useNavigate,useParams } from "react-router-dom";

import { financialEntitlementsApi } from "@/api/financial-entitlements";
import { retireeApi } from "@/api/retirees";
import { retirementApi } from "@/api/retirement";
import type { NormalizableItem, SalaryRecipientForPrint } from "@/components/domain/print/print.types";
import { normalizePrintItem } from "@/components/domain/print/print.utils";
import { Button } from "@/components/ui/Button";
import { PrintLayout } from "@/components/ui/print/PrintLayout";

import { PrintableRetirementFileReport } from "./PrintableRetirementFileReport";

export function RetirementFilePrintPage() {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();
    const fileId = parseInt(id || "");

    const { data: fileData, isLoading: loadingFile, isError: errorFile } = useQuery({
        queryKey: ["retirement-files", fileId],
        queryFn: () => retirementApi.getFile(fileId),
        enabled: !!fileId
    });

    const retireeId = fileData?.retireeID;

    const { data: retiree, isLoading: loadingRetiree, isError: errorRetiree } = useQuery({
        queryKey: ["retirees", retireeId],
        queryFn: async () => {
            if (!retireeId) return null;
            return retireeApi.getById(retireeId);
        },
        enabled: !!retireeId
    });

    const { data: entitled = [], isLoading: loadingEntitled, isError: errorEntitled } = useQuery({
        queryKey: ["entitled-persons", fileId],
        queryFn: () => retirementApi.getEntitledPersons(fileId),
        enabled: !!fileId
    });

    const { data: agents = [], isLoading: loadingAgents, isError: errorAgents } = useQuery({
        queryKey: ["agents", fileId],
        queryFn: () => retirementApi.getAgents(fileId),
        enabled: !!fileId
    });

    const { data: guardians = [], isLoading: loadingGuardians, isError: errorGuardians } = useQuery({
        queryKey: ["guardians", fileId],
        queryFn: () => retirementApi.getGuardians(fileId),
        enabled: !!fileId
    });

    const { data: financial, isLoading: loadingFinancial, isError: errorFinancial } = useQuery({
        queryKey: ["active-entitlement", retireeId],
        queryFn: async () => {
            if (!retireeId) return null;
            const res = await financialEntitlementsApi.getActive(retireeId);
            return res.data;
        },
        enabled: !!retireeId
    });

    const { data: recipientsRaw = [], isLoading: loadingRecipients, isError: errorRecipients } = useQuery({
        queryKey: ["salary-recipients", fileId],
        queryFn: () => retirementApi.getRecipients(fileId),
        enabled: !!fileId
    });

    const { data: paymentBooks = [], isLoading: loadingBooks } = useQuery({
        queryKey: ["payment-books", fileId],
        queryFn: () => retirementApi.getPaymentBooks(fileId),
        enabled: !!fileId
    });

    const recipients = (recipientsRaw as unknown as NormalizableItem[]).map(r => normalizePrintItem(r))
        .filter(Boolean) as SalaryRecipientForPrint[];

    const loading = loadingFile || loadingRetiree || loadingEntitled || loadingAgents || loadingGuardians || loadingFinancial || loadingRecipients || loadingBooks;
    const hasError = errorFile || errorRetiree || errorEntitled || errorAgents || errorGuardians || errorFinancial || errorRecipients;

    if (loading) return <div className="flex justify-center py-20 text-muted-foreground italic text-sm">جاري تحميل بيانات التقرير...</div>;
    if (hasError) return <div className="p-12 text-center text-red-600 font-bold">حدث خطأ أثناء تحميل بيانات التقرير. يرجى المحاولة لاحقاً.</div>;
    if (!fileData || !retiree) return <div className="p-12 text-center font-bold">الملف غير موجود.</div>;

    return (
        <div className="bg-surface-print min-h-screen pb-20 print:bg-white print:pb-0">
            <div className="print:hidden flex items-center justify-between mb-6 p-6 max-w-7xl mx-auto">
                <Button variant="ghost" onClick={() => navigate(`/files/${fileId}`)}>
                    <ArrowRight className="w-5 h-5 ms-2" />
                    رجوع للملف
                </Button>
                <div className="flex gap-2">
                    <Button onClick={() => window.print()} className="flex items-center">
                        <Printer className="w-4 h-4 ms-2" />
                        طباعة التقرير
                    </Button>
                </div>
            </div>

            <div className="w-full flex justify-center">
                <PrintLayout
                    reportNumber={`FILE-${fileId}-${new Date().getFullYear()}`}
                    attachments={`ملف التقاعد رقم ${fileId}`}
                    config={{ sectionTitle: "إدارة المعاشات" }}
                >
                    <PrintableRetirementFileReport 
                        file={{
                            ...fileData,
                            fileOpenDate: fileData.fileOpenDate ?? "",
                            statusName: fileData.fileStatusName ?? null,
                            activePaymentBookNumber: fileData.activePaymentBookNumber || paymentBooks.find((b: any) => b.status === "فعال")?.bookNumber,
                        }}
                        retiree={retiree}
                        entitled={entitled.map((e: any) => ({ ...e, nationalID: e.nationalID ?? undefined }))}
                        agents={agents.map((a: any) => ({ ...a, nationalID: a.nationalID ?? undefined }))}
                        guardians={guardians.map((g: any) => ({ ...g, nationalID: g.nationalID ?? undefined }))}
                        financial={financial}
                        recipients={recipients}
                        paymentBooks={paymentBooks}
                    />
                </PrintLayout>
            </div>
        </div>
    );
}

import { useQuery } from '@tanstack/react-query';
import { ArrowRight, ChevronUp, Download, FilePieChart, FileText, Monitor, Printer, RefreshCw, Users } from 'lucide-react';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';

import { retirementApi } from '@/api/retirement';
import { ReportChartSection, ReportSummaryCards } from '@/components/common/charts';
import { ChartToggle } from '@/components/common/charts';
import { PrintSignatureBlock } from '@/components/common/PrintSignatureBlock';
import { ReportFilters } from '@/components/common/ReportFilters';
import { RetirementFileReportViewer } from '@/components/common/RetirementFileReportViewer';
import { Badge, type CustomColumnDef, DataTable, Heading } from '@/components/ui';
import { Breadcrumb } from '@/components/ui/Breadcrumb';
import { Button } from '@/components/ui/Button';
import { PrintLayout } from '@/components/ui/print/PrintLayout';
import { COLUMN_TYPE } from '@/constants';
import { useReportExport } from '@/hooks/useReportExport';
import { cn } from '@/lib/utils';
import type { EntitledPersonSummary } from '@/types/retirement';

import { REPORT_CATALOG, type ReportDataRow, type ReportFilter } from '../../api/reports';

/* ═══════════════════════════════════════════════════════════════
   Helpers & Constants
   ═══════════════════════════════════════════════════════════════ */
const formatValue = (val: string | number | boolean | null | undefined, type?: string) => {
    if (val === null || val === undefined) return '—';
    if (type === COLUMN_TYPE.CURRENCY && typeof val === 'number') return `${val.toLocaleString('ar-YE')} ر.ي`;
    if (type === COLUMN_TYPE.PERCENT && typeof val === 'number') return `${Number(val).toFixed(1)}%`;
    if (type === COLUMN_TYPE.DATE && (typeof val === 'string' || typeof val === 'number')) return new Date(val).toLocaleDateString('ar-YE');
    if (type === COLUMN_TYPE.NUMBER && typeof val === 'number') return val.toLocaleString('ar-YE');
    if (typeof val === 'boolean') return val ? 'نعم' : 'لا';
    return String(val);
};

const SIGNATURES = [
    { title: 'أعده', sub: 'الاســــم والتوقيـــع' },
    { title: 'راجعه', sub: 'الاســــم والتوقيـــع' },
    { title: 'اعتمد', sub: 'الاســــم والتوقيـــع' },
];

const DEFAULT_PAGE_SIZE = 50;

export function ReportViewerPage() {
    const { reportId } = useParams<{ reportId: string }>();
    const navigate = useNavigate();
    const { exportReport, isExporting } = useReportExport();
    const [filters, setFilters] = useState<ReportFilter>({});
    const [isPrintView, setIsPrintView] = useState(false);
    const [showChart, setShowChart] = useState(true);
    const [page, setPage] = useState(1);
    const [pageSize, setPageSize] = useState(DEFAULT_PAGE_SIZE);
    const [expandedFileId, setExpandedFileId] = useState<number | null>(null);
    const [exportFormat, setExportFormat] = useState<"excel" | "pdf">("excel");

    /* ── جلب المستحقين عند توسيع صف ── */
    const { data: entitledPersons = [], isLoading: isLoadingEntitleds } = useQuery({
        queryKey: ['entitled-persons', expandedFileId],
        queryFn: () => retirementApi.getEntitledPersons(expandedFileId!),
        enabled: !!expandedFileId
    });

    /* ── استخراج إعداد التقرير ── */
    const reportConfig = useMemo(() => REPORT_CATALOG.find(r => r.id === reportId), [reportId]);

    /* ── إعادة التوجيه إذا لم يُعثر على التقرير ── */
    useEffect(() => {
        if (!reportConfig) {
            navigate('/reports');
        }
    }, [reportConfig, navigate]);

    /* ── إعادة تعيين الصفحة عند تغيير الفلاتر ── */
    useEffect(() => {
        setPage(1);
    }, [filters]);

    /* ── أعمدة الجدول ── */
    const tableColumns = useMemo(() => {
        if (!reportConfig) return [];
        const cols: CustomColumnDef<ReportDataRow>[] = [
            {
                key: 'index',
                header: '#',
                className: 'w-16 text-center text-muted-foreground font-mono',
                render: (_, idx) => (page - 1) * pageSize + idx + 1
            },
            ...reportConfig.columns.map(c => ({
                key: c.key,
                header: c.label,
                render: (row: ReportDataRow) => {
                    const cellValue = row[c.key as keyof ReportDataRow];

                    if (c.key === 'missingDocsList') {
                        const docs = String(cellValue ?? '');
                        const items = docs.split('، ').filter(Boolean);
                        return (
                            <div className="flex flex-wrap gap-1 max-w-full sm:max-w-[320px]">
                                {items.map((d, i) => (
                                    <Badge key={i} variant="warning" className="rounded-md px-2 py-0.5 text-xs">
                                        {d}
                                    </Badge>
                                ))}
                                {items.length === 0 && <span className="text-muted-foreground">—</span>}
                            </div>
                        );
                    }
                    if (c.key === 'maxDaysMissing') {
                        const val = Number(cellValue) || 0;
                        const variant = val >= 60 ? 'destructive' : val >= 30 ? 'warning' : 'ghost';
                        return (
                            <Badge variant={variant as any} className="rounded-md px-2 py-0.5 text-xs">
                                {val}
                            </Badge>
                        );
                    }
                    if (c.key === 'missingCount') {
                        const val = Number(cellValue) || 0;
                        return (
                            <Badge variant="outline" className="min-w-[28px] justify-center text-sm font-bold">
                                {val}
                            </Badge>
                        );
                    }
                    return (
                        <span className={cn(c.type === COLUMN_TYPE.CURRENCY && 'font-mono font-bold text-primary')}>
                            {formatValue(cellValue, c.type)}
                        </span>
                    );
                }
            }))
        ];
        return cols;
    }, [reportConfig, page, pageSize]);

    /* ── جلب البيانات ── */
    const { data: pagedResult, isLoading, refetch } = useQuery({
        queryKey: ['report-data', reportId, filters, page, pageSize],
        queryFn: async () => {
            if (!reportConfig) return null;
            const result = await reportConfig.fetchData({ ...filters, pageNumber: page, pageSize });
            return result?.data ?? null;
        },
        enabled: !!reportConfig
    });

    /* ── جلب ملخص الإحصائيات ── */
    const { data: summaryData, isPending: isSummaryPending, isError: isSummaryError, refetch: refetchSummary } = useQuery({
        queryKey: ['report-summary', reportId, filters],
        queryFn: async () => {
            if (!reportConfig?.fetchSummary) return null;
            return await reportConfig.fetchSummary(filters);
        },
        enabled: !!reportConfig?.fetchSummary
    });

    const data = useMemo(() => pagedResult?.items ?? [], [pagedResult]);
    const totalCount = pagedResult?.totalCount ?? 0;

    /* ── معالجات الأحداث ── */
    const handleFilterChange = useCallback((key: string, value: string | number | boolean | null | undefined) => {
        setFilters((prev) => ({ ...prev, [key]: value }));
    }, []);

    const handleRefresh = useCallback(() => {
        void refetch();
        if (reportConfig?.fetchSummary) void refetchSummary();
    }, [refetch, refetchSummary, reportConfig]);

    const handleExport = useCallback((format: "excel" | "pdf" = "excel") => {
        if (reportConfig) exportReport(reportConfig.id, filters, format);
    }, [exportReport, reportConfig, filters]);

    const handlePrint = useCallback(() => window.print(), []);
    const handleTogglePrintView = useCallback(() => setIsPrintView(p => !p), []);
    const handleBack = useCallback(() => navigate('/reports'), [navigate]);

    const handleRowClick = useCallback((row: ReportDataRow) => {
        const fileId = (row.fileID || row.fileId || row.FileID || row.FileId || row.fileid) as number | undefined;
        if (fileId) {
            // For beneficiaries report, toggle expanded row
            if (reportId === 'dep-01') {
                setExpandedFileId(prev => prev === fileId ? null : fileId);
            } else {
                navigate(`/files/${fileId}`);
            }
        }
    }, [navigate, reportId]);

    const handlePageChange = useCallback((newPage: number) => {
        setPage(newPage);
    }, []);

    const handlePageSizeChange = useCallback((newSize: number) => {
        setPageSize(newSize);
        setPage(1);
    }, []);

    /* ── رقم التقرير ── */
    const reportNumber = useMemo(() =>
        reportConfig ? `REP-${reportConfig.id}-${new Date().getFullYear()}` : '',
    [reportConfig]);

    const printLayoutConfig = useMemo(() => ({
        sectionTitle:
            reportConfig?.category === 'التقاعد' || reportConfig?.category === 'المستحقون' ? 'إدارة المعاشات' :
            reportConfig?.category === 'الموارد البشرية' ? 'إدارة الشؤون الإدارية' :
            reportConfig ? `إدارة ${reportConfig.category}` : '',
        orientation: 'landscape' as const,
    }), [reportConfig]);

    /* ── عناصر ثابتة ── */
    const breadcrumbItems = useMemo(() => [
        { label: 'مركز التقارير', href: '/reports' },
        { label: reportConfig?.name ?? '' }
    ], [reportConfig]);

    const emptyIcon = useMemo(() => (
        <FileText className="w-12 h-12 opacity-100 text-muted-foreground" />
    ), []);

    /* ── حماية إضافية قبل الرسم ── */
    if (!reportConfig) return null;

    // Check if this is the special retirement file report
    if (reportId === 'ret-00') {
        return (
            <div className="space-y-6 animate-fade-in text-start">
                <div className="space-y-4 print:hidden">
                    <Breadcrumb items={breadcrumbItems} />
                    <div className="flex items-center gap-4">
                        <Button variant="outline" size="sm" onClick={handleBack} className="bg-background">
                            <ArrowRight className="w-5 h-5" />
                        </Button>
                        <div className="w-11 h-11 rounded-xl bg-primary/10 flex items-center justify-center">
                            <FilePieChart className="w-5 h-5 text-primary" />
                        </div>
                        <div>
                            <Heading level="h1" className="text-lg md:text-xl lg:text-2xl font-bold text-foreground">{reportConfig.name}</Heading>
                            <p className="text-sm text-muted-foreground mt-0.5">{reportConfig.description}</p>
                        </div>
                    </div>
                </div>
                <RetirementFileReportViewer />
            </div>
        );
    }

    return (
        <div className="space-y-6 animate-fade-in text-start">
            {/* ═══════════════════ Header (شاشة فقط) ═══════════════════ */}
            <div className="space-y-4 print:hidden">
                <Breadcrumb items={breadcrumbItems} />
                
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                    <div className="flex items-center gap-4">
                        <Button variant="outline" size="sm" onClick={handleBack} className="bg-background">
                            <ArrowRight className="w-5 h-5" />
                        </Button>
                        <div className="w-11 h-11 rounded-xl bg-primary/10 flex items-center justify-center">
                            <FilePieChart className="w-5 h-5 text-primary" />
                        </div>
                        <div>
                            <Heading level="h1" className="text-lg md:text-xl lg:text-2xl font-bold text-foreground">{reportConfig.name}</Heading>
                            <p className="text-sm text-muted-foreground mt-0.5">{reportConfig.description}</p>
                        </div>
                    </div>

                    <div className="flex items-center gap-2">
                        <Button
                            variant="secondary"
                            size="sm"
                            onClick={handleTogglePrintView}
                            className="h-9 hidden md:flex"
                        >
                            {isPrintView ? (
                                <>
                                    <Monitor className="w-4 h-4 ms-2" />
                                    عرض الشاشة
                                </>
                            ) : (
                                <>
                                    <FileText className="w-4 h-4 ms-2" />
                                    معاينة الطباعة
                                </>
                            )}
                        </Button>
                        <Button variant="outline" size="sm" onClick={handlePrint} className="h-11">
                            <Printer className="w-4 h-4 ms-2" />
                            طباعة
                        </Button>
                        <Button
                            variant={exportFormat === "excel" ? "success" : "outline"}
                            size="sm"
                            onClick={() => { setExportFormat("excel"); handleExport("excel"); }}
                            disabled={isExporting}
                            className="h-9"
                        >
                            {isExporting && exportFormat === "excel" ? <RefreshCw className="w-4 h-4 ms-2 animate-spin" /> : <Download className="w-4 h-4 ms-2" />}
                            تصدير Excel
                        </Button>
                        <Button
                            variant={exportFormat === "pdf" ? "success" : "outline"}
                            size="sm"
                            onClick={() => { setExportFormat("pdf"); handleExport("pdf"); }}
                            disabled={isExporting}
                            className="h-9"
                        >
                            {isExporting && exportFormat === "pdf" ? <RefreshCw className="w-4 h-4 ms-2 animate-spin" /> : <Download className="w-4 h-4 ms-2" />}
                            تصدير PDF
                        </Button>
                    </div>
                </div>
            </div>

            {/* ═══════════════════ المحتوى الخاص بالشاشة ═══════════════════ */}
            {!isPrintView && (
                <div className="space-y-6">
                    <div className="print:hidden">
                        <ReportFilters
                            filters={reportConfig.filters}
                            values={filters}
                            onChange={handleFilterChange}
                            onApply={handleRefresh}
                        />
                    </div>

                    {/* ── ملخص الإحصائيات ── */}
                    {reportConfig.summaryCards && reportConfig.summaryCards.length > 0 && (
                        <div className="print:hidden">
                            <ReportSummaryCards
                                cards={reportConfig.summaryCards}
                                data={data}
                                summaryData={summaryData ?? undefined}
                                loading={!!reportConfig.fetchSummary && isSummaryPending}
                                error={!!reportConfig.fetchSummary && isSummaryError}
                            />
                            {reportConfig.fetchSummary && isSummaryError && (
                                <p role="alert" className="text-sm text-destructive">
                                    تعذر تحميل الإجماليات. اضغط «تحديث التقرير» لإعادة المحاولة.
                                </p>
                            )}
                        </div>
                    )}

                    {/* ── الرسوم البيانية ── */}
                    {reportConfig.charts && reportConfig.charts.length > 0 && (
                        <div className="print:hidden">
                            <div className="flex items-center justify-between mb-4">
                                <Heading level="h3" className="text-lg font-bold">الرسوم البيانية</Heading>
                                <ChartToggle showChart={showChart} onToggle={() => setShowChart(!showChart)} />
                            </div>
                            {showChart && (
                                <ReportChartSection
                                    charts={reportConfig.charts}
                                    data={data}
                                />
                            )}
                        </div>
                    )}

                    <div className="print:hidden">
                        <DataTable
                            columns={tableColumns}
                            data={data}
                            loading={isLoading}
                            emptyMessage="لا توجد بيانات تطابق المعايير المختارة"
                            emptyIcon={emptyIcon}
                            onRowClick={handleRowClick}
                            pagination={{
                                page,
                                pageSize,
                                total: totalCount,
                                onPageChange: handlePageChange,
                                pageSizeOptions: [25, 50, 100],
                                onPageSizeChange: handlePageSizeChange,
                            }}
                        />
                    </div>

                    {/* ── القائمة المنسدلة للمستحقين (تقرير dep-01 فقط) ── */}
                    {reportId === 'dep-01' && expandedFileId && (
                        <div className="print:hidden border border-border rounded-xl bg-card overflow-hidden animate-in slide-in-from-top-2">
                            <div className="flex items-center justify-between px-4 py-3 bg-primary/5 border-b border-border">
                                <div className="flex items-center gap-2">
                                    <Users className="w-4 h-4 text-primary" />
                                    <span className="font-bold text-sm">المستحقون التابعون للملف</span>
                                    {isLoadingEntitleds && (
                                        <span className="text-xs text-muted-foreground">(جاري التحميل...)</span>
                                    )}
                                </div>
                                <Button
                                    variant="ghost"
                                    size="sm"
                                    onClick={() => setExpandedFileId(null)}
                                    className="h-7 px-2"
                                >
                                    <ChevronUp className="w-4 h-4" />
                                </Button>
                            </div>
                            <div className="p-4">
                                {!isLoadingEntitleds && entitledPersons.length === 0 && (
                                    <p className="text-sm text-muted-foreground text-center py-4">لا يوجد مستحقون مسجلون لهذا الملف</p>
                                )}
                                {!isLoadingEntitleds && entitledPersons.length > 0 && (
                                    <div className="space-y-2">
                                        {entitledPersons.map((person: EntitledPersonSummary) => (
                                            <div
                                                key={person.entitledID}
                                                className="flex items-center justify-between p-3 rounded-lg bg-muted/30 border border-border hover:bg-muted/50 transition-colors"
                                            >
                                                <div className="flex items-center gap-3">
                                                    <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center">
                                                        <Users className="w-4 h-4 text-primary" />
                                                    </div>
                                                    <div>
                                                        <p className="font-bold text-sm">{person.fullName}</p>
                                                        <p className="text-xs text-muted-foreground">
                                                            {person.relationshipName || '—'} • {person.nationalID || '—'}
                                                        </p>
                                                    </div>
                                                </div>
                                                <div className="flex items-center gap-2">
                                                    {person.phone && (
                                                        <Badge variant="outline" className="text-xs">{person.phone}</Badge>
                                                    )}
                                                    <Badge variant={person.isActive ? 'success' : 'destructive'} className="text-xs">
                                                        {person.isActive ? 'نشط' : 'غير نشط'}
                                                    </Badge>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        </div>
                    )}
                </div>
            )}

            {/* ═══════════════════ منطقة الطباعة الرسمية ═══════════════════ */}
            <PrintLayout
                printOnly={!isPrintView}
                reportName={reportConfig.description}
                reportNumber={reportNumber}
                attachments=""
                config={printLayoutConfig}
            >
                {/* شريط معلومات التقرير */}
                <div className="mb-4 flex justify-between text-sm text-black border-b border-black pb-2 font-bold">
                    <span>التصنيف: {reportConfig.category}</span>
                    <span>عدد السجلات: {totalCount.toLocaleString('ar-YE')}</span>
                    {filters.fromDate && filters.toDate && (
                        <span>
                            الفترة: {new Date(filters.fromDate as string).toLocaleDateString('ar-YE')} - {new Date(filters.toDate as string).toLocaleDateString('ar-YE')}
                        </span>
                    )}
                </div>

                {/* الجدول الرسمي */}
                <div className="border border-black overflow-x-auto">
                    <table className="w-full border-collapse text-[12px] text-black" dir="rtl">
                        <colgroup>
                            <col style={{ width: '5%' }} />
                            {reportConfig.columns.map((col, idx) => {
                                const w =
                                    col.key === 'missingDocsList' ? '30%' :
                                    col.key === 'fileNumber' ? '12%' :
                                    col.key === 'retireeName' ? '18%' :
                                    col.key === 'phone' ? '12%' : '11.5%';
                                return <col key={idx} style={{ width: w }} />;
                            })}
                        </colgroup>
                        <thead>
                            <tr className="bg-slate-200 border-b-2 border-black">
                                <th className="px-2 py-2 border-e border-black text-center font-extrabold">م</th>
                                {reportConfig.columns.map((col, idx) => (
                                    <th key={idx} className="px-2 py-2 border-e border-black text-center font-extrabold last:border-e-0">
                                        {col.label}
                                    </th>
                                ))}
                            </tr>
                        </thead>
                        <tbody>
                            {data.length === 0 ? (
                                <tr>
                                    <td colSpan={reportConfig.columns.length + 1} className="p-8 text-center text-black border-t border-black">
                                        لا توجد بيانات تطابق المعايير المختارة
                                    </td>
                                </tr>
                            ) : (
                                data.map((row, rowIdx) => (
                                    <tr key={rowIdx} className="border-b border-black last:border-b-0">
                                        <td className="px-2 py-2 border-e border-black text-center font-bold">{(page - 1) * pageSize + rowIdx + 1}</td>
                                        {reportConfig.columns.map((col, colIdx) => {
                                            const cellValue = row[col.key as keyof ReportDataRow];

                                            if (col.key === 'missingDocsList') {
                                                const docs = String(cellValue ?? '');
                                                const items = docs.split('، ').filter(Boolean);
                                                return (
                                                    <td key={colIdx} className="px-2 py-2 border-e border-black text-center last:border-e-0 text-[11px] break-words">
                                                        {items.length > 0 ? (
                                                            <ul className="list-disc list-inside text-start">
                                                                {items.map((d, di) => <li key={di} className="leading-tight">{d}</li>)}
                                                            </ul>
                                                        ) : '—'}
                                                    </td>
                                                );
                                            }
                                            if (col.key === 'maxDaysMissing') {
                                                const val = Number(cellValue) || 0;
                                                const colorClass = val >= 60 ? 'text-destructive font-bold' :
                                                              val >= 30 ? 'text-[hsl(var(--gov-warning))] font-bold' : '';
                                                return (
                                                    <td
                                                        key={colIdx}
                                                        className={cn("px-2 py-2 border-e border-black text-center last:border-e-0", colorClass)}
                                                    >
                                                        {val}
                                                    </td>
                                                );
                                            }
                                            if (col.key === 'missingCount') {
                                                const val = Number(cellValue) || 0;
                                                return (
                                                    <td key={colIdx} className="px-2 py-2 border-e border-black text-center last:border-e-0 font-bold">
                                                        <Badge variant="outline" className="min-w-[24px] justify-center">
                                                            {val}
                                                        </Badge>
                                                    </td>
                                                );
                                            }
                                            return (
                                                <td
                                                    key={colIdx}
                                                    className={cn(
                                                        'px-2 py-2 border-e border-black text-center last:border-e-0',
                                                        col.type === COLUMN_TYPE.CURRENCY && 'font-bold font-mono'
                                                    )}
                                                >
                                                    {formatValue(cellValue, col.type)}
                                                </td>
                                            );
                                        })}
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>

                {/* التوقيعات */}
                <PrintSignatureBlock signatures={SIGNATURES} className="mt-14" />
            </PrintLayout>
        </div>
    );
};

import { useQuery, useQueryClient } from "@tanstack/react-query";
import { Eye, FileText, FolderPlus, MoreHorizontal, Printer, Trash2, Users, X } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";

import { hrApi } from "@/api/hr";
import { lookupApi } from "@/api/pension";
import { retireeApi, type RetireeFilters, type RetireeListItem } from "@/api/retirees";
import { SearchDialog } from "@/components/common/SearchDialog";
import { CreateFileWizard } from "@/components/domain/retirement/CreateFileWizard";
import { Badge, BaseFormDialog, Button, CrudPageLayout, Skeleton } from "@/components/ui";
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/Accordion";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/DropdownMenu";
import { NativeSelect } from "@/components/ui/NativeSelect";
import { queryKeys } from "@/constants/queryKeys";
import { useApiMutation,useCrudState } from "@/hooks";
import { useConfirm } from "@/hooks/useConfirm";
import { useDebouncedSearch } from "@/hooks/useDebouncedSearch";
import { useHasPermission } from "@/stores/authStore";

// ─── Page ──────────────────────────────────────────────

const GENDER_OPTIONS = [
    { id: 1, name: "ذكر" },
    { id: 2, name: "أنثى" },
];

export function RetireesPage() {
    const navigate = useNavigate();
    const crud = useCrudState<RetireeListItem>();
    const { searchTerm: search, setSearchTerm: setSearch, debouncedValue: debouncedSearch } = useDebouncedSearch();
    const [focusedIndex, setFocusedIndex] = useState(-1);
    const focusedIndexRef = useRef(-1);
    const searchInputRef = useRef<HTMLInputElement>(null);
    const [page, setPage] = useState(1);
    const pageSize = 50;

    // ── Filters ──────────────────────────────────────────
    const [categoryId, setCategoryId] = useState<string>("");
    const [rankId, setRankId] = useState<string>("");
    const [gender, setGender] = useState<string>("");
    const [governorate, setGovernorate] = useState<string>("");

    const filters: RetireeFilters = useMemo(() => ({
        categoryId: categoryId ? Number(categoryId) : undefined,
        rankId: rankId ? Number(rankId) : undefined,
        gender: gender ? Number(gender) : undefined,
        governorate: governorate || undefined,
    }), [categoryId, rankId, gender, governorate]);

    const hasActiveFilters = !!(categoryId || rankId || gender || governorate);

    const clearFilters = () => {
        setCategoryId("");
        setRankId("");
        setGender("");
        setGovernorate("");
    };

    // ── Debounce Search ────────────────────────────────
    useEffect(() => {
        setPage(1);
        setFocusedIndex(-1);
        focusedIndexRef.current = -1;
    }, [debouncedSearch, categoryId, rankId, gender, governorate]);

    // ── Lookup data for filters ─────────────────────────
    const { data: categories } = useQuery({
        queryKey: ["lookups", "retiree-categories"],
        queryFn: () => lookupApi.getCategories(),
        staleTime: 5 * 60_000,
    });
    const { data: governorates } = useQuery({
        queryKey: ["lookups", "governorates"],
        queryFn: () => lookupApi.getGovernorates(),
        staleTime: 5 * 60_000,
    });
    const { data: ranks } = useQuery({
        queryKey: ["hr", "ranks"],
        queryFn: () => hrApi.getRanks(),
        staleTime: 5 * 60_000,
    });

    const queryClient = useQueryClient();
    const canCreateFile = useHasPermission("File.Create");
    const canViewDetails = useHasPermission("Retiree.View");
    const canViewFiles = useHasPermission("Retiree.View", "File.View.Sensitive", "File.Create", "File.Edit.BasicData");
    const canDelete = useHasPermission("Retiree.Delete");

    const { confirm, ConfirmDialogElement } = useConfirm();

    const deleteMutation = useApiMutation(
        (id: number) => retireeApi.delete(id),
        {
            successMessage: "تم حذف المتقاعد بنجاح",
            onSuccess: () => {
                refetch();
                queryClient.invalidateQueries({ queryKey: queryKeys.retirees.all });
            }
        }
    );

    const { data: retireesData, isLoading, refetch } = useQuery({
        queryKey: queryKeys.retirees.list({ page, pageSize, search: debouncedSearch, ...filters }),
        queryFn: () => retireeApi.getAll({ page, pageSize, search: debouncedSearch || undefined, ...filters })
    });

    const retirees = retireesData?.items || [];
    const totalCount = retireesData?.totalCount || 0;

    const handleDelete = async (row: RetireeListItem) => {
        const confirmed = await confirm({
            title: "حذف متقاعد",
            description: `هل أنت متأكد من حذف المتقاعد ${row.fullName}؟`,
            confirmLabel: "حذف",
            cancelLabel: "إلغاء",
            variant: "danger",
        });
        if (confirmed) deleteMutation.mutate(row.retireeID);
    };

    const columns = [
        {
            key: "fullName",
            header: "الاسم",
            render: (row: RetireeListItem) => (
                <div className="flex items-center gap-3">
                    <div className="w-9 h-9 rounded-full bg-primary/10 flex items-center justify-center text-primary">
                        <Users className="w-4 h-4" />
                    </div>
                    <div>
                        <p className="font-medium text-foreground">{row.fullName}</p>
                    </div>
                </div>
            ),
        },
        {
            key: "nationalID",
            header: "الرقم الوطني",
            render: (row: RetireeListItem) => (
                <span className="text-sm font-mono">
                    {row.nationalID || <span className="text-muted-foreground italic">غير معبأ</span>}
                </span>
            ),
        },
        {
            key: "militaryNumber",
            header: "الرقم العسكري",
            render: (row: RetireeListItem) => (
                <span className="text-sm font-mono text-primary font-bold">
                    {row.militaryNumber || <span className="text-muted-foreground italic">—</span>}
                </span>
            ),
        },
        {
            key: "rankName",
            header: "الرتبة",
            render: (row: RetireeListItem) => (
                <span className="text-sm">{row.rankName || "—"}</span>
            ),
        },
        {
            key: "category",
            header: "الفئة",
            render: (row: RetireeListItem) => {
                const name = categories?.find((c) => c.id === row.categoryId)?.name;
                return <span className="text-sm">{name || "—"}</span>;
            },
        },
        {
            key: "status",
            header: "الحالة",
            render: (row: RetireeListItem) => (
                <Badge variant={row.isAlive ? "success" : "outline"}>
                    {row.isAlive ? "على قيد الحياة" : "متوفى"}
                </Badge>
            ),
        },
        {
            key: "actions",
            header: "",
            render: (row: RetireeListItem) => (
                <div className="flex items-center gap-1">
                    {canDelete && (
                        <Button
                            variant="ghost-action"
                            size="sm"
                            className="text-destructive hover:text-destructive hover:bg-destructive/10 dark:hover:bg-destructive/20"
                            title="حذف المتقاعد"
                            aria-label="حذف المتقاعد"
                            onClick={(e) => {
                                e.stopPropagation();
                                void handleDelete(row);
                            }}
                        >
                            <Trash2 className="w-4 h-4" />
                        </Button>
                    )}
                    {canViewDetails && (
                        <Button
                            variant="ghost-action"
                            size="sm"
                            title="طباعة المباينة"
                            aria-label="طباعة المباينة"
                            onClick={(e) => {
                                e.stopPropagation();
                                navigate(`/retirees/${row.retireeID}/statement`);
                            }}
                        >
                            <Printer className="w-4 h-4" />
                        </Button>
                    )}
                    {row.fileCount === 0 ? (
                        <>
                            {canCreateFile && (
                                <Button
                                    variant="ghost-action"
                                    size="sm"
                                    onClick={() => {
                                        crud.openEdit(row);
                                    }}
                                >
                                    <FolderPlus className="w-4 h-4 ms-1" />
                                    إنشاء ملف
                                </Button>
                            )}
                            {canViewDetails && (
                                <Button
                                    variant="ghost-action"
                                    size="sm"
                                    onClick={() => navigate(`/retirees/${row.retireeID}`)}
                                >
                                    <Eye className="w-4 h-4 ms-1" />
                                    التفاصيل
                                </Button>
                            )}
                        </>
                    ) : (
                        <div className="flex items-center gap-1">
                            {canViewFiles && (
                                <Button
                                    variant="ghost-action"
                                    size="sm"
                                    onClick={() => navigate(`/files/${row.fileID}`)}
                                    title="عرض ملف التقاعد"
                                >
                                    <FileText className="w-4 h-4 ms-1" />
                                    عرض الملف
                                </Button>
                            )}
                            {canViewDetails && (
                                <Button
                                    variant="ghost-action"
                                    size="sm"
                                    onClick={() => navigate(`/retirees/${row.retireeID}`)}
                                    title="عرض تفاصيل المتقاعد"
                                    aria-label="عرض تفاصيل المتقاعد"
                                >
                                    <Eye className="w-4 h-4" />
                                </Button>
                            )}
                        </div>
                    )}
                </div>
            ),
        },
    ];

    const renderMobileCard = (row: RetireeListItem) => {
        const categoryName = categories?.find((category) => category.id === row.categoryId)?.name;
        return (
            <div className="space-y-2 p-2.5">
                <div className="flex items-start gap-2">
                    <h2 className="min-w-0 flex-1 break-words text-base font-bold leading-relaxed text-foreground">
                        {row.fullName}
                    </h2>
                    <Badge variant={row.isAlive ? "success" : "secondary"} className="shrink-0">
                        {row.isAlive ? "على قيد الحياة" : "متوفى"}
                    </Badge>
                </div>
                <div className="flex min-w-0 items-center gap-2 text-xs text-muted-foreground">
                    <p className="shrink-0 whitespace-nowrap">
                        العسكري: <bdi dir="ltr" className="font-mono font-semibold text-foreground">{row.militaryNumber || "—"}</bdi>
                    </p>
                    <p className="min-w-0 flex-1 truncate" title={`الرقم الوطني: ${row.nationalID || "غير معبأ"}`}>
                        الوطني: <bdi dir="ltr" className="font-mono text-foreground">{row.nationalID || "غير معبأ"}</bdi>
                    </p>
                </div>
                {(row.rankName || categoryName) && (
                    <p className="truncate text-xs text-muted-foreground" title={[row.rankName, categoryName].filter(Boolean).join(" · ")}>
                        {[row.rankName, categoryName].filter(Boolean).join(" · ")}
                    </p>
                )}
                {(canViewDetails || canCreateFile || canViewFiles || canDelete) && (
                    <div className="flex items-center gap-2">
                        {row.fileCount === 0 && canCreateFile && (
                            <Button variant="default" size="sm" className="min-w-0 flex-1" onClick={() => crud.openEdit(row)}>
                                <FolderPlus className="h-4 w-4 shrink-0" aria-hidden="true" />
                                إنشاء ملف
                            </Button>
                        )}
                        {canViewDetails && (
                            <Button
                                variant="outline"
                                size="sm"
                                className="min-w-0 flex-1"
                                onClick={() => navigate(`/retirees/${row.retireeID}/statement`)}
                            >
                                <Printer className="h-4 w-4 shrink-0" aria-hidden="true" />
                                طباعة المباينة
                            </Button>
                        )}
                        {(canViewDetails || (row.fileID && canViewFiles) || canDelete) && (
                            <DropdownMenu>
                                <DropdownMenuTrigger asChild>
                                    <Button variant="outline" size="icon" className="shrink-0" aria-label="إجراءات المتقاعد" title="المزيد">
                                        <MoreHorizontal className="h-4 w-4" aria-hidden="true" />
                                    </Button>
                                </DropdownMenuTrigger>
                                <DropdownMenuContent align="end">
                                    {canViewDetails && (
                                        <DropdownMenuItem onSelect={() => navigate(`/retirees/${row.retireeID}`)}>
                                            <Eye className="h-4 w-4" aria-hidden="true" />
                                            تفاصيل المتقاعد
                                        </DropdownMenuItem>
                                    )}
                                    {row.fileID && canViewFiles && (
                                        <DropdownMenuItem onSelect={() => navigate(`/files/${row.fileID}`)}>
                                            <FileText className="h-4 w-4" aria-hidden="true" />
                                            عرض ملف التقاعد
                                        </DropdownMenuItem>
                                    )}
                                    {canDelete && (
                                        <DropdownMenuItem className="text-destructive" onSelect={() => { void handleDelete(row); }}>
                                            <Trash2 className="h-4 w-4" aria-hidden="true" />
                                            حذف المتقاعد
                                        </DropdownMenuItem>
                                    )}
                                </DropdownMenuContent>
                            </DropdownMenu>
                        )}
                    </div>
                )}
            </div>
        );
    };

    const filterFields = (
        <div className="grid grid-cols-2 gap-2 lg:grid-cols-4">
            <NativeSelect
                label="الفئة"
                value={categoryId}
                onChange={setCategoryId}
                options={[
                    { value: "", label: "جميع الفئات" },
                    ...(categories ?? []).map((category) => ({ value: String(category.id), label: category.name })),
                ]}
            />
            <NativeSelect
                label="الرتبة"
                value={rankId}
                onChange={setRankId}
                options={[
                    { value: "", label: "جميع الرتب" },
                    ...(ranks ?? []).map((rank) => ({ value: String(rank.rankID), label: rank.rankName })),
                ]}
            />
            <NativeSelect
                label="الجنس"
                value={gender}
                onChange={setGender}
                options={[
                    { value: "", label: "الكل" },
                    ...GENDER_OPTIONS.map((option) => ({ value: String(option.id), label: option.name })),
                ]}
            />
            <NativeSelect
                label="المحافظة"
                value={governorate}
                onChange={setGovernorate}
                options={[
                    { value: "", label: "جميع المحافظات" },
                    ...(governorates ?? []).map((option) => ({ value: option.name, label: option.name })),
                ]}
            />
        </div>
    );
    const clearFiltersButton = hasActiveFilters ? (
        <Button variant="ghost" size="sm" onClick={clearFilters} className="text-destructive">
            <X className="h-4 w-4" aria-hidden="true" />
            مسح الفلاتر
        </Button>
    ) : null;

    // ── Keyboard Navigation ────────────────────────────
    const handleSearchKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement>) => {
        if (e.key === "ArrowDown") {
            e.preventDefault();
            setFocusedIndex(prev => {
                const next = prev + 1;
                const clamped = next < retirees.length ? next : prev;
                focusedIndexRef.current = clamped;
                return clamped;
            });
        } else if (e.key === "ArrowUp") {
            e.preventDefault();
            setFocusedIndex(prev => {
                const clamped = prev > 0 ? prev - 1 : prev;
                focusedIndexRef.current = clamped;
                return clamped;
            });
        } else if (e.key === "Enter") {
            e.preventDefault();
            const idx = focusedIndexRef.current;
            if (idx >= 0 && idx < retirees.length) {
                navigate(`/retirees/${retirees[idx].retireeID}`);
            }
        } else if (e.key === "Escape") {
            setFocusedIndex(-1);
            focusedIndexRef.current = -1;
        }
    }, [retirees, navigate]);

    // Scroll to focused row
    useEffect(() => {
        if (focusedIndex >= 0) {
            const row = document.querySelector(`[data-row-index="${focusedIndex}"]`)
                      || document.querySelector(`[data-index="${focusedIndex}"]`);
            if (row) {
                row.scrollIntoView({ behavior: "smooth", block: "nearest" });
            }
        }
    }, [focusedIndex]);

    return (
        <CrudPageLayout
            density="compact"
            title="المتقاعدون"
            titleSuffix={
                isLoading ? (
                    <Skeleton className="h-6 w-16 rounded-full" />
                ) : (
                    <span className="inline-flex items-center gap-1.5 rounded-full bg-primary/10 px-2.5 py-0.5 text-sm font-bold text-primary tabular-nums">
                        <Users className="w-3.5 h-3.5" aria-hidden="true" />
                        {totalCount.toLocaleString("en-US")}
                    </span>
                )
            }
            description="سجل المتقاعدين مع إمكانية البحث والمباينة"
            columns={columns}
            data={retirees}
            loading={isLoading}
            searchable
            searchInHeader
            searchLabel="البحث عن متقاعد"
            searchPlaceholder="الاسم أو الرقم العسكري"
            onSearchChange={(val) => setSearch(val)}
            searchValue={search}
            onSearchKeyDown={handleSearchKeyDown}
            searchInputRef={searchInputRef}
            focusedRowIndex={focusedIndex}
            renderMobileCard={renderMobileCard}
            mobileScrollMode="page"
            rowClassName={(row) => row.isAlive
                ? "max-sm:bg-[color:color-mix(in_srgb,hsl(var(--gov-success))_8%,hsl(var(--card)))]"
                : "max-sm:bg-muted"}
            onRowClick={(row) => { if (row.fileID) navigate(`/files/${row.fileID}`); else navigate(`/retirees/${row.retireeID}`); }}
            headerActions={
                <SearchDialog
                    value={search}
                    onSelect={(val) => { setSearch(val); setPage(1); }}
                    queryKey={["retirees", "dialog-search"]}
                    fetchFn={(term) => retireeApi.getAll({ page: 1, pageSize: 100, search: term || undefined })}
                    getName={(r) => r.fullName}
                    getSubtitle={(r) => r.nationalID || r.militaryNumber || ""}
                    title="بحث بالاسم"
                    placeholder="اكتب اسم المتقاعد..."
                    hideTrigger
                />
            }
            rowKey={(row) => row.retireeID}
            pagination={{
                page,
                pageSize,
                total: totalCount,
                onPageChange: (p) => setPage(p)
            }}
        >
            <Accordion type="single" collapsible className="sm:hidden">
                <AccordionItem value="retiree-filters" className="border-0">
                    <AccordionTrigger density="compact">
                        <span className="flex items-center gap-2">
                            الفلاتر
                            {hasActiveFilters && (
                                <Badge variant="secondary">{[categoryId, rankId, gender, governorate].filter(Boolean).length} مفعّل</Badge>
                            )}
                        </span>
                    </AccordionTrigger>
                    <AccordionContent className="space-y-1 pb-0">
                        {filterFields}
                        {clearFiltersButton}
                    </AccordionContent>
                </AccordionItem>
            </Accordion>
            <div className="hidden space-y-1 sm:block">
           
                {filterFields}
            </div>
            <BaseFormDialog
                open={crud.isFormOpen}
                onOpenChange={crud.onOpenChange}
                title="فتح ملف تقاعد جديد"
                description={crud.selectedItem
                    ? `فتح ملف تقاعد للمتقاعد: ${crud.selectedItem.fullName}. أكمل الخطوات التالية.`
                    : "قم بإدخال بيانات ملف التقاعد الجديد في الخطوات التالية."}
                size="4xl"
                footer={null}
            >
                {crud.selectedItem && (
                    <CreateFileWizard
                        key={crud.selectedItem.retireeID}
                        initialRetireeId={crud.selectedItem.retireeID}
                        initialRetireeName={crud.selectedItem.fullName}
                        onSuccess={() => {
                            crud.closeForm();
                            refetch();
                        }}
                        onCancel={() => {
                            crud.closeForm();
                        }}
                    />
                )}
            </BaseFormDialog>
            {ConfirmDialogElement}
        </CrudPageLayout>
    );
}

import { useQuery, useQueryClient } from "@tanstack/react-query";
import {
    ArrowRight,
    Check,
    Contrast,
    Crop,
    Download,
    Loader2,
    RotateCcw,
    RotateCw,
    Save,
    Sun,
    Undo,
    ZoomIn,
    ZoomOut,
} from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { toast } from "sonner";

import { documentsApi } from "@/api/documents";
import { Heading, Text } from "@/components/ui";
import { Button } from "@/components/ui/Button";
import { Card } from "@/components/ui/Card";
import { CornerEditor } from "@/components/ui/CornerEditor";
import { Slider } from "@/components/ui/Slider";
import { useDocumentBlob } from "@/hooks/useDocumentBlob";
import { DEFAULT_CROP_TIMEOUT_MS, runCropPipeline } from "@/lib/crop-pipeline";
import { getCropBudget } from "@/lib/crop-region";
import { getDeviceCapabilities } from "@/lib/device-capabilities";
import { getDocumentUrl } from "@/lib/utils";


interface DocumentData {
    documentID: number;
    documentTypeID: number;
    documentTypeName: string;
    fileName: string;
    filePath?: string | null;
    notes?: string | null;
    uploadedByUser?: string | null;
    createdAt: string;
}

interface ImageSettings {
    brightness: number;
    contrast: number;
    sharpness: number;
    rotation: 0 | 90 | 180 | 270;
}

const DEFAULT_SETTINGS: ImageSettings = {
    brightness: 100,
    contrast: 100,
    sharpness: 0,
    rotation: 0,
};

const IMAGE_EXTENSIONS = [".jpg", ".jpeg", ".png", ".gif", ".bmp", ".webp", ".tiff", ".tif"];
/** مهلة رفع الملف — مستقلة عن مهلة المعالجة */
const UPLOAD_TIMEOUT_MS = 60000;

// ─── Canvas Pool ─────────────────────────────────────────
const globalCanvasPool: HTMLCanvasElement[] = [];

function acquireCanvas(w?: number, h?: number): HTMLCanvasElement {
    const c = globalCanvasPool.pop() || window.document.createElement("canvas");
    if (w !== undefined) c.width = w;
    if (h !== undefined) c.height = h;
    return c;
}

function releaseCanvas(c: HTMLCanvasElement) {
    c.width = 0;
    c.height = 0;
    if (globalCanvasPool.length < 3) globalCanvasPool.push(c);
}

function isImageDocument(doc: DocumentData | null): boolean {
    if (!doc?.fileName) return false;
    const lower = doc.fileName.toLowerCase();
    return IMAGE_EXTENSIONS.some((ext) => lower.endsWith(ext));
}

// ─── Helpers ─────────────────────────────────────────────

/**
 * تحميل عنصر صورة من blob URL.
 *
 * لا crossOrigin: رابط blob: نفس الأصل، فلا يتلوث الـ canvas عند toBlob.
 * تحميل صورة من رابط API المطلق في وضع CORS يفشل في المتصفح ويُسقط
 * المعالجة — الجلب يمرّ عبر useDocumentBlob (النمط الموحّد).
 */
function loadImageElement(src: string): Promise<HTMLImageElement> {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => resolve(img);
        img.onerror = () => reject(new Error("فشل تحميل الصورة"));
        img.src = src;
    });
}

function rotateImage(
    img: HTMLImageElement,
    rotation: 0 | 90 | 180 | 270,
): HTMLCanvasElement {
    const isVertical = rotation === 90 || rotation === 270;
    const w = isVertical ? img.height : img.width;
    const h = isVertical ? img.width : img.height;
    const canvas = acquireCanvas(w, h);
    const ctx = canvas.getContext("2d");
    if (!ctx) throw new Error("فشل إنشاء سياق الرسم للدوران");

    ctx.translate(w / 2, h / 2);
    ctx.rotate((rotation * Math.PI) / 180);
    ctx.drawImage(img, -img.width / 2, -img.height / 2);

    return canvas;
}

function rotateCorners(
    corners: { x: number; y: number }[],
    rotation: 0 | 90 | 180 | 270,
    naturalW: number,
    naturalH: number,
): { x: number; y: number }[] {
    switch (rotation) {
        case 90:  return corners.map(c => ({ x: naturalH - c.y, y: c.x }));
        case 180: return corners.map(c => ({ x: naturalW - c.x, y: naturalH - c.y }));
        case 270: return corners.map(c => ({ x: c.y, y: naturalW - c.x }));
        default:  return corners;
    }
}

function canvasToFile(canvas: HTMLCanvasElement, originalName: string): Promise<File> {
    return new Promise((resolve, reject) => {
        canvas.toBlob((blob) => {
            if (!blob) {
                reject(new Error("فشل تحويل Canvas"));
                return;
            }
            // Strip GUID prefix added by LocalFileStorageService (e.g. "guid_original.jpg")
            const cleaned = originalName.replace(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}_/i, "");
            const baseName = cleaned.replace(/\.[^.]+$/, "");
            const name = baseName.endsWith("_scanned") ? `${baseName}.jpg` : `${baseName}_scanned.jpg`;
            resolve(new File([blob], name, { type: "image/jpeg" }));
        }, "image/jpeg", 0.85);
    });
}

function applySharpen(
    ctx: CanvasRenderingContext2D,
    width: number,
    height: number,
    amount: number,
) {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const original = new Uint8ClampedArray(data);

    const kernel = [
        0, -1, 0,
        -1, 5, -1,
        0, -1, 0,
    ];

    for (let y = 1; y < height - 1; y++) {
        for (let x = 1; x < width - 1; x++) {
            for (let c = 0; c < 3; c++) {
                let sum = 0;
                for (let ky = -1; ky <= 1; ky++) {
                    for (let kx = -1; kx <= 1; kx++) {
                        const idx = ((y + ky) * width + (x + kx)) * 4 + c;
                        sum += original[idx] * kernel[(ky + 1) * 3 + (kx + 1)];
                    }
                }
                const idx = (y * width + x) * 4 + c;
                data[idx] = Math.min(255, Math.max(0, original[idx] + (sum - original[idx]) * amount));
            }
        }
    }

    ctx.putImageData(imageData, 0, 0);
}

function renderSettingsImage(
    ctx: CanvasRenderingContext2D,
    img: HTMLImageElement,
    settings: ImageSettings,
    scale: number,
): void {
    const canvas = ctx.canvas;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    ctx.translate(canvas.width / 2, canvas.height / 2);
    ctx.rotate((settings.rotation * Math.PI) / 180);
    ctx.scale(scale, scale);
    ctx.drawImage(img, -img.width / 2, -img.height / 2);
    ctx.restore();

    const brightness = settings.brightness / 100;
    const contrast = settings.contrast / 100;
    ctx.filter = `brightness(${brightness}) contrast(${contrast})`;
    ctx.drawImage(canvas, 0, 0);
    ctx.filter = "none";

    if (settings.sharpness > 0) {
        applySharpen(ctx, canvas.width, canvas.height, settings.sharpness / 100);
    }
}

function renderExportCanvas(img: HTMLImageElement, settings: ImageSettings): HTMLCanvasElement {
    const isVertical = settings.rotation === 90 || settings.rotation === 270;
    const canvas = acquireCanvas(
        isVertical ? img.height : img.width,
        isVertical ? img.width : img.height,
    );
    const ctx = canvas.getContext("2d");
    if (!ctx) {
        releaseCanvas(canvas);
        throw new Error("فشل إنشاء سياق الرسم");
    }
    // التصدير من الأصل بالدقة الكاملة — دقة المعاينة لا تدخل هنا
    renderSettingsImage(ctx, img, settings, 1);
    return canvas;
}

// ─── Component ───────────────────────────────────────────

const deviceCapabilities = getDeviceCapabilities();

export function DocumentProcessPage() {
    const { id, docId } = useParams<{ id: string; docId: string }>();
    const fileId = parseInt(id ?? "", 10);
    const documentId = parseInt(docId ?? "", 10);
    const navigate = useNavigate();
    const queryClient = useQueryClient();

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const originalImageRef = useRef<HTMLImageElement | null>(null);
    const settingsRef = useRef<ImageSettings>(DEFAULT_SETTINGS);
    // رقم العملية الجارية: أي انتهاء مهلة أو إلغاء يجعل الفحص اللاحق يرفض نتائج العملية القديمة
    const operationRef = useRef(0);
    const abortRef = useRef<AbortController | null>(null);

    const [settings, setSettings] = useState<ImageSettings>(DEFAULT_SETTINGS);
    const [history, setHistory] = useState<ImageSettings[]>([DEFAULT_SETTINGS]);
    const [historyIndex, setHistoryIndex] = useState(0);
    const [zoom, setZoom] = useState(1);
    const [isProcessing, setIsProcessing] = useState(false);

    const [isCropMode, setIsCropMode] = useState(false);
    const [manualCorners, setManualCorners] = useState<{ x: number; y: number }[] | null>(null);

    useEffect(() => {
        settingsRef.current = settings;
    }, [settings]);

    // إعادة تهيئة جلسة التحرير عند تغيير الوثيقة — منع تسريب الإعدادات والسجل والزوايا بين الوثائق
    useEffect(() => {
        setSettings(DEFAULT_SETTINGS);
        setHistory([DEFAULT_SETTINGS]);
        setHistoryIndex(0);
        setZoom(1);
        setIsProcessing(false);
        setIsCropMode(false);
        setManualCorners(null);
        settingsRef.current = DEFAULT_SETTINGS;
        originalImageRef.current = null;
    }, [documentId]);

    const { data: docData, isLoading } = useQuery({
        queryKey: ["document", documentId],
        queryFn: () => documentsApi.getById(documentId),
        enabled: documentId > 0 && !isNaN(documentId),
    });

    // الجلب يمرّ عبر useDocumentBlob — النمط الموحّد لملفات محمية (JWT).
    const { blobUrl: imageBlobUrl, loading: blobLoading } = useDocumentBlob(docData?.filePath);

    const imageUrl = useMemo(() => {
        if (!docData?.filePath) return null;
        return getDocumentUrl(docData.filePath);
    }, [docData?.filePath]);

    useEffect(() => {
        if (!imageBlobUrl) return;

        let cancelled = false;

        void (async () => {
            try {
                const img = await loadImageElement(imageBlobUrl);
                if (cancelled) return;
                originalImageRef.current = img;
                applySettings(settingsRef.current);
            } catch {
                if (cancelled) return;
                toast.error("تعذّر تحميل الصورة، تحقّق من الاتصال أو من صلاحية الجلسة");
            }
        })();

        return () => {
            cancelled = true;
        };
    }, [imageBlobUrl]);

    // فشل الجلب: useDocumentBlob يُبقي blobUrl=null و loading=false
    useEffect(() => {
        if (!docData?.filePath || blobLoading) return;
        if (imageBlobUrl) return;
        if (originalImageRef.current) return;
        toast.error("تعذّر تحميل الصورة، تحقّق من الاتصال أو من صلاحية الجلسة");
    }, [docData?.filePath, blobLoading, imageBlobUrl]);

    const applySettings = useCallback(
        (newSettings: ImageSettings) => {
            const canvas = canvasRef.current;
            const img = originalImageRef.current;
            if (!canvas || !img) return;

            setIsProcessing(true);

            const ctx = canvas.getContext("2d");
            if (!ctx) {
                setIsProcessing(false);
                return;
            }

            const { previewDim } = getCropBudget(deviceCapabilities);
            const isVertical = newSettings.rotation === 90 || newSettings.rotation === 270;
            const baseW = isVertical ? img.height : img.width;
            const baseH = isVertical ? img.width : img.height;
            // معاينة بدقة منفصلة عن التصدير: حجم شاشة المعاينة لا يمس دقة الحفظ
            const scale = Math.min(1, previewDim / baseW, previewDim / baseH);
            canvas.width = Math.max(1, Math.round(baseW * scale));
            canvas.height = Math.max(1, Math.round(baseH * scale));

            renderSettingsImage(ctx, img, newSettings, scale);

            setIsProcessing(false);
        },
        []
    );

    useEffect(() => {
        if (!isCropMode) {
            applySettings(settings);
        }
    }, [settings, applySettings, isCropMode]);

    const undo = useCallback(() => {
        if (historyIndex > 0) {
            const newIndex = historyIndex - 1;
            setHistoryIndex(newIndex);
            setSettings(history[newIndex]);
        }
    }, [historyIndex, history]);

    const redo = useCallback(() => {
        if (historyIndex < history.length - 1) {
            const newIndex = historyIndex + 1;
            setHistoryIndex(newIndex);
            setSettings(history[newIndex]);
        }
    }, [historyIndex, history]);

    const saveToHistory = useCallback(
        (newSettings: ImageSettings) => {
            const newHistory = history.slice(0, historyIndex + 1);
            newHistory.push(newSettings);
            setHistory(newHistory);
            setHistoryIndex(newHistory.length - 1);
        },
        [history, historyIndex]
    );

    const updateSetting = useCallback(
        <K extends keyof ImageSettings>(key: K, value: ImageSettings[K]) => {
            const newSettings = { ...settings, [key]: value };
            setSettings(newSettings);
            saveToHistory(newSettings);
        },
        [settings, saveToHistory]
    );

    const rotate = useCallback(
        (delta: 90 | -90) => {
            const newRotation = ((settings.rotation + delta + 360) % 360) as 0 | 90 | 180 | 270;
            updateSetting("rotation", newRotation);
        },
        [settings.rotation, updateSetting]
    );

    const enableCropMode = useCallback(() => {
        setIsCropMode(true);
        setManualCorners(null);
    }, []);

    const cancelCrop = useCallback(() => {
        setIsCropMode(false);
        setManualCorners(null);
        applySettings(settings);
    }, [applySettings, settings]);

    const applyCrop = useCallback(async () => {
        if (!manualCorners || manualCorners.length !== 4 || !imageUrl || !docData) return;

        setIsProcessing(true);

        const opId = ++operationRef.current;
        const controller = new AbortController();
        abortRef.current = controller;

        let workCanvas: HTMLCanvasElement | null = null;
        let outCanvas: HTMLCanvasElement | null = null;

        // مهلة المعالجة فقط (WebGL/Worker/CPU) — الرفع خارجها
        const timeoutId = setTimeout(() => {
            // إنهاء فعلي: توقف رقم العملية (تُرفض كل نتيجة لاحقة) وإلغاء المعالجة الجارية
            operationRef.current++;
            controller.abort();
            toast.error("انتهت مهلة القص، يرجى المحاولة مرة أخرى");
            setIsProcessing(false);
        }, DEFAULT_CROP_TIMEOUT_MS);

        try {
            // الصورة محمّلة مسبقاً في originalImageRef من blob: — لا جلب ثانٍ
            const img = originalImageRef.current;
            if (!img) throw new Error("الصورة غير محمّلة");
            if (opId !== operationRef.current) return;

            const hasRotation = settings.rotation !== 0;
            const rotatedCorners = hasRotation
                ? rotateCorners(manualCorners, settings.rotation, img.naturalWidth, img.naturalHeight)
                : manualCorners;

            let regionSource: CanvasImageSource;
            let regionSourceW: number;
            let regionSourceH: number;

            if (hasRotation) {
                workCanvas = rotateImage(img, settings.rotation);
                regionSource = workCanvas;
                regionSourceW = workCanvas.width;
                regionSourceH = workCanvas.height;
            } else {
                // بدون دوران: لا تُنشأ نسخة بالحجم الطبيعي — تُستخرج منطقة القص مباشرة من الأصل
                regionSource = img;
                regionSourceW = img.naturalWidth;
                regionSourceH = img.naturalHeight;
            }

            let finalData: Uint8ClampedArray<ArrayBuffer>;
            let finalW: number;
            let finalH: number;

            try {
                const result = await runCropPipeline({
                    source: regionSource,
                    sourceWidth: regionSourceW,
                    sourceHeight: regionSourceH,
                    corners: rotatedCorners,
                    capabilities: deviceCapabilities,
                    signal: controller.signal,
                });
                finalData = result.data;
                finalW = result.width;
                finalH = result.height;
            } catch (error) {
                console.error("Processor failed:", error);
                const message = error instanceof Error ? error.message : "";
                throw new Error(/[\u0600-\u06FF]/.test(message) ? message : "فشل معالجة الصورة");
            }

            if (opId !== operationRef.current) return;

            // انتهت المعالجة: تُلغى المهلة قبل الحفظ والرفع
            clearTimeout(timeoutId);

            outCanvas = acquireCanvas(finalW, finalH);
            const outCtx = outCanvas.getContext("2d");
            if (!outCtx) throw new Error("فشل إنشاء سياق الإخراج");
            outCtx.putImageData(new ImageData(finalData, finalW, finalH), 0, 0);

            const brightness = settings.brightness / 100;
            const contrast = settings.contrast / 100;
            if (brightness !== 1 || contrast !== 1) {
                outCtx.filter = `brightness(${brightness}) contrast(${contrast})`;
                outCtx.drawImage(outCanvas, 0, 0);
                outCtx.filter = "none";
            }

            if (settings.sharpness > 0) {
                applySharpen(outCtx, finalW, finalH, settings.sharpness / 100);
            }

            const file = await canvasToFile(outCanvas, docData.fileName);
            releaseCanvas(outCanvas);
            outCanvas = null;

            if (opId !== operationRef.current) return;

            // استبدال الأصل: تحديث الوثيقة الحالية بدل إنشاء نسخة جديدة — المالك والحقول تبقى كما هي
            const formData = new FormData();
            formData.append("File", file);
            formData.append("DocumentTypeID", String(docData.documentTypeID));
            formData.append("Notes", `صورة مقصوصة من: ${docData.fileName}`);

            // مهلة الرفع منفصلة: الطلب يُلغى فعلياً عبر signal
            const uploadController = new AbortController();
            abortRef.current = uploadController;
            const uploadTimeoutId = setTimeout(() => uploadController.abort(), UPLOAD_TIMEOUT_MS);
            try {
                await documentsApi.update(docData.documentID, formData, uploadController.signal);
            } catch (error) {
                if (uploadController.signal.aborted) {
                    throw new Error("انتهت مهلة رفع الصورة، يرجى المحاولة مرة أخرى");
                }
                throw error;
            } finally {
                clearTimeout(uploadTimeoutId);
            }
            if (opId !== operationRef.current) return;

            toast.success("تم القص والحفظ بنجاح");
            setIsCropMode(false);
            setManualCorners(null);
            await queryClient.invalidateQueries({ queryKey: ["documents", fileId] });
            await queryClient.invalidateQueries({ queryKey: ["document", documentId] });
            navigate(`/files/${id}?tab=documents`);
        } catch (error) {
            if (opId !== operationRef.current) return; // نتيجة ملغاة — لا رسالة ولا واجهة
            console.error("Crop error:", error);
            toast.error(error instanceof Error ? error.message : "فشل قص الصورة");
        } finally {
            clearTimeout(timeoutId);
            if (workCanvas) releaseCanvas(workCanvas);
            if (outCanvas) releaseCanvas(outCanvas);
            setIsProcessing(false);
        }
    }, [manualCorners, imageUrl, docData, settings, fileId, documentId, id, navigate, queryClient]);

    const handleSave = useCallback(async () => {
        const img = originalImageRef.current;
        if (!img || !docData) return;

        setIsProcessing(true);

        const opId = ++operationRef.current;
        const controller = new AbortController();
        abortRef.current = controller;

        try {
            // إعادة الرسم من الأصل بالدقة الكاملة — دقة المعاينة المصغرة لا تُحفظ
            const exportCanvas = renderExportCanvas(img, settings);
            let file: File;
            try {
                file = await canvasToFile(exportCanvas, docData.fileName);
            } finally {
                releaseCanvas(exportCanvas);
            }
            if (opId !== operationRef.current) return;

            // استبدال الأصل بدل رفع نسخة جديدة — يمنع فقدان المالك والبيانات الوصفية
            const formData = new FormData();
            formData.append("File", file);
            formData.append("DocumentTypeID", String(docData.documentTypeID));
            formData.append("Notes", `صورة معالجة من: ${docData.fileName}`);

            await documentsApi.update(docData.documentID, formData, controller.signal);
            if (opId !== operationRef.current) return;

            toast.success("تم حفظ الصورة المعالجة بنجاح");
            await queryClient.invalidateQueries({ queryKey: ["documents", fileId] });
            await queryClient.invalidateQueries({ queryKey: ["document", documentId] });
            navigate(`/files/${id}?tab=documents`);
        } catch (error) {
            if (opId !== operationRef.current) return;
            console.error("Save error:", error);
            toast.error("فشل حفظ الصورة");
        } finally {
            setIsProcessing(false);
        }
    }, [docData, settings, fileId, documentId, id, navigate, queryClient]);

    const handleDownload = useCallback(() => {
        const img = originalImageRef.current;
        if (!img) return;

        const link = window.document.createElement("a");
        // الامتداد من صيغة التصدير الفعلية (JPEG) لا من اسم الأصل
        const baseName = (docData?.fileName || "image").replace(/\.[^.]+$/, "");
        link.download = `processed_${baseName}.jpg`;
        const exportCanvas = renderExportCanvas(img, settings);
        try {
            link.href = exportCanvas.toDataURL("image/jpeg", 0.92);
        } finally {
            releaseCanvas(exportCanvas);
        }
        link.click();
    }, [docData?.fileName, settings]);

    const resetSettings = useCallback(() => {
        setSettings(DEFAULT_SETTINGS);
        saveToHistory(DEFAULT_SETTINGS);
    }, [saveToHistory]);

    if (isLoading) {
        return (
            <div className="flex items-center justify-center min-h-screen">
                <Loader2 className="w-8 h-8 animate-spin text-primary" />
            </div>
        );
    }

    if (!docData || !isImageDocument(docData)) {
        return (
            <div className="flex flex-col items-center justify-center min-h-screen gap-4">
                <p className="text-muted-foreground">الوثيقة غير موجودة أو ليست صورة</p>
                <Button onClick={() => navigate(`/files/${id}?tab=documents`)}>
                    العودة للوثائق
                </Button>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-background flex flex-col">
            <header className="border-b bg-card sticky top-0 z-10">
                <div className="container mx-auto px-4 py-3 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => navigate(`/files/${id}?tab=documents`)}
                            className="rounded-full"
                        >
                            <ArrowRight className="w-5 h-5" />
                        </Button>
                        <div>
                            <Heading level="h1" className="font-bold text-lg">{docData.documentTypeName}</Heading>
                            <Text variant="caption">{docData.fileName}</Text>
                        </div>
                    </div>
                    <div className="flex items-center gap-2">
                        {isCropMode ? (
                            <>
                                <Button
                                    variant="outline"
                                    size="sm"
                                    onClick={cancelCrop}
                                    disabled={isProcessing}
                                    className="gap-2"
                                >
                                    إلغاء
                                </Button>
                                <Button
                                    size="sm"
                                    onClick={applyCrop}
                                    disabled={!manualCorners || manualCorners.length !== 4 || isProcessing}
                                    className="gap-2"
                                >
                                    {isProcessing ? (
                                        <Loader2 className="w-4 h-4 animate-spin" />
                                    ) : (
                                        <Check className="w-4 h-4" />
                                    )}
                                    تطبيق القص
                                </Button>
                            </>
                        ) : (
                            <>
                                <Button
                                    variant="outline"
                                    size="sm"
                                    onClick={handleDownload}
                                    className="gap-2"
                                >
                                    <Download className="w-4 h-4" />
                                    تحميل
                                </Button>
                                <Button
                                    size="sm"
                                    onClick={handleSave}
                                    disabled={isProcessing}
                                    className="gap-2"
                                >
                                    {isProcessing ? (
                                        <Loader2 className="w-4 h-4 animate-spin" />
                                    ) : (
                                        <Save className="w-4 h-4" />
                                    )}
                                    حفظ كنسخة جديدة
                                </Button>
                            </>
                        )}
                    </div>
                </div>
            </header>

            <div className="flex-1 flex overflow-hidden">
                <div className="flex-1 overflow-auto bg-muted/20 flex items-center justify-center p-4">
                    {isCropMode ? (
                        <div className="w-full h-full max-w-5xl">
                            <CornerEditor
                                imageUrl={imageBlobUrl || imageUrl || ""}
                                rotation={settings.rotation}
                                corners={manualCorners ?? undefined}
                                onCornersChange={setManualCorners}
                            />
                        </div>
                    ) : (
                        <div
                            className="relative bg-white rounded-lg overflow-hidden"
                            style={{ transform: `scale(${zoom})`, transformOrigin: "center" }}
                        >
                            <canvas
                                ref={canvasRef}
                                className="max-w-full max-h-[70vh]"
                            />
                            {isProcessing && (
                                <div className="absolute inset-0 bg-background/50 flex items-center justify-center">
                                    <Loader2 className="w-8 h-8 animate-spin text-primary" />
                                </div>
                            )}
                        </div>
                    )}
                </div>

                <aside className="hidden md:block md:w-80 border-r bg-card overflow-y-auto flex-shrink-0">
                    <div className="p-4 space-y-6">
                        <Card className="p-4">
                            <Heading level="h3" className="font-bold text-sm mb-3 flex items-center gap-2">
                                <ZoomIn className="w-4 h-4" />
                                التكبير والتصغير
                            </Heading>
                            <div className="flex items-center gap-2">
                                <Button
                                    variant="outline"
                                    size="icon"
                                    onClick={() => setZoom(Math.max(0.25, zoom - 0.25))}
                                    disabled={zoom <= 0.25 || isCropMode}
                                >
                                    <ZoomOut className="w-4 h-4" />
                                </Button>
                                <span className="flex-1 text-center text-sm font-mono">
                                    {Math.round(zoom * 100)}%
                                </span>
                                <Button
                                    variant="outline"
                                    size="icon"
                                    onClick={() => setZoom(Math.min(3, zoom + 0.25))}
                                    disabled={zoom >= 3 || isCropMode}
                                >
                                    <ZoomIn className="w-4 h-4" />
                                </Button>
                            </div>
                        </Card>

                        <Card className="p-4">
                            <Heading level="h3" className="font-bold text-sm mb-3 flex items-center gap-2">
                                <RotateCw className="w-4 h-4" />
                                التدوير
                            </Heading>
                            <div className="flex items-center gap-2">
                                <Button
                                    variant="outline"
                                    className="flex-1 gap-2"
                                    onClick={() => rotate(-90)}
                                    disabled={isCropMode}
                                >
                                    <RotateCcw className="w-4 h-4" />
                                    يسار 90°
                                </Button>
                                <Button
                                    variant="outline"
                                    className="flex-1 gap-2"
                                    onClick={() => rotate(90)}
                                    disabled={isCropMode}
                                >
                                    <RotateCw className="w-4 h-4" />
                                    يمين 90°
                                </Button>
                            </div>
                            {settings.rotation !== 0 && (
                                <Text variant="caption" className="text-center mt-2">
                                    الزاوية الحالية: {settings.rotation}°
                                </Text>
                            )}
                        </Card>

                        <Card className={`p-4 ${isCropMode ? "border-primary" : ""}`}>
                            <Heading level="h3" className="font-bold text-sm mb-3 flex items-center gap-2">
                                <Crop className="w-4 h-4" />
                                القص المتقدم
                            </Heading>
                            {isCropMode ? (
                                <div className="space-y-2">
                                    <Text variant="caption">
                                        اسحب النقاط الملونة لتعديل حواف المستند
                                    </Text>
                                    <Text variant="caption">
                                        يمكنك تحديد أي شكل رباعي غير منتظم
                                    </Text>
                                </div>
                            ) : (
                                <>
                                    <Text variant="caption" className="mb-3">
                                        قص متقدم مع تعديل الحواف والمنظور
                                    </Text>
                                    <Button
                                        variant="outline"
                                        className="w-full gap-2"
                                        onClick={enableCropMode}
                                    >
                                        <Crop className="w-4 h-4" />
                                        بدء القص
                                    </Button>
                                </>
                            )}
                        </Card>

                        <Card className="p-4">
                            <Heading level="h3" className="font-bold text-sm mb-3 flex items-center gap-2">
                                <Sun className="w-4 h-4" />
                                تحسين الصورة
                            </Heading>
                            <div className="space-y-4">
                                <div>
                                    <div className="flex items-center justify-between mb-2">
                                        <Text variant="caption" className="flex items-center gap-1">
                                            <Sun className="w-3 h-3" />
                                            السطوع
                                        </Text>
                                        <span className="text-xs font-mono text-muted-foreground">
                                            {settings.brightness}%
                                        </span>
                                    </div>
                                    <Slider
                                        value={[settings.brightness]}
                                        onValueChange={([v]) => updateSetting("brightness", v)}
                                        min={50}
                                        max={150}
                                        step={1}
                                        disabled={isCropMode}
                                    />
                                </div>

                                <div>
                                    <div className="flex items-center justify-between mb-2">
                                        <Text variant="caption" className="flex items-center gap-1">
                                            <Contrast className="w-3 h-3" />
                                            التباين
                                        </Text>
                                        <span className="text-xs font-mono text-muted-foreground">
                                            {settings.contrast}%
                                        </span>
                                    </div>
                                    <Slider
                                        value={[settings.contrast]}
                                        onValueChange={([v]) => updateSetting("contrast", v)}
                                        min={50}
                                        max={150}
                                        step={1}
                                        disabled={isCropMode}
                                    />
                                </div>

                                <div>
                                    <div className="flex items-center justify-between mb-2">
                                        <Text variant="caption">الحدة</Text>
                                        <span className="text-xs font-mono text-muted-foreground">
                                            {settings.sharpness}%
                                        </span>
                                    </div>
                                    <Slider
                                        value={[settings.sharpness]}
                                        onValueChange={([v]) => updateSetting("sharpness", v)}
                                        min={0}
                                        max={100}
                                        step={1}
                                        disabled={isCropMode}
                                    />
                                </div>
                            </div>
                        </Card>

                        <Card className="p-4">
                            <Heading level="h3" className="font-bold text-sm mb-3">سجل التعديلات</Heading>
                            <div className="flex items-center gap-2">
                                <Button
                                    variant="outline"
                                    size="sm"
                                    onClick={undo}
                                    disabled={historyIndex === 0 || isCropMode}
                                    className="flex-1 gap-1"
                                >
                                    <Undo className="w-4 h-4" />
                                    تراجع
                                </Button>
                                <Button
                                    variant="outline"
                                    size="sm"
                                    onClick={redo}
                                    disabled={historyIndex === history.length - 1 || isCropMode}
                                    className="flex-1 gap-1"
                                >
                                    <RotateCcw className="w-4 h-4" />
                                    إعادة
                                </Button>
                            </div>
                            <Button
                                variant="ghost"
                                size="sm"
                                onClick={resetSettings}
                                disabled={isCropMode}
                                className="w-full mt-2 text-destructive hover:text-destructive"
                            >
                                إعادة ضبط الكل
                            </Button>
                        </Card>
                    </div>
                </aside>
            </div>
        </div>
    );
}

import { useQuery } from "@tanstack/react-query";
import {
    BarChart3,
    ChevronDown,
    FileSpreadsheet,
    FileText,
    Users,
} from "lucide-react";
import { useCallback, useMemo, useState } from "react";

import { lookupApi } from "@/api/pension";
import {
    type NameValuePair,
    retirementApi,
    type RetirementFileReportFilter,
    type RetirementFileReportRow,
} from "@/api/retirement";
import {
    Badge,
    Button,
    Card,
    CardContent,
    CardHeader,
    CardTitle,
    type CustomColumnDef,
    DataTable,
    NativeSelect,
    PageHeader,
    PageLayout,
    Skeleton,
    StatCard,
    Text,
} from "@/components/ui";

export function RetirementFileReportsPage() {
    const initialFilter = useMemo<RetirementFileReportFilter>(
        () => ({ pageNumber: 1, pageSize: 10 }),
        []
    );

    const [filter, setFilter] = useState<RetirementFileReportFilter>(initialFilter);
    const [activeSection, setActiveSection] = useState<string | null>(null);
    const [exporting, setExporting] = useState<"excel" | "pdf" | null>(null);

    const { data: allBranches = [] } = useQuery({
        queryKey: ["lookup-branches"],
        queryFn: () => lookupApi.getBranches(),
    });

    const { data: allGovernorates = [] } = useQuery({
        queryKey: ["lookup-governorates"],
        queryFn: () => lookupApi.getGovernorates(),
    });

    const { data: summary, isLoading: summaryLoading } = useQuery({
        queryKey: ["retirement-file-report-summary", filter],
        queryFn: () => retirementApi.getReportSummary(filter),
    });

    const { data: reportData, isLoading: reportLoading } = useQuery({
        queryKey: ["retirement-file-report", filter],
        queryFn: () => retirementApi.getReport(filter),
    });

    const handleFilterChange = useCallback(
        (key: keyof RetirementFileReportFilter, value: string | number | undefined) => {
            setFilter((prev) => ({
                ...prev,
                [key]: value === "" || value === undefined || (typeof value === "number" && Number.isNaN(value)) ? undefined : value,
                pageNumber: 1,
            }));
        },
        []
    );

    const handleExport = useCallback(
        async (format: "excel" | "pdf") => {
            if (exporting) return;
            try {
                setExporting(format);
                const response = await retirementApi.exportReport(filter, format);
                const blob = new Blob([response.data], {
                    type: format === "excel" ? "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" : "application/pdf",
                });
                const url = window.URL.createObjectURL(blob);
                const link = document.createElement("a");
                link.href = url;
                link.download = `retirement_files_report_${new Date().toISOString().split("T")[0]}.${format === "excel" ? "xlsx" : "pdf"}`;
                document.body.appendChild(link);
                link.click();
                link.remove();
                window.URL.revokeObjectURL(url);
            } catch (error) {
                console.error("Export failed:", error);
            } finally {
                setExporting(null);
            }
        },
        [exporting, filter]
    );

    const formatDate = useCallback((dateString?: string) => {
        if (!dateString) return "---";
        const date = new Date(dateString);
        if (Number.isNaN(date.getTime())) return "---";
        return new Intl.DateTimeFormat("ar", { day: "2-digit", month: "2-digit", year: "numeric" }).format(date);
    }, []);

    const items = useMemo<RetirementFileReportRow[]>(() => reportData?.items ?? [], [reportData]);

    const mergedBranches = useMemo(() => {
        const countMap = new Map((summary?.byBranch ?? []).map((item) => [item.name, item.count]));
        return allBranches.map((branch) => ({ ...branch, count: countMap.get(branch.name) ?? 0 }));
    }, [allBranches, summary?.byBranch]);

    const columns = useMemo<CustomColumnDef<RetirementFileReportRow>[]>(() => [
        { key: "fileNumber", header: "رقم الملف", accessor: (row) => row.fileNumber || "---", className: "text-center font-bold text-primary whitespace-nowrap" },
        { key: "retireeName", header: "المتقاعد", accessor: (row) => row.retireeName || "---", className: "font-medium min-w-[180px]" },
        { key: "militaryNumber", header: "الرقم العسكري", accessor: (row) => row.militaryNumber || "---", className: "text-center font-mono whitespace-nowrap" },
        { key: "rankName", header: "الرتبة", accessor: (row) => row.rankName || "---", className: "text-center whitespace-nowrap" },
        { key: "branchName", header: "الفرع", accessor: (row) => row.branchName || "---", className: "whitespace-nowrap" },
        { key: "governorateName", header: "المحافظة", accessor: (row) => row.governorateName || "---", className: "whitespace-nowrap" },
        { key: "gender", header: "الجنس", accessor: (row) => row.gender === 2 ? "أنثى" : "ذكر", className: "text-center whitespace-nowrap" },
        { key: "socialStatusName", header: "الحالة الاجتماعية", accessor: (row) => row.socialStatusName || "---", className: "text-center whitespace-nowrap" },
        { key: "retirementDate", header: "تاريخ التقاعد", accessor: (row) => formatDate(row.retirementDate), className: "text-center whitespace-nowrap" },
        {
            key: "statusName", header: "حالة الملفات", className: "text-center whitespace-nowrap",
            render: (row) => {
                const status = row.statusName || "---";
                const variant = status.includes("نشط") ? "success" : status.includes("معلق") || status.includes("ناقص") ? "warning" : "secondary";
                return <Badge variant={variant}>{status}</Badge>;
            },
        },
        { key: "missingDocumentsCount", header: "مستندات ناقصة", accessor: (row) => row.missingDocumentsCount ?? 0, className: "text-center font-bold" },
    ], [formatDate]);

    if (summaryLoading) {
        return (
            <PageLayout>
                <div className="space-y-6">
                    <Skeleton className="h-20 w-full rounded-2xl" />
                    <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
                        {Array.from({ length: 4 }).map((_, i) => <Skeleton key={i} className="h-28 rounded-xl" />)}
                    </div>
                    <Skeleton className="h-48 rounded-xl" />
                    <Skeleton className="h-[420px] rounded-xl" />
                </div>
            </PageLayout>
        );
    }

    return (
        <PageLayout>
            {/* Header */}
            <PageHeader
                title="تقارير ملفات التقاعد"
                description="تحليل شامل وإحصائيات تفصيلية لملفات التقاعد"
                icon={<BarChart3 className="h-6 w-6 text-primary" />}
                actions={
                    <>
                        <Button variant="outline" size="sm" disabled={exporting !== null} onClick={() => handleExport("excel")} className="gap-2">
                            <FileSpreadsheet className="h-4 w-4 text-emerald-600" />
                            {exporting === "excel" ? "جاري التصدير..." : "تصدير Excel"}
                        </Button>
                        <Button variant="outline" size="sm" disabled={exporting !== null} onClick={() => handleExport("pdf")} className="gap-2">
                            <FileText className="h-4 w-4 text-red-600" />
                            {exporting === "pdf" ? "جاري التصدير..." : "تصدير PDF"}
                        </Button>
                    </>
                }
            />

            {/* Summary KPIs */}
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
                <StatCard title="إجمالي الملفات" value={summary?.totalCount ?? 0} icon={<Users className="h-4 w-4" />} variant="blue" />
                <StatCard title="الملفات النشطة" value={summary?.activeCount ?? 0} icon={<BarChart3 className="h-4 w-4" />} variant="emerald" />
                <StatCard title="الملفات المعلقة" value={summary?.suspendedCount ?? 0} icon={<BarChart3 className="h-4 w-4" />} variant="amber" />
                <StatCard title="بانتظار المراجعة" value={summary?.pendingReviewCount ?? 0} icon={<FileText className="h-4 w-4" />} variant="rose" />
            </div>

            {/* Filters */}
            <Card>
      
                <CardContent className="p-5">
                    <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-7">
                        <FilterField label="الفرع">
                            <NativeSelect
                                placeholder="كل الفروع"
                                options={mergedBranches.map((b) => ({ label: `${b.name} (${b.count})`, value: String(b.id) }))}
                                value={filter.branchId?.toString() ?? ""}
                                onChange={(v) => handleFilterChange("branchId", v ? Number(v) : undefined)}
                            />
                        </FilterField>
                        <FilterField label="المحافظة">
                            <NativeSelect
                                placeholder="كل المحافظات"
                                options={allGovernorates.map((g) => ({ label: g.name, value: g.name }))}
                                value={filter.governorate ?? ""}
                                onChange={(v) => handleFilterChange("governorate", v || undefined)}
                            />
                        </FilterField>
                        <FilterField label="الجنس">
                            <NativeSelect
                                placeholder="الكل"
                                options={[{ label: "ذكر", value: "1" }, { label: "أنثى", value: "2" }]}
                                value={filter.gender?.toString() ?? ""}
                                onChange={(v) => handleFilterChange("gender", v ? Number(v) : undefined)}
                            />
                        </FilterField>
                        <FilterField label="حالة المراجعة">
                            <NativeSelect
                                placeholder="الكل"
                                options={[{ label: "بانتظار المراجعة", value: "1" }, { label: "تمت المراجعة", value: "2" }, { label: "مرفوض", value: "3" }]}
                                value={filter.reviewStatus?.toString() ?? ""}
                                onChange={(v) => handleFilterChange("reviewStatus", v ? Number(v) : undefined)}
                            />
                        </FilterField>
                        <FilterField label="الرتبة">
                            <NativeSelect placeholder="كل الرتب" options={[]} value="" onChange={() => undefined} />
                        </FilterField>
                        <FilterField label="الحالة الاجتماعية">
                            <NativeSelect placeholder="كل الحالات" options={[]} value="" onChange={() => undefined} />
                        </FilterField>
                        <FilterField label="حالة الملفات">
                            <NativeSelect placeholder="كل الحالات" options={[]} value="" onChange={() => undefined} />
                        </FilterField>
                    </div>
                </CardContent>
            </Card>

            {/* Data Table */}
            <Card>
                <CardHeader className="border-b">
                    <div className="flex items-center justify-between">
                        <div>
                            <CardTitle className="text-base">بيانات ملفات التقاعد</CardTitle>
                            <p className="mt-1 text-xs text-muted-foreground">عرض الملفات المطابقة للفلاتر المحددة</p>
                        </div>
                        <Badge variant="secondary">{(reportData?.totalCount ?? 0).toLocaleString("ar")} ملف</Badge>
                    </div>
                </CardHeader>
                <CardContent className="p-0">
                    <div className="overflow-x-auto">
                        <DataTable
                            columns={columns}
                            data={items}
                            loading={reportLoading}
                            pagination={{
                                page: filter.pageNumber,
                                pageSize: filter.pageSize,
                                total: reportData?.totalCount ?? 0,
                                onPageChange: (page) => setFilter((prev) => ({ ...prev, pageNumber: page })),
                            }}
                            emptyMessage="لا توجد ملفات مطابقة للمعايير المحددة"
                        />
                    </div>
                </CardContent>
            </Card>

            {/* Report Sections */}
            <div className="space-y-4">
                <ReportSection title="حسب الرتبة" data={summary?.byRank ?? []} isActive={activeSection === "rank"} onToggle={() => setActiveSection((c) => c === "rank" ? null : "rank")} />
                <ReportSection title="حسب الفرع" data={summary?.byBranch ?? []} isActive={activeSection === "branch"} onToggle={() => setActiveSection((c) => c === "branch" ? null : "branch")} />
                <ReportSection title="حسب المحافظة" data={summary?.byGovernorate ?? []} isActive={activeSection === "governorate"} onToggle={() => setActiveSection((c) => c === "governorate" ? null : "governorate")} />
                <ReportSection title="حسب الجنس" data={summary?.byGender ?? []} isActive={activeSection === "gender"} onToggle={() => setActiveSection((c) => c === "gender" ? null : "gender")} />
                <ReportSection title="حسب حالة الملفات" data={summary?.byStatus ?? []} isActive={activeSection === "status"} onToggle={() => setActiveSection((c) => c === "status" ? null : "status")} />
                <ReportSection title="حسب الحالة الاجتماعية" data={summary?.bySocialStatus ?? []} isActive={activeSection === "socialStatus"} onToggle={() => setActiveSection((c) => c === "socialStatus" ? null : "socialStatus")} />
            </div>
        </PageLayout>
    );
}

function FilterField({ label, children }: { label: string; children: React.ReactNode }) {
    return (
        <div className="space-y-2">
            <Text variant="caption" className="font-medium">{label}</Text>
            {children}
        </div>
    );
}

function ReportSection({ title, data, isActive, onToggle }: { title: string; data: NameValuePair[]; isActive: boolean; onToggle: () => void }) {
    const total = data.reduce((sum, item) => sum + (item.count ?? 0), 0);

    return (
        <Card>
            <button type="button" onClick={onToggle} className="w-full text-right" aria-expanded={isActive}>
                <CardHeader className="transition-colors hover:bg-muted/40">
                    <div className="flex items-center justify-between gap-4">
                        <div className="flex items-center gap-3">
                            <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
                                <BarChart3 className="h-4 w-4 text-primary" />
                            </div>
                            <div>
                                <CardTitle className="text-sm font-semibold">{title}</CardTitle>
                                <p className="mt-1 text-xs text-muted-foreground">توزيع الملفات</p>
                            </div>
                        </div>
                        <div className="flex items-center gap-2">
                            <Badge variant="outline">{data.length.toLocaleString("ar")} عنصر</Badge>
                            <Badge variant="secondary">{total.toLocaleString("ar")}</Badge>
                            <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform ${isActive ? "rotate-180" : ""}`} />
                        </div>
                    </div>
                </CardHeader>
            </button>
            {isActive && (
                <CardContent className="border-t bg-muted/10 p-4">
                    {data.length === 0 ? (
                        <div className="py-8 text-center text-sm text-muted-foreground">لا توجد بيانات</div>
                    ) : (
                        <div className="space-y-1">
                            {data.map((item, index) => {
                                const count = item.count ?? 0;
                                const percentage = total > 0 ? (count / total) * 100 : 0;
                                return (
                                    <div key={`${item.name}-${index}`} className="rounded-lg p-3 transition-colors hover:bg-background">
                                        <div className="mb-2 flex items-center justify-between gap-4">
                                            <span className="text-sm font-medium">{item.name || "---"}</span>
                                            <div className="flex items-center gap-3">
                                                <span className="font-mono text-sm font-bold">{count.toLocaleString("ar")}</span>
                                                <span className="w-12 text-left text-xs text-muted-foreground">{Math.round(percentage)}%</span>
                                            </div>
                                        </div>
                                        <div className="h-2 overflow-hidden rounded-full bg-muted">
                                            <div className="h-full rounded-full bg-primary transition-all duration-500" style={{ width: `${Math.min(percentage, 100)}%` }} />
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </CardContent>
            )}
        </Card>
    );
}

import { useQuery, useQueryClient } from "@tanstack/react-query";
import { Check, Edit2, Eye, Trash2, UserCheck, X } from "lucide-react";
import { useCallback,useMemo, useState } from "react";

import { retirementApi } from "@/api/retirement";
import { AgentDialog } from "@/components/domain/retirement/AgentDialog";
import { ViewAgentDialog } from "@/components/domain/retirement/ViewAgentDialog";
import { Badge, Button, CrudPageLayout, type CustomColumnDef, EditableImage, TabHeader, useConfirm } from "@/components/ui";
import { PENDING_REVIEW_STATUS } from "@/constants";
import { useApiMutation, useCreateShortcut, useCrudState } from "@/hooks";
import { type AgencyScope,agentScopeLabel } from "@/lib/agentScope";
import { formatDate, getPhotoUrl, resolvePersonalPhotoPath } from "@/lib/utils";
import { useHasPermission } from "@/stores/authStore";
import type { AgentDto } from "@/types/retirement";

// ─── Types ─────────────────────────────────────────────

export interface Agent {
    agencyScope?: AgencyScope | null;
    entitledID?: number | null;
    entitledPersonName?: string | null;
    agentID: number;
    fileID: number;
    fileNumber: string;
    fullName: string;
    nationalID: string;
    personalPhotoPath?: string;
    phone?: string;
    agencyNumber: string;
    agencyDate: string;
    agencyEndDate?: string;
    notes?: string;
    isActive: boolean;
    createdAt: string;
    updatedAt?: string;
    pendingReviewStatus?: number;
}

interface AgentsTabProps { fileId: number; fileNumber?: string; }

/**
 * تبويب إدارة الوكلاء لملف التقاعد
 */
export function AgentsTab({ fileId, fileNumber }: AgentsTabProps) {
    const queryClient = useQueryClient();
    const { confirm, ConfirmDialogElement } = useConfirm();
    const crud = useCrudState<Agent>();

    // الصلاحيات
    const canView = useHasPermission("Agent.View", "File.View.Sensitive");
    const canCreate = useHasPermission("Agent.Add");
    const canEdit = useHasPermission("Agent.Edit", "Agent.Manage");
    const canDelete = useHasPermission("Agent.Delete", "Agent.Manage");

    const [modalMode, setModalMode] = useState<"create" | "edit">("create");

    // جلب البيانات
    const { data: agents = [], isLoading } = useQuery({
        queryKey: ["agents", fileId],
        queryFn: () => retirementApi.getAgents(fileId).then(data => data as unknown as Agent[])
    });

    const acknowledgeMutation = useApiMutation(
        (params: { entityType: string; entityId: number }) =>
            retirementApi.acknowledgeEntityRejection(params.entityType, params.entityId),
        {
            successMessage: "تم قبول الرفض وإعادة الكيان لحالته الطبيعية",
            invalidateKeys: [["agents", fileId], ["retirement-file"]]
        }
    );

    const getAgentPhotoUrl = (agent: Agent) => getPhotoUrl(resolvePersonalPhotoPath(agent));

    const handleOpenCreate = useCallback(() => {
        setModalMode("create");
        crud.openCreate();
    }, [crud]);

    const handleOpenEdit = useCallback((agent: Agent) => {
        setModalMode("edit");
        crud.openEdit(agent);
    }, [crud]);

    const deactivateMutation = useApiMutation(
        (id: number) => retirementApi.deactivateAgent(id),
        {
            successMessage: "تم إلغاء تفعيل الوكيل بنجاح",
            invalidateKeys: [["agents", fileId], ["retirement-file"]],
            onSuccess: () => crud.closeDelete()
        }
    );

    const deleteMutation = useApiMutation(
        (id: number) => retirementApi.deleteAgent(id),
        {
            successMessage: "تم حذف الوكيل بنجاح",
            invalidateKeys: [["agents", fileId], ["retirement-file"]]
        }
    );

    const updatePhotoMutation = useApiMutation(
        ({ id, data }: { id: number; data: FormData }) => {
            const photo = data.get("PersonalPhoto");
            if (!(photo instanceof File)) throw new Error("الصورة مطلوبة");
            return retirementApi.uploadAgentPhoto(id, photo);
        },
        {
            successMessage: "تم تحديث الصورة الشخصية للوكيل بنجاح",
            invalidateKeys: [["agents", fileId], ["retirement-file"]],
        }
    );

    const handleDeactivate = useCallback(async (agent: Agent) => {
        const ok = await confirm({
            title: "تأكيد إلغاء التفعيل",
            description: `هل أنت متأكد من إلغاء تفعيل الوكيل "${agent.fullName}"؟`,
            variant: "danger"
        });
        if (ok) deactivateMutation.mutate(agent.agentID);
    }, [confirm, deactivateMutation]);

    const handleDelete = useCallback(async (agent: Agent) => {
        const ok = await confirm({
            title: "تأكيد الحذف",
            description: `هل أنت متأكد من حذف الوكيل "${agent.fullName}"؟ لا يمكن التراجع عن هذا الإجراء.`,
            variant: "danger"
        });
        if (ok) deleteMutation.mutate(agent.agentID);
    }, [confirm, deleteMutation]);

    const columns = useMemo<CustomColumnDef<Agent>[]>(() => [
        {
            key: "photo",
            header: "الصورة",
            render: (row) => (
                <EditableImage
                    src={getAgentPhotoUrl(row)}
                    alt={row.fullName}
                    fallbackIcon={<UserCheck className="w-5 h-5 text-muted-foreground" />}
                    className="w-10 h-10 rounded-full object-cover border bg-muted/30"
                    canEdit={canEdit}
                    size="sm"
                    onUpload={async (file) => {
                        const formData = new FormData();
                        formData.append("FullName", row.fullName);
                        formData.append("NationalID", row.nationalID);
                        formData.append("Phone", row.phone || "");
                        formData.append("AgencyNumber", row.agencyNumber || "");
                        
                        const agencyDate = row.agencyDate ? row.agencyDate.split('T')[0] : "";
                        formData.append("AgencyDate", agencyDate);
                        
                        if (row.agencyEndDate && row.agencyEndDate !== "0001-01-01T00:00:00") {
                             formData.append("AgencyEndDate", row.agencyEndDate.split('T')[0]);
                        }
                        
                        formData.append("Notes", row.notes || "");
                        formData.append("PersonalPhoto", file);

                        await updatePhotoMutation.mutateAsync({ id: row.agentID, data: formData });
                    }}
                />
            )
        },
        {
            key: "fullName",
            header: "اسم الوكيل",
            render: (row) => (
                <div className="flex items-center gap-2">
                    <span className="font-bold">{row.fullName}</span>
                    {row.pendingReviewStatus === PENDING_REVIEW_STATUS.PENDING_REVIEW && (
                        <Badge variant="warning" className="text-[10px] sm:text-xs h-5">قيد المراجعة</Badge>
                    )}
                    {row.pendingReviewStatus === PENDING_REVIEW_STATUS.REJECTED && (
                        <Badge variant="destructive" className="text-[10px] sm:text-xs h-5">مرفوض</Badge>
                    )}
                </div>
            )
        },
        {
            key: "nationalID",
            header: "الرقم الوطني",
            render: (row) => <span className="font-mono text-xs text-muted-foreground">{row.nationalID}</span>
        },
        { key: "agencyNumber", header: "رقم الوكالة", accessor: (row) => row.agencyNumber },
        { key: "entitledPersonName", header: "الوكالة عن", render: (row) => agentScopeLabel(row) },
        {
            key: "agencyDate",
            header: "تاريخ الوكالة",
            render: (row) => <span className="text-xs font-mono">{formatDate(row.agencyDate)}</span>
        },
        {
            key: "agencyEndDate",
            header: "تاريخ الانتهاء",
            render: (row) => row.agencyEndDate ? <span className="text-xs font-mono text-amber-600">{formatDate(row.agencyEndDate)}</span> : "—"
        },
        {
            key: "status",
            header: "الحالة",
            render: (row) => (
                <Badge variant={row.isActive ? "success" : "ghost"}>
                    {row.isActive ? "نشط" : "معطل"}
                </Badge>
            )
        },
        {
            key: "actions",
            header: "الإجراءات",
            render: (row) => (
                <div className="flex gap-1 justify-center">
                    {canView && (
                        <Button size="icon" variant="ghost" className="min-h-[44px] min-w-[44px] text-blue-600" onClick={() => crud.openViewer(row)} title="عرض التفاصيل">
                            <Eye className="w-4 h-4" />
                        </Button>
                    )}
                    {row.isActive && canEdit && (
                        <Button size="icon" variant="ghost" className="min-h-[44px] min-w-[44px] text-muted-foreground" onClick={() => handleOpenEdit(row)} title="تعديل">
                            <Edit2 className="w-4 h-4" />
                        </Button>
                    )}
                    {row.isActive && canDelete && (
                        <Button size="icon" variant="ghost" className="min-h-[44px] min-w-[44px] text-destructive" onClick={() => handleDeactivate(row)} title="إلغاء تفعيل">
                            <X className="w-4 h-4" />
                        </Button>
                    )}
                    {canDelete && (
                        <Button size="icon" variant="ghost" className="min-h-[44px] min-w-[44px] text-red-600" onClick={() => handleDelete(row)} title="حذف">
                            <Trash2 className="w-4 h-4" />
                        </Button>
                    )}
                    {row.pendingReviewStatus === PENDING_REVIEW_STATUS.REJECTED && (
                        <Button size="icon" variant="ghost" className="min-h-[44px] min-w-[44px] text-amber-600" onClick={() => acknowledgeMutation.mutate({ entityType: "Agent", entityId: row.agentID })} title="قبول الرفض">
                            <Check className="w-4 h-4" />
                        </Button>
                    )}
                </div>
            )
        }
    ], [canView, canEdit, canDelete, crud, handleOpenEdit, handleDeactivate, handleDelete, deleteMutation, updatePhotoMutation, acknowledgeMutation]);

    useCreateShortcut(handleOpenCreate, canCreate);

    return (
        <div className="space-y-2 md:space-y-4 animate-in fade-in duration-500 text-start">
            <TabHeader
                title="الوكلاء المعتمدون"
                description="إدارة الوكلاء المخولين بالاستلام أو المراجعة للملف التقاعدي"
                icon={UserCheck}
                action={{
                    label: "إضافة وكيل",
                    icon: UserCheck,
                    onClick: handleOpenCreate,
                    show: canCreate,
                    title: "إضافة وكيل (Alt+A)"
                }}
            />

            <CrudPageLayout
                title="الوكلاء المعتمدون"
                hideHeader={true}
                columns={columns}
                data={agents}
                loading={isLoading}
                emptyMessage="لا يوجد وكلاء مسجلون لهذا الملف."
                renderMobileCard={(row) => (
                    <div className="p-3 space-y-2">
                        <div className="flex items-center gap-2.5">
                            <EditableImage
                                src={getAgentPhotoUrl(row)}
                                alt={row.fullName}
                                fallbackIcon={<UserCheck className="w-7 h-7 text-muted-foreground" />}
                                className="w-10 h-10 rounded-full object-cover border bg-muted/30 shrink-0"
                                canEdit={canEdit}
                                size="sm"
                                onUpload={async (file) => {
                                    const formData = new FormData();
                                    formData.append("FullName", row.fullName);
                                    formData.append("NationalID", row.nationalID);
                                    formData.append("Phone", row.phone || "");
                                    formData.append("AgencyNumber", row.agencyNumber || "");

                                    const agencyDate = row.agencyDate ? row.agencyDate.split('T')[0] : "";
                                    formData.append("AgencyDate", agencyDate);

                                    if (row.agencyEndDate && row.agencyEndDate !== "0001-01-01T00:00:00") {
                                        formData.append("AgencyEndDate", row.agencyEndDate.split('T')[0]);
                                    }

                                    formData.append("Notes", row.notes || "");
                                    formData.append("PersonalPhoto", file);

                                    await updatePhotoMutation.mutateAsync({ id: row.agentID, data: formData });
                                } } />
                            <div className="flex-1 min-w-0">
                                <div className="flex items-center gap-1 flex-wrap">
                                    <span className="font-bold text-xs break-words">{row.fullName}</span>
                                    {row.pendingReviewStatus === PENDING_REVIEW_STATUS.PENDING_REVIEW && (
                                        <Badge variant="warning" className="text-[8px] h-3.5 shrink-0">قيد المراجعة</Badge>
                                    )}
                                    {row.pendingReviewStatus === PENDING_REVIEW_STATUS.REJECTED && (
                                        <Badge variant="destructive" className="text-[8px] h-3.5 shrink-0">مرفوض</Badge>
                                    )}
                                </div>
                                <p className="text-[10px] text-muted-foreground font-mono">{row.agencyNumber}</p>
                                <p className="text-xs text-muted-foreground break-words">{agentScopeLabel(row)}</p>
                            </div>
                        </div>
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-1.5 text-xs border-b border-border pb-2">
                            <div>
                                <span className="text-muted-foreground">تاريخ الوكالة:</span>
                                <span className="font-bold me-1">{formatDate(row.agencyDate)}</span>
                            </div>
                            <div>
                                <span className="text-muted-foreground">الحالة:</span>
                                <Badge variant={row.isActive ? "success" : "ghost"} className="text-[9px] h-3.5 me-1">
                                    {row.isActive ? "نشط" : "معطل"}
                                </Badge>
                            </div>
                        </div>
                        <div className="flex justify-end items-center gap-0.5">
                            {canView && (
                                <Button size="icon" variant="ghost" className="min-h-[36px] min-w-[36px] text-blue-600" onClick={() => crud.openViewer(row)}>
                                    <Eye className="w-3.5 h-3.5" />
                                </Button>
                            )}
                            {row.isActive && canEdit && (
                                <Button size="icon" variant="ghost" className="min-h-[36px] min-w-[36px] text-muted-foreground" onClick={() => handleOpenEdit(row)}>
                                    <Edit2 className="w-3.5 h-3.5" />
                                </Button>
                            )}
                            {row.isActive && canDelete && (
                                <Button size="icon" variant="ghost" className="min-h-[36px] min-w-[36px] text-destructive" onClick={() => handleDeactivate(row)}>
                                    <X className="w-3.5 h-3.5" />
                                </Button>
                            )}
                            {canDelete && (
                                <Button size="icon" variant="ghost" className="min-h-[36px] min-w-[36px] text-red-600" onClick={() => handleDelete(row)}>
                                    <Trash2 className="w-3.5 h-3.5" />
                                </Button>
                            )}
                            {row.pendingReviewStatus === PENDING_REVIEW_STATUS.REJECTED && (
                                <Button size="icon" variant="ghost" className="min-h-[36px] min-w-[36px] text-amber-600" onClick={() => acknowledgeMutation.mutate({ entityType: "Agent", entityId: row.agentID })}>
                                    <Check className="w-3.5 h-3.5" />
                                </Button>
                            )}
                        </div>
                    </div>
                )}
            >
            <AgentDialog
                open={crud.isFormOpen}
                onClose={crud.closeForm}
                onSaved={() => {
                    queryClient.invalidateQueries({ queryKey: ["agents", fileId] });
                    queryClient.invalidateQueries({ queryKey: ["retirement-file", fileId] });
                }}
                fileId={fileId}
                fileNumber={fileNumber}
                mode={modalMode}
                initialData={(crud.selectedItem as unknown as AgentDto) || undefined}
            />

            <ViewAgentDialog
                open={crud.isViewerOpen}
                onClose={crud.closeViewer}
                agent={crud.viewerTarget}
                fileId={fileId}
            />

            {ConfirmDialogElement}
        </CrudPageLayout>
    </div>
    );
}

export interface BookFormValues {
  bookNumber?: string;
  bookType?: string;
  issueDate?: string;
  expiryDate?: string;
  status?: string;
  legacyColor?: string;
  changeReason?: string;
  recipientName?: string;
  recipientType?: string;
  notes?: string;
  issuingBranchID?: number | null;
  bookImage?: File | null;
  autoCreateSalaryRecipient?: boolean;
  salaryRecipientType?: string;
  salaryRecipientName?: string;
  salaryRecipientID?: number | null;
  [key: string]: any;
}

