import { useQuery, useQueryClient } from "@tanstack/react-query";
import {
    AlertTriangle,
    CheckCircle,
    Eye,
    FileText,
    FileWarning,
    Info,
    ListChecks,
    Pencil,
    Plus,
    Printer,
    StickyNote,
    Trash2,
    Upload,
    User,
} from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";
import { toast } from "sonner";

import api from "@/api/axios";
import { retirementApi } from "@/api/retirement";
import { AddMissingDocumentDialog } from "@/components/domain/retirement/AddMissingDocumentDialog";
import { BulkUploadDialog } from "@/components/domain/retirement/BulkUploadDialog";
import { DocumentViewerDialog } from "@/components/domain/retirement/DocumentViewerDialog";
import { EditDocumentDialog } from "@/components/domain/retirement/EditDocumentDialog";
import { MissingDocActionDialog } from "@/components/domain/retirement/MissingDocActionDialog";
import { UploadDocumentDialog } from "@/components/domain/retirement/UploadDocumentDialog";
import {
    Badge,
    Button,
    type CustomColumnDef,
    DataTable,
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    LoadingIndicator,
    Text,
    TabHeader,
    useConfirm,
} from "@/components/ui";
import { PENDING_REVIEW_STATUS } from "@/constants";
import { useApiMutation, useCreateShortcut } from "@/hooks";
import { getDocumentUrl } from "@/lib/utils";
import { formatDate } from "@/lib/utils";
import { useHasPermission } from "@/stores/authStore";
import type {
    DocumentItem,
    MissingDocumentInfo as MissingDocumentItem,
} from "@/types/retirement";

interface DocumentsTabProps {
    fileId: number;
    retireeName?: string;
}

const ENTITY_LABELS: Record<string, string> = {
    Agent: "الوكيل",
    Spouse: "الشريك",
    Guardian: "الوصي",
    EntitledPerson: "المستفيد",
    Retiree: "المتقاعد",
    Pledge: "تعهد",
    Exemption: "إعفاء",
    Suspension: "إيقاف",
    SalaryBatch: "دفعة معاشات",
};

const NOTES_TRUNCATE = 30;

function isLongNote(note: string) {
    return note.length > NOTES_TRUNCATE;
}

function truncateNote(note: string) {
    if (!isLongNote(note)) return note;
    return note.slice(0, NOTES_TRUNCATE) + "…";
}

/**
 * تبويب إدارة الوثائق والمستندات للملف التقاعدي
 */
export function DocumentsTab({ fileId, retireeName }: DocumentsTabProps) {
    const queryClient = useQueryClient();
    const { confirm, ConfirmDialogElement } = useConfirm();

    // ─── الصلاحيات ───
    const canUpload = useHasPermission("File.Documents.Upload");
    const canDelete = useHasPermission("File.Delete.Soft");
    const canManageMissing = useHasPermission("MissingDocument.Manage");
    const canEdit = useHasPermission("File.Documents.Update");

    // ─── حالة الحوارات ───
    const [uploadOpen, setUploadOpen] = useState(false);
    const [uploadDefaultTypeId, setUploadDefaultTypeId] = useState<number | undefined>();
    const [uploadEntityIds, setUploadEntityIds] = useState<
        | {
              retireeID?: number;
              agentID?: number;
              guardianID?: number;
              entitledID?: number;
              pledgeID?: number;
              exemptionID?: number;
          }
        | undefined
    >();
    const [addMissingOpen, setAddMissingOpen] = useState(false);
    const [actionOpen, setActionOpen] = useState(false);
    const [activeMissing, setActiveMissing] = useState<MissingDocumentItem | null>(null);
    const [bulkUploadOpen, setBulkUploadOpen] = useState(false);
    const [viewerOpen, setViewerOpen] = useState(false);
    const [viewingDoc, setViewingDoc] = useState<DocumentItem | null>(null);
    const [editOpen, setEditOpen] = useState(false);
    const [editingDoc, setEditingDoc] = useState<DocumentItem | null>(null);
    const [notesOpen, setNotesOpen] = useState(false);
    const [notesContent, setNotesContent] = useState<{ title: string; body: string } | null>(null);

    // ─── جلب البيانات ───
    // م37: مفتاح فرعي للمستودع المركب (docs/missing/types) حتى لا يتعارض مع
    // مصفوفة الوثائق في useDocumentsByFileQuery — البادئة ["documents", fileId]
    // تُبطله مع كل التحديثات القائمة على المفتاح الأب
    const { data, isLoading, error } = useQuery({
        queryKey: ["documents", fileId, "tab"],
        queryFn: async () => {
            const [docs, missing, auto, types] = await Promise.all([
                retirementApi.getDocuments(fileId),
                retirementApi.getMissingDocuments(fileId),
                retirementApi.getAutoDetectedMissing(fileId).catch(() => []),
                retirementApi.getDocumentTypes(),
            ]);

            const manualMissing = missing.map((m: MissingDocumentItem) => {
                let entityName = m.entityName;
                let entityType = m.entityType;
                if (!entityName) {
                    if (m.agentName) {
                        entityName = m.agentName;
                        entityType = "Agent";
                    } else if (m.guardianName) {
                        entityName = m.guardianName;
                        entityType = "Guardian";
                    } else if (m.entitledName) {
                        entityName = m.entitledName;
                        entityType = "EntitledPerson";
                    }
                }
                return { ...m, entityName, entityType };
            });

            const autoMissing: MissingDocumentItem[] = auto.map((ad: MissingDocumentItem) => ({
                missingDocumentID: 0,
                documentTypeID: ad.documentTypeID,
                documentTypeName: ad.documentTypeName,
                status: "Pending",
                createdAt: new Date().toISOString(),
                isAutoDetected: true,
                entityName: ad.entityName,
                entityType: ad.entityType,
                retireeID: ad.retireeID || undefined,
                agentID: ad.agentID || undefined,
                agentName: ad.entityType === "Agent" ? ad.entityName : undefined,
                guardianID: ad.guardianID || undefined,
                guardianName: ad.entityType === "Guardian" ? ad.entityName : undefined,
                entitledID: ad.entitledID || undefined,
                entitledName: ad.entityType === "EntitledPerson" ? ad.entityName : undefined,
                pledgeID: ad.pledgeID || undefined,
                exemptionID: ad.exemptionID || undefined,
                notes: undefined,
            }));

            return {
                documents: docs,
                missingDocs: [...manualMissing, ...autoMissing],
                docTypes: types,
            };
        },
    });

    const documents = data?.documents ?? [];
    const missingDocs = data?.missingDocs ?? [];
    const docTypes = data?.docTypes ?? [];

    // ─── إعادة تحميل البيانات ───
    const refreshData = useCallback(() => {
        queryClient.invalidateQueries({ queryKey: ["documents", fileId] });
        queryClient.invalidateQueries({ queryKey: ["retirement-file", fileId] });
    }, [queryClient, fileId]);

    // ─── اختصارات لوحة المفاتيح ───
    const handleOpenUpload = useCallback(() => {
        if (canUpload) setUploadOpen(true);
    }, [canUpload]);
    useCreateShortcut(handleOpenUpload, canUpload);

    // ─── معالجة الأخطاء ───
    useEffect(() => {
        if (error) toast.error("حدث خطأ أثناء تحميل بيانات الوثائق");
    }, [error]);

    // ─── حذف وثيقة ───
    const deleteMutation = useApiMutation(
        (id: number) => retirementApi.deleteDocument(id),
        {
            successMessage: "تم حذف الوثيقة بنجاح",
            invalidateKeys: [["documents", fileId], ["retirement-file"]],
        }
    );

    const handleDelete = useCallback(
        async (doc: DocumentItem) => {
            const ok = await confirm({
                title: "حذف الوثيقة",
                description: `هل أنت متأكد من حذف الوثيقة "${doc.documentTypeName}" نهائياً؟`,
                variant: "danger",
            });
            if (ok) deleteMutation.mutate(doc.documentID);
        },
        [confirm, deleteMutation]
    );

    // ─── طباعة جميع الوثائق ───
    const handlePrintAll = useCallback(() => {
        if (!documents.length) return;

        const printWindow = window.open("", "_blank", "width=900,height=700");
        if (!printWindow) {
            toast.error("يرجى السماح لنافذة منبثقة بالظهور للطباعة");
            return;
        }

        const docsHtml = documents
            .filter((doc: DocumentItem) => doc.filePath)
            .map((doc: DocumentItem) => {
                const filePath = doc.filePath!;
                const cleanPath = filePath.startsWith("/") ? filePath.slice(1) : filePath;
                const url = getDocumentUrl(cleanPath) ?? `/${cleanPath}`;
                const isImage = /\.(jpg|jpeg|png|gif|webp|bmp|svg)$/i.test(filePath);
                const isPdf = /\.pdf$/i.test(filePath);

                if (isImage) {
                    return `<div class="doc-page"><img src="${url}" /><p class="doc-title">${doc.documentTypeName}</p></div>`;
                }
                if (isPdf) {
                    return `<div class="doc-page"><iframe src="${url}"></iframe><p class="doc-title">${doc.documentTypeName}</p></div>`;
                }
                return `<div class="doc-page"><a href="${url}" target="_blank">${doc.documentTypeName} — افتح الملف</a></div>`;
            })
            .join("\n");

        printWindow.document.write(`<!DOCTYPE html>
<html lang="ar" dir="rtl">
<head>
    <meta charset="UTF-8" />
    <title>طباعة وثائق الملف</title>
    <link href="https://fonts.googleapis.com/css2?family=Noto+Kufi+Arabic:wght@400;600;700&display=swap" rel="stylesheet">
    <style>
        * { box-sizing: border-box; margin: 0; padding: 0; }
        body { font-family: 'Noto Kufi Arabic', sans-serif; direction: rtl; padding: 24px; background: var(--bg-card); }
        .doc-page { page-break-after: always; text-align: center; margin-bottom: 24px; }
        .doc-page:last-child { page-break-after: auto; }
        .doc-page img, .doc-page iframe { max-width: 100%; max-height: 88vh; object-fit: contain; border: 1px solid #e5e7eb; border-radius: 8px; }
        .doc-page iframe { width: 100%; height: 88vh; border: none; }
        .doc-page a { display: inline-block; margin-top: 20px; padding: 10px 24px; background: #0066cc; color: white; text-decoration: none; border-radius: 6px; font-weight: 600; }
        .doc-title { margin-top: 12px; font-size: 13px; color: #6b7280; font-weight: 600; }
        h2 { font-size: 18px; font-weight: 700; margin-bottom: 24px; color: #111827; }
    </style>
</head>
<body>
    <h2>وثائق الملف التقاعدي</h2>
    ${docsHtml}
    <script>
        let loaded = 0;
        const els = document.querySelectorAll('img, iframe');
        const total = els.length;
        function checkReady() {
            loaded++;
            if (loaded >= total) setTimeout(() => window.print(), 600);
        }
        els.forEach(el => {
            if (el.tagName === 'IMG' && el.complete) checkReady();
            else el.onload = checkReady;
        });
        if (total === 0) window.print();
    </script>
</body>
</html>`);
        printWindow.document.close();
    }, [documents]);

    // ─── تأشير وثيقة كمسلّمة ───
    const fulfillMutation = useApiMutation(
        async (doc: MissingDocumentItem) => {
            let missingId = doc.missingDocumentID;
            if (doc.isAutoDetected || !missingId) {
                const res = await api.post<{ data: { missingDocumentID: number } }>(
                    "/missing-documents",
                    {
                        fileID: fileId,
                        documentTypeID: doc.documentTypeID,
                        agentID: doc.agentID,
                        guardianID: doc.guardianID,
                        entitledID: doc.entitledID,
                    }
                );
                missingId = res.data.data.missingDocumentID;
            }
            return retirementApi.fulfillMissingDocument(missingId);
        },
        {
            successMessage: "تم تأشير الوثيقة كمسلّمة بنجاح",
            invalidateKeys: [["documents", fileId], ["retirement-file"]],
        }
    );

    const handleFulfill = useCallback(
        async (doc: MissingDocumentItem) => {
            const ok = await confirm({
                title: "تأشير كمسلّمة",
                description: `هل أنت متأكد من استلام وتأشير وثيقة "${doc.documentTypeName}" كمسلّمة ورقيًا دون رفعها على النظام؟`,
                variant: "default",
            });
            if (ok) fulfillMutation.mutate(doc);
        },
        [confirm, fulfillMutation]
    );

    // ─── تسمية الكيان ───
    const getEntityLabel = useCallback(
        (type?: string | null, name?: string | null) => {
            const label = ENTITY_LABELS[type || ""] || type;
            const finalName = name || retireeName;
            if (label && finalName) return `${label}: ${finalName}`;
            return finalName || label || "—";
        },
        [retireeName]
    );

    // ─── عرض الملاحظات الكاملة ───
    const openNotes = useCallback((title: string, body: string) => {
        setNotesContent({ title, body });
        setNotesOpen(true);
    }, []);

    // ─── أعمدة الجدول ───
    const columns = useMemo<CustomColumnDef<DocumentItem>[]>(
        () => [
            {
                key: "documentTypeName",
                header: "نوع الوثيقة",
                className: "sm:w-[220px] w-auto",
                render: (row) => (
                    <div className="flex items-center gap-3 min-w-0">
                        <div className="w-9 h-9 rounded-lg bg-primary/10 flex items-center justify-center text-primary shrink-0">
                            <FileText className="w-4 h-4" />
                        </div>
                        <div className="min-w-0">
                            <span className="font-semibold text-sm block truncate">
                                {row.documentTypeName}
                            </span>
                            <div className="flex items-center gap-1.5 mt-0.5">
                                {row.pendingReviewStatus === PENDING_REVIEW_STATUS.PENDING_REVIEW && (
                                    <Badge variant="warning" className="text-[10px] h-5 px-1.5">
                                        قيد المراجعة
                                    </Badge>
                                )}
                                {row.pendingReviewStatus === PENDING_REVIEW_STATUS.REJECTED && (
                                    <Badge variant="destructive" className="text-[10px] h-5 px-1.5">
                                        مرفوض
                                    </Badge>
                                )}
                            </div>
                        </div>
                    </div>
                ),
            },
            {
                key: "entityName",
                header: "صاحب الوثيقة",
                className: "sm:w-[140px] w-auto",
                render: (row) => (
                    <div className="flex items-center gap-1.5 text-xs text-muted-foreground min-w-0">
                        <User className="w-3.5 h-3.5 shrink-0" />
                        <span className="truncate block">
                            {getEntityLabel(row.entityType, row.entityName)}
                        </span>
                    </div>
                ),
            },
            {
                key: "uploadedByUser",
                header: "بواسطة",
                className: "sm:w-[100px] w-auto",
                render: (row) => (
                    <span className="text-xs text-muted-foreground font-medium truncate block">
                        {row.uploadedByUser || "النظام"}
                    </span>
                ),
            },
            {
                key: "createdAt",
                header: "تاريخ الرفع",
                className: "sm:w-[110px] w-auto",
                render: (row) => (
                    <Badge variant="outline" className="text-[11px] font-mono truncate max-w-full">
                        {formatDate(row.createdAt)}
                    </Badge>
                ),
            },
            {
                key: "notes",
                header: "ملاحظات",
                className: "max-w-[100px]",
                render: (row) => {
                    if (!row.notes) {
                        return <span className="text-xs text-muted-foreground">—</span>;
                    }
                    const long = isLongNote(row.notes);
                    return (
                        <div className="flex items-start gap-1.5 text-xs text-muted-foreground min-w-0">
                            <StickyNote className="w-3.5 h-3.5 text-yellow-500 shrink-0 mt-0.5" />
                            <div className="min-w-0 overflow-hidden">
                                <span className="block truncate">
                                    {truncateNote(row.notes)}
                                </span>
                                {long && (
                                    <Button
                                        variant="link"
                                        size="sm"
                                        className="h-auto p-0 text-[11px] text-primary font-semibold underline-offset-2 mr-1"
                                        onClick={() => openNotes(row.documentTypeName, row.notes!)}
                                    >
                                        عرض التفاصيل
                                    </Button>
                                )}
                            </div>
                        </div>
                    );
                },
            },
            {
                key: "actions",
                header: "إجراءات",
                className: "sm:w-[90px] w-auto",
                render: (row) => (
                    <div className="flex items-center justify-center gap-0.5">
                        <Button
                            size="icon"
                            variant="ghost"
                            className="h-8 w-8 text-blue-600 hover:text-blue-700 hover:bg-blue-50"
                            onClick={() => {
                                setViewingDoc(row);
                                setViewerOpen(true);
                            }}
                            title="عرض"
                        >
                            <Eye className="w-4 h-4" />
                        </Button>
                        {canEdit && (
                            <Button
                                size="icon"
                                variant="ghost"
                                className="h-8 w-8 text-amber-600 hover:text-amber-700 hover:bg-amber-50"
                                onClick={() => {
                                    setEditingDoc(row);
                                    setEditOpen(true);
                                }}
                                title="تعديل"
                            >
                                <Pencil className="w-4 h-4" />
                            </Button>
                        )}
                        {canDelete && (
                            <Button
                                size="icon"
                                variant="ghost"
                                className="h-8 w-8 text-destructive hover:text-destructive hover:bg-destructive/10"
                                onClick={() => handleDelete(row)}
                                title="حذف"
                            >
                                <Trash2 className="w-4 h-4" />
                            </Button>
                        )}
                    </div>
                ),
            },
        ],
        [canDelete, canEdit, getEntityLabel, handleDelete, openNotes]
    );

    // ─── حالات التحميل والخطأ ───
    if (error) {
        return (
            <div className="py-16 text-center flex flex-col items-center gap-3 text-destructive">
                <AlertTriangle className="w-10 h-10" />
                <Text variant="body" className="font-bold">حدث خطأ أثناء تحميل بيانات الوثائق</Text>
                <Button
                    variant="outline"
                    size="sm"
                    onClick={() =>
                        queryClient.invalidateQueries({ queryKey: ["documents", fileId] })
                    }
                >
                    إعادة المحاولة
                </Button>
            </div>
        );
    }

    if (isLoading) {
        return <LoadingIndicator message="جاري تحميل المستندات..." />;
    }

    return (
        <div className="space-y-4 md:space-y-6 animate-in fade-in duration-500">
            {/* ═══ Header ═══ */}
            {/* ═══ Header ═══ */}
            <TabHeader
                title="وثائق الملف المرفوعة"
                description="كافة المستندات المؤرشفة والمرفقة مع هذا الملف التقاعدي"
                icon={FileText}
            >
                {canUpload && (
                    <>
                        <Button
                            size="sm"
                            variant="outline"
                            onClick={() => setBulkUploadOpen(true)}
                            className="gap-1 rounded-xl font-bold h-8 md:h-10 px-4 md:px-6 transition-all text-xs md:text-sm shrink-0"
                        >
                            <Upload className="w-3.5 h-3.5 md:w-4 md:h-4 ms-1" />
                            <span className="hidden sm:inline">رفع جماعي</span>
                            <span className="sm:hidden">جماعي</span>
                        </Button>
                        <Button
                            size="sm"
                            onClick={() => {
                                setUploadDefaultTypeId(undefined);
                                setUploadEntityIds(undefined);
                                setUploadOpen(true);
                            }}
                            className="gap-1 rounded-xl font-bold h-8 md:h-10 px-4 md:px-6 transition-all text-xs md:text-sm shrink-0"
                        >
                            <Plus className="w-3.5 h-3.5 md:w-4 md:h-4 ms-1" />
                            <span className="hidden sm:inline">رفع وثيقة</span>
                            <span className="sm:hidden">وثيقة</span>
                        </Button>
                    </>
                )}
                {canManageMissing && (
                    <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setAddMissingOpen(true)}
                        className="gap-1 rounded-xl font-bold h-8 md:h-10 px-4 md:px-6 transition-all text-xs md:text-sm shrink-0"
                    >
                        <ListChecks className="w-3.5 h-3.5 md:w-4 md:h-4 ms-1" />
                        <span className="hidden sm:inline">تسجيل نقص</span>
                        <span className="sm:hidden">نقص</span>
                    </Button>
                )}
                {documents.length > 0 && (
                    <Button
                        variant="ghost"
                        size="sm"
                        onClick={handlePrintAll}
                        className="h-8 md:h-10 px-2 md:px-3 shrink-0 rounded-xl"
                        title="طباعة الكل"
                    >
                        <Printer className="w-4 h-4" />
                    </Button>
                )}
            </TabHeader>

            {/* ═══ Missing Documents ═══ */}
            {missingDocs.length > 0 && (
                <div className="bg-destructive/[0.03] border border-destructive rounded-xl overflow-hidden">
                    {/* Header */}
                    <div className="bg-destructive/10 px-4 py-3 md:px-5 md:py-3.5 flex items-center justify-between border-b border-destructive">
                        <div className="flex items-center gap-2 text-destructive font-bold">
                            <FileWarning className="w-5 h-5" />
                            <span className="text-sm md:text-base">
                                وثائق ناقصة ({missingDocs.length})
                            </span>
                        </div>
                        <AlertTriangle className="w-5 h-5 text-destructive animate-pulse" />
                    </div>

                    {/* List */}
                    <div className="divide-y divide-destructive">
                        {missingDocs.map((md, idx) => (
                            <div
                                key={`${md.documentTypeID}-${md.entityType || idx}`}
                                className="px-4 py-3 md:px-5 md:py-4 flex flex-col md:flex-row md:items-center justify-between gap-3 hover:bg-destructive/[0.02] transition-colors"
                            >
                                <div className="flex items-start md:items-center gap-3">
                                    <div className="w-10 h-10 rounded-xl bg-destructive/10 flex items-center justify-center text-destructive shrink-0 mt-0.5 md:mt-0">
                                        <Info className="w-5 h-5" />
                                    </div>
                                    <div className="space-y-1 min-w-0">
                                        <Text variant="body" className="font-bold leading-tight">
                                            {md.documentTypeName}
                                        </Text>
                                        <div className="flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
                                            <span className="flex items-center gap-1 font-medium">
                                                <User className="w-3.5 h-3.5" />
                                                {getEntityLabel(md.entityType, md.entityName)}
                                            </span>
                                            <Badge
                                                variant="outline"
                                                className="text-[10px] h-5 px-1.5 border-destructive text-destructive bg-destructive/[0.05]"
                                            >
                                                {md.status}
                                            </Badge>
                                        </div>
                                        {md.notes && (
                                            <Text variant="caption">
                                                {md.notes}
                                            </Text>
                                        )}
                                    </div>
                                </div>

                <div className="flex flex-nowrap items-center gap-1.5 overflow-x-auto">
                                    {canUpload && (
                                        <Button
                                            size="sm"
                                            variant="outline"
                                            className="h-8 px-3 text-xs font-semibold border-primary text-primary hover:bg-primary/5 gap-1.5 rounded-lg"
                                            onClick={() => {
                                                setUploadDefaultTypeId(md.documentTypeID);
                                                setUploadEntityIds({
                                                    retireeID: md.retireeID || undefined,
                                                    agentID: md.agentID || undefined,
                                                    guardianID: md.guardianID || undefined,
                                                    entitledID: md.entitledID || undefined,
                                                    pledgeID: md.pledgeID || undefined,
                                                    exemptionID: md.exemptionID || undefined,
                                                });
                                                setUploadOpen(true);
                                            }}
                                        >
                                            <Upload className="w-3.5 h-3.5" />
                                            رفع الوثيقة
                                        </Button>
                                    )}
                                    {canManageMissing && (
                                        <Button
                                            size="sm"
                                            variant="outline"
                                            className="h-8 px-3 text-xs font-semibold border-emerald-500 text-emerald-600 hover:bg-emerald-500/10 gap-1.5 rounded-lg"
                                            onClick={() => handleFulfill(md)}
                                            disabled={fulfillMutation.isPending}
                                        >
                                            <CheckCircle className="w-3.5 h-3.5" />
                                            مسلّمة
                                        </Button>
                                    )}
                                    {canManageMissing && (
                                        <Button
                                            size="sm"
                                            variant="outline"
                                            className="h-8 px-3 text-xs font-semibold border-destructive text-destructive hover:bg-destructive/5 rounded-lg"
                                            onClick={() => {
                                                setActiveMissing(md);
                                                setActionOpen(true);
                                            }}
                                        >
                                            إجراء إداري
                                        </Button>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* ═══ Documents DataTable ═══ */}
            <DataTable
                columns={columns}
                data={documents}
                loading={isLoading}
                emptyMessage="لا توجد وثائق مؤرشفة لهذا الملف"
                renderMobileCard={(row) => (
                    <div className="px-3 py-3 space-y-3">
                        {/* Title */}
                        <div className="flex items-center gap-3">
                            <div className="w-9 h-9 rounded-lg bg-primary/10 flex items-center justify-center text-primary shrink-0">
                                <FileText className="w-4 h-4" />
                            </div>
                            <div className="min-w-0 flex-1">
                                <div className="font-semibold text-sm truncate">
                                    {row.documentTypeName}
                                </div>
                                <div className="text-xs text-muted-foreground truncate flex items-center gap-1">
                                    <User className="w-3 h-3 shrink-0" />
                                    {getEntityLabel(row.entityType, row.entityName)}
                                </div>
                            </div>
                        </div>

                        {/* Meta */}
                        <div className="flex flex-wrap items-center gap-2">
                            {row.pendingReviewStatus === PENDING_REVIEW_STATUS.PENDING_REVIEW && (
                                <Badge variant="warning" className="text-[10px] h-5">
                                    قيد المراجعة
                                </Badge>
                            )}
                            {row.pendingReviewStatus === PENDING_REVIEW_STATUS.REJECTED && (
                                <Badge variant="destructive" className="text-[10px] h-5">
                                    مرفوض
                                </Badge>
                            )}
                            <span className="text-xs text-muted-foreground">
                                بواسطة {row.uploadedByUser || "النظام"}
                            </span>
                            <Badge variant="outline" className="text-[10px] font-mono">
                                {formatDate(row.createdAt)}
                            </Badge>
                        </div>

                        {/* Notes */}
                        {row.notes && (
                            <div className="text-xs text-muted-foreground bg-muted/50 p-2.5 rounded-lg">
                                <div className="flex items-start gap-1.5">
                                    <StickyNote className="w-3.5 h-3.5 text-yellow-500 shrink-0 mt-0.5" />
                                    <div className="min-w-0">
                                        <span className="block truncate">
                                            {truncateNote(row.notes)}
                                        </span>
                                        {isLongNote(row.notes) && (
                                            <Button
                                                variant="link"
                                                size="sm"
                                                className="h-auto p-0 text-[11px] text-primary font-semibold underline-offset-2 mr-1"
                                                onClick={() => openNotes(row.documentTypeName, row.notes!)}
                                            >
                                                عرض التفاصيل
                                            </Button>
                                        )}
                                    </div>
                                </div>
                            </div>
                        )}

                        {/* Actions */}
                        <div className="flex items-center justify-end gap-1 pt-1 border-t">
                            <Button
                                size="icon"
                                variant="ghost"
                                className="h-8 w-8 text-blue-600"
                                onClick={() => {
                                    setViewingDoc(row);
                                    setViewerOpen(true);
                                }}
                                title="عرض"
                            >
                                <Eye className="w-4 h-4" />
                            </Button>
                            {canEdit && (
                                <Button
                                    size="icon"
                                    variant="ghost"
                                    className="h-8 w-8 text-amber-600"
                                    onClick={() => {
                                        setEditingDoc(row);
                                        setEditOpen(true);
                                    }}
                                    title="تعديل"
                                >
                                    <Pencil className="w-4 h-4" />
                                </Button>
                            )}
                            {canDelete && (
                                <Button
                                    size="icon"
                                    variant="ghost"
                                    className="h-8 w-8 text-destructive"
                                    onClick={() => handleDelete(row)}
                                    title="حذف"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </Button>
                            )}
                        </div>
                    </div>
                )}
            />

            {/* ═══ Notes Detail Dialog ═══ */}
            <Dialog open={notesOpen} onOpenChange={setNotesOpen}>
                <DialogContent className="sm:max-w-lg max-w-[92vw] rounded-xl">
                    <DialogHeader className="pb-2 border-b">
                        <DialogTitle className="text-base font-bold flex items-center gap-2">
                            <StickyNote className="w-5 h-5 text-yellow-500" />
                            {notesContent?.title || "ملاحظات"}
                        </DialogTitle>
                    </DialogHeader>
                    <div className="py-4">
                        <Text variant="body" className="leading-relaxed text-foreground whitespace-pre-wrap break-words">
                            {notesContent?.body}
                        </Text>
                    </div>
                </DialogContent>
            </Dialog>

            {/* ═══ Modals ═══ */}
            <UploadDocumentDialog
                open={uploadOpen}
                onOpenChange={(open) => {
                    setUploadOpen(open);
                    if (!open) {
                        setUploadDefaultTypeId(undefined);
                        setUploadEntityIds(undefined);
                    }
                }}
                onSaved={refreshData}
                fileId={fileId}
                docTypes={docTypes}
                defaultTypeId={uploadDefaultTypeId}
                missingEntityIds={uploadEntityIds}
            />

            <AddMissingDocumentDialog
                open={addMissingOpen}
                onOpenChange={setAddMissingOpen}
                onSaved={refreshData}
                fileId={fileId}
                docTypes={docTypes}
                existingMissingTypeIds={missingDocs.map((md) => md.documentTypeID)}
            />

            <MissingDocActionDialog
                open={actionOpen}
                onOpenChange={setActionOpen}
                onSaved={refreshData}
                fileId={fileId}
                activeMissing={activeMissing}
            />

            <BulkUploadDialog
                open={bulkUploadOpen}
                onOpenChange={setBulkUploadOpen}
                onSaved={refreshData}
                fileId={fileId}
                docTypes={docTypes}
            />

            <DocumentViewerDialog
                open={viewerOpen}
                onOpenChange={setViewerOpen}
                document={viewingDoc}
                fileId={fileId}
                onUploaded={() => {
                    refreshData();
                    setViewerOpen(false);
                }}
                onRefresh={refreshData}
            />

            <EditDocumentDialog
                open={editOpen}
                onOpenChange={setEditOpen}
                document={editingDoc}
                fileId={fileId}
                onSaved={() => {
                    refreshData();
                    setEditOpen(false);
                }}
            />

            {ConfirmDialogElement}
        </div>
    );
}

import { useQuery } from "@tanstack/react-query";
import { AlertTriangle, Check, Edit2,Eye, Trash2, UserCircle2, UserMinus, UserPlus, Users } from "lucide-react";
import { useEffect, useMemo,useState } from "react";
import { toast } from "sonner";

import { retirementApi } from "@/api/retirement";
// ─── Standalone Dialogs ───────────────────────────────
import { EntitledPersonFormDialog } from "@/components/domain/retirement/EntitledPersonFormDialog";
import { ReactivateEntitledPersonDialog } from "@/components/domain/retirement/ReactivateEntitledPersonDialog";
import { StopEntitledPersonDialog } from "@/components/domain/retirement/StopEntitledPersonDialog";
import { ViewEntitledPersonDialog } from "@/components/domain/retirement/ViewEntitledPersonDialog";
import { Badge, Button, type CustomColumnDef, DataTable, EditableImage, TabHeader, useConfirm } from "@/components/ui";
import { PENDING_REVIEW_STATUS } from "@/constants";
import { useApiMutation, useCreateShortcut } from "@/hooks";
import { normalizeDateInputValue } from "@/lib/date";
import { cn, getPhotoUrl, resolvePersonalPhotoPath } from "@/lib/utils";
import { useHasPermission } from "@/stores/authStore";

// ─── Types ─────────────────────────────────────────────

export interface EntitledPerson {
    entitledID: number;
    fileID: number;
    fullName: string;
    nationalID: string;
    relationshipName?: string;
    dateOfBirth?: string;
    ageYears?: number;
    phone?: string;
    socialStatusID?: number;
    socialStatusName?: string;
    healthStatusID?: number;
    healthStatusName?: string;
    hasDisabilityException: boolean;
    isEligible: boolean;
    isDeceased: boolean;
    stopReason?: string;
    createdAt: string;
    updatedAt?: string;
    pendingReviewStatus?: number;
    relationshipID?: number;
    personalPhotoPath?: string | null;
    sharePercent?: number | null;
}

interface EntitledPersonsTabProps {
    fileId: number;
}

/**
 * تبويب الورثة والمستحقين لملف التقاعد
 */
export function EntitledPersonsTab({ fileId }: EntitledPersonsTabProps) {
    const { confirm, ConfirmDialogElement } = useConfirm();
    const canView = useHasPermission("EntitledPerson.View");
    const canCreate = useHasPermission("EntitledPerson.Create");
    const canEdit = useHasPermission("EntitledPerson.Edit");
    const canDelete = useHasPermission("EntitledPerson.Delete");
    const canManageLifecycle = useHasPermission("EntitledPerson.Lifecycle");

    // ─── Dialog State ──────────────────────────────────
    const [formOpen, setFormOpen] = useState(false);
    const [formMode, setFormMode] = useState<"create" | "edit">("create");
    const [selectedPerson, setSelectedPerson] = useState<EntitledPerson | null>(null);

    const [stopOpen, setStopOpen] = useState(false);
    const [reactivateOpen, setReactivateOpen] = useState(false);
    const [viewOpen, setViewOpen] = useState(false);

    // ─── Data Query ─────────────────────────────────────
    const { data: persons = [], isLoading, error } = useQuery({
        queryKey: ["entitled-persons", fileId],
        queryFn: () => retirementApi.getEntitledPersons(fileId).then(data => data as unknown as EntitledPerson[])
    });

    const acknowledgeMutation = useApiMutation(
        (params: { entityType: string; entityId: number }) =>
            retirementApi.acknowledgeEntityRejection(params.entityType, params.entityId),
        {
            successMessage: "تم قبول الرفض وإعادة الكيان لحالته الطبيعية",
            invalidateKeys: [["entitled-persons", fileId], ["retirement-file"]]
        }
    );

    const getPersonPhotoUrl = (person: EntitledPerson) => getPhotoUrl(resolvePersonalPhotoPath(person));

    const updatePhotoMutation = useApiMutation(
        ({ id, data }: { id: number; data: FormData }) => retirementApi.updateEntitledPerson(id, data),
        {
            successMessage: "تم تحديث الصورة الشخصية للمستحق بنجاح",
            invalidateKeys: [["entitled-persons", fileId], ["retirement-file"]],
        }
    );

    const deleteMutation = useApiMutation(
        (id: number) => retirementApi.deleteEntitledPerson(id),
        {
            successMessage: "تم حذف المستحق بنجاح",
            invalidateKeys: [["entitled-persons", fileId], ["retirement-file"]]
        }
    );

    const handleDelete = async (person: EntitledPerson) => {
        const ok = await confirm({
            title: "تأكيد الحذف",
            description: `هل أنت متأكد من حذف "${person.fullName}"؟ لا يمكن التراجع عن هذا الإجراء.`,
            variant: "danger"
        });
        if (ok) deleteMutation.mutate(person.entitledID);
    };

    // ─── Handlers ────────────────────────────────────────

    const handleOpenCreate = () => {
        setFormMode("create");
        setSelectedPerson(null);
        setFormOpen(true);
    };

    const handleOpenEdit = (p: EntitledPerson) => {
        setFormMode("edit");
        setSelectedPerson(p);
        setFormOpen(true);
    };

    const handleOpenStop = (p: EntitledPerson) => {
        setSelectedPerson(p);
        setStopOpen(true);
    };

    const handleOpenReactivate = (p: EntitledPerson) => {
        setSelectedPerson(p);
        setReactivateOpen(true);
    };

    const handleOpenView = (p: EntitledPerson) => {
        setSelectedPerson(p);
        setViewOpen(true);
    };

    const columns = useMemo<CustomColumnDef<EntitledPerson>[]>(() => [
        {
            key: "photo",
            header: "الصورة",
            render: (row) => (
                <EditableImage
                    src={getPersonPhotoUrl(row)}
                    alt={row.fullName}
                    fallbackIcon={<UserCircle2 className="w-5 h-5 text-muted-foreground" />}
                    className="w-10 h-10 rounded-full object-cover border bg-muted/30"
                    canEdit={canEdit}
                    size="sm"
                    onUpload={async (file) => {
                        const formData = new FormData();
                        formData.append("fullName", row.fullName);
                        formData.append("nationalID", row.nationalID || "");
                        formData.append("relationshipID", (row.relationshipID || 0).toString());
                        if (row.dateOfBirth) {
                            // DateOnly في الـAPI: "YYYY-MM-DD" فقط، بلا طابع زمني.
                            const dateOfBirth = normalizeDateInputValue(row.dateOfBirth);
                            if (dateOfBirth) formData.append("dateOfBirth", dateOfBirth);
                        }
                        formData.append("phone", row.phone || "");
                        formData.append("socialStatusID", (row.socialStatusID || 0).toString());
                        formData.append("healthStatusID", (row.healthStatusID || 0).toString());
                        formData.append("hasDisabilityException", (row.hasDisabilityException ?? false).toString());
                        formData.append("PersonalPhoto", file);

                        await updatePhotoMutation.mutateAsync({ id: row.entitledID, data: formData });
                    }}
                />
            )
        },
        {
            key: "fullName",
            header: "الاسم الكامل",
            render: (row) => (
                <div className="flex items-center gap-2">
                    <span className="font-bold">{row.fullName}</span>
                    {row.pendingReviewStatus === PENDING_REVIEW_STATUS.PENDING_REVIEW && (
                        <Badge variant="warning" className="text-[10px] sm:text-xs h-5">قيد المراجعة</Badge>
                    )}
                    {row.pendingReviewStatus === PENDING_REVIEW_STATUS.REJECTED && (
                        <Badge variant="destructive" className="text-[10px] sm:text-xs h-5">مرفوض</Badge>
                    )}
                </div>
            )
        },
        {
            key: "relationshipName",
            header: "القرابة",
            accessor: (row) => row.relationshipName || "—"
        },
        {
            key: "sharePercent",
            header: "حصة المعاش",
            render: (row) => row.sharePercent == null ? "—" : `${row.sharePercent}%`
        },
        {
            key: "nationalID",
            header: "الرقم الوطني",
            render: (row) => <span className="font-mono text-xs text-muted-foreground">{row.nationalID || "—"}</span>
        },
        {
            key: "ageYears",
            header: "العمر",
            render: (row) => (
                <div className="text-center font-mono">
                    {row.ageYears} <span className="text-[10px] sm:text-xs text-muted-foreground">سنة</span>
                </div>
            )
        },
        {
            key: "socialStatusName",
            header: "الحالة الاجتماعية",
            accessor: (row) => row.socialStatusName || "—"
        },
        {
            key: "isEligible",
            header: "حالة الاستحقاق",
            render: (row) => (
                <div className="text-center">
                    <Badge variant={row.isEligible ? "success" : "ghost"}>
                        {row.isEligible ? "مستحق" : "موقوف"}
                    </Badge>
                </div>
            )
        },
        {
            key: "actions",
            header: "إجراءات",
            render: (row) => (
                <div className="flex justify-center gap-1">
                    {canView && (
                        <Button 
                            size="icon" 
                            variant="ghost-action" 
                            className="min-h-[44px] min-w-[44px] rounded-xl text-blue-600 hover:bg-blue-50" 
                            onClick={() => handleOpenView(row)} 
                            title="عرض"
                        >
                            <Eye className="w-4 h-4" />
                        </Button>
                    )}
                    {canEdit && (
                        <Button 
                            size="icon" 
                            variant="ghost-action" 
                            className="min-h-[44px] min-w-[44px] rounded-xl text-muted-foreground hover:bg-muted" 
                            onClick={() => handleOpenEdit(row)} 
                            title="تعديل"
                        >
                            <Edit2 className="w-4 h-4" />
                        </Button>
                    )}
                    {canManageLifecycle && (
                        row.isEligible ? (
                            <Button 
                                size="icon" 
                                variant="ghost-action" 
                                className="min-h-[44px] min-w-[44px] rounded-xl text-destructive hover:bg-destructive/10" 
                                onClick={() => handleOpenStop(row)} 
                                title="إيقاف"
                            >
                                <UserMinus className="w-4 h-4" />
                            </Button>
                        ) : !row.isDeceased && (
                            <Button 
                                size="icon" 
                                variant="ghost-action" 
                                className="min-h-[44px] min-w-[44px] rounded-xl text-emerald-600 hover:bg-emerald-50" 
                                onClick={() => handleOpenReactivate(row)} 
                                title="تفعيل"
                            >
                                <UserPlus className="w-4 h-4" />
                            </Button>
                        )
                    )}
                    {canDelete && (
                        <Button 
                            size="icon" 
                            variant="ghost-action" 
                            className="min-h-[44px] min-w-[44px] rounded-xl text-red-600 hover:bg-red-50" 
                            onClick={() => handleDelete(row)} 
                            title="حذف"
                        >
                            <Trash2 className="w-4 h-4" />
                        </Button>
                    )}
                    {row.pendingReviewStatus === PENDING_REVIEW_STATUS.REJECTED && (
                        <Button
                            size="icon"
                            variant="ghost-action"
                            className="min-h-[44px] min-w-[44px] rounded-xl text-amber-600 hover:bg-amber-50"
                            onClick={() => acknowledgeMutation.mutate({ entityType: "EntitledPerson", entityId: row.entitledID })}
                            title="قبول الرفض"
                        >
                            <Check className="w-4 h-4" />
                        </Button>
                    )}
                </div>
            )
        }
    ], [canView, canEdit, canManageLifecycle, canDelete, getPersonPhotoUrl, updatePhotoMutation]);

    useEffect(() => {
        if (error) toast.error("حدث خطأ أثناء تحميل بيانات الورثة والمستحقين");
    }, [error]);

    useCreateShortcut(handleOpenCreate, canCreate && !formOpen);

    if (error) return (
        <div className="py-12 text-center text-destructive flex flex-col items-center gap-2">
            <AlertTriangle className="w-8 h-8" />
            <p className="font-bold">حدث خطأ أثناء تحميل بيانات الورثة والمستحقين</p>
        </div>
    );

    return (
        <div className="space-y-2 md:space-y-4 animate-in fade-in duration-500">
            <TabHeader
                title="قائمة الورثة والمستحقين"
                description="إدارة بيانات أفراد عائلة المتقاعد المستحقين للمعاش"
                icon={Users}
                action={{
                    label: "إضافة مستحق",
                    icon: UserPlus,
                    onClick: handleOpenCreate,
                    show: canCreate,
                    title: "إضافة مستحق (Alt+A)"
                }}
            />

            <DataTable
                columns={columns}
                data={persons}
                loading={isLoading}
                emptyMessage="لا يوجد ورثة مسجلين لهذا الملف التقاعدي"
                renderMobileCard={(row) => (
                    <div className="p-3 space-y-2">
                        <div className="flex items-start gap-2.5">
                            <EditableImage
                                src={getPersonPhotoUrl(row)}
                                alt={row.fullName}
                                fallbackIcon={<UserCircle2 className="w-7 h-7 text-muted-foreground" />}
                                className="w-11 h-11 rounded-full object-cover border bg-muted/30 shrink-0"
                                canEdit={canEdit}
                                size="sm"
                                onUpload={async (file) => {
                                    const formData = new FormData();
                                    formData.append("fullName", row.fullName);
                                    formData.append("nationalID", row.nationalID || "");
                                    formData.append("relationshipID", (row.relationshipID || 0).toString());
                                    if (row.dateOfBirth) {
                                        // DateOnly في الـAPI: "YYYY-MM-DD" فقط، بلا طابع زمني.
                                        const dateOfBirth = normalizeDateInputValue(row.dateOfBirth);
                                        if (dateOfBirth) formData.append("dateOfBirth", dateOfBirth);
                                    }
                                    formData.append("phone", row.phone || "");
                                    formData.append("socialStatusID", (row.socialStatusID || 0).toString());
                                    formData.append("healthStatusID", (row.healthStatusID || 0).toString());
                                    formData.append("hasDisabilityException", (row.hasDisabilityException ?? false).toString());
                                    formData.append("PersonalPhoto", file);

                                    await updatePhotoMutation.mutateAsync({ id: row.entitledID, data: formData });
                                }}
                            />
                            <div className="flex-1 min-w-0">
                                <p className="font-bold text-xs truncate">{row.fullName}</p>
                                <div className="flex items-center gap-1.5 mt-0.5 flex-wrap">
                                    {row.pendingReviewStatus === PENDING_REVIEW_STATUS.PENDING_REVIEW && (
                                        <Badge variant="warning" className="text-[8px] h-3.5 shrink-0">قيد المراجعة</Badge>
                                    )}
                                    {row.pendingReviewStatus === PENDING_REVIEW_STATUS.REJECTED && (
                                        <Badge variant="destructive" className="text-[8px] h-3.5 shrink-0">مرفوض</Badge>
                                    )}
                                    <span className="text-[10px] text-muted-foreground">{row.relationshipName || "—"}</span>
                                    <span className={cn("w-2 h-2 rounded-full shrink-0", row.isEligible ? "bg-emerald-500" : "bg-muted-foreground")} title={row.isEligible ? "مستحق" : "موقوف"} />
                                </div>
                            </div>
                        </div>
                        <div className="flex items-center gap-1 text-xs">
                            <span className="text-muted-foreground">العمر:</span>
                            <span className="font-bold">{row.ageYears || "—"}</span>
                        </div>
                        <div className="flex justify-end items-center gap-0">
                            {canView && (
                                <Button size="icon" variant="ghost" className="min-h-[32px] min-w-[32px] h-8 w-8 text-blue-600" onClick={() => handleOpenView(row)}>
                                    <Eye className="w-3.5 h-3.5" />
                                </Button>
                            )}
                            {canEdit && (
                                <Button size="icon" variant="ghost" className="min-h-[32px] min-w-[32px] h-8 w-8 text-muted-foreground" onClick={() => handleOpenEdit(row)}>
                                    <Edit2 className="w-3.5 h-3.5" />
                                </Button>
                            )}
                            {canDelete && (
                                <Button size="icon" variant="ghost" className="min-h-[32px] min-w-[32px] h-8 w-8 text-destructive" onClick={() => handleDelete(row)}>
                                    <Trash2 className="w-3.5 h-3.5" />
                                </Button>
                            )}
                            {row.pendingReviewStatus === PENDING_REVIEW_STATUS.REJECTED && (
                                <Button size="icon" variant="ghost" className="min-h-[32px] min-w-[32px] h-8 w-8 text-amber-600" onClick={() => acknowledgeMutation.mutate({ entityType: "EntitledPerson", entityId: row.entitledID })}>
                                    <Check className="w-3.5 h-3.5" />
                                </Button>
                            )}
                        </div>
                    </div>
                )}
            />

            {/* ─── Dialogs ──────────────── */}

            <EntitledPersonFormDialog
                open={formOpen}
                onOpenChange={setFormOpen}
                mode={formMode}
                initialData={selectedPerson || undefined}
                fileId={fileId}
            />

            <StopEntitledPersonDialog
                open={stopOpen}
                onOpenChange={setStopOpen}
                personId={selectedPerson?.entitledID || 0}
                targetName={selectedPerson?.fullName || ""}
                fileId={fileId}
            />

            <ReactivateEntitledPersonDialog
                open={reactivateOpen}
                onOpenChange={setReactivateOpen}
                personId={selectedPerson?.entitledID || 0}
                targetName={selectedPerson?.fullName || ""}
                fileId={fileId}
            />

            <ViewEntitledPersonDialog
                open={viewOpen}
                onOpenChange={setViewOpen}
                person={selectedPerson}
            />

            {ConfirmDialogElement}
        </div>
    );
}

import { useQuery, useQueryClient } from "@tanstack/react-query";
import { AlertTriangle, Check, FileText, Hash, Inbox, ShieldCheck, UserPlus, X } from "lucide-react";
import { useEffect, useMemo,useState } from "react";
import { toast } from "sonner";

import { retirementApi } from "@/api/retirement";
import { AddGuardianMinorDialog } from "@/components/domain/retirement/AddGuardianMinorDialog";
import { GuardianDialog } from "@/components/domain/retirement/GuardianDialog";
import { Badge, Button, EditableImage, EmptyState, LoadingIndicator, TabHeader, useConfirm } from "@/components/ui";
import { PENDING_REVIEW_STATUS } from "@/constants";
import { useApiMutation, useCreateShortcut } from "@/hooks";
import { useEntitledPersonsQuery } from "@/hooks/queries";
import { cn,formatDate, getPhotoUrl, resolvePersonalPhotoPath } from "@/lib/utils";
import { useHasPermission } from "@/stores/authStore";
import type { EntitledPersonSummary } from "@/types/retirement";

// ─── Types ─────────────────────────────────────────────

export interface GuardianMinor {
    entitledID: number;
    entitledPersonName: string;
    isActive: boolean;
    startDate: string;
    endDate?: string;
}

export interface Guardian {
    guardianID: number;
    minors: GuardianMinor[];
    fullName: string;
    nationalID: string;
    personalPhotoPath?: string;
    phone?: string;
    guardianshipDocNumber: string;
    startDate: string;
    endDate?: string;
    isActive: boolean;
    createdAt: string;
    pendingReviewStatus?: number;
}

interface GuardiansTabProps { fileId: number; }

/**
 * تبويب إدارة الأوصياء والمستحقين القاصرين لملف التقاعد
 */
export function GuardiansTab({ fileId }: GuardiansTabProps) {
    const queryClient = useQueryClient();
    const { confirm, ConfirmDialogElement } = useConfirm();

    // الصلاحيات
    const canCreate = useHasPermission("Guardian.Add");
    const canEnd = useHasPermission("Guardian.Delete", "Guardian.Manage");

    // حالة الحوارات
    const [addOpen, setAddOpen] = useState(false);
    const [addMinorOpen, setAddMinorOpen] = useState(false);
    const [selectedGuardianId, setSelectedGuardianId] = useState<number | null>(null);

    const { data: entitledsData = [], isLoading: isLoadingEntitleds } = useEntitledPersonsQuery(fileId);

    const { data: guardiansData = [], isLoading: isLoadingGuardians, error: guardiansError } = useQuery({
        queryKey: ["guardians-tab", fileId],
        queryFn: () => retirementApi.getGuardians(fileId).then(data =>
            (data as Guardian[]).map(g => ({ ...g, minors: g.minors || [] }))
        )
    });

    const acknowledgeMutation = useApiMutation(
        (params: { entityType: string; entityId: number }) =>
            retirementApi.acknowledgeEntityRejection(params.entityType, params.entityId),
        {
            successMessage: "تم قبول الرفض وإعادة الكيان لحالته الطبيعية",
            invalidateKeys: [["guardians-tab", fileId], ["retirement-file"]]
        }
    );

    const isLoading = isLoadingEntitleds || isLoadingGuardians;

    const entitleds = entitledsData as EntitledPersonSummary[];
    const guardians = guardiansData || [];
    const hasActiveGuardian = guardians.some(g => g.isActive);

    const handleOpenCreate = () => setAddOpen(true);

    useCreateShortcut(handleOpenCreate, canCreate && !hasActiveGuardian);

    // تصفية المستحقين القاصرين المتاحين للوصاية
    const availableEntitleds = useMemo(() => entitleds.filter(ep => {
        if (!ep.isEligible || !ep.dateOfBirth) return false;
        // حساب العمر بشكل تقريبي
        const age = (new Date().getTime() - new Date(ep.dateOfBirth).getTime()) / (1000 * 60 * 60 * 24 * 365.25);
        if (age >= 18) return false;

        const hasActiveG = guardians.some(g =>
            g.isActive && g.minors && g.minors.some(m => m.entitledID === ep.entitledID && m.isActive)
        );
        return !hasActiveG;
    }), [entitleds, guardians]);

    // طفرات البيانات
    const endMutation = useApiMutation(
        (id: number) => retirementApi.endGuardianship(id, { reason: "تم إنهاء الوصاية من قبل المستخدم" }),
        {
            successMessage: "تم إنهاء الوصاية بنجاح",
            invalidateKeys: [["guardians-tab", fileId], ["retirement-file"]]
        }
    );

    const updatePhotoMutation = useApiMutation(
        ({ id, file }: { id: number, file: File }) => {
            const formData = new FormData();
            formData.append("personalPhoto", file);
            return retirementApi.updateGuardian(id, formData);
        },
        {
            successMessage: "تم تحديث الصورة الشخصية للوصي بنجاح",
            invalidateKeys: [["guardians-tab", fileId]]
        }
    );

    // المعالجات
    const handleEndGuardianship = async (id: number) => {
        const ok = await confirm({
            title: "هل تريد إنهاء هذه الوصاية؟",
            description: "سيتم إيقاف صلاحية الوصي عن كافة القاصرين التابعين له.",
            variant: "danger"
        });
        if (ok) endMutation.mutate(id);
    };

    const handleAddMinor = (id: number) => {
        setSelectedGuardianId(id);
        setAddMinorOpen(true);
    };

    useEffect(() => {
        if (guardiansError) toast.error("حدث خطأ أثناء تحميل بيانات الأوصياء");
    }, [guardiansError]);

    if (guardiansError) return (
        <div className="py-12 text-center text-destructive flex flex-col items-center gap-2">
            <AlertTriangle className="w-8 h-8" />
            <p className="font-bold">حدث خطأ أثناء تحميل بيانات الأوصياء</p>
        </div>
    );

    if (isLoading) return <LoadingIndicator message="جاري تحميل الأوصياء..." />;

    return (
        <div className="space-y-2 md:space-y-4 animate-in fade-in duration-500 text-start" dir="rtl">
            {ConfirmDialogElement}
            <TabHeader
                title="الأوصياء المعتمدون"
                description="إدارة الأوصياء القانونيين على القاصرين من الورثة"
                icon={ShieldCheck}
                action={{
                    label: "تسجيل وصي جديد",
                    icon: ShieldCheck,
                    onClick: () => setAddOpen(true),
                    show: canCreate && !hasActiveGuardian,
                }}
            />

            {guardians.length === 0 ? (
                <EmptyState icon={Inbox} title="لا يوجد أوصياء مسجلون لهذا الملف" />
            ) : (
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                    {guardians.map(g => (
                        <div key={g.guardianID} className={cn("border rounded-2xl p-5 bg-card  transition-all border-border", !g.isActive && "opacity-100 grayscale bg-muted/20")}>
                            <div className="flex gap-4 items-start mb-4">
                                <div className="flex-shrink-0">
                                    <EditableImage
                                        src={getPhotoUrl(resolvePersonalPhotoPath(g))}
                                        alt={g.fullName}
                                        fallbackIcon={<ShieldCheck className="w-8 h-8 opacity-100" />}
                                        className="w-16 h-16 rounded-xl object-cover border-2 border-background "
                                        canEdit={canEnd && g.isActive}
                                        onUpload={async (file) => {
                                            await updatePhotoMutation.mutateAsync({ id: g.guardianID, file });
                                        }}
                                    />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <div className="flex justify-between items-start gap-2">
                                        <h4 className="font-black text-lg truncate text-foreground flex items-center gap-2">
                                            {g.fullName}
                                            {g.pendingReviewStatus === PENDING_REVIEW_STATUS.PENDING_REVIEW && (
                                                <Badge variant="warning" className="text-[10px] sm:text-xs h-5">قيد المراجعة</Badge>
                                            )}
                                            {g.pendingReviewStatus === PENDING_REVIEW_STATUS.REJECTED && (
                                                <Badge variant="destructive" className="text-[10px] sm:text-xs h-5">مرفوض</Badge>
                                            )}
                                        </h4>
                                        <Badge variant={g.isActive ? "success" : "secondary"} className="font-black h-5">{g.isActive ? "نشط" : "منتهي"}</Badge>
                                    </div>
                                    <p className="text-xs text-muted-foreground flex items-center gap-1.5 mt-1 font-mono font-bold">
                                        <Hash className="w-3 h-3 text-muted-primary" /> {g.nationalID}
                                    </p>
                                    <p className="text-[10px] sm:text-xs text-muted-foreground flex items-center gap-1.5 mt-1.5 font-medium">
                                        <FileText className="w-3 h-3 text-muted-primary" /> صك وصاية رقم: <span className="font-mono font-black text-foreground">{g.guardianshipDocNumber}</span>
                                    </p>
                                </div>
                            </div>

                            <div className="bg-muted/40 rounded-xl p-4 space-y-3 mb-4 border border-border">
                                <p className="text-[10px] sm:text-xs font-black text-primary uppercase tracking-widest flex items-center gap-2">
                                    <span className="w-1.5 h-1.5 rounded-full bg-primary" />
                                    المستحقين تحت الوصاية
                                </p>
                                <div className="space-y-2">
                                    {g.minors.length === 0 ? (
                                        <p className="text-xs text-muted-foreground italic py-1">لا يوجد قاصرين مرتبطين حالياً</p>
                                    ) : g.minors.map(m => (
                                        <div key={m.entitledID} className="flex items-center justify-between text-sm py-1.5 border-b border-border last:border-0">
                                            <span className={cn("font-bold", !m.isActive && "line-through text-muted-foreground opacity-100")}>{m.entitledPersonName}</span>
                                            <span className="text-[10px] sm:text-xs font-mono text-muted-foreground bg-background px-1.5 py-0.5 rounded border border-border">منذ: {formatDate(m.startDate)}</span>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            <div className="flex justify-between items-center pt-4 border-t border-dashed border-border">
                                <span className="text-[10px] sm:text-xs text-muted-foreground flex items-center gap-1 font-medium">
                                    التسجيل: <span className="font-mono font-bold">{formatDate(g.createdAt)}</span>
                                </span>
                                <div className="flex gap-2">
                                    {g.isActive && canCreate && (
                                        <Button size="sm" variant="ghost" className="min-h-[44px] px-2.5 text-primary hover:bg-primary/5 text-xs font-black" onClick={() => handleAddMinor(g.guardianID)}>
                                            <UserPlus className="w-3.5 h-3.5 ms-1" /> إضافة قاصر
                                        </Button>
                                    )}
                                    {g.isActive && canEnd && (
                                        <Button size="sm" variant="ghost" className="min-h-[44px] px-2.5 text-destructive hover:bg-destructive/5 text-xs font-black" onClick={() => handleEndGuardianship(g.guardianID)}>
                                            <X className="w-3.5 h-3.5 ms-1" /> إنهاء الوصاية
                                        </Button>
                                    )}
                                    {g.pendingReviewStatus === PENDING_REVIEW_STATUS.REJECTED && (
                                        <Button size="sm" variant="ghost" className="min-h-[44px] px-2.5 text-amber-600 hover:bg-amber-50 text-xs font-black" onClick={() => acknowledgeMutation.mutate({ entityType: "Guardian", entityId: g.guardianID })}>
                                            <Check className="w-3.5 h-3.5 ms-1" /> قبول الرفض
                                        </Button>
                                    )}
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            <GuardianDialog
                open={addOpen}
                onClose={() => setAddOpen(false)}
                onSaved={() => {
                    queryClient.invalidateQueries({ queryKey: ["guardians-tab", fileId] });
                    queryClient.invalidateQueries({ queryKey: ["retirement-file", fileId] });
                }}
                fileId={fileId}
                availableEntitleds={availableEntitleds}
            />

            <AddGuardianMinorDialog
                open={addMinorOpen}
                onClose={() => setAddMinorOpen(false)}
                onSaved={() => {
                    queryClient.invalidateQueries({ queryKey: ["guardians-tab", fileId] });
                    queryClient.invalidateQueries({ queryKey: ["retirement-file", fileId] });
                }}
                guardianId={selectedGuardianId || 0}
                availableEntitleds={availableEntitleds}
            />
        </div>
    );
}

import { useQuery } from "@tanstack/react-query";
import { AlertTriangle, Ban, BookOpen, Check, Edit2, FileText, Plus, Printer } from "lucide-react";
import { useEffect, useMemo,useState } from "react";
import { toast } from "sonner";

import { retirementApi } from "@/api/retirement";
import { type BookFormValues,PaymentBookDialog } from "@/components/domain/retirement/PaymentBookDialog";
import { Badge, Button, type CustomColumnDef,DataTable, StatusBadge, TabHeader, useConfirm } from "@/components/ui";
import { PENDING_REVIEW_STATUS, RECIPIENT_TYPE_AR } from "@/constants";
import { PAYMENT_BOOK_STATUS } from "@/constants/statusConfigs";
import { useApiMutation, useCreateShortcut, useCrudState } from "@/hooks";
import { useAgentsQuery, useEntitledPersonsQuery, useFileDetailsQuery, useGuardiansQuery } from "@/hooks/queries";
import { cn, formatDate } from "@/lib/utils";
import { useHasPermission } from "@/stores/authStore";
import type { AgentSummary, EntitledPersonSummary,GuardianSummary } from "@/types/retirement";

// ─── Types ──────────────────────────────────────────────

export interface PaymentBook {
    paymentBookID: number;
    fileID: number;
    bookNumber: string;
    issueDate: string;
    expiryDate: string;
    status: string;
    bookType: string;
    legacyColor?: string | null;
    changeReason?: string | null;
    recipientName?: string | null;
    recipientType?: string | null;
    notes?: string | null;
    issuingBranchID?: number | null;
    issuingBranchName?: string | null;
    createdAt: string;
    updatedAt?: string | null;
    pendingReviewStatus?: number;
}

interface RecipientOption { id: string | number; name: string; }

interface PaymentBooksTabProps {
    fileId: number;
}

const CHANGE_REASONS = [
    "إصدار أول",
    "تجديد سنوي",
    "تغيير وكيل",
    "تعيين وكيل",
    "تعديل وصي",
    "تعديل مستحقين",
    "بدل فاقد",
    "بدل تالف",
];
const RECIPIENT_TYPES = [RECIPIENT_TYPE_AR.RETIREE, RECIPIENT_TYPE_AR.AGENT, RECIPIENT_TYPE_AR.GUARDIAN, RECIPIENT_TYPE_AR.ENTITLED];

/**
 * تبويب سجل دفاتر صرف المعاش لملف التقاعد
 */
export function PaymentBooksTab({ fileId }: PaymentBooksTabProps) {
    const { confirm, ConfirmDialogElement } = useConfirm();
    const crud = useCrudState<PaymentBook>();


    // الصلاحيات
    const canCreate = useHasPermission("PaymentBook.Add");
    const canEdit = useHasPermission("PaymentBook.Edit");
    const canDelete = useHasPermission("PaymentBook.Delete", "PaymentBook.Manage");

    const [modalMode, setModalMode] = useState<"create" | "edit">("create");

    const { file } = useFileDetailsQuery(fileId);
    const { data: agents = [] } = useAgentsQuery(fileId);
    const { data: guardians = [] } = useGuardiansQuery(fileId);
    const { data: entitleds = [] } = useEntitledPersonsQuery(fileId);

    // جلب البيانات
    const { data: books = [], isLoading, error } = useQuery({
        queryKey: ["payment-books", fileId],
        queryFn: () => retirementApi.getPaymentBooks(fileId).then(data => data as unknown as PaymentBook[])
    });

    const acknowledgeMutation = useApiMutation(
        (params: { entityType: string; entityId: number }) =>
            retirementApi.acknowledgeEntityRejection(params.entityType, params.entityId),
        {
            successMessage: "تم قبول الرفض وإعادة الكيان لحالته الطبيعية",
            invalidateKeys: [["payment-books", fileId], ["retirement-file"]]
        }
    );

    // طفرات البيانات
    const saveMutation = useApiMutation(
        async ({ values, paymentBookID }: { values: BookFormValues; paymentBookID?: number }) => {
            if (paymentBookID) {
                const updateDto = {
                    bookNumber: values.bookNumber,
                    issueDate: values.issueDate ? values.issueDate : undefined,
                    expiryDate: values.expiryDate ? values.expiryDate : undefined,
                    status: values.status,
                    legacyColor: values.legacyColor,
                    changeReason: values.changeReason,
                    recipientName: values.recipientName,
                    recipientType: values.recipientType,
                    notes: values.notes,
                    issuingBranchID: values.issuingBranchID || null,
                };
                return retirementApi.updatePaymentBook(paymentBookID, updateDto);
            } else {
                const formData = new FormData();
                formData.append("FileID", fileId.toString());
                formData.append("IssueDate", values.issueDate ? values.issueDate : new Date().toISOString().split('T')[0]);
                formData.append("BookType", values.bookType);
                if (values.bookType === "يدوي") {
                    if (values.bookNumber) formData.append("BookNumber", values.bookNumber);
                    if (values.legacyColor) formData.append("LegacyColor", values.legacyColor);
                } else {
                    if (values.expiryDate) formData.append("ExpiryDate", values.expiryDate);
                    if (values.changeReason) formData.append("ChangeReason", values.changeReason);
                }

                if (values.recipientName) formData.append("RecipientName", values.recipientName);
                if (values.recipientType) formData.append("RecipientType", values.recipientType);
                if (values.notes) formData.append("Notes", values.notes);
                if (values.issuingBranchID) formData.append("IssuingBranchID", values.issuingBranchID.toString());
                
                // Auto Salary Recipient fields
                if (values.autoCreateSalaryRecipient !== undefined) {
                    formData.append("AutoCreateSalaryRecipient", values.autoCreateSalaryRecipient.toString());
                }
                if (values.autoCreateSalaryRecipient && values.salaryRecipientID && values.salaryRecipientType) {
                    if (values.salaryRecipientType === RECIPIENT_TYPE_AR.RETIREE) formData.append("RetireeID", values.salaryRecipientID.toString());
                    else if (values.salaryRecipientType === RECIPIENT_TYPE_AR.AGENT) formData.append("AgentID", values.salaryRecipientID.toString());
                    else if (values.salaryRecipientType === RECIPIENT_TYPE_AR.ENTITLED) formData.append("EntitledID", values.salaryRecipientID.toString());
                    else if (values.salaryRecipientType === RECIPIENT_TYPE_AR.GUARDIAN) formData.append("GuardianID", values.salaryRecipientID.toString());
                }

                if (values.bookImage instanceof File) {
                    formData.append("BookImage", values.bookImage);
                }
                return retirementApi.createPaymentBook(formData);
            }
        },
        {
            successMessage: "تم حفظ دفتر الصرف بنجاح",
            invalidateKeys: [["payment-books", fileId], ["retirement-file"], ["salary-recipients", fileId]],
            onSuccess: () => {
                sessionStorage.removeItem("payment_book_draft");
                crud.closeForm();
            }
        }
    );

    const deleteMutation = useApiMutation(
        (id: number) => retirementApi.deletePaymentBook(id),
        {
            successMessage: "تم إلغاء تفعيل الدفتر بنجاح",
            invalidateKeys: [["payment-books", fileId], ["retirement-file"]]
        }
    );

    useEffect(() => {
        if (error) toast.error("حدث خطأ أثناء تحميل دفاتر الصرف");
    }, [error]);

    const handleDelete = async (book: PaymentBook) => {
        const ok = await confirm({
            title: "إلغاء تفعيل الدفتر",
            description: `هل أنت متأكد من رغبتك في إلغاء تفعيل الدفتر رقم "${book.bookNumber}"؟`,
            variant: "danger"
        });
        if (ok) deleteMutation.mutate(book.paymentBookID);
    };

    const getRecipientOptions = async (recipientType: string): Promise<RecipientOption[]> => {
        if (!recipientType) return [];
        if (recipientType === RECIPIENT_TYPE_AR.RETIREE) {
            const name = file?.retireeFullName;
            const id = file?.retireeID; 
            return name && id ? [{ id: id, name: name }] : [];
        } else if (recipientType === RECIPIENT_TYPE_AR.AGENT) {
            return (agents as AgentSummary[])
                .filter(a => a.isActive && !a.isDeleted)
                .map(item => ({ id: item.agentID, name: item.fullName }));
        } else if (recipientType === RECIPIENT_TYPE_AR.GUARDIAN) {
            return (guardians as GuardianSummary[])
                .filter(g => g.isActive && !g.isDeleted)
                .map(item => ({ id: item.guardianID, name: item.fullName }));
        } else if (recipientType === RECIPIENT_TYPE_AR.ENTITLED) {
            return (entitleds as EntitledPersonSummary[])
                .filter(e => e.isEligible && !e.isDeceased && !e.isDeleted)
                .map(item => ({ id: item.entitledID, name: item.fullName }));
        }
        return [];
    };



    const getBookTypeStyle = (book: PaymentBook) => {
        if (book.bookType === "إلكتروني") {
            return { bg: "bg-green-500/5 dark:bg-green-950/20", icon: BookOpen, iconBg: "bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400", label: "إلكتروني" };
        }
        switch (book.legacyColor) {
            case "أبيض": return { bg: "bg-muted dark:bg-muted/20", icon: FileText, iconBg: "bg-muted dark:bg-muted text-muted-foreground", label: "يدوي - أبيض" };
            case "أخضر": return { bg: "bg-green-500/5 dark:bg-green-950/20", icon: FileText, iconBg: "bg-green-200 dark:bg-green-900/30 text-green-700 dark:text-green-400", label: "يدوي - أخضر" };
            case "أزرق": return { bg: "bg-blue-500/5 dark:bg-blue-950/20", icon: FileText, iconBg: "bg-blue-200 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400", label: "يدوي - أزرق" };
            default: return { bg: "bg-muted dark:bg-muted/20", icon: FileText, iconBg: "bg-muted dark:bg-muted text-muted-foreground", label: "يدوي" };
        }
    };

    const columns = useMemo<CustomColumnDef<PaymentBook>[]>(() => [
        {
            key: "bookNumber",
            header: "رقم الدفتر",
            render: (row) => {
                const style = getBookTypeStyle(row);
                const Icon = style.icon;
                return (
                    <div className={`flex items-center gap-2 p-1.5 rounded-lg ${style.bg}`}>
                        <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${style.iconBg}`}>
                            <Icon className="w-4 h-4" />
                        </div>
                        <div className="flex flex-col">
                            <span className="font-mono font-bold tracking-wider flex items-center gap-1.5">
                                {row.bookNumber}
                                {row.pendingReviewStatus === PENDING_REVIEW_STATUS.PENDING_REVIEW && (
                                    <Badge variant="warning" className="text-[10px] sm:text-xs h-4 leading-none px-1">قيد المراجعة</Badge>
                                )}
                                {row.pendingReviewStatus === PENDING_REVIEW_STATUS.REJECTED && (
                                    <Badge variant="destructive" className="text-[10px] sm:text-xs h-4 leading-none px-1">مرفوض</Badge>
                                )}
                            </span>
                            <span className="text-[10px] sm:text-xs text-muted-foreground">{style.label}</span>
                        </div>
                    </div>
                );
            }
        },
        {
            key: "issueDate",
            header: "تاريخ الإصدار",
            render: (row) => <span className="font-mono text-xs">{formatDate(row.issueDate)}</span>
        },
        {
            key: "expiryDate",
            header: "تاريخ الانتهاء",
            render: (row) => row.bookType === "يدوي"
                ? <span className="text-xs text-muted-foreground">—</span>
                : <span className="font-mono text-xs">{formatDate(row.expiryDate)}</span>
        },
        {
            key: "recipient",
            header: "المستلم",
            render: (row) => (
                <div className="flex flex-col gap-0.5 text-start">
                    <span className="font-bold text-sm">{row.recipientName || "—"}</span>
                    <Badge variant="outline" className="w-fit text-[10px] sm:text-xs h-4 leading-none px-1.5">{row.recipientType || "—"}</Badge>
                </div>
            )
        },
        {
            key: "status",
            header: "الحالة",
            render: (row) => <StatusBadge status={row.status} config={PAYMENT_BOOK_STATUS} />
        },
        {
            key: "issuingBranch",
            header: "جهة الإصدار",
            render: (row) => <span className="text-xs">{row.issuingBranchName || "—"}</span>
        },
        {
            key: "actions",
            header: "إجراءات",
            render: (row) => (
                <div className="flex items-center justify-center gap-1">
                    {row.bookType !== "يدوي" && (
                        <Button variant="ghost" size="icon" className="min-h-[44px] min-w-[44px]" onClick={() => window.open(`/payment-books/${row.paymentBookID}/print`, "_blank")}>
                            <Printer className="w-4 h-4 text-primary" />
                        </Button>
                    )}
                    {canEdit && (
                        <Button variant="ghost" size="icon" className="min-h-[44px] min-w-[44px]" onClick={() => { setModalMode("edit"); crud.openEdit(row); }}>
                            <Edit2 className="w-4 h-4" />
                        </Button>
                    )}
                    {canDelete && (
                        <Button 
                            variant="ghost" 
                            size="icon" 
                            className="min-h-[44px] min-w-[44px] text-destructive" 
                            disabled={row.status === "ملغي"}
                            onClick={() => handleDelete(row)}
                        >
                            <Ban className="w-4 h-4" />
                        </Button>
                    )}
                    {row.pendingReviewStatus === PENDING_REVIEW_STATUS.REJECTED && (
                        <Button variant="ghost" size="icon" className="min-h-[44px] min-w-[44px] text-amber-600" onClick={() => acknowledgeMutation.mutate({ entityType: "PaymentBook", entityId: row.paymentBookID })} title="قبول الرفض">
                            <Check className="w-4 h-4" />
                        </Button>
                    )}
                </div>
            )
        }
    ], [crud, file, agents, guardians, entitleds, handleDelete, canEdit, canDelete, acknowledgeMutation]);

    const handleOpenCreate = () => { setModalMode("create"); crud.openCreate(); };

    useCreateShortcut(handleOpenCreate, canCreate);

    if (error) return (
        <div className="py-12 text-center text-destructive flex flex-col items-center gap-2">
            <AlertTriangle className="w-8 h-8" />
            <p className="font-bold">حدث خطأ أثناء تحميل دفاتر الصرف</p>
        </div>
    );

    return (
        <div className="space-y-2 md:space-y-4 animate-in fade-in duration-500 text-start">
            <TabHeader
                title="سجل دفاتر الصرف"
                description="قائمة بدفاتر صرف المستحقات الصادرة لهذا الملف"
                icon={BookOpen}
                action={{
                    label: "إضافة دفتر جديد",
                    icon: Plus,
                    onClick: () => { setModalMode("create"); crud.openCreate(); },
                    show: canCreate
                }}
            />

            <DataTable
                columns={columns}
                data={books}
                loading={isLoading}
                emptyMessage="لا يوجد دفاتر صرف مسجلة لهذا الملف"
                renderMobileCard={(item) => {
                    const style = getBookTypeStyle(item);
                    const Icon = style.icon;
                    return (
                        <div className="p-3 space-y-2">
                            <div className="flex items-center gap-2">
                                <div className={`w-7 h-7 rounded-lg flex items-center justify-center ${style.iconBg}`}>
                                    <Icon className="w-3.5 h-3.5" />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <div className="font-mono font-bold text-xs tracking-wider flex items-center gap-1">
                                        <span className="truncate">{item.bookNumber}</span>
                                        {item.pendingReviewStatus === PENDING_REVIEW_STATUS.PENDING_REVIEW && (
                                            <Badge variant="warning" className="text-[8px] h-3.5 shrink-0">قيد المراجعة</Badge>
                                        )}
                                        {item.pendingReviewStatus === PENDING_REVIEW_STATUS.REJECTED && (
                                            <Badge variant="destructive" className="text-[8px] h-3.5 shrink-0">مرفوض</Badge>
                                        )}
                                    </div>
                                    <span className="text-[10px] text-muted-foreground">{style.label}</span>
                                </div>
                                <span className={cn("w-2 h-2 rounded-full shrink-0", item.status === "ملغي" ? "bg-muted-foreground" : "bg-emerald-500")} title={item.status} />
                            </div>
                            <div className="text-[10px] text-muted-foreground space-y-0.5">
                                {item.recipientName && <div>المستلم: <span className="font-bold">{item.recipientName}</span></div>}
                                {item.issuingBranchName && <div>جهة الإصدار: <span className="font-bold">{item.issuingBranchName}</span></div>}
                                <div>الإصدار: <span className="font-mono">{formatDate(item.issueDate)}</span></div>
                                {item.bookType !== "يدوي" && <div>الانتهاء: <span className="font-mono">{formatDate(item.expiryDate)}</span></div>}
                            </div>
                            <div className="flex justify-end gap-0">
                                {item.bookType !== "يدوي" && (
                                    <Button variant="ghost" size="icon" className="min-h-[32px] min-w-[32px] h-8 w-8" onClick={() => window.open(`/payment-books/${item.paymentBookID}/print`, "_blank")}>
                                        <Printer className="w-3.5 h-3.5 text-primary" />
                                    </Button>
                                )}
                                {canEdit && (
                                    <Button variant="ghost" size="icon" className="min-h-[32px] min-w-[32px] h-8 w-8" onClick={() => { setModalMode("edit"); crud.openEdit(item); }}>
                                        <Edit2 className="w-3.5 h-3.5" />
                                    </Button>
                                )}
                                {canDelete && (
                                    <Button variant="ghost" size="icon" className="min-h-[32px] min-w-[32px] h-8 w-8 text-destructive" disabled={item.status === "ملغي"} onClick={() => handleDelete(item)}>
                                        <Ban className="w-3.5 h-3.5" />
                                    </Button>
                                )}
                                {item.pendingReviewStatus === PENDING_REVIEW_STATUS.REJECTED && (
                                    <Button variant="ghost" size="icon" className="min-h-[32px] min-w-[32px] h-8 w-8 text-amber-600" onClick={() => acknowledgeMutation.mutate({ entityType: "PaymentBook", entityId: item.paymentBookID })}>
                                        <Check className="w-3.5 h-3.5" />
                                    </Button>
                                )}
                            </div>
                        </div>
                    );
                }}
            />

            <PaymentBookDialog
                open={crud.isFormOpen}
                onOpenChange={crud.onOpenChange}
                fileId={fileId}
                mode={modalMode}
                editRecordId={crud.selectedItem?.paymentBookID}
                onSubmit={(v, ctx) => saveMutation.mutateAsync({ values: v, paymentBookID: ctx.paymentBookID })}
                isLoading={saveMutation.isPending}
                initialData={crud.selectedItem ? {
                    bookNumber: crud.selectedItem.bookNumber,
                    issueDate: crud.selectedItem.issueDate,
                    expiryDate: crud.selectedItem.expiryDate,
                    bookType: crud.selectedItem.bookType,
                    legacyColor: crud.selectedItem.legacyColor || undefined,
                    changeReason: crud.selectedItem.changeReason || undefined,
                    recipientType: crud.selectedItem.recipientType || undefined,
                    recipientName: crud.selectedItem.recipientName || undefined,
                    status: crud.selectedItem.status,
                    notes: crud.selectedItem.notes || undefined,
                    issuingBranchID: crud.selectedItem.issuingBranchID || undefined,
                } : undefined}
                lookups={{
                    changeReasons: CHANGE_REASONS,
                    recipientTypes: RECIPIENT_TYPES,
                    getRecipientOptions: getRecipientOptions
                }}
            />

            {ConfirmDialogElement}
        </div>
    );
}

import { useQuery } from "@tanstack/react-query";
import { CheckCircle, Edit2, FileSignature, Plus, Printer,ShieldCheck, X } from "lucide-react";
import { useCallback,useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";

import { documentsApi } from "@/api/documents";
import {
    type CreateExemptionDto,
    type CreatePledgeDto,
    retirementApi} from "@/api/retirement";
import { ExemptionDialog, type ExemptionFormValues } from "@/components/domain/retirement/ExemptionDialog";
import { FulfillPledgeDialog, type FulfillPledgeFormValues } from "@/components/domain/retirement/FulfillPledgeDialog";
import { PledgeDialog, type PledgeFormValues } from "@/components/domain/retirement/PledgeDialog";
import {
    Badge,
    Button,
    type CustomColumnDef,
    DataTable,
    LoadingIndicator,
    TabHeader,
    useConfirm} from "@/components/ui";
import { useApiMutation, useCreateShortcut } from "@/hooks";
import { useAgentsQuery, useEntitledPersonsQuery, useGuardiansQuery, useMissingDocumentsQuery } from "@/hooks/queries";
import { cn, formatDate } from "@/lib/utils";
import { useHasPermission } from "@/stores/authStore";
import type {
    AgentSummary,
    EntitledPersonSummary,
    ExemptionItem,
    GuardianSummary,
    MissingDocumentInfo,
    PledgeItem} from "@/types/retirement";
import { mapMissingDocsForDialog,resolveMissingDocumentIds } from "@/utils/missing-documents";

interface PledgesAndExemptionsTabProps {
    fileId: number;
    retireeName?: string;
}

type TabType = "pledges" | "exemptions";

/**
 * تبويب إدارة التعهدات والإعفاءات للملف التقاعدي
 */
export function PledgesAndExemptionsTab({ fileId, retireeName }: PledgesAndExemptionsTabProps) {
    const navigate = useNavigate();
    const { confirm, ConfirmDialogElement } = useConfirm();

    // الصلاحيات
    const canCreatePledge = useHasPermission("DocumentPledge.Add");
    const canEditPledge = useHasPermission("DocumentPledge.Edit");
    const canManagePledge = useHasPermission("DocumentPledge.Manage");
    const canCreateExemption = useHasPermission("DocumentExemption.Add");
    const canEditExemption = useHasPermission("DocumentExemption.Edit");
    const canManageExemption = useHasPermission("DocumentExemption.Manage");

    const [activeTab, setActiveTab] = useState<TabType>("pledges");

    const [dialogState, setDialogState] = useState({
        pledge: { open: false, mode: "create" as "create" | "edit", data: null as PledgeItem | null, shouldPrint: false },
        exemption: { open: false, mode: "create" as "create" | "edit", data: null as ExemptionItem | null },
        fulfill: { open: false, data: null as PledgeItem | null }
    });

    const handleOpenCreatePledge = useCallback(() => {
        setDialogState(s => ({ ...s, pledge: { open: true, mode: "create", data: null, shouldPrint: false } }));
    }, []);

    const handleOpenCreateExemption = useCallback(() => {
        setDialogState(s => ({ ...s, exemption: { open: true, mode: "create", data: null } }));
    }, []);

    // جلب البيانات
    const { data: peData, isLoading: isPEDataLoading, isError: peError, refetch: refetchPE } = useQuery({
        queryKey: ["pledges-exemptions", fileId],
        queryFn: async () => {
            const [pledgesRes, exemptionsRes] = await Promise.all([
                retirementApi.getPledges(fileId),
                retirementApi.getExemptions(fileId)
            ]);
            return {
                pledges: (pledgesRes as PledgeItem[]).map(p => ({ ...p, missingDocuments: p.missingDocuments || [] })),
                exemptions: (exemptionsRes as ExemptionItem[]).map(e => ({ ...e, missingDocuments: e.missingDocuments || [] }))
            };
        }
    });

    const pledges = peData?.pledges || [];
    const exemptions = peData?.exemptions || [];

    const { data: missingDocs = [], isLoading: isLoadingDocs, refetch: refetchMissing } = useMissingDocumentsQuery(fileId);
    const { data: agents = [], isLoading: isLoadingAgents } = useAgentsQuery(fileId);
    const { data: entitleds = [], isLoading: isLoadingEntitleds } = useEntitledPersonsQuery(fileId);
    const { data: guardians = [], isLoading: isLoadingGuardians } = useGuardiansQuery(fileId);

    const isLoading = isPEDataLoading || isLoadingDocs || isLoadingAgents || isLoadingEntitleds || isLoadingGuardians;

    const lookups = useMemo(() => ({
        activeAgent: agents.find((a: AgentSummary) => a.isActive) ? { id: agents.find((a: AgentSummary) => a.isActive)!.agentID, fullName: agents.find((a: AgentSummary) => a.isActive)!.fullName } : null,
        agents: agents.map((a: AgentSummary) => ({ id: a.agentID, fullName: a.fullName })),
        entitleds: entitleds.map((e: EntitledPersonSummary) => ({ id: e.entitledID, fullName: e.fullName })),
        guardians: guardians.map((g: GuardianSummary) => ({ id: g.guardianID, fullName: g.fullName })),
    }), [agents, entitleds, guardians]);

    // طفرات البيانات
    const pledgeMutation = useApiMutation(async (payload: { values: CreatePledgeDto & { pledgeFile?: File }; id?: number; shouldPrint?: boolean; keepOpen?: boolean }) => {
        if (payload.id) {
            const res = await retirementApi.updatePledge(payload.id, payload.values);
            return { ...res, keepOpen: payload.keepOpen };
        } else {
            const { pledgeFile, ...dto } = payload.values;
            const res = await retirementApi.createPledge(dto);
            if (pledgeFile && res.isSuccess) {
                const formData = new FormData();
                formData.append("File", pledgeFile);
                formData.append("DocumentTypeID", "9"); // وثيقة تعهد
                formData.append("RetirementFileID", String(fileId));
                formData.append("PledgeID", String(res.data));
                await documentsApi.upload(formData);
            }
            return { ...res, keepOpen: payload.keepOpen };
        }
    }, {
        successMessage: "تم حفظ التعهد بنجاح",
        invalidateKeys: [["pledges-exemptions", fileId], ["retirement-file"], ["documents", fileId]],
        onSuccess: (res) => {
            const result = res as { shouldPrint?: boolean; data?: { pledgeID: number }; keepOpen?: boolean };
            if (!result?.keepOpen) {
                setDialogState(s => ({ ...s, pledge: { open: false, mode: "create", data: null, shouldPrint: false } }));
            }
            if (result?.shouldPrint && result?.data?.pledgeID) {
                navigate(`/pledges/${result.data.pledgeID}/print`);
            }
        }
    });

    const exemptionMutation = useApiMutation(async (payload: { values: CreateExemptionDto & { exemptionFile?: File }; id?: number }) => {
        if (payload.id) {
            return retirementApi.updateExemption(payload.id, payload.values);
        } else {
            const { exemptionFile, ...dto } = payload.values;
            const res = await retirementApi.createExemption(dto);
            if (exemptionFile && res.isSuccess) {
                const formData = new FormData();
                formData.append("File", exemptionFile);
                formData.append("DocumentTypeID", "10"); // توجيه إعفاء
                formData.append("RetirementFileID", String(fileId));
                formData.append("ExemptionID", String(res.data));
                await documentsApi.upload(formData);
            }
            return res;
        }
    }, {
        successMessage: "تم حفظ الإعفاء بنجاح",
        invalidateKeys: [["pledges-exemptions", fileId], ["retirement-file"], ["documents", fileId]],
        onSuccess: () => setDialogState(s => ({ ...s, exemption: { open: false, mode: "create", data: null } }))
    });

    const fulfillPledgeMutation = useApiMutation(async (values: FulfillPledgeFormValues) => {
        const docsToUpload = values.documents.filter((d) => d.file);
        
        if (docsToUpload.length === 0) return { isSuccess: true };

        const results = [];
        for (const doc of docsToUpload) {
            const originalDoc = dialogState.fulfill.data?.missingDocuments?.find(m => m.missingDocumentID === doc.missingDocumentID);
            const formData = new FormData();
            if (doc.file) formData.append("File", doc.file);
            formData.append("DocumentTypeID", String(originalDoc?.documentTypeID));
            formData.append("RetirementFileID", String(fileId));
            
            if (originalDoc?.agentID) formData.append("AgentID", String(originalDoc.agentID));
            if (originalDoc?.entitledID) formData.append("EntitledPersonID", String(originalDoc.entitledID));
            if (originalDoc?.guardianID) formData.append("GuardianID", String(originalDoc.guardianID));
            
            try {
                const res = await documentsApi.upload(formData);
                results.push(res);
            } catch (err) {
                console.error(`Failed to upload document ${doc.missingDocumentID}:`, err);
                throw err; // Stop the sequence if one fails (safer for transaction integrity)
            }
        }
        
        return results;
    }, {
        successMessage: "تم رفع الوثائق وتحديث حالة التعهد بنجاح",
        invalidateKeys: [["pledges-exemptions", fileId], ["retirement-file"], ["documents", fileId], ["missing-documents", fileId]],
        onSuccess: () => {
            setDialogState(s => ({ ...s, fulfill: { open: false, data: null } }));
            // Refetch is already handled by invalidateKeys, but explicit call for immediate UI update
            void refetchPE();
            void refetchMissing();
        }
    });

    const deletePledgeMutation = useApiMutation((id: number) => retirementApi.deletePledge(id), {
        successMessage: "تم حذف التعهد بنجاح",
        invalidateKeys: [["pledges-exemptions", fileId], ["retirement-file"]]
    });

    const deleteExemptionMutation = useApiMutation((id: number) => retirementApi.deleteExemption(id), {
        successMessage: "تم حذف الإعفاء بنجاح",
        invalidateKeys: [["pledges-exemptions", fileId], ["retirement-file"]]
    });

    // المعالجات
    const handlePledgeSubmit = async (values: PledgeFormValues, options?: { keepOpen?: boolean }) => {
        let pledgedName = "";
        let pledgedType = "";
        switch (values.pledgedByType) {
            case "retiree": pledgedName = retireeName || ""; pledgedType = "متقاعد"; break;
            case "agent": pledgedName = lookups.agents.find((a: { id: number | string; }) => String(a.id) === values.selectedID)?.fullName || ""; pledgedType = "وكيل"; break;
            case "entitled": pledgedName = lookups.entitleds.find((e: { id: number; fullName: string }) => e.id === Number(values.selectedID))?.fullName || ""; pledgedType = "مستحق"; break;
            case "guardian": pledgedName = lookups.guardians.find((g: { id: number; fullName: string }) => g.id === Number(values.selectedID))?.fullName || ""; pledgedType = "وصي"; break;
        }

        const deadlineDate = new Date();
        deadlineDate.setMonth(deadlineDate.getMonth() + Number(values.deadlineMonths));

        const materializedIds = await resolveMissingDocumentIds(
            values.missingDocumentIDs, missingDocs, fileId
        );

        const payload: CreatePledgeDto & { pledgeFile?: File } = {
            fileID: fileId,
            missingDocumentIDs: materializedIds,
            deadline: deadlineDate.toISOString().split("T")[0],
            pledgedByName: pledgedName,
            pledgedByType: pledgedType,
            reason: values.reason || undefined,
            pledgeFile: values.pledgeFile as File || undefined,
        };
        
        // We use mutateAsync to allow the dialog to handle "Save & Add Another" logic
        await pledgeMutation.mutateAsync({ 
            values: payload, 
            id: dialogState.pledge.data?.pledgeID, 
            shouldPrint: values.issueOfficialPledge,
            keepOpen: options?.keepOpen,
        });
    };

    const handleExemptionSubmit = async (values: ExemptionFormValues) => {
        const materializedIds = await resolveMissingDocumentIds(
            values.missingDocumentIDs, missingDocs, fileId
        );

        const payload: CreateExemptionDto & { exemptionFile?: File } = {
            fileID: fileId,
            missingDocumentIDs: materializedIds,
            directiveSource: values.directiveSource,
            exemptionDate: values.exemptionDate,
            notes: values.notes || undefined,
            exemptionFile: values.exemptionFile as File || undefined,
        };
        exemptionMutation.mutate({ values: payload, id: dialogState.exemption.data?.exemptionID });
    };

    const handleMarkFulfilled = useCallback(async (p: PledgeItem) => {
        setDialogState(s => ({ ...s, fulfill: { open: true, data: p } }));
    }, []);

    const handleDeletePledge = useCallback(async (p: PledgeItem) => {
        if (!(await confirm({ title: "حذف التعهد", description: "هل أنت متأكد من حذف هذا التعهد نهائياً؟", variant: "danger" }))) return;
        deletePledgeMutation.mutate(p.pledgeID);
    }, [confirm, deletePledgeMutation]);


    const handleDeleteExemption = useCallback(async (e: ExemptionItem) => {
        if (!(await confirm({ title: "حذف الإعفاء", description: "هل أنت متأكد من حذف هذا الإعفاء نهائياً؟", variant: "danger" }))) return;
        deleteExemptionMutation.mutate(e.exemptionID);
    }, [confirm, deleteExemptionMutation]);

    // Shared render for missing documents column
    const renderDocsColumn = useCallback((row: { missingDocuments?: MissingDocumentInfo[] }) => (
        <div className="flex flex-wrap gap-1 text-start">
            {row.missingDocuments?.map((doc, idx) => {
                const isFulfilled = doc.status === "Fulfilled";
                return (
                    <Badge 
                        key={idx} 
                        variant={isFulfilled ? "success" : "outline"} 
                        className={`text-[10px] sm:text-xs font-bold ${isFulfilled ? "opacity-100 line-through" : ""}`}
                        title={isFulfilled ? "مستلمة" : "غير مستلمة"}
                    >
                        {doc.documentTypeName}
                    </Badge>
                );
            }) || "—"}
        </div>
    ), []);

    const pledgeColumns = useMemo<CustomColumnDef<PledgeItem>[]>(() => [
        { key: "docs", header: "الوثائق", render: renderDocsColumn },
        { key: "pledgeDate", header: "تاريخ التعهد", render: (row) => <span className="font-mono text-xs">{formatDate(row.pledgeDate)}</span> },
        { key: "deadline", header: "المهلة", render: (row) => <span className="font-mono text-xs text-amber-600 font-bold">{formatDate(row.deadline)}</span> },
        { key: "pledgedByName", header: "المتعهد", accessor: (row) => row.pledgedByName || "—" },
        {
            key: "status",
            header: "الحالة",
            render: (row) => {
                const map: Record<string, { label: string; variant: "outline" | "warning" | "success" | "destructive" }> = {
                    Active: { label: "نشط", variant: "warning" },
                    Fulfilled: { label: "مستوفى", variant: "success" },
                    Expired: { label: "منتهي", variant: "destructive" },
                };
                const info = map[row.status] || { label: row.status, variant: "outline" };
                return <Badge variant={info.variant} className="font-black">{info.label}</Badge>;
            }
        },
        {
            key: "actions",
            header: "إجراءات",
            render: (row) => (
                <div className="flex items-center justify-center gap-1">
                    <Button size="icon" variant="ghost" className="min-h-[44px] min-w-[44px] text-primary hover:bg-primary/5" onClick={() => navigate(`/pledges/${row.pledgeID}/print`)} title="طباعة تعهد">
                        <Printer className="w-4 h-4" />
                    </Button>
                    {row.status === "Active" && (canEditPledge || canManagePledge) && (
                        <Button size="icon" variant="ghost" className="min-h-[44px] min-w-[44px] text-emerald-600 hover:bg-emerald-50" onClick={() => handleMarkFulfilled(row)} title="مستوفى">
                            <CheckCircle className="w-4 h-4" />
                        </Button>
                    )}
                    {canEditPledge && (
                        <Button size="icon" variant="ghost" className="min-h-[44px] min-w-[44px] text-muted-foreground hover:bg-muted" onClick={() => setDialogState(s => ({ ...s, pledge: { open: true, mode: "edit", data: row, shouldPrint: false } }))} title="تعديل">
                            <Edit2 className="w-4 h-4" />
                        </Button>
                    )}
                    {canManagePledge && (
                        <Button size="icon" variant="ghost" className="min-h-[44px] min-w-[44px] text-destructive hover:bg-destructive/5" onClick={() => handleDeletePledge(row)} title="حذف">
                            <X className="w-4 h-4" />
                        </Button>
                    )}
                </div>
            )
        }
    ], [canEditPledge, canManagePledge, handleMarkFulfilled, handleDeletePledge, navigate, renderDocsColumn]);

    const exemptionColumns = useMemo<CustomColumnDef<ExemptionItem>[]>(() => [
        { key: "docs", header: "الوثائق", render: renderDocsColumn },
        { key: "directiveSource", header: "مصدر التوجيه", render: (row) => <span className="font-bold text-sm">{row.directiveSource}</span> },
        { key: "exemptionDate", header: "تاريخ الإعفاء", render: (row) => <span className="font-mono text-xs">{formatDate(row.exemptionDate)}</span> },
        { key: "notes", header: "ملاحظات", accessor: (row) => row.notes || "—" },
        {
            key: "actions",
            header: "إجراءات",
            render: (row) => (
                <div className="flex items-center justify-center gap-1">
                    {canEditExemption && (
                        <Button size="icon" variant="ghost" className="min-h-[44px] min-w-[44px] text-muted-foreground hover:bg-muted" onClick={() => setDialogState(s => ({ ...s, exemption: { open: true, mode: "edit", data: row } }))} title="تعديل">
                            <Edit2 className="w-4 h-4" />
                        </Button>
                    )}
                    {canManageExemption && (
                        <Button size="icon" variant="ghost" className="min-h-[44px] min-w-[44px] text-destructive hover:bg-destructive/5" onClick={() => handleDeleteExemption(row)} title="حذف">
                            <X className="w-4 h-4" />
                        </Button>
                    )}
                </div>
            )
        }
    ], [canEditExemption, canManageExemption, handleDeleteExemption, renderDocsColumn]);

    useCreateShortcut(activeTab === "pledges" ? handleOpenCreatePledge : handleOpenCreateExemption, activeTab === "pledges" ? canCreatePledge : canCreateExemption);

    if (isLoading) return <LoadingIndicator message="جاري تحميل القروض والمعفيات..." />;
    if (peError) return <div className="py-12 text-center text-destructive">تعذر تحميل بيانات التعهدات والإعفاءات</div>;

    return (
        <div className="space-y-3 md:space-y-6 animate-in fade-in duration-500 text-start" dir="rtl">
            {/* Card Header */}
            <TabHeader
                title="التعهدات والإعفاءات"
                description="متابعة وثائق التعهدات المستندية وتوجيهات الإعفاء الخاصة بالملف"
                icon={FileSignature}
                action={{
                    label: activeTab === "pledges" ? "إضافة تعهد" : "إضافة إعفاء",
                    icon: Plus,
                    onClick: () => activeTab === "pledges" ? setDialogState(s => ({ ...s, pledge: { open: true, mode: "create", data: null, shouldPrint: false } })) : setDialogState(s => ({ ...s, exemption: { open: true, mode: "create", data: null } })),
                    show: activeTab === "pledges" ? canCreatePledge : canCreateExemption
                }}
            >
                <div className="flex p-1 bg-background/80 rounded-xl border border-border w-fit ms-0 sm:ms-4">
                    <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => setActiveTab("pledges")}
                        className={`flex items-center gap-2 px-3 py-1.5 text-xs font-bold rounded-lg ${activeTab === "pledges"
                            ? "bg-primary text-primary-foreground shadow-sm"
                            : "text-muted-foreground"
                            }`}
                    >
                        <FileSignature className="w-3.5 h-3.5" />
                        التعهدات <span className="ms-1 px-1.5 py-0.5 rounded-full bg-primary/20 text-[10px] font-mono font-bold">{pledges.length}</span>
                    </Button>
                    <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => setActiveTab("exemptions")}
                        className={`flex items-center gap-2 px-3 py-1.5 text-xs font-bold rounded-lg ${activeTab === "exemptions"
                            ? "bg-primary text-primary-foreground shadow-sm"
                            : "text-muted-foreground"
                            }`}
                    >
                        <ShieldCheck className="w-3.5 h-3.5" />
                        الإعفاءات <span className="ms-1 px-1.5 py-0.5 rounded-full bg-primary/20 text-[10px] font-mono font-bold">{exemptions.length}</span>
                    </Button>
                </div>
            </TabHeader>

            {/* Content */}
            <DataTable
                columns={(activeTab === "pledges" ? pledgeColumns : exemptionColumns) as CustomColumnDef<PledgeItem | ExemptionItem>[]}
                data={(activeTab === "pledges" ? pledges : exemptions) as (PledgeItem | ExemptionItem)[]}
                loading={isLoading}
                emptyMessage={activeTab === "pledges" ? "لا توجد تعهدات مسجلة لهذا الملف" : "لا توجد إعفاءات مسجلة لهذا الملف"}
                renderMobileCard={(item) => activeTab === "pledges" ? (
                    <div className="p-3 space-y-2">
                        <div className="flex items-center justify-between">
                            {(() => {
                                const pMap: Record<string, { color: string; label: string }> = {
                                    Active: { color: "bg-amber-500", label: "نشط" },
                                    Fulfilled: { color: "bg-emerald-500", label: "مستوفى" },
                                    Expired: { color: "bg-red-500", label: "منتهي" },
                                };
                                const info = pMap[(item as PledgeItem).status] || { color: "bg-muted-foreground", label: (item as PledgeItem).status };
                                return <span className={cn("w-2 h-2 rounded-full shrink-0", info.color)} title={info.label} />;
                            })()}
                            <span className="font-mono text-[10px] text-amber-600 font-bold">{formatDate((item as PledgeItem).deadline)}</span>
                        </div>
                        <div className="flex flex-wrap gap-1">
                            {(item as PledgeItem).missingDocuments?.map((doc, idx) => {
                                const isFulfilled = doc.status === "Fulfilled";
                                return (
                                    <Badge key={idx} variant={isFulfilled ? "success" : "outline"} className={`text-[9px] h-3.5 font-bold ${isFulfilled ? "opacity-100 line-through" : ""}`}>
                                        {doc.documentTypeName}
                                    </Badge>
                                );
                            }) || "—"}
                        </div>
                        <div className="text-[10px] text-muted-foreground space-y-0.5">
                            <div>المتعهد: {(item as PledgeItem).pledgedByName || "—"}</div>
                            <div>التاريخ: <span className="font-mono">{formatDate((item as PledgeItem).pledgeDate)}</span></div>
                        </div>
                        <div className="flex justify-end gap-0">
                            <Button size="icon" variant="ghost" className="min-h-[32px] min-w-[32px] h-8 w-8 text-primary" onClick={() => navigate(`/pledges/${(item as PledgeItem).pledgeID}/print`)}>
                                <Printer className="w-3.5 h-3.5" />
                            </Button>
                            {(item as PledgeItem).status === "Active" && (canEditPledge || canManagePledge) && (
                                <Button size="icon" variant="ghost" className="min-h-[32px] min-w-[32px] h-8 w-8 text-emerald-600" onClick={() => handleMarkFulfilled(item as PledgeItem)}>
                                    <CheckCircle className="w-3.5 h-3.5" />
                                </Button>
                            )}
                            {canEditPledge && (
                                <Button size="icon" variant="ghost" className="min-h-[32px] min-w-[32px] h-8 w-8 text-muted-foreground" onClick={() => setDialogState(s => ({ ...s, pledge: { open: true, mode: "edit", data: item as PledgeItem, shouldPrint: false } }))}>
                                    <Edit2 className="w-3.5 h-3.5" />
                                </Button>
                            )}
                            {canManagePledge && (
                                <Button size="icon" variant="ghost" className="min-h-[32px] min-w-[32px] h-8 w-8 text-destructive" onClick={() => handleDeletePledge(item as PledgeItem)}>
                                    <X className="w-3.5 h-3.5" />
                                </Button>
                            )}
                        </div>
                    </div>
                ) : (
                    <div className="p-3 space-y-2">
                        <div className="font-bold text-xs">{(item as ExemptionItem).directiveSource}</div>
                        <div className="text-[10px] text-muted-foreground space-y-0.5">
                            <div>التاريخ: <span className="font-mono">{formatDate((item as ExemptionItem).exemptionDate)}</span></div>
                            {(item as ExemptionItem).notes && <div>ملاحظات: {(item as ExemptionItem).notes}</div>}
                        </div>
                        <div className="flex flex-wrap gap-1">
                            {(item as ExemptionItem).missingDocuments?.map((doc, idx) => {
                                const isFulfilled = doc.status === "Fulfilled";
                                return (
                                    <Badge key={idx} variant={isFulfilled ? "success" : "outline"} className={`text-[9px] h-3.5 font-bold ${isFulfilled ? "opacity-100 line-through" : ""}`}>
                                        {doc.documentTypeName}
                                    </Badge>
                                );
                            }) || "—"}
                        </div>
                        <div className="flex justify-end gap-0">
                            {canEditExemption && (
                                <Button size="icon" variant="ghost" className="min-h-[32px] min-w-[32px] h-8 w-8 text-muted-foreground" onClick={() => setDialogState(s => ({ ...s, exemption: { open: true, mode: "edit", data: item as ExemptionItem } }))}>
                                    <Edit2 className="w-3.5 h-3.5" />
                                </Button>
                            )}
                            {canManageExemption && (
                                <Button size="icon" variant="ghost" className="min-h-[32px] min-w-[32px] h-8 w-8 text-destructive" onClick={() => handleDeleteExemption(item as ExemptionItem)}>
                                    <X className="w-3.5 h-3.5" />
                                </Button>
                            )}
                        </div>
                    </div>
                )}
            />

            {/* Dialogs */}
            {dialogState.pledge.open && (
                <PledgeDialog
                    open={dialogState.pledge.open}
                    onClose={() => setDialogState(s => ({ ...s, pledge: { open: false, mode: "create", data: null, shouldPrint: false } }))}
                    onSubmit={handlePledgeSubmit}
                    isLoading={pledgeMutation.isPending}
                    mode={dialogState.pledge.mode}
                    missingDocs={mapMissingDocsForDialog(missingDocs)}
                    retireeId={fileId}
                    retireeName={retireeName}
                    lookups={lookups}
                    initialData={dialogState.pledge.data ? {
                        missingDocumentIDs: dialogState.pledge.data.missingDocuments?.map(m => m.missingDocumentID) || [],
                        reason: dialogState.pledge.data.reason || "",
                        deadlineMonths: 3,
                        pledgedByType: (() => {
                            const type = dialogState.pledge.data.pledgedByType;
                            if (type === "متقاعد") return "retiree";
                            if (type === "وكيل") return "agent";
                            if (type === "مستحق") return "entitled";
                            if (type === "وصي") return "guardian";
                            return "retiree";
                        })(),
                        selectedID: (() => {
                            const name = dialogState.pledge.data.pledgedByName;
                            const type = dialogState.pledge.data.pledgedByType;
                            if (type === "متقاعد") return String(fileId);
                            if (type === "وكيل") return String(lookups.agents.find((a: { fullName: string | undefined; }) => a.fullName === name)?.id || "");
                            if (type === "مستحق") return String(lookups.entitleds.find((e: { fullName: string | undefined; }) => e.fullName === name)?.id || "");
                            if (type === "وصي") return String(lookups.guardians.find((g: { fullName: string | undefined; }) => g.fullName === name)?.id || "");
                            return "";
                        })()
                    } : undefined}
                />
            )}


            {dialogState.exemption.open && (
                <ExemptionDialog
                    open={dialogState.exemption.open}
                    onClose={() => setDialogState(s => ({ ...s, exemption: { open: false, mode: "create", data: null } }))}
                    onSubmit={handleExemptionSubmit}
                    isLoading={exemptionMutation.isPending}
                    mode={dialogState.exemption.mode}
                    missingDocs={mapMissingDocsForDialog(missingDocs)}
                    initialData={dialogState.exemption.data ? {
                        missingDocumentIDs: dialogState.exemption.data.missingDocuments?.map(m => m.missingDocumentID) || [],
                        directiveSource: dialogState.exemption.data.directiveSource,
                        exemptionDate: dialogState.exemption.data.exemptionDate.split("T")[0],
                        notes: dialogState.exemption.data.notes || "",
                    } : undefined}
                />
            )}

            {dialogState.fulfill.open && dialogState.fulfill.data && (
                <FulfillPledgeDialog
                    open={dialogState.fulfill.open}
                    onOpenChange={(o) => !o && setDialogState(s => ({ ...s, fulfill: { open: false, data: null } }))}
                    onClose={() => setDialogState(s => ({ ...s, fulfill: { open: false, data: null } }))}
                    pledge={dialogState.fulfill.data}
                    isLoading={fulfillPledgeMutation.isPending}
                    onSubmit={async (values) => { await fulfillPledgeMutation.mutateAsync(values); }}
                />
            )}

            {ConfirmDialogElement}
        </div>
    );
}

import { useQuery } from "@tanstack/react-query";
import { AlertTriangle, Check, Wallet, X } from "lucide-react";
import { useEffect, useMemo,useState } from "react";
import { toast } from "sonner";

import { type EndRecipientDto,retirementApi } from "@/api/retirement";
import { type CreateSalaryRecipientDto,salaryRecipientApi } from "@/api/salary-recipients";
import { EndRecipientDialog, type EndRecipientFormValues } from "@/components/domain/retirement/EndRecipientDialog";
import { type RecipientFormValues,RecipientsDialog } from "@/components/domain/retirement/RecipientsDialog";
import { Badge, Button, type CustomColumnDef, DataTable, TabHeader } from "@/components/ui";
import { PENDING_REVIEW_STATUS } from "@/constants";
import { useApiMutation, useCreateShortcut, useCrudState } from "@/hooks";
import { useAgentsQuery, useEntitledPersonsQuery, useGuardiansQuery } from "@/hooks/queries";
import { cn, formatDate } from "@/lib/utils";
import { useHasPermission } from "@/stores/authStore";
import type { AgentSummary, EntitledPersonSummary, GuardianSummary, RecipientItem } from "@/types/retirement";

interface RecipientsTabProps {
    fileId: number;
    retireeId?: number;
    retireeName?: string;
}

/**
 * تبويب مستلمي المعاش لملف التقاعد
 */
export function RecipientsTab({ fileId, retireeId, retireeName }: RecipientsTabProps) {
    const canCreate = useHasPermission("SalaryRecipient.Add");
    const canEnd = useHasPermission("SalaryRecipient.Edit");

    const crud = useCrudState<RecipientItem>();
    const [endOpen, setEndOpen] = useState(false);
    const [endingRecipient, setEndingRecipient] = useState<RecipientItem | null>(null);

    // جلب البيانات
    const { data: recipients = [], isLoading: loadingRecipients, error } = useQuery({
        queryKey: ["salary-recipients", fileId],
        queryFn: () => retirementApi.getRecipients(fileId).then(data => data as RecipientItem[])
    });

    const acknowledgeMutation = useApiMutation(
        (params: { entityType: string; entityId: number }) =>
            retirementApi.acknowledgeEntityRejection(params.entityType, params.entityId),
        {
            successMessage: "تم قبول الرفض وإعادة الكيان لحالته الطبيعية",
            invalidateKeys: [["salary-recipients", fileId], ["retirement-file"]]
        }
    );

    const { data: agentsData = [] } = useAgentsQuery(fileId);
    const { data: entitledsData = [] } = useEntitledPersonsQuery(fileId);
    const { data: guardiansData = [] } = useGuardiansQuery(fileId);

    const agents = useMemo(() => 
        (agentsData as AgentSummary[])
            .filter(a => (a.isActive === true) && !a.isDeleted)
            .map(a => ({ id: a.agentID, fullName: a.entitledPersonName ? `${a.fullName} - عن: ${a.entitledPersonName}` : `${a.fullName} - وكيل عام` })),
    [agentsData]);

    const entitleds = useMemo(() => 
        (entitledsData as EntitledPersonSummary[])
            .filter(e => !e.isDeceased && !e.isDeleted)
            .map(e => ({ 
                id: e.entitledID, 
                fullName: e.fullName,
                isEligible: e.isEligible,
                hasPersonalPhoto: e.hasPersonalPhoto,
                hasNationalIdDocument: e.hasNationalIdDocument
            })), 
    [entitledsData]);

    const guardians = useMemo(() => 
        (guardiansData as GuardianSummary[])
            .filter(g => (g.isActive === true) && !g.isDeleted)
            .map(g => ({ id: g.guardianID, fullName: g.fullName })), 
    [guardiansData]);

    // طفرات البيانات
    const createMutation = useApiMutation(
        (payload: CreateSalaryRecipientDto) => salaryRecipientApi.create(payload),
        {
            successMessage: "تم إضافة مستلم المعاش بنجاح وتفعيل المستحق",
            invalidateKeys: [["salary-recipients", fileId], ["entitled-persons", fileId]],
            onSuccess: () => crud.closeForm()
        }
    );

    const endMutation = useApiMutation(
        (payload: EndRecipientDto) =>
            retirementApi.endRecipient(endingRecipient?.recipientID || 0, payload),
        {
            successMessage: "تم إنهاء مستلم المعاش بنجاح",
            invalidateKeys: [["salary-recipients", fileId]],
            onSuccess: () => {
                setEndOpen(false);
                setEndingRecipient(null);
            }
        }
    );

    useEffect(() => {
        if (error) toast.error("حدث خطأ أثناء تحميل بيانات مستلمي المعاش");
    }, [error]);

    // المعالجات
    const handleCreate = (values: RecipientFormValues) => {
        const payload: CreateSalaryRecipientDto = {
            fileID: fileId,
            startDate: values.startDate,
            notes: values.notes || undefined,
            // بيانات تكميلية
            nationalID: values.nationalID,
            birthDate: values.birthDate,
            socialStatusID: values.socialStatusID,
            healthStatusID: values.healthStatusID,
            personalPhoto: values.personalPhoto,
            nationalIdImage: values.nationalIdImage,
            sharePercent: values.recipientType === "entitled" && values.sharePercent ? Number(values.sharePercent) : undefined,
            entitledAmount: values.recipientType === "entitled" && values.entitledAmount ? Number(values.entitledAmount) : undefined,
        };

        if (values.recipientType === "retiree") payload.retireeID = Number(values.targetID);
        else if (values.recipientType === "agent") payload.agentID = Number(values.targetID);
        else if (values.recipientType === "entitled") payload.entitledID = Number(values.targetID);
        else if (values.recipientType === "guardian") payload.guardianID = Number(values.targetID);
        if (values.recipientType === "guardian") payload.entitledID = Number(values.coveredEntitledID);

        createMutation.mutate(payload);
    };

    const handleEnd = (values: EndRecipientFormValues) => {
        const payload: EndRecipientDto = {
            endDate: values.endDate,
            notes: values.notes || undefined
        };
        endMutation.mutate(payload);
    };

    const columns: CustomColumnDef<RecipientItem>[] = [
        {
            key: "recipientName",
            header: "اسم المستلم",
            render: (row) => (
                <div className="flex flex-col text-start">
                    <span className="font-bold flex items-center gap-2">
                        {row.recipientName || row.retireeFullName || row.agentFullName || row.entitledFullName || row.guardianFullName || "—"}
                        {row.pendingReviewStatus === PENDING_REVIEW_STATUS.PENDING_REVIEW && (
                            <Badge variant="warning" className="text-[10px] sm:text-xs h-5">قيد المراجعة</Badge>
                        )}
                        {row.pendingReviewStatus === PENDING_REVIEW_STATUS.REJECTED && (
                            <Badge variant="destructive" className="text-[10px] sm:text-xs h-5">مرفوض</Badge>
                        )}
                    </span>
                    <span className="text-[10px] sm:text-xs text-muted-foreground">{row.isActive ? "نشط" : "غير نشط"}</span>
                    {row.entitledPersonName && <span className="text-xs text-muted-foreground break-words">عن المستحق: {row.entitledPersonName}</span>}
                </div>
            )
        },
        {
            key: "startDate",
            header: "تاريخ البدء",
            render: (row) => <span className="font-mono text-xs">{formatDate(row.startDate)}</span>
        },
        {
            key: "sharePercent",
            header: "حصة المعاش",
            render: (row) => row.sharePercent == null ? "—" : `${row.sharePercent}%`
        },
        {
            key: "endDate",
            header: "تاريخ الانتهاء",
            render: (row) => row.endDate ? <span className="font-mono text-xs text-rose-600">{formatDate(row.endDate)}</span> : "—"
        },
        {
            key: "isActive",
            header: "الحالة",
            render: (row) => (
                <Badge variant={row.isActive ? "success" : "outline"}>
                    {row.isActive ? "نشط حالياً" : "سابق / منتهي"}
                </Badge>
            )
        },
        {
            key: "actions",
            header: "إجراءات",
            render: (row) => (
                <div className="flex items-center justify-center gap-1">
                    {row.isActive && canEnd ? (
                        <Button
                            size="sm"
                            variant="ghost"
                            className="text-destructive hover:bg-destructive/5 hover:text-destructive gap-1.5 font-bold"
                            onClick={() => {
                                setEndingRecipient(row);
                                setEndOpen(true);
                            }}
                        >
                            <X className="w-3.5 h-3.5" /> إنهاء الاستلام
                        </Button>
                    ) : null}
                    {row.pendingReviewStatus === PENDING_REVIEW_STATUS.REJECTED && (
                        <Button size="icon" variant="ghost" className="min-h-[44px] min-w-[44px] text-amber-600" onClick={() => acknowledgeMutation.mutate({ entityType: "SalaryRecipient", entityId: row.recipientID })} title="قبول الرفض">
                            <Check className="w-4 h-4" />
                        </Button>
                    )}
                </div>
            )
        }
    ];

    if (error) return (
        <div className="py-12 text-center text-destructive flex flex-col items-center gap-2">
            <AlertTriangle className="w-8 h-8" />
            <p className="font-bold">حدث خطأ أثناء تحميل بيانات مستلمي المعاش</p>
        </div>
    );

    useCreateShortcut(crud.openCreate, canCreate);

    return (
        <div className="space-y-2 md:space-y-4 animate-in fade-in duration-500 text-start">
            <TabHeader
                title="مستلمي المعاش"
                description="سجل الأشخاص المخولين باستلام المعاش (متقاعد، وكلاء، أوصياء)"
                icon={Wallet}
                action={{
                    label: "تعيين مستلم جديد",
                    icon: Wallet,
                    onClick: crud.openCreate,
                    show: canCreate
                }}
            />

            <DataTable
                columns={columns}
                data={recipients}
                loading={loadingRecipients}
                emptyMessage="لا يوجد مستلمين مسجلين حالياً"
                renderMobileCard={(item) => (
                    <div className="p-3 space-y-2">
                        <div className="flex items-center justify-between">
                            <span className="font-bold text-xs truncate max-w-[200px]">
                                {item.retireeFullName || item.agentFullName || item.entitledFullName || item.guardianFullName || "—"}
                            </span>
                            <span className={cn("w-2 h-2 rounded-full shrink-0", item.isActive ? "bg-emerald-500" : "bg-muted-foreground")} title={item.isActive ? "نشط" : "منتهي"} />
                        </div>
                        <div className="flex items-center gap-1.5 flex-wrap">
                            {item.pendingReviewStatus === PENDING_REVIEW_STATUS.PENDING_REVIEW && (
                                <Badge variant="warning" className="text-[8px] h-3.5 shrink-0">قيد المراجعة</Badge>
                            )}
                            {item.pendingReviewStatus === PENDING_REVIEW_STATUS.REJECTED && (
                                <Badge variant="destructive" className="text-[8px] h-3.5 shrink-0">مرفوض</Badge>
                            )}
                        </div>
                        <div className="text-[10px] text-muted-foreground flex items-center gap-3 flex-wrap">
                            <span>البدء: <span className="font-mono">{formatDate(item.startDate)}</span></span>
                            {item.endDate && <span>الانتهاء: <span className="font-mono text-rose-600">{formatDate(item.endDate)}</span></span>}
                        </div>
                        <div className="flex justify-end gap-1">
                            {item.isActive && canEnd && (
                                <Button
                                    size="sm"
                                    variant="ghost"
                                    className="text-destructive hover:bg-destructive/5 gap-1 font-bold min-h-[32px] h-8 text-xs px-2"
                                    onClick={() => {
                                        setEndingRecipient(item);
                                        setEndOpen(true);
                                    }}
                                >
                                    <X className="w-3.5 h-3.5" /> إنهاء
                                </Button>
                            )}
                            {item.pendingReviewStatus === PENDING_REVIEW_STATUS.REJECTED && (
                                <Button
                                    size="sm"
                                    variant="ghost"
                                    className="min-h-[32px] h-8 text-amber-600 gap-1 text-xs px-2"
                                    onClick={() => acknowledgeMutation.mutate({ entityType: "SalaryRecipient", entityId: item.recipientID })}
                                >
                                    <Check className="w-3.5 h-3.5" /> قبول
                                </Button>
                            )}
                        </div>
                    </div>
                )}
            />

            <RecipientsDialog
                open={crud.isFormOpen}
                onOpenChange={crud.onOpenChange}
                onSubmit={handleCreate}
                isLoading={createMutation.isPending}
                retireeId={retireeId}
                retireeName={retireeName}
                lookups={{
                    agents,
                    entitleds,
                    guardians
                }}
            />

            {endOpen && endingRecipient && (
                <EndRecipientDialog
                    open={endOpen}
                    onOpenChange={(o) => !o && setEndOpen(false)}
                    onSubmit={handleEnd}
                    isLoading={endMutation.isPending}
                    recipientName={endingRecipient.retireeFullName || endingRecipient.agentFullName || endingRecipient.entitledFullName || endingRecipient.guardianFullName || ""}
                />
            )}
        </div>
    );
}

import { useQuery, useQueryClient } from "@tanstack/react-query";
import { AlertTriangle, CheckCircle2, Download, FileText, Gavel, RefreshCw, Search, Trash2, Upload, XCircle } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useNavigate,useParams } from "react-router-dom";
import { toast } from "sonner";

import type { SettlementItemDto } from "@/api/settlements";
import { settlementApi } from "@/api/settlements";
import { LinkRetireeDialog } from "@/components/domain/settlements/LinkRetireeDialog";
import { Button, CrudPageLayout, EmptyState, Loader, PageLayout, StatCard, useConfirm } from "@/components/ui";
import { AlertBanner } from "@/components/ui/AlertBanner";
import { useApiMutation } from "@/hooks";
import { useDebouncedSearch } from "@/hooks/useDebouncedSearch";
import { formatDate } from "@/lib/utils";
import { useHasPermission } from "@/stores/authStore";

// ─── Page ──────────────────────────────────────────────

export function SettlementBatchDetailsPage() {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();
    const canManage = useHasPermission("Settlement.Manage");
    const canExport = useHasPermission("Export.Financial");
    const { confirm } = useConfirm();
    const queryClient = useQueryClient();
    const fileInputRef = useRef<HTMLInputElement>(null);
    const correctionFileInputRef = useRef<HTMLInputElement>(null);

    const { searchTerm, setSearchTerm, debouncedValue: debouncedSearch } = useDebouncedSearch();
    const [focusedIndex, setFocusedIndex] = useState(-1);
    const focusedIndexRef = useRef(-1);
    const searchInputRef = useRef<HTMLInputElement>(null);
    const [itemsPage, setItemsPage] = useState(1);
    const itemsPageSize = 20;
    const [isGeneratingFailures, setIsGeneratingFailures] = useState(false);

    // ── Debounce Search ────────────────────────────────
    useEffect(() => {
        setItemsPage(1);
        setFocusedIndex(-1);
        focusedIndexRef.current = -1;
    }, [debouncedSearch]);

    const importCorrectionMutation = useApiMutation(
        async (file: File) => {
            const batchId = decision?.data?.batchID;
            if (!batchId) {
                console.error("Batch ID is missing in decision data", decision?.data);
                throw new Error("رقم الكشف غير متوفر؛ يرجى تحديث الصفحة والمحاولة مرة أخرى.");
            }
            
            return await settlementApi.importCorrection(batchId, {
                file,
                decisionNumber: decision.data.decisionNumber,
                decisionDate: decision.data.decisionDate,
                decisionType: decision.data.decisionType || undefined,
                notes: decision.data.notes || undefined,
            });
        },
        {
            successMessage: "تم استكمال الاستيراد بنجاح",
            onSuccessCallback: () => {
                setItemsPage(1);
                queryClient.invalidateQueries({ queryKey: ["settlement-decision", id] });
                queryClient.invalidateQueries({ queryKey: ["settlement-decision-items", id] });
            }
        }
    );

    // For Link Dialog
    const [linkDialogOpen, setLinkDialogOpen] = useState(false);
    const [selectedItemToLink, setSelectedItemToLink] = useState<SettlementItemDto | null>(null);

    const { data: decision, isLoading: loadingDecision, isError: decisionError } = useQuery({
        queryKey: ["settlement-decision", id],
        queryFn: () => settlementApi.getDecision(parseInt(id!)),
        enabled: !!id
    });

    const { data: itemsPaged, isLoading: loadingItems } = useQuery({
        queryKey: ["settlement-decision-items", id, { page: itemsPage, pageSize: itemsPageSize, searchTerm: debouncedSearch }],
        queryFn: () => settlementApi.getDecisionItems(parseInt(id!), { page: itemsPage, pageSize: itemsPageSize, searchTerm: debouncedSearch || undefined }),
        enabled: !!id
    });

    const items = useMemo(() => itemsPaged?.items || [], [itemsPaged]);
    const itemsTotalCount = itemsPaged?.totalCount || 0;

    const loading = loadingDecision || loadingItems;

    const deleteMutation = useApiMutation(
        async () => {
            await settlementApi.deleteDecision(parseInt(id!));
        },
        {
            successMessage: "تم حذف القرار بنجاح",
            onSuccessCallback: () => navigate("/settlements")
        }
    );

    const exportMutation = useApiMutation(
        async () => {
            const res = await settlementApi.exportDecision(parseInt(id!));
            const url = window.URL.createObjectURL(new Blob([res.data]));
            const a = document.createElement("a");
            a.href = url;
            a.download = `settlement_decision_${id}.xlsx`;
            a.click();
            window.URL.revokeObjectURL(url);
            return res;
        },
        { successMessage: "تم تحميل ملف Excel" }
    );

    const downloadStoredFailureReport = useCallback(async () => {
        setIsGeneratingFailures(true);
        try {
            const response = await settlementApi.getFailureReport(parseInt(id!));

            const url = window.URL.createObjectURL(new Blob([response.data]));
            const link = document.createElement('a');
            link.href = url;
            link.setAttribute('download', `failures_report_decision_${id}.xlsx`);
            document.body.appendChild(link);
            link.click();
            link.remove();
            window.URL.revokeObjectURL(url);
        } catch (error: unknown) {
            console.error("Failed to download failure report", error);
            const err = error as { response?: { data?: Blob } };
            const message = err.response?.data instanceof Blob ? await err.response.data.text() : "فشل تحميل تقرير الأخطاء";
            toast.error(message);
        } finally {
            setIsGeneratingFailures(false);
        }
    }, [id]);

    const handleFileChange = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setIsGeneratingFailures(true);
        try {
            const response = await settlementApi.exportFailures(parseInt(id!), file);

            const url = window.URL.createObjectURL(new Blob([response.data]));
            const link = document.createElement('a');
            link.href = url;
            link.setAttribute('download', `failures_report_decision_${id}.xlsx`);
            document.body.appendChild(link);
            link.click();
            link.remove();
            window.URL.revokeObjectURL(url);
        } catch (error: unknown) {
            console.error("Failed to download error report", error);
            const err = error as { response?: { data?: Blob } };
            const message = err.response?.data instanceof Blob ? await err.response.data.text() : "فشل فحص الملف";
            toast.error(message);
        } finally {
            setIsGeneratingFailures(false);
            if (fileInputRef.current) fileInputRef.current.value = "";
            queryClient.invalidateQueries({ queryKey: ["settlement-decision", id] });
        }
    }, [id, queryClient, toast]);

    const handleDelete = async () => {
        if (!(await confirm({ title: "تأكيد الإجراء", description: "هل أنت متأكد من حذف هذا القرار وجميع بنوده؟", variant: "danger" }))) return;
        deleteMutation.mutate({});
    };

    const matchedCount = items.filter(i => i.retireeID).length;
    const unmatchedCount = items.filter(i => !i.retireeID).length;

    const itemColumns = [
        {
            key: "serial",
            header: "ت",
            render: (row: SettlementItemDto) => (
                <span className="font-mono text-muted-foreground">{row.serialNumber}</span>
            )
        },
        {
            key: "militaryNumber",
            header: "الرقم العسكري",
            render: (row: SettlementItemDto) => (
                <span className="font-mono">{row.militaryNumber || "-"}</span>
            )
        },
        {
            key: "name",
            header: "الاسم",
            render: (row: SettlementItemDto) => (
                <div>
                    <div className="font-medium">{row.retireeFullName}</div>
                    {row.retireeID ? (
                        <div className="text-xs text-success flex items-center gap-1 mt-0.5">
                            <CheckCircle2 className="w-4 h-4" /> مطابق
                        </div>
                    ) : (
                        <div className="text-xs text-warning flex items-center gap-1 mt-0.5">
                            <XCircle className="w-4 h-4" /> غير مطابق
                        </div>
                    )}
                </div>
            )
        },
        {
            key: "ranks",
            header: "الرتبة (الحالية ➔ الجديدة)",
            render: (row: SettlementItemDto) => (
                <div className="text-xs">
                    <span className="text-muted-foreground">{row.currentRankName}</span>
                    <span className="mx-2">➔</span>
                    <span className="font-bold text-primary">{row.processedRankName}</span>
                </div>
            )
        },
        {
            key: "salary",
            header: "المعاش المعتمد",
            render: (row: SettlementItemDto) => (
                <span className="font-mono font-bold">
                    {(row.processedRankSalary ?? 0).toLocaleString()} ر.ي
                </span>
            )
        },
        {
            key: "actions",
            header: "",
            render: (row: SettlementItemDto) => (
                <div className="flex items-center gap-2">
                    {row.retireeID ? (
                        <span className="text-xs text-success">الاستحقاق مُنشأ</span>
                    ) : (
                        <Button
                            variant="secondary"
                            size="sm"
                            className="text-xs h-7"
                            onClick={() => {
                                setSelectedItemToLink(row);
                                setLinkDialogOpen(true);
                            }}
                        >
                            ربط يدوي
                        </Button>
                    )}
                </div>
            )
        }
    ];

    // ── Keyboard Navigation ────────────────────────────
    const handleSearchKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement>) => {
        if (e.key === "ArrowDown") {
            e.preventDefault();
            setFocusedIndex(prev => {
                const next = prev + 1;
                const clamped = next < items.length ? next : prev;
                focusedIndexRef.current = clamped;
                return clamped;
            });
        } else if (e.key === "ArrowUp") {
            e.preventDefault();
            setFocusedIndex(prev => {
                const clamped = prev > 0 ? prev - 1 : prev;
                focusedIndexRef.current = clamped;
                return clamped;
            });
        } else if (e.key === "Enter") {
            e.preventDefault();
            const idx = focusedIndexRef.current;
            if (idx >= 0 && idx < items.length) {
                const row = items[idx];
                if (!row.retireeID) {
                    setSelectedItemToLink(row);
                    setLinkDialogOpen(true);
                }
            }
        } else if (e.key === "Escape") {
            setFocusedIndex(-1);
            focusedIndexRef.current = -1;
        }
    }, [items]);

    // Scroll to focused row
    useEffect(() => {
        if (focusedIndex >= 0) {
            const row = document.querySelector(`[data-row-index="${focusedIndex}"]`)
                      || document.querySelector(`[data-index="${focusedIndex}"]`);
            if (row) {
                row.scrollIntoView({ behavior: "smooth", block: "nearest" });
            }
        }
    }, [focusedIndex]);

    if (loading) {
        return <Loader variant="fullscreen" />;
    }

    if (decisionError) {
        return <AlertBanner variant="destructive" title="تعذر تحميل بيانات القرار" />;
    }

    if (!decision?.data) {
        return <EmptyState icon={<FileText className="h-12 w-12" /> as any} title="لم يتم العثور على القرار" description="عذراً، لم يتم العثور على القرار المطلوب." />;
    }

    const dec = decision.data;

    return (
        <PageLayout className="p-4 sm:p-6">
            <CrudPageLayout<SettlementItemDto>
                title={`قرار تسوية رقم ${dec.decisionNumber}`}
                description={`تاريخ القرار: ${formatDate(dec.decisionDate)} • النوع: ${dec.decisionType || "تسوية رتب"}`}
                icon={<Gavel className="w-6 h-6 text-primary" />}
                columns={itemColumns}
                data={items}
                loading={loadingItems}
                searchable
                searchInHeader
                searchPlaceholder="بحث بالاسم أو الرقم العسكري..."
                searchValue={searchTerm}
                onSearchChange={(val) => setSearchTerm(val)}
                onSearchKeyDown={handleSearchKeyDown}
                searchInputRef={searchInputRef}
                focusedRowIndex={focusedIndex}
                pagination={{
                    page: itemsPage,
                    pageSize: itemsPageSize,
                    total: itemsTotalCount,
                    onPageChange: (p) => setItemsPage(p)
                }}
                headerActions={
                    <>
                        <Button variant="outline" className="gap-2" onClick={() => navigate(`/settlements/${id}/print`)}>
                            <FileText className="w-4 h-4" /> طباعة القرار
                        </Button>
                        {canExport && (
                            <Button variant="outline" className="gap-2" onClick={() => exportMutation.mutate(undefined)} loading={exportMutation.isPending}>
                                <Download className="w-4 h-4" /> تصدير Excel
                            </Button>
                        )}
                        {canManage && (
                            <Button
                                variant="destructive"
                                className="gap-2"
                                onClick={handleDelete}
                                loading={deleteMutation.isPending}
                            >
                                <Trash2 className="w-4 h-4" /> حذف القرار
                            </Button>
                        )}
                    </>
                }
            >
                {/* ─── Custom Page Content ─── */}
                <div className="space-y-6">
                    {/* Proactive Data Shortage Alert */}
                    {(dec.sourceRowsCount > dec.itemCount || dec.hasFailureReport) && (
                        <AlertBanner
                            variant="warning"
                            title="تم اكتشاف نقص في البيانات المستوردة"
                            description={`ملف الـ Excel الأصلي يحتوي على ${dec.sourceRowsCount} صف، بينما تم استيراد ${dec.itemCount} بند فقط. هناك ${dec.sourceRowsCount - dec.itemCount} صف فاشل.`}
                            icon={<AlertTriangle className="h-5 w-5" />}
                            className="flex flex-col md:flex-row items-center justify-between gap-4"
                        >
                            <div className="flex items-center gap-2 flex-wrap">
                                {dec.hasFailureReport && (
                                    <Button
                                        variant="warning"
                                        size="sm"
                                        className="gap-2 font-bold"
                                        onClick={downloadStoredFailureReport}
                                        loading={isGeneratingFailures}
                                    >
                                        <Download className="w-4 h-4" />
                                        تحميل تقرير الأخطاء
                                    </Button>
                                )}
                                <input
                                    type="file"
                                    ref={correctionFileInputRef}
                                    className="hidden"
                                    accept=".xlsx,.xls"
                                    onChange={(e) => {
                                        const file = e.target.files?.[0];
                                        if (file) importCorrectionMutation.mutate(file);
                                        e.target.value = "";
                                    }}
                                />
                                <Button 
                                    variant="primary" 
                                    size="sm" 
                                    className="gap-2 font-bold"
                                    onClick={() => correctionFileInputRef.current?.click()}
                                    loading={importCorrectionMutation.isPending}
                                >
                                    <Upload className="w-4 h-4" />
                                    رفع واستكمال الاستيراد
                                </Button>
                                <input
                                    type="file"
                                    ref={fileInputRef}
                                    className="hidden"
                                    accept=".xlsx,.xls"
                                    onChange={handleFileChange}
                                />
                                <Button 
                                    variant="outline" 
                                    size="sm" 
                                    className="gap-2 border-warning hover:bg-warning/10 text-warning"
                                    onClick={() => fileInputRef.current?.click()}
                                    loading={isGeneratingFailures}
                                >
                                    <Search className="w-4 h-4" />
                                    فحص ملف جديد
                                </Button>
                            </div>
                        </AlertBanner>
                    )}

                    {/* Stats Grid */}
                    <div className="grid grid-cols-2 md:grid-cols-3 gap-2 sm:gap-4">
                        <StatCard
                            title="إجمالي الفروقات المالية"
                            value={`${(dec.totalAmount ?? 0).toLocaleString()} ر.ي`}
                            icon={<Gavel className="w-6 h-6" />}
                            variant="blue"
                        />
                        <StatCard
                            title="سجلات متطابقة (تم الربط)"
                            value={matchedCount}
                            icon={<CheckCircle2 className="w-6 h-6" />}
                            variant="emerald"
                            description={`${Math.round((matchedCount / items.length) * 100) || 0}% من إجمالي السجلات`}
                        />
                        <StatCard
                            title="سجلات معلقة (تحتاج ربط)"
                            value={unmatchedCount}
                            icon={<RefreshCw className="w-6 h-6" />}
                            variant="amber"
                            description="يتطلب ربطاً يدوياً بالمتقاعدين"
                        />
                    </div>
                </div>
            </CrudPageLayout>

            {/* Dialogs */}
            <LinkRetireeDialog
                open={linkDialogOpen}
                onOpenChange={(open) => {
                    if (!open) {
                        setLinkDialogOpen(false);
                        setSelectedItemToLink(null);
                    }
                }}
                item={selectedItemToLink}
                onLinked={() => {
                    queryClient.invalidateQueries({ queryKey: ["settlement-decision", id] });
                    queryClient.invalidateQueries({ queryKey: ["settlement-decision-items", id] });
                }}
            />
        </PageLayout>
    );
}

import { useQuery, useQueryClient } from "@tanstack/react-query";
import { Calendar, FileText, Hash,Trash2 } from "lucide-react";
import { useCallback, useEffect, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";

import type { SettlementDecisionDto } from "@/api/settlements";
import { settlementApi } from "@/api/settlements";
import { SearchDialog } from "@/components/common/SearchDialog";
import { CreateSettlementDecisionDialog } from "@/components/domain/settlements/CreateSettlementDecisionDialog";
import { Badge, Button, CrudPageLayout, useConfirm } from "@/components/ui";
import { queryKeys } from "@/constants/queryKeys";
import { useApiMutation,useCrudState } from "@/hooks";
import { useDebouncedSearch } from "@/hooks/useDebouncedSearch";
import { formatDate } from "@/lib/utils";
import { useHasPermission } from "@/stores/authStore";

// ─── Page ──────────────────────────────────────────────

export function SettlementDecisionsPage() {
    const navigate = useNavigate();
    const canManage = useHasPermission("Settlement.Manage");
    const { confirm, ConfirmDialogElement } = useConfirm();
    const queryClient = useQueryClient();
    const crudState = useCrudState<SettlementDecisionDto>();

    const { searchTerm, setSearchTerm, debouncedValue: debouncedSearch } = useDebouncedSearch();
    const [focusedIndex, setFocusedIndex] = useState(-1);
    const focusedIndexRef = useRef(-1);
    const searchInputRef = useRef<HTMLInputElement>(null);
    const [page, setPage] = useState(1);
    const pageSize = 20;

    // ── Debounce Search ────────────────────────────────
    useEffect(() => {
        setPage(1);
        setFocusedIndex(-1);
        focusedIndexRef.current = -1;
    }, [debouncedSearch]);

    const { data: pagedResponse, isLoading: loading, error: queryError } = useQuery({
        queryKey: queryKeys.settlements.decisions.list({ page, pageSize, searchTerm: debouncedSearch }),
        queryFn: () => settlementApi.getAllDecisions({ page, pageSize, searchTerm: debouncedSearch || undefined })
    });

    useEffect(() => {
        if (queryError) {
            toast.error("فشل تحميل القرارات", {
                description: queryError instanceof Error ? queryError.message : "حدث خطأ غير متوقع"
            });
        }
    }, [queryError]);

    const decisions = pagedResponse?.items || [];
    const totalCount = pagedResponse?.totalCount || 0;

    // Auto-navigate back if the current page becomes empty (e.g., after delete)
    useEffect(() => {
        if (pagedResponse && decisions.length === 0 && page > 1) {
            setPage(p => p - 1);
        }
    }, [pagedResponse, decisions.length, page]);

    const deleteMutation = useApiMutation(
        async (id: number) => { await settlementApi.deleteDecision(id); },
        {
            successMessage: "تم حذف القرار بنجاح",
            onSuccessCallback: () => {
                queryClient.invalidateQueries({ queryKey: queryKeys.settlements.decisions.all });
            }
        }
    );

    const handleDelete = async (id: number) => {
        const confirmed = await confirm({
            title: "تأكيد الحذف",
            description: "هل أنت متأكد من حذفه هذا القرار وجميع بنوده؟",
            variant: "danger",
        });
        if (!confirmed) return;
        deleteMutation.mutate(id);
    };

    const columns = [
        {
            key: "decisionNumber",
            header: "رقم القرار",
            render: (row: SettlementDecisionDto) => (
                <span className="font-mono font-bold text-primary">{row.decisionNumber}</span>
            )
        },
        {
            key: "decisionDate",
            header: "تاريخ القرار",
            render: (row: SettlementDecisionDto) => (
                <div className="flex items-center gap-1.5 text-sm">
                    <Calendar className="w-3.5 h-3.5 text-muted-foreground" />
                    {formatDate(row.decisionDate)}
                </div>
            )
        },
        {
            key: "decisionType",
            header: "النوع",
            render: (row: SettlementDecisionDto) => (
                <Badge variant="outline">{row.decisionType || "تسوية"}</Badge>
            )
        },
        {
            key: "itemCount",
            header: "عدد القيود",
            render: (row: SettlementDecisionDto) => (
                <div className="flex items-center gap-1.5">
                    <Hash className="w-3.5 h-3.5 text-muted-foreground" />
                    <span className="font-medium">{row.itemCount}</span>
                </div>
            )
        },
        {
            key: "totalAmount",
            header: "إجمالي المبلغ",
            render: (row: SettlementDecisionDto) => (
                <span className="font-medium">{row.totalAmount?.toLocaleString("ar-YE") || "0"} ر.ي</span>
            )
        },
        {
            key: "createdBy",
            header: "بواسطة",
            render: (row: SettlementDecisionDto) => (
                <span className="text-sm text-muted-foreground">{row.createdByUserName || "-"}</span>
            )
        },
        {
            key: "actions",
            header: "",
            render: (row: SettlementDecisionDto) => (
                <div className="flex items-center gap-1">
                    <Button
                        variant="ghost"
                        size="icon"
                        className="min-h-[44px] min-w-[44px]"
                        onClick={(e) => { e.stopPropagation(); navigate(`/settlements/${row.decisionID}`); }}
                    >
                        <FileText className="w-4 h-4" />
                    </Button>
                    {canManage && (
                        <Button
                            variant="ghost"
                            size="icon"
                            className="min-h-[44px] min-w-[44px] text-destructive hover:text-destructive"
                            onClick={(e) => { e.stopPropagation(); handleDelete(row.decisionID); }}
                            loading={deleteMutation.isPending && deleteMutation.variables === row.decisionID}
                        >
                            <Trash2 className="w-4 h-4" />
                        </Button>
                    )}
                </div>
            )
        }
    ];

    // ── Keyboard Navigation ────────────────────────────
    const handleSearchKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement>) => {
        if (e.key === "ArrowDown") {
            e.preventDefault();
            setFocusedIndex(prev => {
                const next = prev + 1;
                const clamped = next < decisions.length ? next : prev;
                focusedIndexRef.current = clamped;
                return clamped;
            });
        } else if (e.key === "ArrowUp") {
            e.preventDefault();
            setFocusedIndex(prev => {
                const clamped = prev > 0 ? prev - 1 : prev;
                focusedIndexRef.current = clamped;
                return clamped;
            });
        } else if (e.key === "Enter") {
            e.preventDefault();
            const idx = focusedIndexRef.current;
            if (idx >= 0 && idx < decisions.length) {
                navigate(`/settlements/${decisions[idx].decisionID}`);
            }
        } else if (e.key === "Escape") {
            setFocusedIndex(-1);
            focusedIndexRef.current = -1;
        }
    }, [decisions, navigate]);

    // Scroll to focused row
    useEffect(() => {
        if (focusedIndex >= 0) {
            const row = document.querySelector(`[data-row-index="${focusedIndex}"]`)
                      || document.querySelector(`[data-index="${focusedIndex}"]`);
            if (row) {
                row.scrollIntoView({ behavior: "smooth", block: "nearest" });
            }
        }
    }, [focusedIndex]);

    return (
        <CrudPageLayout
            title="قرارات التسوية"
            description="إدارة قرارات تسوية الرتب الصادرة من الوزارة"
            createLabel="إضافة قرار جديد"
            onCreateClick={canManage ? () => crudState.openCreate() : undefined}
            headerActions={
                <SearchDialog
                    value={searchTerm}
                    onSelect={(name) => setSearchTerm(name)}
                    queryKey={["settlement-decisions-search"]}
                    fetchFn={(term) =>
                        settlementApi.getAllDecisions({ page: 1, pageSize: 100, searchTerm: term })
                    }
                    getName={(item) => item.decisionNumber}
                    getSubtitle={(item) => item.decisionType || "تسوية"}
                    title="بحث عن قرار"
                    placeholder="بحث برقم القرار..."
                    hideTrigger
                />
            }
            columns={columns}
            data={decisions}
            loading={loading}
            searchable
            searchInHeader
            searchPlaceholder="بحث برقم أو نوع القرار..."
            searchValue={searchTerm}
            onSearchChange={(val) => setSearchTerm(val)}
            onSearchKeyDown={handleSearchKeyDown}
            searchInputRef={searchInputRef}
            focusedRowIndex={focusedIndex}
            rowKey={(row) => row.decisionID}
            onRowClick={(row) => navigate(`/settlements/${row.decisionID}`)}
            pagination={{
                page,
                pageSize,
                total: totalCount,
                onPageChange: (p) => setPage(p)
            }}
        >
            <CreateSettlementDecisionDialog
                open={crudState.isFormOpen}
                onOpenChange={(open) => !open && crudState.closeForm()}
                onSaved={() => { setPage(1); queryClient.invalidateQueries({ queryKey: ["settlement-decisions"] }); }}
            />

            {ConfirmDialogElement}
        </CrudPageLayout>
    );
}

import { jwtDecode } from "jwt-decode";
import { create } from "zustand";

import api, { broadcastLogout,broadcastToken } from "@/api/axios";

import { useNotificationStore } from "./useNotificationStore";

// ─── Constants ──────────────────────────────────────────
const LS_TOKEN_KEY = "auth_token";
const LS_REFRESH_TOKEN_KEY = "auth_refresh_token";
const LS_USER_KEY = "auth_user";
const LS_PERMISSIONS_KEY = "auth_permissions";

// ─── Types ──────────────────────────────────────────────
export interface AuthUser {
    id: number;
    fullName: string;
    username: string;
    email?: string | null;
    role: string;
    roleId?: number;
    branchId?: number;
    branchName?: string;
    mustChangePassword?: boolean;
    createdAt?: string;
    lastLogin?: string | null;
    isActive?: boolean;
}

export interface LoginResponse {
    token: string;
    refreshToken?: string;
    user: AuthUser;
}

export type HydrationState = 'idle' | 'restoring' | 'loadingPermissions' | 'ready' | 'error';

interface AuthState {
    token: string | null;
    user: AuthUser | null;
    permissions: string[];
    permissionsLoaded: boolean;
    permissionsError: boolean;
    isLoadingPermissions: boolean;
    isAuthenticated: boolean;
    isHydrated: boolean;
    hydrationState: HydrationState;
    sessionExpired: boolean;
    hydrationError: boolean;
    login: (data: LoginResponse) => Promise<void>;
    logout: () => Promise<void>;
    handleSessionExpiry: () => void;
    hydrate: () => Promise<void>;
    refreshPermissions: (silent?: boolean) => Promise<void>;
    refreshTokenNow: () => Promise<void>;
}

// ─── Logger ─────────────────────────────────────────────
function logError(context: string, error: unknown) {
    if (import.meta.env.DEV) {
         
        console.error(`[AuthStore] ${context}:`, error);
    }
    // TODO: Send to error tracking service in production
}

// ─── Pre-emptive token refresh ──────────────────────────
let _refreshTimer: ReturnType<typeof setTimeout> | null = null;

function _clearRefreshTimer() {
    if (_refreshTimer) clearTimeout(_refreshTimer);
    _refreshTimer = null;
}

function _scheduleTokenRefresh(token: string | null) {
    _clearRefreshTimer();
    if (!token) return;

    try {
        const decoded = jwtDecode<{ exp?: number }>(token);
        const exp = decoded?.exp;

        if (typeof exp !== 'number' || isNaN(exp)) {
            logError('Token missing or invalid exp claim', { exp });
            return;
        }

        const timeLeft = exp * 1000 - Date.now();
        if (timeLeft <= 10_000) return; // less than 10s left — too late to pre-empt

        // Refresh at 70% of token lifetime, or 5 min before expiry — whichever is sooner
        const refreshAt = Math.min(timeLeft - 5 * 60 * 1000, timeLeft * 0.7);
        if (refreshAt <= 0) return;

        const scheduledToken = token; // Capture for closure identity check

        _refreshTimer = setTimeout(async () => {
            const currentToken = useAuthStore.getState().token;
            if (!currentToken || currentToken !== scheduledToken) return;

            const currentRefreshToken = localStorage.getItem(LS_REFRESH_TOKEN_KEY);
            if (!currentRefreshToken) return;

            try {
                // ✅ Use api instance instead of raw axios to respect interceptors
                const res = await api.post<{ isSuccess: boolean; token?: string; refreshToken?: string }>(
                    "/auth/refresh",
                    { token: currentToken, refreshToken: currentRefreshToken },
                    { timeout: 5000 }
                );
                if (res.data.isSuccess && res.data.token) {
                    localStorage.setItem(LS_TOKEN_KEY, res.data.token);
                    if (res.data.refreshToken) localStorage.setItem(LS_REFRESH_TOKEN_KEY, res.data.refreshToken);
                    useAuthStore.setState({ token: res.data.token });
                    broadcastToken(res.data.token, res.data.refreshToken ?? "");
                    _scheduleTokenRefresh(res.data.token);
                }
            } catch (err) {
                logError('Pre-emptive token refresh failed', err);
                /* Refresh failed — will be handled reactively on next 401 */
            }
        }, refreshAt);
    } catch (err) {
        logError('Invalid token in _scheduleTokenRefresh', err);
    }
}

// ─── Activity-based token refresh ───────────────────────
let _lastActivityRefresh = 0;
const ACTIVITY_REFRESH_INTERVAL = 15 * 60 * 1000; // 15 دقيقة

async function _refreshTokenNow() {
    const now = Date.now();
    // منع التجديد المتكرر — مرة كل 15 دقيقة كحد أقصى
    if (now - _lastActivityRefresh < ACTIVITY_REFRESH_INTERVAL) return;

    const state = useAuthStore.getState();
    const currentToken = state.token;
    if (!currentToken || !state.isAuthenticated) return;

    // فحص: هل التوكن سينتهي خلال 15 دقيقة؟
    try {
        const decoded = jwtDecode<{ exp?: number }>(currentToken);
        const exp = decoded?.exp;
        if (typeof exp !== 'number' || isNaN(exp)) return;

        const timeLeft = exp * 1000 - now;
        // إذا بقي أكثر من 15 دقيقة، لا حاجة للتجديد
        if (timeLeft > ACTIVITY_REFRESH_INTERVAL) return;
        // إذا انتهى منذ أكثر من دقيقتين، نترك الـ 401 interceptor يتعامل
        if (timeLeft < -120_000) return;
    } catch {
        return;
    }

    _lastActivityRefresh = now;

    const currentRefreshToken = localStorage.getItem(LS_REFRESH_TOKEN_KEY);
    if (!currentRefreshToken) return;

    try {
        const res = await api.post<{ isSuccess: boolean; token?: string; refreshToken?: string }>(
            "/auth/refresh",
            { token: currentToken, refreshToken: currentRefreshToken },
            { timeout: 5000 }
        );
        if (res.data.isSuccess && res.data.token) {
            localStorage.setItem(LS_TOKEN_KEY, res.data.token);
            if (res.data.refreshToken) localStorage.setItem(LS_REFRESH_TOKEN_KEY, res.data.refreshToken);
            useAuthStore.setState({ token: res.data.token });
            broadcastToken(res.data.token, res.data.refreshToken ?? "");
            _scheduleTokenRefresh(res.data.token);
        }
    } catch (err) {
        logError('Activity-based token refresh failed', err);
    }
}

// ─── AbortController & concurrency guards ─────────────────
let _hydrateAbortController: AbortController | null = null;
let _permissionsAbortController: AbortController | null = null;

function _clearAbortControllers() {
    if (_hydrateAbortController) {
        try { _hydrateAbortController.abort(); } catch { /* ignore */ }
        _hydrateAbortController = null;
    }
    if (_permissionsAbortController) {
        try { _permissionsAbortController.abort(); } catch { /* ignore */ }
        _permissionsAbortController = null;
    }
}

// ─── Synchronous cache read for instant first render ─────
function _readCacheSync(): { token: string | null; user: AuthUser | null; permissions: string[] } {
    try {
        const token = localStorage.getItem(LS_TOKEN_KEY);
        const userRaw = localStorage.getItem(LS_USER_KEY);
        const permsRaw = localStorage.getItem(LS_PERMISSIONS_KEY);
        if (token && userRaw && permsRaw) {
            return {
                token,
                user: JSON.parse(userRaw) as AuthUser,
                permissions: JSON.parse(permsRaw) as string[],
            };
        }
    } catch { /* corrupt cache — ignore */ }
    return { token: null, user: null, permissions: [] };
}

const _initialCache = _readCacheSync();

// ─── Store ──────────────────────────────────────────────
export const useAuthStore = create<AuthState>((set, get) => ({
    token: _initialCache.token,
    user: _initialCache.user,
    permissions: _initialCache.permissions,
    permissionsLoaded: _initialCache.token !== null,
    permissionsError: false,
    isLoadingPermissions: false,
    isAuthenticated: _initialCache.token !== null,
    isHydrated: _initialCache.token !== null,
    hydrationState: _initialCache.token !== null ? 'ready' : 'idle',
    sessionExpired: false,
    hydrationError: false,

    login: async (data: LoginResponse) => {
        _clearRefreshTimer();
        _clearAbortControllers();

        localStorage.setItem(LS_TOKEN_KEY, data.token);
        if (data.refreshToken) localStorage.setItem(LS_REFRESH_TOKEN_KEY, data.refreshToken);
        localStorage.setItem(LS_USER_KEY, JSON.stringify(data.user));

        // علم لتحميل الإشعارات عند تسجيل الدخول فقط (وليس عند refresh)
        sessionStorage.setItem('fresh_login', 'true');

        set({
            token: data.token,
            user: data.user,
            permissions: [],
            permissionsLoaded: false,
            permissionsError: false,
            isLoadingPermissions: true,
            isAuthenticated: true,
            isHydrated: true,
            hydrationState: 'loadingPermissions',
            sessionExpired: false,
            hydrationError: false,
        });

        _scheduleTokenRefresh(data.token);

        try {
            const res = await api.get<{ data: string[] }>("/auth/me/permissions");
            const perms = Array.isArray(res.data.data) ? res.data.data : [];
            localStorage.setItem(LS_PERMISSIONS_KEY, JSON.stringify(perms));
            set({
                permissions: perms,
                permissionsLoaded: true,
                permissionsError: false,
                isLoadingPermissions: false,
                hydrationState: 'ready',
            });
        } catch (err) {
            logError('Failed to load permissions after login', err);
            set({
                permissions: [],
                permissionsLoaded: true,
                permissionsError: true,
                isLoadingPermissions: false,
                hydrationState: 'error',
            });
        }
    },

    logout: async () => {
        _clearRefreshTimer();
        _clearAbortControllers();

        const tokenToRevoke = localStorage.getItem(LS_TOKEN_KEY);

        localStorage.removeItem(LS_TOKEN_KEY);
        localStorage.removeItem(LS_REFRESH_TOKEN_KEY);
        localStorage.removeItem(LS_USER_KEY);
        localStorage.removeItem(LS_PERMISSIONS_KEY);

        if (tokenToRevoke) {
            try {
                await api.post(
                    "/auth/logout",
                    {},
                    { headers: { Authorization: `Bearer ${tokenToRevoke}` }, timeout: 5000 }
                );
            } catch (err) {
                logError('Logout request failed', err);
            }
        }

        try {
            useNotificationStore.getState().reset();
        } catch { /* ignore if store not ready */ }

        set({
            token: null,
            user: null,
            permissions: [],
            permissionsLoaded: false,
            permissionsError: false,
            isLoadingPermissions: false,
            isAuthenticated: false,
            isHydrated: true,
            hydrationState: 'idle',
            sessionExpired: false,
            hydrationError: false,
        });

        broadcastLogout();

        // ✅ Dispatch event instead of direct navigation to avoid NS_BINDING_ABORTED
        // Let the router handle navigation gracefully
        window.dispatchEvent(new CustomEvent("auth:logout"));
    },

    handleSessionExpiry: () => {
        // Prevent duplicate calls — already expired, skip
        if (get().sessionExpired) return;

        // تسجيل السبب للتشخيص
        if (import.meta.env.DEV) {
             
            console.error('[AuthStore] Session expired:', {
                hadToken: !!get().token,
                hadRefreshToken: !!localStorage.getItem(LS_REFRESH_TOKEN_KEY),
                timestamp: new Date().toISOString(),
            });
        }

        _clearRefreshTimer();
        _clearAbortControllers();

        localStorage.removeItem(LS_TOKEN_KEY);
        localStorage.removeItem(LS_REFRESH_TOKEN_KEY);
        localStorage.removeItem(LS_USER_KEY);
        localStorage.removeItem(LS_PERMISSIONS_KEY);

        try {
            useNotificationStore.getState().reset();
        } catch { /* ignore if store not ready */ }

        set({
            token: null,
            user: null,
            permissions: [],
            permissionsLoaded: false,
            permissionsError: false,
            isLoadingPermissions: false,
            isAuthenticated: false,
            isHydrated: true,
            hydrationState: 'idle',
            sessionExpired: true,
            hydrationError: false,
        });

        // ✅ Dispatch event for router to handle navigation
        window.dispatchEvent(new CustomEvent("auth:session-expired"));
    },

    hydrate: async () => {
        // Prevent concurrent hydration
        if (_hydrateAbortController) {
            try { _hydrateAbortController.abort(); } catch { }
        }
        _hydrateAbortController = new AbortController();
        const abortSignal = _hydrateAbortController.signal;

        const storedToken = localStorage.getItem(LS_TOKEN_KEY);

        // Try localStorage cache for instant render — NO loader if cache exists
        const cachedUserRaw = localStorage.getItem(LS_USER_KEY);
        const cachedPermsRaw = localStorage.getItem(LS_PERMISSIONS_KEY);
        let restoredFromCache = false;

        if (storedToken && cachedUserRaw && cachedPermsRaw) {
            try {
                const user = JSON.parse(cachedUserRaw) as AuthUser;
                const perms = JSON.parse(cachedPermsRaw) as string[];
                set({
                    token: storedToken,
                    user,
                    permissions: perms,
                    permissionsLoaded: true,
                    isAuthenticated: true,
                    isHydrated: true,
                    hydrationState: 'ready',
                    isLoadingPermissions: false,
                });
                restoredFromCache = true;
            } catch (err) {
                logError('Corrupt cache during hydrate', err);
            }
        }

        // Only show restoring state if NO cache (first load)
        if (!restoredFromCache) {
            set({ hydrationState: 'restoring' });
        }

        let tokenToUse: string | null = null;

        if (storedToken) {
            try {
                const decoded = jwtDecode<{ exp?: number }>(storedToken);
                const exp = decoded?.exp;

                if (typeof exp === 'number' && !isNaN(exp)) {
                    const isExpired = exp * 1000 <= Date.now() + 120_000;

                    if (isExpired) {
                        const currentRefreshToken = localStorage.getItem(LS_REFRESH_TOKEN_KEY);
                        if (currentRefreshToken) {
                            try {
                                const res = await api.post<{ isSuccess: boolean; token?: string; refreshToken?: string }>(
                                    "/auth/refresh",
                                    { token: storedToken, refreshToken: currentRefreshToken },
                                    { timeout: 3000, signal: abortSignal }
                                );
                                if (res.data.isSuccess && res.data.token) {
                                    localStorage.setItem(LS_TOKEN_KEY, res.data.token);
                                    if (res.data.refreshToken) localStorage.setItem(LS_REFRESH_TOKEN_KEY, res.data.refreshToken);
                                    tokenToUse = res.data.token;
                                    set({ token: res.data.token });
                                    broadcastToken(res.data.token, res.data.refreshToken ?? "");
                                }
                            } catch (err) {
                                logError('Token refresh during hydrate failed', err);
                            }
                        }
                    } else {
                        tokenToUse = storedToken;
                        if (!restoredFromCache) set({ token: storedToken });
                    }
                }
            } catch (err) {
                logError('Invalid stored token during hydrate', err);
            }
        }

        if (!tokenToUse && storedToken) {
            localStorage.removeItem(LS_TOKEN_KEY);
            localStorage.removeItem(LS_REFRESH_TOKEN_KEY);
            localStorage.removeItem(LS_USER_KEY);
            localStorage.removeItem(LS_PERMISSIONS_KEY);
            set({ token: null });
        }

        if (tokenToUse) {
            if (!abortSignal.aborted) {
                try {
                    const [meRes, permsRes] = await Promise.all([
                        api.get<{ data: AuthUser }>("/auth/me", {
                            timeout: 3000,
                            signal: abortSignal,
                        }),
                        api.get<{ data: string[] }>("/auth/me/permissions", {
                            timeout: 5000,
                            signal: abortSignal,
                        }),
                    ]);

                    if (abortSignal.aborted) return;

                    const user = meRes.data.data;
                    const perms = Array.isArray(permsRes.data.data) ? permsRes.data.data : [];

                    localStorage.setItem(LS_USER_KEY, JSON.stringify(user));
                    localStorage.setItem(LS_PERMISSIONS_KEY, JSON.stringify(perms));

                    set({
                        token: tokenToUse,
                        user,
                        permissions: perms,
                        permissionsLoaded: true,
                        permissionsError: false,
                        isLoadingPermissions: false,
                        isAuthenticated: true,
                        isHydrated: true,
                        hydrationState: 'ready',
                        sessionExpired: false,
                        hydrationError: false,
                    });

                    _scheduleTokenRefresh(tokenToUse);
                    _hydrateAbortController = null;
                    return;
                } catch (err: any) {
                    if (abortSignal.aborted) return;
                    logError('API failed during hydrate', err);
                    // API failed — keep cached data if we have it
                    if (restoredFromCache) {
                        set({
                            isAuthenticated: true,
                            isHydrated: true,
                            hydrationState: 'ready',
                            sessionExpired: false,
                            hydrationError: false,
                        });
                        _scheduleTokenRefresh(tokenToUse);
                        _hydrateAbortController = null;
                        return;
                    }
                }
            }
        }

        // All attempts failed
        if (abortSignal.aborted) return;

        localStorage.removeItem(LS_TOKEN_KEY);
        localStorage.removeItem(LS_REFRESH_TOKEN_KEY);
        localStorage.removeItem(LS_USER_KEY);
        localStorage.removeItem(LS_PERMISSIONS_KEY);
        set({
            token: null,
            user: null,
            isAuthenticated: false,
            isHydrated: true,
            hydrationState: 'ready',
            hydrationError: false,
            sessionExpired: false,
        });

        _hydrateAbortController = null;
    },

    refreshPermissions: async (silent = false) => {
        if (_permissionsAbortController) {
            try { _permissionsAbortController.abort(); } catch { /* ignore */ }
        }
        _permissionsAbortController = new AbortController();
        const signal = _permissionsAbortController.signal;

        if (!silent || !get().permissionsLoaded) {
            set({ permissionsError: false, hydrationState: 'loadingPermissions', isLoadingPermissions: true });
        }

        try {
            const res = await api.get<{ data: string[] }>("/auth/me/permissions", { signal });
            const perms = Array.isArray(res.data.data) ? res.data.data : [];

            set({
                permissions: perms,
                permissionsLoaded: true,
                permissionsError: false,
                hydrationState: 'ready',
                isLoadingPermissions: false,
            });
        } catch (err: any) {
            if (err.name === 'AbortError' || err?.code === 'ERR_CANCELED') {
                return;
            }

            logError('Permission refresh failed', err);

            if (!silent || !get().permissionsLoaded) {
                set({
                    permissions: [],
                    permissionsLoaded: true,
                    permissionsError: true,
                    hydrationState: 'error',
                    isLoadingPermissions: false,
                });
            } else {
                // Silent refresh failed but we have old permissions — keep them, just flag the error
                set({ permissionsError: true, isLoadingPermissions: false });
            }
        } finally {
            _permissionsAbortController = null;
        }
    },

    refreshTokenNow: async () => {
        await _refreshTokenNow();
    },
}));

// ─── Selectors ──────────────────────────────────────────
export const useHasRole = (...roles: string[]) => {
    const user = useAuthStore((s) => s.user);
    if (!user) return false;
    return roles.some((r) => r.toLowerCase() === user.role?.toLowerCase());
};

export const useHasPermission = (...codes: string[]) => {
    const permissions = useAuthStore((s) => s.permissions);
    const permissionsLoaded = useAuthStore((s) => s.permissionsLoaded);
    const isHydrated = useAuthStore((s) => s.isHydrated);

    // During hydration, deny access — PermissionRoute handles its own loading gate
    if (!isHydrated || !permissionsLoaded) return false;

    return codes.some((code) => permissions.includes(code));
};

export const useHasAllPermissions = (...codes: string[]) => {
    const permissions = useAuthStore((s) => s.permissions);
    const permissionsLoaded = useAuthStore((s) => s.permissionsLoaded);
    const isHydrated = useAuthStore((s) => s.isHydrated);

    // During hydration, deny access
    if (!isHydrated || !permissionsLoaded) return false;

    return codes.every((code) => permissions.includes(code));
};
